    "src/live/capture.js": ["chrome.tabs.get", "chrome.scripting.executeScript", "chrome.tabs.onUpdated.addListener", "chrome.tabs.onUpdated.removeListener", "chrome.tabs.onRemoved.addListener", "chrome.tabs.onRemoved.removeListener", "chrome.tabs.sendMessage", "chrome.runtime.onMessage.addListener", "chrome.runtime.onMessage.removeListener", "chrome.runtime.id"],
    "src/live/dom_reader.js": ["chrome.runtime.sendMessage", "chrome.runtime.onMessage.addListener", "chrome.runtime.id", "chrome.runtime.getURL"],
    "src/live/panel.js": ["chrome.runtime.connect", "chrome.permissions.request"]
