BASE = "https://v3.football.api-sports.io"
MAX_BODY = 8 * 1024 * 1024
PROVIDER_DIAGNOSTICS = frozenset(
    {
        "NONE",
        "CONTENT_ENCODING",
        "CONTENT_LENGTH_MISMATCH",
        "INVALID_JSON",
        "ENVELOPE_SHAPE",
        "ERRORS_SHAPE",
        "PAGING_MISSING",
        "PAGING_INVALID",
        "STATUS_RESPONSE_SHAPE",
        "STATUS_RESULT_COUNT",
        "RESULT_ROWS",
        "FIXTURE_IDS",
        "STATUS_FIELDS",
    }
)


class ProviderError(ValueError):
    def __init__(self, code: str, retry_after: float | None = None, *, diagnostic: str = "NONE"):
        if diagnostic not in PROVIDER_DIAGNOSTICS:
            raise ValueError("E_PROVIDER_DIAGNOSTIC")
        super().__init__(code)
        self.code, self.retry_after = code, retry_after
        self.diagnostic = diagnostic


class NoRedirect(HTTPRedirectHandler):
    def redirect_request(
        self, req: Any, fp: Any, code: int, msg: str, headers: Any, newurl: str
    ) -> None:
        return None


def build_fixed_opener() -> OpenerDirector:
    context = ssl.create_default_context()
    context.set_alpn_protocols(["http/1.1"])
    return build_opener(ProxyHandler({}), NoRedirect(), HTTPSHandler(context=context))


class _IsolatedReply(io.BytesIO):
    def __init__(self, value: dict[str, Any]):
        super().__init__(base64.b64decode(value["body"], validate=True))
        self.status, self.headers, self.url = value["status"], value["headers"], value["url"]

    def geturl(self) -> str:
        return str(self.url)


def _isolated_open(request: Request, timeout: float) -> _IsolatedReply:
    """Bound DNS, TLS, headers and body together in one owned backend child."""
    if not 0 < timeout <= 10:
        raise TimeoutError()
    deadline = time.monotonic() + timeout
    module_root = str(Path(__file__).resolve().parents[2])
    program = (
        "import sys;sys.path.insert(0,"
        + repr(module_root)
        + ");from moj_discovery.providers.api_football import _request_worker;_request_worker()"
    )
    child = subprocess.Popen(  # noqa: S603 -- fixed backend entrypoint; key only in private stdin.
        [sys.executable, "-I", "-c", program],
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        env={},
        close_fds=True,
    )
    try:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise TimeoutError()
        payload = json.dumps(
            {
                "url": request.full_url,
                "key": request.get_header("X-apisports-key"),
                "timeout": remaining,
            }
        ).encode()
        raw, _ = child.communicate(payload, timeout=remaining)
        if child.returncode != 0 or len(raw) > (MAX_BODY + 1) * 2:
            raise TimeoutError()
        value = parse_strict_json(raw)
        if type(value) is not dict or set(value) != {"status", "headers", "url", "body"}:
            raise ProviderError("TRANSPORT_ERROR")
        return _IsolatedReply(value)
    except subprocess.TimeoutExpired:
        raise TimeoutError() from None
    finally:
        if child.poll() is None:
            child.kill()  # Exact owned Popen child, never an image-name/PID search.
        child.communicate()


def _request_worker() -> None:
    """Private subprocess entrypoint, not a public CLI or a generic HTTP proxy."""
    import signal

    value = parse_strict_json(sys.stdin.buffer.read(4097))
    if type(value) is not dict or set(value) != {"url", "key", "timeout"}:
        raise ValueError("E_PROVIDER_WORKER_INPUT")
    url, timeout = value["url"], value["timeout"]
    paths = (
        r"(?:/status|/leagues\?id=[1-9][0-9]*&season=[0-9]{4}"
        r"|/fixtures\?league=[1-9][0-9]*&season=[0-9]{4}&date=[0-9]{4}-[0-9]{2}-[0-9]{2}"
        r"|/fixtures\?ids=[1-9][0-9]*(?:-[1-9][0-9]*){0,19})"
    )
    if (
        type(url) is not str
        or re.fullmatch(re.escape(BASE) + paths, url) is None
        or type(timeout) not in {int, float}
        or not 0 < timeout <= 10
    ):
        raise ValueError("E_PROVIDER_WORKER_SCOPE")
    # Default SIGALRM termination also bounds a blocking libc DNS lookup on WSL/Linux.
    signal.signal(signal.SIGALRM, signal.SIG_DFL)
    signal.setitimer(signal.ITIMER_REAL, timeout)
    key = SecretValue(value["key"])
    request = Request(  # noqa: S310 -- fixed HTTPS authority and finite path grammar.
        url,
        method="GET",
        headers={
            "x-apisports-key": key.reveal_for_header(),
            "Accept": "application/json",
            "Accept-Encoding": "identity",
        },
    )  # noqa: S310 -- fixed HTTPS authority and finite path grammar.
    try:
        response = build_fixed_opener().open(request, timeout=timeout)
    except HTTPError as error:
        response = error
    with response:
        # The parent projects/validates the response. No raw provider bytes reach artifacts.
        body = response.read(MAX_BODY + 1)
        headers = {
            name: response.headers[name]
            for name in (*HEADER_NAMES, "Retry-After", "Content-Length", "Content-Encoding")
            if name in response.headers
        }
        record = {
            "status": response.code,
            "headers": headers,
            "url": response.geturl(),
            "body": base64.b64encode(body).decode(),
        }
    sys.stdout.write(json.dumps(record))
    sys.stdout.flush()


def retry_after_seconds(value: str | None, now: datetime) -> float:
    try:
        if value is None or len(value) > 128:
            return 60
        if re.fullmatch(r"[0-9]{1,10}", value):
            return float(value)
        stamp = parsedate_to_datetime(value)
        if stamp.tzinfo is None:
            return 60
        return max(0, (stamp - now).total_seconds())
    except (ValueError, TypeError, OverflowError):
        return 60


@dataclass(frozen=True)
class SafeStatus:
    plan: str
    active: bool
    expires_on: str | None
    daily_limit: int | None
    daily_remaining: int | None


@dataclass(frozen=True)
class ProviderResponse:
    request_id: str
    source_kind: str
    purpose: str
    rows: tuple[dict[str, Any], ...] = field(repr=False)
    missing_ids: tuple[int, ...] = ()
    attempts: int = 1


def _positive_id(value: object) -> int:
    if type(value) is not int or not 0 < value <= 2**53 - 1:
        raise ProviderError("PARAMETER_ERROR")
    return value


def _select(value: object, keys: Sequence[str]) -> dict[str, Any]:
    if type(value) is not dict:
        return {}
    return {key: copy.deepcopy(value[key]) for key in keys if key in value}


def _fixture_fields(raw: dict[str, Any]) -> dict[str, Any]:
    result: dict[str, Any] = {
        "fixture": _select(raw.get("fixture"), ("id", "date", "timestamp")),
        "league": _select(raw.get("league"), ("id", "season")),
        "teams": {},
        "goals": _select(raw.get("goals"), ("home", "away")),
        "score": {},
    }
    result["fixture"]["status"] = _select(
        raw.get("fixture", {}).get("status"), ("short", "elapsed", "extra")
    )
    for side in ("home", "away"):
        result["teams"][side] = _select(
            _select(raw.get("teams"), (side,)).get(side), ("id", "name")
        )
    for period in ("halftime", "fulltime"):
        result["score"][period] = _select(
            _select(raw.get("score"), (period,)).get(period), ("home", "away")
        )
    for section in ("events", "lineups", "statistics", "players"):
        value = raw.get(section)
        if section != "events":
            result[section] = (
                ([] if not value else [{}])
                if isinstance(value, list)
                else (None if value is None else {"invalid": True})
            )
        elif isinstance(value, list):
            if len(value) > 2000 or any(type(row) is not dict for row in value):
                result[section] = {"invalid": True}
                continue
            events = []
            for row in value:
                event = _select(row, ("type", "detail"))
                event["time"] = _select(row.get("time"), ("elapsed", "extra"))
                for actor in ("team", "player", "assist"):
                    event[actor] = _select(row.get(actor), ("id",))
                events.append(event)
            result[section] = events
        else:
            result[section] = None if value is None else {"invalid": True}
    return result


class ApiFootballClient:
    def __init__(
        self,
        secret: SecretValue,
        quota: QuotaLedger,
        scope: ProviderScope,
        *,
        opener: Any = None,
        now_mono: Callable[[], float] = time.monotonic,
        now_utc: Callable[[], datetime] = lambda: datetime.now(UTC),
        sleep: Callable[[float], None] = time.sleep,
        before_attempt: Callable[[str, str], None] | None = None,
    ):
        try:
            verify_probe_protocol(scope)
            verify_call_authorization(scope, now_mono=now_mono())
            if (
                quota.scope_id != scope.scope_id
                or type(secret) is not SecretValue
                or (opener is None and scope.source_kind != "OBSERVED_REAL")
                or (opener is not None and scope.source_kind != "MOCK")
            ):
                raise ValueError()
        except Exception:
            raise ProviderError("REAL_AUTHORITY_REQUIRED") from None
        self.scope, self.quota = scope, quota
        self._secret: SecretValue | None = secret
        self._real = opener is None
        self._opener = build_fixed_opener() if opener is None else opener
        self._mono, self._utc, self._sleep = now_mono, now_utc, sleep
        self._before_attempt = before_attempt
        self._lock = threading.Lock()
        self._next_start = now_mono()
        self._stopped: str | None = None
        self._blocked_purposes: dict[str, str] = {}
        self._coverage_cache: dict[tuple[int, int], tuple[float, dict[str, Any]]] = {}
        self._lookup_cache: dict[str, tuple[float, ProviderResponse]] = {}
        self.request_log: list[dict[str, Any]] = []
        self.http_attempts = 0

    def __enter__(self) -> "ApiFootballClient":
        return self

    def __exit__(
        self,
        kind: type[BaseException] | None,
        value: BaseException | None,
        traceback: TracebackType | None,
    ) -> None:
        self.close()

    def close(self) -> None:
        self._secret = None
        self._stopped = "STOPPED"

    def _admit(self, purpose: str) -> None:
        if self._stopped:
            raise ProviderError(self._stopped)
        if purpose in self._blocked_purposes:
            raise ProviderError(self._blocked_purposes[purpose])
        self.check_credential()
        try:
            verify_call_authorization(self.scope, purpose=purpose, now_mono=self._mono())
        except Exception:
            raise ProviderError("RUN_DEADLINE_OR_AUTHORITY") from None
        if self.quota.count_attempts() >= self.scope.max_attempts:
            raise ProviderError("SESSION_BUDGET")

    def check_credential(self) -> None:
        if self._secret is None:
            raise ProviderError("STOPPED")
        try:
            self._secret.check_usable()
        except ValueError:
            self._stopped = "AUTH_FAILED"
            raise ProviderError("AUTH_FAILED") from None

    def _read(self, response: Any, request: Request, timeout: float) -> bytes:
        if response.geturl() != request.full_url:
            raise ProviderError("REDIRECT")
        encoding = response.headers.get("Content-Encoding", "identity")
        if encoding.lower() not in {"identity", ""}:
            raise ProviderError("SCHEMA_ERROR", diagnostic="CONTENT_ENCODING")
        length = response.headers.get("Content-Length")
        if length is not None and (
            not re.fullmatch(r"[0-9]{1,10}", length) or int(length) > MAX_BODY
        ):
            raise ProviderError("RESPONSE_TOO_LARGE")
        deadline = min(self.scope.deadline_mono, self._mono() + timeout)
        chunks, size = [], 0
        while True:
            if self._real and not isinstance(response, _IsolatedReply) and response.fp is None:
                break
            remaining = deadline - self._mono()
            if remaining <= 0:
                raise ProviderError("TIMEOUT")
            if self._real and not isinstance(response, _IsolatedReply):
                # Pinned Python 3.12 HTTPResponse socket; fail closed if the shape changes.
                response.fp.raw._sock.settimeout(min(10, remaining))
            chunk = response.read1(min(65536, MAX_BODY + 1 - size))
            size += len(chunk)
            if size > MAX_BODY:
                raise ProviderError("RESPONSE_TOO_LARGE")
            if not chunk:
                break
            chunks.append(chunk)
        if length is not None and size != int(length):
            raise ProviderError("SCHEMA_ERROR", diagnostic="CONTENT_LENGTH_MISMATCH")
        return b"".join(chunks)

    def _decode(self, raw: bytes, purpose: str, ids: tuple[int, ...]) -> dict[str, Any]:
        # Only fixed validator labels escape; never retain response values or exception text.
        diagnostic = "INVALID_JSON"
        try:
            body = parse_strict_json(raw)
            diagnostic = "ENVELOPE_SHAPE"
            if type(body) is not dict:
                raise ProviderError("SCHEMA_ERROR")
            diagnostic = "ERRORS_SHAPE"
            errors = body.get("errors")
            if errors not in ({}, []):
                if isinstance(errors, dict) and set(errors) & {"token", "access", "authentication"}:
                    raise ProviderError("AUTH_FAILED")
                raise ProviderError(
                    "PROVIDER_ERROR" if isinstance(errors, (dict, list)) else "SCHEMA_ERROR"
                )
            assert self._secret is not None
            key = self._secret.reveal_for_header()
            # Reject credential echoes before any projection or retention. No secret hash is made.
            encoded_key = quote(key, safe="")

            def has_echo(value: object) -> bool:
                if isinstance(value, str):
                    return key in value or encoded_key in value
                if isinstance(value, dict):
                    return any(has_echo(k) or has_echo(v) for k, v in value.items())
                if isinstance(value, list):
                    return any(has_echo(v) for v in value)
                return False

            if has_echo(body):
                raise ProviderError("SECRET_ECHO")
            paging = body.get("paging")
            diagnostic = "PAGING_MISSING" if "paging" not in body else "PAGING_INVALID"
            if (
                type(paging) is not dict
                or type(paging.get("current")) is not int
                or type(paging.get("total")) is not int
                or paging["current"] != 1
                or paging["total"] != 1
            ):
                raise ProviderError("SCHEMA_ERROR")
            rows = body.get("response")
            if purpose == "STATUS":
                diagnostic = "STATUS_RESPONSE_SHAPE"
                if type(rows) is not dict:
                    raise ProviderError("SCHEMA_ERROR")
                diagnostic = "STATUS_RESULT_COUNT"
                # STATUS is an object, not a one-row fixture list. Validate its
                # payload in get_status; this metadata is not an authentication gate.
                if type(body.get("results")) is not int or not 0 <= body["results"] <= 2**31 - 1:
                    raise ProviderError("SCHEMA_ERROR")
            elif (
                type(rows) is not list
                or type(body.get("results")) is not int
                or body["results"] != len(rows)
                or any(type(row) is not dict for row in rows)
            ):
                raise ProviderError("SCHEMA_ERROR", diagnostic="RESULT_ROWS")
            if purpose in {"BUNDLE", "LOOKUP"}:
                diagnostic = "FIXTURE_IDS"
                returned = [_positive_id(row.get("fixture", {}).get("id")) for row in rows]
                if len(returned) != len(set(returned)) or (
                    purpose == "BUNDLE" and not set(returned) <= set(ids)
                ):
                    raise ProviderError("SCHEMA_ERROR")
            return body
        except ProviderError as error:
            if error.code == "SCHEMA_ERROR" and error.diagnostic == "NONE":
                error.diagnostic = diagnostic
            raise
        except Exception:
            raise ProviderError("SCHEMA_ERROR", diagnostic=diagnostic) from None

    def _request(
        self, purpose: str, path: str, ids: tuple[int, ...] = ()
    ) -> tuple[dict[str, Any], str, int]:
        allowed = {
            "STATUS": "/status",
            "COVERAGE": f"/leagues?id={self.scope.league_id}&season={self.scope.season}",
            "BUNDLE": "/fixtures?ids=" + "-".join(map(str, ids)),
            "LOOKUP": (
                f"/fixtures?league={self.scope.league_id}&season={self.scope.season}"
                f"&date={self.scope.lookup_date}"
            ),
        }
        if purpose == "EVENTS_FALLBACK":
            if path not in {f"/fixtures/events?fixture={i}" for i in self.scope.events_fixture_ids}:
                raise ProviderError("FALLBACK_DISABLED")
        elif purpose not in allowed or path != allowed[purpose]:
            raise ProviderError("PARAMETER_ERROR")
        if purpose == "BUNDLE" and (not ids or not set(ids) <= set(self.scope.fixture_ids)):
            raise ProviderError("PARAMETER_ERROR")
        if not self._lock.acquire(blocking=False):
            raise ProviderError("IN_FLIGHT")
        try:
            for index in range(3):
                self._admit(purpose)
                delay = max(0, self._next_start - self._mono())
                if delay >= self.scope.deadline_mono - self._mono():
                    raise ProviderError("RUN_DEADLINE_OR_AUTHORITY")
                if delay:
                    self._sleep(delay)
                self._admit(purpose)
                reservation = self.quota.reserve_attempt(
                    self.scope.scope_id, purpose, self._utc(), self._mono()
                )
                if isinstance(reservation, Denied):
                    raise ProviderError(reservation.code)
                headers: dict[str, str] = {}
                response = None
                body = None
                failure: ProviderError | None = None
                started = self._mono()
                self._next_start = started + 10
                try:
                    if self._before_attempt is not None:
                        self._before_attempt(purpose, reservation.attempt_id)
                    assert self._secret is not None
                    request = Request(  # noqa: S310 -- exact purpose/path allowlist above, fixed HTTPS host
                        BASE + path,
                        method="GET",
                        headers={
                            "x-apisports-key": self._secret.reveal_for_header(),
                            "Accept": "application/json",
                            "Accept-Encoding": "identity",
                        },
                    )
                    timeout = min(10, self.scope.deadline_mono - self._mono())
                    if timeout <= 0:
                        raise ProviderError("RUN_DEADLINE_OR_AUTHORITY")
                    try:
                        self.http_attempts += 1
                        response = (
                            _isolated_open(request, timeout)
                            if self._real
                            else self._opener.open(request, timeout=timeout)
                        )
                    except HTTPError as error:
                        response = error
                    headers = {
                        str(k).lower(): str(v)
                        for k, v in response.headers.items()
                        if str(k).lower() in (*HEADER_NAMES, "retry-after")
                    }
                    status = response.code if isinstance(response, HTTPError) else response.status
                    if status in {401, 403}:
                        raise ProviderError("AUTH_FAILED")
                    if 300 <= status < 400:
                        raise ProviderError("REDIRECT")
                    if status == 429:
                        raise ProviderError(
                            "HTTP_429", retry_after_seconds(headers.get("retry-after"), self._utc())
                        )
                    if status == 499 or 500 <= status <= 599:
                        raise ProviderError("HTTP_5XX", 2 if index == 0 else 4)
                    if status != 200:
                        raise ProviderError("PARAMETER_ERROR")
                    body = self._decode(self._read(response, request, timeout), purpose, ids)
                except ProviderError as error:
                    failure = error
                except TimeoutError:
                    failure = ProviderError("TIMEOUT", 2 if index == 0 else 4)
                except URLError:
                    failure = ProviderError("TRANSPORT_ERROR")
                except KeyboardInterrupt:
                    failure = ProviderError("USER_STOP")
                except Exception:
                    failure = ProviderError("TRANSPORT_ERROR")
                finally:
                    if response is not None:
                        try:
                            response.close()
                        except Exception:
                            failure = failure or ProviderError("TRANSPORT_ERROR")
                    outcome = "SUCCESS" if failure is None else failure.code
                    ledger_outcome = (
                        outcome
                        if outcome
                        in {
                            "SUCCESS",
                            "AUTH_FAILED",
                            "HTTP_429",
                            "HTTP_5XX",
                            "TIMEOUT",
                            "REDIRECT",
                            "TRANSPORT_ERROR",
                            "SCHEMA_ERROR",
                            "PROVIDER_ERROR",
                        }
                        else ("UNKNOWN" if outcome == "USER_STOP" else "SCHEMA_ERROR")
                    )
                    self.quota.finalize_attempt(
                        reservation.attempt_id,
                        ledger_outcome,
                        {k: v for k, v in headers.items() if k in HEADER_NAMES},
                    )
                    self.request_log.append(
                        {
                            "attempt_id": reservation.attempt_id,
                            "purpose": purpose,
                            "outcome": outcome,
                            "diagnostic": "NONE" if failure is None else failure.diagnostic,
                            "source_kind": self.scope.source_kind,
                        }
                    )
                if failure is None:
                    assert body is not None
                    return body, reservation.attempt_id, index + 1
                if failure.code in {"AUTH_FAILED", "SECRET_ECHO", "REDIRECT"}:
                    self._stopped = failure.code
                if failure.code == "USER_STOP":
                    raise KeyboardInterrupt from None
                if failure.code == "HTTP_429":
                    self._next_start = max(
                        self._next_start, self._mono() + (failure.retry_after or 60)
                    )
                if failure.code not in {"HTTP_429", "HTTP_5XX", "TIMEOUT"} or index == 2:
                    if failure.code in {
                        "SCHEMA_ERROR",
                        "PARAMETER_ERROR",
                        "PROVIDER_ERROR",
                        "RESPONSE_TOO_LARGE",
                    }:
                        self._blocked_purposes[purpose] = failure.code
                    raise failure from None
                retry_delay = failure.retry_after
                if retry_delay is None:
                    retry_delay = 2 if index == 0 else 4
                self._next_start = max(self._next_start, self._mono() + retry_delay)
            raise ProviderError("PROVIDER_UNAVAILABLE")
        finally:
            self._lock.release()

    def get_status(self) -> SafeStatus:
        body, _, _ = self._request("STATUS", "/status")
        try:
            response = body["response"]
            subscription, requests = response.get("subscription", {}), response.get("requests", {})
            if type(subscription) is not dict or type(requests) is not dict:
                raise ValueError()
            plan, active = subscription.get("plan"), subscription.get("active")
            if type(plan) is not str or not plan.strip() or type(active) is not bool:
                raise ValueError()
            plan = plan.upper()
            if plan not in {"FREE", "PRO", "ULTRA", "MEGA"}:
                plan = "UNKNOWN"
            expires = None
            raw_end = subscription.get("end")
            if type(raw_end) is str:
                try:
                    if re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", raw_end):
                        expires = date.fromisoformat(raw_end).isoformat()
                    else:
                        stamp = datetime.fromisoformat(raw_end)
                        if stamp.tzinfo is not None:
                            expires = stamp.astimezone(UTC).date().isoformat()
                except (ValueError, OverflowError):
                    pass  # Unknown expiry stays unknown; it grants no live authority.
            limit, used = requests.get("limit_day"), requests.get("current")
            if (
                type(limit) is not int
                or type(used) is not int
                or not 0 <= used <= limit <= 2**31 - 1
            ):
                raise ValueError()
            remaining = limit - used
            return SafeStatus(plan, active, expires, limit, remaining)
        except Exception:
            raise ProviderError("SCHEMA_ERROR", diagnostic="STATUS_FIELDS") from None

    def get_fixture_bundle(self, ids: Sequence[int]) -> ProviderResponse:
        ordered = tuple(sorted({_positive_id(i) for i in ids}))
        if not 1 <= len(ordered) <= 20 or not set(ordered) <= set(self.scope.fixture_ids):
            raise ProviderError("PARAMETER_ERROR")
        body, request_id, attempts = self._request(
            "BUNDLE", "/fixtures?ids=" + "-".join(map(str, ordered)), ordered
        )
        try:
            rows = tuple(_fixture_fields(row) for row in body["response"])
            missing = tuple(sorted(set(ordered) - {row["fixture"]["id"] for row in rows}))
            return ProviderResponse(
                request_id, self.scope.source_kind, "BUNDLE", rows, missing, attempts
            )
        except Exception:
            raise ProviderError("SCHEMA_ERROR") from None

    def get_coverage(self, league_id: int, season: int) -> dict[str, Any]:
        self._admit("COVERAGE")
        if (
            type(league_id) is not int
            or league_id != self.scope.league_id
            or type(season) is not int
            or season != self.scope.season
        ):
            raise ProviderError("PARAMETER_ERROR")
        key = (league_id, season)
        cached = self._coverage_cache.get(key)
        if cached and self._mono() < cached[0]:
            return copy.deepcopy(cached[1])
        body, _, _ = self._request("COVERAGE", f"/leagues?id={league_id}&season={season}")
        try:
            matching = [row for row in body["response"] if row["league"]["id"] == league_id]
            if len(matching) != 1:
                raise ValueError()
            seasons = [s for s in matching[0]["seasons"] if s["year"] == season]
            if len(seasons) != 1:
                raise ValueError()
            coverage = seasons[0]["coverage"]["fixtures"]
            result = {
                "league_id": league_id,
                "season": season,
                "coverage": {
                    name: coverage.get(name) if type(coverage.get(name)) is bool else None
                    for name in ("events", "lineups", "statistics_fixtures", "statistics_players")
                },
            }
            self._coverage_cache[key] = (self._mono() + 86400, result)
            return copy.deepcopy(result)
        except Exception:
            raise ProviderError("SCHEMA_ERROR") from None

    def get_events(self, fixture_id: int) -> ProviderResponse:
        _positive_id(fixture_id)
        if fixture_id not in self.scope.events_fixture_ids:
            raise ProviderError("FALLBACK_DISABLED")
        body, request_id, attempts = self._request(
            "EVENTS_FALLBACK", f"/fixtures/events?fixture={fixture_id}"
        )
        projected = _fixture_fields({"fixture": {}, "events": body["response"]})["events"]
        return ProviderResponse(
            request_id, self.scope.source_kind, "EVENTS_FALLBACK", tuple(projected), (), attempts
        )

    def get_fixtures_for_date(self, league_id: int, season: int, date: str) -> ProviderResponse:
        self._admit("LOOKUP")
        if (
            type(league_id) is not int
            or league_id != self.scope.league_id
            or type(season) is not int
            or season != self.scope.season
            or type(date) is not str
            or date != self.scope.lookup_date
            or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date)
        ):
            raise ProviderError("LOOKUP_NOT_AUTHORIZED")
        cached = self._lookup_cache.get(date)
        if cached and self._mono() < cached[0]:
            return copy.deepcopy(cached[1])
        body, request_id, attempts = self._request(
            "LOOKUP", f"/fixtures?league={league_id}&season={season}&date={date}"
        )
        rows = tuple(_fixture_fields(row) for row in body["response"])
        result = ProviderResponse(request_id, self.scope.source_kind, "LOOKUP", rows, (), attempts)
        self._lookup_cache[date] = (self._mono() + 60, result)
        return result"""One bounded backend scheduler for the selected fixture union."""

import copy
import math
import threading
import time
from collections.abc import Callable, Sequence
from dataclasses import dataclass, field
from datetime import UTC, datetime
from typing import Any
from uuid import uuid4

from ..provider_protocol import verify_probe_protocol
from .api_football import ApiFootballClient, ProviderError, ProviderResponse
from .football_normalizer import BundleProjection, ObservationStamp, normalize_bundle
from .poll_budget import PollSegment, estimate_requests

TRANSIENT = frozenset(
    {"HTTP_429", "HTTP_5XX", "TIMEOUT", "TRANSPORT_ERROR", "PROVIDER_UNAVAILABLE"}
)
STOP_REASONS = frozenset({"USER_STOP", "RUN_DEADLINE", "SHUTDOWN", "SCOPE_REVOKED"})


@dataclass(frozen=True)
class PollOutcome:
    status: str
    reason: str
    next_due_mono: float | None
    projection: BundleProjection | None = None
    stale_ids: tuple[int, ...] = ()
    stopped_ids: dict[int, str] = field(default_factory=dict)
    wake_gap: bool = False
    fallback: ProviderResponse | None = None


class ProviderBundlePoller:
    def __init__(
        self,
        client: ApiFootballClient,
        *,
        now_mono: Callable[[], float] = time.monotonic,
        now_utc: Callable[[], datetime] = lambda: datetime.now(UTC),
    ):
        verify_probe_protocol(client.scope)
        self.client = client
        self._mono, self._utc = now_mono, now_utc
        now = now_mono()
        limit = 300 if client.scope.stage == "PROVIDER_PROBE" else 7200
        if not now < client.scope.deadline_mono <= now + limit:
            raise ValueError("E_POLLER_DEADLINE")
        duration = min(limit, math.ceil(client.scope.deadline_mono - now))
        self._floor = 30 if client.scope.stage == "PROVIDER_PROBE" else 15
        fallback = len(client.scope.events_fixture_ids) * math.ceil(duration / 60)
        if (
            fallback
            and estimate_requests(
                [PollSegment(0, duration, self._floor)], fallback_calls=fallback
            ).with_reserve
            > client.scope.max_attempts
        ):
            raise ValueError("E_FALLBACK_BUDGET")
        self.clock_domain_id = str(uuid4())
        self._ids: tuple[int, ...] = ()
        self._revision = 0
        self._states: dict[int, dict[str, Any]] = {}
        self._due: dict[int, float] = {}
        self._terminal: dict[int, tuple[float, int]] = {}
        self._unknown: dict[int, float] = {}
        self._stopped: dict[int, str] = {}
        self._stale: set[int] = set()
        self._fallback_due = dict.fromkeys(client.scope.events_fixture_ids, now_mono() + 10)
        self._fallback_count = 0
        self._not_before = now_mono()
        self._last_tick = now_mono()
        self._failures = 0
        self._pause: str | None = None
        self._stop_reason: str | None = None
        self._state_lock = threading.RLock()
        self._request_lock = threading.Lock()

    @property
    def last_states(self) -> dict[int, dict[str, Any]]:
        with self._state_lock:
            return copy.deepcopy(self._states)

    def set_watchlist(self, ids: Sequence[int], scope_revision: int) -> None:
        with self._state_lock:
            if (
                len(ids) > 20
                or any(type(i) is not int or i <= 0 for i in ids)
                or not set(ids) <= set(self.client.scope.fixture_ids)
                or type(scope_revision) is not int
                or not self._revision <= scope_revision <= 2**63 - 1
            ):
                raise ValueError("E_WATCHLIST_SCOPE")
            selected = tuple(sorted(set(ids)))
            if scope_revision == self._revision:
                if selected != self._ids:
                    raise ValueError("E_WATCHLIST_REVISION")
                return
            now = self._mono()
            for fixture_id in selected:
                if fixture_id not in self._ids:
                    self._due[fixture_id] = now
            self._ids, self._revision = selected, scope_revision

    def request_refresh(self) -> None:
        # A refresh subscribes to the next shared due request; it cannot reset deadlines.
        return None

    def stop(self, reason: str) -> None:
        if reason not in STOP_REASONS:
            raise ValueError("E_STOP_REASON")
        with self._state_lock:
            self._stop_reason = reason

    def _active(self) -> tuple[int, ...]:
        return tuple(i for i in self._ids if i not in self._stopped)

    def _next(self) -> float | None:
        active = self._active()
        if self._pause or self._stop_reason or not active:
            return None
        deadlines = [self._due[i] for i in active]
        deadlines += [due for i, due in self._fallback_due.items() if i in active]
        return max(self._not_before, min(deadlines))

    def _outcome(
        self,
        status: str,
        reason: str = "NONE",
        *,
        projection: BundleProjection | None = None,
        wake_gap: bool = False,
        fallback: ProviderResponse | None = None,
    ) -> PollOutcome:
        return PollOutcome(
            status,
            reason,
            self._next(),
            projection,
            tuple(sorted(self._stale.intersection(self._ids))),
            dict(self._stopped),
            wake_gap,
            fallback,
        )

    def _schedule(self, fixture_id: int, state: dict[str, Any], now: float) -> None:
        period = state["period"]
        if period != "UNKNOWN":
            self._unknown.pop(fixture_id, None)
        if period != "FINISHED":
            self._terminal.pop(fixture_id, None)
        if period == "OUT_OF_SCOPE":
            self._stopped[fixture_id] = "OUT_OF_SCOPE_NORMAL_TIME"
        elif period == "FINISHED":
            first, count = self._terminal.get(fixture_id, (now, 0))
            if fixture_id in self._terminal and count == 0 and now >= first + 120:
                self._stopped[fixture_id] = "TERMINAL_CONFIRMATION_MISSED"
                return
            if fixture_id in self._terminal and now >= first + (30 if count == 0 else 120):
                count += 1
            self._terminal[fixture_id] = first, count
            if count == 2:
                self._stopped[fixture_id] = "TERMINAL_CONFIRMED"
            else:
                self._due[fixture_id] = max(now + 10, first + (30 if count == 0 else 120))
        else:
            interval = 60
            if period in {"H1", "H2"}:
                interval = self._floor
            elif period == "PREGAME":
                kickoff = datetime.fromisoformat(state["kickoff_utc"])
                interval = 60 if (kickoff - self._utc()).total_seconds() >= 600 else 30
            elif period == "UNKNOWN":
                self._unknown.setdefault(fixture_id, now)
            self._due[fixture_id] = now + interval

    def tick(self, now_mono: float) -> PollOutcome:
        if not self._request_lock.acquire(blocking=False):
            with self._state_lock:
                return self._outcome("WAIT", "IN_FLIGHT")
        try:
            return self._tick(now_mono)
        finally:
            self._request_lock.release()

    def _tick(self, now: float) -> PollOutcome:
        with self._state_lock:
            if not math.isfinite(now) or now < self._last_tick or abs(now - self._mono()) > 1:
                self._pause = "CLOCK_ERROR"
            wake = now - self._last_tick > 90
            self._last_tick = now
            if now >= self.client.scope.deadline_mono:
                self._stop_reason = "RUN_DEADLINE"
            if self._stop_reason:
                return self._outcome("STOPPED", self._stop_reason)
            if self._pause:
                return self._outcome("PAUSED", self._pause)
            for i, first in self._unknown.items():
                if now - first >= 300:
                    self._stopped[i] = "UNKNOWN_PERIOD_TIMEOUT"
            active = self._active()
            if not active:
                return self._outcome("STOPPED", "NO_ACTIVE_FIXTURES")
            if wake:
                self._stale.update(active)
            due = self._next()
            if due is None or now < due:
                return self._outcome("WAIT", wake_gap=wake)
            fallback_id = None
            if now < min(self._due[i] for i in active):
                fallback_id = next(
                    (i for i in active if self._fallback_due.get(i, math.inf) <= now), None
                )
            previous = copy.deepcopy(self._states)
        try:
            if fallback_id is not None:
                if self.client.scope.stage == "PROVIDER_PROBE" and self._fallback_count >= 2:
                    raise ProviderError("FALLBACK_PROBE_LIMIT")
                response = self.client.get_events(fallback_id)
                projection = None
            else:
                response = self.client.get_fixture_bundle(active)
                projection = normalize_bundle(
                    response,
                    active,
                    ObservationStamp(
                        self._utc(),
                        int(self._mono() * 1_000_000),
                        self.clock_domain_id,
                        str(uuid4()),
                        self.client.scope.league_id,
                        self.client.scope.season,
                        previous,
                    ),
                )
        except Exception as error:
            with self._state_lock:
                self._stale.update(active)
                delay = 60.0
                if type(error) is ProviderError and error.code == "HTTP_429":
                    delay = max(delay, error.retry_after or 60)
                self._not_before = self._mono() + delay
                code = (
                    error.code if type(error) is ProviderError else "INVALID_PROVIDER_OBSERVATION"
                )
                self._failures += 1
                if code not in TRANSIENT or self._failures >= 3:
                    # Only finite client codes from this boundary reach the visible projection.
                    self._pause = "PROVIDER_RESTART_REQUIRED" if code in TRANSIENT else code
                return self._outcome(
                    "PAUSED" if self._pause else "STALE",
                    self._pause or "CIRCUIT_OPEN",
                    wake_gap=wake,
                )
        with self._state_lock:
            completed = self._mono()
            self._not_before = completed + 10
            self._failures = 0
            if fallback_id is not None:
                self._fallback_count += 1
                self._fallback_due[fallback_id] = completed + 60
                return self._outcome(
                    "UPDATED", "FALLBACK_OBSERVATION", fallback=response, wake_gap=wake
                )
            assert projection is not None
            for i in projection.missing_ids:
                self._stale.add(i)
                self._due[i] = completed + 60
            for i, reason in projection.rejected.items():
                self._stale.add(i)
                self._stopped[i] = reason
            for i, state in projection.states.items():
                self._states[i] = state
                self._stale.discard(i)
                self._schedule(i, state, completed)
            return self._outcome("UPDATED", projection=projection, wake_gap=wake)"""Pure football projection: source observations and semantic changes stay distinct."""

import hashlib
from collections import Counter
from collections.abc import Mapping, Sequence
from dataclasses import dataclass, field
from datetime import UTC, datetime
from typing import Any
from uuid import UUID

import rfc8785

from ..live_contracts import MAX_INTEGER, validate_live_record
from .api_football import ProviderResponse

PERIODS = {
    "NS": "PREGAME",
    "1H": "H1",
    "HT": "HALFTIME",
    "2H": "H2",
    "FT": "FINISHED",
    "SUSP": "BLOCKED",
    "INT": "BLOCKED",
    **dict.fromkeys(
        ("ET", "BT", "P", "AET", "PEN", "PST", "CANC", "ABD", "AWD", "WO"), "OUT_OF_SCOPE"
    ),
}
TYPES = {"goal": "GOAL", "card": "CARD", "subst": "SUBSTITUTION", "var": "VAR"}
DETAILS = {
    "normal goal": "NORMAL_GOAL",
    "own goal": "OWN_GOAL",
    "penalty": "PENALTY",
    "missed penalty": "MISSED_PENALTY",
    "yellow card": "YELLOW_CARD",
    "red card": "RED_CARD",
    "second yellow card": "SECOND_YELLOW",
    "goal cancelled": "GOAL_CANCELLED",
    "penalty cancelled": "PENALTY_CANCELLED",
}
OBSERVATION_FIELDS = frozenset(
    {
        "observed_at_utc",
        "received_mono_us",
        "clock_domain_id",
        "request_id",
        "batch_observation_id",
        "content_revision",
    }
)


@dataclass(frozen=True)
class ObservationStamp:
    observed_at_utc: datetime
    received_mono_us: int
    clock_domain_id: str
    batch_observation_id: str
    league_id: int
    season: int
    previous_states: Mapping[int, dict[str, Any]] = field(default_factory=dict, repr=False)


@dataclass(frozen=True)
class EventRevision:
    kind: str
    old_hash: str
    new_hash: str


@dataclass(frozen=True)
class BundleProjection:
    states: dict[int, dict[str, Any]]
    missing_ids: tuple[int, ...]
    rejected: dict[int, str]
    event_changes: dict[int, EventRevision]
    batch_observation_id: str
    source_kind: str


def _event_bytes(events: Sequence[dict[str, Any]]) -> list[bytes]:
    return sorted(rfc8785.dumps(event) for event in events)


def compare_event_sets(
    old: Sequence[dict[str, Any]], new: Sequence[dict[str, Any]]
) -> EventRevision:
    before, after = _event_bytes(old), _event_bytes(new)
    before_hash = hashlib.sha256(
        b"BH-LIVE-READONLY/Events/v1\0[" + b",".join(before) + b"]"
    ).hexdigest()
    after_hash = hashlib.sha256(
        b"BH-LIVE-READONLY/Events/v1\0[" + b",".join(after) + b"]"
    ).hexdigest()
    kind = (
        "UNCHANGED"
        if before == after
        else ("CORRECTION" if Counter(before) - Counter(after) else "EVENT_SET_CHANGED")
    )
    return EventRevision(kind, before_hash, after_hash)


def semantic_hash(state: dict[str, Any]) -> str:
    payload = {k: v for k, v in state.items() if k not in OBSERVATION_FIELDS}
    return hashlib.sha256(
        b"BH-LIVE-READONLY/ProviderSemantic/v1\0" + rfc8785.dumps(payload)
    ).hexdigest()


def _integer(value: object, minimum: int = 0, maximum: int = 2**53 - 1) -> int:
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError("INVALID_FIXTURE")
    return value


def _nullable(value: object, minimum: int = 0) -> int | None:
    return None if value is None else _integer(value, minimum)


def _score(value: object, flags: set[str]) -> dict[str, int] | None:
    if value is None:
        return None
    if type(value) is not dict:
        raise ValueError("INVALID_FIXTURE")
    home, away = value.get("home"), value.get("away")
    for score in (home, away):
        if score is not None:
            _integer(score, 0, 100)
    if home is None or away is None:
        if home is not None or away is not None:
            flags.add("PARTIAL_SCORE")
        return None
    return {"home": home, "away": away}


def _availability(value: object) -> str:
    if value is None:
        return "MISSING"
    if type(value) is not list:
        return "MALFORMED"
    return "PRESENT" if value else "EMPTY"


def _actor_id(value: object) -> int | None:
    if value is None:
        return None
    if type(value) is not dict:
        raise ValueError("INVALID_EVENT")
    return _nullable(value.get("id"), 1)


def _events(
    value: object, participants: set[int]
) -> tuple[list[dict[str, Any]], str, set[str], str]:
    if value is None:
        return [], "UNKNOWN_SECTION", {"EVENTS_UNKNOWN"}, "UNKNOWN"
    try:
        if type(value) is not list or len(value) > 2000:
            raise ValueError()
        normalized = []
        flags: set[str] = set()
        for event in value:
            source_time = event["time"]
            kind = TYPES.get(event["type"].casefold(), "OTHER")
            detail = DETAILS.get(event["detail"].casefold(), "OTHER")
            if kind == "OTHER" or detail == "OTHER":
                flags.add("UNKNOWN_EVENT_DETAIL")
            team = _actor_id(event.get("team"))
            if team is not None and team not in participants:
                raise ValueError()
            normalized.append(
                {
                    "elapsed_minute": _nullable(source_time.get("elapsed")),
                    "extra_minute": _nullable(source_time.get("extra")),
                    "team_id": team,
                    "player_id": _actor_id(event.get("player")),
                    "assist_id": _actor_id(event.get("assist")),
                    "type": kind,
                    "detail": detail,
                }
            )
        normalized.sort(key=rfc8785.dumps)
        dismissals = [
            e
            for e in normalized
            if e["type"] == "CARD" and e["detail"] in {"RED_CARD", "SECOND_YELLOW"}
        ]
        players = [(e["team_id"], e["player_id"]) for e in dismissals]
        red = "KNOWN"
        if (
            flags
            or any(team is None or player is None for team, player in players)
            or len(set(players)) != len(players)
        ):
            red = "UNKNOWN"
            flags.add("RED_CARD_STATE_UNKNOWN")
        return normalized, "OBSERVED" if normalized else "OBSERVED_EMPTY", flags, red
    except (KeyError, TypeError, ValueError, AttributeError):
        return [], "MALFORMED", {"EVENTS_MALFORMED"}, "UNKNOWN"


def _fixture(
    raw: dict[str, Any], response: ProviderResponse, stamp: ObservationStamp
) -> dict[str, Any]:
    fixture, league = raw["fixture"], raw["league"]
    fixture_id = _integer(fixture["id"], 1)
    if (
        _integer(league["id"], 1) != stamp.league_id
        or _integer(league["season"], 2000, 2100) != stamp.season
    ):
        raise ValueError("INVALID_FIXTURE")
    kickoff = datetime.fromisoformat(fixture["date"])
    if kickoff.tzinfo is None or _integer(fixture["timestamp"], 1) != int(kickoff.timestamp()):
        raise ValueError("INVALID_FIXTURE")
    kickoff_text = kickoff.astimezone(UTC).isoformat().replace("+00:00", "Z")
    home, away = raw["teams"]["home"], raw["teams"]["away"]
    home_id, away_id = _integer(home["id"], 1), _integer(away["id"], 1)
    previous = stamp.previous_states.get(fixture_id)
    if previous is not None:
        previous = validate_live_record(previous, "ProviderState")
        if (
            previous["fixture_id"] != fixture_id
            or previous["home_id"] != home_id
            or previous["away_id"] != away_id
            or previous["kickoff_utc"] != kickoff_text
        ):
            raise ValueError("IDENTITY_MISMATCH")
    status = fixture["status"]
    period = PERIODS.get(status["short"], "UNKNOWN")
    elapsed, extra = _nullable(status.get("elapsed")), _nullable(status.get("extra"))
    flags = {"SYNTHETIC"} if response.source_kind == "MOCK" else set()
    if period in {"UNKNOWN", "OUT_OF_SCOPE", "BLOCKED"}:
        flags.add(
            {
                "UNKNOWN": "UNKNOWN_PERIOD",
                "OUT_OF_SCOPE": "NORMAL_TIME_INELIGIBLE",
                "BLOCKED": "SOURCE_BLOCKED",
            }[period]
        )
    events, events_status, event_flags, red = _events(raw.get("events"), {home_id, away_id})
    flags.update(event_flags)
    availability = {
        name: _availability(raw.get(name))
        for name in ("events", "lineups", "statistics", "players")
    }
    if events_status == "MALFORMED":
        availability["events"] = "MALFORMED"
    score = _score(raw.get("goals"), flags)
    scores = raw.get("score") or {}
    halftime, fulltime = (
        _score(scores.get("halftime"), flags),
        _score(scores.get("fulltime"), flags),
    )
    if (
        score is not None
        and events_status in {"OBSERVED", "OBSERVED_EMPTY"}
        and all(e["type"] != "VAR" and e["detail"] not in {"OWN_GOAL", "OTHER"} for e in events)
    ):
        goals = Counter(
            e["team_id"]
            for e in events
            if e["type"] == "GOAL" and e["detail"] in {"NORMAL_GOAL", "PENALTY"}
        )
        if goals[home_id] != score["home"] or goals[away_id] != score["away"]:
            flags.add("SCORE_EVENT_DISAGREEMENT")
    state = {
        "fixture_id": fixture_id,
        "observed_at_utc": stamp.observed_at_utc.isoformat().replace("+00:00", "Z"),
        "received_mono_us": str(stamp.received_mono_us),
        "clock_domain_id": stamp.clock_domain_id,
        "request_id": response.request_id,
        "batch_observation_id": stamp.batch_observation_id,
        "content_revision": "1",
        "status_code": status["short"],
        "period": period,
        "elapsed_minute": elapsed,
        "extra_minute": extra,
        "clock_precision": "MINUTE" if elapsed is not None else "UNKNOWN",
        "kickoff_utc": kickoff_text,
        "home_id": home_id,
        "away_id": away_id,
        "home_name": home["name"],
        "away_name": away["name"],
        "score_current": score,
        "score_ht": halftime,
        "score_ft": fulltime,
        "events": events,
        "events_status": events_status,
        "section_availability": availability,
        "red_card_state": red,
        "provider_updated_at": None,
        "quality_flags": sorted(flags),
    }
    if previous is not None:
        revision = int(previous["content_revision"]) + (
            semantic_hash(previous) != semantic_hash(state)
        )
        state["content_revision"] = str(revision)
    return validate_live_record(state, "ProviderState")


def normalize_bundle(
    response: ProviderResponse, selected: Sequence[int], observation: ObservationStamp
) -> BundleProjection:
    if (
        response.purpose != "BUNDLE"
        or response.source_kind not in {"MOCK", "OBSERVED_REAL"}
        or not 1 <= len(selected) <= 5
        or len(set(selected)) != len(selected)
        or any(type(i) is not int or i <= 0 for i in selected)
        or observation.observed_at_utc.tzinfo is None
        or observation.observed_at_utc.utcoffset() != UTC.utcoffset(observation.observed_at_utc)
    ):
        raise ValueError("E_BUNDLE_SCOPE")
    _integer(observation.received_mono_us, 0, MAX_INTEGER)
    _integer(observation.league_id, 1)
    _integer(observation.season, 2000, 2100)
    for identifier in (
        observation.clock_domain_id,
        observation.batch_observation_id,
        response.request_id,
    ):
        UUID(identifier)
    seen: set[int] = set()
    states, rejected, changes = {}, {}, {}
    for raw in response.rows:
        fixture_id = _integer(raw.get("fixture", {}).get("id"), 1)
        if fixture_id not in selected or fixture_id in seen:
            raise ValueError("E_BUNDLE_SCOPE")
        seen.add(fixture_id)
        try:
            state = _fixture(raw, response, observation)
            states[fixture_id] = state
            previous = observation.previous_states.get(fixture_id)
            if (
                previous
                and previous["events_status"] in {"OBSERVED", "OBSERVED_EMPTY"}
                and state["events_status"] in {"OBSERVED", "OBSERVED_EMPTY"}
            ):
                changes[fixture_id] = compare_event_sets(previous["events"], state["events"])
        except Exception as error:
            rejected[fixture_id] = (
                "IDENTITY_MISMATCH" if str(error) == "IDENTITY_MISMATCH" else "INVALID_FIXTURE"
            )
    return BundleProjection(
        states,
        tuple(sorted(set(selected) - seen)),
        rejected,
        changes,
        observation.batch_observation_id,
        response.source_kind,
    )"""Request-count arithmetic, not provider billing or a source-latency guarantee."""

from collections.abc import Sequence
from dataclasses import dataclass
from decimal import ROUND_CEILING, Decimal


@dataclass(frozen=True)
class PollSegment:
    start_seconds: int
    end_seconds: int
    interval_seconds: int


@dataclass(frozen=True)
class BudgetEstimate:
    periodic: int
    overhead: int
    fallback: int
    calls: int
    with_reserve: int


def estimate_requests(
    segments: Sequence[PollSegment],
    setup: int = 3,
    confirmations: int = 2,
    fallback_calls: int = 0,
    reserve_fraction: Decimal = Decimal("0.20"),
) -> BudgetEstimate:
    if any(type(v) is not int or v < 0 for v in (setup, confirmations, fallback_calls)):
        raise ValueError("E_BUDGET_COUNT")
    if (
        not isinstance(reserve_fraction, Decimal)
        or not reserve_fraction.is_finite()
        or not 0 <= reserve_fraction <= 1
    ):
        raise ValueError("E_BUDGET_RESERVE")
    for s in segments:
        if (
            any(type(v) is not int for v in (s.start_seconds, s.end_seconds, s.interval_seconds))
            or not 0 <= s.start_seconds <= s.end_seconds
            or s.interval_seconds <= 0
        ):
            raise ValueError("E_BUDGET_INTERVAL")
    boundaries = sorted({v for s in segments for v in (s.start_seconds, s.end_seconds)})
    merged: list[PollSegment] = []
    # ponytail: quadratic in plan segments (a handful per fixture); sweep-line if plans grow.
    for start, end in zip(boundaries, boundaries[1:], strict=False):
        active = [
            s.interval_seconds
            for s in segments
            if s.start_seconds <= start and s.end_seconds >= end
        ]
        if not active:
            continue
        interval = min(active)
        if merged and merged[-1].end_seconds == start and merged[-1].interval_seconds == interval:
            merged[-1] = PollSegment(merged[-1].start_seconds, end, interval)
        else:
            merged.append(PollSegment(start, end, interval))
    periodic = sum(
        (s.end_seconds - s.start_seconds + s.interval_seconds - 1) // s.interval_seconds
        for s in merged
    )
    calls = periodic + setup + confirmations + fallback_calls
    with_reserve = int(
        (Decimal(calls) * (1 + reserve_fraction)).to_integral_value(rounding=ROUND_CEILING)
    )
    return BudgetEstimate(periodic, setup + confirmations, fallback_calls, calls, with_reserve)"""Durable attempt reservations with one process owner; this is not run authorization."""

import fcntl
import math
import os
import re
import sqlite3
import threading
import time
from collections.abc import Mapping
from dataclasses import dataclass
from datetime import UTC, datetime, timedelta
from pathlib import Path
from types import TracebackType
from typing import cast
from uuid import UUID, uuid4

from ..live_contracts import CONTRACTS

PURPOSES = frozenset({"STATUS", "COVERAGE", "LOOKUP", "BUNDLE", "EVENTS_FALLBACK"})
OUTCOMES = frozenset(
    {
        "SUCCESS",
        "AUTH_FAILED",
        "HTTP_429",
        "HTTP_5XX",
        "TIMEOUT",
        "REDIRECT",
        "TRANSPORT_ERROR",
        "SCHEMA_ERROR",
        "PROVIDER_ERROR",
        "UNKNOWN",
    }
)
QUOTA_ERRORS = frozenset({"QUOTA_INVALID", "QUOTA_INCONSISTENT"})
HEADER_NAMES = (
    "x-ratelimit-requests-limit",
    "x-ratelimit-requests-remaining",
    "x-ratelimit-limit",
    "x-ratelimit-remaining",
)


@dataclass(frozen=True)
class Denied:
    code: str


@dataclass(frozen=True)
class Reservation:
    attempt_id: str
    scope_id: str
    purpose: str
    reserved_at_utc: str


def _quota_headers(headers: Mapping[str, str]) -> tuple[int | None, ...]:
    selected: dict[str, str] = {}
    for key, value in headers.items():
        name = key.lower()
        if name in HEADER_NAMES:
            if (
                name in selected
                or type(value) is not str
                or not re.fullmatch(r"[0-9]{1,10}", value)
            ):
                raise ValueError("E_QUOTA_HEADERS")
            selected[name] = value
    if not selected:
        return (None, None, None, None)
    if set(selected) != set(HEADER_NAMES):
        raise ValueError("E_QUOTA_HEADERS")
    limit, remaining, minute_limit, minute_remaining = (int(selected[n]) for n in HEADER_NAMES)
    if not (
        0 < limit <= 2**31 - 1
        and 0 <= remaining <= limit
        and 0 < minute_limit <= 2**31 - 1
        and 0 <= minute_remaining <= minute_limit
    ):
        raise ValueError("E_QUOTA_HEADERS")
    return limit, remaining, minute_limit, minute_remaining


class QuotaLedger:
    def __init__(
        self,
        path: Path,
        *,
        scope_id: str,
        daily_cap: int = 6000,
        session_cap: int = 600,
        minute_cap: int = 6,
        allow_status_bootstrap: bool = False,
    ):
        if (
            str(UUID(scope_id)) != scope_id
            or type(allow_status_bootstrap) is not bool
            or any(
                type(v) is not int or not 1 <= v <= maximum
                for v, maximum in [(daily_cap, 6000), (session_cap, 600), (minute_cap, 6)]
            )
        ):
            raise ValueError("E_QUOTA_CONFIG")
        if any(p.is_symlink() for p in (path, *path.parents)):
            raise ValueError("E_QUOTA_PATH")
        path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        if path.parent.stat().st_mode & 0o077:
            raise ValueError("E_QUOTA_PATH")
        self._lock_fd = os.open(str(path) + ".lock", os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
        try:
            fcntl.flock(self._lock_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            os.close(self._lock_fd)
            raise ValueError("E_QUOTA_POLLER_LOCK") from None
        try:
            fd = os.open(path, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
            os.close(fd)
            if path.stat().st_mode & 0o077:
                raise ValueError("E_QUOTA_PATH")
            self.db = sqlite3.connect(path, isolation_level=None, check_same_thread=False)
            self.db.row_factory = sqlite3.Row
            ddl = (CONTRACTS / "quota-store.sql").read_text()
            if not self.db.execute("SELECT name FROM sqlite_schema WHERE type='table'").fetchone():
                self.db.executescript(ddl)
            for pragma in (
                "journal_mode=DELETE",
                "synchronous=FULL",
                "foreign_keys=ON",
                "trusted_schema=OFF",
                "busy_timeout=5000",
            ):
                self.db.execute("PRAGMA " + pragma)
            with sqlite3.connect(":memory:") as expected:
                expected.executescript(ddl)
                query = "SELECT type,name,sql FROM sqlite_schema ORDER BY type,name"
                if [tuple(row) for row in self.db.execute(query)] != expected.execute(
                    query
                ).fetchall():
                    raise ValueError("E_QUOTA_SCHEMA")
            if self.db.execute("PRAGMA quick_check").fetchone()[0] != "ok":
                raise ValueError("E_QUOTA_DATABASE")
        except BaseException:
            if hasattr(self, "db"):
                self.db.close()
            os.close(self._lock_fd)
            raise
        self.scope_id = scope_id
        self.daily_cap, self.session_cap, self.minute_cap = daily_cap, session_cap, minute_cap
        self.allow_status_bootstrap = allow_status_bootstrap
        self.boot_id = Path("/proc/sys/kernel/random/boot_id").read_text().strip()
        self._pending: Reservation | None = None
        self._mutex = threading.RLock()
        self._pid = os.getpid()
        self._closed = False

    def __enter__(self) -> "QuotaLedger":
        return self

    def __exit__(
        self,
        exc_type: type[BaseException] | None,
        exc: BaseException | None,
        tb: TracebackType | None,
    ) -> None:
        self.close()

    def close(self) -> None:
        with self._mutex:
            if not self._closed:
                self.db.close()
                os.close(self._lock_fd)
                self._closed = True

    def _owner(self) -> None:
        if self._closed or os.getpid() != self._pid:
            raise ValueError("E_QUOTA_OWNER")

    def count_attempts(self, scope_id: str | None = None) -> int:
        with self._mutex:
            self._owner()
            return int(
                self.db.execute(
                    "SELECT count(*) FROM quota_reservations WHERE scope_id=?",
                    (scope_id or self.scope_id,),
                ).fetchone()[0]
            )

    def _latest_quota(self) -> sqlite3.Row | None:
        return cast(
            sqlite3.Row | None,
            self.db.execute(
                "SELECT r.rowid AS ordinal,r.*,o.* FROM quota_reservations r JOIN quota_outcomes o "
                "USING(attempt_id) WHERE o.observed_daily_limit IS NOT NULL "
                "ORDER BY r.rowid DESC LIMIT 1"
            ).fetchone(),
        )

    def display_remaining(self, now_utc: datetime, now_mono: float) -> dict[str, int | None]:
        with self._mutex:
            self._owner()
            day = now_utc.astimezone(UTC).date().isoformat()
            used_day = self.db.execute(
                "SELECT count(*) FROM quota_reservations WHERE utc_day=?", (day,)
            ).fetchone()[0]
            used_minute = self.db.execute(
                "SELECT count(*) FROM quota_reservations WHERE boot_id=? AND reserved_mono_us>?",
                (self.boot_id, int((now_mono - 60) * 1000000)),
            ).fetchone()[0]
            known = self._latest_quota()
            return {
                "session_remaining": max(0, self.session_cap - self.count_attempts()),
                "daily_remaining": max(0, self.daily_cap - used_day),
                "minute_remaining": max(0, self.minute_cap - used_minute),
                "provider_remaining": int(known["observed_daily_remaining"])
                if known is not None
                and known["utc_day"] == day
                and known["boot_id"] == self.boot_id
                else None,
            }

    def _provider_guard(self, purpose: str, day: str, mono_us: int) -> Denied | None:
        known = self._latest_quota()
        latest = self.db.execute(
            "SELECT r.scope_id,o.result_code FROM quota_reservations r JOIN quota_outcomes o "
            "USING(attempt_id) ORDER BY r.rowid DESC LIMIT 1"
        ).fetchone()
        if (
            latest
            and latest["scope_id"] == self.scope_id
            and latest["result_code"] == "AUTH_FAILED"
        ):
            return Denied("AUTH_FAILED")
        if known is None or known["utc_day"] != day or known["boot_id"] != self.boot_id:
            used = self.db.execute(
                "SELECT count(*) FROM quota_reservations WHERE scope_id=? AND purpose='STATUS' "
                "AND utc_day=?",
                (self.scope_id, day),
            ).fetchone()[0]
            if purpose == "STATUS" and self.allow_status_bootstrap and used == 0:
                return None
            return Denied("QUOTA_UNKNOWN" if known is None else "QUOTA_RECONCILIATION_REQUIRED")
        if latest and latest["result_code"] in QUOTA_ERRORS and purpose != "STATUS":
            return Denied("QUOTA_RECONCILIATION_REQUIRED")
        last_ordinal = self.db.execute("SELECT max(rowid) FROM quota_reservations").fetchone()[0]
        start = (
            self.db.execute(
                "SELECT max(r.rowid) FROM quota_reservations r "
                "JOIN quota_outcomes o USING(attempt_id) "
                "WHERE r.utc_day=? AND r.purpose='STATUS' AND o.observed_daily_limit IS NOT NULL",
                (day,),
            ).fetchone()[0]
            or 0
        )
        receipts = self.db.execute(
            "SELECT r.rowid AS ordinal,r.*,o.* FROM quota_reservations r JOIN quota_outcomes o "
            "USING(attempt_id) WHERE r.rowid>=? AND r.utc_day=? AND r.boot_id=? "
            "AND o.observed_daily_limit IS NOT NULL",
            (start, day, self.boot_id),
        ).fetchall()
        # Preserve observed headers literally. Ordinal gaps only overcount debt; rows never delete.
        remaining = min(
            row["observed_daily_remaining"] - (last_ordinal - row["ordinal"]) for row in receipts
        )
        floor = (known["observed_daily_limit"] + 4) // 5
        if remaining <= floor:
            return Denied("PROVIDER_DAILY_RESERVE")
        rolling = self.db.execute(
            "SELECT count(*) FROM quota_reservations WHERE boot_id=? AND reserved_mono_us>?",
            (self.boot_id, mono_us - 60_000_000),
        ).fetchone()[0]
        if rolling >= known["observed_minute_limit"]:
            return Denied("PROVIDER_MINUTE_BUDGET")
        for row in receipts:
            observed_mono = row["reserved_mono_us"] + int(
                (
                    datetime.fromisoformat(row["observed_at_utc"])
                    - datetime.fromisoformat(row["reserved_at_utc"])
                ).total_seconds()
                * 1_000_000
            )
            if (
                mono_us - observed_mono < 60_000_000
                and row["observed_minute_remaining"] - (last_ordinal - row["ordinal"]) <= 0
            ):
                return Denied("PROVIDER_MINUTE_BUDGET")
        return None

    def reserve_attempt(
        self, scope_id: str, purpose: str, now_utc: datetime, now_mono: float
    ) -> Reservation | Denied:
        with self._mutex:
            self._owner()
            if (
                scope_id != self.scope_id
                or purpose not in PURPOSES
                or now_utc.tzinfo is None
                or now_utc.utcoffset() != UTC.utcoffset(now_utc)
                or type(now_mono) not in {int, float}
                or not math.isfinite(now_mono)
                or not 0 <= now_mono <= (2**63 - 1) / 1_000_000
            ):
                raise ValueError("E_QUOTA_REQUEST")
            if self._pending is not None:
                return Denied("IN_FLIGHT")
            day, utc = now_utc.date().isoformat(), now_utc.isoformat()
            mono = int(now_mono * 1_000_000)
            self.db.execute("BEGIN IMMEDIATE")
            try:
                last = self.db.execute(
                    "SELECT * FROM quota_reservations ORDER BY rowid DESC LIMIT 1"
                ).fetchone()
                deny = None
                if last and (
                    now_utc < datetime.fromisoformat(last["reserved_at_utc"])
                    or (last["boot_id"] == self.boot_id and mono < last["reserved_mono_us"])
                ):
                    deny = Denied("CLOCK_ROLLBACK")
                elif self.count_attempts() >= self.session_cap:
                    deny = Denied("SESSION_BUDGET")
                elif (
                    self.db.execute(
                        "SELECT count(*) FROM quota_reservations WHERE utc_day=?", (day,)
                    ).fetchone()[0]
                    >= self.daily_cap
                ):
                    deny = Denied("DAILY_BUDGET")
                elif (
                    last
                    and last["boot_id"] != self.boot_id
                    and (now_utc - datetime.fromisoformat(last["reserved_at_utc"])).total_seconds()
                    < 60
                ):
                    deny = Denied("CLOCK_RECONCILIATION_REQUIRED")
                elif (
                    last
                    and last["boot_id"] == self.boot_id
                    and mono - last["reserved_mono_us"] < 10_000_000
                ):
                    deny = Denied("MINIMUM_GAP")
                elif (
                    self.db.execute(
                        "SELECT count(*) FROM quota_reservations "
                        "WHERE boot_id=? AND reserved_mono_us>?",
                        (self.boot_id, mono - 60_000_000),
                    ).fetchone()[0]
                    >= self.minute_cap
                ):
                    deny = Denied("MINUTE_BUDGET")
                else:
                    deny = self._provider_guard(purpose, day, mono)
                if deny:
                    self.db.execute("ROLLBACK")
                    return deny
                attempt = Reservation(str(uuid4()), scope_id, purpose, utc)
                self.db.execute(
                    "INSERT INTO quota_reservations VALUES(?,?,?,?,?,?,?,?)",
                    (
                        attempt.attempt_id,
                        "api-football-primary",
                        scope_id,
                        purpose,
                        day,
                        utc,
                        self.boot_id,
                        mono,
                    ),
                )
                self.db.execute("COMMIT")
                self._pending = attempt
                self._pending_native_start = time.monotonic()
                return attempt
            except BaseException:
                if self.db.in_transaction:
                    self.db.execute("ROLLBACK")
                raise

    def finalize_attempt(
        self, reservation_id: str, outcome: str, headers: Mapping[str, str]
    ) -> None:
        with self._mutex:
            self._owner()
            pending = self._pending
            if pending is None or pending.attempt_id != reservation_id or outcome not in OUTCOMES:
                raise ValueError("E_QUOTA_FINALIZE")
            result = outcome
            try:
                limit, remaining, minute_limit, minute_remaining = _quota_headers(headers)
            except (ValueError, TypeError, AttributeError):
                limit = remaining = minute_limit = minute_remaining = None
                result = "QUOTA_INVALID"
            old = self._latest_quota()
            if (
                old
                and limit is not None
                and old["utc_day"] == pending.reserved_at_utc[:10]
                and pending.purpose != "STATUS"
                and (
                    limit != old["observed_daily_limit"]
                    or remaining > old["observed_daily_remaining"]
                )
            ):
                limit = remaining = minute_limit = minute_remaining = None
                result = "QUOTA_INCONSISTENT"
            if outcome == "AUTH_FAILED":
                result = outcome
            observed = (
                datetime.fromisoformat(pending.reserved_at_utc)
                + timedelta(seconds=time.monotonic() - self._pending_native_start)
            ).isoformat()
            self.db.execute("BEGIN IMMEDIATE")
            try:
                self.db.execute(
                    "INSERT INTO quota_outcomes VALUES(?,?,?,?,?,?,?)",
                    (
                        reservation_id,
                        result,
                        limit,
                        remaining,
                        minute_limit,
                        minute_remaining,
                        observed,
                    ),
                )
                self.db.execute("COMMIT")
                self._pending = None
            except BaseException:
                if self.db.in_transaction:
                    self.db.execute("ROLLBACK")
                raise"""Hybrid Discovery v6.2 authoring-only bootstrap.""""""Check declaration-stage producers, sources, and consumers fail closed."""

from __future__ import annotations

import re
from pathlib import Path

from jsonschema import Draft202012Validator

SHA256 = re.compile(r"[0-9a-f]{64}\Z")


def _source_valid(entry: dict[str, object]) -> bool:
    source = entry["source"]
    classification = entry["classification"]
    if classification in {"BASELINE_INPUT", "PLAN_SEED", "GENERATED_OUTPUT"}:
        return (
            isinstance(source, dict)
            and set(source) == {"path"}
            and isinstance(source["path"], str)
            and bool(source["path"].strip())
        )
    if classification == "BASELINE_COPY":
        return (
            isinstance(source, dict)
            and set(source) == {"path", "sha256"}
            and isinstance(source["path"], str)
            and bool(source["path"].strip())
            and isinstance(source["sha256"], str)
            and bool(SHA256.fullmatch(source["sha256"]))
        )
    if classification in {"TASK_OUTPUT", "EVIDENCE_OUTPUT"}:
        return source is None
    if classification == "EXTERNAL_INPUT":
        return (
            isinstance(source, dict)
            and set(source)
            in ({"path", "binding"}, {"path", "binding", "creation_owner", "creation_command"})
            and all(isinstance(value, str) and value.strip() for value in source.values())
        )
    return False


def _path(value: str, authoring_root: Path, owned_paths: set[str]) -> str:
    value = value.split("::", 1)[0]
    normalized = value.removeprefix(str(authoring_root) + "/")
    if normalized in owned_paths:
        return normalized
    matches = {
        owned
        for owned in owned_paths
        if not Path(owned).is_absolute() and value.endswith("/" + owned)
    }
    return next(iter(matches)) if len(matches) == 1 else value


def validate_artifact_lifecycle(
    registry: dict[str, object],
    manifest: dict[str, object],
    authoring_root: Path | None = None,
    schema: dict[str, object] | None = None,
) -> dict[str, object]:
    authoring_root = authoring_root or Path(__file__).resolve().parents[3]
    if schema is not None:
        schema = {**schema, "$ref": "#/$defs/ArtifactOwnershipRegistry"}
        if list(Draft202012Validator(schema).iter_errors(registry)):
            raise ValueError("E_OWNER_SCHEMA")
    tasks = manifest["tasks"]
    order = {task["task_id"]: index for index, task in enumerate(tasks)}
    entries = registry.get("entries")
    if not isinstance(entries, list):
        raise ValueError("E_OWNER_REGISTRY")
    paths: set[str] = set()
    owned: dict[str, dict[str, object]] = {}
    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError("E_OWNER_SCHEMA")
        path = entry.get("path")
        if not isinstance(path, str) or not path or path in paths:
            raise ValueError("E_OWNER_DUPLICATE")
        paths.add(path)
        owned[path] = entry
        if not _source_valid(entry):
            raise ValueError(f"E_OWNER_SOURCE:{path}")
        owner = entry.get("creation_owner")
        if owner is None:
            if not entry["source"]:
                raise ValueError(f"E_OWNER_MISSING:{path}")
        elif not isinstance(owner, str) or not owner.strip() or owner not in order:
            raise ValueError(f"E_OWNER_UNKNOWN:{path}")
        for modifier in entry.get("modifying_tasks", []):
            if (
                not isinstance(modifier, str)
                or modifier not in order
                or owner is not None
                and order[modifier] < order[owner]
            ):
                raise ValueError(f"E_MODIFIER_ORDER:{path}")
        qualification = entry.get("qualification_owner")
        if qualification is not None and (
            not isinstance(qualification, str)
            or qualification not in order
            or owner is not None
            and order[qualification] < order[owner]
        ):
            raise ValueError(f"E_QUALIFICATION_ORDER:{path}")
        for consumer in entry.get("consumers", []):
            if not isinstance(consumer, str) or consumer not in order:
                raise ValueError(f"E_CONSUMER_UNKNOWN:{path}")
            if owner is not None and order[consumer] < order[owner]:
                raise ValueError(f"E_CONSUMER_BEFORE_OWNER:{path}")
    for task in tasks:
        task_id = task["task_id"]
        for field in ("outputs", "exact_files", "evidence_artifacts"):
            for value in task[field]:
                path = _path(value, authoring_root, paths)
                entry = owned.get(path)
                if entry is None:
                    raise ValueError(f"E_UNOWNED:{value}")
                if field == "outputs" and task_id not in {
                    entry["creation_owner"],
                    *entry["modifying_tasks"],
                }:
                    raise ValueError(f"E_OUTPUT_OWNER:{value}")
                if task_id not in entry["consumers"] and task_id != entry["creation_owner"]:
                    raise ValueError(f"E_CONSUMER_UNDECLARED:{value}")
    return {"result": "PASS", "artifact_count": len(entries)}"""Bootstrap-only semantic verification for the sealed authorization vectors.

This module verifies contract fixtures.  It does not expose an authorization or
discovery runtime entry point, mutate a consumption ledger, or confer authority.
"""

