import hashlib
import hmac
import json
import unicodedata
from functools import lru_cache
from pathlib import Path
from typing import Any, cast

import rfc8785


class CanonicalError(ValueError):
    pass


def parse_strict_json(raw: bytes) -> object:
    if raw.startswith(b"\xef\xbb\xbf"):
        raise CanonicalError("MALFORMED_UTF8_OR_JSON")
    try:
        text = raw.decode("utf-8")
        value = json.loads(
            text,
            object_pairs_hook=_unique_object,
            parse_constant=_reject_constant,
        )
    except UnicodeError as error:
        raise CanonicalError("MALFORMED_UTF8_OR_JSON") from error
    except json.JSONDecodeError as error:
        raise CanonicalError("MALFORMED_UTF8_OR_JSON") from error
    _validate_unicode(value)
    return value


def _reject_constant(_value: str) -> None:
    raise CanonicalError("MALFORMED_UTF8_OR_JSON")


def _unique_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise CanonicalError("DUPLICATE_JSON_KEY")
        result[key] = value
    return result


def _validate_unicode(value: object) -> None:
    if isinstance(value, str):
        if str.isascii(value):
            return
        if (
            any(0xD800 <= ord(char) <= 0xDFFF for char in value)
            or unicodedata.normalize("NFC", value) != value
        ):
            raise CanonicalError("NON_NFC_OR_INVALID_UNICODE")
    elif isinstance(value, dict):
        for key, child in value.items():
            _validate_unicode(key)
            _validate_unicode(child)
    elif isinstance(value, list):
        for child in value:
            _validate_unicode(child)


def canonical_content_hash(
    artifact_type: str,
    value: object,
    *,
    registry_path: Path | None = None,
    registry_bytes: bytes | None = None,
) -> str:
    return hashlib.sha256(
        canonical_preimage(
            artifact_type, value, registry_path=registry_path, registry_bytes=registry_bytes
        )
    ).hexdigest()


def verify_canonical_content_hash(
    artifact_type: str,
    value: object,
    expected_hash: str,
    *,
    registry_path: Path | None = None,
) -> bool:
    computed = canonical_content_hash(artifact_type, value, registry_path=registry_path)
    if not hmac.compare_digest(computed, expected_hash):
        raise CanonicalError("CONTENT_HASH_MISMATCH")
    return True


@lru_cache(maxsize=8)
def _domain(registry_bytes: bytes, artifact_type: str) -> tuple[str, tuple[str, ...]]:
    # Cache immutable results by complete source bytes, never pathname or mtime.
    registry = parse_strict_json(registry_bytes)
    assert isinstance(registry, dict)
    matches = [entry for entry in registry["domains"] if entry["artifact_type"] == artifact_type]
    if len(matches) != 1:
        raise CanonicalError("UNSUPPORTED_VERSION_OR_ALGORITHM")
    entry = matches[0]
    _validate_registered_exclusions(
        artifact_type,
        cast(list[str], entry["excluded_json_pointers"]),
        cast(dict[str, Any], registry),
    )
    domain = entry["domain"]
    if not isinstance(domain, str):
        raise CanonicalError("SCHEMA_INVALID")
    return domain, tuple(entry["excluded_json_pointers"])


def canonical_preimage(
    artifact_type: str,
    value: object,
    *,
    registry_path: Path | None = None,
    registry_bytes: bytes | None = None,
) -> bytes:
    registry_path = registry_path or Path(
        "vendor/hybrid-discovery-v6.3.6/registries/canonical-hash-domains.v1.json"
    )
    domain, exclusions = _domain(
        registry_path.read_bytes() if registry_bytes is None else registry_bytes, artifact_type
    )
    projected = copy.deepcopy(value)
    if not isinstance(projected, dict):
        raise CanonicalError("SCHEMA_INVALID")
    for pointer in exclusions:
        if pointer.count("/") != 1:
            raise CanonicalError("UNREGISTERED_HASH_EXCLUSION")
        key = pointer[1:].replace("~1", "/").replace("~0", "~")
        if key not in projected:
            raise CanonicalError("SCHEMA_INVALID_BEFORE_CANONICAL_HASH")
        del projected[key]
    _validate_unicode(projected)
    canonical = rfc8785.dumps(projected)
    assert isinstance(canonical, bytes)
    return domain.encode() + canonical


def _validate_registered_exclusions(
    artifact_type: str, exclusions: list[str], registry: dict[str, Any]
) -> None:
    classes = registry.get("domain_validation_classes")
    groups = registry.get("schema_binding_groups")
    if not isinstance(classes, list) or not isinstance(groups, list):
        raise CanonicalError("UNREGISTERED_HASH_EXCLUSION")
    class_matches = [
        item
        for item in classes
        if isinstance(item, dict)
        and isinstance(item.get("artifact_types"), list)
        and artifact_type in item["artifact_types"]
    ]
    if len(class_matches) != 1:
        raise CanonicalError("UNREGISTERED_HASH_EXCLUSION")
    class_id = class_matches[0].get("class_id")
    if class_id == "GOVERNED_NO_EXCLUSION":
        if exclusions:
            raise CanonicalError("UNREGISTERED_HASH_EXCLUSION")
        return
    if class_id != "SCHEMA_GATED_SELF_HASH":
        raise CanonicalError("UNREGISTERED_HASH_EXCLUSION")
    group_matches = [
        item
        for item in groups
        if isinstance(item, dict)
        and isinstance(item.get("artifact_types"), list)
        and artifact_type in item["artifact_types"]
    ]
    if len(group_matches) != 1:
        raise CanonicalError("UNREGISTERED_HASH_EXCLUSION")
    registered = group_matches[0].get("required_excluded_json_pointers")
    if not isinstance(registered, list) or exclusions != registered:
        raise CanonicalError("UNREGISTERED_HASH_EXCLUSION")from .errors import ContractNotImplementedError


def validate_discovery_capability(*_args: object, **_kwargs: object) -> None:
    raise ContractNotImplementedError("G0-T03")"""Shared frozen precedence and coverage validation for clock vectors."""
from __future__ import annotations


def load_clock_failure_precedence(
    precedence: dict[str, object],
    coverage: dict[str, object],
    vectors: dict[str, object],
) -> dict[str, object]:
    negative = precedence.get("negative_vectors")
    source_negative = vectors.get("mapping_negative_vectors")
    entries = coverage.get("entries")
    ordered = precedence.get("ordered_error_codes")
    if (
        not isinstance(negative, list)
        or not isinstance(source_negative, list)
        or not isinstance(entries, list)
        or not isinstance(ordered, list)
        or precedence.get("negative_mapping_count") != 16
        or len(negative) != 16
        or len(source_negative) != 16
        or coverage.get("total_named_vectors") != 65
        or len(entries) != 65
        or len(ordered) != len(set(ordered))
    ):
        raise ValueError("E_CLOCK_PRECEDENCE")
    for index, (frozen, source) in enumerate(zip(negative, source_negative), 1):
        expected = source.get("expected_error") or "SOURCE_AGE_UNKNOWN"
        if (
            frozen.get("vector_id") != source.get("id")
            or frozen.get("source_index") != index - 1
            or frozen.get("mutation") != source.get("mutation")
            or frozen.get("expected_error") != source.get("expected_error")
            or frozen.get("mapping_eligible") != source.get("mapping_eligible")
            or frozen.get("precedence_rank") != index
            or ordered[index - 1] != expected
        ):
            raise ValueError("E_CLOCK_PRECEDENCE")
    ids = [entry.get("vector_id") for entry in entries if isinstance(entry, dict)]
    if len(ids) != len(set(ids)) or any(not isinstance(vector_id, str) for vector_id in ids):
        raise ValueError("E_CLOCK_COVERAGE")
    return {
        "negative_mapping_count": len(negative),
        "total_named_vectors": len(ids),
        "ordered_error_codes": ordered,
    }"""Exact raw clock arithmetic and separate stored assertions; vector adapter is test-only."""
from __future__ import annotations

from collections.abc import Mapping
from pathlib import Path
from typing import NotRequired, TypedDict, cast

from jsonschema.exceptions import ValidationError  # type: ignore[import-untyped]

from .canonical import CanonicalError, canonical_content_hash, verify_canonical_content_hash
from .schema_registry import validate_artifact

INT64_MAX = 2**63 - 1
INT64_MIN = -(2**63)


class ClockPrimitiveEvaluation(TypedDict):
    accepted: bool
    error: str


class ClockObservationEvaluation(ClockPrimitiveEvaluation):
    schema_valid: bool
    computed_hash: str | None


def verify_clock_observation(
    artifact_type: str,
    record: Mapping[str, object],
    *,
    vendor: Path = Path("vendor/hybrid-discovery-v6.3.6"),
) -> ClockObservationEvaluation:
    """Validate the observation before recomputing its registered canonical hash."""
    if "content_hash" not in record:
        return {"accepted": False, "error": "SCHEMA_INVALID_BEFORE_CANONICAL_HASH",
                "schema_valid": False, "computed_hash": None}
    try:
        validate_artifact(
            dict(record), "clock-coherence-records.schema.json",
            bootstrap_only=True, vendor=vendor,
        )
        expected_hash = record["content_hash"]
        if not isinstance(expected_hash, str):
            raise ValidationError("content_hash")
        computed_hash = canonical_content_hash(
            artifact_type, record,
            registry_path=vendor / "registries/canonical-hash-domains.v1.json",
        )
        verify_canonical_content_hash(
            artifact_type, record, expected_hash,
            registry_path=vendor / "registries/canonical-hash-domains.v1.json",
        )
    except ValidationError:
        return {"accepted": False, "error": "SCHEMA_INVALID", "schema_valid": False,
                "computed_hash": None}
    except CanonicalError as exc:
        return {"accepted": False, "error": str(exc), "schema_valid": True,
                "computed_hash": computed_hash if "computed_hash" in locals() else None}
    return {"accepted": True, "error": "SCHEMA_VALID_AND_RECOMPUTED_HASH_MATCH",
            "schema_valid": True, "computed_hash": computed_hash}


def compute_drift(relative_drift_ppm: int, source_anchor_us: int, x: int) -> int:
    """Return ceil(ppm * absolute source distance / one million)."""
    if any(type(value) is not int for value in (relative_drift_ppm, source_anchor_us, x)):
        raise ValueError("E_INVALID_DRIFT_INPUT")
    if relative_drift_ppm < 0 or source_anchor_us < 0 or x < 0:
        raise ValueError("E_INVALID_DRIFT_INPUT")
    numerator = relative_drift_ppm * abs(x - source_anchor_us)
    return (numerator + 999_999) // 1_000_000


def validate_midpoint(value: Mapping[str, object]) -> ClockPrimitiveEvaluation:
    """Apply the exact overflow-safe predicates used by the governed SQLite DDL."""
    fields = {
        "offset_lower_us", "offset_upper_us", "base_uncertainty_us", "offset_midpoint_us",
    }
    if set(value) != fields or any(type(value[field]) is not int for field in fields):
        return {"accepted": False, "error": "REJECT_CHECK_CONSTRAINT"}
    lower = cast(int, value["offset_lower_us"])
    upper = cast(int, value["offset_upper_us"])
    midpoint = cast(int, value["offset_midpoint_us"])
    uncertainty = cast(int, value["base_uncertainty_us"])
    if any(number < INT64_MIN or number > INT64_MAX for number in (lower, upper, midpoint)):
        return {"accepted": False, "error": "REJECT_OVERFLOW_GUARD"}
    if uncertainty < 0 or uncertainty > 125_000 or lower > INT64_MAX - uncertainty * 2:
        return {"accepted": False, "error": "REJECT_OVERFLOW_GUARD"}
    if (lower > midpoint or midpoint > upper or upper != lower + uncertainty * 2
            or midpoint != lower + uncertainty):
        return {"accepted": False, "error": "REJECT_CHECK_CONSTRAINT"}
    error = "ACCEPT_OVERFLOW_SAFE" if upper == INT64_MAX else "ACCEPT"
    return {"accepted": True, "error": error}

class ClockEndpoint(TypedDict):
    clock_domain_id: str
    boot_id: str
    owner: str
    unit: str
    resolution_us: int


class RawClockInput(TypedDict):
    source: ClockEndpoint
    target: ClockEndpoint
    t1: int
    t2: int
    t3: int
    t4: int
    valid_sample_count: NotRequired[int]
    mapping_segment_age_us: NotRequired[int]
    wall_step_us: NotRequired[int]
    eligible_target_intervals: NotRequired[list[list[int]]]
    proven_mapping: NotRequired[bool]


class ClockGuardrails(TypedDict):
    max_network_rtt_us: int
    max_base_uncertainty_us: int
    minimum_valid_samples: int
    max_mapping_segment_age_us: int
    wall_step_tolerance_us: int


class ClockEvaluation(TypedDict):
    accepted: bool
    error: str
    raw_lower_us: int
    raw_upper_us: int
    network_rtt_us: int
    padding_us: int
    offset_interval_us: list[int]
    offset_midpoint_us: int
    base_uncertainty_us: int


_IDENTITY_FIELDS = ("clock_domain_id", "boot_id", "unit", "owner")
_TIMESTAMPS = ("t1", "t2", "t3", "t4")
_ENDPOINT_OVERRIDES = {f"{t}_{field}" for t in _TIMESTAMPS for field in _IDENTITY_FIELDS}
_RAW_FIELDS = set(RawClockInput.__annotations__) | _ENDPOINT_OVERRIDES
_STORED_FIELDS = set(ClockEvaluation.__annotations__) | {"offset_lower_us", "offset_upper_us"}


def _result(
    error: str, raw_lower: int = 0, raw_upper: int = 0, rtt: int = 0,
    padding: int = 0, lower: int = 0, upper: int = 0,
) -> ClockEvaluation:
    midpoint = (lower + upper) // 2
    return {
        "accepted": error == "ACCEPT", "error": error,
        "raw_lower_us": raw_lower, "raw_upper_us": raw_upper,
        "network_rtt_us": rtt, "padding_us": padding,
        "offset_interval_us": [lower, upper], "offset_midpoint_us": midpoint,
        "base_uncertainty_us": max(midpoint - lower, upper - midpoint),
    }


def _reject(actual: ClockEvaluation, error: str) -> ClockEvaluation:
    return {**actual, "accepted": False, "error": error}


def _valid_input(raw: Mapping[str, object], guardrails: Mapping[str, object]) -> bool:
    if not isinstance(raw, Mapping) or not isinstance(guardrails, Mapping):
        return False
    if set(raw) - _RAW_FIELDS:
        return False
    for key in _TIMESTAMPS:
        if type(raw.get(key)) is not int:
            return False
    for side in ("source", "target"):
        endpoint = raw.get(side)
        if not isinstance(endpoint, dict) or set(endpoint) != set(ClockEndpoint.__annotations__):
            return False
        if any(not isinstance(endpoint[k], str) or not endpoint[k] for k in _IDENTITY_FIELDS):
            return False
        if type(endpoint["resolution_us"]) is not int or endpoint["resolution_us"] < 0:
            return False
    for key in _ENDPOINT_OVERRIDES & raw.keys():
        if not isinstance(raw[key], str) or not raw[key]:
            return False
    for key in ClockGuardrails.__annotations__:
        value = guardrails.get(key)
        if type(value) is not int or value < 0:
            return False
    for key in ("valid_sample_count", "mapping_segment_age_us", "wall_step_us"):
        if key in raw and (type(raw[key]) is not int or (
            key != "wall_step_us" and cast(int, raw[key]) < 0
        )):
            return False
    if "proven_mapping" in raw and type(raw["proven_mapping"]) is not bool:
        return False
    if "eligible_target_intervals" in raw:
        intervals = raw["eligible_target_intervals"]
        if not isinstance(intervals, list) or not intervals:
            return False
        for interval in intervals:
            if (not isinstance(interval, list) or len(interval) != 2
                    or any(type(item) is not int for item in interval)):
                return False
    return True


def derive_clock_mapping(
    raw: RawClockInput | Mapping[str, object], guardrails: ClockGuardrails | Mapping[str, object],
) -> ClockEvaluation:
    """Derive from validated raw evidence only; never accept expected or derived fields."""
    if not _valid_input(raw, guardrails):
        return _result("E_INVALID_RAW_CLOCK_INPUT")
    sample, limits = cast(RawClockInput, raw), cast(ClockGuardrails, guardrails)
    source, target = sample["source"], sample["target"]
    t1, t2, t3, t4 = (sample["t1"], sample["t2"], sample["t3"], sample["t4"])
    if t3 < t2:
        return _result("E_NEGATIVE_TARGET_ORDER")
    if t4 < t1:
        return _result("E_NEGATIVE_SOURCE_ORDER")
    raw_lower, raw_upper = t3 - t4, t2 - t1
    rtt = (t4 - t1) - (t3 - t2)
    padding = source["resolution_us"] + target["resolution_us"]
    actual = _result("ACCEPT", raw_lower, raw_upper, rtt, padding,
                     raw_lower - padding, raw_upper + padding)
    if rtt < 0:
        return _reject(actual, "E_NEGATIVE_NETWORK_RTT")
    endpoints = (("t1", source), ("t4", source), ("t2", target), ("t3", target))
    for times, endpoint, error in (
        (("t1", "t4"), source, "E_SOURCE_DOMAIN_MISMATCH"),
        (("t2", "t3"), target, "E_TARGET_DOMAIN_MISMATCH"),
    ):
        if any(raw.get(f"{t}_clock_domain_id", endpoint["clock_domain_id"])
               != endpoint["clock_domain_id"] for t in times):
            return _reject(actual, error)
    if any(raw.get(f"{t}_boot_id", e["boot_id"]) != e["boot_id"] for t, e in endpoints):
        return _reject(actual, "E_BOOT_MISMATCH")
    if any(e["unit"] != "MICROSECOND" or raw.get(f"{t}_unit", e["unit"]) != "MICROSECOND"
           for t, e in endpoints):
        return _reject(actual, "E_UNIT_NOT_MICROSECOND")
    if any(raw.get(f"{t}_owner", e["owner"]) != e["owner"] for t, e in endpoints):
        return _reject(actual, "E_TIMESTAMP_OWNER_MISMATCH")
    if rtt > limits["max_network_rtt_us"]:
        return _reject(actual, "E_MAX_NETWORK_RTT_EXCEEDED")
    if actual["base_uncertainty_us"] > limits["max_base_uncertainty_us"]:
        return _reject(actual, "E_MAX_BASE_UNCERTAINTY_EXCEEDED")
    if sample.get("valid_sample_count", limits["minimum_valid_samples"]) < limits[
        "minimum_valid_samples"
    ]:
        return _reject(actual, "E_MINIMUM_VALID_SAMPLES")
    if sample.get("mapping_segment_age_us", 0) > limits["max_mapping_segment_age_us"]:
        return _reject(actual, "E_MAX_MAPPING_SEGMENT_AGE")
    if abs(sample.get("wall_step_us", 0)) > limits["wall_step_tolerance_us"]:
        return _reject(actual, "E_WALL_STEP_TOLERANCE")
    intervals = sample.get("eligible_target_intervals")
    if intervals and max(i[0] for i in intervals) > min(i[1] for i in intervals):
        return _reject(actual, "E_INCONSISTENT_MAPPING")
    if sample.get("proven_mapping") is False or (
        source["owner"] == "CDP_BROWSER" and sample.get("proven_mapping") is not True
    ):
        return _reject(actual, "SOURCE_AGE_UNKNOWN")
    return actual


def validate_stored_mapping(
    stored: Mapping[str, object], raw: RawClockInput | Mapping[str, object],
    guardrails: ClockGuardrails | Mapping[str, object],
) -> ClockEvaluation:
    """Check supplied stored assertions against raw recomputation, retaining raw diagnostics.

    MAP-NEG-09/10/11 are SERIALIZED_MAPPING_VALIDATION: their frozen errors describe
    invalid stored intervals/RTT/radius. Other numeric mismatches reject as corruption.
    Raw sample rejection always prevents a stored value from making it eligible.
    """
    actual = derive_clock_mapping(raw, guardrails)
    if not actual["accepted"]:
        return actual
    if not stored or set(stored) - _STORED_FIELDS:
        return _reject(actual, "E_STORED_MAPPING_MISMATCH")
    expected: dict[str, object] = dict(actual)
    expected.update(offset_lower_us=actual["offset_interval_us"][0],
                    offset_upper_us=actual["offset_interval_us"][1])
    for key, value in stored.items():
        if key == "offset_interval_us":
            if (not isinstance(value, list) or len(value) != 2
                    or any(type(item) is not int for item in value)):
                return _reject(actual, "E_STORED_MAPPING_MISMATCH")
        elif type(value) is not type(expected[key]):
            return _reject(actual, "E_STORED_MAPPING_MISMATCH")
    lower = cast(int, stored.get("offset_lower_us", actual["offset_interval_us"][0]))
    upper = cast(int, stored.get("offset_upper_us", actual["offset_interval_us"][1]))
    interval = cast(list[int], stored.get("offset_interval_us", [lower, upper]))
    if lower > upper or interval[0] > interval[1]:
        return _reject(actual, "E_INVERTED_OFFSET_INTERVAL")
    limits = cast(ClockGuardrails, guardrails)
    if cast(int, stored.get("network_rtt_us", 0)) > limits["max_network_rtt_us"]:
        return _reject(actual, "E_MAX_NETWORK_RTT_EXCEEDED")
    if cast(int, stored.get("base_uncertainty_us", 0)) > limits["max_base_uncertainty_us"]:
        return _reject(actual, "E_MAX_BASE_UNCERTAINTY_EXCEEDED")
    if any(value != expected[key] for key, value in stored.items()):
        return _reject(actual, "E_STORED_MAPPING_MISMATCH")
    return actual


def evaluate_clock_mapping_vector(
    vector: Mapping[str, object], guardrails: Mapping[str, object],
) -> ClockEvaluation:
    """Verification-only legacy adapter. IDs/expected metadata never affect computation.

    Golden and MAP-NEG-01..08/12..16 use RAW_SAMPLE; MAP-NEG-09..11 use the
    separate stored validator. The source_owner alias belongs only to legacy fixtures.
    """
    stored = {k: v for k, v in vector.items() if k in _STORED_FIELDS}
    raw = {k: v for k, v in vector.items()
           if k not in _STORED_FIELDS | {"id", "expected", "source_owner"}}
    if "source_owner" in vector and isinstance(raw.get("source"), dict):
        raw["source"] = {**cast(dict[str, object], raw["source"]), "owner": vector["source_owner"]}
    return (validate_stored_mapping(stored, raw, guardrails) if stored
            else derive_clock_mapping(raw, guardrails))from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass

_CLOSURE_REASONS = frozenset(
    {
        "DOMAIN_BOOT_CHANGED",
        "MONOTONIC_REGRESSION",
        "WALL_CLOCK_STEP",
        "SLEEP_RESUME",
        "MAX_DURATION",
        "RTT_EXCEEDED",
        "UNCERTAINTY_EXCEEDED",
        "INCONSISTENT_MAPPING",
        "LIFECYCLE_INVALIDATED",
        "RUN_CLOSED",
    }
)


@dataclass(frozen=True)
class MappingClosure:
    mapping_id: str
    reason: str
    permanent: bool = True
    reopen_permitted: bool = False


class ClockMapper:
    def select(
        self,
        candidates: Iterable[Mapping[str, object]],
        history: Sequence[MappingClosure] = (),
    ) -> Mapping[str, object]:
        closed = {closure.mapping_id for closure in history}
        eligible = [
            candidate for candidate in candidates if candidate.get("mapping_id") not in closed
        ]
        for candidate in eligible:
            mapping_id = candidate.get("mapping_id")
            width = candidate.get("width_us")
            valid_from = candidate.get("valid_from_us")
            if (
                not isinstance(mapping_id, str)
                or not mapping_id
                or type(width) is not int
                or width < 0
                or type(valid_from) is not int
                or valid_from < 0
            ):
                raise ValueError("E_INVALID_MAPPING_CANDIDATE")
        if not eligible:
            raise ValueError("E_NO_VALID_MAPPING")
        return min(
            eligible,
            key=lambda candidate: (
                candidate["width_us"],
                -candidate["valid_from_us"],  # type: ignore[operator]
                candidate["mapping_id"],
            ),
        )

    def close(
        self,
        mapping_id: str,
        reason: str,
        history: Sequence[MappingClosure] = (),
    ) -> tuple[MappingClosure, ...]:
        if not mapping_id or reason not in _CLOSURE_REASONS:
            raise ValueError("E_INVALID_MAPPING_CLOSURE")
        if any(closure.mapping_id == mapping_id for closure in history):
            raise ValueError("E_MAPPING_PERMANENTLY_CLOSED")
        return (*history, MappingClosure(mapping_id, reason))

    def reopen(self, mapping_id: str, history: Sequence[MappingClosure]) -> None:
        if any(closure.mapping_id == mapping_id for closure in history):
            raise ValueError("E_MAPPING_PERMANENTLY_CLOSED")
        raise ValueError("E_NO_VALID_MAPPING")import re
from collections.abc import Mapping

_TRANSITIONS = {
    ("OPEN", "SHOCK_ATOMIC_CLOSE"): "SHOCKED_CLOSED",
    ("NEW_EPOCH_OPEN", "SHOCK_ATOMIC_CLOSE"): "SHOCKED_CLOSED",
    ("SHOCKED_CLOSED", "CLOSE_RECORDED"): "WAITING_FOR_RESNAPSHOT",
    ("WAITING_FOR_RESNAPSHOT", "RESNAPSHOT_CANDIDATE_ACCEPTED"): "NEW_EPOCH_PENDING",
    ("NEW_EPOCH_PENDING", "RELEASE_PREDICATE_SATISFIED"): "NEW_EPOCH_OPEN",
    ("NEW_EPOCH_PENDING", "NEW_SHOCK_CLOSED_CANDIDATE"): "WAITING_FOR_RESNAPSHOT",
}


def _rejected(error: str, state: str) -> dict[str, object]:
    return {"accepted": False, "error": error, "state": state}


def _valid_artifact_id(value: object) -> bool:
    return (
        isinstance(value, str)
        and re.fullmatch(r"[A-Z][A-Z0-9_]*:[0-9a-f]{64}", value) is not None
    )


class CoherenceController:
    def transition(self, state: str, reason: str) -> str:
        try:
            return _TRANSITIONS[state, reason]
        except KeyError as exc:
            raise ValueError("E_INVALID_COHERENCE_TRANSITION") from exc

    def accept_candidate(self, value: Mapping[str, object]) -> dict[str, object]:
        required = (
            value.get("controller_state") == "WAITING_FOR_RESNAPSHOT",
            value.get("proof_status") == "OBSERVED",
            value.get("proof_verified") is True,
            value.get("release_predicate") == "SATISFIED",
            value.get("predecessor_permanently_closed") is True,
            value.get("candidate_distinct_from_predecessor") is True,
            value.get("freshness_binding_verified") is True,
            value.get("shock_binding_verified") is True,
            value.get("mapping_bindings_verified") is True,
            value.get("continuity_bindings_verified") is True,
        )
        if not all(required):
            return _rejected("E_RESNAPSHOT_CANDIDATE_BINDING", "WAITING_FOR_RESNAPSHOT")
        return {"accepted": True, "error": "ACCEPT", "state": "NEW_EPOCH_PENDING"}

    def evaluate_release(self, value: Mapping[str, object]) -> dict[str, object]:
        if value.get("predecessor_reopen_requested") is True:
            return _rejected("E_PREDECESSOR_EPOCH_IMMUTABLE", "CLOSED_FOREVER")
        if value.get("controller_state") != "NEW_EPOCH_PENDING":
            return _rejected("E_INVALID_COHERENCE_TRANSITION", "NEW_EPOCH_PENDING")
        predecessor_id = value.get("predecessor_epoch_id")
        candidate_id = value.get("candidate_epoch_id")
        if (
            value.get("candidate_created") is not True
            or not _valid_artifact_id(predecessor_id)
            or not _valid_artifact_id(candidate_id)
        ):
            return _rejected("E_RELEASE_BINDING", "NEW_EPOCH_PENDING")
        if candidate_id == predecessor_id:
            return _rejected("E_INVALID_COHERENCE_TRANSITION", "NEW_EPOCH_PENDING")
        if value.get("predecessor_permanently_closed") is not True:
            return _rejected("E_NON_GENESIS_PREDECESSOR_NOT_CLOSED", "WAITING_FOR_RESNAPSHOT")
        if value.get("predecessor_closed") is not True:
            return _rejected("E_PREDECESSOR_NOT_CLOSED", "WAITING_FOR_RESNAPSHOT")
        if value.get("signed_accepted_capability_evidence") is not True:
            return _rejected("E_CAPABILITY_EVIDENCE_NOT_ACCEPTED", "WAITING_FOR_RESNAPSHOT")
        if value.get("proof_status") == "NOT_OBSERVED":
            return _rejected("E_RESNAPSHOT_NOT_OBSERVED", "WAITING_FOR_RESNAPSHOT")
        if value.get("proof_status") != "OBSERVED" or value.get("proof_verified") is not True:
            return _rejected("E_RESNAPSHOT_UNKNOWN", "WAITING_FOR_RESNAPSHOT")
        if value.get("snapshot_semantics") != "FULL_AUTHORITATIVE_SNAPSHOT":
            return _rejected("E_RESNAPSHOT_NOT_OBSERVED", "WAITING_FOR_RESNAPSHOT")
        checks = (
            (value.get("football_state") == "FRESH", "E_FOOTBALL_STATE_NOT_FRESH"),
            (value.get("operator_state") == "FRESH", "E_OPERATOR_STATE_NOT_FRESH"),
            (value.get("market_book") == "FRESH_COMPLETE_OPEN", "E_MARKET_BOOK_NOT_COMPLETE_OPEN"),
            (value.get("conservative_lower_bounds_strictly_after_shock_upper") is True,
             "E_NOT_STRICTLY_POST_SHOCK"),
            (value.get("proof_bound_mappings_open_unclosed_valid_at_release") is True,
             "E_MAPPING_CLOSED"),
            (value.get("mappings_valid") is True, "E_MAPPING_CLOSED"),
            (value.get("identities_orientation_generations_agree") is True,
             "E_IDENTITY_OR_GENERATION_MISMATCH"),
            (value.get("cursor_ranges_contiguous") is True, "E_CURSOR_NOT_CONTIGUOUS"),
        )
        for passed, error in checks:
            if not passed:
                return _rejected(error, "NEW_EPOCH_PENDING")
        blocker_absent = value.get(
            "gap_conflict_schema_lifecycle_mapping_or_later_shock_absent"
        )
        if blocker_absent is not True:
            if value.get("blocker") == "LATER_OR_INTERSECTING_SHOCK":
                return _rejected("E_CANDIDATE_CLOSED_BY_NEW_SHOCK", "WAITING_FOR_RESNAPSHOT")
            return _rejected("E_RELEASE_BLOCKED", "NEW_EPOCH_PENDING")
        if value.get("score_period_suspension_and_shock_fields_agree") is not True:
            return _rejected("E_STATE_FIELDS_DISAGREE", "NEW_EPOCH_PENDING")
        if (
            value.get("freshness_bindings_valid_at_release") is not True
            or value.get("continuity_bindings_valid_at_release") is not True
            or value.get("proof_bindings_valid") is not True
        ):
            return _rejected("E_RELEASE_BINDING", "NEW_EPOCH_PENDING")
        return {
            "accepted": True,
            "error": "ACCEPT",
            "state": "NEW_EPOCH_OPEN",
            "predecessor_state": "CLOSED_FOREVER",
            "successor_distinct": True,
        }from .errors import ContractNotImplementedError


