from .live_replay import file_hash

RunRef = Path
QualityView = dict[str, Any]
DataManifest = dict[str, Any]


def freeze_dataset_manifest(run_refs: Sequence[RunRef], quality_view: QualityView) -> DataManifest:
    from tools.qualify_live_readonly import qualify_recorded_run

    required = {"selection_basis", "historical_data", "chronological_partitions"}
    if (
        type(quality_view) is not dict
        or not required <= set(quality_view) <= required | {"data_rights_refs"}
        or quality_view["selection_basis"] != "DATA_QUALITY_ONLY"
        or quality_view["historical_data"] not in {"NOT_SUPPLIED", "PARTIAL", "PRESENT"}
        or len(run_refs) > 100
        or len(set(run_refs)) != len(run_refs)
    ):
        raise ValueError("E_DATA_MANIFEST_INPUT")
    partitions = quality_view["chronological_partitions"]
    if type(partitions) is not list or len(partitions) > 3:
        raise ValueError("E_DATA_MANIFEST_PARTITIONS")
    last = None
    for index, part in enumerate(partitions):
        if (
            set(part) != {"name", "start", "end"}
            or part["name"] != ("TRAIN", "VALIDATION", "TEST")[index]
        ):
            raise ValueError("E_DATA_MANIFEST_PARTITIONS")
        start, end = date.fromisoformat(part["start"]), date.fromisoformat(part["end"])
        if start >= end or last is not None and start < last:
            raise ValueError("E_DATA_MANIFEST_PARTITIONS")
        last = end
    rights = []
    for ref in quality_view.get("data_rights_refs", []):
        if set(ref) != {"source", "path", "sha256"} or ref["source"] not in {
            "API_FOOTBALL",
            "MISE_O_JEU",
        }:
            raise ValueError("E_DATA_MANIFEST_RIGHTS")
        path = Path(ref["path"])
        if (
            not path.is_absolute()
            or not path.is_file()
            or any(p.is_symlink() for p in (path, *path.parents))
            or path.stat().st_size > 65536
            or file_hash(path) != ref["sha256"]
        ):
            raise ValueError("E_DATA_MANIFEST_RIGHTS")
        record = json.loads(path.read_bytes())
        if (
            set(record) != {"source", "status", "uses", "reviewer_role", "reviewed_at_utc"}
            or record["source"] != ref["source"]
            or record["status"] not in {"ACCEPTED", "REVIEW_REQUIRED"}
            or record["uses"] != ["LOCAL_RECORDING", "RESEARCH"]
            or record["reviewer_role"] != "USER_DATA_ACCESS_REVIEW"
            or datetime.fromisoformat(record["reviewed_at_utc"]) > datetime.now(UTC)
        ):
            raise ValueError("E_DATA_MANIFEST_RIGHTS")
        rights.append({**ref, "status": record["status"]})
    if len(rights) > 2 or len({r["source"] for r in rights}) != len(rights):
        raise ValueError("E_DATA_MANIFEST_RIGHTS")
    rows, targets, qualifications = [], [], []
    for run in run_refs:
        qualified = qualify_recorded_run(run)
        qualifications.append(qualified)
        database = run.absolute() / "live.sqlite3"
        with closing(sqlite3.connect(database.as_uri() + "?mode=ro", uri=True)) as db:
            db.execute("PRAGMA query_only=ON")
            events = [
                json.loads(row[0])
                for row in db.execute(
                    "SELECT payload_canonical FROM live_events ORDER BY receive_index"
                )
            ]
        provider = [e["payload"] for e in events if e["payload_type"] == "ProviderState"]
        bindings = [e["payload"]["after"] for e in events if e["payload_type"] == "BindingChange"]
        rows.append(
            {
                "run_id": qualified["run_id"],
                "source_kind": qualified["source_kind"],
                "identity": [
                    {
                        k: b[k]
                        for k in (
                            "provider_fixture_id",
                            "league_id",
                            "season",
                            "home_id",
                            "away_id",
                            "kickoff_utc",
                        )
                    }
                    for b in bindings
                ],
                "coverage": {
                    "event_count": len(events),
                    "provider_observations": len(provider),
                    "ft_comparisons": qualified["complete_ft_book_checks"],
                },
                "timing": {
                    "first_receipt_utc": events[0]["observed_at_utc"] if events else None,
                    "last_receipt_utc": events[-1]["observed_at_utc"] if events else None,
                    "source_age": "UNKNOWN_UNLESS_SOURCE_TIMESTAMP_OBSERVED",
                },
                "corrections_and_quality_flags": dict(
                    Counter(flag for state in provider for flag in state["quality_flags"])
                ),
                "missingness": qualified["missing_inputs"],
                "quota": {"real_http_attempts": qualified["real_http_attempts"]},
                "cost": "UNKNOWN",
                "settlement": {
                    "FT": "NORMAL_TIME_INCLUDING_STOPPAGE",
                    "H1": "NOT_QUALIFIED",
                    "H2": "NOT_QUALIFIED",
                },
            }
        )
        if file_hash(database) != qualified["artifacts"]["live.sqlite3"]:
            raise ValueError("E_DATA_MANIFEST_SOURCE_CHANGED")
        targets.append(
            {
                "path": str(database),
                "sha256": file_hash(database),
                "content": "RECORDED_OBSERVATIONS_ONLY_NOT_SETTLED_OUTCOME_LABELS",
            }
        )
    accepted = len(rights) == 2 and all(r["status"] == "ACCEPTED" for r in rights)
    result: DataManifest = {
        "schema_version": "part-b-data-manifest/v1",
        "has_source_provenance": bool(qualifications),
        "quality_view": {k: copy.deepcopy(quality_view[k]) for k in required} | {"runs": rows},
        "actual_targets": targets,
        "rights_evidence": rights,
        "data_rights": "USER_REVIEW_RECORDED" if accepted else "REVIEW_REQUIRED",
        "SCOPE0_READY_FOR_REVIEW": bool(qualifications)
        and accepted
        and all(q["LIVE_READ_ONLY_PASS"] for q in qualifications),
        "MODEL_ENABLED": False,
        "MONEY_READY": "NO",
        "PART_C_ACTIVATED": False,
    }
    return {**result, "manifest_sha256": hashlib.sha256(rfc8785.dumps(result)).hexdigest()}"""Issue the MATERIALIZED_CONTRACTS_VALID gate from sealed, materialized inputs."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

from .artifact_ownership import validate_artifact_lifecycle
from .task_contracts import validate_task_manifest_semantics


def _load(path: Path) -> dict[str, object]:
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError("E_DECLARATION_INPUT")
    return value


def _commands(registries: Path) -> list[dict[str, object]]:
    return [
        command
        for name in (
            "task-command-registry.v1.json",
            "review-command-registry.v1.json",
            "cybersecurity-command-registry.v1.json",
            "baseline-replay-command-registry.v1.json",
        )
        for command in _load(registries / name)["commands"]
    ]


def _resolve_pointer(document: object, pointer: object) -> bool:
    if not isinstance(pointer, str) or not pointer.startswith("#/"):
        return False
    value = document
    for part in pointer[2:].split("/"):
        part = part.replace("~1", "/").replace("~0", "~")
        if not isinstance(value, dict) or part not in value:
            return False
        value = value[part]
    return True


def _validate_schema_references(plan_root: Path) -> int:
    references = _load(
        plan_root / "docs/registries/schema-reference-registry.v1.json"
    )["references"]
    if not isinstance(references, list):
        raise ValueError("E_SCHEMA_REFERENCE")
    seen: set[str] = set()
    for reference in references:
        if not isinstance(reference, dict):
            raise ValueError("E_SCHEMA_REFERENCE")
        logical_name = reference.get("logical_name")
        relative = reference.get("plan_source_path")
        pointer = reference.get("json_pointer")
        if (
            not isinstance(logical_name, str)
            or not isinstance(relative, str)
            or not relative.startswith("pack/docs/")
            or logical_name in seen
        ):
            raise ValueError("E_SCHEMA_REFERENCE")
        schema = _load(plan_root / relative.removeprefix("pack/"))
        if not _resolve_pointer(schema, pointer):
            raise ValueError("E_SCHEMA_POINTER")
        seen.add(logical_name)
    return len(seen)


def issue_declaration_complete_receipt(plan_root: Path) -> dict[str, object]:
    """Return a MATERIALIZED_CONTRACTS_VALID receipt without creating future evidence."""
    registry_root = plan_root / "docs/registries"
    ownership = _load(registry_root / "artifact-ownership.v1.json")
    manifest = _load(plan_root / "docs/tasks/task-manifest.v6.3.6.json")
    schema = _load(plan_root / "docs/schemas/artifact-ownership.schema.json")
    commands = _commands(registry_root)
    owned = {entry["path"] for entry in ownership["entries"]}
    validate_task_manifest_semantics(manifest, commands, owned)
    validate_artifact_lifecycle(
        ownership,
        manifest,
        authoring_root=Path(__file__).resolve().parents[3],
        schema=schema,
    )
    schema_reference_count = _validate_schema_references(plan_root)
    payload = {
        "schema_version": "materialized-contracts-valid/v1",
        "gate": "MATERIALIZED_CONTRACTS_VALID",
        "result": "PASS",
        "task_count": len(manifest["tasks"]),
        "artifact_count": len(ownership["entries"]),
        "command_count": len({command["command_id"] for command in commands}),
        "schema_reference_count": schema_reference_count,
        "authorized_production_phases": "NONE",
    }
    raw = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode()
    payload["content_hash"] = hashlib.sha256(
        b"HD636/MATERIALIZED-CONTRACTS/v1\0" + raw
    ).hexdigest()
    return payload"""Static escaped accounting diagnostics, never observed match data."""

from html import escape
from typing import Any


def render_diagnostic(result: dict[str, Any]) -> str:
    if (
        result.get("verified") is not True
        or result.get("source_kind") != "SYNTHETIC_TEST"
        or result.get("production_authority") != "NONE"
        or result.get("MONEY_READY") != "NO"
        or not isinstance(result.get("cases"), list)
    ):
        raise ValueError("E_OFFLINE_UNVERIFIED_DIAGNOSTIC")

    def text(value: object) -> str:
        return escape("UNKNOWN" if value is None else str(value), quote=True)

    rows = "".join(
        "<tr>"
        + "".join(
            "<td>" + text(case.get(field)) + "</td>"
            for field in (
                "case_id",
                "actual_count",
                "highest_sequence",
                "ack",
                "gap_count",
                "replay",
                "reason",
            )
        )
        + "</tr>"
        for case in result["cases"]
    )
    return (
        '<!doctype html><html lang="en"><meta charset="utf-8">'
        '<meta http-equiv="Content-Security-Policy" content="'
        "default-src 'none'; style-src 'unsafe-inline'\">"
        "<title>Synthetic offline accounting</title><style>"
        "body{font:16px system-ui;margin:2rem;max-width:80rem}"
        "table{border-collapse:collapse}"
        "th,td{padding:.5rem;border:1px solid #aaa;text-align:left}</style>"
        "<body><h1>SYNTHETIC ONLY</h1><p>No observed match data.</p><p>Offline slice: "
        + text(result.get("OFFLINE_SLICE_PASS"))
        + "</p><p>Run: "
        + text(result.get("run_id"))
        + "</p><p>Source revision: "
        + text(result.get("code_revision"))
        + "</p><p>Source age: UNKNOWN</p><table><thead><tr><th>Case</th><th>Committed rows</th>"
        "<th>Highest sequence</th><th>ACK</th><th>Gaps</th>"
        "<th>Replay</th><th>Reason</th></tr></thead>"
        "<tbody>"
        + rows
        + "</tbody></table><p>Live read-only: PENDING_REAL_INPUTS_AND_LIVE_REVIEW</p>"
        "<p>Money ready: NO · Production authority: NONE</p></body></html>"
    )"""Closed process-crash vector mapping validation."""
from __future__ import annotations


def validate_crash_harness_registry(
    registry: dict[str, object],
    child_registry: dict[str, object],
    vectors: dict[str, object],
) -> dict[str, object]:
    entries = registry.get("entries")
    cases = vectors.get("cases")
    children = child_registry.get("entries")
    if not isinstance(entries, list) or not isinstance(cases, list) or not isinstance(children, list):
        raise ValueError("E_CRASH_REGISTRY")
    source = {case.get("id"): case for case in cases if isinstance(case, dict)}
    mapped = {entry.get("vector_id"): entry for entry in entries if isinstance(entry, dict)}
    if (
        len(source) != 46
        or len(mapped) != 46
        or len(entries) != 46
        or set(source) != set(mapped)
        or registry.get("source_case_count") != 46
        or registry.get("mapped_case_count") != 46
    ):
        raise ValueError("E_CRASH_COVERAGE")
    by_harness = {
        child.get("harness"): child
        for child in children
        if isinstance(child, dict) and isinstance(child.get("harness"), str)
    }
    if len(by_harness) != 5 or len(children) != 5:
        raise ValueError("E_CRASH_CHILD")
    for vector_id, case in source.items():
        if not isinstance(vector_id, str):
            raise ValueError("E_CRASH_COVERAGE")
        entry = mapped[vector_id]
        if (
            entry.get("source_case_index") != cases.index(case)
            or entry.get("source_boundary") != case.get("boundary")
            or entry.get("kill_action") != case.get("kill")
            or entry.get("expected_post_restart_state") != case.get("expected")
            or entry.get("harness") not in by_harness
            or not isinstance(entry.get("child_command_id"), str)
            or not entry["child_command_id"].startswith("CRASH_VECTOR_")
            or not isinstance(entry.get("crash_checkpoint"), str)
            or not entry["crash_checkpoint"].strip()
            or not isinstance(entry.get("owner_task"), str)
            or not entry["owner_task"].startswith("V636-P03-T")
            or not isinstance(entry.get("verification_command_id"), str)
            or not entry["verification_command_id"].startswith("TEST_V636_P03_T")
        ):
            raise ValueError("E_CRASH_CHILD")
    return {"result": "PASS", "case_count": 46, "harness_count": len(by_harness)}"""Release gate for completely executed process-level durability vectors."""
