import sqlite3
from contextlib import closing
from time import time_ns
from typing import Any

from .canonical import canonical_content_hash, verify_canonical_content_hash
from .errors import ContractNotImplementedError
from .schema_registry import validate_artifact
from .store import VENDOR, RunStore, read_journal, validate_journal

# The inherited DDL/schema select one universal H0, not a per-identity seed.
H0 = "149300a0e3954885a1d6c0f13a9d1101227cc21cce37bd6b7c72eab641741c0c"
REGISTRY = VENDOR / "registries/canonical-hash-domains.v1.json"
POSITION = "run_id=? AND browser_run_id=? AND producer_id=? AND stream_id=? AND generation=?"


def _integer(value: str) -> int:
    parsed = int(value)
    if not 0 <= parsed <= 9223372036854775807:
        raise ValueError("E_INGEST_INTEGER_RANGE")
    return parsed


class Ingestor:
    def __init__(self, store: RunStore) -> None:
        self.store = store

    def apply(self, observation: dict[str, Any]) -> dict[str, Any]:
        validate_artifact(
            observation, "raw-observation.schema.json", bootstrap_only=True, vendor=VENDOR
        )
        verify_canonical_content_hash(
            "RawObservation", observation, observation["content_hash"], registry_path=REGISTRY
        )
        # Lifecycle/GAP observations require semantic handlers beyond this journal.
        if observation["observation_kind"] in {"LIFECYCLE", "GAP"}:
            raise ContractNotImplementedError("F0A-T04:OBSERVATION_SEMANTICS")
        run = observation["discovery_run_id"]
        browser = observation["context"]["browser_run_id"]
        stream = observation["stream_id"]
        generation, sequence = (_integer(observation[key]) for key in ("generation", "sequence"))
        content_hash = observation["content_hash"]
        now = time_ns() // 1000
        rejected: str | None = None
        ack: dict[str, Any] = {}
        with closing(self.store.connect()) as connection, connection:
            connection.execute("BEGIN IMMEDIATE")
            validate_journal(read_journal(connection, ordered=False))
            meta = connection.execute("SELECT * FROM run_meta").fetchall()
            if len(meta) != 1 or (
                meta[0]["run_id"] != run
                or meta[0]["run_status"] != "OPEN"
                or meta[0]["pack_hash"] != observation["pack_hash"]
                or meta[0]["build_hash"] != observation["build_hash"]
            ):
                raise ValueError("E_INGEST_RUN_BINDING")
            generations = connection.execute(
                "SELECT * FROM stream_generations WHERE run_id=? AND browser_run_id=? "
                "AND stream_id=? AND generation=?",
                (run, browser, stream, generation),
            ).fetchall()
            if len(generations) != 1:
                raise ValueError("E_INGEST_GENERATION_BINDING")
            current = generations[0]
            if current["generation_state"] != "ACTIVE":
                raise ValueError("E_INGEST_GENERATION_CLOSED")
            key = (run, browser, current["producer_id"], stream, generation)
            if (
                connection.execute(
                    f"SELECT 1 FROM raw_conflicts WHERE {POSITION} LIMIT 1",  # noqa: S608
                    key,
                ).fetchone()
                is not None
            ):
                raise ValueError("E_INGEST_CONFLICT")
            raw = connection.execute(
                f"SELECT * FROM raw_commits WHERE {POSITION} AND sequence=?",  # noqa: S608
                (*key, sequence),
            ).fetchone()
            previous = connection.execute(
                f"SELECT * FROM reducer_cursors WHERE {POSITION} "  # noqa: S608
                "ORDER BY highest_contiguous_sequence DESC LIMIT 1",
                key,
            ).fetchone()
            highest = 0 if previous is None else previous["highest_contiguous_sequence"]
            if raw is not None and raw["raw_observation_content_hash"] == content_hash:
                row = connection.execute(
                    f"SELECT * FROM ack_outbox WHERE {POSITION} "  # noqa: S608
                    "AND highest_contiguous_sequence=?",
                    (*key, sequence),
                ).fetchone()
                if row is None:
                    raise ValueError("E_INGEST_INCOMPLETE_DURABLE_CHAIN")
                ack = dict(row)
            elif raw is not None or sequence != highest + 1:
                if sequence <= highest and raw is None:
                    raise ValueError("E_INGEST_INCOMPLETE_DURABLE_CHAIN")
                if raw is not None:
                    connection.execute(
                        "INSERT INTO raw_conflicts VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                        (
                            "conflict:" + content_hash,
                            raw["raw_commit_id"],
                            *key,
                            sequence,
                            observation["raw_observation_id"],
                            content_hash,
                            now,
                        ),
                    )
                    self._gap(
                        connection,
                        current,
                        highest,
                        sequence,
                        content_hash,
                        now,
                        "CONFLICTING_DUPLICATE",
                    )
                    rejected = "E_INGEST_CONFLICT"
                else:
                    self._gap(
                        connection,
                        current,
                        highest,
                        sequence,
                        content_hash,
                        now,
                        "MISSING_SEQUENCE",
                    )
                    rejected = "E_INGEST_GAP"
            else:
                prior_hash = H0 if previous is None else previous["cursor_hash"]
                cursor = canonical_content_hash(
                    "CursorStep",
                    {
                        "schema_version": "cursor-step/v1",
                        "discovery_run_id": run,
                        "browser_run_id": browser,
                        "producer_id": current["producer_id"],
                        "stream_id": stream,
                        "generation": str(generation),
                        "sequence": str(sequence),
                        "raw_observation_hash": content_hash,
                        "previous_cursor_hash": prior_hash,
                    },
                    registry_path=REGISTRY,
                )
                raw_id, application_id, revision_id, reducer_id, outbox_id = (
                    prefix + ":" + cursor
                    for prefix in ("raw", "application", "revision", "cursor", "ack")
                )
                connection.execute(
                    "INSERT INTO raw_commits VALUES (?,?,?,?,?,?,?,?,?,?,?,1,'APPLIED',?)",
                    (
                        raw_id,
                        *key,
                        sequence,
                        observation["raw_observation_id"],
                        content_hash,
                        prior_hash,
                        cursor,
                        now,
                    ),
                )
                connection.execute(
                    "INSERT INTO application_records VALUES (?,?,?,?,?,?,?,?,?,?,'APPLIED',?)",
                    (application_id, raw_id, *key, sequence, content_hash, prior_hash, now),
                )
                # Journal revision = the committed input-chain digest. No domain state is inferred.
                connection.execute(
                    "INSERT INTO derived_revisions VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    (
                        revision_id,
                        application_id,
                        raw_id,
                        *key,
                        sequence,
                        sequence,
                        None if previous is None else prior_hash,
                        cursor,
                        now,
                    ),
                )
                connection.execute(
                    "INSERT INTO reducer_cursors VALUES (?,?,?,?,?,?,?,?,?,?,1,?,?)",
                    (
                        reducer_id,
                        revision_id,
                        *key,
                        sequence,
                        prior_hash,
                        cursor,
                        content_hash,
                        now,
                    ),
                )
                connection.execute(
                    "INSERT INTO ack_outbox VALUES (?,?,?,?,?,?,?,?,?,?,?,?,1,?)",
                    (
                        outbox_id,
                        raw_id,
                        application_id,
                        revision_id,
                        reducer_id,
                        *key,
                        sequence,
                        cursor,
                        now,
                    ),
                )
                ack = dict(
                    connection.execute(
                        "SELECT * FROM ack_outbox WHERE ack_outbox_id=?", (outbox_id,)
                    ).fetchone()
                )
        # The connection context has committed, including deferred constraints, before return.
        if rejected is not None:
            raise ValueError(rejected)
        return ack

    def confirm_ack(self, ack: dict[str, Any]) -> dict[str, Any]:
        """Persist an idempotent confirmation only for the exact durable outbox ACK."""
        with closing(self.store.connect()) as connection, connection:
            connection.execute("BEGIN IMMEDIATE")
            validate_journal(read_journal(connection, ordered=False))
            durable = connection.execute(
                "SELECT * FROM ack_outbox WHERE ack_outbox_id=?", (ack.get("ack_outbox_id"),)
            ).fetchone()
            if durable is None or dict(durable) != ack:
                raise ValueError("E_ACK_CONFIRMATION_BINDING")
            key = tuple(
                ack[name]
                for name in (
                    "run_id",
                    "browser_run_id",
                    "producer_id",
                    "stream_id",
                    "generation",
                )
            )
            previous = connection.execute(
                f"SELECT * FROM ack_cursors WHERE {POSITION} AND owner='BACKEND' "  # noqa: S608
                "ORDER BY highest_contiguous_sequence DESC LIMIT 1",
                key,
            ).fetchone()
            if previous is not None:
                if previous["highest_contiguous_sequence"] > ack["highest_contiguous_sequence"]:
                    raise ValueError("E_ACK_CONFIRMATION_REGRESSION")
                if previous["highest_contiguous_sequence"] == ack["highest_contiguous_sequence"]:
                    if previous["cursor_hash"] != ack["cursor_hash"]:
                        raise ValueError("E_ACK_CONFIRMATION_BINDING")
                    return dict(previous)
            identifier = "confirmation:" + ack["cursor_hash"]
            connection.execute(
                "INSERT INTO ack_cursors VALUES (?,?,?,?,?,?,'BACKEND',?,?,1,"
                "'BACKEND_DURABLE_CHAIN',?,?)",
                (
                    identifier,
                    *key,
                    ack["highest_contiguous_sequence"],
                    ack["cursor_hash"],
                    None if previous is None else previous["ack_cursor_id"],
                    time_ns() // 1000,
                ),
            )
            result = dict(
                connection.execute(
                    "SELECT * FROM ack_cursors WHERE ack_cursor_id=?",
                    (identifier,),
                ).fetchone()
            )
        return result

    def store_late_repair(self, observation: dict[str, Any]) -> dict[str, Any]:
        """Persist a missing predecessor row without applying or acknowledging it."""
        validate_artifact(
            observation, "raw-observation.schema.json", bootstrap_only=True, vendor=VENDOR
        )
        verify_canonical_content_hash(
            "RawObservation", observation, observation["content_hash"], registry_path=REGISTRY
        )
        run = observation["discovery_run_id"]
        browser = observation["context"]["browser_run_id"]
        producer = observation["clock_context"]["clock_domain_id"]
        stream = observation["stream_id"]
        generation, sequence = (_integer(observation[key]) for key in ("generation", "sequence"))
        now = time_ns() // 1000
        with closing(self.store.connect()) as connection, connection:
            connection.execute("BEGIN IMMEDIATE")
            validate_journal(read_journal(connection, ordered=False))
            meta = connection.execute("SELECT * FROM run_meta").fetchall()
            if len(meta) != 1 or (
                meta[0]["run_id"] != run
                or meta[0]["run_status"] != "OPEN"
                or meta[0]["pack_hash"] != observation["pack_hash"]
                or meta[0]["build_hash"] != observation["build_hash"]
            ):
                raise ValueError("E_INGEST_RUN_BINDING")
            current = connection.execute(
                "SELECT * FROM stream_generations WHERE run_id=? AND browser_run_id=? "
                "AND producer_id=? AND stream_id=? AND generation=?",
                (run, browser, producer, stream, generation),
            ).fetchone()
            if current is None or current["generation_state"] not in {"CLOSED", "QUARANTINED_GAP"}:
                raise ValueError("E_INGEST_LATE_REPAIR_BINDING")
            key = (run, browser, current["producer_id"], stream, generation)
            gap = connection.execute(
                "SELECT * FROM gap_records WHERE run_id=? AND browser_run_id=? "
                "AND producer_id=? AND stream_id=? AND predecessor_generation=? "
                "AND missing_from_sequence<=? AND missing_to_sequence>=? AND repair_status='OPEN'",
                (*key, sequence, sequence),
            ).fetchone()
            if (
                gap is None
                or connection.execute(
                    f"SELECT 1 FROM raw_commits WHERE {POSITION} AND sequence=?",  # noqa: S608
                    (*key, sequence),
                ).fetchone()
            ):
                raise ValueError("E_INGEST_LATE_REPAIR_BINDING")
            previous = connection.execute(
                f"SELECT * FROM reducer_cursors WHERE {POSITION} "  # noqa: S608
                "AND highest_contiguous_sequence<? "
                "ORDER BY highest_contiguous_sequence DESC LIMIT 1",
                (*key, sequence),
            ).fetchone()
            prior_hash = H0 if previous is None else previous["cursor_hash"]
            content_hash = observation["content_hash"]
            cursor = canonical_content_hash(
                "CursorStep",
                {
                    "schema_version": "cursor-step/v1",
                    "discovery_run_id": run,
                    "browser_run_id": browser,
                    "producer_id": current["producer_id"],
                    "stream_id": stream,
                    "generation": str(generation),
                    "sequence": str(sequence),
                    "raw_observation_hash": content_hash,
                    "previous_cursor_hash": prior_hash,
                },
                registry_path=REGISTRY,
            )
            raw_id = "late-repair:" + cursor
            connection.execute(
                "INSERT INTO raw_commits VALUES (?,?,?,?,?,?,?,?,?,?,?,1,'LATE_REPAIR_ONLY',?)",
                (
                    raw_id,
                    *key,
                    sequence,
                    observation["raw_observation_id"],
                    content_hash,
                    prior_hash,
                    cursor,
                    now,
                ),
            )
            return dict(
                connection.execute(
                    "SELECT * FROM raw_commits WHERE raw_commit_id=?", (raw_id,)
                ).fetchone()
            )

    @staticmethod
    def _gap(
        connection: sqlite3.Connection,
        current: sqlite3.Row,
        highest: int,
        sequence: int,
        digest: str,
        now: int,
        reason: str,
    ) -> None:
        controllers = connection.execute(
            "SELECT * FROM coherence_controllers WHERE run_id=?", (current["run_id"],)
        ).fetchall()
        # No stream-to-fixture mapping exists in this DDL: ambiguous multi-fixture input holds.
        if len(controllers) != 1 or controllers[0]["controller_state"] not in {
            "OPEN",
            "NEW_EPOCH_OPEN",
        }:
            raise ValueError("E_INGEST_GAP_COHERENCE_BINDING")
        controller = controllers[0]
        key = tuple(
            current[field] for field in ("run_id", "browser_run_id", "producer_id", "stream_id")
        )
        generation = current["generation"]
        gap, shock, transition, binding = (
            prefix + ":" + digest for prefix in ("gap", "shock", "transition", "binding")
        )
        conflict = reason == "CONFLICTING_DUPLICATE"
        missing_from = sequence if conflict else highest + 1
        missing_to = sequence if conflict else sequence - 1
        connection.execute(
            "INSERT INTO gap_records VALUES (?,?,?,?,?,?,?,?,?,?,?,'OPEN',?,?)",
            (
                gap,
                *key,
                generation,
                generation + 1,
                missing_from,
                missing_to,
                sequence,
                reason,
                sequence - 1 if conflict else highest,
                now,
            ),
        )
        connection.execute(
            "INSERT INTO shock_observations VALUES (?,?,?,?,?,?,?,?)",
            (
                shock,
                key[0],
                controller["fixture_id"],
                "SCHEMA_CONFLICT" if conflict else "SEQUENCE_GAP",
                now,
                now,
                digest,
                now,
            ),
        )
        connection.execute(
            "INSERT INTO coherence_transitions VALUES (?,?,?,?, 'SHOCKED_CLOSED',?,NULL,?,"
            "NULL,NULL,1,'SHOCK_ATOMIC_CLOSE',?)",
            (
                transition,
                controller["coherence_controller_id"],
                controller["fixture_id"],
                controller["controller_state"],
                controller["current_epoch_id"],
                shock,
                now,
            ),
        )
        connection.execute(
            "UPDATE coherence_controllers SET controller_state='SHOCKED_CLOSED',"
            "active_shock_observation_id=?,controller_revision=controller_revision+1,"
            "updated_at_us=? "
            "WHERE coherence_controller_id=?",
            (shock, now, controller["coherence_controller_id"]),
        )
        connection.execute(
            "INSERT INTO gap_epoch_bindings VALUES (?,?,?,?,?,?,"
            "'AFFECTED_EPOCH_PERMANENTLY_CLOSED',?)",
            (
                binding,
                gap,
                controller["current_epoch_id"],
                controller["coherence_controller_id"],
                shock,
                transition,
                now,
            ),
        )
        connection.execute(
            "UPDATE stream_generations SET generation_state=?,closed_at_us=?,"
            "close_reason=? WHERE generation_id=?",
            ("CLOSED" if conflict else "QUARANTINED_GAP", now, reason, current["generation_id"]),
        )
        connection.execute(
            "INSERT INTO generation_transitions VALUES (?,?,?,?,?,?,?,?,?,?)",
            (
                "generation-transition:" + digest,
                gap,
                *key,
                generation,
                generation + 1,
                "CONFLICT" if conflict else "GAP",
                now,
            ),
        )
        connection.execute(
            "INSERT INTO stream_generations VALUES (?,?,?,?,?,?,?,'ACTIVE',?,NULL,NULL)",
            ("generation:" + digest, *key, generation + 1, generation, now),
        )"""Durable sanitized delivery evidence alongside the shared ingest journal."""

import copy
import hashlib
import os
import re
import sqlite3
import stat
from collections.abc import Callable, Iterator
from contextlib import closing
from pathlib import Path
from typing import Any, cast
from uuid import uuid4

import rfc8785

from .canonical import parse_strict_json
from .ingest import Ingestor
from .offline_protocol import validate_context
from .store import RunStore, read_journal, validate_journal
from .synthetic_source import validate_synthetic_observation

DOMAIN = b"BH-OFFLINE-JOURNAL/v1\0"
HEX = re.compile(r"^[0-9a-f]{64}$")
UUID = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$")
ERRORS = {
    "E_INGEST_GAP": "GAP",
    "E_INGEST_CONFLICT": "CONFLICT",
    "E_INGEST_GENERATION_CLOSED": "CLOSED_GENERATION",
}


def _read(path: Path, maximum: int = 16777216) -> bytes:
    descriptor = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    with os.fdopen(descriptor, "rb") as source:
        info = os.fstat(source.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_size > maximum:
            raise ValueError("E_OFFLINE_FILE_INTEGRITY")
        return source.read(maximum + 1)


def _sync(directory: Path) -> None:
    descriptor = os.open(directory, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


class InputJournal:
    def __init__(self, run_dir: Path, observer: Callable[[str, int], None] | None = None):
        self.observer = observer
        if any(path.is_symlink() for path in (run_dir, *run_dir.parents)):
            raise ValueError("E_OFFLINE_RUN_PATH")
        self.root = run_dir.absolute()
        if (self.root / "raw").is_symlink() or not (self.root / "raw").is_dir():
            raise ValueError("E_OFFLINE_RUN_PATH")
        self.context = cast(
            dict[str, Any], parse_strict_json(_read(self.root / "context.json", 262144))
        )
        validate_context(self.context)
        self.path = self.root / "receive.jsonl"
        self.store = RunStore(self.root / "run.sqlite3")
        self._verified_bytes = b""
        self._verified_rows: list[dict[str, Any]] = []

    def _rows(self, *, complete_prefix: bool = False) -> list[dict[str, Any]]:
        if any(path.is_symlink() for path in (self.root, *self.root.parents, self.root / "raw")):
            raise ValueError("E_OFFLINE_RUN_PATH")
        if not self.path.exists() and not self.path.is_symlink():
            if self._verified_bytes:
                raise ValueError("E_OFFLINE_JOURNAL_INTEGRITY")
            return []
        data = _read(self.path)
        if complete_prefix:
            data = data[: data.rfind(b"\n") + 1]
        # Re-read every byte; same-size or restored-mtime tampering invalidates reuse.
        if data == self._verified_bytes:
            return self._verified_rows
        if not data.startswith(self._verified_bytes):
            raise ValueError("E_OFFLINE_JOURNAL_INTEGRITY")
        if data and not data.endswith(b"\n"):
            raise ValueError("E_OFFLINE_JOURNAL_PARTIAL_TAIL")
        rows = []
        previous = "0" * 64
        receives: set[int] = set()
        outcomes: set[int] = set()
        for index, line in enumerate(data.splitlines(), 1):
            row = cast(dict[str, Any], parse_strict_json(line))
            common = {
                "row_index",
                "kind",
                "reference_receive_index",
                "previous_row_hash",
                "row_hash",
            }
            fields = {
                "RECEIVED": {"raw_hash", "batch_id", "generation", "sequence"},
                "OUTCOME": {"outcome"},
                "ACK_CONFIRMATION": {"generation", "sequence", "cursor_hash"},
                "PARTIAL_TAIL": {"artifact", "artifact_sha256"},
            }
            if (
                not isinstance(row, dict)
                or row.get("kind") not in fields
                or set(row) != common | fields[row["kind"]]
                or type(row["row_index"]) is not int
                or row["row_index"] != index
                or row["previous_row_hash"] != previous
                or rfc8785.dumps(row) != line
            ):
                raise ValueError("E_OFFLINE_JOURNAL_INTEGRITY")
            digest = hashlib.sha256(
                DOMAIN + rfc8785.dumps({k: v for k, v in row.items() if k != "row_hash"})
            ).hexdigest()
            if row["row_hash"] != digest:
                raise ValueError("E_OFFLINE_JOURNAL_INTEGRITY")
            reference = row["reference_receive_index"]
            if row["kind"] == "RECEIVED":
                if (
                    type(reference) is not int
                    or reference != len(receives) + 1
                    or not HEX.fullmatch(row["raw_hash"])
                    or not UUID.fullmatch(row["batch_id"])
                ):
                    raise ValueError("E_OFFLINE_JOURNAL_INTEGRITY")
                receives.add(reference)
            elif row["kind"] == "OUTCOME":
                if reference not in receives or reference in outcomes:
                    raise ValueError("E_OFFLINE_JOURNAL_INTEGRITY")
                outcomes.add(reference)
            elif reference is not None:
                raise ValueError("E_OFFLINE_JOURNAL_INTEGRITY")
            rows.append(row)
            previous = digest
        self._verified_bytes, self._verified_rows = data, rows
        return rows

    def _append(self, value: dict[str, Any]) -> None:
        rows = self._rows()
        row = {
            "row_index": len(rows) + 1,
            "previous_row_hash": rows[-1]["row_hash"] if rows else "0" * 64,
            **value,
        }
        row["row_hash"] = hashlib.sha256(DOMAIN + rfc8785.dumps(row)).hexdigest()
        descriptor = os.open(
            self.path, os.O_WRONLY | os.O_APPEND | os.O_CREAT | os.O_NOFOLLOW, 0o600
        )
        with os.fdopen(descriptor, "ab") as output:
            info = os.fstat(output.fileno())
            if (
                not stat.S_ISREG(info.st_mode)
                or info.st_nlink != 1
                or info.st_size != len(self._verified_bytes)
            ):
                raise ValueError("E_OFFLINE_FILE_INTEGRITY")
            encoded = rfc8785.dumps(row) + b"\n"
            output.write(encoded)
            output.flush()
            os.fsync(output.fileno())
        _sync(self.root)
        self._verified_bytes += encoded
        self._verified_rows = [*rows, copy.deepcopy(row)]

    def record_received(self, raw_bytes: bytes, batch_id: str) -> int:
        if not UUID.fullmatch(batch_id):
            raise ValueError("E_OFFLINE_SCHEMA")
        self._rows()
        raw = validate_synthetic_observation(raw_bytes, self.context)
        data = rfc8785.dumps(raw)
        path = self.root / "raw" / (raw["content_hash"] + ".json")
        if path.exists() or path.is_symlink():
            if _read(path, 65536) != data:
                raise ValueError("E_OFFLINE_RAW_CONFLICT")
        else:
            temporary = self.root / "raw" / (".pending-" + str(uuid4()))
            descriptor = os.open(
                temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600
            )
            with os.fdopen(descriptor, "wb") as output:
                output.write(data)
                output.flush()
                os.fsync(output.fileno())
            os.replace(temporary, path)
            _sync(path.parent)
        receive_index = sum(1 for row in self._rows() if row["kind"] == "RECEIVED") + 1
        self._append(
            {
                "kind": "RECEIVED",
                "reference_receive_index": receive_index,
                "raw_hash": raw["content_hash"],
                "batch_id": batch_id,
                "generation": raw["generation"],
                "sequence": raw["sequence"],
            }
        )
        return receive_index

    def record_outcome(self, receive_index: int, outcome: dict[str, Any]) -> None:
        self._record_outcome(receive_index, outcome)

    def _record_outcome(
        self,
        receive_index: int,
        outcome: dict[str, Any],
        applied_raw: dict[str, Any] | None = None,
    ) -> None:
        rows = self._rows()
        received = [
            r
            for r in rows
            if r["kind"] == "RECEIVED" and r["reference_receive_index"] == receive_index
        ]
        if len(received) != 1:
            raise ValueError("E_OFFLINE_OUTCOME_BINDING")
        existing = [
            r
            for r in rows
            if r["kind"] == "OUTCOME" and r["reference_receive_index"] == receive_index
        ]
        if existing:
            if existing[0]["outcome"] != outcome:
                raise ValueError("E_OFFLINE_OUTCOME_CONFLICT")
            return
        if outcome.get("status") == "APPLIED" and set(outcome) == {"status", "ack"}:
            ack = outcome["ack"]
            if applied_raw is not None:
                # Same synchronous invocation of real Ingestor.apply, after its commit.
                # No caller-supplied outcome or fault observer may use this proof.
                if (
                    applied_raw["content_hash"] != received[0]["raw_hash"]
                    or applied_raw["generation"] != received[0]["generation"]
                    or applied_raw["sequence"] != received[0]["sequence"]
                    or str(ack["generation"]) != received[0]["generation"]
                    or str(ack["highest_contiguous_sequence"]) != received[0]["sequence"]
                ):
                    raise ValueError("E_OFFLINE_OUTCOME_BINDING")
            else:
                with closing(self.store.connect()) as connection:
                    validate_journal(read_journal(connection, ordered=False))
                    raw_row = connection.execute(
                        "SELECT raw_observation_content_hash FROM raw_commits "
                        "WHERE raw_commit_id=?",
                        (ack.get("raw_commit_id"),),
                    ).fetchone()
                    actual = connection.execute(
                        "SELECT * FROM ack_outbox WHERE ack_outbox_id=?",
                        (ack.get("ack_outbox_id"),),
                    ).fetchone()
                if (
                    actual is None
                    or raw_row is None
                    or raw_row[0] != received[0]["raw_hash"]
                    or dict(actual) != ack
                    or str(ack["generation"]) != received[0]["generation"]
                    or str(ack["highest_contiguous_sequence"]) != received[0]["sequence"]
                ):
                    raise ValueError("E_OFFLINE_OUTCOME_BINDING")
        elif not (
            set(outcome) == {"status", "code"}
            and outcome["status"] == "REJECTED"
            and outcome["code"] in {"GAP", "CONFLICT", "CLOSED_GENERATION", "STORAGE_FAILED"}
        ):
            raise ValueError("E_OFFLINE_OUTCOME_BINDING")
        self._append(
            {"kind": "OUTCOME", "reference_receive_index": receive_index, "outcome": outcome}
        )

    def apply(self, raw_bytes: bytes, batch_id: str) -> dict[str, Any]:
        index = self.record_received(raw_bytes, batch_id)
        if self.observer:
            self.observer("AFTER_RECEIVED", index)
        raw = validate_synthetic_observation(raw_bytes, self.context)
        return self._apply_received(index, raw)

    def _apply_received(self, index: int, raw: dict[str, Any]) -> dict[str, Any]:
        try:
            outcome = {"status": "APPLIED", "ack": Ingestor(self.store).apply(raw)}
        except ValueError as error:
            if str(error) not in ERRORS:
                raise
            outcome = {"status": "REJECTED", "code": ERRORS[str(error)]}
        except (sqlite3.Error, OSError):
            outcome = {"status": "REJECTED", "code": "STORAGE_FAILED"}
        if self.observer:
            self.observer("AFTER_APPLY", index)
        self._record_outcome(index, outcome, raw if self.observer is None else None)
        return outcome

    def record_ack_confirmation(self, generation: str, sequence: str, cursor_hash: str) -> None:
        with closing(self.store.connect()) as connection:
            row = connection.execute(
                "SELECT * FROM ack_outbox WHERE generation=? "
                "AND highest_contiguous_sequence=? AND cursor_hash=?",
                (int(generation), int(sequence), cursor_hash),
            ).fetchone()
        if row is None:
            raise ValueError("E_OFFLINE_ACK_BINDING")
        Ingestor(self.store).confirm_ack(dict(row))
        self._append(
            {
                "kind": "ACK_CONFIRMATION",
                "reference_receive_index": None,
                "generation": generation,
                "sequence": sequence,
                "cursor_hash": cursor_hash,
            }
        )

    def iter_operations(
        self, *, start: int = 0, complete_prefix: bool = False
    ) -> Iterator[dict[str, Any]]:
        for row in self._rows(complete_prefix=complete_prefix)[start:]:
            if row["kind"] == "RECEIVED":
                data = _read(self.root / "raw" / (row["raw_hash"] + ".json"), 65536)
                raw = validate_synthetic_observation(data, self.context)
                if (
                    raw["content_hash"] != row["raw_hash"]
                    or raw["generation"] != row["generation"]
                    or raw["sequence"] != row["sequence"]
                    or rfc8785.dumps(raw) != data
                ):
                    raise ValueError("E_OFFLINE_RAW_BINDING")
                yield {**row, "raw": raw}
            else:
                if row["kind"] == "PARTIAL_TAIL":
                    if row["artifact"] != "partial-tail-" + row["artifact_sha256"] + ".jsonl":
                        raise ValueError("E_OFFLINE_JOURNAL_INTEGRITY")
                    if (
                        hashlib.sha256(_read(self.root / row["artifact"])).hexdigest()
                        != row["artifact_sha256"]
                    ):
                        raise ValueError("E_OFFLINE_JOURNAL_INTEGRITY")
                yield copy.deepcopy(row)

    def reconcile(self, store: RunStore) -> dict[str, int]:
        if store.db_path.absolute() != self.store.db_path:
            raise ValueError("E_OFFLINE_RUN_PATH")
        if self.path.exists():
            data = _read(self.path)
            if data and not data.endswith(b"\n"):
                digest = hashlib.sha256(data).hexdigest()
                retained = self.root / ("partial-tail-" + digest + ".jsonl")
                if retained.exists():
                    raise ValueError("E_OFFLINE_PARTIAL_ALREADY_RETAINED")
                os.rename(self.path, retained)
                prefix = data[: data.rfind(b"\n") + 1]
                descriptor = os.open(self.path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                with os.fdopen(descriptor, "wb") as output:
                    output.write(prefix)
                    output.flush()
                    os.fsync(output.fileno())
                self._append(
                    {
                        "kind": "PARTIAL_TAIL",
                        "reference_receive_index": None,
                        "artifact": retained.name,
                        "artifact_sha256": digest,
                    }
                )
        operations = list(self.iter_operations())
        completed = {r["reference_receive_index"] for r in operations if r["kind"] == "OUTCOME"}
        repaired = 0
        for row in operations:
            if row["kind"] == "RECEIVED" and row["reference_receive_index"] not in completed:
                with closing(store.connect()) as connection:
                    validate_journal(read_journal(connection, ordered=False))
                    gap = connection.execute(
                        "SELECT * FROM gap_records WHERE gap_id=?", ("gap:" + row["raw_hash"],)
                    ).fetchone()
                    ack = connection.execute(
                        "SELECT a.* FROM ack_outbox a JOIN raw_commits r "
                        "ON a.raw_commit_id=r.raw_commit_id WHERE r.raw_observation_content_hash=?",
                        (row["raw_hash"],),
                    ).fetchone()
                if gap is not None:
                    if (
                        gap["run_id"] != self.context["run_id"]
                        or gap["stream_id"] != self.context["stream_id"]
                        or gap["detected_sequence"] != int(row["sequence"])
                    ):
                        raise ValueError("E_OFFLINE_OUTCOME_BINDING")
                    code = {"MISSING_SEQUENCE": "GAP", "CONFLICTING_DUPLICATE": "CONFLICT"}[
                        gap["gap_reason"]
                    ]
                    self.record_outcome(
                        row["reference_receive_index"], {"status": "REJECTED", "code": code}
                    )
                elif ack is not None:
                    self.record_outcome(
                        row["reference_receive_index"], {"status": "APPLIED", "ack": dict(ack)}
                    )
                else:
                    self._apply_received(row["reference_receive_index"], row["raw"])
                repaired += 1
        return {"reconciled_operations": repaired}from .errors import ContractNotImplementedError


class LifecycleReducer:
    def apply(self, *_args: object, **_kwargs: object) -> None:
        raise ContractNotImplementedError("F0A-T07")"""Explicit v2 configuration. Parsing is network-free and grants no run authority."""

import copy
import hashlib
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, cast

from .canonical import parse_strict_json
from .live_contracts import schema_validate

ROOT = Path(__file__).resolve().parents[2]


def private_path(name: str, *, root: Path = ROOT, must_exist: bool = False) -> Path:
    relative = Path(name)
    if (
        relative.is_absolute()
        or ".." in relative.parts
        or "\\" in name
        or not relative.parts
        or relative.parts[0] != ".local"
    ):
        raise ValueError("E_LIVE_CONFIG_PATH")
    path = root / relative
    if any(p.is_symlink() for p in (path, *path.parents)):
        raise ValueError("E_LIVE_CONFIG_PATH")
    if not path.resolve().is_relative_to((root / ".local").resolve()):
        raise ValueError("E_LIVE_CONFIG_PATH")
    if must_exist and not path.is_file():
        raise ValueError("E_LIVE_CONFIG_EVIDENCE_MISSING")
    return path


@dataclass(frozen=True)
class LiveConfig:
    _data: dict[str, Any]
    sha256: str
    original_json: str | None = field(default=None, repr=False)

    @property
    def public(self) -> dict[str, Any]:
        return copy.deepcopy(self._data)

    @property
    def enabled(self) -> bool:
        return bool(self._data["enabled"])

    @property
    def fixture_ids(self) -> tuple[int, ...]:
        return tuple(sorted(self._data["provider"]["fixture_ids"]))


def load_live_config(path: Path, require_enabled: bool = False) -> LiveConfig:
    try:
        if path.is_symlink() or path.stat().st_size > 65536:
            raise ValueError("E_LIVE_CONFIG_FILE")
        raw = path.read_bytes()
        value = cast(dict[str, Any], parse_strict_json(raw))
        schema_validate(value, "config")
        provider, runtime, operator = value["provider"], value["runtime"], value["operator"]
        for name in (
            "batch_api_limit",
            "live_poll_seconds",
            "halftime_poll_seconds",
            "prematch_poll_seconds",
            "near_kickoff_poll_seconds",
            "events_fallback_poll_seconds",
            "daily_soft_cap",
            "max_requests_per_run",
            "max_requests_per_minute",
            "min_request_gap_seconds",
            "max_in_flight",
        ):
            if type(provider[name]) is not int:
                raise ValueError("E_LIVE_CONFIG_INTEGER")
        if type(runtime["max_matches"]) is not int or type(runtime["port"]) is not int:
            raise ValueError("E_LIVE_CONFIG_INTEGER")
        selected = set(provider["fixture_ids"])
        fallback = set(provider["events_fallback_fixture_ids"])
        if (
            len(selected) > runtime["max_matches"]
            or not fallback <= selected
            or (not provider["events_fallback_enabled"] and fallback)
        ):
            raise ValueError("E_LIVE_CONFIG_SCOPE")
        if require_enabled and not value["enabled"]:
            raise ValueError("E_LIVE_CONFIG_DISABLED")
        private_path(runtime["run_output_dir"])
        refs = [
            operator["capture_profile_path"],
            runtime["platform_qualification_path"],
            *(ref for name, ref in value["gates"].items() if name != "live_intent_path"),
        ]
        for ref in refs:
            if ref is not None:
                private_path(ref, must_exist=value["enabled"])
        # Intent creation follows config creation; the launcher validates its bytes before I/O.
        if value["gates"]["live_intent_path"] is not None:
            private_path(value["gates"]["live_intent_path"])
        if value["enabled"]:
            profile = private_path(operator["capture_profile_path"], must_exist=True)
            if (
                hashlib.sha256(profile.read_bytes()).hexdigest()
                != operator["profile_evidence_hash"]
            ):
                raise ValueError("E_LIVE_CONFIG_PROFILE_HASH")
        return LiveConfig(copy.deepcopy(value), hashlib.sha256(raw).hexdigest(), raw.decode())
    except Exception:
        raise ValueError("E_LIVE_CONFIG") from None"""Source-owned live schema boundary; validation never confers source authority."""

import copy
import hashlib
import json
from decimal import Decimal
from pathlib import Path
from typing import Any, cast
from urllib.parse import urlsplit

import rfc8785

from .canonical import _validate_unicode
from .schema_registry import _compiled, _plain_json

CONTRACTS = Path(__file__).resolve().parents[2] / "contracts/live_readonly/v1"
RECORD_KINDS = frozenset(
    {
        "ProviderState",
        "MarketBook",
        "FixtureBinding",
        "BindingChange",
        "HealthChange",
        "LiveEvent",
    }
)
MAX_INTEGER = 2**63 - 1
COUNTERS = frozenset(
    {
        "received_mono_us",
        "content_revision",
        "binding_revision",
        "capture_revision",
        "browser_mono_us",
        "revision",
        "before_revision",
        "epoch",
        "generation",
        "sequence",
        "counter",
        "first_sequence",
        "last_sequence",
        "monotonic_us",
    }
)


def schema_validate(value: object, name: str, kind: str | None = None) -> None:
    """Resolve only registered local resources; no external resolver or I/O callback."""
    if name not in {"records", "wire", "config", "operator-profile", "run-intent"}:
        raise ValueError("E_LIVE_SCHEMA_NAME")
    schema = (CONTRACTS / f"{name}.schema.json").read_bytes()
    resources = tuple(p.read_bytes() for p in sorted(CONTRACTS.glob("*.schema.json")))
    if kind is not None:
        if name != "records" or kind not in RECORD_KINDS:
            raise ValueError("E_LIVE_SCHEMA_KIND")
        schema = json.dumps({"$ref": f"urn:betting-helper:live-records:v1#/$defs/{kind}"}).encode()
    if not _plain_json(value):
        raise ValueError("E_LIVE_JSON_TYPE")
    _validate_unicode(value)
    _scalars(value)
    _compiled(schema, resources).validate(value)


def _scalars(value: Any, key: str = "") -> None:
    if type(value) is float:
        raise ValueError("E_LIVE_INTEGER_TYPE")
    if isinstance(value, dict):
        for name, child in value.items():
            _scalars(child, name)
    elif isinstance(value, list):
        for child in value:
            _scalars(child, key)
    elif isinstance(value, str):
        if any(ord(c) < 32 or ord(c) == 127 for c in value):
            raise ValueError("E_LIVE_CONTROL_CHARACTER")
        if key in COUNTERS and int(value) > MAX_INTEGER:
            raise ValueError("E_LIVE_INTEGER_RANGE")


def _semantics(value: dict[str, Any], kind: str) -> None:
    if kind == "LiveEvent":
        _semantics(value["payload"], value["payload_type"])
    elif kind == "BindingChange":
        _semantics(value["after"], "FixtureBinding")
    elif kind in {"ProviderState", "FixtureBinding"}:
        if value["home_id"] == value["away_id"]:
            raise ValueError("E_LIVE_PARTICIPANTS")
        if kind == "ProviderState":
            # This adapter has no verified upstream update-time field.
            if value["provider_updated_at"] is not None:
                raise ValueError("E_LIVE_SOURCE_TIME_UNVERIFIED")
            if value["events_status"] in {"OBSERVED_EMPTY", "UNKNOWN_SECTION"} and value["events"]:
                raise ValueError("E_LIVE_EVENTS_STATUS")
        else:
            if value["operator_home_id"] == value["operator_away_id"]:
                raise ValueError("E_LIVE_PARTICIPANTS")
            if value["orientation_status"] == "VERIFIED" and not value["evidence_hashes"]:
                raise ValueError("E_LIVE_BINDING_EVIDENCE")
            for key in ("operator_match_url", "livescore_match_url"):
                if value[key] is not None:
                    url = urlsplit(value[key])
                    if (
                        url.scheme != "https"
                        or not url.hostname
                        or url.username
                        or url.password
                        or url.query
                        or url.fragment
                        or url.port not in {None, 443}
                    ):
                        raise ValueError("E_LIVE_BINDING_URL")
    elif kind == "MarketBook":
        selections = value["selections"].values()
        if len({row["selection_id"] for row in selections}) != 3:
            raise ValueError("E_LIVE_SELECTION_IDENTITY")
        if any(Decimal(row["decimal_odds"]) <= 1 for row in selections):
            raise ValueError("E_LIVE_ODDS")


def validate_live_record(value: object, kind: str) -> dict[str, Any]:
    try:
        schema_validate(value, "records", kind)
        record = cast(dict[str, Any], value)
        _scalars(record)
        _semantics(record, kind)
        if len(rfc8785.dumps(record)) > 65536:
            raise ValueError("E_LIVE_RECORD_SIZE")
        return copy.deepcopy(record)
    except Exception:
        # Schema exceptions include rejected data; never propagate them to logging.
        raise ValueError("E_LIVE_RECORD") from None


def event_hash(value: object) -> str:
    record = validate_live_record(value, "LiveEvent")
    del record["content_hash"]
    return hashlib.sha256(b"BH-LIVE-READONLY/Event/v1\0" + rfc8785.dumps(record)).hexdigest()"""Exact observed identity binding; names are display data, never matching keys."""

import hashlib
import importlib
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from .canonical import parse_strict_json
from .live_contracts import validate_live_record
from .operator_profile import ExtractionProfile, _private_bytes, activate_profile

OPERATOR_FIELDS = frozenset(
    {"fixture_id", "home_id", "away_id", "competition_id", "season", "kickoff_utc", "match_url"}
)
PROVIDER_FIELDS = frozenset(
    {"fixture_id", "home_id", "away_id", "league_id", "season", "kickoff_utc"}
)


@dataclass(frozen=True)
class BindingEvidence:
    root: Path
    mapping_path: Path
    mapping_sha256: str
    source_kind: str
    provider_metadata: dict[str, Any]
    profile: ExtractionProfile = field(repr=False)
    previous: dict[str, Any] | None = None


def bind_fixture(
    provider: dict[str, Any], operator: dict[str, Any], evidence: BindingEvidence
) -> dict[str, Any]:
    try:
        provider = validate_live_record(provider, "ProviderState")
        if not isinstance(evidence, BindingEvidence) or evidence.source_kind not in {
            "SYNTHETIC_TEST",
            "OBSERVED_REAL",
        }:
            raise ValueError()
        raw = _private_bytes(evidence.mapping_path, evidence.root)
        digest = hashlib.sha256(raw).hexdigest()
        if digest != evidence.mapping_sha256:
            raise ValueError()
        mapping = parse_strict_json(raw)
        if (
            not isinstance(mapping, dict)
            or set(mapping)
            != {
                "schema_version",
                "source_kind",
                "binding_id",
                "revision",
                "provider",
                "operator",
                "livescore_match_url",
            }
            or mapping["schema_version"] != "fixture-mapping/v1"
        ):
            raise ValueError()
        if (
            mapping["source_kind"] != evidence.source_kind
            or set(operator) != OPERATOR_FIELDS
            or set(evidence.provider_metadata) != PROVIDER_FIELDS
            or mapping["provider"] != evidence.provider_metadata
            or mapping["operator"] != operator
        ):
            raise ValueError()
        if any(
            provider[k] != evidence.provider_metadata[k]
            for k in ("fixture_id", "home_id", "away_id", "kickoff_utc")
        ):
            raise ValueError()
        if (
            operator["kickoff_utc"] != provider["kickoff_utc"]
            or operator["season"] != evidence.provider_metadata["season"]
            or not isinstance(operator["competition_id"], str)
            or not 1 <= len(operator["competition_id"]) <= 128
        ):
            raise ValueError()
        target = "SYNTHETIC_TEST" if evidence.source_kind == "SYNTHETIC_TEST" else "OPERATOR"
        profile = activate_profile(evidence.profile, target)
        if (
            operator["fixture_id"] not in profile["permitted_fixture_ids"]
            or operator["match_url"]
            not in {profile["origin"] + path for path in profile["exact_paths"]}
            or ("SYNTHETIC" in provider["quality_flags"]) != (target == "SYNTHETIC_TEST")
        ):
            raise ValueError()
        if target == "OPERATOR":
            # Real admission belongs to the current evidence/host verifier, never this hash check.
            importlib.import_module("moj_discovery.live_preflight_batched").verify_binding_evidence(
                mapping, evidence
            )
        previous = evidence.previous
        if previous is not None:
            previous = validate_live_record(previous, "FixtureBinding")
        if int(mapping["revision"]) != (
            1 if previous is None else int(previous["revision"]) + 1
        ) or (
            previous is not None
            and (
                mapping["binding_id"] != previous["binding_id"]
                or provider["fixture_id"] != previous["provider_fixture_id"]
            )
        ):
            raise ValueError()
        return validate_live_record(
            {
                "binding_id": mapping["binding_id"],
                "revision": mapping["revision"],
                "provider_fixture_id": provider["fixture_id"],
                "league_id": evidence.provider_metadata["league_id"],
                "season": evidence.provider_metadata["season"],
                **{
                    k: provider[k]
                    for k in ("kickoff_utc", "home_id", "away_id", "home_name", "away_name")
                },
                "operator_fixture_id": operator["fixture_id"],
                "operator_home_id": operator["home_id"],
                "operator_away_id": operator["away_id"],
                "operator_match_url": operator["match_url"],
                "livescore_match_url": mapping["livescore_match_url"],
                "orientation_status": "VERIFIED",
                "evidence_hashes": [digest],
            },
            "FixtureBinding",
        )
    except Exception:
        raise ValueError("E_LIVE_IDENTITY") from None


def fixture_key(binding: dict[str, Any]) -> str:
    value = validate_live_record(binding, "FixtureBinding")
    return f"{value['provider_fixture_id']}:{value['binding_id']}:{value['revision']}""""One-use local terminal consent. This is not an independent review or signature."""

import copy
import fcntl
import hashlib
import os
import sqlite3
import threading
import time
from collections.abc import Iterator
from contextlib import closing, contextmanager, suppress
from dataclasses import dataclass, field
from datetime import UTC, datetime
from pathlib import Path
from typing import Any
from uuid import UUID, uuid4

import rfc8785

from .canonical import parse_strict_json
from .live_config import ROOT, LiveConfig, private_path
from .live_contracts import schema_validate
from .provider_protocol import ProviderScope
from .secrets_local import controlling_tty

PHRASES = {
    "PROVIDER_PROBE": "ALLOW PROVIDER PROBE",
    "OPERATOR_DISCOVERY": "ALLOW OPERATOR OBSERVATION",
    "LIVE_READ_ONLY": "START READ ONLY",
}
_SEAL = object()
_claim_lock = threading.Lock()


def discovery_field_map(value: Any) -> dict[str, Any]:
    """Bound selector data only; this does not assert the selectors were observed."""
    from .operator_profile import REQUIRED_CAPTURE, validate_selector

    if type(value) is dict and value == {"selection_mode": "USER_SELECTED_REGION_V1"}:
        return copy.deepcopy(value)
    if type(value) is not dict or set(value) != set(REQUIRED_CAPTURE) | {"score", "period"}:
        raise ValueError("E_DISCOVERY_FIELD_MAP")
    for name, selector in value.items():
        if selector is None and name != "match_root":
            continue
        validate_selector(selector)
    root = value["match_root"]
    if "#" not in root and "[data-" not in root:
        raise ValueError("E_DISCOVERY_ROOT")
    return copy.deepcopy(value)


def discovery_review_scope(
    intent: "RunIntent",
    config: LiveConfig,
    selectors: dict[str, Any],
    profile_name: str,
    expires_at: str,
) -> dict[str, Any]:
    """Pre-sample tool review, deliberately independent of accepted profile evidence."""
    from urllib.parse import urlsplit

    from .live_preflight_batched import _expires
    from .operator_profile import capture_source_hash

    value = _validate(intent, config, datetime.now(UTC))
    if value["stage"] != "OPERATOR_DISCOVERY" or len(value["fixture_ids"]) != 1:
        raise ValueError("E_DISCOVERY_INTENT")
    parsed = urlsplit(value["operator_urls"][0])
    if parsed.netloc != "miseojeuplus.espacejeux.com" or not parsed.path.startswith("/sports/"):
        raise ValueError("E_DISCOVERY_ORIGIN")
    if (
        type(profile_name) is not str
        or not 1 <= len(profile_name) <= 80
        or any(ord(c) < 32 or ord(c) == 127 for c in profile_name)
    ):
        raise ValueError("E_DISCOVERY_PROFILE_NAME")
    _expires(expires_at, datetime.now(UTC))
    return dict(
        kind="OPERATOR_DISCOVERY_TOOL",
        source_tree_sha256=source_tree_hash(intent.root),
        capture_source_sha256=capture_source_hash(intent.root),
        config_sha256=config.sha256,
        fixture_ids=value["fixture_ids"],
        exact_url=value["operator_urls"][0],
        selectors=discovery_field_map(selectors),
        profile_name=profile_name,
        max_duration_seconds=value["max_duration_seconds"],
        max_http_attempts=0,
        expires_at=expires_at,
    )


def discovery_mac(key: bytes, kind: str, run_id: str, nonce: str, payload: str = "") -> str:
    import hmac

    if len(key) != 32 or kind not in {"AUTH", "PLAN", "SAMPLE", "ACK"}:
        raise ValueError("E_DISCOVERY_MAC")
    data = f"BH-DISCOVERY/v1\0{kind}\0{run_id}\0{nonce}\0{payload}".encode()
    return hmac.new(key, data, "sha256").hexdigest()


async def serve_operator_discovery(
    receipt: "RunIntentReceipt",
    selectors: dict[str, Any],
    profile_name: str,
    review: dict[str, Any],
    output: Path,
    *,
    verified_review: Any = None,
) -> dict[str, Any]:
    """One reviewed, consented, keyless exchange with the fixed extension reader."""
    import asyncio
    import base64
    import hmac
    import json
    import secrets

    from websockets.asyncio.server import serve
    from websockets.typing import Origin

    from tools.qualify_chrome_indexeddb import _extension_id

    from .live_preflight_batched import recheck_external_review, verify_external_review

    verify_receipt(receipt, "OPERATOR_DISCOVERY")
    scope = discovery_review_scope(
        receipt.intent,
        receipt.config,
        selectors,
        profile_name,
        review.get("scope", {}).get("expires_at", ""),
    )
    if verified_review is None:
        verified_review = await asyncio.to_thread(
            verify_external_review, review, scope, receipt.intent.root, datetime.now(UTC)
        )
    else:
        await asyncio.to_thread(
            recheck_external_review,
            verified_review,
            review,
            scope,
            receipt.intent.root,
            datetime.now(UTC),
        )
    verify_receipt(receipt, "OPERATOR_DISCOVERY")
    # Claim only after actual tool review. An accepted capture profile is not required.
    claim_receipt(receipt, "OPERATOR_DISCOVERY")
    path = private_path(str(output.relative_to(receipt.intent.root)), root=receipt.intent.root)
    if path.exists():
        raise ValueError("E_DISCOVERY_OUTPUT_EXISTS")
    key = secrets.token_bytes(32)
    manifest = json.loads((receipt.intent.root / "extension/manifest.live.json").read_text())
    origin = "chrome-extension://" + _extension_id(manifest["key"])
    deadline = min(
        receipt.deadline_mono,
        time.monotonic()
        + (datetime.fromisoformat(scope["expires_at"]) - datetime.now(UTC)).total_seconds(),
    )
    finished = asyncio.Event()
    result: dict[str, Any] = {"status": "NOT_OBSERVED", "profile_accepted": False}
    claimed = False

    async def current() -> None:
        verify_receipt(receipt, "OPERATOR_DISCOVERY")
        if time.monotonic() >= deadline:
            raise ValueError("E_DISCOVERY_EXPIRED")
        await asyncio.to_thread(
            recheck_external_review,
            verified_review,
            review,
            scope,
            receipt.intent.root,
            datetime.now(UTC),
        )
        verify_receipt(receipt, "OPERATOR_DISCOVERY")
        if time.monotonic() >= deadline:
            raise ValueError("E_DISCOVERY_EXPIRED")

    async def exchange(ws: Any) -> None:
        nonlocal claimed, result
        if claimed or ws.request.path != "/operator-discovery":
            await ws.close(code=1008)
            return
        claimed = True
        nonce = secrets.token_hex(32)
        try:
            async with asyncio.timeout(max(0.001, deadline - time.monotonic())):
                await current()
                await ws.send(json.dumps({"run_id": receipt.run_id, "nonce": nonce}))
                auth = parse_strict_json((await asyncio.wait_for(ws.recv(), 5)).encode())
                if (
                    type(auth) is not dict
                    or set(auth) != {"mac"}
                    or not hmac.compare_digest(
                        str(auth["mac"]), discovery_mac(key, "AUTH", receipt.run_id, nonce)
                    )
                ):
                    raise ValueError("E_DISCOVERY_AUTH")
                await current()
                plan = dict(
                    exactUrl=scope["exact_url"],
                    sourceKind="OBSERVED_REAL",
                    fieldMapHash=hashlib.sha256(rfc8785.dumps(scope["selectors"])).hexdigest(),
                    selectors=scope["selectors"],
                    expiresAt=scope["expires_at"],
                    leaseMs=max(1, int((deadline - time.monotonic()) * 1000)),
                )
                payload = json.dumps(plan, separators=(",", ":"), ensure_ascii=False)
                await ws.send(
                    json.dumps(
                        {
                            "payload": payload,
                            "mac": discovery_mac(key, "PLAN", receipt.run_id, nonce, payload),
                        }
                    )
                )
                frame = parse_strict_json((await ws.recv()).encode())
                if (
                    type(frame) is not dict
                    or set(frame) != {"payload", "mac"}
                    or type(frame["payload"]) is not str
                    or not hmac.compare_digest(
                        str(frame["mac"]),
                        discovery_mac(key, "SAMPLE", receipt.run_id, nonce, frame["payload"]),
                    )
                ):
                    raise ValueError("E_DISCOVERY_SAMPLE_MAC")
                sample = parse_strict_json(frame["payload"].encode())
                validate_discovery_sample(sample, plan)
                await current()
                candidate = dict(
                    status="UNADMITTED_SAMPLE",
                    profile_accepted=False,
                    binding_verified=False,
                    source_kind="OBSERVED_REAL",
                    sample=sample,
                    run_id=receipt.run_id,
                    intent_sha256=receipt.intent.sha256,
                    source_tree_sha256=scope["source_tree_sha256"],
                    review_scope_sha256=hashlib.sha256(rfc8785.dumps(scope)).hexdigest(),
                    profile_name_user_supplied=profile_name,
                    provider_requests=0,
                )
                path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
                fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
                with os.fdopen(fd, "w") as handle:
                    json.dump(candidate, handle, indent=2, ensure_ascii=False)
                    handle.write("\n")
                    handle.flush()
                    os.fsync(handle.fileno())
                result = {**candidate, "status": "UNADMITTED_SAMPLE_SAVED"}
                payload = json.dumps({"status": "UNADMITTED_SAMPLE_SAVED"}, separators=(",", ":"))
                await ws.send(
                    json.dumps(
                        {
                            "payload": payload,
                            "mac": discovery_mac(key, "ACK", receipt.run_id, nonce, payload),
                        }
                    )
                )
        except Exception:
            if result["status"] != "UNADMITTED_SAMPLE_SAVED":
                result = {"status": "DISCOVERY_REJECTED", "profile_accepted": False}
        finally:
            finished.set()

    # Same pinned local authority as Part B. No arbitrary URL, port or proxy surface.
    async with serve(
        exchange,
        "127.0.0.1",
        8765,
        origins=[Origin(origin)],
        max_size=16384,
        max_queue=1,
        compression=None,
        ping_interval=None,
        close_timeout=1,
    ):
        ticket = dict(
            kind="OPERATOR_DISCOVERY",
            runId=receipt.run_id,
            key=base64.urlsafe_b64encode(key).decode().rstrip("="),
        )
        print(
            "LOCAL_DISCOVERY_PAIRING_TICKET: " + json.dumps(ticket, separators=(",", ":")),
            flush=True,
        )
        with suppress(TimeoutError):
            await asyncio.wait_for(finished.wait(), max(0.001, deadline - time.monotonic()))
    return result


def validate_selection_map(value: Any) -> None:
    """Only observed candidate text/selectors; no semantic profile admission."""
    import json
    import unicodedata

    from .operator_profile import validate_selector

    if (
        type(value) is not dict
        or set(value) != {"match_root_selector", "candidates"}
        or type(value["candidates"]) is not list
        or not 1 <= len(value["candidates"]) <= 32
        or len(json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode()) > 10000
    ):
        raise ValueError("E_DISCOVERY_MAP")
    validate_selector(value["match_root_selector"])
    if "#" not in value["match_root_selector"] and "[data-" not in value["match_root_selector"]:
        raise ValueError("E_DISCOVERY_ROOT")
    seen = set()
    for row in value["candidates"]:
        if type(row) is not dict or set(row) != {"selector", "text", "market_id"}:
            raise ValueError("E_DISCOVERY_MAP")
        validate_selector(row["selector"])
        if row["selector"] in seen or row["text"] is None and row["market_id"] is None:
            raise ValueError("E_DISCOVERY_MAP")
        seen.add(row["selector"])
        for text in (row["text"], row["market_id"]):
            if text is not None and (
                type(text) is not str
                or not 1 <= len(text) <= 256
                or text != unicodedata.normalize("NFC", text)
                or any(ord(c) < 32 or ord(c) == 127 for c in text)
            ):
                raise ValueError("E_DISCOVERY_TEXT")


def validate_discovery_sample(sample: Any, plan: dict[str, Any]) -> None:
    import unicodedata

    mapping = discovery_field_map(plan["selectors"]) == {
        "selection_mode": "USER_SELECTED_REGION_V1"
    }
    fields = set(discovery_field_map(plan["selectors"])) - {"match_root"}
    if (
        type(sample) is not dict
        or set(sample)
        != {
            "status",
            "source_kind",
            "exact_url",
            "field_map_hash",
            "tab_id",
            "document_id",
            "document_epoch",
            "fields",
            "observed_at_utc",
            "browser_mono_us",
            "profile_accepted",
            "binding_verified",
        }
        or sample["status"] != "UNADMITTED_SAMPLE"
        or sample["source_kind"] != plan["sourceKind"]
        or sample["exact_url"] != plan["exactUrl"]
        or sample["field_map_hash"] != plan["fieldMapHash"]
        or sample["profile_accepted"] is not False
        or sample["binding_verified"] is not False
    ):
        raise ValueError("E_DISCOVERY_SAMPLE_SCOPE")
    if mapping:
        validate_selection_map(sample["fields"])
    elif type(sample["fields"]) is not dict or set(sample["fields"]) != fields:
        raise ValueError("E_DISCOVERY_FIELDS")
    for value in [] if mapping else sample["fields"].values():
        if value is not None and (
            type(value) is not str
            or not 1 <= len(value) <= 256
            or value != unicodedata.normalize("NFC", value)
            or any(ord(c) < 32 or ord(c) == 127 for c in value)
        ):
            raise ValueError("E_DISCOVERY_TEXT")
    if type(sample["tab_id"]) is not int or sample["tab_id"] < 0:
        raise ValueError("E_DISCOVERY_TAB")
    for name in ("document_id", "document_epoch", "observed_at_utc", "browser_mono_us"):
        if type(sample[name]) is not str or not 1 <= len(sample[name]) <= 128:
            raise ValueError("E_DISCOVERY_IDENTITY")

    try:
        stamp = datetime.fromisoformat(sample["observed_at_utc"])
        age = (datetime.now(UTC) - stamp).total_seconds()
        mono = sample["browser_mono_us"]
        if (
            stamp.utcoffset() != UTC.utcoffset(stamp)
            or not -1 <= age <= 600
            or str(UUID(sample["document_epoch"])) != sample["document_epoch"]
            or not mono.isascii()
            or not mono.isdecimal()
            or str(int(mono)) != mono
            or not 0 <= int(mono) <= 9223372036854775807
            or any(ord(c) < 32 or ord(c) == 127 for c in sample["document_id"])
        ):
            raise ValueError()
    except (ValueError, TypeError, OverflowError):
        raise ValueError("E_DISCOVERY_CLOCK_OR_DOCUMENT") from None


def source_tree_hash(root: Path = ROOT) -> str:
    """Hash source and pinned build inputs only; never enumerate local credential files."""
    files: set[Path] = set()
    for folder, suffix in (
        ("src/moj_discovery", ".py"),
        ("tools", ".py"),
        ("tools", ".cjs"),
        ("extension/src", ".ts"),
        ("extension/src/live", ".html"),
        ("extension/src/live", ".css"),
        ("contracts/live_readonly/v1", ".json"),
        ("contracts/live_readonly/v1", ".sql"),
    ):
        files.update((root / folder).rglob("*" + suffix))
    files.update(
        root / name
        for name in (
            "pyproject.toml",
            "uv.lock",
            "package.json",
            "pnpm-lock.yaml",
            "extension/package.json",
            "extension/pnpm-lock.yaml",
            "extension/manifest.live.json",
            "extension/tsconfig.json",
            "extension/tsconfig.live.json",
        )
    )
    hashes = {}
    for path in sorted(files):
        if not path.exists():
            continue  # Optional root/extension lock location; the installed lock is included.
        if not path.is_file() or any(p.is_symlink() for p in (path, *path.parents)):
            raise ValueError("E_INTENT_SOURCE_PATH")
        hashes[str(path.relative_to(root))] = hashlib.sha256(path.read_bytes()).hexdigest()
    if not hashes:
        raise ValueError("E_INTENT_SOURCE_EMPTY")
    return hashlib.sha256(b"BH-PartB-Source/v1\0" + rfc8785.dumps(hashes)).hexdigest()


def validate_intent_window(issued: datetime, expires: datetime, now: datetime) -> None:
    if (
        any(t.tzinfo is None or t.utcoffset() != UTC.utcoffset(t) for t in (issued, expires, now))
        or not 0 < (expires - issued).total_seconds() <= 900
        or not issued <= now < expires
    ):
        raise ValueError("E_INTENT_EXPIRED")


@dataclass(frozen=True)
class RunIntent:
    _data: dict[str, Any] = field(repr=False)
    sha256: str
    root: Path = field(repr=False, default=ROOT)
    original_json: str | None = field(default=None, repr=False)

    @property
    def public(self) -> dict[str, Any]:
        return copy.deepcopy(self._data)


@dataclass(frozen=True)
class RunIntentReceipt:
    intent: RunIntent
    config: LiveConfig = field(repr=False)
    run_id: str
    deadline_mono: float
    consumed_at_utc: str
    started_mono: float
    confirmation_kind: str = "LOCAL_TTY_USER_CONFIRMATION"
    _proof: object = field(default=None, repr=False)
    _pid: int = field(default=0, repr=False)
    _claimed: bool = field(default=False, repr=False)
    _live_authority: object = field(default=None, repr=False, init=False)


def _validate(intent: RunIntent, config: LiveConfig, now: datetime) -> dict[str, Any]:
    try:
        if type(intent) is not RunIntent or type(config) is not LiveConfig:
            raise ValueError()
        value, cfg = intent.public, config.public
        schema_validate(value, "run-intent")
        lookup = value.get("lookup_date")
        if lookup is not None:
            from datetime import date

            if date.fromisoformat(lookup).isoformat() != lookup:
                raise ValueError()
        validate_intent_window(
            datetime.fromisoformat(value["issued_at"]),
            datetime.fromisoformat(value["expires_at"]),
            now,
        )
        if (
            value["config_sha256"] != config.sha256
            or value["source_tree_sha256"] != source_tree_hash(intent.root)
            or tuple(sorted(value["fixture_ids"])) != config.fixture_ids
            or not (0 if lookup is not None else 1)
            <= len(config.fixture_ids)
            <= cfg["runtime"]["max_matches"]
            or cfg["provider"]["league_id"] is None
            or cfg["provider"]["season"] is None
            or cfg["provider"]["events_fallback_enabled"]
            or cfg["provider"]["events_fallback_fixture_ids"]
        ):
            raise ValueError()
        if value["stage"] == "LIVE_READ_ONLY" and (
            not config.enabled
            or not 1 <= value["max_http_attempts"] <= cfg["provider"]["max_requests_per_run"]
            or len(value["operator_urls"]) != len(config.fixture_ids)
            or value["max_duration_seconds"] > cfg["runtime"]["max_run_minutes"] * 60
        ):
            raise ValueError()
        if (
            value["stage"] == "PROVIDER_PROBE"
            and value["max_http_attempts"] > cfg["provider"]["max_requests_per_run"]
        ):
            raise ValueError()
        for url in value["operator_urls"]:
            from urllib.parse import urlsplit

            parsed = urlsplit(url)
            if (
                parsed.scheme != "https"
                or not parsed.hostname
                or parsed.username
                or parsed.password
                or parsed.query
                or parsed.fragment
            ):
                raise ValueError()
        return value
    except Exception:
        raise ValueError("E_INTENT_SCOPE_OR_SOURCE") from None


def load_run_intent(path: Path, config: LiveConfig, stage: str, *, root: Path = ROOT) -> RunIntent:
    try:
        relative = str(path.relative_to(root)) if path.is_absolute() else str(path)
        checked = private_path(relative, root=root, must_exist=True)
        if checked.stat().st_size > 65536:
            raise ValueError()
        raw = checked.read_bytes()
        value = parse_strict_json(raw)
        if type(value) is not dict or value["stage"] != stage or stage not in PHRASES:
            raise ValueError()
        intent = RunIntent(value, hashlib.sha256(raw).hexdigest(), root, raw.decode())
        _validate(intent, config, datetime.now(UTC))
        if stage == "LIVE_READ_ONLY" and relative != config.public["gates"]["live_intent_path"]:
            raise ValueError()
        return intent
    except Exception:
        raise ValueError("E_INTENT_LOAD") from None


@contextmanager
def _ledger(root: Path) -> Iterator[sqlite3.Connection]:
    path = private_path(".local/part-b/intent-consumptions.sqlite3", root=root)
    path.parent.mkdir(parents=True, mode=0o700, exist_ok=True)
    fd = os.open(path, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
        with closing(sqlite3.connect(path, timeout=5, isolation_level=None)) as db:
            db.execute("PRAGMA synchronous=FULL")
            db.execute("PRAGMA busy_timeout=5000")
            version = db.execute("PRAGMA user_version").fetchone()[0]
            if version == 0:
                db.executescript((ROOT / "contracts/live_readonly/v1/intent-store.sql").read_text())
            elif version != 1:
                raise ValueError("E_INTENT_LEDGER_VERSION")
            yield db
    finally:
        fcntl.flock(fd, fcntl.LOCK_UN)
        os.close(fd)


def intent_is_consumed(intent: RunIntent) -> bool:
    """Inspect the durable public ledger without granting or consuming authority."""
    with _ledger(intent.root) as db:
        return db.execute(
            "SELECT 1 FROM intent_consumptions WHERE intent_id=?", (intent.public["intent_id"],)
        ).fetchone() is not None


def consume_user_intent(
    intent: RunIntent, config: LiveConfig, confirmation: str
) -> RunIntentReceipt:
    """Only the user-terminal launcher calls this after displaying the exact scope."""
    now = datetime.now(UTC)
    value = _validate(intent, config, now)
    if type(confirmation) is not str or confirmation != PHRASES[value["stage"]]:
        raise ValueError("E_INTENT_DECLINED")
    # Presence of an environment credential never replaces the controlling terminal.
    with controlling_tty():
        pass
    run_id, stamp = str(uuid4()), now.isoformat().replace("+00:00", "Z")
    try:
        with _ledger(intent.root) as db:
            db.execute("BEGIN IMMEDIATE")
            db.execute(
                "INSERT INTO intent_consumptions VALUES (?,?,?,?,?,?,?,?,0)",
                (
                    value["intent_id"],
                    intent.sha256,
                    run_id,
                    value["stage"],
                    value["source_tree_sha256"],
                    config.sha256,
                    stamp,
                    "LOCAL_TTY_USER_CONFIRMATION",
                ),
            )
            db.execute("COMMIT")
    except Exception:
        raise ValueError("E_INTENT_CONSUMED_OR_LEDGER") from None
    started = time.monotonic()
    return RunIntentReceipt(
        intent,
        config,
        run_id,
        started + value["max_duration_seconds"],
        stamp,
        started,
        _proof=_SEAL,
        _pid=os.getpid(),
    )


def verify_receipt(receipt: RunIntentReceipt, stage: str) -> None:
    try:
        if (
            type(receipt) is not RunIntentReceipt
            or receipt._proof is not _SEAL
            or receipt._pid != os.getpid()
            or receipt.intent.public["stage"] != stage
            or not receipt.started_mono <= time.monotonic() < receipt.deadline_mono
            or not 0
            <= (datetime.now(UTC) - datetime.fromisoformat(receipt.consumed_at_utc)).total_seconds()
            < receipt.intent.public["max_duration_seconds"]
            or receipt.config.sha256 != receipt.intent.public["config_sha256"]
            or source_tree_hash(receipt.intent.root) != receipt.intent.public["source_tree_sha256"]
        ):
            raise ValueError()
        with _ledger(receipt.intent.root) as db:
            row = db.execute(
                "SELECT intent_hash,run_id,config_hash,source_tree_hash "
                "FROM intent_consumptions WHERE intent_id=?",
                (receipt.intent.public["intent_id"],),
            ).fetchone()
            if row != (
                receipt.intent.sha256,
                receipt.run_id,
                receipt.config.sha256,
                receipt.intent.public["source_tree_sha256"],
            ):
                raise ValueError()
    except Exception:
        raise ValueError("E_INTENT_RECEIPT") from None


def claim_receipt(receipt: RunIntentReceipt, stage: str) -> None:
    with _claim_lock:
        verify_receipt(receipt, stage)
        if receipt._claimed:
            raise ValueError("E_INTENT_OPERATION_REPLAY")
        object.__setattr__(receipt, "_claimed", True)


def verify_provider_receipt(receipt: RunIntentReceipt, scope: ProviderScope, purpose: str) -> None:
    verify_receipt(receipt, scope.stage)
    if scope.stage == "LIVE_READ_ONLY":
        from .live_preflight_batched import verify_live_receipt

        verify_live_receipt(receipt)
    value, provider = receipt.intent.public, receipt.config.public["provider"]
    if (
        not receipt._claimed
        or receipt.intent.root.resolve() != ROOT.resolve()
        or scope.scope_id != receipt.run_id
        or scope.source_kind != "OBSERVED_REAL"
        or scope.config_sha256 != receipt.config.sha256
        or scope.source_tree_sha256 != value["source_tree_sha256"]
        or tuple(sorted(scope.fixture_ids)) != tuple(sorted(value["fixture_ids"]))
        or scope.league_id != provider["league_id"]
        or scope.season != provider["season"]
        or scope.max_attempts > value["max_http_attempts"]
        or scope.deadline_mono > receipt.deadline_mono
        or scope.events_fixture_ids
        or scope.lookup_date != value.get("lookup_date")
        or purpose
        not in (
            {"STATUS", "LOOKUP"}
            if scope.lookup_date is not None
            else {"STATUS", "COVERAGE", "BUNDLE"}
        )
    ):
        raise ValueError("E_INTENT_PROVIDER_SCOPE")"""Network-free v2 evidence admission, separate from legacy v1 preflight."""

import copy
import hashlib
import importlib
import json
import os
import subprocess
import time
from dataclasses import dataclass, field
from datetime import UTC, datetime, timedelta
from pathlib import Path
from typing import Any
from uuid import uuid4

import rfc8785

from .canonical import parse_strict_json
from .live_config import ROOT, LiveConfig, private_path
from .live_contracts import validate_live_record
from .live_intent import RunIntentReceipt, claim_receipt, source_tree_hash, verify_receipt
from .operator_profile import (
    ExtractionProfile,
    ProfileEvidence,
    capture_source_hash,
    validate_extraction_profile,
)

_SEAL = object()
REQUIRED = {
    "provider": "REQUIRES_REAL_PROVIDER_EVIDENCE",
    "capture": "WAITING_OPERATOR_SAMPLE",
    "platform": "WAITING_PLATFORM",
    "offline": "REQUIRES_CURRENT_PART_A_EVIDENCE",
    "security": "WAITING_REVIEW",
}


def digest(value: Any) -> str:
    return hashlib.sha256(rfc8785.dumps(value)).hexdigest()


def provider_config_scope(config: LiveConfig) -> dict[str, Any]:
    cfg = config.public
    return {
        "provider": cfg["provider"],
        "max_run_minutes": cfg["runtime"]["max_run_minutes"],
        "max_matches": cfg["runtime"]["max_matches"],
        **({"credentials": cfg["credentials"]} if "credentials" in cfg else {}),
    }


def _read(path: Path, root: Path) -> tuple[dict[str, Any], str]:
    path = private_path(str(path.relative_to(root)), root=root, must_exist=True)
    if path.stat().st_size > 16 * 1024 * 1024:
        raise ValueError("E_LIVE_EVIDENCE_SIZE")
    raw = path.read_bytes()
    value = parse_strict_json(raw)
    if type(value) is not dict:
        raise ValueError("E_LIVE_EVIDENCE_OBJECT")
    return value, hashlib.sha256(raw).hexdigest()


def _expires(value: Any, now: datetime) -> datetime:
    expiry = datetime.fromisoformat(value)
    if expiry.utcoffset() != timedelta(0) or not now < expiry <= now + timedelta(days=1):
        raise ValueError("E_LIVE_REVIEW_EXPIRED")
    return expiry


def _host_trust_binding(root: Path) -> str:
    """Bind only configured public trust material and current boot; never a private key."""
    from tools.issue_review_launch_authorization import _regular_hash, review_public_key

    config_path = root / "review-config/review-authority.v1.json"
    config_hash = _regular_hash(config_path)
    config = json.loads(config_path.read_text())
    _, epoch = review_public_key(config)
    return digest(
        {
            "config": config_hash,
            "public_record": _regular_hash(Path(config["public_key_path"])),
            "epoch": epoch,
            "boot": Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
        }
    )


@dataclass(frozen=True)
class _VerifiedExternalReview:
    binding: str
    root: Path
    context: dict[str, Any]
    authority: dict[str, Any]
    trust_binding: str
    expires_at: datetime
    deadline_mono: float
    _proof: object = field(repr=False)
    _pid: int


def recheck_external_review(
    verified: _VerifiedExternalReview,
    bundle: dict[str, Any],
    scope: dict[str, Any],
    root: Path,
    now: datetime,
) -> None:
    from tools.issue_review_launch_authorization import (
        recheck_review_context,
        validate_review_authority_state,
    )

    if (
        type(verified) is not _VerifiedExternalReview
        or verified._proof is not _SEAL
        or verified._pid != os.getpid()
        or verified.root != root
        or verified.binding != digest({"bundle": bundle, "scope": scope})
        or now >= verified.expires_at
        or time.monotonic() >= verified.deadline_mono
        or _host_trust_binding(root) != verified.trust_binding
    ):
        raise ValueError("E_LIVE_EXTERNAL_REVIEW")
    recheck_review_context(verified.context)
    validate_review_authority_state(bundle["authorization"], verified.authority)
    if datetime.now(UTC) >= verified.expires_at or time.monotonic() >= verified.deadline_mono:
        raise ValueError("E_LIVE_REVIEW_EXPIRED")


def verify_external_review(
    bundle: dict[str, Any], scope: dict[str, Any], root: Path, now: datetime
) -> _VerifiedExternalReview:
    """Consume existing host-signed receipts. Never initialize/sign host authority."""
    from tools.issue_review_launch_authorization import (
        _scope_record,
        authorized_review_context,
        recheck_review_context,
        review_public_key,
        validate_review_authority_state,
        validate_review_scope,
    )

    from .review_aggregation import _review_is_well_formed
    from .review_authorization import verify_review_execution_receipt, verify_review_result_binding

    if (
        set(bundle) != {"schema_version", "scope", "result", "authorization", "receipt"}
        or bundle["schema_version"] != "part-b-review-evidence/v1"
        or digest(bundle["scope"]) != digest(scope)
    ):
        raise ValueError("E_LIVE_EXTERNAL_REVIEW")
    expires = _expires(scope["expires_at"], now)
    result, authorization, receipt = (bundle[k] for k in ("result", "authorization", "receipt"))
    _review_is_well_formed(result, "CYBERSECURITY_REVIEWER", current=True)
    verify_review_result_binding(result, authorization)
    head = subprocess.check_output(
        ["/usr/bin/git", "rev-parse", "HEAD"], cwd=root, text=True
    ).strip()  # noqa: S603 -- exact read-only checkout identity.
    if (
        result["repository_commit_oid"] != head
        or result["review_outcome"] != "PASS"
        or any(
            v != ("NONE" if k == "AUTHORIZED_PRODUCTION_PHASES" else "YES")
            for k, v in result["verdicts"].items()
        )
        or any(f["blocking"] for f in result["findings"])
        or len([f for f in result["findings"] if f["finding_id"] == "PART-B-SCOPE"]) != 1
        or not any(
            f["finding_id"] == "PART-B-SCOPE" and f["evidence_ids"] == ["sha256:" + digest(scope)]
            for f in result["findings"]
        )
    ):
        raise ValueError("E_LIVE_REVIEW_SCOPE")
    # Only the configured public record is read. No caller-supplied trust key is accepted.
    authority_path = root / "review-config/review-authority.v1.json"
    if any(p.is_symlink() for p in (authority_path, *authority_path.parents)):
        raise ValueError("E_LIVE_REVIEW_TRUST")
    authority = json.loads(authority_path.read_text())
    public, epoch = review_public_key(authority)
    context = authorized_review_context(authorization, authority, runtime_root=root)
    review_config = context["config"]
    if (
        not isinstance(review_config, dict)
        or review_config.get("schema_version") != "review-config/v3"
    ):
        raise ValueError("E_LIVE_REVIEW_SCOPE")
    record, _ = _scope_record(review_config)
    if digest(record["scope"]) != digest(scope):
        raise ValueError("E_LIVE_REVIEW_SCOPE")
    validate_review_scope(review_config, result)
    validate_review_authority_state(authorization, authority)
    verify_review_execution_receipt(
        receipt,
        authorization,
        public,
        result_sha256=digest(result),
        expected_host_boot_id=Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
        expected_trust_epoch=epoch,
        now=now,
    )
    recheck_review_context(context)
    validate_review_authority_state(authorization, authority)
    expires = min(expires, datetime.fromisoformat(authorization["expires_at"]))
    observed_now = datetime.now(UTC)
    if observed_now >= expires:
        raise ValueError("E_LIVE_REVIEW_EXPIRED")
    return _VerifiedExternalReview(
        digest({"bundle": bundle, "scope": scope}),
        root,
        context,
        authority,
        _host_trust_binding(root),
        expires,
        time.monotonic() + (expires - observed_now).total_seconds(),
        _SEAL,
        os.getpid(),
    )


def verify_profile_review(
    profile: dict[str, Any], review: dict[str, Any], evidence: ProfileEvidence
) -> _VerifiedExternalReview:
    scope = review.get("scope", {})
    expected = {
        "kind",
        "source_tree_sha256",
        "capture_source_sha256",
        "profile_sha256",
        "bindings",
        "sample_refs",
        "expires_at",
        "max_matches",
    }
    if (
        set(scope) != expected
        or scope["kind"] != "CAPTURE_PROFILE"
        or scope["source_tree_sha256"] != source_tree_hash(evidence.root)
        or scope["capture_source_sha256"] != capture_source_hash(evidence.root)
        or scope["profile_sha256"] != digest(profile)
        or scope["bindings"] != list(evidence.fixture_bindings)
        or scope["max_matches"] != profile["max_matches"]
        or profile["source_kind"] != "OBSERVED_REAL"
    ):
        raise ValueError("E_LIVE_CAPTURE_REVIEW")
    actual = {
        str(p.relative_to(evidence.root)): hashlib.sha256(p.read_bytes()).hexdigest()
        for p in evidence.sample_paths
    }
    if scope["sample_refs"] != actual:
        raise ValueError("E_LIVE_CAPTURE_SAMPLES")
    return verify_external_review(review, scope, evidence.root, evidence.now_utc)


@dataclass(frozen=True)
class EvidenceIndex:
    artifacts: dict[str, Any]
    checks: frozenset[str] = frozenset()
    config_sha256: str = ""
    source_sha256: str = ""
    root: Path = ROOT
    paths: dict[str, str] = field(default_factory=dict)
    profile: ExtractionProfile | None = field(default=None, repr=False)
    bindings: tuple[dict[str, Any], ...] = ()
    expires_at: datetime | None = None
    _proof: object = field(default=None, repr=False)
    _pid: int = field(default=0, repr=False)
    config_binding: str = ""
    trust_binding: str = ""
    review_proofs: dict[str, _VerifiedExternalReview] = field(default_factory=dict, repr=False)


@dataclass(frozen=True)
class Readiness:
    live_read_only_ready: bool
    missing_inputs: tuple[str, ...]
    key_status: str
    independent_review: str = "NOT_RUN"
    model_enabled: bool = False
    money_ready: bool = False


def evaluate_live_readiness(
    config: LiveConfig, verified: EvidenceIndex, key_present: bool | None
) -> Readiness:
    """Pure decision over a locally verified snapshot; never tests a real credential."""
    if (
        type(config) is not LiveConfig
        or type(verified) is not EvidenceIndex
        or (key_present is not None and type(key_present) is not bool)
    ):
        raise ValueError("E_LIVE_PREFLIGHT_TYPE")
    trusted = (
        verified._proof is _SEAL
        and verified._pid == os.getpid()
        and verified.config_sha256 == config.sha256
        and verified.config_binding == digest(config.public)
        and verified.expires_at is not None
        and datetime.now(UTC) < verified.expires_at
    )
    checks = verified.checks if trusted else frozenset()
    missing = [message for name, message in REQUIRED.items() if name not in checks]
    if not config.enabled:
        missing.append("LIVE_CONFIG_DISABLED")
    if not config.fixture_ids:
        missing.append("WAITING_MATCH_WINDOW")
    if not key_present:
        missing.append("WAITING_FOR_USER_SECRET")
    return Readiness(
        not missing,
        tuple(missing),
        "NOT_CHECKED"
        if key_present is None
        else "PRESENT_NOT_AUTHENTICATED"
        if key_present
        else "NOT_PRESENT",
        "VERIFIED_HOST_RECEIPT"
        if "security" in checks
        else "SELF_ONLY"
        if verified.artifacts.get("security", {}).get("review_kind") == "SELF_ONLY"
        else "NOT_RUN",
    )


def load_evidence(config: LiveConfig, *, root: Path = ROOT) -> EvidenceIndex:
    """Read/recheck only configured nonsecret artifacts; no browser or provider I/O."""
    cfg, now = config.public, datetime.now(UTC)
    source = source_tree_hash(root)
    refs = {
        "provider": cfg["gates"]["provider_feasibility_path"],
        "capture": cfg["gates"]["capture_review_path"],
        "profile": cfg["operator"]["capture_profile_path"],
        "platform": cfg["runtime"]["platform_qualification_path"],
        "offline": cfg["gates"]["offline_result_path"],
        "security": cfg["gates"]["security_review_path"],
    }
    artifacts, paths, raw_hashes = {}, {}, {}
    checks: set[str] = set()
    profile = None
    trust_binding = ""
    review_proofs = {}
    bindings: tuple[dict[str, Any], ...] = ()
    expiry = now + timedelta(
        minutes=1
    )  # Snapshot expires quickly; real run rechecks retained bindings.
    for name, ref in refs.items():
        if ref is None:
            continue
        try:
            artifacts[name], raw_hashes[name] = _read(root / ref, root)
            paths[ref] = raw_hashes[name]
        except (ValueError, OSError, TypeError):
            continue
    try:
        p = artifacts["provider"]
        ev = p["evidence"]
        if (
            p["PROBE_RESULT"] != "PASS"
            or p["KEY_CHECK"] != "AUTHENTICATED"
            or p["SUBSCRIPTION_CHECK"] != "CONFIRMED"
            or ev["source_kind"] != "OBSERVED_REAL"
            or p["source_tree_sha256"] != source
            or p["provider_config_scope"] != provider_config_scope(config)
            or ev["fixture_ids"] != list(config.fixture_ids)
            or p["finished_before_deadline"] is not True
            or not 0 < p["REQUEST_ATTEMPTS"] == ev["http_attempts"] <= 20
            or len(ev["requests"]) != ev["http_attempts"]
            or not 0 <= ev["elapsed_us"] <= 300000000
            or not now - timedelta(hours=24) <= datetime.fromisoformat(p["finished_at_utc"]) <= now
        ):
            raise ValueError()
        if len(ev["observations"]) != 2:
            raise ValueError()
        for row in ev["observations"]:
            if (
                row["missing_ids"]
                or row["rejected"]
                or {int(k) for k in row["states"]} != set(config.fixture_ids)
            ):
                raise ValueError()
            for state in row["states"].values():
                validate_live_record(state, "ProviderState")
        checks.add("provider")
    except (ValueError, KeyError, TypeError):
        pass
    try:
        review, value = artifacts["capture"], artifacts["profile"]
        scope = review["scope"]
        bindings = tuple(validate_live_record(b, "FixtureBinding") for b in scope["bindings"])
        sample_paths = []
        for ref, expected in scope["sample_refs"].items():
            sample, actual = _read(root / ref, root)
            if actual != expected or sample["source_kind"] != "OBSERVED_REAL":
                raise ValueError()
            paths[ref] = actual
            sample_paths.append(root / ref)
        if raw_hashes["profile"] != cfg["operator"]["profile_evidence_hash"]:
            raise ValueError()
        profile = validate_extraction_profile(
            value, ProfileEvidence(root, now, tuple(sample_paths), root / refs["capture"], bindings)
        )
        if type(profile._review_proof) is not _VerifiedExternalReview:
            raise ValueError("E_LIVE_CAPTURE_REVIEW")
        review_proofs["capture"] = profile._review_proof
        if (
            not profile._real_admitted
            or profile.public["max_matches"] != cfg["runtime"]["max_matches"]
            or {b["provider_fixture_id"] for b in bindings} != set(config.fixture_ids)
            or {b["binding_id"] for b in bindings}
            != set(cfg["operator"]["allowed_fixture_bindings"])
            or any(
                b["orientation_status"] != "VERIFIED"
                or b["league_id"] != cfg["provider"]["league_id"]
                or b["season"] != cfg["provider"]["season"]
                for b in bindings
            )
        ):
            raise ValueError()
        states = artifacts["provider"]["evidence"]["observations"][-1]["states"]
        for binding in bindings:
            state = states[str(binding["provider_fixture_id"])]
            if (
                state["home_id"] != binding["home_id"]
                or state["away_id"] != binding["away_id"]
                or datetime.fromisoformat(state["kickoff_utc"])
                != datetime.fromisoformat(binding["kickoff_utc"])
            ):
                raise ValueError()
        checks.add("capture")
    except (ValueError, KeyError, TypeError, OSError):
        profile = None
    try:
        p = artifacts["platform"]
        if (
            p["status"] != "PASS"
            or p["platform"] != cfg["runtime"]["platform"]
            or p["source_tree_sha256"] != source
            or p["exit"] != 0
            or p["source_kind"] != "SYNTHETIC"
            or p["operator_observed"] is not False
            or p["real_provider_attempts"] != 0
            or p["test_source_sha256"]
            != hashlib.sha256((root / "tests/live/test_local_bridge.py").read_bytes()).hexdigest()
        ):
            raise ValueError()
        parent = (root / refs["platform"]).parent
        observed = []
        for ref, expected in p["evidence"].items():
            path = private_path(str((parent / ref).relative_to(root)), root=root, must_exist=True)
            if hashlib.sha256(path.read_bytes()).hexdigest() != expected:
                raise ValueError()
            if path.name == "observed-bridge.json":
                observed.append(json.loads(path.read_text()))
        if (
            len(observed) != 1
            or observed[0]["platform"] != p["platform"]
            or observed[0]["bound_addresses"] != ["127.0.0.1"]
        ):
            raise ValueError()
        checks.add("platform")
    except (ValueError, KeyError, TypeError, OSError):
        pass
    try:
        # The full verifier runs separately. Here its retained outputs are reopened and
        # later pinned by the host-signed enabled-surface review, never replaced by flags.
        p = artifacts["offline"]
        from tools.offline_harness import source_hashes
        from tools.verify_offline_slice import artifact

        current = hashlib.sha256(json.dumps(source_hashes(), sort_keys=True).encode()).hexdigest()
        if (
            p["OFFLINE_SLICE_PASS"] != "YES"  # noqa: S105 -- public status, not a credential.
            or p["provenance"]["source_tree_sha256"] != current
            or [r["case_id"] for r in p["records"]] != [f"OFF-{i:02d}" for i in range(1, 28)]
        ):
            raise ValueError()
        parent = (root / refs["offline"]).parent
        for row in p["records"]:
            if (
                row["status"] != "PASS"
                or row["executed"] is not True
                or row["command_exit"] != 0
                or not row["artifacts"]
            ):
                raise ValueError()
            for ref in row["artifacts"]:
                artifact(parent, ref)
        checks.add("offline")
    except (ValueError, KeyError, TypeError, OSError):
        pass
    try:
        review = artifacts["security"]
        scope = review["scope"]
        expected = {
            "kind": "LIVE_SECURITY",
            "source_tree_sha256": source,
            "config_sha256": config.sha256,
            "artifacts": {
                k: raw_hashes[k] for k in ("provider", "capture", "profile", "platform", "offline")
            },
            "max_matches": cfg["runtime"]["max_matches"],
            "expires_at": scope["expires_at"],
            "previous_scope_refs": scope.get("previous_scope_refs", {}),
        }
        review_proofs["security"] = verify_external_review(review, expected, root, now)
        if cfg["runtime"]["max_matches"] != 1:
            # PB-22's actual preceding bounded run must be verified before larger capacity.
            importlib.import_module("tools.qualify_live_readonly").verify_preceding_scope(
                config, review, root
            )
        expiry = min(
            _expires(scope["expires_at"], now),
            _expires(artifacts["capture"]["scope"]["expires_at"], now),
            _expires(review["authorization"]["expires_at"], now),
            _expires(artifacts["capture"]["authorization"]["expires_at"], now),
        )
        trust_binding = _host_trust_binding(root)
        checks.add("security")
    except (ValueError, KeyError, TypeError, OSError, ImportError):
        pass
    return EvidenceIndex(
        artifacts,
        frozenset(checks),
        config.sha256,
        source,
        root,
        paths,
        profile,
        bindings,
        expiry,
        _SEAL,
        os.getpid(),
        digest(config.public),
        trust_binding,
        review_proofs,
    )


@dataclass(frozen=True)
class _LiveAuthority:
    evidence: EvidenceIndex
    receipt: RunIntentReceipt
    binding: str
    receiver_binding: str
    _proof: object = field(default=None, repr=False)


def _admission_binding(admitted: Any) -> str:
    return digest(
        {
            "run_id": admitted.run_id,
            "config": admitted.config_sha256,
            "source": admitted.source_tree_sha256,
            "origin": admitted.extension_origin,
            "deadline": admitted.deadline_mono,
            "bindings": admitted.bindings,
            "profile": admitted.profile.public,
            "streams": admitted.capture_streams,
            "source_kind": admitted.source_kind,
        }
    )


def _check_live_review_authority(verified: EvidenceIndex) -> None:
    from tools.issue_review_launch_authorization import validate_review_authority_state

    authority = json.loads((verified.root / "review-config/review-authority.v1.json").read_bytes())
    for name in ("capture", "security"):
        validate_review_authority_state(verified.artifacts[name]["authorization"], authority)


def verify_live_receipt(receipt: RunIntentReceipt) -> _LiveAuthority:
    authority = receipt._live_authority
    if (
        type(authority) is not _LiveAuthority
        or authority._proof is not _SEAL
        or authority.receipt is not receipt
    ):
        raise ValueError("E_LIVE_AUTHORITY")
    verified = authority.evidence
    verify_receipt(receipt, "LIVE_READ_ONLY")
    if (
        not evaluate_live_readiness(receipt.config, verified, True).live_read_only_ready
        or source_tree_hash(verified.root) != verified.source_sha256
        or _host_trust_binding(verified.root) != verified.trust_binding
    ):
        raise ValueError("E_LIVE_AUTHORITY_STALE")
    for path, expected in verified.paths.items():
        if _read(verified.root / path, verified.root)[1] != expected:
            raise ValueError("E_LIVE_AUTHORITY_DRIFT")
    _check_live_review_authority(verified)
    return authority


def verify_run_admission(config: LiveConfig, admitted: Any) -> None:
    authority = verify_live_receipt(admitted.provider_receipt)
    if (
        config.sha256 != authority.evidence.config_sha256
        or admitted.security_evidence is not authority
        or _admission_binding(admitted) != authority.binding
        or admitted.source_kind != "OBSERVED_REAL"
    ):
        raise ValueError("E_LIVE_ADMISSION_BINDING")


def verify_receiver_authority(context: dict[str, Any]) -> None:
    authority = context.get("authority")
    if type(authority) is not _LiveAuthority:
        raise ValueError("E_LIVE_RECEIVER_AUTHORITY")
    verify_live_receipt(authority.receipt)
    if digest({k: v for k, v in context.items() if k != "authority"}) != authority.receiver_binding:
        raise ValueError("E_LIVE_RECEIVER_AUTHORITY")


def recheck_live_evidence(config: LiveConfig, verified: EvidenceIndex) -> None:
    if (
        not evaluate_live_readiness(config, verified, True).live_read_only_ready
        or set(verified.review_proofs) != {"capture", "security"}
        or source_tree_hash(verified.root) != verified.source_sha256
    ):
        raise ValueError("E_LIVE_ADMISSION_PENDING")
    for path, expected in verified.paths.items():
        if _read(verified.root / path, verified.root)[1] != expected:
            raise ValueError("E_LIVE_AUTHORITY_DRIFT")
    for name, proof in verified.review_proofs.items():
        bundle = verified.artifacts[name]
        recheck_external_review(proof, bundle, bundle["scope"], verified.root, datetime.now(UTC))
    if not evaluate_live_readiness(config, verified, True).live_read_only_ready:
        raise ValueError("E_LIVE_ADMISSION_PENDING")


def admit_live_run(
    config: LiveConfig,
    receipt: RunIntentReceipt,
    *,
    verified: EvidenceIndex | None = None,
) -> Any:
    from tools.qualify_chrome_indexeddb import _extension_id

    from .live_service import RunAdmission

    if verified is None or verified.profile is None:
        raise ValueError("E_LIVE_ADMISSION_PENDING")
    recheck_live_evidence(config, verified)
    verify_receipt(receipt, "LIVE_READ_ONLY")
    if receipt.config.sha256 != config.sha256 or receipt.intent.root != ROOT:
        raise ValueError("E_LIVE_ADMISSION_CONFIG")
    if receipt.intent.public["operator_urls"] != [
        binding["operator_match_url"]
        for binding in sorted(verified.bindings, key=lambda b: b["provider_fixture_id"])
    ]:
        raise ValueError("E_LIVE_INTENT_OPERATOR_URL")
    claim_receipt(receipt, "LIVE_READ_ONLY")
    streams = {}
    for binding in verified.bindings:
        markets = verified.profile.observed_markets[binding["operator_fixture_id"]]
        streams[str(uuid4())] = {
            "binding_id": binding["binding_id"],
            "binding_revision": binding["revision"],
            "operator_fixture_id": binding["operator_fixture_id"],
            "generation": "0",
            "profile_hash": verified.profile.profile_hash,
            "document_epoch": str(uuid4()),
            "markets": {
                m["horizon"]: {"market_id": m["market_id"], "selections": m["selections"]}
                for m in markets
            },
        }
    manifest = json.loads((ROOT / "extension/manifest.live.json").read_text())
    admitted = RunAdmission(
        ROOT,
        receipt.run_id,
        config.sha256,
        verified.source_sha256,
        "chrome-extension://" + _extension_id(manifest["key"]),
        receipt.deadline_mono,
        copy.deepcopy(verified.bindings),
        verified.profile,
        streams,
        "OBSERVED_REAL",
        receipt,
    )
    receiver_binding = digest(
        {
            "run_id": admitted.run_id,
            "allowed_extension_origin": admitted.extension_origin,
            "deadline_mono": admitted.deadline_mono,
            "source_kind": admitted.source_kind,
            "capture_streams": admitted.capture_streams,
        }
    )
    authority = _LiveAuthority(
        verified, receipt, _admission_binding(admitted), receiver_binding, _SEAL
    )
    object.__setattr__(receipt, "_live_authority", authority)
    object.__setattr__(admitted, "security_evidence", authority)
    verify_run_admission(config, admitted)
    return admitted"""Pure lane-A preflight. It cannot validate future LV approvals or activate live access."""

import math
import re
from collections.abc import Mapping
from typing import Any


def check_live_readiness(
    config: Mapping[str, Any], evidence: Mapping[str, Any], secret_presence: Mapping[str, bool]
) -> dict[str, Any]:
    if (
        not isinstance(config, Mapping)
        or not isinstance(evidence, Mapping)
        or not isinstance(secret_presence, Mapping)
    ):
        raise ValueError("E_LIVE_CONFIG_TYPE")
    if any(not isinstance(value, Mapping) for value in evidence.values()) or any(
        type(value) is not bool for value in secret_presence.values()
    ):
        raise ValueError("E_LIVE_EVIDENCE_TYPE")
    expected = {
        "schema_version",
        "mode",
        "enabled",
        "provider",
        "operator",
        "runtime",
        "gates",
        "model_enabled",
        "paper_enabled",
        "money_enabled",
        "cashout_submission_enabled",
    }
    if (
        set(config) != expected
        or config["schema_version"] != "bh-live-readonly-config/v1"
        or config["mode"] != "LIVE_READ_ONLY"
        or type(config["enabled"]) is not bool
        or any(
            config[name] is not False
            for name in [
                "model_enabled",
                "paper_enabled",
                "money_enabled",
                "cashout_submission_enabled",
            ]
        )
    ):
        raise ValueError("E_LIVE_CONFIG_SCOPE")
    provider, operator, runtime, gates = (
        config[name] for name in ["provider", "operator", "runtime", "gates"]
    )
    shapes = [
        (
            provider,
            {
                "id",
                "base_url",
                "api_key_env",
                "fixture_ids",
                "poll_fixture_seconds",
                "poll_events_seconds",
                "max_requests_per_run",
                "max_requests_per_minute",
            },
        ),
        (
            operator,
            {
                "capture_profile_path",
                "profile_evidence_hash",
                "user_session_present",
                "allowed_fixture_bindings",
            },
        ),
        (
            runtime,
            {"host", "port", "max_matches", "max_run_minutes", "platform_qualification_path"},
        ),
        (
            gates,
            {
                "offline_result_path",
                "security_review_path",
                "provider_feasibility_path",
                "live_run_authorization_path",
            },
        ),
    ]
    if any(not isinstance(value, dict) or set(value) != keys for value, keys in shapes):
        raise ValueError("E_LIVE_CONFIG_FIELDS")
    if (
        provider["id"] != "API_FOOTBALL_V3"
        or provider["base_url"] != "https://v3.football.api-sports.io"
        or not isinstance(provider["api_key_env"], str)
        or not re.fullmatch("[A-Z][A-Z0-9_]{0,63}", provider["api_key_env"])
        or runtime["host"] != "127.0.0.1"
        or type(runtime["port"]) is not int
        or runtime["port"] != 8765
    ):
        raise ValueError("E_LIVE_CONFIG_BINDING")
    bounds = [
        (runtime["max_matches"], 1, 1),
        (runtime["max_run_minutes"], 1, 120),
        (provider["poll_fixture_seconds"], 30, 3600),
        (provider["poll_events_seconds"], 30, 3600),
        (provider["max_requests_per_run"], 1, 500),
        (provider["max_requests_per_minute"], 1, 8),
    ]
    if any(type(value) is not int or not low <= value <= high for value, low, high in bounds):
        raise ValueError("E_LIVE_CONFIG_LIMIT")
    fixtures = provider["fixture_ids"]
    if (
        not isinstance(fixtures, list)
        or len(fixtures) > runtime["max_matches"]
        or any(type(value) is not int or value <= 0 for value in fixtures)
        or type(operator["user_session_present"]) is not bool
        or not isinstance(operator["allowed_fixture_bindings"], list)
    ):
        raise ValueError("E_LIVE_CONFIG_FIXTURE")
    paths = [
        operator["capture_profile_path"],
        runtime["platform_qualification_path"],
        *gates.values(),
    ]
    if any(
        value is not None and (not isinstance(value, str) or not value or len(value) > 4096)
        for value in paths
    ):
        raise ValueError("E_LIVE_CONFIG_PATH")
    digest = operator["profile_evidence_hash"]
    if digest is not None and (
        not isinstance(digest, str) or not re.fullmatch("[a-f0-9]{64}", digest)
    ):
        raise ValueError("E_LIVE_CONFIG_HASH")
    estimate = 1 + sum(
        math.ceil(runtime["max_run_minutes"] * 60 / provider[field])
        for field in ["poll_fixture_seconds", "poll_events_seconds"]
    )
    minute_estimate = 1 + sum(
        math.ceil(60 / provider[field]) for field in ["poll_fixture_seconds", "poll_events_seconds"]
    )
    within_budget = (
        estimate <= provider["max_requests_per_run"]
        and minute_estimate <= provider["max_requests_per_minute"]
    )
    checks = {
        "offline_gate": "REQUIRES_OFFLINE_GATE_VERIFICATION"
        if "offline_gate" in evidence
        else "PENDING_OFFLINE_GATE",
        "provider_key": "ENV_NAME_PRESENT_UNVALIDATED"
        if secret_presence.get(provider["api_key_env"]) is True
        else "PENDING_KEY",
        "fixture_selection": "SELECTED_UNVALIDATED" if fixtures else "PENDING_FIXTURE",
        "operator_session": "PENDING_MANUAL_OPERATOR_SESSION"
        if not operator["user_session_present"]
        else "SESSION_CLAIM_REQUIRES_LV_REVIEW",
        "operator_fixture_binding": "PENDING_FIXTURE_BINDING"
        if not operator["allowed_fixture_bindings"]
        else "BINDING_REQUIRES_LV_REVIEW",
        "quota_budget": "PENDING_OBSERVED_QUOTA"
        if within_budget
        else "INSUFFICIENT_CONFIGURED_BUDGET",
    }
    for name in [
        "capture_profile",
        "provider_feasibility",
        "platform_qualification",
        "security_review",
        "live_run_authorization",
    ]:
        checks[name] = (
            "PENDING_REAL_INPUTS" if name not in evidence else "REQUIRES_LV_EVIDENCE_REVIEW"
        )
        if evidence.get(name, {}).get("source_kind") == "SYNTHETIC_TEST":
            checks[name] = "SYNTHETIC_NOT_LIVE_EVIDENCE"
    return {
        "LIVE_PREFLIGHT_IMPLEMENTED": "YES",
        "LIVE_READ_ONLY_READY": "PENDING_REAL_INPUTS_AND_LIVE_REVIEW",
        "MONEY_READY": "NO",
        "production_authority": "NONE",
        "status": "PENDING_REAL_INPUTS",
        "evaluation_scope": "SYNTHETIC_PREFLIGHT_ONLY",
        "checks": checks,
        "estimated_requests": estimate,
        "estimated_requests_first_minute": minute_estimate,
        "missing_inputs": [name for name, value in checks.items() if value != "PASS"],
    }"""Authenticated bounded /live receiver. No provider endpoints or generic commands."""

import asyncio
import copy
import importlib
import logging
import math
import re
import secrets
import time
from collections import deque
from collections.abc import Awaitable, Callable
from datetime import UTC, datetime
from http import HTTPStatus
from typing import Any
from uuid import UUID, uuid4, uuid5

from websockets.asyncio.server import Server, ServerConnection, serve
from websockets.exceptions import ConnectionClosed
from websockets.http11 import Request, Response
from websockets.protocol import State
from websockets.typing import Origin

from .live_contracts import event_hash
from .live_store import LiveStore
from .live_wire import LiveSession, PairingAuthority, validate_frame

HEALTH = {
    "HIDDEN": "STALE_MARKET",
    "NAVIGATED": "CONTEXT_UNVERIFIED",
    "DOM_UNSTABLE": "STALE_MARKET",
    "PROFILE_EXPIRED": "PROFILE_EXPIRED",
    "SPOOL_CAPACITY": "PAUSED",
    "DISCONNECTED": "CONTEXT_UNVERIFIED",
    "WORKER_RESTART": "CONTEXT_UNVERIFIED",
    "USER_STOP": "STOPPED",
    "PAIRING_RENEWED": "CONTEXT_UNVERIFIED",
    "CAPTURE_REJECTED": "CONTEXT_UNVERIFIED",
}


class LiveReceiver:
    def connected(self, role: str) -> bool:
        return role in self._active

    def __init__(self, context: dict[str, Any], store: LiveStore, pairing: PairingAuthority):
        self.context = copy.deepcopy(context)
        self.store, self.pairing = store, pairing
        self._validate_context()
        self.server: Server | None = None
        self._reserved: set[ServerConnection] = set()
        self._active: dict[str, tuple[ServerConnection, LiveSession, bytes]] = {}
        self._send_locks: dict[ServerConnection, asyncio.Lock] = {}
        self._send_pending: dict[ServerConnection, int] = {}
        self._intake = asyncio.Lock()
        self._stopped_bindings: set[str] = set()
        self.rejections: deque[str] = deque(maxlen=128)
        self.on_ui: Callable[[str, str | None], Awaitable[None]] | None = None
        self.on_capture: Callable[[dict[str, Any]], Awaitable[None]] | None = None
        self.on_change: Callable[[str | None, str], Awaitable[None]] | None = None

    def _validate_context(self) -> None:
        try:
            c = self.context
            required = {
                "run_id",
                "allowed_extension_origin",
                "deadline_mono",
                "source_kind",
                "capture_streams",
            }
            if (
                set(c) not in (required, required | {"authority"})
                or c["run_id"] != self.store.run_id
                or c["run_id"] != self.pairing.run_id
                or c["deadline_mono"] != self.pairing.deadline
                or not math.isfinite(c["deadline_mono"])
                or not 0 < c["deadline_mono"] - time.monotonic() <= 7200
                or not re.fullmatch(r"chrome-extension://[a-p]{32}", c["allowed_extension_origin"])
                or c["source_kind"] not in {"MOCK", "OBSERVED_REAL"}
            ):
                raise ValueError()
            streams = c["capture_streams"]
            if type(streams) is not dict or not 1 <= len(streams) <= 5:
                raise ValueError()
            bindings = self.store.bindings()
            seen = set()
            for stream_id, scope in streams.items():
                if str(UUID(stream_id)) != stream_id or set(scope) != {
                    "binding_id",
                    "binding_revision",
                    "operator_fixture_id",
                    "generation",
                    "profile_hash",
                    "document_epoch",
                    "markets",
                }:
                    raise ValueError()
                binding = bindings[scope["binding_id"]]
                if (
                    scope["binding_id"] in seen
                    or binding["revision"] != scope["binding_revision"]
                    or binding["operator_fixture_id"] != scope["operator_fixture_id"]
                    or not re.fullmatch(r"[0-9a-f]{64}", scope["profile_hash"])
                    or not re.fullmatch(r"0|[1-9][0-9]{0,18}", scope["generation"])
                    or int(scope["generation"]) > 2**63 - 1
                ):
                    raise ValueError()
                UUID(scope["document_epoch"])
                seen.add(scope["binding_id"])
                if not scope["markets"] or not set(scope["markets"]) <= {"H1", "H2", "FT"}:
                    raise ValueError()
                for market in scope["markets"].values():
                    if (
                        set(market) != {"market_id", "selections"}
                        or set(market["selections"]) != {"HOME", "DRAW", "AWAY"}
                        or len(set(market["selections"].values())) != 3
                        or any(
                            type(i) is not str or not 1 <= len(i) <= 128
                            for i in (market["market_id"], *market["selections"].values())
                        )
                    ):
                        raise ValueError()
            if c["source_kind"] == "OBSERVED_REAL":
                # PB-16 verifies admitted evidence; a context flag never authorizes real capture.
                importlib.import_module(
                    "moj_discovery.live_preflight_batched"
                ).verify_receiver_authority(c)
        except Exception:
            raise ValueError("E_LIVE_RECEIVER_CONTEXT") from None

    async def start(self) -> None:
        logger = logging.Logger("live-wire", level=logging.CRITICAL)
        logger.propagate = False
        logger.addHandler(logging.NullHandler())
        self.server = await serve(
            self._connection,
            "127.0.0.1",
            8765,
            origins=[Origin(self.context["allowed_extension_origin"])],
            compression=None,
            max_size=262144,
            max_queue=8,
            write_limit=32768,
            open_timeout=5,
            close_timeout=3,
            process_request=self._request,
            logger=logger,
        )

    async def close(self) -> None:
        self.pairing.revoke()
        if self.server is not None:
            self.server.close()
            await self.server.wait_closed()

    def _request(self, socket: ServerConnection, request: Request) -> Response | None:
        self._reserved = {s for s in self._reserved if s.state is not State.CLOSED}
        if (
            request.path != "/live"
            or request.headers.get_all("Host") != ["127.0.0.1:8765"]
            or request.headers.get_all("Origin") != [self.context["allowed_extension_origin"]]
        ):
            self.rejections.append("HTTP_BINDING")
            return socket.respond(HTTPStatus.FORBIDDEN, "HTTP_BINDING")
        if len(self._reserved) >= 2 or time.monotonic() >= self.context["deadline_mono"]:
            return socket.respond(HTTPStatus.SERVICE_UNAVAILABLE, "CAPACITY_OR_LEASE")
        self._reserved.add(socket)
        self._send_locks[socket] = asyncio.Lock()
        self._send_pending[socket] = 0
        return None

    async def _send(
        self, peer: tuple[ServerConnection, LiveSession, bytes], kind: str, body: dict[str, Any]
    ) -> None:
        socket, session, key = peer
        if self._send_pending.get(socket, 8) >= 8:
            raise ValueError("E_LIVE_WIRE_BACKPRESSURE")
        self._send_pending[socket] += 1
        try:
            async with self._send_locks[socket]:
                encoded = session.send(kind, body, key)
                await asyncio.wait_for(socket.send(encoded.decode()), 5)
        finally:
            self._send_pending[socket] = max(0, self._send_pending.get(socket, 1) - 1)

    async def publish(self, body: dict[str, Any], *, role: str = "UI_SUBSCRIBER") -> None:
        if role not in {"UI_SUBSCRIBER", "CAPTURE_PRODUCER"}:
            raise ValueError("E_LIVE_PROJECTION_ROLE")
        peer = self._active.get(role)
        if peer is not None:
            try:
                await self._send(peer, "PROJECTION", body)
            except Exception:
                await peer[0].close(1008, "PROJECTION_BACKPRESSURE_OR_REJECTED")

    async def _health(self, binding_id: str | None, code: str) -> None:
        if code not in HEALTH or (
            binding_id is not None and binding_id not in self.store.bindings()
        ):
            raise ValueError("E_LIVE_HEALTH_SCOPE")
        stream = str(uuid5(UUID(self.store.run_id), "BH-LIVE-RECEIVER/health"))
        sequence, previous = self.store.cursor(stream)
        record = dict(
            protocol="BH_LIVE_READONLY_V1",
            run_id=self.store.run_id,
            source_kind="CONTROL",
            stream_id=stream,
            generation="0",
            sequence=str(sequence + 1),
            observation_id=str(uuid4()),
            observed_at_utc=datetime.now(UTC).isoformat().replace("+00:00", "Z"),
            received_mono_us=str(int(time.monotonic() * 1_000_000)),
            payload_type="HealthChange",
            payload=dict(
                binding_id=binding_id,
                reason=code,
                state=HEALTH[code],
                epoch=str(sequence + 1),
                evidence_hashes=[],
            ),
            previous_hash=previous,
            content_hash="0" * 64,
        )
        record["content_hash"] = event_hash(record)
        await asyncio.to_thread(self.store.append, record)

    def _capture_scope(self, event: dict[str, Any]) -> None:
        try:
            scope = self.context["capture_streams"][event["stream_id"]]
            book = event["payload"]
            if (
                scope["binding_id"] in self._stopped_bindings
                or event["generation"] != scope["generation"]
                or any(
                    book[k] != scope[k]
                    for k in (
                        "binding_id",
                        "binding_revision",
                        "operator_fixture_id",
                        "profile_hash",
                        "document_epoch",
                    )
                )
            ):
                raise ValueError()
            market = scope["markets"][book["horizon"]]
            if market["market_id"] != book["market_id"] or market["selections"] != {
                s: b["selection_id"] for s, b in book["selections"].items()
            }:
                raise ValueError()
            if ("SYNTHETIC" in book["quality_flags"]) != (self.context["source_kind"] == "MOCK"):
                raise ValueError()
        except Exception:
            raise ValueError("E_LIVE_CAPTURE_SCOPE") from None

    async def _batch(self, frame: dict[str, Any]) -> list[tuple[str, dict[str, Any]]]:
        validate_frame(frame)
        body = frame["body"]
        for event in body["events"]:
            self._capture_scope(event)
        identity = {k: body[k] for k in ("run_id", "stream_id", "generation", "batch_id")}
        responses = []
        last = None
        rejected = False
        for event in body["events"]:
            try:
                last = await asyncio.to_thread(self.store.append, event)
                if self.on_capture is not None:
                    await self.on_capture(event)
            except (ValueError, OSError):
                rejected = True
                break
        if last is not None:
            responses.append(
                ("ACK", {**identity, "sequence": last.sequence, "content_hash": last.content_hash})
            )
        if rejected:
            responses.append(("NACK", {**identity, "code": "CAPTURE_REJECTED"}))
        return responses

    async def _connection(self, socket: ServerConnection) -> None:
        role = None
        active = False
        try:
            hello = await asyncio.wait_for(socket.recv(), 5)
            if type(hello) is not str:
                raise ValueError("E_LIVE_FRAME_TYPE")
            session, key = self.pairing.consume(hello.encode())
            role = session.role
            peer = (socket, session, key)
            body = dict(
                run_id=self.store.run_id,
                client_nonce=session.client_nonce,
                server_nonce=secrets.token_urlsafe(32),
            )
            await self._send(peer, "WELCOME", body)
            ready = await asyncio.wait_for(
                socket.recv(), max(0, 5 - (time.monotonic() - session.started))
            )
            if type(ready) is not str:
                raise ValueError("E_LIVE_FRAME_TYPE")
            session.receive(ready.encode(), key)
            async with self._intake:
                old = self._active.get(role)
                if old is not None:
                    await old[0].close(1000, "PAIRING_RENEWED")
                self._active[role] = peer
                active = True
                if role == "CAPTURE_PRODUCER":
                    await self._health(None, "PAIRING_RENEWED")
            await self._send(peer, "READY_ACK", body)
            if self.on_change is not None:
                await self.on_change(
                    None, "PAIRING_RENEWED" if role == "CAPTURE_PRODUCER" else "SUBSCRIBED"
                )
            while time.monotonic() < self.context["deadline_mono"]:
                data = await asyncio.wait_for(
                    socket.recv(), max(0, self.context["deadline_mono"] - time.monotonic())
                )
                if type(data) is not str:
                    raise ValueError("E_LIVE_FRAME_TYPE")
                frame = session.receive(data.encode(), key)
                kind, payload = frame["message_type"], frame["body"]
                if kind == "PING":
                    await self._send(peer, "PONG", payload)
                    continue
                if kind == "PONG":
                    continue
                async with self._intake:
                    if self._active.get(role) != peer:
                        raise ValueError("E_LIVE_SESSION_REPLACED")
                    if kind == "CAPTURE_BATCH":
                        replies = await self._batch(frame)
                        for reply_kind, reply in replies:
                            await self._send(peer, reply_kind, reply)
                        if any(k == "NACK" for k, _ in replies):
                            break
                        if self.on_change is not None:
                            await self.on_change(None, "CAPTURE_COMMITTED")
                    elif kind in {"HEALTH", "STOP_CAPTURE"}:
                        if kind == "STOP_CAPTURE":
                            self._stopped_bindings.add(payload["binding_id"])
                        await self._health(
                            payload["binding_id"],
                            "USER_STOP" if kind == "STOP_CAPTURE" else payload["code"],
                        )
                        if self.on_change is not None:
                            await self.on_change(
                                payload["binding_id"],
                                "USER_STOP" if kind == "STOP_CAPTURE" else payload["code"],
                            )
                    elif self.on_ui is not None:
                        binding = payload.get("binding_id")
                        if binding is not None and binding not in self.store.bindings():
                            raise ValueError("E_LIVE_UI_SCOPE")
                        await self.on_ui(kind, binding)
                    else:
                        raise ValueError("E_LIVE_UI_NOT_READY")
        except ConnectionClosed:
            pass
        except Exception:
            self.rejections.append("CONNECTION_REJECTED")
            await socket.close(1008, "CONNECTION_REJECTED")
        finally:
            if active and role is not None and self._active.get(role, (None,))[0] is socket:
                del self._active[role]
                if role == "CAPTURE_PRODUCER":
                    async with self._intake:
                        try:
                            await self._health(None, "DISCONNECTED")
                            if self.on_change is not None:
                                await self.on_change(None, "DISCONNECTED")
                        except (ValueError, OSError):
                            self.rejections.append("HEALTH_STORAGE_FAILED")
            self._reserved.discard(socket)
            self._send_locks.pop(socket, None)
            self._send_pending.pop(socket, None)


async def serve_live_receiver(
    context: dict[str, Any], store: LiveStore, pairing: PairingAuthority
) -> LiveReceiver:
    receiver = LiveReceiver(context, store, pairing)
    await receiver.start()
    return receiver"""Rebuild a closed run from recorded canonical events into a fresh physical database."""

import fcntl
import hashlib
import os
import sqlite3
from contextlib import closing
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any

import rfc8785

from .canonical import parse_strict_json
from .live_contracts import event_hash, validate_live_record
from .live_store import MAX_BYTES, TABLES, LiveStore, verify_live_database


@dataclass(frozen=True)
class ReplayResult:
    equal: bool
    events: int
    logical_sha256: str
    source_database_sha256: str
    replay_database_sha256: str


def file_hash(path: Path) -> str:
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def logical_state_hash(db: sqlite3.Connection) -> str:
    digest = hashlib.sha256(b"BH-LIVE-READONLY/Database/v1\0")
    for table in TABLES:
        digest.update(table.encode() + b"\0")
        for row in db.execute("SELECT * FROM " + table + " ORDER BY 1,2"):  # noqa: S608 - closed table enum
            digest.update(
                rfc8785.dumps([{"bytes_hex": v.hex()} if type(v) is bytes else v for v in row])
                + b"\n"
            )
    return digest.hexdigest()


def _record(row: tuple[Any, ...], expected_index: int) -> dict[str, Any]:
    if row[0] != expected_index or not isinstance(row[8], bytes):
        raise ValueError("E_LIVE_REPLAY_RECEIVE_ORDER")
    event = validate_live_record(parse_strict_json(row[8]), "LiveEvent")
    if rfc8785.dumps(event) != row[8] or event_hash(event) != event["content_hash"]:
        raise ValueError("E_LIVE_REPLAY_HASH")
    expected = (
        expected_index,
        event["run_id"],
        event["stream_id"],
        int(event["generation"]),
        int(event["sequence"]),
        event["observation_id"],
        event["source_kind"],
        event["payload_type"],
        row[8],
        event["previous_hash"],
        event["content_hash"],
        event["observed_at_utc"],
        int(event["received_mono_us"]),
    )
    if row != expected:
        raise ValueError("E_LIVE_REPLAY_COLUMNS")
    return event


def verify_live_replay(run_dir: Path, target_dir: Path) -> ReplayResult:
    source = run_dir / "live.sqlite3"
    if (
        not source.is_file()
        or any(p.is_symlink() for p in (source, *source.parents))
        or source.stat().st_size > MAX_BYTES
    ):
        raise ValueError("E_LIVE_REPLAY_SOURCE")
    if target_dir.exists() or any(p.is_symlink() for p in (target_dir, *target_dir.parents)):
        raise ValueError("E_LIVE_REPLAY_TARGET")
    try:
        lock = os.open(str(source) + ".lock", os.O_RDONLY | os.O_NOFOLLOW)
    except OSError:
        raise ValueError("E_LIVE_REPLAY_LOCK") from None
    try:
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            raise ValueError("E_LIVE_REPLAY_WRITER_ACTIVE") from None
        before_hash = file_hash(source)
        with closing(sqlite3.connect(source.resolve().as_uri() + "?mode=ro", uri=True)) as original:
            original.execute("PRAGMA query_only=ON")
            original.execute("PRAGMA trusted_schema=OFF")
            original.execute("BEGIN")
            verify_live_database(original)
            metas = original.execute("SELECT * FROM run_meta").fetchall()
            closures = original.execute("SELECT * FROM run_closures").fetchall()
            if len(metas) != 1 or len(closures) != 1:
                raise ValueError("E_LIVE_REPLAY_NOT_CLOSED")
            meta, closure = metas[0], closures[0]
            target_dir.mkdir(mode=0o700)
            with LiveStore(
                target_dir / "live.sqlite3",
                run_id=meta[0],
                source_tree_hash=meta[1],
                config_hash=meta[2],
                started_utc=meta[3],
                max_matches=meta[5],
            ) as replay:
                events = 0
                for events, row in enumerate(
                    original.execute("SELECT * FROM live_events ORDER BY receive_index"), start=1
                ):
                    event = _record(row, events)
                    receipt = replay.append(event)
                    if receipt.receive_index != events:
                        raise ValueError("E_LIVE_REPLAY_CURSOR")
                replay.close_run(closure[1], closure[2])
                logical = logical_state_hash(replay.db)
                if logical_state_hash(original) != logical:
                    raise ValueError("E_LIVE_REPLAY_MISMATCH")
            original.execute("COMMIT")
        if file_hash(source) != before_hash:
            raise ValueError("E_LIVE_REPLAY_SOURCE_CHANGED")
        result = ReplayResult(
            True, events, logical, before_hash, file_hash(target_dir / "live.sqlite3")
        )
        output = target_dir / "replay-result.json"
        fd = os.open(output, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        with os.fdopen(fd, "wb") as report:
            report.write(rfc8785.dumps(asdict(result)))
            report.flush()
            os.fsync(report.fileno())
        return result
    except sqlite3.Error:
        raise ValueError("E_LIVE_REPLAY_DATABASE") from None
    finally:
        os.close(lock)"""One local read-only run owner. Real admission is verified by the PB-16 gate."""

