def _utc_now() -> datetime:
    return datetime.now(UTC)


@dataclass(frozen=True)
class RunAdmission:
    root: Path
    run_id: str
    config_sha256: str
    source_tree_sha256: str
    extension_origin: str
    deadline_mono: float
    bindings: tuple[dict[str, Any], ...]
    profile: ExtractionProfile
    capture_streams: dict[str, dict[str, Any]]
    source_kind: str = "MOCK"
    provider_receipt: object = field(default=None, repr=False)
    security_evidence: object = field(default=None, repr=False)


@dataclass(frozen=True)
class LiveRunResult:
    run_id: str
    status: str
    reason: str
    request_attempts: int
    real_http_attempts: int
    run_directory: str
    authenticated: bool = False
    model_enabled: bool = False
    money_ready: bool = False


class MockProviderTransport:
    """Explicit synthetic input only; this transport has no network operation."""

    def __init__(self, responses: list[dict[str, Any]]):
        self.responses = deque(copy.deepcopy(responses))
        self.paths: list[str] = []

    def open(self, request: Any, timeout: float) -> Any:
        if not self.responses:
            raise ProviderError("MOCK_INPUT_EXHAUSTED")
        self.paths.append(request.full_url)
        body = self.responses.popleft()

        class Reply(io.BytesIO):
            status = 200
            headers = {
                "x-ratelimit-requests-limit": "7500",
                "x-ratelimit-requests-remaining": "7499",
                "x-ratelimit-limit": "300",
                "x-ratelimit-remaining": "299",
            }

            def geturl(self) -> str:
                return str(request.full_url)

        return Reply(json.dumps(body).encode())


def verify_run_admission(config: LiveConfig, admitted: RunAdmission, now: float) -> None:
    try:
        if type(config) is not LiveConfig or type(admitted) is not RunAdmission:
            raise ValueError()
        cfg = config.public
        schema_validate(cfg, "config")
        if (
            str(UUID(admitted.run_id)) != admitted.run_id
            or config.sha256 != admitted.config_sha256
            or not re.fullmatch(r"[0-9a-f]{64}", admitted.source_tree_sha256)
            or not re.fullmatch(r"chrome-extension://[a-p]{32}", admitted.extension_origin)
            or not now < admitted.deadline_mono <= now + cfg["runtime"]["max_run_minutes"] * 60
            or not 1 <= len(admitted.bindings) <= cfg["runtime"]["max_matches"]
            or sorted(b["provider_fixture_id"] for b in admitted.bindings)
            != list(config.fixture_ids)
            or sorted(b["binding_id"] for b in admitted.bindings)
            != sorted(cfg["operator"]["allowed_fixture_bindings"])
            or admitted.source_kind not in {"MOCK", "OBSERVED_REAL"}
            or cfg["provider"]["events_fallback_enabled"]
            or cfg["provider"]["events_fallback_fixture_ids"]
        ):
            raise ValueError()
        profile = activate_profile(
            admitted.profile, "SYNTHETIC_TEST" if admitted.source_kind == "MOCK" else "OPERATOR"
        )
        for binding in admitted.bindings:
            validate_live_record(binding, "FixtureBinding")
            if (
                binding["league_id"] != cfg["provider"]["league_id"]
                or binding["season"] != cfg["provider"]["season"]
                or binding["operator_fixture_id"] not in profile["permitted_fixture_ids"]
                or binding["operator_match_url"]
                not in {profile["origin"] + p for p in profile["exact_paths"]}
                or binding["operator_fixture_id"] not in admitted.profile.observed_markets
            ):
                raise ValueError()
        scopes = list(admitted.capture_streams.values())
        if len(scopes) != len(admitted.bindings):
            raise ValueError()
        for scope in scopes:
            observed = admitted.profile.observed_markets[scope["operator_fixture_id"]]
            expected = {
                m["horizon"]: {"market_id": m["market_id"], "selections": m["selections"]}
                for m in observed
            }
            if (
                scope["profile_hash"] != admitted.profile.profile_hash
                or scope["markets"] != expected
            ):
                raise ValueError()
        if admitted.source_kind == "OBSERVED_REAL":
            if not config.enabled:
                raise ValueError()
            importlib.import_module("moj_discovery.live_preflight_batched").verify_run_admission(
                config, admitted
            )
    except Exception:
        raise ValueError("E_LIVE_RUN_ADMISSION") from None


class LiveService:
    def __init__(
        self,
        config: LiveConfig,
        secret: SecretValue,
        admitted: RunAdmission,
        *,
        mock_transport: MockProviderTransport | None = None,
        now_mono: Callable[[], float] = time.monotonic,
        now_utc: Callable[[], datetime] = _utc_now,
        sleep: Callable[[float], None] = time.sleep,
    ):
        verify_run_admission(config, admitted, now_mono())
        if type(secret) is not SecretValue or (
            (admitted.source_kind == "MOCK") != (type(mock_transport) is MockProviderTransport)
        ):
            raise ValueError("E_LIVE_RUN_ADMISSION_TRANSPORT")
        if admitted.source_kind == "OBSERVED_REAL" and (
            now_mono is not time.monotonic or now_utc is not _utc_now or sleep is not time.sleep
        ):
            raise ValueError("E_LIVE_RUN_ADMISSION_CLOCK")
        self.config, self.admitted = config, admitted
        self._mono, self._utc = now_mono, now_utc
        self._lock = threading.RLock()
        self._tick_lock = asyncio.Lock()
        self._resources = ExitStack()
        self.receiver: LiveReceiver | None = None
        self._subscribers: set[asyncio.Queue[dict[str, Any]]] = set()
        self._selected = {b["binding_id"] for b in admitted.bindings}
        self._watchlist_revision = 1
        self._started = False
        self._bootstrapped = False
        self._closed = False
        self._reason: str | None = None
        self._last_clock = now_mono()
        self._last_display_tick = -float("inf")
        cfg = config.public
        self.directory = private_path(cfg["runtime"]["run_output_dir"], root=admitted.root)
        # New run namespace only. Restart preserves the previous journal and needs fresh admission.
        if self.directory.exists():
            raise ValueError("E_LIVE_RUN_RESTART_REQUIRES_ADMISSION")
        self.directory.mkdir(mode=0o700, parents=True)
        self._started_utc = self._utc().isoformat().replace("+00:00", "Z")
        self._started_mono = self._mono()
        self._manual_checks: list[dict[str, Any]] = []
        try:
            from .live_intent import RunIntentReceipt

            receipt = (
                cast(RunIntentReceipt, admitted.provider_receipt)
                if admitted.source_kind == "OBSERVED_REAL"
                else None
            )
            self._artifact(
                "intent.json",
                {
                    "intent": receipt.intent.public if receipt is not None else None,
                    "original_json": receipt.intent.original_json if receipt is not None else None,
                    "intent_sha256": receipt.intent.sha256 if receipt is not None else None,
                    "consumed_at_utc": receipt.consumed_at_utc if receipt is not None else None,
                    "confirmation_kind": receipt.confirmation_kind
                    if receipt is not None
                    else "MOCK",
                },
            )
            self._artifact(
                "config-public.json",
                {
                    "value": cfg,
                    "original_json": config.original_json,
                    "original_sha256": config.sha256,
                    "canonical_sha256": hashlib.sha256(rfc8785.dumps(cfg)).hexdigest(),
                },
            )
            self._artifact(
                "source-bindings.json",
                {
                    "run_id": admitted.run_id,
                    "source_kind": admitted.source_kind,
                    "source_tree_sha256": admitted.source_tree_sha256,
                    "profile": admitted.profile.public,
                    "profile_sha256": admitted.profile.profile_hash,
                    "bindings": list(admitted.bindings),
                    "evidence_refs": cast(Any, admitted.security_evidence).evidence.paths
                    if receipt is not None
                    else {},
                },
            )
            self._artifact("manual-ft-checks.jsonl", [], lines=True)
            self.store = self._resources.enter_context(
                LiveStore(
                    self.directory / "live.sqlite3",
                    run_id=admitted.run_id,
                    source_tree_hash=admitted.source_tree_sha256,
                    config_hash=config.sha256,
                    started_utc=self._started_utc,
                    max_matches=cfg["runtime"]["max_matches"],
                    # Reserve room for bounded run metadata, request outcomes and SQLite journal.
                    max_bytes=MAX_BYTES - 16 * 1024 * 1024,
                )
            )
            for binding in admitted.bindings:
                self._append(
                    "BindingChange",
                    {"before_revision": None, "after": binding, "reason": "USER_VERIFIED_BINDING"},
                )
                self.control(
                    binding["binding_id"],
                    "PROFILE_ADMITTED",
                    hashes=[admitted.profile.profile_hash],
                )
            self.pairing = PairingAuthority(admitted.run_id, admitted.deadline_mono)
            context = dict(
                run_id=admitted.run_id,
                allowed_extension_origin=admitted.extension_origin,
                deadline_mono=admitted.deadline_mono,
                source_kind=admitted.source_kind,
                capture_streams=copy.deepcopy(admitted.capture_streams),
            )
            if admitted.source_kind == "OBSERVED_REAL":
                context["authority"] = admitted.security_evidence
            # Validate receiver scope before creating any provider transport.
            LiveReceiver(context, self.store, self.pairing)
            self._receiver_context = context
            provider = cfg["provider"]
            ledger_path = (
                self.directory / "mock-quota.sqlite3"
                if admitted.source_kind == "MOCK"
                else private_path(
                    ".local/part-b/quota/api-football-primary.sqlite3", root=admitted.root
                )
            )
            self.quota = self._resources.enter_context(
                QuotaLedger(
                    ledger_path,
                    scope_id=admitted.run_id,
                    daily_cap=provider["daily_soft_cap"],
                    session_cap=provider["max_requests_per_run"],
                    minute_cap=provider["max_requests_per_minute"],
                    allow_status_bootstrap=True,
                )
            )
            scope = ProviderScope(
                admitted.run_id,
                config.fixture_ids,
                provider["league_id"],
                provider["season"],
                admitted.deadline_mono,
                source_kind=admitted.source_kind,
                stage="LIVE_READ_ONLY",
                max_attempts=provider["max_requests_per_run"],
                config_sha256=config.sha256,
                source_tree_sha256=admitted.source_tree_sha256,
                receipt=admitted.provider_receipt,
            )
            self.client = self._resources.enter_context(
                ApiFootballClient(
                    secret,
                    self.quota,
                    scope,
                    opener=mock_transport,
                    now_mono=now_mono,
                    now_utc=now_utc,
                    sleep=sleep,
                    before_attempt=self._before_attempt,
                )
            )
            self.poller = ProviderBundlePoller(self.client, now_mono=now_mono, now_utc=now_utc)
            self.poller.set_watchlist(config.fixture_ids, self._watchlist_revision)
        except BaseException:
            self._resources.close()
            raise

    def _artifact(self, name: str, value: Any, *, lines: bool = False) -> None:
        raw = (
            b"".join(rfc8785.dumps(row) + b"\n" for row in value)
            if lines
            else rfc8785.dumps(value) + b"\n"
        )
        if len(raw) > 1024 * 1024:
            raise ValueError("E_LIVE_RUN_ARTIFACT_CAP")
        fd = os.open(
            self.directory / name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600
        )
        with os.fdopen(fd, "wb") as output:
            output.write(raw)
            output.flush()
            os.fsync(output.fileno())

    def record_manual_ft_check(self, fixture_id: int, prices: tuple[str, str, str]) -> None:
        """Record an explicit terminal comparison against a current, committed FT book."""
        from .secrets_local import controlling_tty

        with controlling_tty(), self._lock:
            if self._closed or self._reason or len(self._manual_checks) >= 30:
                raise ValueError("E_LIVE_MANUAL_CHECK_STOPPED")
            binding = next(
                b for b in self.admitted.bindings if b["provider_fixture_id"] == fixture_id
            )
            view = self.view(binding["binding_id"])
            book = view["books"]["FT"]
            stamp = self._utc()
            if (
                type(fixture_id) is not int
                or view["market_states"]["FT"]["status"] != "CURRENT_DISPLAY_ONLY"
                or tuple(book["selections"][s]["decimal_odds"] for s in ("HOME", "DRAW", "AWAY"))
                != prices
                or not 0
                <= (stamp - datetime.fromisoformat(book["observed_at_utc"])).total_seconds()
                <= 30
                or any(
                    r["binding_id"] == binding["binding_id"]
                    and (
                        r["capture_event_hash"] == view["book_meta"]["FT"]["event_hash"]
                        or (stamp - datetime.fromisoformat(r["checked_at_utc"])).total_seconds()
                        < 30
                    )
                    for r in self._manual_checks
                )
            ):
                raise ValueError("E_LIVE_MANUAL_CHECK_NOT_CURRENT_OR_DISTINCT")
            row = {
                "confirmation_kind": "LOCAL_TTY_USER_CHECK",
                "source_kind": self.admitted.source_kind,
                "run_id": self.admitted.run_id,
                "binding_id": binding["binding_id"],
                "capture_event_hash": view["book_meta"]["FT"]["event_hash"],
                "checked_at_utc": stamp.isoformat(),
                "selections": book["selections"],
                "market_id": book["market_id"],
            }
            fd = os.open(
                self.directory / "manual-ft-checks.jsonl", os.O_WRONLY | os.O_APPEND | os.O_NOFOLLOW
            )
            with os.fdopen(fd, "wb") as output:
                output.write(rfc8785.dumps(row) + b"\n")
                output.flush()
                os.fsync(output.fileno())
            self._manual_checks.append(row)

    def _append(self, kind: str, payload: dict[str, Any]) -> dict[str, Any]:
        with self._lock:
            source = "PROVIDER" if kind == "ProviderState" else "CONTROL"
            stream = str(uuid5(UUID(self.admitted.run_id), "BH-LIVE-SERVICE/" + source))
            seq, previous = self.store.cursor(stream)
            now = str(int(self._mono() * 1000000))
            value = copy.deepcopy(payload)
            if kind == "ProviderState":
                # Timestamp actual admission to this backend pipeline under its ordering lock.
                value["received_mono_us"] = now
            event = dict(
                protocol="BH_LIVE_READONLY_V1",
                run_id=self.admitted.run_id,
                source_kind=source,
                stream_id=stream,
                generation="0",
                sequence=str(seq + 1),
                observation_id=str(uuid4()),
                observed_at_utc=self._utc().isoformat().replace("+00:00", "Z"),
                received_mono_us=now,
                previous_hash=previous,
                content_hash="0" * 64,
                payload_type=kind,
                payload=value,
            )
            event["content_hash"] = event_hash(event)
            self.store.append(event)
            return event

    def control(
        self,
        binding_id: str,
        reason: str,
        state: str = "WAITING_FOR_DATA",
        *,
        hashes: list[str] | None = None,
    ) -> dict[str, Any]:
        with self._lock:
            view = self.store.read_projection(binding_id)
            return self._append(
                "HealthChange",
                dict(
                    binding_id=binding_id,
                    reason=reason,
                    state=state,
                    epoch=str(view["epoch"]),
                    evidence_hashes=hashes or [],
                ),
            )

    def _before_attempt(self, purpose: str, request_id: str) -> None:
        with self._lock:
            if (
                self._reason is not None
                or self._mono() >= self.admitted.deadline_mono
                or self._profile_expired()
            ):
                raise ValueError("E_LIVE_RUN_STOPPED")
            if purpose == "BUNDLE":
                for binding in self._selected:
                    self.control(
                        binding, "PROVIDER_REQUEST_STARTED", hashes=[request_reference(request_id)]
                    )

    def view(self, binding_id: str) -> dict[str, Any]:
        return self.store.read_projection(binding_id)

    def subscribe(self) -> asyncio.Queue[dict[str, Any]]:
        if self._closed or len(self._subscribers) >= 8:
            raise ValueError("E_LIVE_SUBSCRIPTION_CAP")
        queue: asyncio.Queue[dict[str, Any]] = asyncio.Queue(maxsize=1)
        self._subscribers.add(queue)
        queue.put_nowait(self.snapshot())
        return queue

    def unsubscribe(self, queue: asyncio.Queue[dict[str, Any]]) -> None:
        self._subscribers.discard(queue)

    def snapshot(self) -> dict[str, Any]:
        views = []
        for binding in self.admitted.bindings:
            view, revision = self.store.read_projection_version(binding["binding_id"])
            views.append({**view, "projection_revision": revision})
        state: WorkspaceState = {
            "run_id": self.admitted.run_id,
            "views": views,
            "selected": sorted(self._selected),
            "max_matches": self.config.public["runtime"]["max_matches"],
            "source_kind": self.admitted.source_kind,
            "quota": self.quota.display_remaining(self._utc(), self._mono()),
            "provider_connection": "STOPPED"
            if self._reason
            else (
                "PAUSED" if not self._selected else "CONNECTED" if self._bootstrapped else "WAITING"
            ),
            "capture_connection": "CONNECTED"
            if self.receiver and self.receiver.connected("CAPTURE_PRODUCER")
            else "DISCONNECTED",
        }
        return {
            **state,
            "workspace": project_watchlist(state),
            "attempts": self.quota.count_attempts(),
            "model_enabled": False,
            "money_ready": False,
        }

    def wire_projection(
        self, binding_id: str, health: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        snapshot = self.snapshot()
        view = next(v for v in snapshot["views"] if v["binding"]["binding_id"] == binding_id)
        match = next(
            v for v in snapshot["workspace"]["matches"] if v["binding"]["binding_id"] == binding_id
        )
        stream, scope = next(
            (k, v)
            for k, v in self.admitted.capture_streams.items()
            if v["binding_id"] == binding_id
        )
        profile = self.admitted.profile.public
        return dict(
            **match,
            run_id=self.admitted.run_id,
            capture_scope={
                "stream_id": stream,
                "generation": scope["generation"],
                "exact_url": view["binding"]["operator_match_url"],
                "profile_status": self.admitted.profile.status,
                "profile_hash": self.admitted.profile.profile_hash,
                "document_epoch": scope["document_epoch"],
                "selectors": profile["selectors"],
                "price_parser": profile["price_parser"],
                "markets": self.admitted.profile.observed_markets[
                    view["binding"]["operator_fixture_id"]
                ],
                "expires_at": profile["expires_at"]
                or (
                    self._utc()
                    + timedelta(seconds=max(0, self.admitted.deadline_mono - self._mono()))
                )
                .isoformat()
                .replace("+00:00", "Z"),
                "max_duration_seconds": max(
                    1, min(7200, int(self.admitted.deadline_mono - self._mono()))
                ),
            },
            health=health
            or {
                "binding_id": binding_id,
                "reason": "DISPLAY_PROJECTION",
                "state": view["status"],
                "epoch": str(view["epoch"]),
                "evidence_hashes": [],
            },
            model_status="MODEL_NOT_QUALIFIED",
            money_ready=False,
        )

    async def publish(self) -> None:
        snapshot = self.snapshot()
        for queue in self._subscribers:
            if queue.full():
                queue.get_nowait()
            queue.put_nowait(copy.deepcopy(snapshot))
        if self.receiver:
            for binding in self.admitted.bindings:
                await self.receiver.publish(self.wire_projection(binding["binding_id"]))

    async def request_capture(self, binding_id: str) -> str | None:
        if binding_id not in self._selected or self._reason is not None:
            return None
        view = self.view(binding_id)
        if view["hold"] is not None:
            return None
        challenge = hashlib.sha256(uuid4().bytes).hexdigest()
        health = self.control(binding_id, "CAPTURE_REQUEST_STARTED", hashes=[challenge])["payload"]
        if self.receiver:
            await self.receiver.publish(
                self.wire_projection(binding_id, health), role="CAPTURE_PRODUCER"
            )
        return challenge

    async def capture_received(self, event: dict[str, Any]) -> None:
        with self._lock:
            book = event["payload"]
            meta = self.view(book["binding_id"])["book_meta"].get(book["horizon"])
            if meta and meta["event_hash"] == event["content_hash"] and meta["receipt_us"] is None:
                self.control(book["binding_id"], "CAPTURE_RECEIVED", hashes=[event["content_hash"]])

    async def source_changed(self, binding_id: str | None, reason: str) -> None:
        if reason == "USER_STOP" and binding_id in self._selected:
            self._selected.remove(binding_id)
            self._watchlist_revision += 1
            self.poller.set_watchlist(
                [
                    b["provider_fixture_id"]
                    for b in self.admitted.bindings
                    if b["binding_id"] in self._selected
                ],
                self._watchlist_revision,
            )
        if reason in {"PAIRING_RENEWED", "CAPTURE_REJECTED"}:
            for selected in self._selected if binding_id is None else [binding_id]:
                await self.request_capture(selected)
        await self.publish()

    async def on_ui(self, command: str, binding_id: str | None) -> None:
        if command == "STOP_SESSION":
            self._reason = "USER_STOP"
            self.poller.stop("USER_STOP")
            for binding in self.admitted.bindings:
                self.control(binding["binding_id"], "USER_STOP", "STOPPED")
        elif command in {"WATCHLIST_ADD", "WATCHLIST_REMOVE"}:
            if binding_id not in {b["binding_id"] for b in self.admitted.bindings}:
                raise ValueError("E_LIVE_UI_SCOPE")
            assert binding_id is not None
            if command == "WATCHLIST_ADD" and binding_id not in self._selected:
                self.control(binding_id, "USER_RESUME")
                self._selected.add(binding_id)
                await self.request_capture(binding_id)
            elif command == "WATCHLIST_REMOVE" and binding_id in self._selected:
                self._selected.remove(binding_id)
                self.control(binding_id, "USER_PAUSE", "PAUSED")
            self._watchlist_revision += 1
            ids = [
                b["provider_fixture_id"]
                for b in self.admitted.bindings
                if b["binding_id"] in self._selected
            ]
            self.poller.set_watchlist(ids, self._watchlist_revision)
        elif command == "REFRESH":
            self.poller.request_refresh()
        elif command != "SELECT_ACTIVE" or binding_id not in {
            b["binding_id"] for b in self.admitted.bindings
        }:
            raise ValueError("E_LIVE_UI_SCOPE")
        await self.publish()

    async def start(self) -> None:
        if self._started or self._closed:
            raise ValueError("E_LIVE_SERVICE_OWNER")
        self.receiver = await serve_live_receiver(self._receiver_context, self.store, self.pairing)
        self.receiver.on_ui = self.on_ui
        self.receiver.on_capture = self.capture_received
        self.receiver.on_change = self.source_changed
        self._started = True

    async def _io(self, operation: Callable[[], Any]) -> Any:
        task = asyncio.create_task(asyncio.to_thread(operation))
        try:
            return await asyncio.shield(task)
        except asyncio.CancelledError:
            # Drain our bounded request before closing its ledger/journal.
            await task
            raise

    def _profile_expired(self) -> bool:
        expires = self.admitted.profile.public["expires_at"]
        return expires is not None and self._utc() >= datetime.fromisoformat(expires)

    async def tick(self) -> None:
        if not self._started or self._closed:
            raise ValueError("E_LIVE_SERVICE_OWNER")
        if self._tick_lock.locked():
            return
        async with self._tick_lock:
            self.client.check_credential()
            now = self._mono()
            if now < self._last_clock:
                self._reason = "SECURITY_HOLD"
            elif now >= self.admitted.deadline_mono:
                self._reason = "RUN_DEADLINE"
            elif self._profile_expired():
                self._reason = "SECURITY_HOLD"
                for binding in self.admitted.bindings:
                    self.control(binding["binding_id"], "PROFILE_EXPIRED", "PROFILE_EXPIRED")
            self._last_clock = max(now, self._last_clock)
            if self._reason is not None:
                if now >= self._last_clock:
                    for binding in self.admitted.bindings:
                        self.control(binding["binding_id"], "RUN_HALTED", "STOPPED")
                    await self.publish()
                return
            if now - self._last_display_tick >= 5:
                self._last_display_tick = now
                for binding in self.admitted.bindings:
                    self.control(binding["binding_id"], "CLOCK_TICK")
            if not self._selected:
                await self.publish()
                return
            if not self._bootstrapped:
                try:
                    status = await self._io(self.client.get_status)
                    if not status.active or status.daily_remaining is None:
                        raise ValueError("E_LIVE_ACCOUNT")
                    self._bootstrapped = True
                except Exception:
                    self._reason = self._reason or "SECURITY_HOLD"
                    for binding in self._selected:
                        self.control(binding, "PROVIDER_START_FAILED", "PAUSED")
                    await self.publish()
                    return
            outcome = await self._io(lambda: self.poller.tick(self._mono()))
            if self._reason is not None:
                return
            if outcome.projection:
                for state in outcome.projection.states.values():
                    self._append("ProviderState", state)
                    binding_id = next(
                        b["binding_id"]
                        for b in self.admitted.bindings
                        if b["provider_fixture_id"] == state["fixture_id"]
                    )
                    delay = 15 if state["period"] in {"H1", "H2"} else 60
                    if (
                        state["period"] == "PREGAME"
                        and (
                            datetime.fromisoformat(state["kickoff_utc"]) - self._utc()
                        ).total_seconds()
                        < 600
                    ):
                        delay = 30
                    self.control(binding_id, "SCHEDULE_" + str(delay))
                    await self.request_capture(binding_id)
            if outcome.status in {"PAUSED", "STOPPED"}:
                self._reason = "SOURCE_STOPPED"
                for binding in self._selected:
                    self.control(binding, "PROVIDER_STOPPED", "PAUSED")
            elif outcome.status == "STALE" or outcome.wake_gap:
                for binding in self._selected:
                    self.control(binding, "PROVIDER_DISCONNECTED", "STALE_PROVIDER")
            await self.publish()

    async def close(self, reason: str = "USER_STOP") -> LiveRunResult:
        if self._closed:
            raise ValueError("E_LIVE_SERVICE_CLOSED")
        self._reason = self._reason or reason
        try:
            self.client.check_credential()
        except ProviderError:
            self._reason = "SECURITY_HOLD"
        self.poller.stop("SHUTDOWN")
        if self.receiver:
            await self.receiver.close()
        async with self._tick_lock:
            try:
                if self._mono() >= self._last_clock:
                    for binding in self.admitted.bindings:
                        self.control(binding["binding_id"], "USER_STOP", "STOPPED")
                    await self.publish()
                closed_utc = self._utc().isoformat().replace("+00:00", "Z")
                self.store.close_run(closed_utc, self._reason)
                count = self.quota.count_attempts()
                rows = self.quota.db.execute(
                    "SELECT r.attempt_id,r.purpose,r.reserved_at_utc,"
                    "r.reserved_mono_us,o.result_code "
                    "FROM quota_reservations r LEFT JOIN quota_outcomes o USING(attempt_id) "
                    "WHERE r.scope_id=? ORDER BY r.reserved_mono_us,r.attempt_id",
                    (self.admitted.run_id,),
                ).fetchall()
                requests = [
                    dict(
                        zip(
                            (
                                "attempt_id",
                                "purpose",
                                "reserved_at_utc",
                                "reserved_mono_us",
                                "outcome",
                            ),
                            row,
                            strict=True,
                        )
                    )
                    for row in rows
                ]
                self._artifact("requests.jsonl", requests, lines=True)
                self._artifact(
                    "result.json",
                    {
                        "schema_version": "part-b-recorded-run/v1",
                        "run_id": self.admitted.run_id,
                        "source_kind": self.admitted.source_kind,
                        "status": "STOPPED",
                        "reason": self._reason,
                        "started_at_utc": self._started_utc,
                        "closed_at_utc": closed_utc,
                        "duration_us": max(0, int((self._mono() - self._started_mono) * 1000000)),
                        "reserved_attempts": count,
                        "http_attempts": self.client.http_attempts,
                        "real_http_attempts": self.client.http_attempts
                        if self.admitted.source_kind == "OBSERVED_REAL"
                        else 0,
                        "authenticated": self._bootstrapped,
                        "model_enabled": False,
                        "money_ready": False,
                    },
                )
                with (self.directory / "provider-attempts.json").open("x") as output:
                    json.dump(
                        {
                            "source_kind": self.admitted.source_kind,
                            "reserved_attempts": count,
                            "http_attempts": self.client.http_attempts,
                            "attempts": self.client.request_log,
                        },
                        output,
                        indent=2,
                    )
                    output.flush()
                    os.fsync(output.fileno())
                return LiveRunResult(
                    self.admitted.run_id,
                    "STOPPED",
                    self._reason,
                    count,
                    self.client.http_attempts
                    if self.admitted.source_kind == "OBSERVED_REAL"
                    else 0,
                    str(self.directory),
                    authenticated=self._bootstrapped,
                )
            finally:
                self._closed = True
                self._resources.close()


async def _run(
    service: LiveService, on_ready: Callable[[LiveService], Callable[[], None] | None] | None = None
) -> LiveRunResult:
    cleanup: Callable[[], None] | None = None
    try:
        await service.start()
        if on_ready is not None:
            cleanup = on_ready(service)
        while service._reason is None:
            await service.tick()
            await asyncio.sleep(1)
    except Exception:
        service._reason = service._reason or "SECURITY_HOLD"
    finally:
        try:
            if cleanup is not None:
                cleanup()
        finally:
            result = await service.close()
    return result


def run_live_service(
    config: LiveConfig,
    secret: SecretValue,
    admitted: RunAdmission,
    *,
    on_ready: Callable[[LiveService], Callable[[], None] | None] | None = None,
) -> LiveRunResult:
    # No secret lookup occurs here. Only the no-echo user-terminal launcher may obtain it.
    return asyncio.run(_run(LiveService(config, secret, admitted), on_ready))"""Pure display projection. Receive order is replay order, never source chronology.

Only backend-generated HealthChange records carry receipt/request clocks. A
CAPTURE_REQUEST_STARTED challenge is sent through the existing PROJECTION health
record; the fixed producer derives its observation ID before starting DOM reads.
CAPTURE_RECEIVED links the actual committed operator event to backend receipt time.
Producer-supplied monotonic values are never compared to backend monotonic values.
"""

import copy
import hashlib
from typing import Any
from uuid import UUID, uuid5

import rfc8785

from .live_contracts import MAX_INTEGER, event_hash, validate_live_record
from .providers.football_normalizer import semantic_hash

CHALLENGE_NAMESPACE = UUID("8aa7e474-6a01-4ae9-91d8-d4770a55b3e4")
BOOK_RECEIPT_FIELDS = frozenset(
    {"capture_revision", "observed_at_utc", "browser_mono_us", "clock_domain_id"}
)
BLOCKS = {"STOPPED", "PAUSED", "PROFILE_EXPIRED", "OUT_OF_SCOPE"}
TIMED_CONTROLS = {
    "CLOCK_TICK",
    "PROFILE_ADMITTED",
    "PROVIDER_REQUEST_STARTED",
    "CAPTURE_REQUEST_STARTED",
    "CAPTURE_RECEIVED",
    "SCHEDULE_15",
    "SCHEDULE_30",
    "SCHEDULE_60",
    "USER_RESUME",
}


def request_reference(request_id: str) -> str:
    UUID(request_id)
    return hashlib.sha256(b"BH-LIVE-READONLY/Request/v1\0" + request_id.encode()).hexdigest()


def capture_observation_id(challenge_hash: str, horizon: str) -> str:
    if (
        len(challenge_hash) != 64
        or any(c not in "0123456789abcdef" for c in challenge_hash)
        or horizon not in {"H1", "H2", "FT"}
    ):
        raise ValueError("E_LIVE_CAPTURE_CHALLENGE")
    return str(uuid5(CHALLENGE_NAMESPACE, challenge_hash + ":" + horizon))


def h2_score(ht: tuple[int, int] | None, current: tuple[int, int] | None) -> tuple[int, int] | None:
    if ht is None or current is None:
        return None
    if (
        len(ht) != 2
        or len(current) != 2
        or any(type(v) is not int or not 0 <= v <= 100 for v in (*ht, *current))
        or any(a > b for a, b in zip(ht, current, strict=True))
    ):
        return None
    return current[0] - ht[0], current[1] - ht[1]


def _observations(previous: dict[str, Any] | None, event: dict[str, Any]) -> dict[str, Any]:
    """Preserve source records independently before deriving display eligibility."""
    kind, payload = event["payload_type"], event["payload"]
    view = copy.deepcopy(previous)
    if kind == "BindingChange":
        binding = validate_live_record(payload["after"], "FixtureBinding")
        before = None if view is None else view["binding"]["revision"]
        if payload["before_revision"] != before or int(binding["revision"]) != (
            1 if before is None else int(before) + 1
        ):
            raise ValueError("E_LIVE_BINDING_REVISION")
        view = {
            "binding_id": binding["binding_id"],
            "binding": binding,
            "provider": None,
            "books": {},
            "health": None,
            "model_enabled": False,
            "money_ready": False,
        }
    elif view is None:
        raise ValueError("E_LIVE_BINDING_REQUIRED")
    elif kind == "ProviderState":
        binding = view["binding"]
        if any(
            payload[k] != binding[b]
            for k, b in (
                ("fixture_id", "provider_fixture_id"),
                ("home_id", "home_id"),
                ("away_id", "away_id"),
                ("kickoff_utc", "kickoff_utc"),
            )
        ):
            raise ValueError("E_LIVE_BINDING_MISMATCH")
        prior = view["provider"]
        expected_revision = (
            1
            if prior is None
            else int(prior["content_revision"]) + (semantic_hash(prior) != semantic_hash(payload))
        )
        if int(payload["content_revision"]) != expected_revision:
            raise ValueError("E_LIVE_PROVIDER_REVISION")
        view["provider"] = payload
    elif kind == "MarketBook":
        if (
            payload["binding_revision"] != view["binding"]["revision"]
            or payload["operator_fixture_id"] != view["binding"]["operator_fixture_id"]
        ):
            raise ValueError("E_LIVE_BINDING_MISMATCH")
        prior = view["books"].get(payload["horizon"])
        if prior is not None and int(payload["capture_revision"]) <= int(prior["capture_revision"]):
            raise ValueError("E_LIVE_CAPTURE_REVISION")
        view["books"][payload["horizon"]] = payload
    elif kind == "HealthChange":
        view["health"] = payload
    else:
        raise ValueError("E_LIVE_STORE_KIND")
    assert view is not None
    view["last_observation_id"] = event["observation_id"]
    view["observed_at_utc"] = event["observed_at_utc"]
    view["received_mono_us"] = event["received_mono_us"]
    return view


def _invalidate(view: dict[str, Any], reason: str, event: dict[str, Any]) -> None:
    view["epoch"] += 1
    if view["epoch"] > MAX_INTEGER:
        raise ValueError("E_LIVE_EPOCH_RANGE")
    view["invalidation"] = {"reason": reason, "evidence_hash": event["content_hash"]}
    view["provider_epoch"] = None
    view["requests"] = {}
    view["capture_requests"] = {}
    for meta in view["book_meta"].values():
        meta["epoch"] = None


def _advance(view: dict[str, Any], value: int) -> None:
    if value < view["backend_now_us"]:
        raise ValueError("E_LIVE_BACKEND_CLOCK")
    view["backend_now_us"] = value


def _book_semantic(book: dict[str, Any]) -> str:
    return hashlib.sha256(
        rfc8785.dumps({k: v for k, v in book.items() if k not in BOOK_RECEIPT_FIELDS})
    ).hexdigest()


def _event_context(provider: dict[str, Any]) -> dict[str, Any]:
    return {
        **{
            k: provider[k]
            for k in ("score_current", "score_ht", "period", "red_card_state", "events_status")
        },
        "events": [e for e in provider["events"] if e["type"] in {"GOAL", "CARD", "VAR"}],
    }


def _health(view: dict[str, Any], event: dict[str, Any]) -> None:
    payload = event["payload"]
    reason, evidence = payload["reason"], payload["evidence_hashes"]
    if reason in TIMED_CONTROLS:
        _advance(view, int(event["received_mono_us"]))
    if reason == "PROFILE_ADMITTED":
        if len(evidence) != 1 or view["hold"] in {"STOPPED", "PROFILE_EXPIRED"}:
            raise ValueError("E_LIVE_PROFILE_ADMISSION")
        if view["profile_hash"] != evidence[0]:
            _invalidate(view, reason, event)
        view["profile_hash"] = evidence[0]
    elif reason in {"PROVIDER_REQUEST_STARTED", "CAPTURE_REQUEST_STARTED"}:
        if len(evidence) != 1 or int(payload["epoch"]) != view["epoch"] or view["hold"] in BLOCKS:
            raise ValueError("E_LIVE_REQUEST_EPOCH")
        pending = (
            view["requests"] if reason == "PROVIDER_REQUEST_STARTED" else view["capture_requests"]
        )
        refs = (
            [evidence[0]]
            if reason == "PROVIDER_REQUEST_STARTED"
            else [capture_observation_id(evidence[0], h) for h in ("H1", "H2", "FT")]
        )
        if any(ref in pending for ref in refs):
            raise ValueError("E_LIVE_REQUEST_CAP")
        # One current request per source/fixture. Superseded late observations
        # remain visible but cannot satisfy this new request's freshness gate.
        pending.clear()
        for ref in refs:
            pending[ref] = {"epoch": view["epoch"], "started_us": view["backend_now_us"]}
    elif reason == "CAPTURE_RECEIVED":
        if len(evidence) != 1:
            raise ValueError("E_LIVE_CAPTURE_RECEIPT")
        matches = [m for m in view["book_meta"].values() if m["event_hash"] == evidence[0]]
        if len(matches) != 1 or matches[0]["receipt_us"] is not None:
            raise ValueError("E_LIVE_CAPTURE_RECEIPT")
        meta = matches[0]
        meta["receipt_us"] = view["backend_now_us"]
        if meta["semantic_changed"]:
            meta["changed_us"] = view["backend_now_us"]
    elif reason.startswith("SCHEDULE_") and reason in TIMED_CONTROLS:
        view["scheduled_interval_seconds"] = int(reason.removeprefix("SCHEDULE_"))
    elif reason == "CLOCK_TICK":
        pass
    elif reason == "USER_RESUME":
        if view["hold"] in {"STOPPED", "PROFILE_EXPIRED", "OUT_OF_SCOPE"}:
            raise ValueError("E_LIVE_RESUME_REQUIRES_ADMISSION")
        view["hold"] = None
        _invalidate(view, reason, event)
    else:
        _invalidate(view, reason, event)
        if payload["state"] in BLOCKS:
            view["hold"] = payload["state"]


def _display(view: dict[str, Any]) -> None:
    provider, now = view["provider"], view["backend_now_us"]
    provider_age = (
        None if view["provider_receipt_us"] is None else now - view["provider_receipt_us"]
    )
    view["provider_receipt_age_us"] = provider_age
    view["provider_content_age_us"] = (
        None if view["provider_changed_us"] is None else now - view["provider_changed_us"]
    )
    view["source_age"] = None
    view["source_time_status"] = "UNKNOWN"
    view["market_states"] = {}
    view["h2_score"] = None
    if provider is not None and view["halftime_baseline"] is not None:
        ht = view["halftime_baseline"]
        if provider["score_ht"] == ht and provider["score_current"] is not None:
            result = h2_score(
                (ht["home"], ht["away"]),
                (provider["score_current"]["home"], provider["score_current"]["away"]),
            )
            if result is not None:
                view["h2_score"] = {"home": result[0], "away": result[1]}
    for horizon, book in view["books"].items():
        meta = view["book_meta"][horizon]
        market_age = None if meta["receipt_us"] is None else now - meta["receipt_us"]
        state = "CURRENT_DISPLAY_ONLY"
        if view["hold"] is not None:
            state = view["hold"]
        elif view["binding"]["orientation_status"] != "VERIFIED":
            state = "CONTEXT_UNVERIFIED"
        elif view["profile_hash"] != book["profile_hash"]:
            state = "PROFILE_EXPIRED" if view["profile_hash"] is not None else "WAITING_FOR_DATA"
        elif provider is None:
            state = "WAITING_FOR_DATA"
        elif provider["period"] in {"OUT_OF_SCOPE", "BLOCKED", "UNKNOWN", "FINISHED"}:
            state = "OUT_OF_SCOPE"
        elif book["market_status"] != "OPEN":
            state = "MARKET_SUSPENDED"
        elif (
            book["settlement_basis"] != "NORMAL_TIME_INCLUDING_STOPPAGE"
            or (horizon == "H1" and provider["period"] != "H1")
            or (horizon == "H2" and provider["period"] != "H2")
        ):
            state = "OUT_OF_SCOPE"
        elif (
            book["operator_score"] is not None
            and provider["score_current"] is not None
            and book["operator_score"] != provider["score_current"]
        ) or (
            book["operator_period"] not in {None, "UNKNOWN"}
            and book["operator_period"] != provider["period"]
        ):
            state = "STATE_CONFLICT"
        elif (
            book["operator_score"] is None
            or provider["score_current"] is None
            or book["operator_period"] in {None, "UNKNOWN"}
            or (horizon == "H2" and view["h2_score"] is None)
            or book["capture_evidence_tier"] != "DISPLAY_COHERENT"
        ):
            state = "CONTEXT_UNVERIFIED"
        elif (
            provider_age is None
            or provider_age > max(45, 2 * view["scheduled_interval_seconds"] + 5) * 1000000
        ):
            state = "STALE_PROVIDER"
        elif market_age is None or market_age > 35000000:
            state = "STALE_MARKET"
        elif view["provider_epoch"] != view["epoch"] or meta["epoch"] != view["epoch"]:
            state = "WAITING_FOR_DATA"
        view["market_states"][horizon] = {
            "status": state,
            "market_eligible": state == "CURRENT_DISPLAY_ONLY",
            "receipt_age_us": market_age,
            "content_age_us": None if meta["changed_us"] is None else now - meta["changed_us"],
            "source_age": None,
        }
    view["market_eligible"] = any(m["market_eligible"] for m in view["market_states"].values())
    view["status"] = view["hold"] or (
        "CURRENT_DISPLAY_ONLY" if view["market_eligible"] else "WAITING_FOR_DATA"
    )
    view["model_enabled"] = False
    view["money_ready"] = False


def reduce_live_event(current: dict[str, Any] | None, event: dict[str, Any]) -> dict[str, Any]:
    event = validate_live_record(event, "LiveEvent")
    if event_hash(event) != event["content_hash"]:
        raise ValueError("E_LIVE_EVENT_HASH")
    kind, payload = event["payload_type"], event["payload"]
    expected_source = {
        "BindingChange": "CONTROL",
        "HealthChange": "CONTROL",
        "ProviderState": "PROVIDER",
        "MarketBook": "OPERATOR",
    }[kind]
    if event["source_kind"] != expected_source:
        raise ValueError("E_LIVE_SOURCE_ROLE")
    if current is not None:
        binding = current["binding"]
        event_binding = payload.get("binding_id")
        if (event_binding is not None and event_binding != binding["binding_id"]) or (
            kind == "ProviderState" and payload["fixture_id"] != binding["provider_fixture_id"]
        ):
            raise ValueError("E_LIVE_BINDING_MISMATCH")
        if kind == "BindingChange" and payload["after"]["binding_id"] != binding["binding_id"]:
            raise ValueError("E_LIVE_BINDING_MISMATCH")
    view = _observations(current, event)
    if kind == "BindingChange":
        view.update(
            epoch=0 if current is None else current["epoch"] + 1,
            invalidation={"reason": "BINDING_CHANGE", "evidence_hash": event["content_hash"]},
            backend_now_us=0 if current is None else current["backend_now_us"],
            provider_receipt_us=None,
            provider_changed_us=None,
            provider_epoch=None,
            provider_clock_domain=None,
            requests={},
            capture_requests={},
            book_meta={},
            halftime_baseline=None,
            profile_hash=None,
            hold=None,
            scheduled_interval_seconds=15,
        )
    elif kind == "HealthChange":
        _health(view, event)
    elif kind == "ProviderState":
        assert current is not None
        previous = current["provider"]
        if view["provider_clock_domain"] not in {None, payload["clock_domain_id"]}:
            _invalidate(view, "BACKEND_CLOCK_CHANGED", event)
            view["hold"] = "PAUSED"
        else:
            _advance(view, int(payload["received_mono_us"]))
            view["provider_clock_domain"] = payload["clock_domain_id"]
            request = view["requests"].pop(request_reference(payload["request_id"]), None)
            if previous is not None and _event_context(previous) != _event_context(payload):
                _invalidate(view, "PROVIDER_CONTEXT_CHANGED", event)
            view["provider_receipt_us"] = view["backend_now_us"]
            if previous is None or semantic_hash(previous) != semantic_hash(payload):
                view["provider_changed_us"] = view["backend_now_us"]
            if request is not None and request["epoch"] == view["epoch"]:
                view["provider_epoch"] = view["epoch"]
            if (
                payload["period"] == "HALFTIME"
                and payload["score_ht"] is not None
                and payload["score_ht"] == payload["score_current"]
            ):
                view["halftime_baseline"] = copy.deepcopy(payload["score_ht"])
    elif kind == "MarketBook":
        assert current is not None
        previous = current["books"].get(payload["horizon"])
        request = view["capture_requests"].pop(event["observation_id"], None)
        if previous is not None and any(
            previous[k] != payload[k]
            for k in ("operator_score", "operator_period", "document_epoch", "profile_hash")
        ):
            _invalidate(view, "OPERATOR_CONTEXT_CHANGED", event)
        elif payload["market_status"] != "OPEN" and (
            previous is None or previous["market_status"] == "OPEN"
        ):
            _invalidate(view, "MARKET_SUSPENDED", event)
        previous_meta = current["book_meta"].get(payload["horizon"])
        view["book_meta"][payload["horizon"]] = {
            "event_hash": event["content_hash"],
            "receipt_us": None,
            "epoch": request["epoch"]
            if request is not None and request["epoch"] == view["epoch"]
            else None,
            "semantic_changed": previous is None
            or _book_semantic(previous) != _book_semantic(payload),
            "changed_us": None if previous_meta is None else previous_meta["changed_us"],
        }
    _display(view)
    return view"""Typed append-only journal; a durable receipt is returned only after COMMIT."""

import fcntl
import hashlib
import json
import os
import re
import sqlite3
import threading
from dataclasses import dataclass
from datetime import UTC, datetime
from pathlib import Path
from types import TracebackType
from typing import Any, cast
from uuid import UUID, uuid4, uuid5

import rfc8785

from .canonical import parse_strict_json
from .live_contracts import CONTRACTS, event_hash, validate_live_record
from .live_state import reduce_live_event
from .store import _schema_objects

TABLES = (
    "run_meta",
    "live_events",
    "stream_cursors",
    "projection_versions",
    "request_links",
    "run_closures",
)
ZERO = "0" * 64
MAX_BYTES = 512 * 1024 * 1024


def view_hash(view: dict[str, Any]) -> str:
    return hashlib.sha256(b"BH-LIVE-READONLY/View/v1\0" + rfc8785.dumps(view)).hexdigest()


def verify_live_database(db: sqlite3.Connection) -> None:
    if db.execute("PRAGMA user_version").fetchone()[0] != 1:
        raise ValueError("E_LIVE_STORE_SCHEMA")
    query = "SELECT type,name,tbl_name,sql FROM sqlite_schema ORDER BY type,name"
    if tuple(tuple(r) for r in db.execute(query)) != _schema_objects(
        (CONTRACTS / "live-store.sql").read_text()
    ):
        raise ValueError("E_LIVE_STORE_SCHEMA")
    if (
        db.execute("PRAGMA integrity_check").fetchall() != [("ok",)]
        or db.execute("PRAGMA foreign_key_check").fetchall()
    ):
        raise ValueError("E_LIVE_STORE_INTEGRITY")


def _timestamp(value: str) -> None:
    stamp = datetime.fromisoformat(value)
    if stamp.tzinfo is None or stamp.utcoffset() != UTC.utcoffset(stamp):
        raise ValueError("E_LIVE_STORE_TIME")


def _authorizer(
    action: int, first: str | None, second: str | None, db: str | None, trigger: str | None
) -> int:
    if action in {
        sqlite3.SQLITE_SELECT,
        sqlite3.SQLITE_READ,
        sqlite3.SQLITE_TRANSACTION,
        sqlite3.SQLITE_RECURSIVE,
    }:
        return sqlite3.SQLITE_OK
    if action == sqlite3.SQLITE_INSERT and first in TABLES:
        return sqlite3.SQLITE_OK
    if action == sqlite3.SQLITE_FUNCTION and second in {"max", "coalesce", "length", "raise"}:
        return sqlite3.SQLITE_OK
    return sqlite3.SQLITE_DENY


@dataclass(frozen=True)
class DurableReceipt:
    receive_index: int
    run_id: str
    stream_id: str
    generation: str
    sequence: str
    content_hash: str


def reduce_projection(previous: dict[str, Any] | None, event: dict[str, Any]) -> dict[str, Any]:
    return reduce_live_event(previous, event)


class LiveStore:
    def __init__(
        self,
        path: Path,
        *,
        run_id: str,
        source_tree_hash: str,
        config_hash: str,
        started_utc: str,
        max_matches: int,
        max_bytes: int = MAX_BYTES,
    ):
        if (
            str(UUID(run_id)) != run_id
            or any(not re.fullmatch(r"[0-9a-f]{64}", h) for h in (source_tree_hash, config_hash))
            or type(max_matches) is not int
            or max_matches not in {1, 3, 5}
        ):
            raise ValueError("E_LIVE_RUN_META")
        _timestamp(started_utc)
        if type(max_bytes) is not int or not 131072 <= max_bytes <= MAX_BYTES:
            raise ValueError("E_LIVE_STORE_CAP")
        if any(p.is_symlink() for p in (path, *path.parents)):
            raise ValueError("E_LIVE_STORE_PATH")
        path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        if path.parent.stat().st_mode & 0o077:
            raise ValueError("E_LIVE_STORE_PATH")
        self._fd = os.open(str(path) + ".lock", os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
        try:
            fcntl.flock(self._fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            os.close(self._fd)
            raise ValueError("E_LIVE_STORE_LOCK") from None
        self.path, self.run_id, self.max_bytes = path, run_id, max_bytes
        self._mutex = threading.RLock()
        self._pid, self._closed = os.getpid(), False
        try:
            fd = os.open(path, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
            os.close(fd)
            if path.stat().st_mode & 0o077:
                raise ValueError("E_LIVE_STORE_PATH")
            self.db = sqlite3.connect(path, isolation_level=None, check_same_thread=False)
            if not self.db.execute("SELECT name FROM sqlite_schema WHERE type='table'").fetchone():
                self.db.executescript((CONTRACTS / "live-store.sql").read_text())
            for pragma in (
                "journal_mode=DELETE",
                "synchronous=FULL",
                "foreign_keys=ON",
                "trusted_schema=OFF",
                "busy_timeout=5000",
                "temp_store=MEMORY",
            ):
                self.db.execute("PRAGMA " + pragma)
            page = self.db.execute("PRAGMA page_size").fetchone()[0]
            if (
                self.db.execute("PRAGMA max_page_count=" + str(max_bytes // page)).fetchone()[0]
                > max_bytes // page
            ):
                raise ValueError("E_LIVE_STORE_CAP")
            verify_live_database(self.db)
            expected = (
                run_id,
                source_tree_hash,
                config_hash,
                started_utc,
                "LIVE_READ_ONLY",
                max_matches,
                0,
            )
            existing = self.db.execute("SELECT * FROM run_meta").fetchall()
            if existing and existing != [expected]:
                raise ValueError("E_LIVE_RUN_META")
            if not existing:
                self.db.execute("INSERT INTO run_meta VALUES(?,?,?,?,?,?,?)", expected)
            self.db.set_authorizer(_authorizer)
        except BaseException:
            if hasattr(self, "db"):
                self.db.close()
            os.close(self._fd)
            raise

    def __enter__(self) -> "LiveStore":
        return self

    def __exit__(
        self,
        kind: type[BaseException] | None,
        error: BaseException | None,
        traceback: TracebackType | None,
    ) -> None:
        self.close()

    def _owner(self) -> None:
        if self._closed or self._pid != os.getpid():
            raise ValueError("E_LIVE_STORE_OWNER")

    def close(self) -> None:
        with self._mutex:
            if not self._closed:
                self.db.close()
                os.close(self._fd)
                self._closed = True

    def read_projection(self, binding_id: str) -> dict[str, Any]:
        return self.read_projection_version(binding_id)[0]

    def read_projection_version(self, binding_id: str) -> tuple[dict[str, Any], int]:
        with self._mutex:
            self._owner()
            row = self.db.execute(
                "SELECT canonical_view,content_hash,revision FROM projection_versions "
                "WHERE run_id=? "
                "AND binding_id=? ORDER BY revision DESC LIMIT 1",
                (self.run_id, binding_id),
            ).fetchone()
            if row is None:
                raise ValueError("E_LIVE_BINDING_REQUIRED")
            view = cast(dict[str, Any], parse_strict_json(bytes(row[0])))
            if view_hash(view) != row[1] or rfc8785.dumps(view) != row[0]:
                raise ValueError("E_LIVE_PROJECTION_HASH")
            return view, int(row[2])

    def bindings(self) -> dict[str, dict[str, Any]]:
        with self._mutex:
            self._owner()
            ids = [
                r[0]
                for r in self.db.execute(
                    "SELECT DISTINCT binding_id FROM projection_versions WHERE run_id=?",
                    (self.run_id,),
                )
            ]
            return {i: self.read_projection(i)["binding"] for i in ids}

    def projection_revision(self, binding_id: str) -> int:
        return self.read_projection_version(binding_id)[1]

    def cursor(self, stream_id: str, generation: str = "0") -> tuple[int, str]:
        with self._mutex:
            self._owner()
            row = self.db.execute(
                "SELECT sequence,content_hash FROM stream_cursors WHERE run_id=? AND "
                "stream_id=? AND generation=? ORDER BY sequence DESC LIMIT 1",
                (self.run_id, stream_id, int(generation)),
            ).fetchone()
            return (0, ZERO) if row is None else (int(row[0]), str(row[1]))

    def _binding_ids(self, event: dict[str, Any]) -> list[str]:
        kind, payload = event["payload_type"], event["payload"]
        bindings = self.bindings()
        if kind == "BindingChange":
            after = payload["after"]
            if any(
                b["provider_fixture_id"] == after["provider_fixture_id"]
                and b["binding_id"] != after["binding_id"]
                for b in bindings.values()
            ):
                raise ValueError("E_LIVE_BINDING_DUPLICATE")
            if (
                after["binding_id"] not in bindings
                and len(bindings)
                >= self.db.execute(
                    "SELECT max_matches FROM run_meta WHERE run_id=?", (self.run_id,)
                ).fetchone()[0]
            ):
                raise ValueError("E_LIVE_BINDING_SCOPE")
            return [str(after["binding_id"])]
        if kind == "ProviderState":
            ids = [
                i for i, b in bindings.items() if b["provider_fixture_id"] == payload["fixture_id"]
            ]
        elif kind == "HealthChange" and payload["binding_id"] is None:
            return list(bindings)
        else:
            ids = [payload["binding_id"]] if payload["binding_id"] in bindings else []
        if not ids:
            raise ValueError("E_LIVE_BINDING_REQUIRED")
        return ids

    def _stream_check(self, event: dict[str, Any]) -> None:
        stream, generation = event["stream_id"], int(event["generation"])
        previous = self.db.execute(
            "SELECT generation,source_kind,payload_canonical,receive_index FROM live_events "
            "WHERE run_id=? AND stream_id=? ORDER BY receive_index DESC LIMIT 1",
            (self.run_id, stream),
        ).fetchone()
        if previous is None:
            if generation != 0:
                raise ValueError("E_LIVE_GENERATION_REVIEW")
            return
        if (
            previous[1] != event["source_kind"]
            or generation < previous[0]
            or generation > previous[0] + 1
        ):
            raise ValueError("E_LIVE_STREAM_SCOPE")
        prior = json.loads(previous[2])
        if event["source_kind"] == "OPERATOR":
            if event["payload"]["binding_id"] != prior["payload"]["binding_id"]:
                raise ValueError("E_LIVE_BINDING_STREAM")
            if (
                generation == previous[0]
                and event["payload"]["document_epoch"] != prior["payload"]["document_epoch"]
            ):
                raise ValueError("E_LIVE_GENERATION_REVIEW")
        if generation > previous[0] and (
            event["source_kind"] != "OPERATOR"
            or event["payload"]["binding_revision"] == prior["payload"]["binding_revision"]
            or event["payload"]["document_epoch"] == prior["payload"]["document_epoch"]
        ):
            raise ValueError("E_LIVE_GENERATION_REVIEW")
        if generation == previous[0] and int(event["received_mono_us"]) < int(
            prior["received_mono_us"]
        ):
            raise ValueError("E_LIVE_STREAM_CLOCK")
        health_stream = str(uuid5(UUID(stream), "BH-LIVE-STORE/health"))
        controls = self.db.execute(
            "SELECT payload_canonical FROM live_events WHERE run_id=? AND stream_id=?",
            (self.run_id, health_stream),
        )
        if any(
            (p := json.loads(r[0])["payload"])["reason"] == "STREAM_CONFLICT"
            and int(p["epoch"]) == generation
            for r in controls
        ):
            raise ValueError("E_LIVE_STREAM_FROZEN")

    def _control_rejection(self, event: dict[str, Any], reason: str) -> None:
        if event["source_kind"] == "CONTROL":
            return
        ids = self._binding_ids(event)
        stream = str(uuid5(UUID(event["stream_id"]), "BH-LIVE-STORE/health"))
        sequence, previous = self.cursor(stream)
        control = {
            **event,
            "source_kind": "CONTROL",
            "stream_id": stream,
            "generation": "0",
            "sequence": str(sequence + 1),
            "observation_id": str(uuid4()),
            "payload_type": "HealthChange",
            "previous_hash": previous,
            "content_hash": ZERO,
            "payload": {
                "binding_id": ids[0] if len(ids) == 1 else None,
                "state": "PAUSED" if reason == "STREAM_CONFLICT" else "GAP",
                "reason": reason,
                "epoch": event["generation"],
                "evidence_hashes": [event["content_hash"]],
            },
        }
        control["content_hash"] = event_hash(control)
        self._append(control)

    def append(self, event: object) -> DurableReceipt:
        record = validate_live_record(event, "LiveEvent")
        if record["run_id"] != self.run_id or event_hash(record) != record["content_hash"]:
            raise ValueError("E_LIVE_EVENT_HASH_OR_RUN")
        _timestamp(record["observed_at_utc"])
        if (
            record["payload_type"] in {"ProviderState", "MarketBook"}
            and record["observed_at_utc"] != record["payload"]["observed_at_utc"]
        ):
            raise ValueError("E_LIVE_EVENT_OBSERVATION_TIME")
        with self._mutex:
            self._owner()
            try:
                return self._append(record)
            except ValueError as error:
                if str(error) in {"E_LIVE_STREAM_CONFLICT", "E_LIVE_SEQUENCE_GAP"}:
                    self._control_rejection(
                        record,
                        "STREAM_CONFLICT" if str(error).endswith("CONFLICT") else "SEQUENCE_GAP",
                    )
                raise

    def _append(self, event: dict[str, Any]) -> DurableReceipt:
        canonical = rfc8785.dumps(event)
        self.db.execute("BEGIN IMMEDIATE")
        try:
            position = (
                self.run_id,
                event["stream_id"],
                int(event["generation"]),
                int(event["sequence"]),
            )
            existing = self.db.execute(
                "SELECT receive_index,payload_canonical FROM live_events WHERE run_id=? AND "
                "stream_id=? AND generation=? AND sequence=?",
                position,
            ).fetchone()
            if existing and existing[1] == canonical:
                self._verify_receipt(int(existing[0]), event)
                self.db.execute("COMMIT")
                return DurableReceipt(
                    int(existing[0]),
                    *position[:2],
                    event["generation"],
                    event["sequence"],
                    event["content_hash"],
                )
            if self.db.execute(
                "SELECT 1 FROM run_closures WHERE run_id=?", (self.run_id,)
            ).fetchone():
                raise ValueError("E_LIVE_RUN_CLOSED")
            self._stream_check(event)
            if existing:
                raise ValueError("E_LIVE_STREAM_CONFLICT")
            sequence, previous_hash = self.cursor(event["stream_id"], event["generation"])
            if int(event["sequence"]) != sequence + 1:
                raise ValueError("E_LIVE_SEQUENCE_GAP")
            if event["previous_hash"] != previous_hash:
                raise ValueError("E_LIVE_CURSOR_MISMATCH")
            ids = self._binding_ids(event)
            projections = []
            for binding_id in ids:
                row = self.db.execute(
                    "SELECT revision FROM projection_versions WHERE run_id=? AND "
                    "binding_id=? ORDER BY revision DESC LIMIT 1",
                    (self.run_id, binding_id),
                ).fetchone()
                prior = None if row is None else self.read_projection(binding_id)
                view = reduce_projection(prior, event)
                projections.append(
                    (
                        binding_id,
                        1 if row is None else row[0] + 1,
                        rfc8785.dumps(view),
                        view_hash(view),
                    )
                )
            used = sum(p.stat().st_size for p in self.path.parent.iterdir() if p.is_file())
            if (
                used + 2 * len(canonical) + sum(len(p[2]) for p in projections) + 65536
                > self.max_bytes
            ):
                raise ValueError("E_LIVE_STORE_CAP")
            index = self.db.execute(
                "SELECT coalesce(max(receive_index),0)+1 FROM live_events"
            ).fetchone()[0]
            self.db.execute(
                "INSERT INTO live_events VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (
                    index,
                    *position[:3],
                    position[3],
                    event["observation_id"],
                    event["source_kind"],
                    event["payload_type"],
                    canonical,
                    event["previous_hash"],
                    event["content_hash"],
                    event["observed_at_utc"],
                    int(event["received_mono_us"]),
                ),
            )
            self.db.execute(
                "INSERT INTO "
                "stream_cursors(receive_index,run_id,stream_id,generation,sequence,content_hash) "
                "VALUES(?,?,?,?,?,?)",
                (index, *position, event["content_hash"]),
            )
            for binding_id, revision, payload, digest in projections:
                self.db.execute(
                    "INSERT INTO "
                    "projection_versions(receive_index,run_id,binding_id,revision,"
                    "canonical_view,content_hash) "
                    "VALUES(?,?,?,?,?,?)",
                    (index, self.run_id, binding_id, revision, payload, digest),
                )
            if event["payload_type"] == "ProviderState":
                p = event["payload"]
                self.db.execute(
                    "INSERT INTO request_links VALUES(?,?,?)",
                    (index, p["request_id"], p["batch_observation_id"]),
                )
            self.db.execute("COMMIT")
            self._verify_receipt(index, event)
            row = self.db.execute(
                "SELECT payload_canonical FROM live_events WHERE receive_index=?", (index,)
            ).fetchone()
            if row is None or row[0] != canonical:
                raise ValueError("E_LIVE_POSTCOMMIT_READBACK")
            return DurableReceipt(
                index,
                self.run_id,
                event["stream_id"],
                event["generation"],
                event["sequence"],
                event["content_hash"],
            )
        except BaseException as error:
            if self.db.in_transaction:
                self.db.execute("ROLLBACK")
            if isinstance(error, sqlite3.Error):
                raise ValueError("E_LIVE_STORE_IO") from None
            raise

    def _verify_receipt(self, index: int, event: dict[str, Any]) -> None:
        cursor = self.db.execute(
            "SELECT run_id,stream_id,generation,sequence,content_hash FROM stream_cursors "
            "WHERE receive_index=?",
            (index,),
        ).fetchone()
        expected = (
            self.run_id,
            event["stream_id"],
            int(event["generation"]),
            int(event["sequence"]),
            event["content_hash"],
        )
        if cursor != expected:
            raise ValueError("E_LIVE_POSTCOMMIT_CURSOR")
        projections = self.db.execute(
            "SELECT canonical_view,content_hash FROM projection_versions WHERE receive_index=?",
            (index,),
        ).fetchall()
        if event["payload_type"] != "HealthChange" and len(projections) != 1:
            raise ValueError("E_LIVE_POSTCOMMIT_PROJECTION")
        for canonical, digest in projections:
            view = cast(dict[str, Any], parse_strict_json(canonical))
            if rfc8785.dumps(view) != canonical or view_hash(view) != digest:
                raise ValueError("E_LIVE_POSTCOMMIT_PROJECTION")
        links = self.db.execute(
            "SELECT request_id,batch_observation_id FROM request_links WHERE receive_index=?",
            (index,),
        ).fetchall()
        expected_links = (
            []
            if event["payload_type"] != "ProviderState"
            else [(event["payload"]["request_id"], event["payload"]["batch_observation_id"])]
        )
        if links != expected_links:
            raise ValueError("E_LIVE_POSTCOMMIT_REQUEST_LINK")

    def close_run(self, closed_at_utc: str, reason_code: str) -> None:
        _timestamp(closed_at_utc)
        if reason_code not in {
            "USER_STOP",
            "RUN_DEADLINE",
            "SOURCE_STOPPED",
            "STORAGE_CAP",
            "SECURITY_HOLD",
        }:
            raise ValueError("E_LIVE_CLOSE_REASON")
        with self._mutex:
            self._owner()
            row = (
                self.run_id,
                closed_at_utc,
                reason_code,
                self.db.execute("SELECT max(receive_index) FROM live_events").fetchone()[0],
            )
            old = self.db.execute(
                "SELECT * FROM run_closures WHERE run_id=?", (self.run_id,)
            ).fetchone()
            if old is not None:
                if old != row:
                    raise ValueError("E_LIVE_RUN_CLOSED")
                return
            self.db.execute("INSERT INTO run_closures VALUES(?,?,?,?)", row)"""Closed live-only wire, role-bound handshake, finite one-time pairing lease."""

import base64
import hashlib
import hmac
import math
import secrets
import threading
import time
from collections.abc import Callable
from dataclasses import dataclass, field
from typing import Any, cast
from uuid import UUID, uuid4

import rfc8785

from .canonical import parse_strict_json
from .live_contracts import event_hash, schema_validate, validate_live_record

PROTOCOL = "BH_LIVE_WIRE_V1"
DOMAIN = b"BH-LIVE-WIRE/v1\0"
ROLES = frozenset({"CAPTURE_PRODUCER", "UI_SUBSCRIBER"})
CLIENT_TYPES = {
    "CAPTURE_PRODUCER": {"CAPTURE_BATCH", "HEALTH", "STOP_CAPTURE", "PING", "PONG"},
    "UI_SUBSCRIBER": {
        "WATCHLIST_ADD",
        "WATCHLIST_REMOVE",
        "SELECT_ACTIVE",
        "REFRESH",
        "STOP_SESSION",
        "PING",
        "PONG",
    },
}
BACKEND_TYPES = frozenset({"ACK", "NACK", "PROJECTION", "PING", "PONG"})


def validate_frame(value: object) -> dict[str, Any]:
    try:
        schema_validate(value, "wire")
        frame = cast(dict[str, Any], value)
        if len(rfc8785.dumps(frame)) > 262144:
            raise ValueError()
        body = frame["body"]
        if frame["message_type"] == "CAPTURE_BATCH":
            first, last = int(body["first_sequence"]), int(body["last_sequence"])
            if last - first + 1 != len(body["events"]):
                raise ValueError()
            for sequence, raw in enumerate(body["events"], first):
                event = validate_live_record(raw, "LiveEvent")
                if (
                    event["source_kind"] != "OPERATOR"
                    or event["payload_type"] != "MarketBook"
                    or any(event[k] != body[k] for k in ("run_id", "stream_id", "generation"))
                    or event["sequence"] != str(sequence)
                    or event_hash(event) != event["content_hash"]
                ):
                    raise ValueError()
        elif frame["message_type"] == "PROJECTION":
            validate_live_record(body["binding"], "FixtureBinding")
            health = validate_live_record(body["health"], "HealthChange")
            if health["binding_id"] not in {None, body["binding"]["binding_id"]}:
                raise ValueError()
            if body["provider_state"] is not None:
                state = validate_live_record(body["provider_state"], "ProviderState")
                if state["fixture_id"] != body["binding"]["provider_fixture_id"]:
                    raise ValueError()
            horizons = set()
            for value in body["books"]:
                book = validate_live_record(value, "MarketBook")
                if (
                    book["binding_id"] != body["binding"]["binding_id"]
                    or book["binding_revision"] != body["binding"]["revision"]
                    or book["horizon"] in horizons
                ):
                    raise ValueError()
                horizons.add(book["horizon"])
            if "display" in body and set(body["display"]["markets"]) != horizons:
                raise ValueError()
            if "capture_scope" in body:
                scope = body["capture_scope"]
                if (
                    "display" not in body
                    or scope["exact_url"] != body["binding"]["operator_match_url"]
                    or (scope["profile_status"] == "DRAFT")
                    != (body["display"]["source_kind"] == "MOCK")
                    or int(scope["generation"]) > 2**63 - 1
                    or any(book["profile_hash"] != scope["profile_hash"] for book in body["books"])
                ):
                    raise ValueError()
        return frame
    except Exception:
        raise ValueError("E_LIVE_WIRE_SCHEMA") from None


def encode_frame(content: dict[str, Any], key: bytes) -> bytes:
    if type(key) is not bytes or len(key) != 32 or "mac" in content:
        raise ValueError("E_LIVE_WIRE_KEY")
    validate_frame({**content, "mac": "0" * 64})
    signature = hmac.new(key, DOMAIN + rfc8785.dumps(content), hashlib.sha256).hexdigest()
    return rfc8785.dumps({**content, "mac": signature})


def decode_frame(data: bytes, key: bytes) -> dict[str, Any]:
    if type(data) is not bytes or len(data) > 262144 or type(key) is not bytes or len(key) != 32:
        raise ValueError("E_LIVE_WIRE_FRAME")
    try:
        frame = validate_frame(parse_strict_json(data))
        content = {k: v for k, v in frame.items() if k != "mac"}
        expected = hmac.new(key, DOMAIN + rfc8785.dumps(content), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(frame["mac"], expected):
            raise ValueError()
        return frame
    except Exception:
        raise ValueError("E_LIVE_WIRE_AUTHENTICATION") from None


class LiveSession:
    def __init__(
        self,
        session_id: str,
        run_id: str,
        side: str,
        role: str,
        deadline_mono: float,
        *,
        clock: Callable[[], float] = time.monotonic,
    ):
        for identifier in (session_id, run_id):
            if str(UUID(identifier)) != identifier:
                raise ValueError("E_LIVE_WIRE_IDENTITY")
        if (
            side not in {"CLIENT", "BACKEND"}
            or role not in ROLES
            or not math.isfinite(deadline_mono)
            or not 0 < deadline_mono - clock() <= 7200
        ):
            raise ValueError("E_LIVE_WIRE_ROLE_OR_LEASE")
        self.session_id, self.run_id, self.side, self.role = session_id, run_id, side, role
        self.deadline, self.clock, self.started = deadline_mono, clock, clock()
        self.stage, self.in_counter, self.out_counter = 0, 0, 0
        self.client_nonce: str | None = None
        self.server_nonce: str | None = None

    @property
    def ready(self) -> bool:
        return self.stage == 4 and self.clock() < self.deadline

    def accept(self, frame: dict[str, Any], incoming: bool) -> None:
        validate_frame(frame)
        now = self.clock()
        if now < self.started or now >= self.deadline:
            raise ValueError("E_LIVE_WIRE_LEASE")
        outgoing = "CLIENT_TO_BACKEND" if self.side == "CLIENT" else "BACKEND_TO_CLIENT"
        direction = (
            ("BACKEND_TO_CLIENT" if outgoing == "CLIENT_TO_BACKEND" else "CLIENT_TO_BACKEND")
            if incoming
            else outgoing
        )
        counter = (self.in_counter if incoming else self.out_counter) + 1
        body, kind = frame["body"], frame["message_type"]
        if (
            frame["session_id"] != self.session_id
            or frame["direction"] != direction
            or frame["counter"] != str(counter)
            or body["run_id"] != self.run_id
        ):
            raise ValueError("E_LIVE_WIRE_SESSION_COUNTER")
        stage, client, server = self.stage, self.client_nonce, self.server_nonce
        if stage < 4:
            if now - self.started > 5:
                raise ValueError("E_LIVE_WIRE_HANDSHAKE_TIMEOUT")
            types = ("HELLO", "WELCOME", "READY", "READY_ACK")
            expected_incoming = stage % 2 == (1 if self.side == "CLIENT" else 0)
            if kind != types[stage] or incoming != expected_incoming:
                raise ValueError("E_LIVE_WIRE_HANDSHAKE_ORDER")
            for name in ("client_nonce", "server_nonce"):
                if name in body:
                    decoded = base64.urlsafe_b64decode(body[name] + "=")
                    if (
                        len(decoded) != 32
                        or base64.urlsafe_b64encode(decoded).rstrip(b"=").decode() != body[name]
                    ):
                        raise ValueError("E_LIVE_WIRE_NONCE")
            if stage == 0:
                if body["role"] != self.role:
                    raise ValueError("E_LIVE_WIRE_ROLE")
                client = body["client_nonce"]
            elif body["client_nonce"] != client:
                raise ValueError("E_LIVE_WIRE_NONCE")
            if stage == 1:
                server = body["server_nonce"]
                if server == client:
                    raise ValueError("E_LIVE_WIRE_NONCE")
            elif stage >= 2 and body["server_nonce"] != server:
                raise ValueError("E_LIVE_WIRE_NONCE")
            stage += 1
        elif kind not in (
            CLIENT_TYPES[self.role] if direction == "CLIENT_TO_BACKEND" else BACKEND_TYPES
        ):
            raise ValueError("E_LIVE_WIRE_ROLE_DENIED")
        self.stage, self.client_nonce, self.server_nonce = stage, client, server
        if incoming:
            self.in_counter = counter
        else:
            self.out_counter = counter

    def send(self, kind: str, body: dict[str, Any], key: bytes) -> bytes:
        content = dict(
            protocol=PROTOCOL,
            session_id=self.session_id,
            direction="CLIENT_TO_BACKEND" if self.side == "CLIENT" else "BACKEND_TO_CLIENT",
            counter=str(self.out_counter + 1),
            message_type=kind,
            body=body,
        )
        data = encode_frame(content, key)
        self.accept({**content, "mac": "0" * 64}, False)
        return data

    def receive(self, data: bytes, key: bytes) -> dict[str, Any]:
        frame = decode_frame(data, key)
        self.accept(frame, True)
        return frame


@dataclass(frozen=True)
class PairingTicket:
    session_id: str
    role: str
    expires_mono: float
    key: bytes = field(repr=False)

    def __repr__(self) -> str:
        return "PairingTicket([REDACTED])"


class PairingAuthority:
    def __init__(
        self, run_id: str, deadline_mono: float, *, clock: Callable[[], float] = time.monotonic
    ):
        if (
            str(UUID(run_id)) != run_id
            or not math.isfinite(deadline_mono)
            or not 0 < deadline_mono - clock() <= 7200
        ):
            raise ValueError("E_LIVE_PAIRING_SCOPE")
        self.run_id, self.deadline, self.clock = run_id, deadline_mono, clock
        self._tickets: dict[str, PairingTicket] = {}
        self._issued = 0
        self._lock = threading.Lock()

    def issue(self, role: str) -> PairingTicket:
        with self._lock:
            now = self.clock()
            self._tickets = {s: t for s, t in self._tickets.items() if t.expires_mono > now}
            if (
                role not in ROLES
                or now >= self.deadline
                or len(self._tickets) >= 2
                or self._issued >= 32
            ):
                raise ValueError("E_LIVE_PAIRING_CAP")
            ticket = PairingTicket(
                str(uuid4()), role, min(now + 120, self.deadline), secrets.token_bytes(32)
            )
            self._tickets[ticket.session_id] = ticket
            self._issued += 1
            return ticket

    def revoke(self) -> None:
        with self._lock:
            self._tickets.clear()
            self.deadline = self.clock()

    def consume(self, data: bytes) -> tuple[LiveSession, bytes]:
        with self._lock:
            try:
                if type(data) is not bytes or len(data) > 262144:
                    raise ValueError()
                hello = validate_frame(parse_strict_json(data))
                ticket = self._tickets[hello["session_id"]]
                if self.clock() >= ticket.expires_mono:
                    raise ValueError()
                session = LiveSession(
                    ticket.session_id,
                    self.run_id,
                    "BACKEND",
                    ticket.role,
                    self.deadline,
                    clock=self.clock,
                )
                session.receive(data, ticket.key)
                if session.stage != 1:
                    raise ValueError()
                del self._tickets[ticket.session_id]
                return session, ticket.key
            except Exception:
                raise ValueError("E_LIVE_PAIRING_REJECTED") from None"""One bounded two-read DOM snapshot becomes one complete display-only book."""

import copy
from dataclasses import dataclass
from typing import Any

from .live_contracts import MAX_INTEGER, validate_live_record
from .operator_profile import ExtractionProfile, activate_profile, parse_decimal_price

SNAPSHOT_FIELDS = frozenset(
    {
        "operator_fixture_id",
        "home_id",
        "away_id",
        "market_id",
        "horizon",
        "settlement_basis",
        "selections",
        "market_status",
        "operator_score",
        "operator_period",
    }
)


@dataclass(frozen=True)
class CapturedFields:
    snapshots: tuple[dict[str, Any], dict[str, Any]]
    binding: dict[str, Any]
    exact_url: str
    observed_at_utc: str
    first_read_mono_us: int
    browser_mono_us: int
    clock_domain_id: str
    capture_revision: str
    document_epoch: str


def assemble_book(capture: CapturedFields, profile: ExtractionProfile) -> dict[str, Any]:
    try:
        data = activate_profile(
            profile,
            "SYNTHETIC_TEST" if profile.public["source_kind"] == "SYNTHETIC_TEST" else "OPERATOR",
        )
        binding = validate_live_record(capture.binding, "FixtureBinding")
        first, second = capture.snapshots
        if (
            set(first) != SNAPSHOT_FIELDS
            or first != second
            or type(capture.first_read_mono_us) is not int
            or type(capture.browser_mono_us) is not int
            or not 0 <= capture.first_read_mono_us < capture.browser_mono_us <= MAX_INTEGER
            or not 100000 <= capture.browser_mono_us - capture.first_read_mono_us <= 1000000
            or capture.exact_url != binding["operator_match_url"]
            or capture.exact_url not in {data["origin"] + p for p in data["exact_paths"]}
            or first["operator_fixture_id"] != binding["operator_fixture_id"]
            or first["home_id"] != binding["operator_home_id"]
            or first["away_id"] != binding["operator_away_id"]
        ):
            raise ValueError()
        observed = [
            m
            for m in profile.observed_markets[first["operator_fixture_id"]]
            if m["market_id"] == first["market_id"] and m["horizon"] == first["horizon"]
        ]
        if (
            len(observed) != 1
            or first["settlement_basis"] != observed[0]["settlement_basis"]
            or set(first["selections"]) != {"HOME", "DRAW", "AWAY"}
        ):
            raise ValueError()
        selections = {}
        for side, quote in first["selections"].items():
            if (
                set(quote) != {"selection_id", "price_text"}
                or quote["selection_id"] != observed[0]["selections"][side]
            ):
                raise ValueError()
            selections[side] = {
                "selection_id": quote["selection_id"],
                "decimal_odds": parse_decimal_price(quote["price_text"], data["price_parser"]),
            }
        return validate_live_record(
            {
                **{
                    k: copy.deepcopy(first[k])
                    for k in SNAPSHOT_FIELDS - {"home_id", "away_id", "selections"}
                },
                "binding_id": binding["binding_id"],
                "binding_revision": binding["revision"],
                "selections": selections,
                "capture_revision": capture.capture_revision,
                "native_revision": None,
                "observed_at_utc": capture.observed_at_utc,
                "browser_mono_us": str(capture.browser_mono_us),
                "clock_domain_id": capture.clock_domain_id,
                "source_updated_at": None,
                "capture_evidence_tier": "DISPLAY_COHERENT",
                "profile_hash": profile.profile_hash,
                "document_epoch": capture.document_epoch,
                "quality_flags": ["SYNTHETIC"] if data["source_kind"] == "SYNTHETIC_TEST" else [],
            },
            "MarketBook",
        )
    except Exception:
        raise ValueError("E_LIVE_BOOK") from None"""Fail-closed MATERIALIZATION_COMPLETE gate for the sealed authoring inventory."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path, PurePosixPath

from jsonschema import Draft202012Validator


def _fail(code: str, path: str = "") -> None:
    raise ValueError(f"E_MATERIALIZATION_COMPLETE:{code}{':' + path if path else ''}")


def _safe_file(root: Path, relative: str) -> Path | None:
    path = PurePosixPath(relative)
    if path.is_absolute() or not path.parts or any(part in {"", ".", ".."} for part in path.parts):
        return None
    current = root
    for part in path.parts:
        current /= part
        if current.is_symlink():
            return None
    return current if current.is_file() else None


def _read_json(path: Path, code: str) -> dict[str, object]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        _fail(code)
    if not isinstance(value, dict):
        _fail(code)
    return value


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _source_is_valid(entry: dict[str, object]) -> bool:
    source = entry["source"]
    classification = entry["classification"]
    if classification in {"BASELINE_INPUT", "PLAN_SEED", "GENERATED_OUTPUT"}:
        return (
            isinstance(source, dict)
            and set(source) == {"path"}
            and isinstance(source["path"], str)
            and bool(source["path"].strip())
        )
    if classification == "BASELINE_COPY":
        return (
            isinstance(source, dict)
            and set(source) == {"path", "sha256"}
            and isinstance(source["path"], str)
            and isinstance(source["sha256"], str)
            and len(source["sha256"]) == 64
            and all(char in "0123456789abcdef" for char in source["sha256"])
        )
    if classification in {"TASK_OUTPUT", "EVIDENCE_OUTPUT"}:
        return source is None
    if classification == "EXTERNAL_INPUT":
        return (
            isinstance(source, dict)
            and set(source) in (
                {"path", "binding"},
                {"path", "binding", "creation_owner", "creation_command"},
            )
            and all(isinstance(value, str) and value.strip() for value in source.values())
        )
    return False


def _verify_plan_closure(plan_root: Path, expected_manifest_hash: str) -> None:
    manifest_path = _safe_file(plan_root, "MANIFEST_SHA256.json")
    if manifest_path is None or _sha256(manifest_path) != expected_manifest_hash:
        _fail("BOOTSTRAP")
    manifest = _read_json(manifest_path, "MANIFEST")
    entries = manifest.get("entries")
    if not isinstance(entries, list):
        _fail("MANIFEST")
    listed: set[str] = set()
    for entry in entries:
        if not isinstance(entry, dict):
            _fail("MANIFEST")
        relative = entry.get("path")
        size = entry.get("size")
        digest = entry.get("sha256")
        if (
            not isinstance(relative, str)
            or not isinstance(size, int)
            or isinstance(size, bool)
            or size < 0
            or not isinstance(digest, str)
            or len(digest) != 64
            or relative in listed
        ):
            _fail("MANIFEST")
        file_path = _safe_file(plan_root, relative)
        if file_path is None or file_path.stat().st_size != size or _sha256(file_path) != digest:
            _fail("MANIFEST", relative)
        listed.add(relative)
    actual: set[str] = set()
    for candidate in plan_root.rglob("*"):
        if candidate.is_symlink():
            _fail("PLAN_SYMLINK")
        if candidate.is_file():
            actual.add(candidate.relative_to(plan_root).as_posix())
    if actual != listed | {"MANIFEST_SHA256.json"}:
        _fail("MANIFEST_CLOSURE")


def validate_materialization_complete(root: Path) -> dict[str, object]:
    """Validate every required artifact without consuming deferred external outputs."""
    if root.is_symlink() or not root.is_dir():
        _fail("ROOT")
    runtime_root = root.resolve()
    authoring_root = runtime_root.parent
    plan_root = authoring_root / "plan-input"
    bootstrap_path = _safe_file(authoring_root, ".bootstrap/authoring-workspace-receipt.json")
    if bootstrap_path is None or plan_root.is_symlink() or not plan_root.is_dir():
        _fail("BOOTSTRAP")
    bootstrap = _read_json(bootstrap_path, "BOOTSTRAP")
    if (
        bootstrap.get("authoring_root") != str(authoring_root)
        or bootstrap.get("plan_input_root") != str(plan_root)
        or not isinstance(bootstrap.get("manifest_sha256"), str)
    ):
        _fail("BOOTSTRAP")
    _verify_plan_closure(plan_root, bootstrap["manifest_sha256"])

    ownership_path = _safe_file(plan_root, "docs/registries/artifact-ownership.v1.json")
    schema_path = _safe_file(plan_root, "docs/schemas/artifact-ownership.schema.json")
    tasks_path = _safe_file(plan_root, "docs/tasks/task-manifest.v6.3.6.json")
    if ownership_path is None or schema_path is None or tasks_path is None:
        _fail("DECLARATION_INPUT")
    ownership = _read_json(ownership_path, "OWNERSHIP")
    schema = _read_json(schema_path, "OWNERSHIP_SCHEMA")
    schema = {**schema, "$ref": "#/$defs/ArtifactOwnershipRegistry"}
    if list(Draft202012Validator(schema).iter_errors(ownership)):
        _fail("OWNERSHIP_SCHEMA")
    task_manifest = _read_json(tasks_path, "TASKS")
    tasks = task_manifest.get("tasks")
    if not isinstance(tasks, list):
        _fail("TASKS")
    order = {
        task["task_id"]: index
        for index, task in enumerate(tasks)
        if isinstance(task, dict) and isinstance(task.get("task_id"), str)
    }
    if len(order) != len(tasks) or "V636-P01-T06" not in order:
        _fail("TASKS")
    cutoff = order["V636-P01-T06"]

    entries = ownership.get("entries")
    if not isinstance(entries, list):
        _fail("OWNERSHIP")
    paths: set[str] = set()
    materialized = 0
    deferred = 0
    for entry in entries:
        if not isinstance(entry, dict):
            _fail("ENTRY")
        path = entry.get("path")
        owner = entry.get("creation_owner")
        if not isinstance(path, str) or not path or path in paths or not _source_is_valid(entry):
            _fail("ENTRY", path if isinstance(path, str) else "")
        paths.add(path)
        if owner is None:
            if entry["source"] is None:
                _fail("UNOWNED", path)
        elif not isinstance(owner, str) or owner not in order:
            _fail("UNKNOWN_OWNER", path)
        for field, code in (
            ("modifying_tasks", "MODIFIER"),
            ("consumers", "CONSUMER"),
        ):
            for task_id in entry[field]:
                if task_id not in order:
                    _fail(code, path)
                if owner is not None and order[task_id] < order[owner]:
                    _fail("CONSUMER_BEFORE_OWNER", path)
        qualification = entry["qualification_owner"]
        if qualification is not None:
            if qualification not in order or owner is not None and order[qualification] < order[owner]:
                _fail("QUALIFICATION", path)

        if not entry["materialization_required"]:
            deferred += 1
            continue
        if PurePosixPath(path).is_absolute() or owner is not None and order[owner] > cutoff:
            _fail("FUTURE_OWNER", path)
        target = _safe_file(authoring_root, path)
        if target is None:
            _fail("MISSING", path)
        classification = entry["classification"]
        source = entry["source"]
        if classification == "BASELINE_COPY":
            assert isinstance(source, dict)
            source_path = Path(source["path"])
            if not source_path.is_file() or source_path.is_symlink() or _sha256(source_path) != source["sha256"]:
                _fail("BASELINE_SOURCE", path)
        elif classification == "PLAN_SEED":
            assert isinstance(source, dict)
            source_path = _safe_file(authoring_root, source["path"])
            if source_path is None or source_path.read_bytes() != target.read_bytes():
                _fail("PLAN_SEED", path)
        materialized += 1

    receipt = {
        "schema_version": "materialization-complete/v2",
        "gate": "MATERIALIZATION_COMPLETE",
        "result": "PASS",
        "artifact_root": str(runtime_root),
        "authoring_root": str(authoring_root),
        "plan_input_manifest_sha256": bootstrap["manifest_sha256"],
        "materialized_artifact_count": materialized,
        "deferred_artifact_count": deferred,
        "authorized_production_phases": "NONE",
    }
    payload = json.dumps(receipt, sort_keys=True, separators=(",", ":")).encode()
    receipt["content_hash"] = hashlib.sha256(b"HD636/MATERIALIZATION/v1\\0" + payload).hexdigest()
    return receipt"""Explicit offline-only SQLite denial, retaining the actual authorization decision."""

import os
import sqlite3
from pathlib import Path
from typing import Any

import rfc8785

from .store import RunStore, _runtime_authorizer


class WriteDeniedStore(RunStore):
    def __init__(self, db_path: Path, event_path: Path):
        super().__init__(db_path)
        self.event_path = event_path

    def connect(self) -> sqlite3.Connection:
        db = super().connect()
        committed = db.execute(
            "SELECT raw_observation_content_hash FROM raw_commits ORDER BY sequence"
        ).fetchall()
        if len(committed) == 2:

            def authorize(
                action: int,
                table: str | None,
                column: str | None,
                database: str | None,
                trigger: str | None,
            ) -> int:
                if action == sqlite3.SQLITE_INSERT and table == "raw_commits":
                    event: dict[str, Any] = {
                        "operation": "SQLITE_DENY",
                        "action": action,
                        "table": table,
                        "committed_hashes": [row[0] for row in committed],
                    }
                    descriptor = os.open(
                        self.event_path,
                        os.O_WRONLY | os.O_CREAT | os.O_APPEND | os.O_NOFOLLOW,
                        0o600,
                    )
                    with os.fdopen(descriptor, "ab") as output:
                        output.write(rfc8785.dumps(event) + b"\n")
                        output.flush()
                        os.fsync(output.fileno())
                    return sqlite3.SQLITE_DENY
                return _runtime_authorizer(action, table, column, database, trigger)

            db.set_authorizer(authorize)
        return db"""Compare every logical SQLite column, excluding only the supplied physical times."""

import hashlib
import json
import re
import sqlite3
from contextlib import closing
from pathlib import Path
from typing import Any

import rfc8785

from .store import read_journal, validate_journal, verified_ddl, verify_database

CONTRACT = Path(__file__).resolve().parents[2] / "contracts/offline_slice/v1/replay-projection.json"


def semantic_projection(db_path: Path) -> dict[str, list[dict[str, Any]]]:
    if (
        db_path.is_symlink()
        or not db_path.is_file()
        or db_path.stat().st_nlink != 1
        or any(parent.is_symlink() for parent in db_path.parents)
    ):
        raise ValueError("E_OFFLINE_DATABASE_BINDING")
    contract = json.loads(CONTRACT.read_text())
    ddl = verified_ddl().encode()
    blob = hashlib.sha1(
        b"blob " + str(len(ddl)).encode() + b"\0" + ddl, usedforsecurity=False
    ).hexdigest()
    if blob != contract["ddl_git_blob"]:
        raise ValueError("E_OFFLINE_PROJECTION_DDL")
    exclusions = contract["table_time_exclusions"]
    with closing(sqlite3.connect(db_path.resolve().as_uri() + "?mode=ro", uri=True)) as db:
        db.row_factory = sqlite3.Row
        verify_database(db)
        validate_journal(read_journal(db, ordered=False))
        tables = [row[0] for row in db.execute("SELECT name FROM sqlite_schema WHERE type='table'")]
        if not set(exclusions).issubset(tables):
            raise ValueError("E_OFFLINE_PROJECTION_TABLE")
        projected = {}
        for table in sorted(tables):
            if not re.fullmatch("[a-z_]+", table):
                raise ValueError("E_OFFLINE_PROJECTION_TABLE")
            cursor = db.execute(f'SELECT * FROM "{table}"')  # noqa: S608 -- verified DDL identifiers
            columns = {column[0] for column in cursor.description}
            excluded = set(exclusions.get(table, []))
            if not excluded.issubset(columns):
                raise ValueError("E_OFFLINE_PROJECTION_COLUMN")
            rows = [{name: row[name] for name in columns - excluded} for row in cursor.fetchall()]
            if table not in exclusions and rows:
                raise ValueError("E_OFFLINE_UNEXPECTED_TABLE_STATE")
            projected[table] = sorted(rows, key=rfc8785.dumps)
        return projected"""Closed offline schema and identity checks; no production transport authority."""

import json
from collections.abc import Callable
from functools import lru_cache
from typing import Any, cast

import rfc8785
from jsonschema import Draft202012Validator  # type: ignore[import-untyped]

from .schema_registry import _compiled, validate_artifact
from .store import VENDOR

CONTRACTS = VENDOR.parents[1] / "contracts/offline_slice/v1"
MAX_INTEGER = 9223372036854775807


def _validator(name: str) -> Draft202012Validator:
    return _compiled((CONTRACTS / name).read_bytes(), _resources())


def _resources() -> tuple[bytes, ...]:
    return tuple(p.read_bytes() for p in sorted((VENDOR / "schemas").glob("*.json"))) + tuple(
        p.read_bytes() for p in sorted(CONTRACTS.glob("*.schema.json"))
    )


@lru_cache(maxsize=8)
def _envelope(schema_bytes: bytes, resources: tuple[bytes, ...]) -> Draft202012Validator:
    schema = json.loads(schema_bytes)
    observations = schema["$defs"]["BATCH"]["properties"]["observations"]
    if observations["items"] != {"$ref": "urn:hybrid-discovery:v6.2:raw-observation:v1"}:
        raise ValueError("E_OFFLINE_SCHEMA_CONTRACT")
    # Equivalent conjunction: closed envelope AND every complete raw schema below.
    # Separate raw proofs can be reused by the journal/ingestor, with exact source bytes.
    observations["items"] = True
    encoded = json.dumps(schema).encode()
    return _compiled(
        encoded, tuple(encoded if data == schema_bytes else data for data in resources)
    )


def validate_context(value: dict[str, Any]) -> None:
    try:
        _validator("context.schema.json").validate(value)
        if not 1024 <= int(value["normal_spool_limit_bytes"]) <= 133169152:
            raise ValueError()
        if int(value["generation"]) > MAX_INTEGER:
            raise ValueError()
    except Exception:
        raise ValueError("E_OFFLINE_SOURCE_BINDING") from None


def validate_frame(value: dict[str, Any]) -> None:
    try:
        _envelope((CONTRACTS / "frame.schema.json").read_bytes(), _resources()).validate(value)
        if int(value["counter"]) > MAX_INTEGER:
            raise ValueError()
        if value["message_type"] == "BATCH":
            body = value["body"]
            first, last = int(body["first_sequence"]), int(body["last_sequence"])
            if not 1 <= first <= last <= MAX_INTEGER or last - first + 1 != len(
                body["observations"]
            ):
                raise ValueError()
            if int(body["generation"]) > MAX_INTEGER:
                raise ValueError()
            for sequence, raw in enumerate(body["observations"], first):
                validate_artifact(
                    raw, "raw-observation.schema.json", bootstrap_only=True, vendor=VENDOR
                )
                if (
                    raw["discovery_run_id"] != body["run_id"]
                    or raw["context"]["browser_run_id"] != body["browser_run_id"]
                    or raw["stream_id"] != body["stream_id"]
                    or raw["generation"] != body["generation"]
                    or raw["sequence"] != str(sequence)
                    or len(rfc8785.dumps(raw)) > 65536
                ):
                    raise ValueError()
        if len(rfc8785.dumps(value)) > 262144:
            raise ValueError()
    except Exception:
        raise ValueError("E_OFFLINE_SCHEMA") from None


# Standard-library HMAC; the key is never included in frame or context serialization.
def encode_frame(frame_without_mac: dict[str, Any], key: bytes) -> bytes:
    import hashlib
    import hmac

    if len(key) != 32 or "mac" in frame_without_mac:
        raise ValueError("E_OFFLINE_KEY_OR_FRAME")
    frame = {**frame_without_mac, "mac": "0" * 64}
    validate_frame(frame)
    frame["mac"] = hmac.new(
        key, b"BH-OFFLINE-WIRE/v1\0" + rfc8785.dumps(frame_without_mac), hashlib.sha256
    ).hexdigest()
    return rfc8785.dumps(frame)


class SessionState:
    def __init__(
        self, session_id: str, run_id: str, role: str, clock: Callable[[], float] | None = None
    ) -> None:
        from time import monotonic

        if role not in {"CLIENT", "BACKEND"}:
            raise ValueError("E_OFFLINE_ROLE")
        self.session_id = session_id
        self.run_id = run_id
        self.role = role
        self.clock = clock or monotonic
        self.started = self.clock()
        self.stage = 0
        self.in_counter = 0
        self.out_counter = 0
        self.client_nonce: str | None = None
        self.server_nonce: str | None = None

    @property
    def ready(self) -> bool:
        return self.stage == 4

    def accept(self, frame: dict[str, Any], *, incoming: bool) -> None:
        import base64

        outgoing = "CLIENT_TO_BACKEND" if self.role == "CLIENT" else "BACKEND_TO_CLIENT"
        direction = (
            ("BACKEND_TO_CLIENT" if outgoing == "CLIENT_TO_BACKEND" else "CLIENT_TO_BACKEND")
            if incoming
            else outgoing
        )
        expected_counter = (self.in_counter if incoming else self.out_counter) + 1
        if (
            frame["session_id"] != self.session_id
            or frame["direction"] != direction
            or frame["counter"] != str(expected_counter)
        ):
            raise ValueError("E_OFFLINE_SESSION_COUNTER")
        body = frame["body"]
        if "run_id" in body and body["run_id"] != self.run_id:
            raise ValueError("E_OFFLINE_SOURCE_BINDING")
        client_nonce, server_nonce = self.client_nonce, self.server_nonce
        stage = self.stage
        if stage < 4:
            if self.clock() - self.started > 5:
                raise ValueError("E_OFFLINE_HANDSHAKE_TIMEOUT")
            types = ("HELLO", "WELCOME", "READY", "READY_ACK")
            expected_incoming = (stage % 2 == 1) if self.role == "CLIENT" else (stage % 2 == 0)
            if frame["message_type"] != types[stage] or incoming != expected_incoming:
                raise ValueError("E_OFFLINE_HANDSHAKE_ORDER")
            for name in ("client_nonce", "server_nonce"):
                if name in body:
                    nonce = body[name]
                    decoded = base64.urlsafe_b64decode(nonce + "=")
                    if (
                        len(decoded) != 32
                        or base64.urlsafe_b64encode(decoded).rstrip(b"=").decode() != nonce
                    ):
                        raise ValueError("E_OFFLINE_NONCE")
            if stage == 0:
                client_nonce = body["client_nonce"]
            elif body["client_nonce"] != client_nonce:
                raise ValueError("E_OFFLINE_NONCE")
            if stage == 1:
                server_nonce = body["server_nonce"]
                if server_nonce == client_nonce:
                    raise ValueError("E_OFFLINE_NONCE")
            elif stage >= 2 and body["server_nonce"] != server_nonce:
                raise ValueError("E_OFFLINE_NONCE")
            stage += 1
        elif stage != 4 or frame["message_type"] in {"HELLO", "WELCOME", "READY", "READY_ACK"}:
            raise ValueError("E_OFFLINE_HANDSHAKE_ORDER")
        elif frame["message_type"] == "STOP":
            stage = 5
        self.client_nonce, self.server_nonce, self.stage = client_nonce, server_nonce, stage
        if incoming:
            self.in_counter = expected_counter
        else:
            self.out_counter = expected_counter

    def send(self, message_type: str, body: dict[str, Any], key: bytes) -> bytes:
        frame = {
            "protocol": "BH_OFFLINE_WIRE_V1",
            "session_id": self.session_id,
            "direction": "CLIENT_TO_BACKEND" if self.role == "CLIENT" else "BACKEND_TO_CLIENT",
            "counter": str(self.out_counter + 1),
            "message_type": message_type,
            "body": body,
        }
        encoded = encode_frame(frame, key)
        self.accept(frame, incoming=False)
        return encoded


def verify_frame(data: bytes, key: bytes, session: SessionState) -> dict[str, Any]:
    import hashlib
    import hmac

    from .canonical import parse_strict_json

    if len(data) > 262144 or len(key) != 32:
        raise ValueError("E_OFFLINE_FRAME_SIZE_OR_KEY")
    try:
        parsed = parse_strict_json(data)
        if not isinstance(parsed, dict):
            raise ValueError()
        frame = cast(dict[str, Any], parsed)
        validate_frame(frame)
    except Exception:
        raise ValueError("E_OFFLINE_SCHEMA") from None
    content = {k: v for k, v in frame.items() if k != "mac"}
    expected = hmac.new(
        key, b"BH-OFFLINE-WIRE/v1\0" + rfc8785.dumps(content), hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(frame["mac"], expected):
        raise ValueError("E_OFFLINE_MAC")
    session.accept(frame, incoming=True)
    return frame"""Authenticated loopback-only receiver for synthetic accounting runs."""

import asyncio
import logging
import secrets
from collections.abc import Awaitable, Callable
from contextlib import closing
from http import HTTPStatus
from time import monotonic
from typing import Any

import rfc8785
from websockets.asyncio.server import Server, ServerConnection, serve
from websockets.exceptions import ConnectionClosed
from websockets.http11 import Request, Response
from websockets.protocol import State
from websockets.typing import Origin

from .canonical import parse_strict_json
from .input_journal import InputJournal
from .offline_protocol import SessionState, validate_context, validate_frame, verify_frame
from .store import RunStore, read_journal, validate_journal
from .synthetic_source import validate_synthetic_observation


class OfflineReceiver:
    def __init__(
        self,
        context: dict[str, Any],
        key_provider: Callable[[str], bytes | None],
        store: RunStore,
        journal: InputJournal,
    ):
        validate_context(context)
        if journal.context != context or store.db_path != journal.store.db_path:
            raise ValueError("E_OFFLINE_SOURCE_BINDING")
        self.context = context
        self.key_provider = key_provider
        self.store = store
        self.journal = journal
        self.server: Server | None = None
        self._reserved: set[ServerConnection] = set()
        self._used_sessions: set[str] = set()
        self._lock = asyncio.Lock()
        self._active: ServerConnection | None = None
        self.started = monotonic()
        self.rejections: list[str] = []
        self.before_send: (
            Callable[[ServerConnection, str, dict[str, Any]], Awaitable[bool]] | None
        ) = None

    async def start(self) -> None:
        logger = logging.Logger("offline-wire", level=logging.CRITICAL)
        logger.propagate = False
        logger.addHandler(logging.NullHandler())
        self.server = await serve(
            self._connection,
            "127.0.0.1",
            8765,
            origins=[Origin(self.context["allowed_extension_origin"])],
            compression=None,
            max_size=262144,
            max_queue=8,
            open_timeout=5,
            close_timeout=3,
            process_request=self._request,
            logger=logger,
        )

    async def close(self) -> None:
        if self.server is not None:
            self.server.close()
            await self.server.wait_closed()

    def _request(self, connection: ServerConnection, request: Request) -> Response | None:
        self._reserved = {item for item in self._reserved if item.state is not State.CLOSED}
        if (
            request.path != "/offline"
            or request.headers.get_all("Host") != ["127.0.0.1:8765"]
            or request.headers.get_all("Origin") != [self.context["allowed_extension_origin"]]
        ):
            self.rejections.append("E_OFFLINE_HTTP_BINDING")
            return connection.respond(HTTPStatus.FORBIDDEN, "E_OFFLINE_HTTP_BINDING")
        if len(self._reserved) >= 2:
            self.rejections.append("E_OFFLINE_SOCKET_CAPACITY")
            return connection.respond(HTTPStatus.SERVICE_UNAVAILABLE, "E_OFFLINE_SOCKET_CAPACITY")
        self._reserved.add(connection)
        return None

    async def _connection(self, socket: ServerConnection) -> None:
        try:
            deadline = monotonic() + 5
            hello_data = await asyncio.wait_for(socket.recv(), 5)
            if not isinstance(hello_data, str):
                raise ValueError("E_OFFLINE_FRAME_TYPE")
            hello = parse_strict_json(hello_data.encode())
            if not isinstance(hello, dict):
                raise ValueError("E_OFFLINE_FRAME_TYPE")
            validate_frame(hello)
            sid = hello["session_id"]
            key = self.key_provider(sid)
            if key is None or sid in self._used_sessions:
                raise ValueError("E_OFFLINE_SESSION_REUSE")
            state = SessionState(sid, self.context["run_id"], "BACKEND")
            state.started = deadline - 5
            verify_frame(hello_data.encode(), key, state)
            self._used_sessions.add(sid)
            body = {
                "run_id": self.context["run_id"],
                "client_nonce": state.client_nonce,
                "server_nonce": secrets.token_urlsafe(32),
            }
            await socket.send(state.send("WELCOME", body, key).decode())
            ready = await asyncio.wait_for(socket.recv(), max(0, deadline - monotonic()))
            if not isinstance(ready, str):
                raise ValueError("E_OFFLINE_FRAME_TYPE")
            verify_frame(ready.encode(), key, state)
            await socket.send(state.send("READY_ACK", body, key).decode())
            async with self._lock:
                if self._active is not None and self._active is not socket:
                    await self._active.close(1000, "E_OFFLINE_REPLACED")
                self._active = socket
            while True:
                remaining = 600 - (monotonic() - self.started)
                if remaining <= 0:
                    raise ValueError("E_OFFLINE_RUN_TIMEOUT")
                data = await asyncio.wait_for(socket.recv(), remaining)
                if not isinstance(data, str):
                    raise ValueError("E_OFFLINE_FRAME_TYPE")
                frame = verify_frame(data.encode(), key, state)
                if frame["message_type"] == "STOP":
                    break
                if frame["message_type"] == "PING":
                    await socket.send(state.send("PONG", frame["body"], key).decode())
                    continue
                if frame["message_type"] != "BATCH":
                    raise ValueError("E_OFFLINE_MESSAGE_TYPE")
                async with self._lock:
                    if self._active is not socket:
                        raise ValueError("E_OFFLINE_SESSION_REPLACED")
                    responses = await self.process_batch(frame)
                for message_type, response in responses:
                    if self.before_send and not await self.before_send(
                        socket, message_type, response
                    ):
                        return
                    await socket.send(state.send(message_type, response, key).decode())
                if any(kind == "NACK" for kind, _ in responses):
                    await socket.close(1008, "E_OFFLINE_BATCH_REJECTED")
                    return
        except ConnectionClosed:
            pass
        except Exception:
            # Never log peer text, keys, exception strings, URLs or payload fingerprints.
            self.rejections.append("E_OFFLINE_CONNECTION_REJECTED")
            await socket.close(1008, "E_OFFLINE_CONNECTION_REJECTED")
        finally:
            self._reserved.discard(socket)
            if self._active is socket:
                self._active = None

    async def process_batch(self, frame: dict[str, Any]) -> list[tuple[str, dict[str, Any]]]:
        validate_frame(frame)
        if frame["message_type"] != "BATCH":
            raise ValueError("E_OFFLINE_MESSAGE_TYPE")
        body = frame["body"]
        fields = ("run_id", "browser_run_id", "producer_id", "stream_id", "generation")
        if any(body[name] != self.context[name] for name in fields):
            raise ValueError("E_OFFLINE_IDENTITY")
        with closing(self.store.connect()) as db:
            binding = db.execute(
                "SELECT producer_id FROM stream_generations WHERE run_id=? "
                "AND browser_run_id=? AND stream_id=? AND generation=?",
                (
                    body["run_id"],
                    body["browser_run_id"],
                    body["stream_id"],
                    int(body["generation"]),
                ),
            ).fetchall()
        if len(binding) != 1 or binding[0]["producer_id"] != body["producer_id"]:
            raise ValueError("E_OFFLINE_IDENTITY")
        payloads = [rfc8785.dumps(row) for row in body["observations"]]
        for payload in payloads:
            validate_synthetic_observation(payload, self.context)
        identity = {name: body[name] for name in ("batch_id", *fields)}
        ack = None
        rejection = None
        for payload in payloads:
            outcome = self.journal.apply(payload, body["batch_id"])
            if outcome["status"] != "APPLIED":
                rejection = ("NACK", {**identity, "code": outcome["code"]})
                break
            ack = outcome["ack"]
        responses = []
        if ack is not None:
            sequence = ack["highest_contiguous_sequence"]
            with closing(self.store.connect()) as db:
                confirmed = db.execute(
                    "SELECT MAX(highest_contiguous_sequence) FROM ack_cursors WHERE owner='BACKEND'"
                ).fetchone()[0]
                if confirmed is not None and sequence <= confirmed:
                    validate_journal(read_journal(db, ordered=False))
                    actual = db.execute(
                        "SELECT * FROM ack_outbox WHERE ack_outbox_id=?",
                        (ack["ack_outbox_id"],),
                    ).fetchone()
                    if actual is None or dict(actual) != ack:
                        raise ValueError("E_OFFLINE_ACK_BINDING")
            if confirmed is None or sequence > confirmed:
                self.journal.record_ack_confirmation(
                    body["generation"], str(sequence), ack["cursor_hash"]
                )
            responses.append(
                (
                    "ACK",
                    {
                        **identity,
                        "highest_contiguous_sequence": str(sequence),
                        "cursor_hash": ack["cursor_hash"],
                    },
                )
            )
        if rejection is not None:
            responses.append(rejection)
        return responses


async def serve_offline(
    context: dict[str, Any],
    key_provider: Callable[[str], bytes | None],
    store: RunStore,
    journal: InputJournal,
) -> OfflineReceiver:
    receiver = OfflineReceiver(context, key_provider, store, journal)
    await receiver.start()
    return receiver"""Fresh synthetic run seeds in the real governed SQLite store."""

import hashlib
import os
from contextlib import closing
from pathlib import Path
from time import time_ns
from typing import Any

import rfc8785

from .offline_protocol import validate_context
from .store import RunStore


def create_offline_run(run_dir: Path, context: dict[str, Any]) -> RunStore:
    validate_context(context)
    if any(path.is_symlink() for path in (run_dir, *run_dir.parents)):
        raise ValueError("E_OFFLINE_RUN_PATH")
    run_dir.mkdir(mode=0o700, parents=True, exist_ok=False)
    (run_dir / "raw").mkdir(mode=0o700)
    descriptor = os.open(run_dir / "context.json", os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(descriptor, "wb") as output:
        output.write(rfc8785.dumps(context))
        output.flush()
        os.fsync(output.fileno())
    store = RunStore(run_dir / "run.sqlite3")
    store.bootstrap_v1()
    os.chmod(store.db_path, 0o600)
    identity = hashlib.sha256(
        rfc8785.dumps([context["run_id"], context["stream_id"], context["generation"]])
    ).hexdigest()
    now = time_ns() // 1000
    with closing(store.connect()) as connection, connection:
        connection.execute(
            "INSERT INTO run_meta VALUES (?,1,'OPEN',"
            "'offline-only:synthetic-not-authorization',?,?,?,NULL)",
            (context["run_id"], context["vendor_sha256"], context["code_sha256"], now),
        )
        connection.execute(
            "INSERT INTO stream_generations VALUES (?,?,?,?,?,?,NULL,'ACTIVE',?,NULL,NULL)",
            (
                "generation:" + identity,
                context["run_id"],
                context["browser_run_id"],
                context["producer_id"],
                context["stream_id"],
                int(context["generation"]),
                now,
            ),
        )
        connection.execute(
            "INSERT INTO coherence_epochs VALUES (?,?,'fixture:offline-accounting',"
            "0,NULL,'OPEN',NULL,NULL,?,0)",
            ("epoch:" + identity, context["run_id"], now),
        )
        connection.execute(
            "INSERT INTO coherence_controllers VALUES (?,?,'fixture:offline-accounting',"
            "'OPEN',?,NULL,NULL,NULL,0,?)",
            ("controller:" + identity, context["run_id"], "epoch:" + identity, now),
        )
    directory = os.open(run_dir, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(directory)
    finally:
        os.close(directory)
    return store"""Inert extraction profiles; live admission requires observed source-bound review."""

import copy
import hashlib
import importlib
import re
import unicodedata
from dataclasses import dataclass, field
from datetime import UTC, datetime
from decimal import Decimal
from pathlib import Path
from typing import Any
from urllib.parse import urlsplit

import rfc8785

from .canonical import parse_strict_json
from .live_config import private_path
from .live_contracts import MAX_INTEGER, schema_validate, validate_live_record

CAPTURE_FILES = (
    "extension/src/live/dom_reader.ts",
    "extension/src/live/capture.ts",
    "extension/src/live/background.ts",
    "extension/src/live/panel.ts",
    "extension/src/live/workspace.ts",
    "extension/src/live/contracts.ts",
    "extension/src/live/protocol.ts",
    "extension/src/live/spool.ts",
    "extension/src/live/transport.ts",
    "extension/src/storage/durable_idb.ts",
    "src/moj_discovery/operator_profile.py",
    "contracts/live_readonly/v1/operator-profile.schema.json",
    "contracts/live_readonly/v1/records.schema.json",
    "contracts/live_readonly/v1/wire.schema.json",
)
EXCLUDED = re.compile(
    r"password|passwd|token|cookie|account|balance|betslip|cashout|login|email|username|wallet|form|input|textarea|iframe|contenteditable",
    re.I,
)
IDENTIFIER = r"[A-Za-z_][A-Za-z0-9_-]{0,127}"
TAG = r"(?:div|span|section|article|header|h[1-6]|p|strong|em|label)"
SUFFIX = (
    rf"(?:[.#]{IDENTIFIER}|\[data-(?:testid|role|fixture-id|market-id|selection-id)="
    r"""["'][A-Za-z0-9_-]{1,128}["']\])"""
)
COMPOUND = re.compile(rf"(?:{TAG}(?:{SUFFIX})*|(?:{SUFFIX})+)")
REQUIRED_CAPTURE = frozenset(
    {
        "match_root",
        "fixture_id",
        "home_team",
        "away_team",
        "home_id",
        "away_id",
        "market_root",
        "horizon_label",
        "home_selection",
        "draw_selection",
        "away_selection",
        "home_odds",
        "draw_odds",
        "away_odds",
        "market_status",
    }
)


@dataclass(frozen=True)
class ProfileEvidence:
    root: Path
    now_utc: datetime
    sample_paths: tuple[Path, ...] = ()
    review_path: Path | None = None
    fixture_bindings: tuple[dict[str, Any], ...] = field(default=(), repr=False)


@dataclass(frozen=True)
class ExtractionProfile:
    _data: dict[str, Any] = field(repr=False)
    field_map: dict[str, dict[str, str]]
    observed_markets: dict[str, list[dict[str, Any]]]
    profile_hash: str
    _real_admitted: bool = False
    _review_proof: object = field(default=None, repr=False)

    @property
    def status(self) -> str:
        return str(self._data["status"])

    @property
    def public(self) -> dict[str, Any]:
        return copy.deepcopy(self._data)


def capture_source_hash(root: Path) -> str:
    hashes = {}
    for name in CAPTURE_FILES:
        path = root / name
        if not path.is_file() or path.is_symlink():
            raise ValueError("E_PROFILE_CAPTURE_SOURCE_MISSING")
        hashes[name] = hashlib.sha256(path.read_bytes()).hexdigest()
    return hashlib.sha256(
        b"BH-LIVE-READONLY/CaptureSource/v1\0" + rfc8785.dumps(hashes)
    ).hexdigest()


def validate_selector(value: str) -> None:
    if type(value) is not str or not 1 <= len(value) <= 512 or EXCLUDED.search(value):
        raise ValueError("E_PROFILE_SELECTOR")
    # No escapes, pseudo selectors, wildcard, sibling traversal or selector-list union.
    parts = re.split(r"\s*>\s*|\s+", value)
    if not 1 <= len(parts) <= 8 or any(COMPOUND.fullmatch(p) is None for p in parts):
        raise ValueError("E_PROFILE_SELECTOR")


def parse_decimal_price(text: str, parser: str) -> str:
    if type(text) is not str or parser not in {"DECIMAL_DOT", "DECIMAL_COMMA"}:
        raise ValueError("E_PROFILE_PRICE")
    separator = r"\." if parser == "DECIMAL_DOT" else ","
    if re.fullmatch(rf"[1-9][0-9]{{0,5}}(?:{separator}[0-9]{{1,6}})?", text) is None:
        raise ValueError("E_PROFILE_PRICE")
    normalized = text.replace(",", ".")
    if Decimal(normalized) <= 1:
        raise ValueError("E_PROFILE_PRICE")
    return normalized


def _private_bytes(path: Path, root: Path) -> bytes:
    relative = path.absolute().relative_to(root.absolute())
    checked = private_path(str(relative), root=root, must_exist=True)
    if checked is None or checked.stat().st_size > 65536:
        raise ValueError("E_PROFILE_EVIDENCE_SIZE")
    return checked.read_bytes()


def _observed_labels(value: object) -> None:
    if type(value) is not dict or set(value) != {"horizon", "status", "period", "score_separator"}:
        raise ValueError("E_PROFILE_LABELS")
    if value["score_separator"] not in {None, "EN_DASH", "COLON", "HYPHEN"}:
        raise ValueError("E_PROFILE_LABELS")
    strings = [value["horizon"]]
    for name, permitted in (
        ("status", {"OPEN", "SUSPENDED", "CLOSED", "UNKNOWN"}),
        (
            "period",
            {"PREGAME", "H1", "HALFTIME", "H2", "FINISHED", "BLOCKED", "OUT_OF_SCOPE", "UNKNOWN"},
        ),
    ):
        mapping = value[name]
        if type(mapping) is not dict or not set(mapping) <= permitted:
            raise ValueError("E_PROFILE_LABELS")
        if len(set(mapping.values())) != len(mapping):
            raise ValueError("E_PROFILE_LABELS")
        strings.extend(mapping.values())
    for label in strings:
        if (
            type(label) is not str
            or not 1 <= len(label) <= 256
            or label != unicodedata.normalize("NFC", label)
            or any(ord(c) < 32 or ord(c) == 127 for c in label)
        ):
            raise ValueError("E_PROFILE_LABELS")


def _samples(
    value: dict[str, Any], evidence: ProfileEvidence, field_map: dict[str, dict[str, str]]
) -> dict[str, list[dict[str, Any]]]:
    bindings = {
        b["operator_fixture_id"]: validate_live_record(b, "FixtureBinding")
        for b in evidence.fixture_bindings
    }
    markets: dict[str, list[dict[str, Any]]] = {}
    hashes = []
    for path in evidence.sample_paths:
        raw = _private_bytes(path, evidence.root)
        hashes.append(hashlib.sha256(raw).hexdigest())
        sample = parse_strict_json(raw)
        keys = {
            "schema_version",
            "source_kind",
            "profile_id",
            "origin",
            "path",
            "fixture_id",
            "home_id",
            "away_id",
            "markets",
            "field_map",
        }
        if (
            type(sample) is not dict
            or set(sample) != keys
            or sample["schema_version"] != "operator-profile-sample/v1"
            or any(sample[k] != value[k] for k in ("source_kind", "profile_id", "origin"))
            or sample["path"] not in value["exact_paths"]
            or sample["fixture_id"] not in value["permitted_fixture_ids"]
            or sample["field_map"] != field_map
        ):
            raise ValueError("E_PROFILE_SAMPLE_SCOPE")
        binding = bindings[sample["fixture_id"]]
        if (
            sample["home_id"] != binding["operator_home_id"]
            or sample["away_id"] != binding["operator_away_id"]
            or binding["operator_match_url"] != sample["origin"] + sample["path"]
        ):
            raise ValueError("E_PROFILE_SAMPLE_ORIENTATION")
        if type(sample["markets"]) is not list or not 1 <= len(sample["markets"]) <= 3:
            raise ValueError("E_PROFILE_SAMPLE_MARKET")
        horizons = set()
        for market in sample["markets"]:
            if (
                type(market) is not dict
                or set(market)
                != {"market_id", "horizon", "settlement_basis", "selections", "labels"}
                or market["horizon"] not in value["horizons"]
                or market["horizon"] in horizons
                or market["settlement_basis"] != "NORMAL_TIME_INCLUDING_STOPPAGE"
                or type(market["selections"]) is not dict
                or set(market["selections"]) != {"HOME", "DRAW", "AWAY"}
                or len(set(market["selections"].values())) != 3
            ):
                raise ValueError("E_PROFILE_SAMPLE_MARKET")
            _observed_labels(market["labels"])
            for identifier in (market["market_id"], *market["selections"].values()):
                if (
                    type(identifier) is not str
                    or not 1 <= len(identifier) <= 128
                    or any(ord(c) < 32 or ord(c) == 127 for c in identifier)
                ):
                    raise ValueError("E_PROFILE_SAMPLE_MARKET")
            horizons.add(market["horizon"])
        if sample["fixture_id"] in markets and markets[sample["fixture_id"]] != sample["markets"]:
            raise ValueError("E_PROFILE_SAMPLE_CONFLICT")
        markets[sample["fixture_id"]] = sample["markets"]
    if sorted(hashes) != sorted(value["evidence_hashes"]):
        raise ValueError("E_PROFILE_SAMPLE_HASH")
    return markets


def validate_extraction_profile(value: object, evidence: ProfileEvidence) -> ExtractionProfile:
    try:
        schema_validate(value, "operator-profile")
        if (
            type(value) is not dict
            or not isinstance(evidence, ProfileEvidence)
            or evidence.now_utc.tzinfo is None
            or evidence.now_utc.utcoffset() != UTC.utcoffset(evidence.now_utc)
        ):
            raise ValueError()
        data = copy.deepcopy(value)
        if (
            int(data["profile_version"]) > MAX_INTEGER
            or len(data["permitted_fixture_ids"]) > data["max_matches"]
        ):
            raise ValueError()
        origin = urlsplit(data["origin"])
        if (
            origin.username
            or origin.password
            or origin.query
            or origin.fragment
            or origin.path
            or not origin.hostname
        ):
            raise ValueError()
        if data["source_kind"] == "SYNTHETIC_TEST":
            if data["status"] != "DRAFT" or not (
                data["origin"] == "https://example.invalid"
                or (origin.scheme == "http" and origin.hostname == "127.0.0.1")
            ):
                raise ValueError()
        elif origin.scheme != "https" or origin.port not in {None, 443}:
            raise ValueError()
        for path in data["exact_paths"]:
            if (
                path.startswith("//")
                or "%" in path
                or "\\" in path
                or any(p in {".", ".."} for p in path.split("/"))
                or len(path) > 2048
            ):
                raise ValueError()
        selectors = data["selectors"]
        for selector in selectors.values():
            if selector is not None:
                validate_selector(selector)
        root_selector = selectors["match_root"]
        if root_selector is not None and "#" not in root_selector and "[data-" not in root_selector:
            raise ValueError()
        for fields in (
            ("home_team", "away_team"),
            ("home_id", "away_id"),
            ("home_selection", "draw_selection", "away_selection"),
            ("home_odds", "draw_odds", "away_odds"),
        ):
            present = [selectors[k] for k in fields if selectors[k] is not None]
            if len(set(present)) != len(present):
                raise ValueError()
        field_map = {
            name: {
                "selector": selector,
                "reader": "ROOT_NODE"
                if name == "match_root"
                else "DATA_MARKET_ID"
                if name == "market_root"
                else "TEXT_CONTENT",
            }
            for name, selector in selectors.items()
            if selector is not None
        }
        markets = _samples(data, evidence, field_map)
        admitted = False
        review_proof = None
        if data["status"] == "ACCEPTED":
            expires = datetime.fromisoformat(data["expires_at"])
            if (
                expires.tzinfo is None
                or not evidence.now_utc < expires
                or not field_map.keys() >= REQUIRED_CAPTURE
                or set(markets) != set(data["permitted_fixture_ids"])
                or evidence.review_path is None
                or int(data["profile_version"]) < 1
            ):
                raise ValueError()
            current = capture_source_hash(evidence.root)
            if data["capture_source_hash"] != current or data["reviewed_source_hash"] != current:
                raise ValueError()
            review = parse_strict_json(_private_bytes(evidence.review_path, evidence.root))
            # PB-16 verifies the external review authority. Its absence keeps the profile inert.
            review_proof = importlib.import_module(
                "moj_discovery.live_preflight_batched"
            ).verify_profile_review(data, review, evidence)
            admitted = True
        return ExtractionProfile(
            data,
            field_map,
            markets,
            hashlib.sha256(rfc8785.dumps(data)).hexdigest(),
            admitted,
            review_proof,
        )
    except Exception:
        raise ValueError("E_PROFILE_REJECTED") from None


def activate_profile(profile: ExtractionProfile, target: str) -> dict[str, Any]:
    value = profile.public
    if (
        target == "SYNTHETIC_TEST"
        and value["source_kind"] == "SYNTHETIC_TEST"
        and profile.status == "DRAFT"
    ):
        if not profile.field_map.keys() >= REQUIRED_CAPTURE:
            raise ValueError("E_PROFILE_UNCONFIGURED")
        return value
    if (
        target != "OPERATOR"
        or value["source_kind"] != "OBSERVED_REAL"
        or profile.status != "ACCEPTED"
        or not profile._real_admitted
    ):
        raise ValueError("E_PROFILE_INACTIVE")
    return valueimport argparse
