COMMAND_RESULT_DOMAIN = b"HYBRID-DISCOVERY/v6.2/Repo0CommandResultSet/v1\0"
RECEIPT_DOMAIN = b"HYBRID-DISCOVERY/v6.2/Repo0BaselineReceipt/v1\0"
