def _git_environment(root: Path) -> dict[str, str]:
    return {
        "GIT_CONFIG_NOSYSTEM": "1",
        "GIT_TERMINAL_PROMPT": "0",
        "HOME": str(root),
        "LANG": "C.UTF-8",
        "LC_ALL": "C.UTF-8",
        "PATH": "/usr/bin:/bin",
    }


def _git_output(root: Path, *arguments: str) -> bytes:
    result = subprocess.run(  # noqa: S603 - fixed absolute Git executable
        ["/usr/bin/git", "-C", str(root), *arguments],
        capture_output=True,
        env=_git_environment(root),
    )
    if result.returncode != 0:
        raise ValueError("E_REPO0_GIT_STATE")
    return result.stdout


def _head_file_tree(root: Path) -> dict[str, object]:
    raw = _git_output(root, "ls-tree", "-r", "-z", "--full-tree", "HEAD")
    entries: list[dict[str, object]] = []
    for item in raw.split(b"\0"):
        if not item:
            continue
        try:
            metadata, raw_path = item.split(b"\t", 1)
            mode, object_type, object_id = metadata.split(b" ", 2)
            path = raw_path.decode("utf-8")
        except (UnicodeDecodeError, ValueError) as error:
            raise ValueError("E_REPO0_FILE_TREE_ENTRY") from error
        if object_type != b"blob" or mode not in {b"100644", b"100755"}:
            raise ValueError("E_REPO0_FILE_TREE_ENTRY")
        if not _valid_repo_path(path) or path == ".gitmodules":
            raise ValueError("E_REPO0_FILE_TREE_ENTRY")
        content = _git_output(root, "cat-file", "blob", object_id.decode("ascii"))
        entries.append(
            {
                "entry_kind": "REGULAR_FILE",
                "file_sha256": hashlib.sha256(content).hexdigest(),
                "git_mode": mode.decode("ascii"),
                "gitlink": False,
                "hardlink": False,
                "path": path,
                "size_bytes": str(len(content)),
                "symlink": False,
            }
        )
    entries.sort(key=lambda entry: cast(str, entry["path"]).encode())
    tree: dict[str, object] = {
        "entries": entries,
        "schema_version": "repo0-independent-file-tree/v1",
    }
    _validate_independent_file_tree(tree)
    return tree


def compute_vendor_tree_root(vendor: Path) -> str:
    root = vendor.absolute()
    root_stat = root.lstat()
    if stat.S_ISLNK(root_stat.st_mode) or not stat.S_ISDIR(root_stat.st_mode):
        raise ValueError("E_REPO0_VENDOR_TREE")
    files: list[tuple[str, int, str]] = []

    def visit(directory: Path) -> None:
        for entry in sorted(os.scandir(directory), key=lambda value: os.fsencode(value.name)):
            path = Path(entry.path)
            relative = path.relative_to(root).as_posix()
            if not _valid_repo_path(relative):
                raise ValueError("E_REPO0_VENDOR_TREE")
            entry_stat = entry.stat(follow_symlinks=False)
            if stat.S_ISLNK(entry_stat.st_mode):
                raise ValueError("E_REPO0_VENDOR_TREE")
            if stat.S_ISDIR(entry_stat.st_mode):
                visit(path)
                continue
            if not stat.S_ISREG(entry_stat.st_mode) or entry_stat.st_nlink != 1:
                raise ValueError("E_REPO0_VENDOR_TREE")
            if relative == "SCHEMA_SHA256.json":
                continue
            content = path.read_bytes()
            if len(content) != entry_stat.st_size:
                raise ValueError("E_REPO0_VENDOR_TREE")
            files.append((relative, len(content), hashlib.sha256(content).hexdigest()))

    visit(root)
    framed = b"".join(
        path.encode() + b"\0" + str(size).encode() + b"\0" + digest.encode() + b"\n"
        for path, size, digest in sorted(files, key=lambda value: value[0].encode())
    )
    return hashlib.sha256(framed).hexdigest()


def _read_jcs_record(path: Path, error: str) -> tuple[dict[str, object], bytes]:
    try:
        raw = path.read_bytes()
        parsed = parse_strict_json(raw)
    except (OSError, ValueError) as cause:
        raise ValueError(error) from cause
    if not isinstance(parsed, dict) or raw != rfc8785.dumps(cast(Any, parsed)) + b"\n":
        raise ValueError(error)
    return cast(dict[str, object], parsed), raw


def _verify_command_result_set(
    root: Path,
    result_set: dict[str, object],
    result_bytes: bytes,
) -> tuple[dict[str, object], str]:
    from tools.run_command_registry import (
        EXPECTED_EXECUTION_ENVIRONMENT,
        expand_invocations,
        validate_registry,
    )

    registry_path = root / "task-command-registry.json"
    registry = cast(dict[str, Any], validate_registry(registry_path))
    contract = cast(dict[str, Any], registry["baseline_result_contract"])
    required = {
        "additional_argv_invocation_count",
        "algorithm_id",
        "candidate_exclusion_policy_id",
        "completion_state",
        "domain",
        "execution_environment",
        "expanded_invocation_count",
        "inherit_parent_environment",
        "production_authority",
        "qualified_file_tree",
        "qualified_file_tree_root_sha256",
        "record_type",
        "registry_path",
        "registry_sha256",
        "results",
        "root_eligible",
        "schema_version",
        "task_invocation_count",
        "verification_invocation_count",
        "working_directory",
    }
    if set(result_set) != required:
        raise ValueError("E_REPO0_COMMAND_ROOT_INELIGIBLE")
    if (
        result_set["record_type"] != "Repo0CommandResultSet"
        or result_set["schema_version"] != "repo0-command-result-set/v1"
        or result_set["algorithm_id"] != "HD-REPO0-COMMAND-RESULTS-SHA256-v1"
        or result_set["domain"] != COMMAND_RESULT_DOMAIN.decode()
        or result_set["completion_state"] != "COMPLETE_ACCEPTED"
        or result_set["root_eligible"] is not True
        or result_set["production_authority"] != "NONE"
        or result_set["inherit_parent_environment"] is not False
        or result_set["execution_environment"] != EXPECTED_EXECUTION_ENVIRONMENT
        or result_set["working_directory"] != contract["working_directory"]
        or result_set["registry_path"] != "task-command-registry.json"
        or result_set["registry_sha256"]
        != hashlib.sha256(registry_path.read_bytes()).hexdigest()
        or result_set["candidate_exclusion_policy_id"] != "REPO0-CANDIDATE-EXCLUSIONS-v1"
        or result_set["verification_invocation_count"] != "41"
        or result_set["task_invocation_count"] != "60"
        or result_set["additional_argv_invocation_count"] != "9"
        or result_set["expanded_invocation_count"] != "101"
    ):
        raise ValueError("E_REPO0_COMMAND_CONTEXT")
    qualified_tree = _validate_independent_file_tree(result_set["qualified_file_tree"])
    qualified_root = compute_independent_file_tree_root(qualified_tree)
    if result_set["qualified_file_tree_root_sha256"] != qualified_root:
        raise ValueError("E_REPO0_QUALIFIED_TREE")
    results = result_set["results"]
    expanded = expand_invocations(registry, "baseline")
    if not isinstance(results, list) or len(results) != 101 or len(expanded) != 101:
        raise ValueError("E_REPO0_COMMAND_EXPANSION")
    for expected, actual in zip(expanded, results, strict=True):
        if not isinstance(actual, dict):
            raise ValueError("E_REPO0_COMMAND_EXPANSION")
        expected_keys = {
            "argv",
            "argv_ordinal",
            "contract_error_tokens",
            "disposition",
            "execution_state",
            "expectation",
            "expectation_matched",
            "exit_code",
            "invocation_id",
            "invocation_index",
            "owner_id",
            "owner_kind",
            "stderr_sha256",
            "stderr_size_bytes",
            "stdout_sha256",
            "stdout_size_bytes",
            "working_directory",
        }
        if set(actual) != expected_keys or any(
            not _json_equal_exact(actual.get(key), expected[key])
            for key in (
                "argv",
                "argv_ordinal",
                "expectation",
                "invocation_id",
                "invocation_index",
                "owner_id",
                "owner_kind",
            )
        ):
            raise ValueError("E_REPO0_COMMAND_EXPANSION")
        expectation = cast(dict[str, object], expected["expectation"])
        intentional = expectation["kind"] == "INTENTIONAL_RED"
        expected_tokens = [expectation["expected_contract_error"]] if intentional else []
        if (
            actual["execution_state"] != "COMPLETED"
            or actual["expectation_matched"] is not True
            or isinstance(actual["exit_code"], bool)
            or not isinstance(actual["exit_code"], int)
            or actual["exit_code"] != expectation["expected_exit_code"]
            or actual["working_directory"] != contract["working_directory"]
            or actual["contract_error_tokens"] != expected_tokens
            or actual["disposition"]
            != ("EXPECTED_CONTRACT_RED" if intentional else "PASS")
            or any(
                not isinstance(actual[field], str) or _SHA256.fullmatch(actual[field]) is None
                for field in ("stdout_sha256", "stderr_sha256")
            )
            or any(
                not isinstance(actual[field], str)
                or _UNSIGNED_INTEGER.fullmatch(actual[field]) is None
                for field in ("stdout_size_bytes", "stderr_size_bytes")
            )
        ):
            raise ValueError(
                "E_REPO0_CONTRACT_RED" if intentional else "E_REPO0_COMMAND_ROOT_INELIGIBLE"
            )
    if result_bytes != rfc8785.dumps(cast(Any, result_set)) + b"\n":
        raise ValueError("E_REPO0_COMMAND_ROOT_INELIGIBLE")
    return qualified_tree, compute_command_result_root(result_set)


def _repository_state(root: Path) -> dict[str, object]:
    top_level = _git_output(root, "rev-parse", "--show-toplevel").decode().rstrip("\n")
    if top_level != str(root):
        raise ValueError("E_REPO0_AMBIENT_GIT")
    if _git_output(root, "rev-parse", "--show-object-format").strip() != b"sha1":
        raise ValueError("E_REPO0_GIT_STATE")
    commit = _git_output(root, "rev-parse", "HEAD").decode().strip()
    tree_oid = _git_output(root, "rev-parse", "HEAD^{tree}").decode().strip()
    parents = _git_output(root, "rev-list", "--parents", "-n", "1", "HEAD").split()
    commit_count = int(_git_output(root, "rev-list", "--count", "HEAD").strip())
    remote_count = len(_git_output(root, "remote").splitlines())
    dirty = bool(_git_output(root, "status", "--porcelain=v1", "--untracked-files=all"))
    return {
        "commit": commit,
        "tree_oid": tree_oid,
        "parents": len(parents) - 1,
        "commit_count": commit_count,
        "remote_count": remote_count,
        "dirty": dirty,
        "head_tree": _head_file_tree(root),
    }


def _verify_repository_and_result(
    root: Path,
    command_result_path: Path,
    command_result: dict[str, object] | None,
) -> tuple[dict[str, object], bytes, dict[str, object], str, dict[str, object]]:
    if command_result_path.absolute().is_relative_to(root):
        raise ValueError("E_REPO0_RECEIPT_CYCLE")
    if command_result is None:
        result_set, result_bytes = _read_jcs_record(
            command_result_path, "E_REPO0_COMMAND_ROOT_INELIGIBLE"
        )
    else:
        result_set = command_result
        result_bytes = rfc8785.dumps(cast(Any, result_set)) + b"\n"
    qualified_tree, command_root = _verify_command_result_set(root, result_set, result_bytes)
    state = _repository_state(root)
    head_tree = cast(dict[str, object], state["head_tree"])
    if qualified_tree != head_tree:
        raise ValueError("E_REPO0_QUALIFIED_TREE")
    if (
        compute_independent_file_tree_root(head_tree)
        != result_set["qualified_file_tree_root_sha256"]
    ):
        raise ValueError("E_REPO0_QUALIFIED_TREE")
    from tools.run_command_registry import (
        collect_candidate_file_tree,
    )

    working_tree = collect_candidate_file_tree(root, allow_local_git=True)
    if working_tree != head_tree:
        raise ValueError("E_REPO0_QUALIFIED_TREE")
    if (
        state["commit_count"] != 1
        or state["parents"] != 0
        or state["remote_count"] != 0
        or state["dirty"] is not False
    ):
        raise ValueError("E_REPO0_GIT_STATE")
    return result_set, result_bytes, qualified_tree, command_root, state


def _receipt_content_hash(receipt: dict[str, object]) -> str:
    projected = dict(receipt)
    if "content_hash" not in projected:
        raise ValueError("E_REPO0_RECEIPT")
    del projected["content_hash"]
    return hashlib.sha256(RECEIPT_DOMAIN + rfc8785.dumps(cast(Any, projected))).hexdigest()


def _verify_receipt(
    root: Path,
    receipt: dict[str, object],
    receipt_bytes: bytes,
    result_bytes: bytes,
    qualified_tree: dict[str, object],
    command_root: str,
    state: dict[str, object],
) -> None:
    from tools.verify_toolchains import verify_toolchains

    required = {
        "record_type",
        "schema_version",
        "receipt_id",
        "receipt_id_allocation",
        "receipt_path",
        "git_object_format",
        "actual_git_commit_oid",
        "actual_git_tree_oid",
        "independent_file_tree_algorithm",
        "independent_file_tree_entry_count",
        "independent_file_tree_root_sha256",
        "toolchain_versions",
        "lockfile_hash_algorithm",
        "lockfile_hashes",
        "vendor_root_algorithm",
        "vendor_root_sha256",
        "command_result_algorithm",
        "command_result_manifest_path",
        "command_result_manifest_committed_in_baseline",
        "command_result_manifest_file_sha256",
        "command_registry_file_sha256",
        "command_result_invocation_count",
        "command_result_root_sha256",
        "baseline_commit_count",
        "parent_commit_count",
        "worktree_clean",
        "no_remote",
        "remote_count",
        "zero_parent_commit",
        "receipt_committed_in_baseline",
        "verified_at",
        "content_hash",
        "production_authority",
    }
    try:
        receipt_uuid = uuid.UUID(cast(str, receipt.get("receipt_id")))
    except (ValueError, AttributeError) as error:
        raise ValueError("E_REPO0_RECEIPT") from error
    timestamp = receipt.get("verified_at")
    valid_timestamp = False
    if isinstance(timestamp, str):
        try:
            parsed_timestamp = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
            valid_timestamp = (
                parsed_timestamp.utcoffset() == UTC.utcoffset(parsed_timestamp)
                and parsed_timestamp.microsecond == 0
                and parsed_timestamp.isoformat().replace("+00:00", "Z") == timestamp
            )
        except ValueError:
            pass
    expected_toolchains = [
        {"toolchain": "Node", "version": "22.23.0"},
        {"toolchain": "pnpm", "version": "10.33.2"},
        {"toolchain": "Python", "version": "3.12.3"},
        {"toolchain": "uv", "version": "0.11.7"},
    ]
    lock_hashes = [
        {
            "path": "pnpm-lock.yaml",
            "sha256": hashlib.sha256((root / "pnpm-lock.yaml").read_bytes()).hexdigest(),
        },
        {
            "path": "uv.lock",
            "sha256": hashlib.sha256((root / "uv.lock").read_bytes()).hexdigest(),
        },
    ]
    entries = cast(list[object], qualified_tree["entries"])
    if (
        set(receipt) != required
        or receipt["record_type"] != "Repo0BaselineReceipt"
        or receipt["schema_version"] != "repo0-baseline-receipt/v1"
        or receipt_uuid.version != 4
        or str(receipt_uuid) != receipt["receipt_id"]
        or receipt["receipt_id_allocation"] != "UUID_V4_INDEPENDENT_OF_CONTENT_HASH"
        or receipt["receipt_path"] != "docs/receipts/repo0-baseline-receipt.json"
        or receipt["git_object_format"] != "sha1"
        or receipt["actual_git_commit_oid"] != state["commit"]
        or receipt["actual_git_tree_oid"] != state["tree_oid"]
        or receipt["independent_file_tree_algorithm"] != "HD-REPO0-FILE-TREE-SHA256-v1"
        or receipt["independent_file_tree_entry_count"] != str(len(entries))
        or receipt["independent_file_tree_root_sha256"]
        != compute_independent_file_tree_root(qualified_tree)
        or receipt["toolchain_versions"] != expected_toolchains
        or verify_toolchains()
        or receipt["lockfile_hash_algorithm"] != "SHA-256-RAW-BYTES"
        or receipt["lockfile_hashes"] != lock_hashes
        or receipt["vendor_root_algorithm"] != "HD-VENDOR-TREE-SHA256-v1"
        or receipt["vendor_root_sha256"]
        != compute_vendor_tree_root(root / "vendor/hybrid-discovery-v6.3.6")
        or receipt["command_result_algorithm"] != "HD-REPO0-COMMAND-RESULTS-SHA256-v1"
        or receipt["command_result_manifest_path"] != "docs/receipts/repo0-command-results.json"
        or receipt["command_result_manifest_committed_in_baseline"] is not False
        or receipt["command_result_manifest_file_sha256"]
        != hashlib.sha256(result_bytes).hexdigest()
        or receipt["command_registry_file_sha256"]
        != hashlib.sha256((root / "task-command-registry.json").read_bytes()).hexdigest()
        or receipt["command_result_invocation_count"] != "101"
        or receipt["command_result_root_sha256"] != command_root
        or isinstance(receipt["baseline_commit_count"], bool)
        or not isinstance(receipt["baseline_commit_count"], int)
        or receipt["baseline_commit_count"] != 1
        or isinstance(receipt["parent_commit_count"], bool)
        or not isinstance(receipt["parent_commit_count"], int)
        or receipt["parent_commit_count"] != 0
        or receipt["worktree_clean"] is not True
        or receipt["no_remote"] is not True
        or isinstance(receipt["remote_count"], bool)
        or not isinstance(receipt["remote_count"], int)
        or receipt["remote_count"] != 0
        or receipt["zero_parent_commit"] is not True
        or receipt["receipt_committed_in_baseline"] is not False
        or not valid_timestamp
        or receipt["production_authority"] != "NONE"
        or receipt["content_hash"] != _receipt_content_hash(receipt)
        or receipt_bytes != rfc8785.dumps(cast(Any, receipt)) + b"\n"
    ):
        raise ValueError("E_REPO0_RECEIPT")


def _verify_inherited_repository_baseline(
    root: Path,
    receipt: dict[str, object] | None = None,
    *,
    receipt_path: Path = BASELINE_RECEIPT_PATH,
    command_result: dict[str, object] | None = None,
    command_result_path: Path = COMMAND_RESULT_PATH,
) -> list[str]:
    root = root.absolute()
    try:
        root_stat = root.lstat()
    except OSError:
        return ["E_BASELINE:NO_GIT"]
    if stat.S_ISLNK(root_stat.st_mode) or not stat.S_ISDIR(root_stat.st_mode):
        return ["E_REPO0_AMBIENT_GIT"]
    local_git = root / ".git"
    try:
        git_stat = local_git.lstat()
    except OSError:
        ambient = subprocess.run(  # noqa: S603 - fixed absolute Git executable
            ["/usr/bin/git", "-C", str(root), "rev-parse", "--show-toplevel"],
            capture_output=True,
            env=_git_environment(root),
        )
        return ["E_REPO0_AMBIENT_GIT" if ambient.returncode == 0 else "E_BASELINE:NO_GIT"]
    if stat.S_ISLNK(git_stat.st_mode) or not stat.S_ISDIR(git_stat.st_mode):
        return ["E_REPO0_AMBIENT_GIT"]
    result_present = command_result is not None or command_result_path.exists()
    receipt_present = receipt is not None or receipt_path.exists()
    if not result_present or (receipt_present and not result_present):
        return ["E_REPO0_PRESENCE_STATE"]
    try:
        result_set, result_bytes, qualified_tree, command_root, state = (
            _verify_repository_and_result(root, command_result_path, command_result)
        )
        del result_set
        if not receipt_present:
            return []
        if receipt_path.absolute().is_relative_to(root):
            raise ValueError("E_REPO0_RECEIPT_CYCLE")
        if receipt is None:
            receipt_record, receipt_bytes = _read_jcs_record(receipt_path, "E_REPO0_RECEIPT")
        else:
            receipt_record = receipt
            receipt_bytes = rfc8785.dumps(cast(Any, receipt)) + b"\n"
        _verify_receipt(
            root,
            receipt_record,
            receipt_bytes,
            result_bytes,
            qualified_tree,
            command_root,
            state,
        )
    except (OSError, UnicodeError, ValueError) as error:
        return [str(error)]
    return []


def _build_repo0_baseline_receipt(
    root: Path,
    accepted_result_set: Path,
) -> dict[str, object]:
    receipt_path = accepted_result_set.with_name("repo0-baseline-receipt.json")
    if receipt_path.exists() or receipt_path.is_symlink():
        raise ValueError("E_REPO0_RECEIPT_EXISTS")
    errors = _verify_inherited_repository_baseline(
        root,
        receipt_path=receipt_path,
        command_result_path=accepted_result_set,
    )
    if errors:
        raise ValueError(errors[0])
    result_set, result_bytes = _read_jcs_record(
        accepted_result_set, "E_REPO0_COMMAND_ROOT_INELIGIBLE"
    )
    qualified_tree, command_root = _verify_command_result_set(root, result_set, result_bytes)
    state = _repository_state(root)
    entries = cast(list[object], qualified_tree["entries"])
    receipt: dict[str, object] = {
        "record_type": "Repo0BaselineReceipt",
        "schema_version": "repo0-baseline-receipt/v1",
        "receipt_id": str(uuid.uuid4()),
        "receipt_id_allocation": "UUID_V4_INDEPENDENT_OF_CONTENT_HASH",
        "receipt_path": "docs/receipts/repo0-baseline-receipt.json",
        "git_object_format": "sha1",
        "actual_git_commit_oid": state["commit"],
        "actual_git_tree_oid": state["tree_oid"],
        "independent_file_tree_algorithm": "HD-REPO0-FILE-TREE-SHA256-v1",
        "independent_file_tree_entry_count": str(len(entries)),
        "independent_file_tree_root_sha256": compute_independent_file_tree_root(qualified_tree),
        "toolchain_versions": [
            {"toolchain": "Node", "version": "22.23.0"},
            {"toolchain": "pnpm", "version": "10.33.2"},
            {"toolchain": "Python", "version": "3.12.3"},
            {"toolchain": "uv", "version": "0.11.7"},
        ],
        "lockfile_hash_algorithm": "SHA-256-RAW-BYTES",
        "lockfile_hashes": [
            {
                "path": "pnpm-lock.yaml",
                "sha256": hashlib.sha256((root / "pnpm-lock.yaml").read_bytes()).hexdigest(),
            },
            {
                "path": "uv.lock",
                "sha256": hashlib.sha256((root / "uv.lock").read_bytes()).hexdigest(),
            },
        ],
        "vendor_root_algorithm": "HD-VENDOR-TREE-SHA256-v1",
        "vendor_root_sha256": compute_vendor_tree_root(
            root / "vendor/hybrid-discovery-v6.3.6"
        ),
        "command_result_algorithm": "HD-REPO0-COMMAND-RESULTS-SHA256-v1",
        "command_result_manifest_path": "docs/receipts/repo0-command-results.json",
        "command_result_manifest_committed_in_baseline": False,
        "command_result_manifest_file_sha256": hashlib.sha256(result_bytes).hexdigest(),
        "command_registry_file_sha256": hashlib.sha256(
            (root / "task-command-registry.json").read_bytes()
        ).hexdigest(),
        "command_result_invocation_count": "101",
        "command_result_root_sha256": command_root,
        "baseline_commit_count": 1,
        "parent_commit_count": 0,
        "worktree_clean": True,
        "no_remote": True,
        "remote_count": 0,
        "zero_parent_commit": True,
        "receipt_committed_in_baseline": False,
        "verified_at": datetime.now(UTC)
        .replace(microsecond=0)
        .isoformat()
        .replace("+00:00", "Z"),
        "content_hash": "",
        "production_authority": "NONE",
    }
    receipt["content_hash"] = _receipt_content_hash(receipt)
    return receipt


def build_repo0_baseline_receipt(
    root: Path,
    accepted_result_set: Path,
) -> dict[str, object]:
    if root.absolute() != RUNTIME_ROOT or accepted_result_set.absolute() != COMMAND_RESULT_PATH:
        raise ValueError("E_REPO0_RECEIPT_PATH")
    return _build_repo0_baseline_receipt(root.absolute(), accepted_result_set.absolute())


def _write_repo0_baseline_receipt(path: Path, receipt: dict[str, object]) -> None:
    if path.exists() or path.is_symlink():
        raise ValueError("E_REPO0_RECEIPT_EXISTS")
    content = rfc8785.dumps(cast(Any, receipt)) + b"\n"
    descriptor, temporary_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    temporary = Path(temporary_name)
    replaced = False
    try:
        os.fchmod(descriptor, 0o644)
        with os.fdopen(descriptor, "wb") as output:
            output.write(content)
            output.flush()
            os.fsync(output.fileno())
        temporary_stat = temporary.lstat()
        if not stat.S_ISREG(temporary_stat.st_mode) or temporary_stat.st_nlink != 1:
            raise ValueError("E_REPO0_RECEIPT_WRITE")
        os.replace(temporary, path)
        replaced = True
        directory_fd = os.open(path.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
        if path.read_bytes() != content:
            raise ValueError("E_REPO0_RECEIPT_WRITE")
    except Exception:
        if replaced:
            path.unlink(missing_ok=True)
        raise
    finally:
        temporary.unlink(missing_ok=True)


def write_repo0_baseline_receipt(path: Path, receipt: dict[str, object]) -> None:
    if path.absolute() != BASELINE_RECEIPT_PATH:
        raise ValueError("E_REPO0_RECEIPT_PATH")
    _write_repo0_baseline_receipt(path.absolute(), receipt)


def verify_repository_baseline(
    root: Path,
    receipt: dict[str, object] | None = None,
    *,
    receipt_path: Path = BASELINE_RECEIPT_PATH,
    command_result: dict[str, object] | None = None,
    command_result_path: Path = COMMAND_RESULT_PATH,
) -> list[str]:
    """Verify only the current v6.3.6 external receipt contract.

    The historical command-result API above remains for immutable archive fixtures;
    it cannot grant qualification to a successor runtime.
    """
    del command_result_path
    root = root.absolute()
    try:
        root_stat = root.lstat()
    except OSError:
        return ["E_BASELINE:NO_GIT"]
    if stat.S_ISLNK(root_stat.st_mode) or not stat.S_ISDIR(root_stat.st_mode):
        return ["E_REPO0_AMBIENT_GIT"]
    local_git = root / ".git"
    if not local_git.is_dir() or local_git.is_symlink():
        ambient = subprocess.run(  # noqa: S603 - fixed absolute Git executable
            ["/usr/bin/git", "-C", str(root), "rev-parse", "--show-toplevel"],
            capture_output=True,
            env=_git_environment(root),
        )
        return ["E_REPO0_AMBIENT_GIT" if ambient.returncode == 0 else "E_BASELINE:NO_GIT"]
    if command_result is not None or receipt is not None:
        return ["E_REPO0_LEGACY_RESULT"]
    if not receipt_path.exists() or receipt_path.is_symlink():
        return ["E_REPO0_PRESENCE_STATE"]
    if receipt_path.absolute().is_relative_to(root):
        return ["E_REPO0_RECEIPT_CYCLE"]
    try:
        from tools.qualify_zero_parent_baseline import verify_zero_parent_baseline

        verify_zero_parent_baseline(root, receipt_path.absolute())
    except (OSError, ValueError) as error:
        return [str(error)]
    return []


PACK_DIRECTORY_NAME = "hybrid-discovery-v6.2"
ARCHIVE_BASENAME = f"{PACK_DIRECTORY_NAME}.zip"
MANIFEST_PATH = "MANIFEST_SHA256.json"
SIDECAR_SUFFIX = ".sha256"
ZIP_TIMESTAMP = (1980, 1, 1, 0, 0, 0)
ZIP_EXTERNAL_ATTR = (stat.S_IFREG | 0o644) << 16
MAX_MANIFEST_SIZE_BYTES = 9_007_199_254_740_991
_SHA256 = re.compile(r"[0-9a-f]{64}")
_UNSIGNED_INTEGER = re.compile(r"(?:0|[1-9][0-9]{0,39})")
_PORTABLE_PATH = re.compile(r"[A-Za-z0-9._/-]+")


def _source_files(pack: Path) -> dict[str, bytes]:
    try:
        root_stat = pack.lstat()
    except OSError as error:
        raise ValueError("E_PACK:SOURCE_TYPE") from error
    if pack.name != PACK_DIRECTORY_NAME or not stat.S_ISDIR(root_stat.st_mode):
        raise ValueError("E_PACK:SOURCE_TYPE")

    files: dict[str, bytes] = {}

    def visit(directory: Path, prefix: PurePosixPath | None = None) -> None:
        try:
            entries = list(os.scandir(directory))
        except OSError as error:
            raise ValueError("E_PACK:SOURCE_TYPE") from error
        for entry in sorted(entries, key=lambda value: os.fsencode(value.name)):
            relative_text = (
                entry.name if prefix is None else f"{prefix.as_posix()}/{entry.name}"
            )
            relative = _safe_relative_path(relative_text)
            try:
                entry_stat = entry.stat(follow_symlinks=False)
            except OSError as error:
                raise ValueError("E_PACK:SOURCE_TYPE") from error
            if stat.S_ISLNK(entry_stat.st_mode):
                raise ValueError("E_PACK:SOURCE_TYPE")
            if stat.S_ISDIR(entry_stat.st_mode):
                visit(Path(entry.path), relative)
                continue
            if not stat.S_ISREG(entry_stat.st_mode):
                raise ValueError("E_PACK:SOURCE_TYPE")
            if entry_stat.st_nlink != 1:
                raise ValueError("E_PACK:SOURCE_HARDLINK")
            try:
                content = Path(entry.path).read_bytes()
            except OSError as error:
                raise ValueError("E_PACK:SOURCE_TYPE") from error
            if len(content) != entry_stat.st_size:
                raise ValueError("E_PACK:SOURCE_CHANGED")
            files[relative.as_posix()] = content

    visit(pack)
    return files


def _verify_pack(pack: Path) -> dict[str, bytes]:
    source_files = _source_files(pack)
    manifest_bytes = source_files.get(MANIFEST_PATH)
    if manifest_bytes is None:
        raise ValueError("E_PACK:MANIFEST")
    try:
        manifest = parse_strict_json(manifest_bytes)
    except ValueError as error:
        raise ValueError("E_PACK:MANIFEST") from error
    required = {
        "schema_version",
        "pack_version",
        "pack_hash",
        "implementation_baseline_hash",
        "files",
        "self_excluded_path",
        "production_authority",
    }
    if not isinstance(manifest, dict) or set(manifest) != required:
        raise ValueError("E_PACK:MANIFEST")
    if (
        manifest["schema_version"] != "pack-manifest/v1"
        or manifest["pack_version"] != "6.2"
        or manifest["self_excluded_path"] != MANIFEST_PATH
        or manifest["production_authority"] != "NONE"
        or not isinstance(manifest["pack_hash"], str)
        or _SHA256.fullmatch(manifest["pack_hash"]) is None
        or not isinstance(manifest["implementation_baseline_hash"], str)
        or _SHA256.fullmatch(manifest["implementation_baseline_hash"]) is None
        or not isinstance(manifest["files"], list)
        or not manifest["files"]
        or len(manifest["files"]) > 4096
    ):
        raise ValueError("E_PACK:MANIFEST")
    declared: dict[str, tuple[int, str]] = {}
    declared_order: list[str] = []
    for item in manifest["files"]:
        if not isinstance(item, dict) or set(item) != {"path", "size_bytes", "sha256"}:
            raise ValueError("E_PACK:MANIFEST")
        path_value = item["path"]
        size = item["size_bytes"]
        digest = item["sha256"]
        if (
            not isinstance(path_value, str)
            or isinstance(size, bool)
            or not isinstance(size, int)
            or size < 0
            or size > MAX_MANIFEST_SIZE_BYTES
            or not isinstance(digest, str)
            or _SHA256.fullmatch(digest) is None
        ):
            raise ValueError("E_PACK:MANIFEST")
        relative = _safe_relative_path(path_value).as_posix()
        if relative == MANIFEST_PATH:
            raise ValueError("E_PACK:MANIFEST_SELF_REFERENCE")
        if relative in declared:
            raise ValueError("E_PACK:MANIFEST_DUPLICATE")
        declared[relative] = (size, digest)
        declared_order.append(relative)
    if manifest_bytes != rfc8785.dumps(manifest) + b"\n":
        raise ValueError("E_PACK:MANIFEST_SERIALIZATION")
    if declared_order != sorted(declared_order, key=lambda value: value.encode("utf-8")):
        raise ValueError("E_PACK:MANIFEST_ORDER")

    actual_paths = set(source_files) - {MANIFEST_PATH}
    if set(declared) != actual_paths:
        raise ValueError("E_PACK:MANIFEST_FILE_SET")
    for relative, (size, digest) in declared.items():
        content = source_files[relative]
        if len(content) != size or hashlib.sha256(content).hexdigest() != digest:
            raise ValueError(f"E_PACK:FILE:{relative}")

    tree_preimage = b"".join(
        relative.encode("utf-8")
        + b"\0"
        + str(declared[relative][0]).encode("ascii")
        + b"\0"
        + declared[relative][1].encode("ascii")
        + b"\n"
        for relative in declared_order
    )
    if hashlib.sha256(tree_preimage).hexdigest() != manifest["pack_hash"]:
        raise ValueError("E_PACK:MANIFEST_HASH")
    return source_files


def write_pack_manifest(pack: Path, baseline_receipt: Path) -> str:
    if pack.name != PACK_DIRECTORY_NAME or baseline_receipt != (
        pack / "docs/receipts/repo0-baseline-receipt.json"
    ):
        raise ValueError("E_PACK:MANIFEST_PATH")
    manifest_path = pack / MANIFEST_PATH
    if manifest_path.exists() or manifest_path.is_symlink():
        raise ValueError("E_PACK:MANIFEST_EXISTS")
    receipt = parse_strict_json(baseline_receipt.read_bytes())
    if (
        not isinstance(receipt, dict)
        or receipt.get("schema_version") != "repo0-baseline-receipt/v1"
        or not isinstance(receipt.get("independent_file_tree_root_sha256"), str)
        or _SHA256.fullmatch(receipt["independent_file_tree_root_sha256"]) is None
        or receipt.get("production_authority") != "NONE"
    ):
        raise ValueError("E_PACK:BASELINE_RECEIPT")
    source_files = _source_files(pack)
    files: list[dict[str, object]] = []
    tree_items: list[bytes] = []
    for relative in sorted(source_files, key=lambda value: value.encode("utf-8")):
        content = source_files[relative]
        digest = hashlib.sha256(content).hexdigest()
        files.append({"path": relative, "sha256": digest, "size_bytes": len(content)})
        tree_items.append(
            relative.encode("utf-8")
            + b"\0"
            + str(len(content)).encode("ascii")
            + b"\0"
            + digest.encode("ascii")
            + b"\n"
        )
    manifest = {
        "files": files,
        "implementation_baseline_hash": receipt["independent_file_tree_root_sha256"],
        "pack_hash": hashlib.sha256(b"".join(tree_items)).hexdigest(),
        "pack_version": "6.2",
        "production_authority": "NONE",
        "schema_version": "pack-manifest/v1",
        "self_excluded_path": MANIFEST_PATH,
    }
    _atomic_write(manifest_path, rfc8785.dumps(cast(Any, manifest)) + b"\n")
    _verify_pack(pack)
    return cast(str, manifest["pack_hash"])


def _safe_relative_path(value: str) -> PurePosixPath:
    if (
        "\\" in value
        or "\0" in value
        or unicodedata.normalize("NFC", value) != value
        or _PORTABLE_PATH.fullmatch(value) is None
    ):
        raise ValueError("E_PACK:ARCHIVE_PATH")
    path = PurePosixPath(value)
    if (
        path.is_absolute()
        or not path.parts
        or path.as_posix() != value
        or any(part in {"", ".", ".."} for part in path.parts)
    ):
        raise ValueError("E_PACK:ARCHIVE_PATH")
    return path


def _archive_bytes(pack: Path, expected: dict[str, bytes]) -> bytes:
    output = io.BytesIO()
    with ZipFile(output, "w", compression=ZIP_STORED, allowZip64=False) as zipped:
        for relative in sorted(expected, key=lambda value: value.encode("utf-8")):
            info = ZipInfo(f"{pack.name}/{relative}", ZIP_TIMESTAMP)
            info.compress_type = ZIP_STORED
            info.create_system = 3
            info.create_version = 20
            info.extract_version = 20
            info.flag_bits = 0
            info.internal_attr = 0
            info.external_attr = ZIP_EXTERNAL_ATTR
            info.volume = 0
            info.extra = b""
            info.comment = b""
            zipped.writestr(info, expected[relative])
    return output.getvalue()


def build_pack_archive(pack: Path, archive: Path) -> str:
    if archive.name != ARCHIVE_BASENAME:
        raise ValueError("E_PACK:ARCHIVE_NAME")
    resolved_pack = pack.resolve()
    resolved_archive = archive.resolve()
    if resolved_archive == resolved_pack or resolved_pack in resolved_archive.parents:
        raise ValueError("E_PACK:ARCHIVE_PATH")
    expected = _verify_pack(pack)
    content = _archive_bytes(pack, expected)
    digest = hashlib.sha256(content).hexdigest()
    _atomic_write(archive, content)
    _atomic_write(
        archive.with_name(archive.name + SIDECAR_SUFFIX),
        f"{digest}  {archive.name}\n".encode("ascii"),
    )
    verify_pack_archive(pack, archive)
    return digest


def _atomic_write(path: Path, content: bytes) -> None:
    path.parent.mkdir(parents=False, exist_ok=True)
    descriptor, temporary_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    temporary = Path(temporary_name)
    try:
        with os.fdopen(descriptor, "wb") as output:
            output.write(content)
            output.flush()
            os.fsync(output.fileno())
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)


def verify_pack_archive(pack: Path, archive: Path) -> None:
    if archive.name != ARCHIVE_BASENAME:
        raise ValueError("E_PACK:ARCHIVE_NAME")
    expected = _verify_pack(pack)
    try:
        archive_stat = archive.lstat()
    except OSError as error:
        raise ValueError("E_PACK:ARCHIVE_FORMAT") from error
    if not stat.S_ISREG(archive_stat.st_mode) or archive_stat.st_nlink != 1:
        raise ValueError("E_PACK:ARCHIVE_FORMAT")
    try:
        archive_bytes = archive.read_bytes()
    except OSError as error:
        raise ValueError("E_PACK:ARCHIVE_FORMAT") from error
    archive_digest = hashlib.sha256(archive_bytes).hexdigest()
    sidecar = archive.with_name(archive.name + SIDECAR_SUFFIX)
    expected_sidecar = f"{archive_digest}  {archive.name}\n".encode("ascii")
    try:
        sidecar_stat = sidecar.lstat()
        sidecar_bytes = sidecar.read_bytes()
    except OSError as error:
        raise ValueError("E_PACK:SIDECAR") from error
    if (
        not stat.S_ISREG(sidecar_stat.st_mode)
        or sidecar_stat.st_nlink != 1
        or sidecar_bytes != expected_sidecar
    ):
        raise ValueError("E_PACK:SIDECAR")

    archived: dict[str, bytes] = {}
    try:
        with ZipFile(io.BytesIO(archive_bytes)) as zipped:
            if zipped.comment:
                raise ValueError("E_PACK:ARCHIVE_METADATA")
            seen_names: set[str] = set()
            expected_names = [
                f"{PACK_DIRECTORY_NAME}/{relative}"
                for relative in sorted(expected, key=lambda value: value.encode("utf-8"))
            ]
            relative_names: dict[str, str] = {}
            for info in zipped.infolist():
                if info.filename in seen_names:
                    raise ValueError("E_PACK:ARCHIVE_DUPLICATE")
                seen_names.add(info.filename)
                if info.is_dir():
                    raise ValueError("E_PACK:ARCHIVE_FILE_SET")
                archive_path = _safe_relative_path(info.filename)
                if not archive_path.parts or archive_path.parts[0] != PACK_DIRECTORY_NAME:
                    raise ValueError("E_PACK:ARCHIVE_PATH")
                relative = PurePosixPath(*archive_path.parts[1:])
                if not relative.parts:
                    raise ValueError("E_PACK:ARCHIVE_PATH")
                relative_names[info.filename] = relative.as_posix()
            if [info.filename for info in zipped.infolist()] != expected_names:
                raise ValueError("E_PACK:ARCHIVE_FILE_SET")

            for info in zipped.infolist():
                relative_name = relative_names[info.filename]
                if (
                    info.date_time != ZIP_TIMESTAMP
                    or info.compress_type != ZIP_STORED
                    or info.create_system != 3
                    or info.create_version != 20
                    or info.extract_version != 20
                    or info.flag_bits != 0
                    or info.internal_attr != 0
                    or info.external_attr != ZIP_EXTERNAL_ATTR
                    or info.volume != 0
                    or info.extra
                    or info.comment
                ):
                    raise ValueError("E_PACK:ARCHIVE_METADATA")
                expected_content = expected.get(relative_name)
                if expected_content is None:
                    raise ValueError("E_PACK:ARCHIVE_FILE_SET")
                expected_crc = zlib.crc32(expected_content) & 0xFFFFFFFF
                if (
                    info.file_size != len(expected_content)
                    or info.compress_size != len(expected_content)
                    or expected_crc != info.CRC
                ):
                    raise ValueError("E_PACK:ARCHIVE_INTEGRITY")
                archived[relative_name] = zipped.read(info)
    except (BadZipFile, RuntimeError, zlib.error) as error:
        raise ValueError("E_PACK:ARCHIVE_FORMAT") from error
    if set(archived) != set(expected):
        raise ValueError("E_PACK:ARCHIVE_FILE_SET")
    if any(archived[name] != content for name, content in expected.items()):
        raise ValueError("E_PACK:ARCHIVE_BYTES")
    if archive_bytes != _archive_bytes(pack, expected):
        raise ValueError("E_PACK:ARCHIVE_REBUILD")


def main() -> int:
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="command", required=True)
    build = sub.add_parser("build")
    build.add_argument("--pack", type=Path, required=True)
    build.add_argument("--archive", type=Path, required=True)
    verify = sub.add_parser("verify")
    verify.add_argument("--pack", type=Path, required=True)
    verify.add_argument("--archive", type=Path)
    manifest = sub.add_parser("manifest")
    manifest.add_argument("--pack", type=Path, required=True)
    manifest.add_argument("--baseline-receipt", type=Path, required=True)
    args = parser.parse_args()
    if args.command == "build":
        build_pack_archive(args.pack, args.archive)
    elif args.command == "manifest":
        write_pack_manifest(args.pack, args.baseline_receipt)
    elif args.archive is None:
        _verify_pack(args.pack)
    else:
        verify_pack_archive(args.pack, args.archive)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())import importlib
import math
import re
from dataclasses import dataclass
from datetime import date
from uuid import UUID

from .errors import ContractNotImplementedError


@dataclass(frozen=True)
class ProviderScope:
    scope_id: str
    fixture_ids: tuple[int, ...]
    league_id: int
    season: int
    deadline_mono: float
    source_kind: str = "MOCK"
    stage: str = "PROVIDER_PROBE"
    max_attempts: int = 20
    config_sha256: str = "0" * 64
    source_tree_sha256: str = "0" * 64
    receipt: object = None
    events_fixture_ids: tuple[int, ...] = ()
    lookup_date: str | None = None


def verify_probe_protocol(scope: ProviderScope | None = None) -> None:
    if type(scope) is not ProviderScope:
        raise ContractNotImplementedError("D0-T01")
    lookup_only = scope.lookup_date is not None and not scope.fixture_ids
    if scope.lookup_date is not None and (
        scope.stage != "PROVIDER_PROBE"
        or date.fromisoformat(scope.lookup_date).isoformat() != scope.lookup_date
    ):
        raise ValueError("E_PROVIDER_LOOKUP_SCOPE")
    if (
        str(UUID(scope.scope_id)) != scope.scope_id
        or scope.source_kind not in {"MOCK", "OBSERVED_REAL"}
        or scope.stage not in {"PROVIDER_PROBE", "LIVE_READ_ONLY"}
        or not (0 if lookup_only else 1) <= len(scope.fixture_ids) <= 5
        or len(set(scope.fixture_ids)) != len(scope.fixture_ids)
        or any(type(i) is not int or not 0 < i <= 2**53 - 1 for i in scope.fixture_ids)
        or type(scope.league_id) is not int
        or not 0 < scope.league_id <= 2**53 - 1
        or type(scope.season) is not int
        or not 2000 <= scope.season <= 2100
        or type(scope.max_attempts) is not int
        or not 1 <= scope.max_attempts <= (20 if scope.stage == "PROVIDER_PROBE" else 600)
        or type(scope.deadline_mono) not in {int, float}
        or not math.isfinite(scope.deadline_mono)
        or not set(scope.events_fixture_ids) <= set(scope.fixture_ids)
        or any(type(i) is not int for i in scope.events_fixture_ids)
        or any(
            not re.fullmatch(r"[0-9a-f]{64}", h)
            for h in (scope.config_sha256, scope.source_tree_sha256)
        )
    ):
        raise ValueError("E_PROVIDER_SCOPE")


def verify_call_authorization(
    scope: ProviderScope | None = None, *, purpose: str = "STATUS", now_mono: float = 0
) -> None:
    verify_probe_protocol(scope)
    assert scope is not None
    if (
        purpose not in {"STATUS", "COVERAGE", "LOOKUP", "BUNDLE", "EVENTS_FALLBACK"}
        or not math.isfinite(now_mono)
        or not now_mono < scope.deadline_mono
        or scope.deadline_mono > now_mono + (300 if scope.stage == "PROVIDER_PROBE" else 7200)
    ):
        raise ValueError("E_PROVIDER_DEADLINE_OR_PURPOSE")
    if scope.source_kind == "OBSERVED_REAL":
        try:
            # PB-14 supplies this owner. Missing owner/evidence always refuses real I/O.
            admission = importlib.import_module("moj_discovery.live_intent")
            admission.verify_provider_receipt(scope.receipt, scope, purpose)
        except Exception:
            raise ValueError("E_PROVIDER_REAL_AUTHORITY_REQUIRED") from Nonefrom .errors import ContractNotImplementedError


def append_observation(*_args: object, **_kwargs: object) -> None:
    raise ContractNotImplementedError("D0-T02")


def append_correction(*_args: object, **_kwargs: object) -> None:
    raise ContractNotImplementedError("D0-T02")"""Reconstruct observed deliveries in a fresh store through the actual shared ingest."""

import argparse
import hashlib
import sqlite3
from collections.abc import Iterator
from pathlib import Path
from time import monotonic, sleep
from typing import Any

import rfc8785

from .ingest import Ingestor
from .input_journal import ERRORS, InputJournal, _read
from .offline_faults import WriteDeniedStore
from .offline_projection import semantic_projection
from .offline_run import create_offline_run


def _operations(original: InputJournal, writer_closed: Path | None) -> Iterator[dict[str, Any]]:
    consumed: list[dict[str, Any]] = []
    deadline = monotonic() + 120
    while writer_closed is not None and not writer_closed.exists():
        if monotonic() >= deadline:
            raise TimeoutError("E_OFFLINE_REPLAY_TIMEOUT")
        batch = list(original.iter_operations(start=len(consumed), complete_prefix=True))
        consumed.extend(batch)
        yield from batch
        sleep(0.25)
    # Reopen every retained input after the writer stops; cached observations alone
    # cannot prove that source bytes survived or that the final journal is complete.
    original.reconcile(original.store)
    final = list(original.iter_operations())
    if final[: len(consumed)] != consumed:
        raise ValueError("E_OFFLINE_REPLAY_SOURCE_CHANGED")
    yield from final[len(consumed) :]


def verify_replay_equivalence(
    run_dir: Path, replay_dir: Path, *, writer_closed: Path | None = None
) -> dict[str, Any]:
    original = InputJournal(run_dir)
    operations = _operations(original, writer_closed)
    replay_store = create_offline_run(replay_dir, original.context)
    fault_path = run_dir / "sqlite-faults.jsonl"
    if fault_path.exists():
        # Replay the recorded SQLite fault mechanism, never a supplied outcome string.
        replay_store = WriteDeniedStore(replay_store.db_path, replay_dir / "sqlite-faults.jsonl")
    replay = Ingestor(replay_store)
    acks: dict[tuple[str, str, str], dict[str, Any]] = {}
    applied: dict[int, dict[str, Any]] = {}
    for operation in operations:
        kind = operation["kind"]
        if kind == "RECEIVED":
            try:
                ack = replay.apply(operation["raw"])
                outcome = {"status": "APPLIED", "ack": ack}
                acks[
                    (
                        str(ack["generation"]),
                        str(ack["highest_contiguous_sequence"]),
                        ack["cursor_hash"],
                    )
                ] = ack
            except ValueError as error:
                if str(error) not in ERRORS:
                    raise
                outcome = {"status": "REJECTED", "code": ERRORS[str(error)]}
            except (sqlite3.Error, OSError):
                outcome = {"status": "REJECTED", "code": "STORAGE_FAILED"}
            applied[operation["reference_receive_index"]] = outcome
        elif kind == "OUTCOME":
            observed = applied[operation["reference_receive_index"]]
            recorded = operation["outcome"]

            def logical(outcome: dict[str, Any]) -> dict[str, Any]:
                if outcome["status"] != "APPLIED":
                    return outcome
                return {
                    **outcome,
                    "ack": {k: v for k, v in outcome["ack"].items() if k != "committed_at_us"},
                }

            if logical(observed) != logical(recorded):
                raise ValueError("E_OFFLINE_REPLAY_OUTCOME")
        elif kind == "ACK_CONFIRMATION":
            key = (operation["generation"], operation["sequence"], operation["cursor_hash"])
            if key not in acks:
                raise ValueError("E_OFFLINE_ACK_BINDING")
            replay.confirm_ack(acks[key])
        elif kind != "PARTIAL_TAIL":
            raise ValueError("E_OFFLINE_REPLAY_OPERATION")
    expected_actual = semantic_projection(original.store.db_path)
    actual = semantic_projection(replay_store.db_path)
    if fault_path.exists() and _read(fault_path) != _read(replay_dir / "sqlite-faults.jsonl"):
        raise ValueError("E_OFFLINE_REPLAY_FAULT")
    if actual != expected_actual:
        raise ValueError("E_OFFLINE_REPLAY_MISMATCH")
    result: dict[str, Any] = {
        "equal": True,
        "deliveries": len(applied),
        "projection_sha256": hashlib.sha256(rfc8785.dumps(actual)).hexdigest(),
    }
    (replay_dir / "replay-result.json").write_bytes(rfc8785.dumps(result))
    return result


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("run_dir", type=Path)
    parser.add_argument("replay_dir", type=Path)
    parser.add_argument("--writer-closed", type=Path, required=True)
    args = parser.parse_args()
    verify_replay_equivalence(args.run_dir, args.replay_dir, writer_closed=args.writer_closed)"""Deterministic aggregation for the two isolated review roles."""

from __future__ import annotations

import hashlib
import uuid
from datetime import UTC, datetime
from typing import Any, cast

import rfc8785
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

from .review_authorization import (
    _schema_validate,
    review_identity,
    verify_review_execution_receipt,
    verify_review_result_binding,
)

RESULT_DOMAIN = b"HD636/REVIEW-RESULT/v1\0"
_IMPLEMENTATION_FLAGS = (
    "REPO0_BASELINE_VALID",
    "SAFE_TO_IMPLEMENT_R0",
    "SAFE_TO_IMPLEMENT_F0A",
    "SAFE_TO_IMPLEMENT_SEC0",
    "SAFE_TO_IMPLEMENT_E0",
    "SAFE_TO_IMPLEMENT_D0",
)
_SECURITY_FLAGS = (
    "CYBERSECURITY_REVIEW_COMPLETE",
    "CHROME_CAPABILITY_BOUNDARY_PASS",
    "AUTHORIZATION_TRUST_PASS",
    "CREDENTIAL_EVIDENCE_BOUNDARY_PASS",
    "HASHING_CRYPTOGRAPHY_PASS",
    "CUSTODY_ISOLATION_PASS",
)
_SEVERITY = {"CRITICAL": 0, "IMPORTANT": 1, "MINOR": 2}


def _digest(value: object) -> str:
    return hashlib.sha256(rfc8785.dumps(cast(Any, value))).hexdigest()


def review_content_hash(value: dict[str, object]) -> str:
    return hashlib.sha256(
        RESULT_DOMAIN
        + rfc8785.dumps(
            cast(Any, {key: item for key, item in value.items() if key != "content_hash"})
        )
    ).hexdigest()


def _instant(value: object) -> datetime:
    try:
        result = datetime.fromisoformat(str(value))
    except ValueError as error:
        raise ValueError("E_REVIEW_FRESHNESS") from error
    if result.tzinfo is None:
        raise ValueError("E_REVIEW_FRESHNESS")
    return result.astimezone(UTC)


def _complete_receipt(receipt: dict[str, object], role: str) -> None:
    required = {
        "authorization_id",
        "review_role",
        "review_run_id",
        "workspace_root",
        "input_content_roots",
        "result_sha256",
        "commands_executed_root",
        "finished_at",
        "fresh_session_attestation",
        "production_authority",
        "signature_algorithm",
        "signature",
        "host_boot_id",
        "trust_epoch",
        "preparation_commands_root",
    }
    if not required <= set(receipt) or receipt.get("review_role") != role:
        raise ValueError("E_REVIEW_RECEIPT")
    roots = receipt["input_content_roots"]
    fresh = receipt["fresh_session_attestation"]
    if (
        not isinstance(roots, list)
        or len(roots) != 5
        or not all(isinstance(item, str) and len(item) == 64 for item in roots)
        or not isinstance(fresh, dict)
        or fresh.get("attested") is not True
        or fresh.get("procedural_not_cryptographic") is not True
        or receipt.get("production_authority") != "NONE"
        or receipt.get("signature_algorithm") != "Ed25519"
    ):
        raise ValueError("E_REVIEW_RECEIPT")


def _review_is_well_formed(review: dict[str, object], role: str, *, current: bool) -> None:
    if current:
        _schema_validate(
            review,
            "review-result.schema.json",
            {
                "IMPLEMENTATION_READINESS_REVIEWER": "DescendantImplementationReviewResult",
                "CYBERSECURITY_REVIEWER": "DescendantCybersecurityReviewResult",
            }[role],
        )
    if (
        review.get("schema_version") != f"independent-review-result/v{2 if current else 1}"
        or review.get("review_role") != role
        or review.get("authorized_production_phases") != "NONE"
        or review.get("content_hash") != review_content_hash(review)
        or not isinstance(review.get("findings"), list)
        or not isinstance(review.get("verdicts"), dict)
    ):
        raise ValueError("E_REVIEW_RESULT")


def _has_blocking_findings(review: dict[str, object]) -> bool:
    return any(
        isinstance(item, dict) and item.get("blocking") is True
        for item in cast(list[object], review["findings"])
    )


def aggregate_independent_reviews(
    implementation: dict[str, object],
    cybersecurity: dict[str, object],
    implementation_receipt: dict[str, object],
    cybersecurity_receipt: dict[str, object],
    implementation_authorization: dict[str, object],
    cybersecurity_authorization: dict[str, object],
    public_key: Ed25519PublicKey,
    config: dict[str, object],
    *,
    expected_host_boot_id: str,
    expected_trust_epoch: int,
    now: datetime | None = None,
    external_seal: dict[str, object] | None = None,
) -> dict[str, object]:
    if config.get("authorized_production_phases") != "NONE":
        raise ValueError("E_REVIEW_AUTHORITY")
    current = config.get("schema_version") == "review-aggregation-config/v2"
    if config.get("schema_version") not in {
        None,
        "review-aggregation-config/v1",
        "review-aggregation-config/v2",
    }:
        raise ValueError("E_REVIEW_RESULT")
    _review_is_well_formed(implementation, "IMPLEMENTATION_READINESS_REVIEWER", current=current)
    _review_is_well_formed(cybersecurity, "CYBERSECURITY_REVIEWER", current=current)
    verify_review_result_binding(implementation, implementation_authorization)
    verify_review_result_binding(cybersecurity, cybersecurity_authorization)
    if current and review_identity(implementation) != review_identity(cybersecurity):
        raise ValueError("E_REVIEW_IDENTITY")
    if current and (
        external_seal is None
        or external_seal.get("schema_version") != "external-seal-attestation/v7"
        or external_seal.get("artifact_type") != "RUNTIME_PACK"
        or review_identity(external_seal) != review_identity(implementation)
        or external_seal.get("zip_sha256") != implementation["pack_zip_sha256"]
        or any(
            external_seal.get("manifest_sha256") != auth.get("pack_manifest_sha256")
            for auth in (implementation_authorization, cybersecurity_authorization)
        )
    ):
        raise ValueError("E_REVIEW_IDENTITY")
    verify_review_execution_receipt(
        implementation_receipt,
        implementation_authorization,
        public_key,
        result_sha256=_digest(implementation),
        expected_host_boot_id=expected_host_boot_id,
        expected_trust_epoch=expected_trust_epoch,
        now=now,
    )
    verify_review_execution_receipt(
        cybersecurity_receipt,
        cybersecurity_authorization,
        public_key,
        result_sha256=_digest(cybersecurity),
        expected_host_boot_id=expected_host_boot_id,
        expected_trust_epoch=expected_trust_epoch,
        now=now,
    )
    _complete_receipt(implementation_receipt, "IMPLEMENTATION_READINESS_REVIEWER")
    _complete_receipt(cybersecurity_receipt, "CYBERSECURITY_REVIEWER")
    if (
        implementation.get("pack_zip_sha256") != cybersecurity.get("pack_zip_sha256")
        or implementation.get("repo0_receipt_sha256") != cybersecurity.get("repo0_receipt_sha256")
        or implementation_receipt["workspace_root"] == cybersecurity_receipt["workspace_root"]
        or implementation_receipt["authorization_id"] == cybersecurity_receipt["authorization_id"]
        or implementation_receipt["review_run_id"] == cybersecurity_receipt["review_run_id"]
        or implementation_receipt["input_content_roots"]
        != cybersecurity_receipt["input_content_roots"]
        or implementation_authorization.get("one_use_serial")
        == cybersecurity_authorization.get("one_use_serial")
        or implementation_authorization.get("allowed_output_root")
        == cybersecurity_authorization.get("allowed_output_root")
    ):
        raise ValueError("E_REVIEW_INDEPENDENCE")
    if implementation_receipt["result_sha256"] != _digest(implementation) or cybersecurity_receipt[
        "result_sha256"
    ] != _digest(cybersecurity):
        raise ValueError("E_REVIEW_RECEIPT")
    aggregate_at = (now or datetime.now(UTC)).astimezone(UTC)
    latest_finish = max(
        _instant(implementation_receipt["finished_at"]),
        _instant(cybersecurity_receipt["finished_at"]),
    )
    delay = config.get("maximum_aggregate_delay_seconds")
    if not isinstance(delay, int) or isinstance(delay, bool):
        raise ValueError("E_REVIEW_FRESHNESS")
    if (aggregate_at - latest_finish).total_seconds() > delay:
        raise ValueError("E_REVIEW_FRESHNESS")
    implementation_verdicts = implementation["verdicts"]
    cybersecurity_verdicts = cybersecurity["verdicts"]
    assert isinstance(implementation_verdicts, dict) and isinstance(cybersecurity_verdicts, dict)
    if (
        implementation_verdicts.get("AUTHORIZED_PRODUCTION_PHASES") != "NONE"
        or cybersecurity_verdicts.get("AUTHORIZED_PRODUCTION_PHASES") != "NONE"
    ):
        raise ValueError("E_REVIEW_AUTHORITY")
    ready = implementation_verdicts.get("READY_TO_IMPLEMENT_DISCOVERY_PACK")
    implementation_flags = (
        ("DESCENDANT_REPOSITORY_VALID", *_IMPLEMENTATION_FLAGS[1:])
        if current
        else _IMPLEMENTATION_FLAGS
    )
    if ready == "YES" and any(
        implementation_verdicts.get(flag) != "YES" for flag in implementation_flags
    ):
        raise ValueError("E_REVIEW_PREREQUISITES")
    security_complete = all(cybersecurity_verdicts.get(flag) == "YES" for flag in _SECURITY_FLAGS)
    passed = (
        implementation.get("review_outcome") == "PASS"
        and cybersecurity.get("review_outcome") == "PASS"
        and ready == "YES"
        and security_complete
        and not _has_blocking_findings(implementation)
        and not _has_blocking_findings(cybersecurity)
    )
    findings = [
        *cast(list[object], implementation["findings"]),
        *cast(list[object], cybersecurity["findings"]),
    ]
    if not all(isinstance(item, dict) for item in findings):
        raise ValueError("E_REVIEW_RESULT")
    finding_rows = [cast(dict[str, object], item) for item in findings]
    ids = [str(item.get("finding_id")) for item in finding_rows]
    if len(ids) != len(set(ids)):
        raise ValueError("E_REVIEW_FINDINGS")
    finding_rows.sort(
        key=lambda item: (_SEVERITY.get(str(item.get("severity")), 99), str(item.get("finding_id")))
    )
    result_hashes = [
        _digest(implementation),
        _digest(cybersecurity),
        _digest(implementation_receipt),
        _digest(cybersecurity_receipt),
    ]
    aggregate_name = hashlib.sha256(
        b"".join(bytes.fromhex(value) for value in result_hashes)
    ).hexdigest()
    aggregate: dict[str, object] = {
        "schema_version": "review-aggregate-result/v2"
        if current
        else "independent-review-result/v1",
        "review_role": "AGGREGATE_REVIEWER",
        "review_outcome": "PASS"
        if passed
        else (
            "REJECTED"
            if "REJECTED"
            in (implementation.get("review_outcome"), cybersecurity.get("review_outcome"))
            else "HOLD"
        ),
        "findings": finding_rows,
        "pack_zip_sha256": implementation["pack_zip_sha256"],
        **(
            review_identity(implementation)
            if current
            else {"repo0_receipt_sha256": implementation["repo0_receipt_sha256"]}
        ),
        "review_run_id": str(uuid.uuid5(uuid.NAMESPACE_URL, "hd634:" + aggregate_name)),
        "implementation_review_sha256": result_hashes[0],
        "cybersecurity_review_sha256": result_hashes[1],
        "implementation_receipt_sha256": result_hashes[2],
        "cybersecurity_receipt_sha256": result_hashes[3],
        "verdicts": {
            **{flag: implementation_verdicts.get(flag, "NO") for flag in implementation_flags},
            "READY_TO_IMPLEMENT_DISCOVERY_PACK": "YES" if passed else "NO",
            "SAFE_TO_FREEZE_SCOPE0": implementation_verdicts.get("SAFE_TO_FREEZE_SCOPE0", "NO"),
            "AUTHORIZED_PRODUCTION_PHASES": "NONE",
        },
        "authorized_production_phases": "NONE",
    }
    aggregate["content_hash"] = review_content_hash(aggregate)
    if current:
        _schema_validate(aggregate, "review-result.schema.json", "DescendantAggregateReviewResult")
    return aggregate


def build_plan_self_review(record: dict[str, object]) -> dict[str, object]:
    forbidden = {"zip_sha256", "zip", "sidecar", "manifest_sha256", "final_manifest_sha256"}
    required = {
        "schema_version",
        "governed_content_root",
        "task_manifest_sha256",
        "checks",
        "test_exit_code",
        "test_output_sha256",
        "independent_plan_review",
        "runtime_implementation_ready",
        "authorized_production_phases",
    }
    if (
        set(record) != required
        or forbidden & set(record)
        or record.get("schema_version") != "plan-self-review/v1"
    ):
        raise ValueError("E_SELF_REVIEW_BINDING")
    if (
        record.get("test_exit_code") != 0
        or record.get("independent_plan_review") != "PENDING"
        or record.get("runtime_implementation_ready") != "NO"
        or record.get("authorized_production_phases") != "NONE"
    ):
        raise ValueError("E_SELF_REVIEW_BINDING")
    return record"""Domain-separated host review authorization and receipt verification."""

from __future__ import annotations

import base64
import hashlib
import json
from datetime import UTC, datetime, timedelta
from pathlib import Path
from typing import Any, cast

import rfc8785
from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey, Ed25519PublicKey
from jsonschema import Draft202012Validator  # type: ignore[import-untyped]

from .schema_formats import STRICT_FORMAT_CHECKER

LAUNCH_ID_DOMAIN = b"HD636/REVIEW-LAUNCH/ID/v1\0"
LAUNCH_SIGN_DOMAIN = b"HD636/REVIEW-LAUNCH/SIGN/v1\0"
RECEIPT_ID_DOMAIN = b"HD636/REVIEW-RECEIPT/ID/v1\0"
RECEIPT_SIGN_DOMAIN = b"HD636/REVIEW-RECEIPT/SIGN/v1\0"
RUNTIME_ROOT = Path(__file__).resolve().parents[2]
DESCENDANT_IDENTITY_FIELDS = (
    "repository_qualification_receipt_sha256",
    "repository_identity_kind",
    "repository_commit_oid",
    "repository_tree_oid",
    "repository_file_tree_root_sha256",
)


def review_identity(value: dict[str, object]) -> dict[str, object]:
    """Project the complete current identity; missing fields never compare as None."""
    if value.get("repository_identity_kind") != "DESCENDANT" or any(
        not isinstance(value.get(field), str) or not value[field]
        for field in DESCENDANT_IDENTITY_FIELDS
    ):
        raise ValueError("E_REVIEW_IDENTITY")
    return {field: value[field] for field in DESCENDANT_IDENTITY_FIELDS}


def verify_review_result_binding(
    result: dict[str, object], authorization: dict[str, object]
) -> None:
    current = authorization.get("schema_version") == "review-launch-authorization/v2"
    if result.get("schema_version") != f"independent-review-result/v{2 if current else 1}" or any(
        result.get(key) != authorization.get(key) or key not in result or key not in authorization
        for key in ("review_role", "review_run_id", "pack_zip_sha256")
    ):
        raise ValueError("E_REVIEW_RESULT_BINDING")
    if current:
        if review_identity(result) != review_identity(authorization):
            raise ValueError("E_REVIEW_IDENTITY")
    elif result.get("repo0_receipt_sha256") != authorization.get("repo0_receipt_sha256"):
        raise ValueError("E_REVIEW_RESULT_BINDING")


def _b64decode(value: object) -> bytes:
    if not isinstance(value, str) or "=" in value:
        raise ValueError("E_REVIEW_AUTH_SIGNATURE")
    try:
        result = base64.urlsafe_b64decode(value + "=" * (-len(value) % 4))
    except ValueError as error:
        raise ValueError("E_REVIEW_AUTH_SIGNATURE") from error
    if base64.urlsafe_b64encode(result).decode().rstrip("=") != value:
        raise ValueError("E_REVIEW_AUTH_SIGNATURE")
    return result


def _projection(value: dict[str, object], *excluded: str) -> bytes:
    projected = {key: item for key, item in value.items() if key not in excluded}
    return rfc8785.dumps(cast(Any, projected))


def _identifier(value: dict[str, object], *, prefix: str, domain: bytes, derived: str) -> str:
    return prefix + hashlib.sha256(domain + _projection(value, "signature", derived)).hexdigest()


def _schema_validate(value: dict[str, object], schema_name: str, definition: str) -> None:
    schema_path = RUNTIME_ROOT / "vendor/hybrid-discovery-v6.3.6/docs/schemas" / schema_name
    schema = json.loads(schema_path.read_text())
    validator = Draft202012Validator(
        {"$ref": f"#/$defs/{definition}", "$defs": schema["$defs"]},
        format_checker=STRICT_FORMAT_CHECKER,
    )
    if next(validator.iter_errors(value), None) is not None:
        raise ValueError("E_REVIEW_AUTH_SCHEMA")


def _instant(value: object, error: str) -> datetime:
    try:
        result = datetime.fromisoformat(str(value))
    except ValueError as cause:
        raise ValueError(error) from cause
    if result.tzinfo is None:
        raise ValueError(error)
    return result.astimezone(UTC)


def key_id(public_key: Ed25519PublicKey) -> str:
    raw = public_key.public_bytes(serialization.Encoding.Raw, serialization.PublicFormat.Raw)
    return "key:ed25519:" + hashlib.sha256(raw).hexdigest()


def sign_review_launch_authorization(
    authorization: dict[str, object], private_key: Ed25519PrivateKey
) -> dict[str, object]:
    value = dict(authorization)
    value.pop("authorization_id", None)
    value.pop("signature", None)
    value["issuer_key_id"] = key_id(private_key.public_key())
    value["authorization_id"] = _identifier(
        value, prefix="REVIEW-LAUNCH:", domain=LAUNCH_ID_DOMAIN, derived="authorization_id"
    )
    value["signature"] = (
        base64.urlsafe_b64encode(
            private_key.sign(LAUNCH_SIGN_DOMAIN + _projection(value, "signature"))
        )
        .decode()
        .rstrip("=")
    )
    return value


def sign_review_execution_receipt(
    receipt: dict[str, object], private_key: Ed25519PrivateKey
) -> dict[str, object]:
    value = dict(receipt)
    value.pop("receipt_id", None)
    value.pop("signature", None)
    value["issuer_key_id"] = key_id(private_key.public_key())
    value["receipt_id"] = _identifier(
        value, prefix="REVIEW-RECEIPT:", domain=RECEIPT_ID_DOMAIN, derived="receipt_id"
    )
    value["signature"] = (
        base64.urlsafe_b64encode(
            private_key.sign(RECEIPT_SIGN_DOMAIN + _projection(value, "signature"))
        )
        .decode()
        .rstrip("=")
    )
    return value


def _verify_signature(
    value: dict[str, object], public_key: Ed25519PublicKey, domain: bytes
) -> None:
    signature = _b64decode(value.get("signature"))
    if len(signature) != 64:
        raise ValueError("E_REVIEW_AUTH_SIGNATURE")
    try:
        public_key.verify(signature, domain + _projection(value, "signature"))
    except InvalidSignature as error:
        raise ValueError("E_REVIEW_AUTH_SIGNATURE") from error


def _verify_mounts(authorization: dict[str, object]) -> None:
    mounts = authorization.get("input_mounts")
    if not isinstance(mounts, list) or len(mounts) != 5:
        raise ValueError("E_REVIEW_AUTH_BINDING")
    source_roots: list[str] = []
    for mount in mounts:
        if (
            not isinstance(mount, dict)
            or mount.get("mode") != "READ_ONLY"
            or mount.get("source_root") != mount.get("workspace_mount")
            or not isinstance(mount.get("source_root"), str)
        ):
            raise ValueError("E_REVIEW_AUTH_BINDING")
        source_roots.append(cast(str, mount["source_root"]))
    if len(source_roots) != len(set(source_roots)):
        raise ValueError("E_REVIEW_AUTH_BINDING")


def review_launch_duration(authorization: dict[str, object]) -> int:
    """Honor the signed lifetime; never extend an existing four-hour launch."""
    allowed = {
        "review-launch-authorization/v1": (14400,),
        "review-launch-authorization/v2": (14400, 28800),
    }.get(str(authorization.get("schema_version")), ())
    seconds = authorization.get("maximum_duration_seconds")
    if type(seconds) is not int or seconds not in allowed:
        raise ValueError("E_REVIEW_AUTH_EXPIRY")
    return seconds


def verify_review_launch_authorization(
    authorization: dict[str, object],
    public_key: Ed25519PublicKey,
    expected_role: str,
    expected_workspace: str,
    expected_pack_sha256: str,
    *,
    expected_host_boot_id: str | None = None,
    expected_trust_epoch: int | None = None,
    now: datetime | None = None,
) -> dict[str, object]:
    _schema_validate(
        authorization,
        "review-launch-authorization.schema.json",
        "ReviewLaunchAuthorization",
    )
    expected_id = _identifier(
        authorization, prefix="REVIEW-LAUNCH:", domain=LAUNCH_ID_DOMAIN, derived="authorization_id"
    )
    if authorization.get("authorization_id") != expected_id or authorization.get(
        "issuer_key_id"
    ) != key_id(public_key):
        raise ValueError("E_REVIEW_AUTH_BINDING")
    _verify_signature(authorization, public_key, LAUNCH_SIGN_DOMAIN)
    duration = review_launch_duration(authorization)
    issued = _instant(authorization["issued_at"], "E_REVIEW_AUTH_EXPIRY")
    not_before = _instant(authorization["not_before"], "E_REVIEW_AUTH_EXPIRY")
    expires = _instant(authorization["expires_at"], "E_REVIEW_AUTH_EXPIRY")
    trusted_now = (now or datetime.now(UTC)).astimezone(UTC)
    if (
        authorization.get("production_authority") != "NONE"
        or authorization.get("issuer_role") != "HOST_REVIEW_AUTHORITY"
        or authorization.get("audience") != "hybrid-discovery:independent-review-launcher:v1"
        or authorization.get("signature_algorithm") != "Ed25519"
        or authorization.get("fresh_session_required") is not True
        or not (issued <= not_before <= trusted_now < expires)
        or expires - issued != timedelta(seconds=duration)
        or authorization.get("review_role") != expected_role
        or authorization.get("workspace_root") != expected_workspace
        or authorization.get("pack_zip_sha256") != expected_pack_sha256
        or (
            expected_host_boot_id is not None
            and authorization.get("host_boot_id") != expected_host_boot_id
        )
        or (
            expected_trust_epoch is not None
            and authorization.get("trust_epoch") != expected_trust_epoch
        )
    ):
        raise ValueError("E_REVIEW_AUTH_BINDING")
    _verify_mounts(authorization)
    return {"result": "PASS", "authorization_id": expected_id}


def verify_review_execution_receipt(
    receipt: dict[str, object],
    authorization: dict[str, object],
    public_key: Ed25519PublicKey,
    *,
    result_sha256: str,
    expected_host_boot_id: str | None = None,
    expected_trust_epoch: int | None = None,
    now: datetime | None = None,
) -> dict[str, object]:
    verify_review_launch_authorization(
        authorization,
        public_key,
        cast(str, authorization["review_role"]),
        cast(str, authorization["workspace_root"]),
        cast(str, authorization["pack_zip_sha256"]),
        expected_host_boot_id=expected_host_boot_id,
        expected_trust_epoch=expected_trust_epoch,
        now=now,
    )
    _schema_validate(
        receipt,
        "review-execution-receipt.schema.json",
        "ReviewExecutionReceipt",
    )
    expected_id = _identifier(
        receipt,
        prefix="REVIEW-RECEIPT:",
        domain=RECEIPT_ID_DOMAIN,
        derived="receipt_id",
    )
    if (
        receipt.get("receipt_id") != expected_id
        or receipt.get("issuer_key_id") != authorization["issuer_key_id"]
    ):
        raise ValueError("E_REVIEW_RECEIPT_BINDING")
    _verify_signature(receipt, public_key, RECEIPT_SIGN_DOMAIN)
    current = authorization["schema_version"] == "review-launch-authorization/v2"
    if receipt["schema_version"] != f"review-execution-receipt/v{2 if current else 1}":
        raise ValueError("E_REVIEW_IDENTITY")
    if current and review_identity(receipt) != review_identity(authorization):
        raise ValueError("E_REVIEW_IDENTITY")
    mounts = cast(list[dict[str, object]], authorization["input_mounts"])
    expected_roots = [mount["content_root_sha256"] for mount in mounts]
    fresh = receipt.get("fresh_session_attestation")
    started = _instant(receipt["started_at"], "E_REVIEW_RECEIPT_FRESHNESS")
    finished = _instant(receipt["finished_at"], "E_REVIEW_RECEIPT_FRESHNESS")
    consumed = _instant(receipt["authorization_consumed_at"], "E_REVIEW_RECEIPT_FRESHNESS")
    expires = _instant(authorization["expires_at"], "E_REVIEW_RECEIPT_FRESHNESS")
    trusted_now = (now or datetime.now(UTC)).astimezone(UTC)
    if (
        receipt.get("authorization_id") != authorization["authorization_id"]
        or receipt.get("issuer_role") != "HOST_REVIEW_AUTHORITY"
        or receipt.get("review_role") != authorization["review_role"]
        or receipt.get("review_run_id") != authorization["review_run_id"]
        or receipt.get("workspace_root") != authorization["workspace_root"]
        or receipt.get("input_content_roots") != expected_roots
        or receipt.get("result_sha256") != result_sha256
        or receipt.get("production_authority") != "NONE"
        or receipt.get("signature_algorithm") != "Ed25519"
        or receipt.get("host_boot_id") != authorization["host_boot_id"]
        or receipt.get("trust_epoch") != authorization["trust_epoch"]
        or receipt.get("unexpected_changed_paths") != []
        or not isinstance(receipt.get("allowed_changed_paths"), list)
        or not receipt["allowed_changed_paths"]
        or not isinstance(fresh, dict)
        or fresh.get("attestation_type") != "HUMAN_FRESH_CODEX_SESSION"
        or fresh.get("attested") is not True
        or fresh.get("procedural_not_cryptographic") is not True
        or not (consumed <= started <= finished <= expires and finished <= trusted_now)
        or finished - started > timedelta(seconds=review_launch_duration(authorization))
    ):
        raise ValueError("E_REVIEW_RECEIPT_BINDING")
    return {"result": "PASS", "receipt_id": expected_id}from .errors import ContractNotImplementedError


