def _object(value: object) -> Mapping[str, object]:
    assert isinstance(value, dict)
    return value


def _array(value: object) -> list[object]:
    assert isinstance(value, list)
    return value


def _strings(value: object) -> list[str]:
    values = _array(value)
    assert all(isinstance(item, str) for item in values)
    return [str(item) for item in values]


def _timestamp(value: object) -> datetime:
    assert isinstance(value, str)
    return datetime.fromisoformat(value.upper().replace("Z", "+00:00"))


def validate_scope_policy(policy: Mapping[str, object]) -> None:
    assert policy["schema_version"] == "scope0-input-policy/v1"
    assert policy["wildcard_pointers_permitted"] is False
    assert policy["production_authority"] == "NONE"
    assert frozenset(_strings(policy["allowed_categories"])) == SCOPE_CATEGORIES
    assert frozenset(_strings(policy["excluded_source_classes"])) == SCOPE_EXCLUDED_SOURCE_CLASSES
    entries = _array(policy["entries"])
    observed = frozenset(
        (
            str(entry["entry_id"]),
            str(entry["schema_id"]),
            str(entry["schema_version"]),
            str(entry["artifact_name"]),
            str(entry["json_pointer"]),
            str(entry["category"]),
        )
        for entry_value in entries
        for entry in (_object(entry_value),)
    )
    assert len(entries) == len(observed) == 26
    assert observed == SCOPE_POLICY_ENTRIES
    assert all("*" not in entry[4] for entry in observed)


def validate_required_decision_registry(registry: Mapping[str, object]) -> None:
    assert registry["schema_version"] == "required-discovery-decisions/v1"
    assert registry["decision_count"] == len(REQUIRED_DECISIONS)
    assert registry["additional_decisions_permitted"] is False
    assert registry["production_authority"] == "NONE"
    decisions = [_object(item) for item in _array(registry["decisions"])]
    assert tuple(str(item["decision_id"]) for item in decisions) == REQUIRED_DECISIONS
    assert [item["order"] for item in decisions] == list(range(1, 19))
    assert all(item["unresolved_default"] == "UNKNOWN" for item in decisions)


def validate_consumer_registry(registry: Mapping[str, object]) -> None:
    assert registry["schema_version"] == "discovery-capability-consumers/v1"
    assert registry["production_authority"] == "NONE"
    consumers = [_object(item) for item in _array(registry["consumers"])]
    assert len(consumers) == len(DISCOVERY_CONSUMERS)
    assert frozenset(str(item["consumer_id"]) for item in consumers) == DISCOVERY_CONSUMERS


def semantic_vector_error(
    vector_name: str,
    base_case: Mapping[str, object],
    candidate_case: Mapping[str, object],
    *,
    scope_policy: Mapping[str, object] | None = None,
) -> str | None:
    record = _object(candidate_case["record"])
    base_record = _object(base_case["record"])
    if vector_name == "scope-semantic-v1.json":
        assert scope_policy is not None
        return _scope_error(record, base_record, scope_policy)
    assert vector_name == "review-semantic-v1.json"
    if record.get("schema_version") == "discovery-capability/v1":
        return _capability_error(record)
    return _review_error(record)


def _production_error(record: Mapping[str, object]) -> str | None:
    production = record.get("production_authority")
    if isinstance(production, dict):
        production = production.get("AUTHORIZED_PRODUCTION_PHASES")
    if production is None:
        production = record.get("AUTHORIZED_PRODUCTION_PHASES")
    return None if production == "NONE" else "E_PRODUCTION_AUTHORITY"


def _scope_error(
    record: Mapping[str, object],
    base: Mapping[str, object],
    policy: Mapping[str, object],
) -> str | None:
    if "stored_approval_hash" in record:
        return _scope_integrity_error(record, base)
    production_error = _production_error(record)
    if production_error is not None:
        return production_error
    kind = record.get("record_kind")
    if kind == "FROZEN_INITIAL_SCOPE_APPROVAL":
        return _frozen_scope_error(record, base, policy)
    if kind == "NO_FEASIBLE_SCOPE":
        return _no_feasible_scope_error(record)
    if kind == "SCOPE_REVOCATION":
        return _scope_revocation_error(record, base)
    return "E_SCOPE_RECORD_KIND"


def _frozen_scope_error(
    record: Mapping[str, object],
    base: Mapping[str, object],
    policy: Mapping[str, object],
) -> str | None:
    if record.get("authority") != "V7_DESIGN_ONLY":
        return "E_SCOPE_AUTHORITY"
    forecast_scope = _object(record["forecast_bundle_scope"])
    if record.get("competition_id") != forecast_scope.get("competition_id"):
        return "E_SCOPE_COMPETITION_MISMATCH"
    horizons = frozenset(_strings(record["supported_horizons"]))
    bands = _object(record["evaluation_bands"])
    if horizons != frozenset(str(key) for key in bands):
        return "E_SCOPE_HORIZON_BAND_KEYS"
    band_error = _band_error(bands, _strings(forecast_scope["eligible_fixture_states"]))
    if band_error is not None:
        return band_error
    partition_error = _partition_error(_object(record["temporal_partitions"]))
    if partition_error is not None:
        return partition_error
    if not (
        _timestamp(record["valid_from"])
        <= _timestamp(record["review_by"])
        <= _timestamp(record["valid_from"]) + timedelta(seconds=2_592_000)
    ):
        return "E_SCOPE_REVIEW_BOUNDARY"
    admission_error = _admission_error(record, base, policy)
    if admission_error is not None:
        return admission_error
    denial = _object(record["performance_input_denial"])
    if (
        denial.get("policy_enforced") is not True
        or denial.get("audit_confirmed") is not True
        or frozenset(_strings(denial["denied_category_codes"])) != PERFORMANCE_DENIAL_CODES
    ):
        return "E_SCOPE_PERFORMANCE_DENIAL"
    lineage = _object(record["contamination_lineage"])
    if lineage.get("replay_disposition") != "MATCHED":
        return "E_SCOPE_LEDGER_REPLAY"
    if (
        lineage.get("contamination_status") != "CLEAN"
        or lineage.get("test_access_events") != "0"
        or lineage.get("forward_access_events") != "0"
    ):
        return "E_SCOPE_CONTAMINATION"
    if lineage.get("access_ledger_schema_version") != "scope-input-audit/v1":
        return "E_SCOPE_SCHEMA_VERSION"
    ledger_ref = _object(lineage["access_ledger_ref"])
    if (
        ledger_ref.get("schema_id") != "urn:hybrid-discovery:v6.2:meta-records:v1"
        or ledger_ref.get("schema_version") != "scope-input-audit/v1"
        or ledger_ref.get("artifact_type") != "SCOPE_INPUT_AUDIT"
    ):
        return "E_SCOPE_SCHEMA_VERSION"
    if ledger_ref.get("content_hash") != lineage.get("access_ledger_hash"):
        return "E_SCOPE_EVIDENCE_HASH"
    return None


def _band_error(evaluation_bands: Mapping[str, object], eligible_states: list[str]) -> str | None:
    allowed_states = frozenset(eligible_states)
    phase_order = {
        "PRE_MATCH": 0,
        "FIRST_HALF": 1,
        "HALFTIME": 2,
        "SECOND_HALF": 3,
        "EXTRA_TIME": 4,
    }
    admission_by_state = {
        "PRE_MATCH": "ADMITTED_PRE_MATCH",
        "FIRST_HALF": "ADMITTED_FIRST_HALF",
        "HALFTIME": "ADMITTED_HALFTIME",
        "SECOND_HALF": "ADMITTED_SECOND_HALF",
        "EXTRA_TIME": "ADMITTED_EXTRA_TIME",
    }
    for horizon, band_values in evaluation_bands.items():
        live_intervals: list[tuple[int, int]] = []
        chronology: list[tuple[int, int]] = []
        for value in _array(band_values):
            band = _object(value)
            phase = str(band.get("fixture_phase"))
            if horizon == "H1" and phase not in {"PRE_MATCH", "FIRST_HALF"}:
                return "E_SCOPE_H1_PHASE"
            if phase not in allowed_states or band.get("admission_code") != admission_by_state.get(
                phase
            ):
                return "E_SCOPE_BAND_STATE"
            is_live = phase in {"FIRST_HALF", "SECOND_HALF", "EXTRA_TIME"}
            has_minute = "start_minute" in band or "end_minute" in band
            if not is_live and has_minute:
                return "E_SCOPE_NONLIVE_MINUTE"
            if not is_live:
                chronology.append((phase_order[phase], -1))
                continue
            try:
                start = int(str(band["start_minute"]))
                end = int(str(band["end_minute"]))
            except (KeyError, ValueError):
                return "E_SCOPE_MINUTE_RANGE"
            if start < 0 or start > 180 or end < 0 or end > 180:
                return "E_SCOPE_MINUTE_RANGE"
            if start >= end:
                return "E_SCOPE_MINUTE_ORDER"
            live_intervals.append((start, end))
            chronology.append((phase_order[phase], start))
        if chronology != sorted(chronology):
            return "E_SCOPE_BAND_ORDER"
        ordered_intervals = sorted(live_intervals)
        for index, interval in enumerate(ordered_intervals):
            if index and interval[0] < ordered_intervals[index - 1][1]:
                return "E_SCOPE_BAND_OVERLAP"
    return None


def _partition_error(partitions: Mapping[str, object]) -> str | None:
    windows = {
        name: _object(partitions[name]) for name in ("TRAIN", "VALIDATION", "TEST", "FORWARD")
    }
    for name in ("TEST", "FORWARD"):
        window = windows[name]
        if window.get("pre_freeze_access_state") != "NEVER_ACCESSED":
            return f"E_SCOPE_{name}_TOUCHED"
        if window.get("pre_freeze_access_event_count") != "0":
            return f"E_SCOPE_{name}_TOUCHED"
    bounds = {
        name: (_timestamp(window["start"]), _timestamp(window["end"]))
        for name, window in windows.items()
    }
    if any(start >= end for start, end in bounds.values()):
        return "E_SCOPE_PARTITION_EMPTY"
    if bounds["TRAIN"][1] > bounds["VALIDATION"][0]:
        return "E_SCOPE_PARTITION_OVERLAP"
    if bounds["VALIDATION"][1] > bounds["TEST"][0]:
        return "E_SCOPE_PARTITION_ORDER"
    if bounds["TEST"][1] > bounds["FORWARD"][0]:
        return "E_SCOPE_PARTITION_OVERLAP"
    starts = [bounds[name][0] for name in ("TRAIN", "VALIDATION", "TEST", "FORWARD")]
    if starts != sorted(starts):
        return "E_SCOPE_PARTITION_ORDER"
    return None


def _admission_error(
    record: Mapping[str, object],
    base: Mapping[str, object],
    policy: Mapping[str, object],
) -> str | None:
    binding_expectations = {
        "scope_input_view_binding": (
            "urn:hybrid-discovery:v6.2:meta-records:v1",
            "scope-input-view/v1",
        ),
        "scope_input_audit_binding": (
            "urn:hybrid-discovery:v6.2:meta-records:v1",
            "scope-input-audit/v1",
        ),
        "scope_input_policy_binding": (
            "urn:hybrid-discovery:v6.2:scope0-input-policy:v1",
            "scope0-input-policy/v1",
        ),
    }
    for field, expected in binding_expectations.items():
        binding = _object(record[field])
        if (binding.get("schema_id"), binding.get("schema_version")) != expected:
            return "E_SCOPE_SCHEMA_VERSION"
        base_binding = _object(base[field])
        if binding.get("content_hash") != base_binding.get("content_hash"):
            return "E_SCOPE_EVIDENCE_HASH"
    policy_entries = {
        str(entry["entry_id"]): entry
        for value in _array(policy["entries"])
        for entry in (_object(value),)
    }
    base_hashes = {
        str(item["policy_entry_id"]): item.get("projected_value_hash")
        for value in _array(base["admitted_inputs"])
        for item in (_object(value),)
    }
    seen: set[str] = set()
    for value in _array(record["admitted_inputs"]):
        admitted = _object(value)
        pointer = str(admitted.get("json_pointer"))
        if "*" in pointer:
            return "E_SCOPE_POLICY_POINTER"
        entry_id = str(admitted.get("policy_entry_id"))
        if entry_id in seen or entry_id not in policy_entries:
            return "E_SCOPE_POLICY_ADMISSION"
        seen.add(entry_id)
        entry = policy_entries[entry_id]
        if admitted.get("category") != entry.get("category"):
            return "E_SCOPE_POLICY_CATEGORY"
        if pointer != entry.get("json_pointer"):
            return "E_SCOPE_POLICY_POINTER"
        source_ref = _object(admitted["source_ref"])
        expected_artifact_type = (
            "E0_REPORT" if entry.get("schema_version") == "e0-report/v1" else "D0_REPORT"
        )
        if source_ref.get("schema_version") != entry.get("schema_version"):
            return "E_SCOPE_SCHEMA_VERSION"
        if (
            source_ref.get("schema_id") != entry.get("schema_id")
            or source_ref.get("artifact_type") != expected_artifact_type
        ):
            return "E_SCOPE_POLICY_ADMISSION"
        base_item = next(
            (
                item
                for value in _array(base["admitted_inputs"])
                for item in (_object(value),)
                if item.get("policy_entry_id") == entry_id
            ),
            None,
        )
        if base_item is not None and source_ref != _object(base_item["source_ref"]):
            return "E_SCOPE_EVIDENCE_HASH"
        expected_hash = base_hashes.get(entry_id)
        if expected_hash is not None and admitted.get("projected_value_hash") != expected_hash:
            return "E_SCOPE_EVIDENCE_HASH"
    return None


def _no_feasible_scope_error(record: Mapping[str, object]) -> str | None:
    if record.get("authority") != "NONE":
        return "E_SCOPE_AUTHORITY"
    positive_fields = {
        "competition_id",
        "forecast_bundle_scope",
        "supported_horizons",
        "evaluation_bands",
        "temporal_partitions",
        "admitted_inputs",
    }
    if positive_fields.intersection(record):
        return "E_NO_FEASIBLE_POSITIVE_SCOPE"
    return None


def _scope_revocation_error(record: Mapping[str, object], base: Mapping[str, object]) -> str | None:
    if record.get("terminal") is not True or record.get("reopening_permitted") is not False:
        return "E_REVOCATION_TERMINAL"
    if record.get("approval_hash") != base.get("approval_hash"):
        return "E_REVOCATION_APPROVAL_HASH"
    if record.get("revocation_sequence") != base.get("revocation_sequence"):
        return "E_REVOCATION_SEQUENCE"
    if record.get("previous_revocation_hash") != base.get("previous_revocation_hash"):
        return "E_REVOCATION_PREVIOUS_HASH"
    return None


def _scope_integrity_error(record: Mapping[str, object], base: Mapping[str, object]) -> str | None:
    if record.get("stored_approval_hash") != record.get("recomputed_approval_hash"):
        return "E_APPROVAL_IMMUTABILITY"
    if record.get("stored_approval_hash") != record.get("revocation_approval_hash"):
        return "E_REVOCATION_APPROVAL_HASH"
    if record.get("revocation_sequence") != base.get("revocation_sequence"):
        return "E_REVOCATION_SEQUENCE"
    if record.get("previous_revocation_hash") != base.get("previous_revocation_hash"):
        return "E_REVOCATION_PREVIOUS_HASH"
    if record.get("terminal") is not True:
        return "E_REVOCATION_TERMINAL"
    return None


def _review_error(record: Mapping[str, object]) -> str | None:
    production_error = _production_error(record)
    if production_error is not None:
        return production_error
    findings = [_object(item) for item in _array(record["findings"])]
    if record.get("review_outcome") in {"HELD", "REJECTED"} and not findings:
        return "E_REVIEW_FINDINGS_EMPTY"
    finding_ids = [str(item.get("finding_id")) for item in findings]
    if len(finding_ids) != len(set(finding_ids)):
        return "E_FINDING_ID_DUPLICATE"
    for finding in findings:
        if finding.get("blocking") is True and any(
            record.get(verdict) != "NO" for verdict in _strings(finding["affected_verdicts"])
        ):
            return "E_BLOCKER_VERDICT"
    if record.get("READY_TO_IMPLEMENT_DISCOVERY_PACK") == "YES" and any(
        record.get(verdict) != "YES" for verdict in READINESS_INPUTS
    ):
        return "E_READY_CONTRADICTION"
    decisions = [_object(item) for item in _array(record["required_discovery_decisions"])]
    decision_ids = tuple(str(item.get("decision_id")) for item in decisions)
    if decision_ids != REQUIRED_DECISIONS or len(decision_ids) != len(set(decision_ids)):
        return "E_REQUIRED_DECISION_SET"
    for decision in decisions:
        consumers = frozenset(_strings(decision["authorized_consumers"]))
        if not consumers.issubset(DISCOVERY_CONSUMERS):
            return "E_CONSUMER_UNKNOWN"
        disposition = decision.get("disposition")
        evidence = _array(decision["evidence_refs"])
        limitations = _strings(decision["limitation_codes"])
        if disposition == "SUPPORTED" and not evidence:
            return "E_SUPPORTED_EVIDENCE_REQUIRED"
        if disposition == "PARTIAL" and (not evidence or not limitations):
            return "E_PARTIAL_SEMANTICS"
        if disposition in {
            "UNSUPPORTED",
            "UNKNOWN",
            "NOT_OBSERVED",
            "INCONCLUSIVE",
            "SAFETY_STOP",
        }:
            if consumers:
                if disposition == "UNKNOWN":
                    return "E_UNKNOWN_AUTHORIZES_CONSUMER"
                return f"E_{disposition}_AUTHORIZES_CONSUMER"
            if not limitations:
                return f"E_{disposition}_LIMITATION"
    return None


def _capability_error(record: Mapping[str, object]) -> str | None:
    production_error = _production_error(record)
    if production_error is not None:
        return production_error
    evaluated = frozenset(_strings(record["evaluated_consumers"]))
    authorized = frozenset(_strings(record["authorized_consumers"]))
    blocked = frozenset(_strings(record["blocked_consumers"]))
    if not (evaluated | authorized | blocked).issubset(DISCOVERY_CONSUMERS):
        return "E_CONSUMER_UNKNOWN"
    verdict = str(record.get("verdict"))
    evidence = _array(record["evidence_refs"])
    limitations = _strings(record["limitation_codes"])
    unknowns = _strings(record["unknown_codes"])
    confidence = record.get("confidence")
    context_closed = _object(record["tested_context"]).get("context_status") == "CLOSED"
    if verdict == "SUPPORTED":
        if not evidence:
            return "E_SUPPORTED_EVIDENCE_REQUIRED"
        if confidence not in {"OBSERVED", "INFERRED"}:
            return "E_SUPPORTED_CONFIDENCE"
        if unknowns:
            return "E_SUPPORTED_UNKNOWN"
        if not authorized:
            return "E_SUPPORTED_CONSUMER_SCOPE"
        if not context_closed:
            return "E_SUPPORTED_SEMANTICS"
    elif verdict == "PARTIAL":
        if not limitations:
            return "E_PARTIAL_LIMITATION"
        if not evidence:
            return "E_PARTIAL_SEMANTICS"
        if not blocked:
            return "E_PARTIAL_BLOCKED_CONSUMER"
        if not authorized:
            return "E_PARTIAL_AUTHORIZED_CONSUMER"
        if confidence not in {"OBSERVED", "INFERRED"}:
            return "E_PARTIAL_CONFIDENCE"
        if not context_closed:
            return "E_PARTIAL_SEMANTICS"
    elif verdict == "UNSUPPORTED":
        if authorized:
            return "E_UNSUPPORTED_AUTHORIZES"
        if not limitations:
            return "E_UNSUPPORTED_LIMITATION"
        if unknowns:
            return "E_UNSUPPORTED_UNKNOWN"
        if not evidence or not context_closed:
            return "E_UNSUPPORTED_SEMANTICS"
    elif verdict == "UNKNOWN":
        if authorized:
            return "E_UNKNOWN_AUTHORIZES"
        if confidence not in {"UNKNOWN", "NOT_OBSERVED"}:
            return "E_UNKNOWN_SEMANTICS"
        if not limitations or not unknowns:
            return "E_UNKNOWN_SEMANTICS"
    elif verdict == "INDETERMINATE":
        if authorized:
            return "E_INDETERMINATE_AUTHORIZES"
        if confidence not in {"CONFLICT", "INTEGRITY_FAILURE", "INSUFFICIENT_SAMPLE"}:
            return "E_INDETERMINATE_CONFIDENCE"
        if not evidence or not limitations:
            return "E_INDETERMINATE_SEMANTICS"
    else:
        return "E_CAPABILITY_VERDICT"
    if authorized.intersection(blocked):
        return "E_CONSUMER_PARTITION_OVERLAP"
    if evaluated != DISCOVERY_CONSUMERS or authorized | blocked != evaluated:
        return "E_CONSUMER_PARTITION_INCOMPLETE"
    if verdict in {"UNSUPPORTED", "UNKNOWN", "INDETERMINATE"} and blocked != evaluated:
        return f"E_{verdict}_SEMANTICS"
    return None"""Offline SQLite storage using the unmodified governed bootstrap schema."""

import hashlib
import json
import sqlite3
from contextlib import closing
from functools import lru_cache
from pathlib import Path
from typing import Any

from .canonical import canonical_content_hash
from .errors import ContractNotImplementedError

VENDOR = Path(__file__).resolve().parents[2] / "vendor/hybrid-discovery-v6.3.6"


def verified_ddl() -> str:
    relative = "sql/discovery-store-v1.sql"
    lock = json.loads((VENDOR.parents[1] / "schema-lock.json").read_text())
    content = (VENDOR / relative).read_bytes()
    matches = [item for item in lock["files"] if item["path"] == relative]
    if len(matches) != 1 or hashlib.sha256(content).hexdigest() != matches[0]["sha256"]:
        raise ValueError("E_STORE_DDL_HASH")
    return content.decode("utf-8")


@lru_cache(maxsize=8)
def _schema_objects(ddl: str) -> tuple[tuple[Any, ...], ...]:
    with closing(sqlite3.connect(":memory:")) as reference:
        reference.executescript(ddl)
        return tuple(
            reference.execute(
                "SELECT type,name,tbl_name,sql FROM sqlite_schema ORDER BY type,name"
            ).fetchall()
        )


def verify_database(connection: sqlite3.Connection) -> None:
    """Compare complete schema objects, including constraints and all triggers."""
    if connection.execute("PRAGMA user_version").fetchone()[0] != 1:
        raise ValueError("E_STORE_USER_VERSION")
    if [row[0] for row in connection.execute("PRAGMA integrity_check")] != ["ok"]:
        raise ValueError("E_STORE_INTEGRITY")
    if connection.execute("PRAGMA foreign_key_check").fetchall():
        raise ValueError("E_STORE_FOREIGN_KEY")
    query = "SELECT type,name,tbl_name,sql FROM sqlite_schema ORDER BY type,name"
    expected = _schema_objects(verified_ddl())
    if tuple(tuple(row) for row in connection.execute(query)) != expected:
        raise ValueError("E_STORE_SCHEMA")


def _runtime_authorizer(
    action: int, first: str | None, second: str | None, _db: str | None, _trigger: str | None
) -> int:
    allowed = {
        sqlite3.SQLITE_SELECT,
        sqlite3.SQLITE_READ,
        sqlite3.SQLITE_INSERT,
        sqlite3.SQLITE_TRANSACTION,
        sqlite3.SQLITE_SAVEPOINT,
        sqlite3.SQLITE_RECURSIVE,
    }
    if action in allowed:
        return sqlite3.SQLITE_OK
    if action == sqlite3.SQLITE_UPDATE and first in {
        "run_meta",
        "stream_generations",
        "coherence_controllers",
    }:
        return sqlite3.SQLITE_OK
    if action == sqlite3.SQLITE_FUNCTION and second in {
        "max",
        "coalesce",
        "length",
        "glob",
        "raise",
    }:
        return sqlite3.SQLITE_OK
    return sqlite3.SQLITE_DENY


class RunStore:
    def __init__(self, db_path: Path | None = None) -> None:
        self._db_path = db_path

    @property
    def db_path(self) -> Path:
        if self._db_path is None:
            raise ContractNotImplementedError("F0A-T04")
        return self._db_path

    def bootstrap_v1(self) -> None:
        ddl = verified_ddl()
        path = self.db_path
        if path.exists():
            with closing(self.connect()):
                return
        # Exclusive creation never overwrites an existing run or adopts a symlink.
        with path.open("xb"):
            pass
        with closing(sqlite3.connect(path)) as connection:
            connection.executescript(ddl)
            verify_database(connection)

    def connect(self) -> sqlite3.Connection:
        path = self.db_path
        if not path.is_file() or path.is_symlink():
            raise ValueError("E_STORE_MISSING_DATABASE")
        connection = sqlite3.connect(path.resolve().as_uri() + "?mode=rw", uri=True)
        try:
            connection.execute("PRAGMA foreign_keys=ON")
            connection.execute("PRAGMA trusted_schema=OFF")
            connection.execute("PRAGMA synchronous=FULL")
            connection.execute("PRAGMA busy_timeout=5000")
            connection.execute("PRAGMA temp_store=MEMORY")
            if connection.execute("PRAGMA max_page_count=32768").fetchone()[0] != 32768:
                raise ValueError("E_STORE_CAPACITY")
            verify_database(connection)
            connection.row_factory = sqlite3.Row
            connection.set_authorizer(_runtime_authorizer)
            return connection
        except BaseException:
            connection.close()
            raise


TABLES = (
    "run_meta",
    "raw_commits",
    "raw_conflicts",
    "application_records",
    "derived_revisions",
    "reducer_cursors",
    "ack_outbox",
    "ack_cursors",
    "stream_generations",
    "gap_records",
    "gap_epoch_bindings",
    "generation_transitions",
    "coherence_epochs",
    "coherence_controllers",
    "coherence_transitions",
    "shock_observations",
)
KEY = ("run_id", "browser_run_id", "producer_id", "stream_id", "generation")


@lru_cache(maxsize=4096)
def _cursor_digest(position: tuple[Any, ...], registry_bytes: bytes) -> str:
    # Immutable complete input and source bytes: changed storage or registry cannot reuse a proof.
    run, browser, producer, stream, generation, sequence, raw_hash, previous = position
    return canonical_content_hash(
        "CursorStep",
        {
            "schema_version": "cursor-step/v1",
            "discovery_run_id": run,
            "browser_run_id": browser,
            "producer_id": producer,
            "stream_id": stream,
            "generation": str(generation),
            "sequence": str(sequence),
            "raw_observation_hash": raw_hash,
            "previous_cursor_hash": previous,
        },
        registry_bytes=registry_bytes,
    )


def validate_journal(tables: dict[str, list[dict[str, Any]]]) -> None:
    schema = json.loads((VENDOR / "schemas/durability-records.schema.json").read_text())
    registry_bytes = (VENDOR / "registries/canonical-hash-domains.v1.json").read_bytes()
    h0 = schema["$defs"]["CursorChainContract"]["properties"]["seed_hash_h0"]["const"]
    applied = [row for row in tables["raw_commits"] if row["disposition"] == "APPLIED"]
    chains: dict[tuple[Any, ...], tuple[int, str]] = {}
    linked_tables = ("application_records", "derived_revisions", "reducer_cursors", "ack_outbox")
    if any(len(tables[name]) != len(applied) for name in linked_tables):
        raise ValueError("E_STORE_DURABLE_CHAIN")
    positions: dict[str, dict[tuple[Any, ...], dict[str, Any]]] = {}
    for name in linked_tables:
        positions[name] = {}
        for row in tables[name]:
            position = (
                *tuple(row[field] for field in KEY),
                row.get("sequence", row.get("highest_contiguous_sequence")),
            )
            if position in positions[name]:
                raise ValueError("E_STORE_DURABLE_CHAIN")
            positions[name][position] = row
    for raw in sorted(applied, key=lambda row: tuple(row[field] for field in (*KEY, "sequence"))):
        key = tuple(raw[field] for field in KEY)
        sequence, prior = chains.get(key, (0, h0))
        digest = _cursor_digest(
            (*key, raw["sequence"], raw["raw_observation_content_hash"], prior), registry_bytes
        )
        if (raw["sequence"], raw["previous_cursor_hash"], raw["cursor_hash"]) != (
            sequence + 1,
            prior,
            digest,
        ):
            raise ValueError("E_STORE_DURABLE_CHAIN")
        records: dict[str, dict[str, Any]] = {}
        for name in linked_tables:
            match = positions[name].get((*key, sequence + 1))
            if match is None:
                raise ValueError("E_STORE_DURABLE_CHAIN")
            records[name] = match
        app, revision, cursor, ack = (records[name] for name in linked_tables)
        if not (
            app["raw_commit_id"]
            == revision["raw_commit_id"]
            == ack["raw_commit_id"]
            == raw["raw_commit_id"]
            and revision["application_id"] == ack["application_id"] == app["application_id"]
            and cursor["derived_revision_id"]
            == ack["derived_revision_id"]
            == revision["derived_revision_id"]
            and ack["reducer_cursor_id"] == cursor["reducer_cursor_id"]
            and app["input_cursor_hash"] == cursor["previous_cursor_hash"] == prior
            and app["raw_observation_content_hash"]
            == cursor["raw_observation_content_hash"]
            == raw["raw_observation_content_hash"]
            and cursor["cursor_hash"] == ack["cursor_hash"] == revision["revision_hash"] == digest
            and revision["revision"] == sequence + 1
            and revision["previous_revision_hash"] == (None if sequence == 0 else prior)
        ):
            raise ValueError("E_STORE_DURABLE_CHAIN")
        chains[key] = (sequence + 1, digest)
    histories: dict[tuple[Any, ...], dict[str, Any]] = {}
    for ack in sorted(
        tables["ack_cursors"],
        key=lambda row: tuple(
            row[field] for field in (*KEY, "owner", "highest_contiguous_sequence")
        ),
    ):
        key = tuple(ack[field] for field in KEY)
        owner_key = (*key, ack["owner"])
        previous = histories.get(owner_key)
        required_binding = {"BACKEND": "BACKEND_DURABLE_CHAIN", "EXTENSION": "LOCAL_SPOOL_CHAIN"}
        if ack["verified_against"] != required_binding.get(ack["owner"]):
            raise ValueError("E_STORE_ACK_CHAIN")
        if ack["highest_contiguous_sequence"] == 0:
            valid = (
                previous is None
                and ack["previous_ack_cursor_id"] is None
                and ack["cursor_hash"] == h0
            )
        else:
            valid = (
                ack["previous_ack_cursor_id"]
                == (None if previous is None else previous["ack_cursor_id"])
                and (
                    previous is None
                    or previous["highest_contiguous_sequence"] < ack["highest_contiguous_sequence"]
                )
                and positions["ack_outbox"]
                .get((*key, ack["highest_contiguous_sequence"]), {})
                .get("cursor_hash")
                == ack["cursor_hash"]
            )
        if not valid:
            raise ValueError("E_STORE_ACK_CHAIN")
        histories[owner_key] = ack


def read_journal(
    connection: sqlite3.Connection, *, ordered: bool = True
) -> dict[str, list[dict[str, Any]]]:
    result: dict[str, list[dict[str, Any]]] = {}
    cursor = connection.cursor()
    cursor.row_factory = None
    try:
        for table in TABLES:
            cursor.execute(f"SELECT * FROM {table}")  # noqa: S608 -- fixed allowlist
            columns = [column[0] for column in cursor.description]
            result[table] = [dict(zip(columns, row, strict=True)) for row in cursor]
    finally:
        cursor.close()
    if ordered:
        for rows in result.values():
            rows.sort(key=lambda row: json.dumps(row, sort_keys=True))
    return result"""Exact source-symbol resolution without importing untrusted modules."""
from __future__ import annotations

import ast
from pathlib import Path


def resolve_python_symbol(path: Path, symbol: str) -> bool:
    if not path.is_file() or path.is_symlink():
        raise ValueError("E_SYMBOL_SOURCE")
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    except SyntaxError as error:
        raise ValueError("E_SYMBOL_SYNTAX") from error
    if any(
        isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
        and node.name == symbol
        for node in tree.body
    ):
        return True
    raise ValueError("E_SYMBOL_UNRESOLVED")"""Synthetic accounting observations only; never provider or operator observations."""

import hashlib
from pathlib import Path
from typing import Any, cast

import rfc8785

from .canonical import canonical_content_hash, parse_strict_json, verify_canonical_content_hash
from .offline_protocol import validate_context
from .schema_registry import validate_artifact
from .store import VENDOR


def validate_synthetic_observation(data: bytes, context: dict[str, Any]) -> dict[str, Any]:
    if len(data) > 65536:
        raise ValueError("E_OFFLINE_INPUT_SIZE")
    try:
        raw = parse_strict_json(data)
    except Exception:
        raise ValueError("E_OFFLINE_JSON") from None
    try:
        validate_artifact(raw, "raw-observation.schema.json", bootstrap_only=True, vendor=VENDOR)
    except Exception:
        raise ValueError("E_OFFLINE_SCHEMA") from None
    value = cast(dict[str, Any], raw)
    validate_context(context)
    if (
        value["observation_kind"] != "TERMINAL"
        or value["context"]["context_kind"] != "RUN_BOUND_NOT_DOCUMENT"
        or value["discovery_run_id"] != context["run_id"]
        or value["context"]["browser_run_id"] != context["browser_run_id"]
        or value["stream_id"] != context["stream_id"]
        or value["generation"] != context["generation"]
    ):
        raise ValueError("E_OFFLINE_SOURCE_BINDING")
    try:
        verify_canonical_content_hash(
            "RawObservation",
            value,
            value["content_hash"],
            registry_path=VENDOR / "registries/canonical-hash-domains.v1.json",
        )
    except Exception:
        raise ValueError("E_OFFLINE_CONTENT_HASH") from None
    return value


def load_synthetic_observations(path: Path) -> list[dict[str, Any]]:
    data = path.read_bytes()
    if len(data) > 262144:
        raise ValueError("E_OFFLINE_INPUT_SIZE")
    try:
        manifest = cast(dict[str, Any], parse_strict_json(data))
        if (
            set(manifest) != {"schema_version", "source_kind", "context", "record_count"}
            or manifest["schema_version"] != "offline-scenario/v1"
            or manifest["source_kind"] != "SYNTHETIC_TEST"
            or type(manifest["record_count"]) is not int
            or not 1 <= manifest["record_count"] <= 1000
        ):
            raise ValueError()
        context = manifest["context"]
        validate_context(context)
    except Exception:
        raise ValueError("E_OFFLINE_SOURCE_BINDING") from None
    result = []
    for sequence in range(1, manifest["record_count"] + 1):
        raw: dict[str, Any] = {
            "schema_version": "raw-observation/v1",
            "raw_observation_id": "observation:"
            + hashlib.sha256(
                rfc8785.dumps(
                    [context["run_id"], context["stream_id"], context["generation"], str(sequence)]
                )
            ).hexdigest(),
            "observation_kind": "TERMINAL",
            "pack_hash": context["vendor_sha256"],
            "build_hash": context["code_sha256"],
            "implementation_baseline_hash": context["code_sha256"],
            "capability_manifest_hash": context["schema_lock_sha256"],
            "discovery_run_id": context["run_id"],
            # Synthetic context digest; it is explicitly not a signed live receipt.
            "run_receipt_hash": hashlib.sha256(rfc8785.dumps(context)).hexdigest(),
            "stream_id": context["stream_id"],
            "generation": context["generation"],
            "sequence": str(sequence),
            "context": {
                "context_kind": "RUN_BOUND_NOT_DOCUMENT",
                "browser_run_id": context["browser_run_id"],
                "browser_boot_id": context["browser_run_id"],
                "binding_reason": "TERMINAL_ACCOUNTING",
            },
            "clock_context": {
                "clock_domain_id": context["producer_id"],
                "boot_id": context["browser_run_id"],
                "unit": "MICROSECOND",
                "monotonic_value": str(sequence),
                "resolution_us": "1",
                "owner": "BACKEND",
                "mapping_id": "NOT_APPLICABLE",
                "mapping_status": "NOT_APPLICABLE",
            },
            "sanitizer_version": "sanitizer/v1",
            "content_hash": "0" * 64,
            "production_authority": "NONE",
            "facts": {
                "terminal_code": "MANUAL_STOP",
                "final_generation": context["generation"],
                "final_sequence": str(sequence),
                "observation_count": str(sequence),
                "gap_count": "0",
                "safety_disposition": "PARTIAL_EVIDENCE_ONLY",
            },
        }
        raw["content_hash"] = canonical_content_hash(
            "RawObservation",
            raw,
            registry_path=VENDOR / "registries/canonical-hash-domains.v1.json",
        )
        result.append(validate_synthetic_observation(rfc8785.dumps(raw), context))
    return result"""Validate declaration-stage task semantics without inspecting future symbols."""

from __future__ import annotations

import re
from pathlib import PurePosixPath

BAD = re.compile(r"(?i)(?:\b(?:TODO|TBD|FIXME|PLACEHOLDER)\b|\.\.\.|<[^>]+>|\$\{|\$\(|`)")
TASK_AUTHORITIES = {
    "PLAN_AUTHORING",
    "DISCOVERY_IMPLEMENTATION",
    "REVIEW_TOOLING",
    "EXTERNAL_REVIEW",
}


def validate_task_manifest_semantics(
    manifest: dict[str, object], commands: list[dict[str, object]], owned_paths: set[str]
) -> dict[str, object]:
    if (
        manifest.get("authority") != "PLAN_ONLY"
        or manifest.get("authorized_production_phases") != "NONE"
    ):
        raise ValueError("E_PRODUCTION_AUTHORITY")
    tasks = manifest.get("tasks")
    if not isinstance(tasks, list) or manifest.get("declared_task_count") != len(tasks):
        raise ValueError("E_TASK_COUNT")
    command_ids: set[str] = set()
    for command in commands:
        command_id = command.get("command_id")
        argv = command.get("argv")
        if (
            not isinstance(command_id, str)
            or command_id in command_ids
            or not isinstance(argv, list)
            or not argv
        ):
            raise ValueError("E_COMMAND_SHAPE")
        if any(
            not isinstance(token, str)
            or not token.strip()
            or (index == 0 or argv[index - 1] != "-c")
            and BAD.search(token)
            for index, token in enumerate(argv)
        ):
            raise ValueError("E_COMMAND_PLACEHOLDER")
        if any(
            command.get(key) != "DENY"
            for key in ("network", "provider_access", "authenticated_operator_access")
        ):
            raise ValueError("E_COMMAND_AUTHORITY")
        command_ids.add(command_id)
    seen: set[str] = set()
    for task in tasks:
        task_id = task.get("task_id")
        if not isinstance(task_id, str) or task_id in seen:
            raise ValueError("E_TASK_ID")
        if task.get("authority") not in TASK_AUTHORITIES:
            raise ValueError("E_TASK_AUTHORITY")
        dependencies = task.get("dependencies")
        if not isinstance(dependencies, list) or any(
            dependency not in seen for dependency in dependencies
        ):
            raise ValueError("E_DEPENDENCY_UNKNOWN_OR_FUTURE")
        rollback = task.get("rollback")
        if (
            not isinstance(rollback, list)
            or not rollback
            or any(not isinstance(item, str) or not item.strip() for item in rollback)
        ):
            raise ValueError("E_EMPTY_ROLLBACK")
        command_refs = task.get("exact_command_ids")
        if (
            not isinstance(command_refs, list)
            or not command_refs
            or any(reference not in command_ids for reference in command_refs)
        ):
            raise ValueError("E_TASK_COMMAND")
        for field in ("outputs", "exact_files", "evidence_artifacts"):
            for path in task.get(field, []):
                normalized = path
                if isinstance(path, str) and path not in owned_paths:
                    matches = {
                        owned
                        for owned in owned_paths
                        if not PurePosixPath(owned).is_absolute() and path.endswith("/" + owned)
                    }
                    normalized = next(iter(matches)) if len(matches) == 1 else path
                if normalized not in owned_paths:
                    raise ValueError("E_UNOWNED")
        seen.add(task_id)
    return {"result": "PASS", "task_count": len(tasks), "command_count": len(command_ids)}from __future__ import annotations

