def _assert_before_side_effects(outcome: UniversalScanOutcome) -> None:
    if set(outcome.completed_stages) & set(SIDE_EFFECT_STAGES):
        raise UniversalDenialContractError("E_DENIAL_AFTER_SIDE_EFFECT_BOUNDARY")
