def aad(request: dict[str, Any]) -> bytes:
    return json.dumps(
        {k: v for k, v in request.items() if k != "transport_key"},
        sort_keys=True,
        separators=(",", ":"),
    ).encode()


def validate_request(request: dict[str, Any]) -> None:
    try:
        if (
            set(request)
            != {
                "version",
                "slot",
                "action",
                "config_sha256",
                "source_sha256",
                "intent_sha256",
                "generation",
                "run_id",
                "transport_key",
            }
            or type(request["version"]) is not int
            or request["version"] != 1
            or request["slot"] != SLOT
            or request["action"] not in {"probe", "live-readonly"}
            or any(
                not isinstance(request[k], str) or re.fullmatch("[0-9a-f]{64}", request[k]) is None
                for k in ("config_sha256", "source_sha256", "intent_sha256")
            )
            or any(str(UUID(request[k])) != request[k] for k in ("generation", "run_id"))
            or len(base64.b64decode(request["transport_key"], validate=True)) != 32
        ):
            raise ValueError("E_CREDENTIAL_REQUEST")
    except (ValueError, TypeError, KeyError, AttributeError):
        raise ValueError("E_CREDENTIAL_REQUEST") from None


def new_request(
    action: str,
    config_hash: str,
    source_hash: str,
    generation: str,
    *,
    run_id: str,
    intent_hash: str,
) -> tuple[dict[str, Any], bytes]:
    key = os.urandom(32)
    request = {
        "version": 1,
        "slot": SLOT,
        "action": action,
        "config_sha256": config_hash,
        "source_sha256": source_hash,
        "generation": generation,
        "run_id": run_id,
        "intent_sha256": intent_hash,
        "transport_key": base64.b64encode(key).decode(),
    }
    validate_request(request)
    return request, key


def decrypt_response(request: dict[str, Any], key: bytes, response: dict[str, Any]) -> SecretValue:
    try:
        validate_request(request)
        if (
            set(response) != {"version", "nonce", "ciphertext"}
            or type(response["version"]) is not int
            or response["version"] != 1
        ):
            raise ValueError()
        nonce = base64.b64decode(response["nonce"], validate=True)
        if len(nonce) != 12:
            raise ValueError()
        raw = AESGCM(key).decrypt(
            nonce, base64.b64decode(response["ciphertext"], validate=True), aad(request)
        )
        value = json.loads(raw)
        if set(value) != {"key", "generation"} or value["generation"] != request["generation"]:
            raise ValueError()
        return SecretValue(value["key"])
    except Exception:
        raise ValueError("E_CREDENTIAL_RESPONSE") from None


def helper_command(action: str, *, native_python_sha256: str) -> list[str]:
    if action not in {"serve", "metadata", "enroll", "delete", "self-test"}:
        raise ValueError("E_CREDENTIAL_ACTION")
    helper = ROOT / "tools/windows_credential_helper.py"
    if helper.resolve() != helper or helper.stat().st_nlink != 1 or not NATIVE_PYTHON.is_file():
        raise ValueError("E_CREDENTIAL_PLATFORM")
    if (
        re.fullmatch("[0-9a-f]{64}", native_python_sha256) is None
        or hashlib.sha256(NATIVE_PYTHON.read_bytes()).hexdigest() != native_python_sha256
    ):
        raise ValueError("E_CREDENTIAL_INTERPRETER")
    # The helper must be the committed candidate, never an arbitrary program.
    git = shutil.which("git")
    if git is None:
        raise ValueError("E_CREDENTIAL_SOURCE")
    frozen = subprocess.run(  # noqa: S603 -- resolved Git, fixed read-only path.
        [git, "-C", str(ROOT), "show", "HEAD:tools/windows_credential_helper.py"],
        capture_output=True,
        timeout=10,
        check=False,
    )
    if frozen.returncode != 0 or frozen.stdout != helper.read_bytes():
        raise ValueError("E_CREDENTIAL_SOURCE")
    path = subprocess.run(  # noqa: S603 -- fixed local path translation, no secret arguments.
        ["/usr/bin/wslpath", "-w", str(helper)], capture_output=True, timeout=5, check=False
    )
    if path.returncode != 0:
        raise ValueError("E_CREDENTIAL_PLATFORM")
    return [str(NATIVE_PYTHON), "-I", "-B", path.stdout.decode().strip(), "--" + action]


@contextmanager
def stored_key(
    action: str,
    config_hash: str,
    source_hash: str,
    generation: str,
    *,
    run_id: str,
    intent_hash: str,
    native_python_sha256: str,
) -> Iterator[SecretValue]:
    request, key = new_request(
        action, config_hash, source_hash, generation, run_id=run_id, intent_hash=intent_hash
    )
    process = subprocess.Popen(  # noqa: S603 -- fixed committed helper, private pipes.
        helper_command("serve", native_python_sha256=native_python_sha256),
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        env={},
        close_fds=True,
    )  # noqa: S603 -- fixed committed helper, secret only in private pipes.
    try:
        assert process.stdin is not None and process.stdout is not None
        process.stdin.write(json.dumps(request, separators=(",", ":")).encode() + b"\n")
        process.stdin.flush()
        response = bytearray()
        deadline = time.monotonic() + 15
        with selectors.DefaultSelector() as selector:
            selector.register(process.stdout, selectors.EVENT_READ)
            while b"\n" not in response:
                remaining = deadline - time.monotonic()
                if remaining <= 0 or not selector.select(remaining):
                    raise ValueError("E_CREDENTIAL_TIMEOUT")
                chunk = os.read(process.stdout.fileno(), 4096)
                if not chunk or len(response) + len(chunk) > 8192:
                    raise ValueError("E_CREDENTIAL_RESPONSE")
                response.extend(chunk)
        if response.count(b"\n") != 1 or not response.endswith(b"\n"):
            raise ValueError("E_CREDENTIAL_RESPONSE")
        secret = decrypt_response(request, key, json.loads(response))
        # The helper keeps the native mutex until this context closes. Rotation
        # cannot race a provider session which is using the stored credential.
        yield SecretValue(secret.reveal_for_header(), usable=lambda: process.poll() is None)
    finally:
        if process.stdin is not None:
            process.stdin.close()
        try:
            process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            process.kill()  # Only this owned child; never an image-name/PID search.
            process.wait(timeout=5)
        if process.stdout is not None:
            process.stdout.close()"""Closed display projections. Observed records stay separate from receipt ages."""

import copy
from typing import Any, TypedDict
from uuid import UUID

from .live_contracts import validate_live_record


class WorkspaceState(TypedDict):
    run_id: str | None
    views: list[dict[str, Any]]
    selected: list[str]
    max_matches: int
    source_kind: str
    quota: dict[str, int | None]
    provider_connection: str
    capture_connection: str


WorkspaceView = dict[str, Any]
STATES = {
    "WAITING_FOR_DATA",
    "CURRENT_DISPLAY_ONLY",
    "SOURCE_TIME_UNKNOWN",
    "STALE_PROVIDER",
    "STALE_MARKET",
    "STATE_CONFLICT",
    "MARKET_SUSPENDED",
    "PROFILE_EXPIRED",
    "OUT_OF_SCOPE",
    "STOPPED",
    "PAUSED",
    "GAP",
    "CONTEXT_UNVERIFIED",
}


def _age(value: object) -> int | None:
    if value is None:
        return None
    if type(value) is not int or not 0 <= value <= 2**53 - 1:
        raise ValueError("E_WORKSPACE_AGE")
    return value


def project_watchlist(state: WorkspaceState) -> WorkspaceView:
    try:
        if (state["run_id"] is not None and str(UUID(state["run_id"])) != state["run_id"]) or (
            type(state["max_matches"]) is not int
            or state["max_matches"] not in {1, 3, 5}
            or len(state["views"]) > state["max_matches"]
            or len(set(state["selected"])) != len(state["selected"])
            or state["source_kind"] not in {"MOCK", "OBSERVED_REAL"}
            or state["provider_connection"] not in {"WAITING", "CONNECTED", "PAUSED", "STOPPED"}
            or state["capture_connection"] not in {"CONNECTED", "DISCONNECTED"}
        ):
            raise ValueError()
        if state["run_id"] is None and state["views"]:
            raise ValueError()
        quota = state["quota"]
        caps = {
            "session_remaining": 600,
            "daily_remaining": 6000,
            "minute_remaining": 6,
            "provider_remaining": 2**31 - 1,
        }
        if set(quota) != set(caps):
            raise ValueError()
        for key, cap in caps.items():
            value = quota[key]
            if value is None and key == "provider_remaining":
                continue
            if type(value) is not int or not 0 <= value <= cap:
                raise ValueError()
        matches: list[dict[str, Any]] = []
        for view in state["views"]:
            binding = validate_live_record(view["binding"], "FixtureBinding")
            provider = (
                None
                if view["provider"] is None
                else validate_live_record(view["provider"], "ProviderState")
            )
            if provider is not None and any(
                provider[field] != binding[key]
                for field, key in (
                    ("fixture_id", "provider_fixture_id"),
                    ("home_id", "home_id"),
                    ("away_id", "away_id"),
                    ("kickoff_utc", "kickoff_utc"),
                )
            ):
                raise ValueError()
            if (
                view["status"] not in STATES
                or view["model_enabled"] is not False
                or view["money_ready"] is not False
            ):
                raise ValueError()
            books = []
            markets = {}
            for horizon, raw in view["books"].items():
                book = validate_live_record(raw, "MarketBook")
                if (
                    book["binding_id"] != binding["binding_id"]
                    or book["binding_revision"] != binding["revision"]
                    or book["horizon"] != horizon
                ):
                    raise ValueError()
                if ("SYNTHETIC" in book["quality_flags"]) != (state["source_kind"] == "MOCK"):
                    raise ValueError()
                status = view["market_states"][horizon]
                if status["status"] not in STATES:
                    raise ValueError()
                markets[horizon] = {
                    "status": status["status"],
                    "receipt_age_us": _age(status["receipt_age_us"]),
                    "content_age_us": _age(status["content_age_us"]),
                    "source_age_us": None,
                }
                books.append(book)
            if (
                type(view["projection_revision"]) is not int
                or not 0 <= view["projection_revision"] <= 2**63 - 1
            ):
                raise ValueError()
            score = view["h2_score"]
            if score is not None and (
                type(score) is not dict
                or set(score) != {"home", "away"}
                or any(type(v) is not int or not 0 <= v <= 100 for v in score.values())
            ):
                raise ValueError()
            matches.append(
                {
                    "binding": binding,
                    "provider_state": provider,
                    "books": books,
                    "revision": str(view["projection_revision"]),
                    "display": {
                        "source_kind": state["source_kind"],
                        "status": view["status"],
                        "selected": binding["binding_id"] in state["selected"],
                        "max_matches": state["max_matches"],
                        "provider_receipt_age_us": _age(view["provider_receipt_age_us"]),
                        "provider_content_age_us": _age(view["provider_content_age_us"]),
                        "source_age_us": None,
                        "markets": markets,
                        "h2_score": copy.deepcopy(view["h2_score"]),
                        "quota": copy.deepcopy(quota),
                        "provider_connection": state["provider_connection"],
                        "capture_connection": state["capture_connection"],
                    },
                }
            )
        ids = [row["binding"]["binding_id"] for row in matches]
        if len(set(ids)) != len(ids) or not set(state["selected"]) <= set(ids):
            raise ValueError()
        return {
            "run_id": state["run_id"],
            "matches": matches,
            "source_time_status": "UNKNOWN",
            "model_status": "MODEL_NOT_QUALIFIED",
            "money_ready": False,
        }
    except Exception:
        raise ValueError("E_WORKSPACE_PROJECTION") from None# ruff: noqa: E402
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import cast

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

RUNTIME_ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(RUNTIME_ROOT), str(RUNTIME_ROOT / "src")]

from moj_discovery.review_aggregation import aggregate_independent_reviews
from tools.bootstrap_review_authority import bootstrap_review_authority
from tools.build_candidate_qualification_receipt import _read_bytes
from tools.finalize_review import _validate_consumed_authorization
from tools.full_verifier_config import FullVerifierConfig
from tools.issue_review_launch_authorization import (
    _regular_hash,
    _scope_record,
    authorized_review_context,
    recheck_review_context,
    review_public_key,
    validate_review_scope,
)
from tools.retained_artifact_io import RetainedArtifactIO


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", required=True, type=Path)
    parser.add_argument("--review-a", required=True, type=Path)
    parser.add_argument("--receipt-a", required=True, type=Path)
    parser.add_argument("--authorization-a", required=True, type=Path)
    parser.add_argument("--review-b", required=True, type=Path)
    parser.add_argument("--receipt-b", required=True, type=Path)
    parser.add_argument("--authorization-b", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    authorization_a = json.loads(args.authorization_a.read_text())
    authorization_b = json.loads(args.authorization_b.read_text())
    authority = json.loads((RUNTIME_ROOT / "review-config/review-authority.v1.json").read_text())
    config = json.loads(args.config.read_text())
    context_a = context_b = None
    if config.get("schema_version") == "review-aggregation-config/v2" or any(
        auth.get("schema_version") == "review-launch-authorization/v2"
        for auth in (authorization_a, authorization_b)
    ):
        if config.get("schema_version") != "review-aggregation-config/v2":
            raise ValueError("E_REVIEW_AUTH_BINDING")
        context_a = authorized_review_context(authorization_a, authority, runtime_root=RUNTIME_ROOT)
        context_b = authorized_review_context(authorization_b, authority, runtime_root=RUNTIME_ROOT)
        if (
            context_a["transport"] != context_b["transport"]
            or context_a["seal"] != context_b["seal"]
            or context_a["mounts"] != context_b["mounts"]
        ):
            raise ValueError("E_REVIEW_AUTH_BINDING")
        pack = Path(cast(list[dict[str, str]], context_a["mounts"])[0]["source_root"])
        named = pack / "docs/configs/review-aggregation.v2.json"
        controller = cast(FullVerifierConfig, context_a["controller"])
        artifacts = cast(RetainedArtifactIO, context_a["artifacts"])
        _regular_hash(args.config)
        _regular_hash(named)
        if (
            args.config != RUNTIME_ROOT / "review-config/review-aggregation.v2.json"
            or args.config.read_bytes() != named.read_bytes()
            or named.read_bytes()
            != _read_bytes(
                controller.governed_source_pack / "docs/configs/review-aggregation.v2.json",
                artifacts,
            )
            or config.get("repository_identity")
            != {
                "kind": "DESCENDANT",
                "receipt": str(
                    pack / "docs/receipts/descendant-repository-qualification-receipt.json"
                ),
            }
        ):
            raise ValueError("E_REVIEW_AUTH_BINDING")
        for context in (context_a, context_b):
            cast(dict[str, str], context["snapshots"])[str(args.config)] = _regular_hash(
                args.config
            )
            cast(dict[str, str], context["snapshots"])[str(named)] = _regular_hash(named)
            recheck_review_context(context)
        public_key, epoch = review_public_key(authority)
        configs = [cast(dict[str, object], context["config"]) for context in (context_a, context_b)]
        if any(
            selected.get("schema_version") == "review-config/v3" for selected in configs
        ) and any(
            selected.get("schema_version") != "review-config/v3"
            or _scope_record(selected)[0]["scope"]["kind"] != "CANDIDATE_READINESS"
            for selected in configs
        ):
            raise ValueError("E_REVIEW_AUTH_BINDING")
        validate_review_scope(
            cast(dict[str, object], context_a["config"]), json.loads(args.review_a.read_bytes())
        )
        validate_review_scope(
            cast(dict[str, object], context_b["config"]), json.loads(args.review_b.read_bytes())
        )
        result = aggregate_independent_reviews(
            json.loads(args.review_a.read_text()),
            json.loads(args.review_b.read_text()),
            json.loads(args.receipt_a.read_text()),
            json.loads(args.receipt_b.read_text()),
            authorization_a,
            authorization_b,
            public_key,
            config,
            expected_host_boot_id=Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
            expected_trust_epoch=epoch,
            external_seal=cast(dict[str, object], context_a["seal"]),
        )
    bootstrap_review_authority(authority, initialize_if_absent=False)
    _validate_consumed_authorization(authorization_a, authority)
    _validate_consumed_authorization(authorization_b, authority)
    private = serialization.load_pem_private_key(
        Path(cast(str, authority["private_key_path"])).read_bytes(), password=None
    )
    if not isinstance(private, Ed25519PrivateKey):
        raise ValueError("E_REVIEW_AUTH_BINDING")
    if context_a is None:
        result = aggregate_independent_reviews(
            json.loads(args.review_a.read_text()),
            json.loads(args.review_b.read_text()),
            json.loads(args.receipt_a.read_text()),
            json.loads(args.receipt_b.read_text()),
            authorization_a,
            authorization_b,
            private.public_key(),
            config,
            expected_host_boot_id=Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
            expected_trust_epoch=cast(int, authorization_a["trust_epoch"]),
        )
    else:
        recheck_review_context(context_a)
        assert context_b is not None
        recheck_review_context(context_b)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    if args.output != args.output.resolve():
        raise ValueError("E_REVIEW_AUTH_BINDING")
    with args.output.open("x") as output:
        output.write(json.dumps(result, sort_keys=True, separators=(",", ":")) + "\n")
    print(json.dumps(result, sort_keys=True))


if __name__ == "__main__":
    main()"""Copy a governed review pack into one fresh, independently sealable directory."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import shutil
import stat
import sys
from pathlib import Path
from typing import Any, NoReturn

RUNTIME_ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(RUNTIME_ROOT), str(RUNTIME_ROOT / "src")]

from tools.full_verifier_config import FullVerifierConfig, load_controller_config  # noqa: E402
from tools.retained_artifact_io import (  # noqa: E402
    RetainedArtifactIO,
    _canonical_relative,
    canonical_recorded_locator,
)

FORBIDDEN_OUTPUTS = {
    "GOVERNED_CONTENT_ROOT.json",
    "SELF_REVIEW_REPORT.md",
    "SELF_REVIEW_REPORT.json",
    "MANIFEST_SHA256.json",
}
EVIDENCE_ROOT = Path("/home/thenam176/betting-helper/authoring-evidence/hybrid-discovery-v6.3.6")

TASK_MANIFEST = "docs/tasks/task-manifest.v6.3.6.json"
OWNERSHIP = "docs/registries/artifact-ownership.v1.json"
DELIVERY = "docs/registries/delivery-map.v1.json"
COMMAND_IO = "docs/registries/command-io.v1.json"
CONFIG_COPY = "docs/configs/full-verifier-controller.v2.json"
UNION_MANIFEST = "evidence/retained-artifact-manifest.json"
UNION_ROOT = "evidence/retained"
ASSEMBLY_TASK = "V636-P09-T01"


def _fail() -> NoReturn:
    raise ValueError("E_REVIEW_PACK_ASSEMBLY")


def _regular_bytes(path: Path) -> bytes:
    if str(path) != canonical_recorded_locator(str(path)) or path != path.resolve(strict=True):
        _fail()
    info = path.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
        _fail()
    return path.read_bytes()


def _read_bytes(path: Path, artifacts: RetainedArtifactIO | None = None) -> bytes:
    if artifacts is None:
        return _regular_bytes(path)
    return artifacts.read_bytes(str(path), recorded_boundary=artifacts.recorded_boundary(str(path)))


def _document(path: Path, artifacts: RetainedArtifactIO | None = None) -> dict[str, Any]:
    value = json.loads(_read_bytes(path, artifacts))
    if not isinstance(value, dict):
        _fail()
    return value


def _bound_source_document(
    config: FullVerifierConfig,
    relative: str,
    artifacts: RetainedArtifactIO | None,
) -> dict[str, Any]:
    """Source declarations must match the independently qualified LIVE vendor."""
    raw = _read_bytes(config.governed_source_pack / relative, artifacts)
    vendor = config.current_checkout_root / "vendor/hybrid-discovery-v6.3.6"
    if raw != _regular_bytes(vendor / relative):
        _fail()
    value = json.loads(raw)
    if not isinstance(value, dict):
        _fail()
    return value


def _contract(
    config: FullVerifierConfig,
    artifacts: RetainedArtifactIO | None = None,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    tasks = _bound_source_document(config, TASK_MANIFEST, artifacts)["tasks"]
    ownership_rows = _bound_source_document(config, OWNERSHIP, artifacts)["entries"]
    owned = {row["path"]: row for row in ownership_rows}
    if len(owned) != len(ownership_rows):
        _fail()
    task = next(row for row in tasks if row["task_id"] == ASSEMBLY_TASK)
    command = next(
        row
        for row in _bound_source_document(config, COMMAND_IO, artifacts)["commands"]
        if row["command_id"] == "VERIFY_V636_P09_T01"
    )
    if not set(task["inputs"]).issubset(command["inputs"]) or set(task["outputs"]) != set(
        command["outputs"]
    ):
        _fail()
    for relative in (UNION_MANIFEST, UNION_ROOT):
        token = "pack/" + relative
        if token not in task["outputs"] or owned[token]["creation_owner"] != ASSEMBLY_TASK:
            _fail()
    delivery = _bound_source_document(config, DELIVERY, artifacts)
    if delivery.get("schema_version") != "delivery-map/v1":
        _fail()
    return task, owned, delivery


def _exports(config: FullVerifierConfig, delivery: dict[str, Any]) -> dict[str, str]:
    result: dict[str, str] = {}
    for entry in delivery["authoring_source_exports"]:
        if set(entry) != {"source", "destination", "owner"} or entry["owner"] != ASSEMBLY_TASK:
            _fail()
        relative = _relative(entry["source"])
        target = _relative(entry["destination"])
        if (
            target.parts[:2] != ("pack", "authoring-source")
            or relative.as_posix() != entry["source"]
            or target.as_posix() != entry["destination"]
            or target.relative_to("pack").as_posix() in result
        ):
            _fail()
        result[target.relative_to("pack").as_posix()] = str(
            config.governed_source_pack.parent / relative
        )
    return result


def _source_locators(
    config: FullVerifierConfig,
    artifacts: RetainedArtifactIO | None,
) -> list[str]:
    """Derive complete source membership independently of any supplied union."""
    task, owned, delivery = _contract(config, artifacts)
    separate = {token for token in task["outputs"] if token.startswith("pack/")} | {
        "pack/" + relative for relative in _exports(config, delivery)
    }
    required = {
        token
        for token, row in owned.items()
        if token.startswith("pack/")
        and row["materialization_required"] is True
        and token not in separate
    } | {token for token in task["inputs"] if token.startswith("pack/")}
    normative = _bound_source_document(
        config,
        "docs/registries/normative-source-map.v1.json",
        artifacts,
    )
    required.update(
        "pack/" + entry["plan_source"]
        for entry in [*normative["inherited_entries"], *normative["plan_entries"]]
    )
    if required & separate:
        _fail()
    locators = []
    for token in sorted(required):
        relative = _relative(token).relative_to("pack")
        if token not in owned or relative.name in FORBIDDEN_OUTPUTS:
            _fail()
        locators.append(str(config.governed_source_pack / relative))
    return locators


def _named_deliveries(
    config: FullVerifierConfig,
    source_locators: list[str],
    artifacts: RetainedArtifactIO | None = None,
) -> dict[str, str]:
    task, owned, delivery = _contract(config, artifacts)
    source = config.governed_source_pack
    named = {Path(locator).relative_to(source).as_posix(): locator for locator in source_locators}

    def add(relative: str, locator: str, *, exported: bool = False) -> None:
        if _relative(relative).as_posix() != relative:
            _fail()
        token = "pack/" + relative
        if not exported and (
            token not in task["outputs"] or owned[token]["creation_owner"] != ASSEMBLY_TASK
        ):
            _fail()
        if relative in named and named[relative] != locator:
            _fail()
        named[relative] = locator

    for relative, locator in _exports(config, delivery).items():
        add(relative, locator, exported=True)
    for row in _bound_source_document(
        config, "docs/registries/proof-coverage-matrix.v1.json", artifacts
    )["entries"]:
        if row["stage"] == "CANDIDATE":
            locator = canonical_recorded_locator(row["evidence_artifact"])
            if Path(locator).parent != config.evidence_root:
                _fail()
            add(row["sealed_evidence_path"], locator)
    for path in (
        config.candidate_command_evidence,
        config.proof_coverage_evidence,
        config.candidate_issuance_evidence,
        config.candidate_qualification_receipt,
    ):
        add("evidence/" + path.name, str(path))
    assert config.descendant_repository_receipt is not None
    add(
        "docs/receipts/descendant-repository-qualification-receipt.json",
        str(config.descendant_repository_receipt),
    )
    return named


def _retained_inputs(
    config: FullVerifierConfig,
    source_locators: list[str],
    artifacts: RetainedArtifactIO | None = None,
    *,
    snapshots: dict[Path, tuple[bytes, int]] | None = None,
) -> tuple[dict[str, tuple[Path, str, bytes]], dict[str, str]]:
    """Merge finite authenticated owner rows, never discover an evidence directory."""
    task, owned, delivery = _contract(config, artifacts)
    source = config.governed_source_pack
    if len(source_locators) != len(set(source_locators)) or set(source_locators) != set(
        _source_locators(config, artifacts)
    ):
        _fail()
    entries: dict[str, tuple[Path, str, bytes]] = {}

    def add(locator: str, boundary: str, context: RetainedArtifactIO | None = artifacts) -> None:
        locator, boundary = (
            canonical_recorded_locator(locator),
            canonical_recorded_locator(boundary),
        )
        if not Path(locator).is_relative_to(boundary) or locator == boundary:
            _fail()
        if context is None:
            physical, raw = Path(locator), _regular_bytes(Path(locator))
        else:
            physical = context.physical_path(locator, recorded_boundary=boundary)
            raw = context.read_bytes(locator, recorded_boundary=boundary)
        if snapshots is not None:
            snapshots[physical] = raw, stat.S_IMODE(physical.lstat().st_mode)
        prior = entries.get(locator)
        if prior is not None and (prior[1], prior[2]) != (boundary, raw):
            _fail()
        if prior is None:
            entries[locator] = physical, boundary, raw

    qualification = config.qualification_evidence
    assert qualification is not None
    for inventory in (
        qualification.full_repair_inventory,
        qualification.environment_qualification_inventory,
    ):
        manifest = _document(inventory, artifacts)
        # The union changes physical names, not the original owner's manifest
        # grammar. Validate that metadata even when its files use union paths.
        if (
            set(manifest) != {"schema_version", "recorded_boundaries", "files"}
            or manifest["schema_version"] != "retained-artifact-manifest/v1"
            or not isinstance(manifest["recorded_boundaries"], list)
            or not isinstance(manifest["files"], list)
        ):
            _fail()
        boundaries = [canonical_recorded_locator(item) for item in manifest["recorded_boundaries"]]
        if not boundaries or len(boundaries) != len(set(boundaries)):
            _fail()
        locators: set[str] = set()
        relatives: set[str] = set()
        for row in manifest["files"]:
            if not isinstance(row, dict) or set(row) != {
                "recorded_locator",
                "recorded_boundary",
                "copied_relative_path",
                "size_bytes",
                "sha256",
            }:
                _fail()
            locator = canonical_recorded_locator(row["recorded_locator"])
            relative = _canonical_relative(row["copied_relative_path"])
            if (
                locator in locators
                or relative in relatives
                or row["recorded_boundary"] not in boundaries
                or type(row["size_bytes"]) is not int
            ):
                _fail()
            locators.add(locator)
            relatives.add(relative)
        context = artifacts or RetainedArtifactIO.from_manifest(
            manifest, inventory.parent / "retained"
        )
        for row in manifest["files"]:
            add(row["recorded_locator"], row["recorded_boundary"], context)
            if (
                len(entries[row["recorded_locator"]][2]) != row["size_bytes"]
                or hashlib.sha256(entries[row["recorded_locator"]][2]).hexdigest() != row["sha256"]
            ):
                _fail()
        add(str(inventory), str(inventory.parent))
    for locator in source_locators:
        relative = Path(locator).relative_to(source).as_posix()
        if "pack/" + relative not in owned:
            _fail()
        add(locator, str(source))
    add(str(config.source_path), str(config.source_path.parent))
    for locator in _exports(config, delivery).values():
        add(locator, str(source.parent))
    named = _named_deliveries(config, source_locators, artifacts)
    required = {
        str(config.descendant_repository_receipt),
        *named.values(),
        *qualification.binding().values(),
        *(value for value in task["inputs"] if value.startswith("/")),
    }
    for locator in sorted(required):
        if locator in entries:
            if artifacts is None:
                # Required raw aggregates/config/evidence remain independent
                # inputs even when an owner also retained the same locator.
                add(locator, entries[locator][1], None)
            continue
        path = Path(locator)
        boundary = str(source) if path.is_relative_to(source) else str(path.parent)
        add(locator, boundary)
    if artifacts is not None and set(entries) != set(artifacts.recorded_locators()):
        _fail()
    from tools.qualify_descendant_repository import _validate_issuance

    _validate_issuance(config, artifacts)
    return entries, named


def _normative_descendant(
    config: FullVerifierConfig,
    receipt: dict[str, object],
    artifacts: RetainedArtifactIO | None,
) -> None:
    from tools.qualify_zero_parent_baseline import _normative_source_set

    source_map, source_root, count = _normative_source_set(
        config.governed_source_pack, artifacts=artifacts
    )
    if (
        receipt.get("normative_source_map_sha256"),
        receipt.get("normative_source_set_root"),
        receipt.get("normative_source_set_count"),
    ) != (source_map, source_root, int(count)):
        _fail()


def load_sealed_assembly_context(
    pack: Path,
    config_path: Path,
    recorded_config_locator: str,
    retained_manifest: Path,
    retained_root: Path,
) -> tuple[FullVerifierConfig, RetainedArtifactIO]:
    """Load the recorded config, authenticating the named source-owned deliveries."""
    try:
        if (
            pack != pack.resolve(strict=True)
            or config_path != pack / CONFIG_COPY
            or retained_manifest != pack / UNION_MANIFEST
            or retained_root != pack / UNION_ROOT
        ):
            _fail()
        artifacts = RetainedArtifactIO.from_manifest(
            json.loads(_regular_bytes(retained_manifest)), retained_root
        )
        recorded = canonical_recorded_locator(recorded_config_locator)
        physical = artifacts.physical_path(
            recorded, recorded_boundary=artifacts.recorded_boundary(recorded)
        )
        config = load_controller_config(
            physical, mode="SEALED", artifacts=artifacts, recorded_locator=recorded
        )
        if config.schema_version != "full-verifier-controller/v2" or _regular_bytes(
            config_path
        ) != _read_bytes(config.source_path, artifacts):
            _fail()
        from tools.build_candidate_qualification_receipt import (
            validate_candidate_qualification_receipt,
        )

        validate_candidate_qualification_receipt(
            config.current_checkout_root,
            config.candidate_command_evidence,
            _document(config.candidate_qualification_receipt, artifacts),
            config,
            artifacts=artifacts,
        )
        sources = _source_locators(config, artifacts)
        _entries, named = _retained_inputs(config, sources, artifacts)
        for relative, locator in named.items():
            if _regular_bytes(pack / relative) != _read_bytes(Path(locator), artifacts):
                _fail()
        return config, artifacts
    except (OSError, ValueError, KeyError, TypeError, StopIteration, AssertionError) as error:
        raise ValueError("E_REVIEW_PACK_ASSEMBLY") from error


def _current_assembly(
    source: Path,
    destination: Path,
    config: FullVerifierConfig,
    retained_manifest: Path,
    retained_root: Path,
) -> dict[str, object]:
    from tools.qualify_descendant_repository import verify_descendant_qualification_receipt
    from tools.run_environment_qualification import verify_environment_qualification_evidence
    from tools.run_full_repair_qualification import write_closed_inventory
    from tools.verify_full_repair_qualification import verify_full_repair_qualification

    owned_identity: tuple[int, int] | None = None
    try:
        if (
            config.schema_version != "full-verifier-controller/v2"
            or source != config.governed_source_pack
            or config.descendant_repository_receipt is None
            or config.qualification_evidence is None
            or not destination.is_absolute()
            or destination != destination.resolve()
            or retained_manifest != destination / UNION_MANIFEST
            or retained_root != destination / UNION_ROOT
        ):
            _fail()
        # The independent full/candidate/descendant chain precedes any output write.
        receipt = verify_descendant_qualification_receipt(
            config.current_checkout_root,
            config.descendant_repository_receipt,
            pack=source,
            config=config,
        )
        _normative_descendant(config, receipt, None)
        files = _walk(source, strict_directories=True)
        snapshots: dict[Path, tuple[bytes, int]] = {}
        entries, named = _retained_inputs(
            config, [str(path) for path in files], snapshots=snapshots
        )
        protected = {
            config.current_checkout_root,
            source.parent,
            config.evidence_root,
            config.external_authoring_tests.parent,
            config.uv_cache,
            config.pnpm_store,
            config.chrome_path.parent,
            *(Path(boundary) for _, boundary, _ in entries.values()),
            *(physical.parent for physical, _, _ in entries.values()),
            *(physical.parent for physical in snapshots),
        }
        if any(
            destination.is_relative_to(root.resolve()) or root.resolve().is_relative_to(destination)
            for root in protected
        ):
            _fail()
        try:
            destination.lstat()
        except FileNotFoundError:
            pass
        else:
            _fail()
        # Parents may preexist; require canonical existing ancestry before mkdir.
        if destination.parent != destination.parent.resolve(strict=True):
            _fail()
        destination.mkdir()
        info = destination.lstat()
        owned_identity = info.st_dev, info.st_ino

        def check_owned() -> None:
            current = destination.lstat()
            if (
                not stat.S_ISDIR(current.st_mode)
                or (current.st_dev, current.st_ino) != owned_identity
            ):
                _fail()

        for relative, locator in sorted(named.items()):
            check_owned()
            _copy(entries[locator][0], destination / _relative(relative))
        (destination / "evidence").mkdir(exist_ok=True)
        check_owned()
        write_closed_inventory(
            [
                (physical, locator, boundary)
                for locator, (physical, boundary, _raw) in sorted(entries.items())
            ],
            retained_manifest,
        )
        check_owned()
        copied_config, artifacts = load_sealed_assembly_context(
            destination,
            destination / CONFIG_COPY,
            str(config.source_path),
            retained_manifest,
            retained_root,
        )
        if copied_config != config:
            _fail()
        qualification = config.qualification_evidence

        def mapped(path: Path) -> Path:
            return artifacts.physical_path(
                str(path), recorded_boundary=artifacts.recorded_boundary(str(path))
            )

        full = verify_full_repair_qualification(
            mapped(qualification.full_repair_aggregate),
            mapped(qualification.full_repair_inventory),
            config,
            artifacts=artifacts,
        )
        environment = verify_environment_qualification_evidence(
            qualification.environment_qualification_aggregate,
            qualification.environment_qualification_inventory,
            config,
            artifacts=artifacts,
        )
        after = verify_descendant_qualification_receipt(
            config.current_checkout_root,
            config.descendant_repository_receipt,
            pack=source,
            config=config,
            artifacts=artifacts,
        )
        if after != receipt:
            _fail()
        _normative_descendant(config, after, artifacts)
        if files != _walk(source, strict_directories=True):
            _fail()
        for physical, snapshot in snapshots.items():
            if (_regular_bytes(physical), stat.S_IMODE(physical.lstat().st_mode)) != snapshot:
                _fail()
        load_sealed_assembly_context(
            destination,
            destination / CONFIG_COPY,
            str(config.source_path),
            retained_manifest,
            retained_root,
        )
        check_owned()
        return {
            "result": "PASS",
            "production_authority": "NONE",
            "file_count": len(named),
            "files": sorted(named),
            "retained_file_count": len(entries),
            "full_repair": full,
            "environment_qualification": environment,
        }
    except Exception as error:
        if owned_identity is not None:
            try:
                info = destination.lstat()
                if stat.S_ISDIR(info.st_mode) and (info.st_dev, info.st_ino) == owned_identity:
                    shutil.rmtree(destination)
            except OSError:
                pass
        raise ValueError("E_REVIEW_PACK_ASSEMBLY") from error


def _walk(root: Path, *, strict_directories: bool = False) -> list[Path]:
    if root.is_symlink() or not root.is_dir():
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")
    files: list[Path] = []
    for directory, directory_names, names in os.walk(root, followlinks=False):
        base = Path(directory)
        if base.is_symlink():
            raise ValueError("E_REVIEW_PACK_ASSEMBLY")
        if strict_directories and any((base / name).is_symlink() for name in directory_names):
            _fail()
        for name in names:
            source = base / name
            relative = source.relative_to(root)
            info = source.lstat()
            if (
                source.is_symlink()
                or not stat.S_ISREG(info.st_mode)
                or info.st_nlink != 1
                or any(part in {"", ".", ".."} for part in relative.parts)
            ):
                raise ValueError("E_REVIEW_PACK_ASSEMBLY")
            if relative.name in FORBIDDEN_OUTPUTS:
                raise ValueError("E_REVIEW_PACK_ASSEMBLY")
            files.append(source)
    return sorted(files, key=lambda path: path.relative_to(root).as_posix().encode())


def _relative(value: object) -> Path:
    if not isinstance(value, str):
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")
    path = Path(value)
    if path.is_absolute() or not path.parts or any(part in {"", ".", ".."} for part in path.parts):
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")
    return path


def _copy(source: Path, target: Path) -> None:
    info = source.lstat()
    if source.is_symlink() or not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists() or target.is_symlink():
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")
    shutil.copyfile(source, target, follow_symlinks=False)
    target.chmod(stat.S_IMODE(info.st_mode))
    if hashlib.sha256(source.read_bytes()).digest() != hashlib.sha256(target.read_bytes()).digest():
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")


def _copy_authoring_exports(source: Path, destination: Path) -> list[str]:
    mapping_path = source / "docs/registries/delivery-map.v1.json"
    if not mapping_path.exists():
        return []
    try:
        mapping = json.loads(mapping_path.read_text())
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError("E_REVIEW_PACK_ASSEMBLY") from error
    exports = mapping.get("authoring_source_exports") if isinstance(mapping, dict) else None
    if mapping.get("schema_version") != "delivery-map/v1" or not isinstance(exports, list):
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")
    copied: list[str] = []
    for entry in exports:
        if not isinstance(entry, dict) or set(entry) != {"source", "destination", "owner"}:
            raise ValueError("E_REVIEW_PACK_ASSEMBLY")
        source_relative = _relative(entry["source"])
        destination_relative = _relative(entry["destination"])
        if entry["owner"] != "V636-P09-T01" or destination_relative.parts[:2] != (
            "pack",
            "authoring-source",
        ):
            raise ValueError("E_REVIEW_PACK_ASSEMBLY")
        target_relative = Path(*destination_relative.parts[1:])
        _copy(source.parent / source_relative, destination / target_relative)
        copied.append(target_relative.as_posix())
    if len(copied) != len(set(copied)):
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")
    return copied


def _copy_candidate_evidence(source: Path, destination: Path) -> list[str]:
    matrix_path = source / "docs/registries/proof-coverage-matrix.v1.json"
    if not matrix_path.exists():
        return []
    matrix = json.loads(matrix_path.read_text())
    entries = matrix.get("entries") if isinstance(matrix, dict) else None
    if not isinstance(entries, list):
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")
    copied: list[str] = []
    for entry in entries:
        if not isinstance(entry, dict) or entry.get("stage") != "CANDIDATE":
            continue
        source_path = Path(str(entry.get("evidence_artifact")))
        target_relative = _relative(entry.get("sealed_evidence_path"))
        if source_path.parent != EVIDENCE_ROOT or target_relative.parts[:1] != ("evidence",):
            raise ValueError("E_REVIEW_PACK_ASSEMBLY")
        if target_relative.as_posix() in copied:
            continue
        _copy(source_path, destination / target_relative)
        copied.append(target_relative.as_posix())
    return copied


def _copy_sealed_review_sources(source: Path, destination: Path) -> list[str]:
    manifest_path = source / "docs/tasks/task-manifest.v6.3.6.json"
    if not manifest_path.exists():
        return []
    copied: list[str] = []
    authoring_root = source.resolve().parent
    bootstrap = authoring_root / "plan-input/bootstrap"
    for source_path in _walk(bootstrap):
        target_relative = Path("authoring-source/bootstrap") / source_path.relative_to(bootstrap)
        _copy(source_path, destination / target_relative)
        copied.append(target_relative.as_posix())
    manifest = json.loads(manifest_path.read_text())
    tasks = manifest.get("tasks") if isinstance(manifest, dict) else None
    if not isinstance(tasks, list):
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")
    roots = (
        (EVIDENCE_ROOT.resolve(), Path("evidence")),
        (authoring_root, Path("authoring-source/workspace")),
        (authoring_root.parent / "plan-input", Path("authoring-source/plan-input")),
    )
    for task in tasks:
        if not isinstance(task, dict):
            raise ValueError("E_REVIEW_PACK_ASSEMBLY")
        for value in task.get("exact_files", []):
            path = Path(str(value))
            if not path.is_absolute() or not path.is_file():
                continue
            match = next(
                ((root, target) for root, target in roots if path.is_relative_to(root)), None
            )
            if match is None:
                continue
            root, target = match
            target_relative = target / path.relative_to(root)
            target_path = destination / target_relative
            if target_path.exists():
                if (
                    hashlib.sha256(path.read_bytes()).digest()
                    != hashlib.sha256(target_path.read_bytes()).digest()
                ):
                    raise ValueError("E_REVIEW_PACK_ASSEMBLY")
                continue
            _copy(path, target_path)
            copied.append(target_relative.as_posix())
    return copied


def _prove_normative_source_set(pack: Path) -> None:
    from tools.qualify_zero_parent_baseline import _normative_source_set

    receipt_path = pack / "docs/receipts/repo0-baseline-receipt.json"
    try:
        receipt = json.loads(receipt_path.read_text())
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError("E_REVIEW_PACK_ASSEMBLY") from error
    if not isinstance(receipt, dict):
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")
    source_map, source_set, count = _normative_source_set(pack)
    if (
        receipt.get("schema_version") != "repo0-baseline-receipt/v2"
        or receipt.get("normative_source_map_sha256") != source_map
        or receipt.get("normative_source_set_root") != source_set
        or receipt.get("normative_source_set_count") != count
    ):
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")


def assemble_review_pack(
    source: Path,
    destination: Path,
    config: FullVerifierConfig | None = None,
    *,
    retained_manifest: Path | None = None,
    retained_root: Path | None = None,
) -> dict[str, object]:
    if config is not None or retained_manifest is not None or retained_root is not None:
        if (
            not isinstance(config, FullVerifierConfig)
            or retained_manifest is None
            or retained_root is None
        ):
            _fail()
        return _current_assembly(source, destination, config, retained_manifest, retained_root)
    _prove_normative_source_set(source)
    files = _walk(source)
    if destination.exists() or destination.is_symlink():
        raise ValueError("E_REVIEW_PACK_ASSEMBLY")
    destination.mkdir(parents=True)
    copied: list[str] = []
    try:
        for source_path in files:
            relative = source_path.relative_to(source)
            target = destination / relative
            _copy(source_path, target)
            copied.append(relative.as_posix())
        copied.extend(_copy_authoring_exports(source, destination))
        copied.extend(_copy_candidate_evidence(source, destination))
        copied.extend(_copy_sealed_review_sources(source, destination))
        _prove_normative_source_set(destination)
    except BaseException:
        shutil.rmtree(destination)
        raise
    return {"result": "PASS", "file_count": len(copied), "files": copied}


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--source", type=Path, required=True)
    parser.add_argument("--destination", type=Path, required=True)
    parser.add_argument("--config", type=Path)
    parser.add_argument("--retained-manifest", type=Path)
    parser.add_argument("--retained-root", type=Path)
    args = parser.parse_args()
    try:
        config = load_controller_config(args.config) if args.config is not None else None
        print(
            assemble_review_pack(
                args.source,
                args.destination,
                config,
                retained_manifest=args.retained_manifest,
                retained_root=args.retained_root,
            )
        )
    except (OSError, ValueError) as error:
        raise ValueError("E_REVIEW_PACK_ASSEMBLY") from error


if __name__ == "__main__":
    main()"""Create or verify the host-only review key and one-use state database."""
# ruff: noqa: E402
from __future__ import annotations

import argparse
import base64
import json
import os
import sqlite3
import stat
import sys
from hashlib import sha256
from pathlib import Path

RUNTIME_ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(RUNTIME_ROOT), str(RUNTIME_ROOT / "src")]

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

from moj_discovery.review_authorization import key_id


def _regular(path: Path) -> None:
    if path.is_symlink() or not path.is_file() or stat.S_ISLNK(path.lstat().st_mode):
        raise ValueError("E_REVIEW_AUTHORITY_CONFIG")


def _state(path: Path, key: str, epoch: int) -> None:
    if path.exists():
        _regular(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(path)
    try:
        connection.execute(
            "CREATE TABLE IF NOT EXISTS authority_state (key_id TEXT PRIMARY KEY, trust_epoch INTEGER NOT NULL)"
        )
        connection.execute(
            "CREATE TABLE IF NOT EXISTS consumed_serials (authority_key_id TEXT NOT NULL, one_use_serial TEXT NOT NULL, PRIMARY KEY (authority_key_id, one_use_serial))"
        )
        connection.execute("CREATE TABLE IF NOT EXISTS revocations (authorization_id TEXT PRIMARY KEY)")
        stored = connection.execute("SELECT key_id, trust_epoch FROM authority_state").fetchall()
        if not stored:
            connection.execute("INSERT INTO authority_state VALUES (?, ?)", (key, epoch))
        elif stored != [(key, epoch)]:
            raise ValueError("E_REVIEW_AUTHORITY_CONFIG")
        connection.commit()
    finally:
        connection.close()
    os.chmod(path, 0o600)


def bootstrap_review_authority(
    config: dict[str, object], *, initialize_if_absent: bool = False
) -> dict[str, object]:
    private_path = Path(str(config["private_key_path"]))
    public_path = Path(str(config["public_key_path"]))
    if (
        config.get("production_authority") != "NONE"
        or not private_path.is_absolute()
        or not public_path.is_absolute()
        or private_path.parent != public_path.parent
    ):
        raise ValueError("E_REVIEW_AUTHORITY_CONFIG")
    state_path = private_path.parent / "state.sqlite"
    present = (private_path.exists(), public_path.exists())
    if not all(present):
        if not initialize_if_absent or any(present):
            raise ValueError("E_REVIEW_AUTHORITY_ABSENT")
        private_path.parent.mkdir(parents=True, exist_ok=True)
        key = Ed25519PrivateKey.generate()
        private_path.write_bytes(
            key.private_bytes(
                serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()
            )
        )
        raw = key.public_key().public_bytes(serialization.Encoding.Raw, serialization.PublicFormat.Raw)
        public_path.write_text(
            json.dumps(
                {
                    "schema_version": "review-public-key/v1", "key_id": "key:ed25519:" + sha256(raw).hexdigest(),
                    "role": "HOST_REVIEW_AUTHORITY",
                    "public_key_b64url": base64.urlsafe_b64encode(raw).decode().rstrip("="), "trust_epoch": 0,
                }, sort_keys=True, separators=(",", ":")
            ) + "\n"
        )
    _regular(private_path)
    _regular(public_path)
    try:
        private = serialization.load_pem_private_key(private_path.read_bytes(), password=None)
        public = json.loads(public_path.read_text())
    except (TypeError, ValueError, json.JSONDecodeError) as error:
        raise ValueError("E_REVIEW_AUTHORITY_CONFIG") from error
    if not isinstance(private, Ed25519PrivateKey) or not isinstance(public, dict) or set(public) != {
        "schema_version", "key_id", "role", "public_key_b64url", "trust_epoch"
    }:
        raise ValueError("E_REVIEW_AUTHORITY_CONFIG")
    raw = private.public_key().public_bytes(serialization.Encoding.Raw, serialization.PublicFormat.Raw)
    expected = base64.urlsafe_b64encode(raw).decode().rstrip("=")
    epoch = public.get("trust_epoch")
    if (
        public.get("schema_version") != "review-public-key/v1"
        or public.get("role") != "HOST_REVIEW_AUTHORITY"
        or public.get("key_id") != key_id(private.public_key())
        or public.get("public_key_b64url") != expected
        or not isinstance(epoch, int)
        or isinstance(epoch, bool)
        or epoch < 0
    ):
        raise ValueError("E_REVIEW_AUTHORITY_CONFIG")
    os.chmod(private_path, int(str(config["private_key_mode"]), 8))
    os.chmod(public_path, int(str(config["public_key_mode"]), 8))
    _state(state_path, key_id(private.public_key()), epoch)
    return {"result": "PASS", "key_id": public["key_id"], "production_authority": "NONE"}


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", required=True, type=Path)
    parser.add_argument("--initialize-if-absent", action="store_true")
    args = parser.parse_args()
    print(json.dumps(bootstrap_review_authority(json.loads(args.config.read_text()), initialize_if_absent=args.initialize_if_absent), sort_keys=True))


if __name__ == "__main__":
    main()"""Bind passed candidate replay evidence to the exact source inventory."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import stat
import subprocess
import sys
import unicodedata
from pathlib import Path
from typing import TYPE_CHECKING, cast

if TYPE_CHECKING:
    from tools.retained_artifact_io import RetainedArtifactIO

RUNTIME_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(RUNTIME_ROOT))

from tools import run_command_registry  # noqa: E402
from tools.full_verifier_config import FullVerifierConfig, load_controller_config  # noqa: E402
from tools.verify_proof_coverage import verify_proof_coverage_matrix  # noqa: E402

EVIDENCE_ROOT = Path("/home/thenam176/betting-helper/authoring-evidence/hybrid-discovery-v6.3.6")
EXCLUDED_DIRECTORIES = {
    ".git", ".venv", ".mypy_cache", ".pytest_cache", ".ruff_cache", "__pycache__", "node_modules",
}
EXCLUDED_FILES = {".coverage"}


def _canonical(value: object) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":")).encode()


def _git(root: Path, *args: str) -> bytes:
    git = shutil.which("git")
    if git is None:
        raise ValueError("E_CANDIDATE_RECEIPT")
    completed = subprocess.run(  # noqa: S603 - fixed read-only Git operation.
        [git, "-C", str(root), *args],
        capture_output=True,
        check=False,
        timeout=30,
    )
    if completed.returncode != 0:
        raise ValueError("E_CANDIDATE_RECEIPT")
    return completed.stdout


def _inventory(root: Path, generated_outputs: object = None) -> dict[str, object]:
    if root.is_symlink() or not root.is_dir():
        raise ValueError("E_CANDIDATE_RECEIPT")
    if _git(root, "rev-parse", "--show-toplevel").decode().strip() != str(root.resolve()):
        raise ValueError("E_CANDIDATE_RECEIPT")
    ownership = root / "vendor/hybrid-discovery-v6.3.6/docs/registries/artifact-ownership.v1.json"
    declared_generated = (
        run_command_registry._declared_compiler_outputs(root) if ownership.is_file() else set()
    )
    changed = {
        item.decode()
        for command in (
            ("diff", "--name-only", "-z"),
            ("diff", "--cached", "--name-only", "-z"),
            ("ls-files", "--others", "--exclude-standard", "-z"),
        )
        for item in _git(root, *command).split(b"\0")
        if item
    }
    if not changed.issubset(declared_generated):
        raise ValueError("E_CANDIDATE_RECEIPT")
    head = _git(root, "rev-parse", "HEAD").decode().strip()
    tree = _git(root, "rev-parse", "HEAD^{tree}").decode().strip()
    if re.fullmatch(r"[0-9a-f]{40}", head) is None or re.fullmatch(r"[0-9a-f]{40}", tree) is None:
        raise ValueError("E_CANDIDATE_RECEIPT")
    entries: list[dict[str, str]] = []
    raw = _git(root, "ls-tree", "-r", "-z", "--full-tree", "HEAD")
    for item in raw.split(b"\0"):
        if not item:
            continue
        try:
            metadata, encoded_path = item.split(b"\t", 1)
            mode, kind, object_id = metadata.decode().split(" ")
            relative = encoded_path.decode("utf-8")
        except (UnicodeError, ValueError) as error:
            raise ValueError("E_CANDIDATE_RECEIPT") from error
        if relative in declared_generated:
            continue
        if kind != "blob" or mode not in {"100644", "100755"}:
            raise ValueError("E_CANDIDATE_RECEIPT")
        contents = (root / relative).read_bytes()
        if (
            hashlib.sha1(  # noqa: S324 - Git object identity is SHA-1 by protocol.
                f"blob {len(contents)}\0".encode() + contents,
                usedforsecurity=False,
            ).hexdigest()
            != object_id
        ):
            raise ValueError("E_CANDIDATE_RECEIPT")
        entries.append(
            {
                "path": relative,
                "sha256": hashlib.sha256(contents).hexdigest(),
                "size": str(len(contents)),
                "mode": mode,
            }
        )
    inventory: dict[str, object] = {"head": head, "tree": tree, "entries": entries}
    if declared_generated:
        inventory["source_entries"] = inventory.pop("entries")
        inventory["generated_outputs"] = generated_outputs
    return inventory


def _read_bytes(path: Path, artifacts: RetainedArtifactIO | None = None) -> bytes:
    if artifacts is None:
        return path.read_bytes()
    recorded = str(path)
    return artifacts.read_bytes(recorded, recorded_boundary=artifacts.recorded_boundary(recorded))


def _read_evidence(path: Path, artifacts: RetainedArtifactIO | None = None) -> dict[str, object]:
    try:
        value = json.loads(_read_bytes(path, artifacts))
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError("E_CANDIDATE_RECEIPT") from error
    if not isinstance(value, dict):
        raise ValueError("E_CANDIDATE_RECEIPT")
    return cast(dict[str, object], value)


def _historical_inventory(root: Path) -> list[dict[str, str]]:
    """Preserve the v1 whole-filesystem inventory, including generated bytes."""
    if root.is_symlink() or not root.is_dir():
        raise ValueError("E_CANDIDATE_RECEIPT")
    entries: list[dict[str, str]] = []
    for directory, names, files in os.walk(root, followlinks=False):
        base = Path(directory)
        relative_base = base.relative_to(root)
        names[:] = [name for name in names if name not in EXCLUDED_DIRECTORIES]
        for name in sorted(files, key=lambda item: item.encode()):
            path = base / name
            relative = path.relative_to(root).as_posix()
            info = path.lstat()
            if name in EXCLUDED_FILES:
                continue
            if (
                path.is_symlink() or not stat.S_ISREG(info.st_mode) or info.st_nlink != 1
                or not relative or relative.startswith("/")
                or unicodedata.normalize("NFC", relative) != relative
                or any(part in {"", ".", ".."} for part in relative_base.parts)
            ):
                raise ValueError("E_CANDIDATE_RECEIPT")
            contents = path.read_bytes()
            entries.append({
                "path": relative, "sha256": hashlib.sha256(contents).hexdigest(),
                "size": str(len(contents)), "mode": "100755" if info.st_mode & 0o111 else "100644",
            })
    return sorted(entries, key=lambda item: item["path"].encode())


def _historical_receipt(source: Path, command_evidence: Path) -> dict[str, object]:
    """Historical descriptor validation never qualifies a descendant source."""
    evidence = _read_evidence(command_evidence)
    if (
        evidence.get("schema_version") != "candidate-command-results/v1"
        or (source / "vendor/hybrid-discovery-v6.3.6/docs/configs/"
            "full-verifier-controller.v2.json").exists()
        or (source / "review-config/review-a.v2.json").exists()
    ):
        raise ValueError("E_CANDIDATE_RECEIPT")
    try:
        registry = run_command_registry.validate_registry(source / "task-command-registry.json")
        expected = run_command_registry.build_candidate_command_results(
            registry, evidence.get("results")
        )
        if any(
            "full-verifier-controller.v2.json" in token
            or "qualify_descendant_repository.py" in token
            for row in cast(list[dict[str, object]], registry["commands"])
            for token in cast(list[str], row["argv"])
        ) or evidence != expected:
            raise ValueError("E_CANDIDATE_RECEIPT")
        inventory = _historical_inventory(source)
    except (OSError, ValueError) as error:
        raise ValueError("E_CANDIDATE_RECEIPT") from error
    return {
        "schema_version": "candidate-qualification-receipt/v1", "production_authority": "NONE",
        "command_result_root": hashlib.sha256(
            b"HD636/CANDIDATE-COMMAND-RESULTS/v1\0" + _canonical(evidence)
        ).hexdigest(),
        "command_evidence_sha256": hashlib.sha256(command_evidence.read_bytes()).hexdigest(),
        "command_ids": [row["command_id"]
                        for row in cast(list[dict[str, object]], evidence["results"])],
        "inventory": inventory,
    }


def _validate_command_evidence(
    source: Path, evidence: dict[str, object], config: FullVerifierConfig
) -> None:
    if evidence.get("schema_version") != "candidate-command-results/v3":
        raise ValueError("E_CANDIDATE_RECEIPT")
    try:
        run_command_registry.validate_external_authoring_result(
            evidence.get("external_authoring_result"), config
        )
        registry = run_command_registry.validate_registry(source / "task-command-registry.json")
        expected = run_command_registry.build_candidate_command_results(
            registry,
            evidence.get("results"),
            config,
            evidence.get("generated_outputs"),
        )
    except ValueError as error:
        raise ValueError("E_CANDIDATE_RECEIPT") from error
    expected["schema_version"] = "candidate-command-results/v3"
    expected["external_authoring_result"] = evidence["external_authoring_result"]
    if evidence != expected or evidence.get(
        "generated_outputs"
    ) != run_command_registry.collect_generated_outputs(source):
        raise ValueError("E_CANDIDATE_RECEIPT")


def _validate_proof_coverage(
    config: FullVerifierConfig, artifacts: RetainedArtifactIO | None = None
) -> dict[str, object]:
    proof = _read_evidence(config.proof_coverage_evidence, artifacts)
    evidence = proof.get("evidence")
    if (
        proof.get("schema_version") != "proof-coverage-result/v2"
        or proof.get("result") != "PASS"
        or proof.get("production_authority") != "NONE"
        or proof.get("control_count") != 18
        or proof.get("controller_binding") != config.binding()
        or not isinstance(evidence, list)
    ):
        raise ValueError("E_CANDIDATE_RECEIPT")
    try:
        source = config.governed_source_pack / "docs/registries/proof-coverage-matrix.v1.json"
        matrix = _read_evidence(source, artifacts)
        expected = verify_proof_coverage_matrix(
            matrix, config.evidence_root, "CANDIDATE", config, artifacts=artifacts
        )
    except (OSError, ValueError, json.JSONDecodeError) as error:
        raise ValueError("E_CANDIDATE_RECEIPT") from error
    if proof != expected or (artifacts is None and not source.is_file()):
        raise ValueError("E_CANDIDATE_RECEIPT")
    return proof


def _proof_coverage_sha256(
    config: FullVerifierConfig, artifacts: RetainedArtifactIO | None = None
) -> str:
    return hashlib.sha256(_read_bytes(config.proof_coverage_evidence, artifacts)).hexdigest()


def validate_candidate_qualification_receipt(
    source: Path,
    command_evidence: Path,
    receipt: dict[str, object],
    config: FullVerifierConfig | None = None,
    *,
    artifacts: RetainedArtifactIO | None = None,
) -> None:
    if receipt.get("schema_version") == "candidate-qualification-receipt/v1":
        if config is not None or artifacts is not None or receipt != _historical_receipt(
            source, command_evidence
        ):
            raise ValueError("E_CANDIDATE_RECEIPT")
        return
    evidence = _read_evidence(command_evidence, artifacts)
    if config is None:
        raise ValueError("E_CANDIDATE_RECEIPT")
    _validate_command_evidence(source, evidence, config)
    if artifacts is None:
        _validate_proof_coverage(config)
    else:
        _validate_proof_coverage(config, artifacts)
    inventory = _inventory(source, evidence.get("generated_outputs"))
    required = {
        "schema_version",
        "production_authority",
        "command_result_root",
        "command_evidence_sha256",
        "command_ids",
        "inventory",
        "controller_binding",
        "proof_coverage_sha256",
    }
    if (
        set(receipt) != required
        or receipt.get("schema_version") != "candidate-qualification-receipt/v2"
        or receipt.get("production_authority") != "NONE"
        or receipt.get("command_result_root")
        != hashlib.sha256(
            b"HD636/CANDIDATE-COMMAND-RESULTS/v2\0" + _canonical(evidence)
        ).hexdigest()
        or receipt.get("command_evidence_sha256")
        != hashlib.sha256(_read_bytes(command_evidence, artifacts)).hexdigest()
        or receipt.get("command_ids")
        != [entry["command_id"] for entry in cast(list[dict[str, object]], evidence["results"])]
        or receipt.get("inventory") != inventory
        or config is None
        or receipt.get("controller_binding") != config.binding()
        or receipt.get("proof_coverage_sha256")
        != (
            _proof_coverage_sha256(config)
            if artifacts is None
            else _proof_coverage_sha256(config, artifacts)
        )
    ):
        raise ValueError("E_CANDIDATE_RECEIPT")


def build_candidate_qualification_receipt(
    source: Path,
    command_evidence: Path,
    output: Path,
    config: FullVerifierConfig | None = None,
) -> dict[str, object]:
    if config is None:
        historical = _historical_receipt(source, command_evidence)
        validate_candidate_qualification_receipt(source, command_evidence, historical)
        output.parent.mkdir(parents=True, exist_ok=True)
        output.write_text(json.dumps(historical, sort_keys=True, separators=(",", ":")) + "\n")
        return historical
    evidence = _read_evidence(command_evidence)
    _validate_command_evidence(source, evidence, config)
    _validate_proof_coverage(config)
    results = cast(list[dict[str, object]], evidence["results"])
    record: dict[str, object] = {
        "schema_version": "candidate-qualification-receipt/v2",
        "production_authority": "NONE",
        "command_result_root": hashlib.sha256(
            b"HD636/CANDIDATE-COMMAND-RESULTS/v2\0" + _canonical(evidence)
        ).hexdigest(),
        "command_evidence_sha256": hashlib.sha256(command_evidence.read_bytes()).hexdigest(),
        "command_ids": [item["command_id"] for item in results],
        "inventory": _inventory(source, evidence.get("generated_outputs")),
        "controller_binding": config.binding(),
        "proof_coverage_sha256": _proof_coverage_sha256(config),
    }
    validate_candidate_qualification_receipt(source, command_evidence, record, config)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(record, sort_keys=True, separators=(",", ":")) + "\n")
    return record


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", type=Path)
    parser.add_argument("--source", default=RUNTIME_ROOT, type=Path)
    parser.add_argument(
        "--command-evidence", default=EVIDENCE_ROOT / "V636-P07-T01.json", type=Path
    )
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    config = load_controller_config(args.config) if args.config else None
    result = build_candidate_qualification_receipt(
        args.source, args.command_evidence, args.output, config
    )
    print(json.dumps(result, sort_keys=True))


if __name__ == "__main__":
    main()/* Generate CSP-compatible validators from the pinned local schema registry. */
const fs = require('node:fs');
const path = require('node:path');
const {createRequire} = require('node:module');
const root = path.resolve(__dirname, '..');
const localRequire = createRequire(path.join(root, 'extension/package.json'));
const Ajv = localRequire('ajv/dist/2020').default;
const addFormats = localRequire('ajv-formats');
const standalone = localRequire('ajv/dist/standalone').default;
const ajv = new Ajv({allErrors: true, strict: false, code: {source: true, esm: true}});
addFormats(ajv);
for (const directory of ['vendor/hybrid-discovery-v6.3.6/schemas', 'contracts/offline_slice/v1']) {
  for (const name of fs.readdirSync(path.join(root, directory)).filter(n => n.endsWith('.schema.json'))) {
    ajv.addSchema(JSON.parse(fs.readFileSync(path.join(root, directory, name), 'utf8')));
  }
}
let code = standalone(ajv, {
  validateRaw: 'urn:hybrid-discovery:v6.2:raw-observation:v1',
  validateFrame: 'urn:betting-helper:offline-slice:frame:v1',
  validateContext: 'urn:betting-helper:offline-slice:context:v1',
});
// Standalone Ajv references a few pinned CommonJS runtime helpers. Preserve their
// implementation in static closures so extension CSP needs neither eval nor Node.
const modules = new Map();
const declarations = [];
function embed(name, importer = localRequire) {
  const filename = importer.resolve(name);
  if (modules.has(filename)) return modules.get(filename);
  const identifier = '__runtime' + modules.size;
  modules.set(filename, identifier);
  let source = fs.readFileSync(filename, 'utf8');
  const relativeRequire = createRequire(filename);
  source = source.replace(/require\((["'])([^"']+)\1\)/g, (_all, _quote, specifier) => embed(specifier, relativeRequire));
  if (/\brequire\s*\(/.test(source)) throw new Error('E_OFFLINE_DYNAMIC_RUNTIME_IMPORT');
  declarations.push(`const ${identifier}=(()=>{const exports={};const module={exports};\n${source}\nreturn module.exports;})();`);
  return identifier;
}
code = code.replace(/require\((["'])([^"']+)\1\)/g, (_all, _quote, name) => embed(name));
if (/\brequire\s*\(/.test(code)) throw new Error('E_OFFLINE_DYNAMIC_VALIDATOR_IMPORT');
const output = process.argv[2];
if (!output) throw new Error('E_OFFLINE_VALIDATOR_OUTPUT');
fs.mkdirSync(path.dirname(output), {recursive: true});
fs.writeFileSync(output, '// Generated by tools/build_offline_validators.cjs; do not edit.\n' + declarations.join('\n') + '\n' + code);# ruff: noqa: E402
from __future__ import annotations

import argparse
import hashlib
import json
import sys
from pathlib import Path
from typing import TYPE_CHECKING, Any, cast

if TYPE_CHECKING:
    from tools.full_verifier_config import FullVerifierConfig
    from tools.retained_artifact_io import RetainedArtifactIO


def _sha256(path: Path) -> str:
    if path.is_symlink() or not path.is_file():
        raise ValueError("E_SELF_REVIEW_BINDING")
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _build_legacy_self_review(
    governed_root: Path, repo0_receipt: Path, output_dir: Path
) -> dict[str, object]:
    root = json.loads(governed_root.read_text())
    receipt = json.loads(repo0_receipt.read_text())
    if not isinstance(root, dict) or not isinstance(receipt, dict):
        raise ValueError("E_SELF_REVIEW_BINDING")
    task_manifest = output_dir / "docs/tasks/task-manifest.v6.3.6.json"
    if (
        root.get("algorithm") != "HD636-GOVERNED-ROOT-SHA256-v1"
        or root.get("schema_version") != "governed-content-root/v1"
        or not isinstance(root.get("root_sha256"), str)
        or set(receipt)
        != {
            "schema_version",
            "production_authority",
            "baseline_commit",
            "baseline_tree",
            "baseline_file_root_sha256",
            "candidate_qualification_sha256",
            "candidate_command_evidence_sha256",
            "command_result_root",
            "baseline_registry_sha256",
            "toolchain_versions",
            "lockfile_hashes",
            "vendor_root_sha256",
            "normative_source_map_sha256",
            "normative_source_set_root",
            "normative_source_set_count",
        }
        or receipt.get("schema_version") != "repo0-baseline-receipt/v2"
        or receipt.get("production_authority") != "NONE"
    ):
        raise ValueError("E_SELF_REVIEW_BINDING")
    candidate = receipt.get("candidate_qualification_sha256")
    command_root = receipt.get("command_result_root")
    governed = root.get("root_sha256")
    if not all(
        isinstance(value, str) and len(value) == 64 for value in (candidate, command_root, governed)
    ):
        raise ValueError("E_SELF_REVIEW_BINDING")
    record: dict[str, object] = {
        "schema_version": "runtime-self-review/v1",
        "governed_content_root": governed,
        "repo0_receipt_sha256": _sha256(repo0_receipt),
        "candidate_qualification_sha256": candidate,
        "task_manifest_sha256": _sha256(task_manifest),
        "command_result_root": command_root,
        "checks": [{"check_id": "NO_FUTURE_SEAL_IDENTITY", "result": "PASS"}],
        "authority_granted": "NONE",
    }
    if set(record) != {
        "schema_version",
        "governed_content_root",
        "repo0_receipt_sha256",
        "candidate_qualification_sha256",
        "task_manifest_sha256",
        "command_result_root",
        "checks",
        "authority_granted",
    }:
        raise ValueError("E_SELF_REVIEW_BINDING")
    output_dir.joinpath("SELF_REVIEW_REPORT.json").write_text(
        json.dumps(cast(Any, record), sort_keys=True, separators=(",", ":")) + "\n"
    )
    output_dir.joinpath("SELF_REVIEW_REPORT.md").write_text(
        "# Runtime self-review\n\n"
        f"Governed content root: `{governed}`.\n\n"
        "Authority granted: NONE.\n"
    )
    return record


def build_runtime_self_review(
    governed_root: Path,
    repository_receipt: Path,
    output_dir: Path,
    *,
    config: FullVerifierConfig | None = None,
    artifacts: RetainedArtifactIO | None = None,
) -> dict[str, object]:
    try:
        receipt = json.loads(repository_receipt.read_bytes())
        if receipt.get("schema_version") == "repo0-baseline-receipt/v2":
            if config is not None or artifacts is not None:
                raise ValueError("E_SELF_REVIEW_BINDING")
            return _build_legacy_self_review(governed_root, repository_receipt, output_dir)
        if (
            receipt.get("schema_version") != "descendant-repository-qualification-receipt/v1"
            or config is None
            or artifacts is None
            or governed_root != output_dir / "GOVERNED_CONTENT_ROOT.json"
        ):
            raise ValueError("E_SELF_REVIEW_BINDING")
        from tools.seal_review_pack import _descendant_self_review, _self_review_bytes

        record = _descendant_self_review(output_dir, repository_receipt, config, artifacts)
        review, markdown = _self_review_bytes(record)
        (output_dir / "SELF_REVIEW_REPORT.json").write_bytes(review)
        (output_dir / "SELF_REVIEW_REPORT.md").write_bytes(markdown)
        return record
    except (OSError, ValueError, KeyError, TypeError, AttributeError) as error:
        raise ValueError("E_SELF_REVIEW_BINDING") from error


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--input", type=Path)
    parser.add_argument("--output", type=Path)
    parser.add_argument("--governed-root", type=Path)
    receipts = parser.add_mutually_exclusive_group()
    receipts.add_argument("--repo0-receipt", type=Path)
    receipts.add_argument("--repository-receipt", type=Path)
    parser.add_argument("--output-dir", type=Path)
    parser.add_argument("--config", type=Path)
    parser.add_argument("--recorded-config")
    parser.add_argument("--retained-manifest", type=Path)
    parser.add_argument("--retained-root", type=Path)
    args = parser.parse_args()
    context = (args.config, args.recorded_config, args.retained_manifest, args.retained_root)
    if (args.input is not None or args.output is not None) and any(
        value is not None
        for value in (
            args.governed_root,
            args.repo0_receipt,
            args.repository_receipt,
            args.output_dir,
            *context,
        )
    ):
        parser.error("provide exactly one self-review mode")
    config, artifacts = None, None
