import json
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT), str(ROOT / "src")]
from moj_discovery.live_config import load_live_config
from moj_discovery.providers.poll_budget import PollSegment, estimate_requests
from moj_discovery.secrets_local import controlling_tty
from tools.run_with_api_football_key import SafeParser


def main(argv: list[str] | None = None) -> int:
    try:
        parser = SafeParser(description=__doc__, allow_abbrev=False)
        parser.add_argument("--output", type=Path, default=Path("config/live.local.json"))
        parser.add_argument("--platform", choices=("WINDOWS_CHROME_WSL2", "LINUX_CHROME"))
        parser.add_argument("--league", type=int)
        parser.add_argument("--season", type=int)
        parser.add_argument("--fixtures")
        parser.add_argument("--lookup-only", action="store_true")
        parser.add_argument("--max-matches", type=int, choices=(1, 3, 5), default=1)
        parser.add_argument("--minutes", type=int, default=120)
        parser.add_argument("--requests", type=int, default=600)
        parser.add_argument("--daily-cap", type=int, default=6000)
        parser.add_argument("--minute-cap", type=int, default=6)
        parser.add_argument("--replace", action="store_true")
        args = parser.parse_args(argv)
        if args.lookup_only:
            if args.fixtures:
                raise ValueError()
            args.fixtures = ""
        if any(
            getattr(args, name) is None for name in ("platform", "league", "season", "fixtures")
        ):
            with controlling_tty() as terminal:
                for name in ("platform", "league", "season", "fixtures"):
                    if getattr(args, name) is None:
                        terminal.write(
                            name
                            + (
                                " (WINDOWS_CHROME_WSL2 / LINUX_CHROME)"
                                if name == "platform"
                                else " (nonsecret)"
                            )
                            + ": "
                        )
                        terminal.flush()
                        raw = terminal.readline(257).strip()
                        setattr(args, name, int(raw) if name in {"league", "season"} else raw)
        output = args.output if args.output.is_absolute() else ROOT / args.output
        if output != ROOT / "config/live.local.json" or any(
            p.is_symlink() for p in (output, *output.parents)
        ):
            raise ValueError()
        if output.exists() and not args.replace:
            raise ValueError()
        value = json.loads((ROOT / "config/live-batched.example.json").read_text())
        fixtures = [] if args.lookup_only else [int(v) for v in args.fixtures.split(",")]
        if len(set(fixtures)) != len(fixtures) or (not fixtures and not args.lookup_only):
            raise ValueError()
        value["provider"].update(
            league_id=args.league,
            season=args.season,
            fixture_ids=sorted(fixtures),
            max_requests_per_run=args.requests,
            daily_soft_cap=args.daily_cap,
            max_requests_per_minute=args.minute_cap,
        )
        value["runtime"].update(
            platform=args.platform, max_matches=args.max_matches, max_run_minutes=args.minutes
        )
        estimate = (
            estimate_requests([], setup=2, confirmations=0)
            if args.lookup_only
            else estimate_requests([PollSegment(0, args.minutes * 60, 15)] * len(fixtures))
        )
        # This is an upper estimate at the live cadence, not measured provider latency.
        if estimate.with_reserve > args.requests:
            raise ValueError()
        temporary = output.with_name("live.local.json.pending")
        fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        try:
            with os.fdopen(fd, "w") as handle:
                json.dump(value, handle, indent=2)
                handle.write("\n")
                handle.flush()
                os.fsync(handle.fileno())
            load_live_config(temporary)
            if args.replace:
                os.replace(temporary, output)
            else:
                os.link(temporary, output)
                temporary.unlink()
        except Exception:
            # Only this invocation's unpublished temporary file is removed.
            temporary.unlink(missing_ok=True)
            raise
        print("CONFIG_CREATED: DISABLED")
        print("ESTIMATED_ATTEMPTS_WITH_RESERVE: " + str(estimate.with_reserve))
        print("MODEL_ENABLED: false\nMONEY_READY: NO")
        return 0
    except Exception:
        print("CONFIG_NOT_CREATED: INVALID_OR_EXISTING_LOCAL_CONFIG")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())"""Create the one-commit, no-remote delivery repository."""
from __future__ import annotations

import argparse
import json
import subprocess
from pathlib import Path


def _git(root: Path, *arguments: str) -> str:
    environment = {
        "GIT_AUTHOR_EMAIL": "hybrid-discovery@localhost",
        "GIT_AUTHOR_NAME": "Hybrid Discovery",
        "GIT_COMMITTER_EMAIL": "hybrid-discovery@localhost",
        "GIT_COMMITTER_NAME": "Hybrid Discovery",
        "GIT_CONFIG_NOSYSTEM": "1",
        "GIT_TERMINAL_PROMPT": "0",
        "HOME": str(root),
        "LANG": "C.UTF-8",
        "LC_ALL": "C.UTF-8",
        "PATH": "/usr/bin:/bin",
    }
    result = subprocess.run(  # noqa: S603 - fixed Git executable and argv
        ["/usr/bin/git", "-C", str(root), *arguments],
        capture_output=True,
        env=environment,
        text=True,
    )
    if result.returncode != 0:
        raise ValueError("E_ZERO_PARENT_REPOSITORY")
    return result.stdout.strip()


def create_zero_parent_repository(root: Path) -> dict[str, object]:
    if root.is_symlink() or not root.is_dir() or (root / ".git").exists():
        raise ValueError("E_ZERO_PARENT_REPOSITORY")
    source_paths = sorted(
        path.relative_to(root).as_posix()
        for path in root.rglob("*")
        if path.is_file() and not path.is_symlink()
    )
    if not source_paths or any(path.is_symlink() for path in root.rglob("*")):
        raise ValueError("E_ZERO_PARENT_REPOSITORY")
    _git(root, "init", "--initial-branch=main")
    _git(root, "add", "--force", "--", *source_paths)
    if _git(root, "ls-files").splitlines() != source_paths:
        raise ValueError("E_ZERO_PARENT_REPOSITORY")
    if not _git(root, "status", "--porcelain"):
        raise ValueError("E_ZERO_PARENT_REPOSITORY")
    _git(root, "commit", "--no-gpg-sign", "-m", "Hybrid Discovery v6.3.6 baseline")
    head = _git(root, "rev-parse", "HEAD")
    roots = _git(root, "rev-list", "--max-parents=0", "HEAD").splitlines()
    commits = _git(root, "rev-list", "--count", "HEAD")
    if (
        roots != [head]
        or commits != "1"
        or _git(root, "remote")
        or _git(root, "status", "--porcelain")
    ):
        raise ValueError("E_ZERO_PARENT_REPOSITORY")
    return {"result": "PASS", "commit": head}


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", required=True, type=Path)
    args = parser.parse_args()
    print(json.dumps(create_zero_parent_repository(args.root), sort_keys=True))


if __name__ == "__main__":
    main()"""Owned disposable destruction process. No oracle or expected state is accepted."""

from __future__ import annotations

import argparse
import json
import os
import signal
import sys
from contextlib import closing
from pathlib import Path
from time import monotonic, sleep
from typing import Any

if __package__ in {None, ""}:
    root = Path(__file__).resolve().parents[1]
    sys.path[:0] = [str(root / "src"), str(root)]

from moj_discovery.store import RunStore  # noqa: E402
from tools.destruction_support import (  # noqa: E402
    consumption,
    delete_backend,
    immutable_json,
    insert_consumption,
    inventory,
    owned_case,
    persist_intent,
    prepare_backend,
    read_actual,
    validate_consumed,
    validate_external,
    validate_plan,
    worker_read,
    write_proof,
)


def execute(case: Path, config: dict[str, Any], *, recover: bool) -> None:
    run_id = config["identity"]["run_id"]
    database = owned_case(case, run_id)
    plan = json.loads((case / "precommit.json").read_text())
    boundary = config["identity"]["checkpoint_id"]

    def checkpoint(name: str) -> None:
        if not recover and name == boundary:
            immutable_json(case / "checkpoint.json", {**config["identity"], "pid": os.getpid()})
            while True:
                signal.pause()

    validate_plan(plan)
    checkpoint("destroy_01_before_authority")
    if recover and boundary == "destroy_01_before_authority":
        return
    if not recover:
        actual = read_actual(case, config)
        if inventory(actual) != plan["export"]["inventory"]:
            raise ValueError("E_DESTRUCTION_INVENTORY_HASH")
        with closing(RunStore(database).connect()) as connection, connection:
            insert_consumption(connection, consumption(plan))
    validate_consumed(case, plan)
    if database.exists():
        with closing(RunStore(database).connect()) as connection:
            committed = dict(
                connection.execute("SELECT * FROM authorization_consumptions").fetchone()
            )
        immutable_json(case / "consumed-external.json", committed)
    checkpoint("destroy_01a_after_consumption_before_intent")
    persist_intent(case, plan)
    checkpoint("destroy_02_after_intent_before_deletion")
    if boundary == "destroy_04_after_backend_deletion":
        delete_backend(case, plan)
        checkpoint("destroy_04_after_backend_deletion")
        validate_external(case, plan)
        worker_read(config, "destruction-delete")
    else:
        validate_external(case, plan)
        worker_read(config, "destruction-delete")
        checkpoint("destroy_03_after_extension_deletion")
        delete_backend(case, plan)
    checkpoint("destroy_05_after_both_deletions_before_proof")
    write_proof(case, config, plan)
    checkpoint("destroy_06_after_proof")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("mode", choices=("setup", "run", "recover", "read", "validate"))
    parser.add_argument("input", type=Path)
    parser.add_argument("--start", required=True, type=Path)
    args = parser.parse_args()
    args.start.with_suffix(".ready").write_text(str(os.getpid()))
    deadline = monotonic() + 15
    while not args.start.is_file():
        if monotonic() > deadline:
            raise ValueError("E_DESTRUCTION_START_TIMEOUT")
        sleep(0.01)
    config = json.loads(args.input.read_text())
    case = args.input.parent
    result: Any
    if args.mode == "validate":
        try:
            validate_plan(config)
        except ValueError as error:
            result = {"observed_error": str(error)}
        else:
            result = {"observed_error": None}
    elif args.mode == "setup":
        result = prepare_backend(case, config["observation"])
    elif args.mode == "read":
        if set(config) != {"identity", "options", "socket"}:
            raise ValueError("E_DESTRUCTION_READER_INPUT")
        result = read_actual(case, config)
    else:
        execute(case, config, recover=args.mode == "recover")
        result = {"completed": True}
    print(json.dumps({"pid": os.getpid(), "result": result}, sort_keys=True))


if __name__ == "__main__":
    try:
        main()
    except ValueError as error:
        print(json.dumps({"pid": os.getpid(), "result": {"observed_error": str(error)}}))
        raise SystemExit(1) from error"""Disposable-owner destruction mechanics; not a user-run authorization subsystem.

