from __future__ import annotations

import argparse
import hashlib
import json
import subprocess
import sys
from datetime import UTC, datetime
from pathlib import Path
from typing import Any, cast

RUNTIME_ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(RUNTIME_ROOT), str(RUNTIME_ROOT / "src")]

import rfc8785
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
from jsonschema import Draft202012Validator  # type: ignore[import-untyped]

from moj_discovery.review_authorization import (
    _schema_validate,
    review_identity,
    sign_review_execution_receipt,
    verify_review_execution_receipt,
    verify_review_launch_authorization,
    verify_review_result_binding,
)
from moj_discovery.schema_formats import STRICT_FORMAT_CHECKER
from tools.bootstrap_review_authority import bootstrap_review_authority
from tools.issue_review_launch_authorization import (
    _regular_hash,
    authorized_review_context,
    recheck_review_context,
    review_execution_root,
    validate_review_authority_state,
    validate_review_scope,
)


RESULT_DOMAIN = b"HD636/REVIEW-RESULT/v1\0"


def review_content_hash(value: dict[str, object]) -> str:
    payload = {key: item for key, item in value.items() if key != "content_hash"}
    return hashlib.sha256(RESULT_DOMAIN + rfc8785.dumps(cast(Any, payload))).hexdigest()


def _preparation_root(records: list[dict[str, object]]) -> str:
    return hashlib.sha256(
        b"HD636/REVIEW-PREPARATION/v1\0" + rfc8785.dumps(cast(Any, records))
    ).hexdigest()


def _validate_preparation(attestation: dict[str, object], role: object) -> None:
    expected = {
        "IMPLEMENTATION_READINESS_REVIEWER": ["A_INSTALL_PYTHON", "A_INSTALL_NODE"],
        "CYBERSECURITY_REVIEWER": ["B_INSTALL_PYTHON", "B_INSTALL_NODE"],
    }.get(cast(str, role))
    records = attestation.get("preparation_commands")
    if expected is None or not isinstance(records, list) or len(records) != 2:
        raise ValueError("E_REVIEW_FINALIZE_BINDING")
    actual = cast(list[dict[str, object]], records)
    expected_argv = [
        ["uv", "sync", "--frozen", "--offline"],
        ["pnpm", "install", "--frozen-lockfile", "--offline", "--ignore-scripts"],
    ]
    required = {
        "command_id",
        "argv",
        "cwd",
        "environment",
        "exit_code",
        "stdout_sha256",
        "stderr_sha256",
    }
    for index, record in enumerate(actual):
        if (
            not isinstance(record, dict)
            or set(record) != required
            or record.get("command_id") != expected[index]
            or record.get("argv") != expected_argv[index]
            or record.get("exit_code") != 0
            or not isinstance(record.get("cwd"), str)
            or not isinstance(record.get("environment"), dict)
            or not all(
                isinstance(key, str) and isinstance(value, str)
                for key, value in cast(dict[object, object], record["environment"]).items()
            )
            or not all(
                isinstance(record.get(key), str) and len(cast(str, record[key])) == 64
                for key in ("stdout_sha256", "stderr_sha256")
            )
        ):
            raise ValueError("E_REVIEW_FINALIZE_BINDING")
    if attestation.get("preparation_commands_root") != _preparation_root(actual):
        raise ValueError("E_REVIEW_FINALIZE_BINDING")


def _validate_result(result: dict[str, object], role: object) -> None:
    definition = {
        "IMPLEMENTATION_READINESS_REVIEWER": "ImplementationReviewResult",
        "CYBERSECURITY_REVIEWER": "CybersecurityReviewResult",
    }.get(cast(str, role))
    if definition is None:
        raise ValueError("E_REVIEW_FINALIZE_BINDING")
    schema = json.loads(
        (
            RUNTIME_ROOT / "vendor/hybrid-discovery-v6.3.6/docs/schemas/review-result.schema.json"
        ).read_text()
    )
    validator = Draft202012Validator(
        {"$ref": f"#/$defs/{definition}", "$defs": schema["$defs"]},
        format_checker=STRICT_FORMAT_CHECKER,
    )
    if next(validator.iter_errors(result), None) is not None or result.get(
        "content_hash"
    ) != review_content_hash(result):
        raise ValueError("E_REVIEW_FINALIZE_BINDING")


def _validate_current_workspace(
    authorization: dict[str, object], attestation: dict[str, object]
) -> None:
    _validate_preparation(attestation, authorization.get("review_role"))
    fresh = attestation.get("fresh_session_attestation")
    if (
        attestation.get("workspace_root") != authorization["workspace_root"]
        or attestation.get("unexpected_changed_paths") != []
        or not isinstance(fresh, dict)
    ):
        raise ValueError("E_REVIEW_FINALIZE_BINDING")
    try:
        _schema_validate(fresh, "review-execution-receipt.schema.json", "FreshSessionAttestation")
    except ValueError as error:
        raise ValueError("E_REVIEW_FINALIZE_BINDING") from error


def _validate_consumed_authorization(
    authorization: dict[str, object], authority_config: dict[str, object]
) -> None:
    try:
        validate_review_authority_state(authorization, authority_config)
    except ValueError as error:
        raise ValueError("E_REVIEW_FINALIZE_BINDING") from error


def validate_host_preparation(
    authorization: dict[str, object],
    authority: dict[str, object],
    attestation: dict[str, object],
) -> None:
    root = review_execution_root(authorization, authority).with_name(
        str(authorization["review_run_id"]) + "-preparation"
    )
    try:
        _regular_hash(root / "preparation.json")
        record = json.loads((root / "preparation.json").read_bytes())
        records = attestation.get("preparation_commands")
        if (
            not isinstance(records, list)
            or len(records) != 2
            or record
            != {
                "authorization_id": authorization["authorization_id"],
                "commands": records,
                "preparation_commands_root": _preparation_root(records),
            }
            or attestation.get("preparation_commands_root") != record["preparation_commands_root"]
        ):
            raise ValueError("E_REVIEW_EXECUTION")
        expected = {"preparation.json"}
        for index, row in enumerate(records):
            for stream in ("stdout", "stderr"):
                name = f"{index:02d}.{stream}"
                expected.add(name)
                if _regular_hash(root / name) != row.get(stream + "_sha256"):
                    raise ValueError("E_REVIEW_EXECUTION")
        if {p.name for p in root.iterdir()} != expected:
            raise ValueError("E_REVIEW_EXECUTION")
    except (OSError, ValueError, TypeError, KeyError) as error:
        raise ValueError("E_REVIEW_EXECUTION") from error


def validate_host_execution(
    authorization: dict[str, object],
    authority: dict[str, object],
    config: dict[str, object],
    attestation: dict[str, object],
) -> None:
    from tools.run_review_a_checks import run_review_a_checks
    from tools.run_review_b_checks import run_review_b_checks

    validate_host_preparation(authorization, authority, attestation)
    root = review_execution_root(authorization, authority)
    record_path = root / "execution.json"
    _regular_hash(record_path)
    record = json.loads(record_path.read_bytes())
    if (
        not isinstance(record, dict)
        or set(record) != {"authorization_id", "result", "commands", "commands_executed_root"}
        or record["authorization_id"] != authorization["authorization_id"]
    ):
        raise ValueError("E_REVIEW_EXECUTION")
    rows = record["commands"]
    if not isinstance(rows, list) or len(rows) != len(
        cast(list[str], config["mechanical_command_ids"])
    ):
        raise ValueError("E_REVIEW_EXECUTION")
    expected_files = {"execution.json"} | {
        f"{index:02d}.{stream}" for index in range(len(rows)) for stream in ("stdout", "stderr")
    }
    if {path.name for path in root.iterdir()} != expected_files:
        raise ValueError("E_REVIEW_EXECUTION")
    sequence = 0

    def observed(argv: list[str], **kwargs: object) -> subprocess.CompletedProcess[bytes]:
        nonlocal sequence
        row = rows[sequence]
        if (
            row.get("argv") != argv
            or row.get("cwd") != kwargs.get("cwd")
            or row.get("environment") != kwargs.get("env")
            or type(row.get("exit_code")) is not int
        ):
            raise ValueError("E_REVIEW_EXECUTION")
        values = []
        for stream in ("stdout", "stderr"):
            path = root / f"{sequence:02d}.{stream}"
            _regular_hash(path)
            if path.stat().st_size > 750000:
                raise ValueError("E_REVIEW_EXECUTION")
            values.append(path.read_bytes())
        sequence += 1
        return subprocess.CompletedProcess(argv, row["exit_code"], *values)

    registry = json.loads(Path(cast(str, config["command_registry_path"])).read_bytes())
    runner = (
        run_review_a_checks
        if config["role"] == "IMPLEMENTATION_READINESS_REVIEWER"
        else run_review_b_checks
    )
    expected = runner(config, registry, execute=observed)
    if record != {"authorization_id": authorization["authorization_id"], **expected} or (
        attestation["commands_executed_root"] != expected["commands_executed_root"]
    ):
        raise ValueError("E_REVIEW_EXECUTION")


def _validate_current_delivery(
    authorization: dict[str, object], result: Path, receipt: Path
) -> None:
    root = Path(cast(str, authorization["allowed_output_root"]))
    try:
        if (
            not root.is_absolute()
            or root != root.resolve(strict=True)
            or not root.is_dir()
            or root.is_symlink()
            or result != root / "result.json"
            or receipt != root / "execution-receipt.json"
            or receipt.exists()
            or receipt.is_symlink()
        ):
            raise ValueError("E_REVIEW_FINALIZE_BINDING")
        for path in (result, root / "workspace-attestation.json"):
            if path != path.resolve(strict=True):
                raise ValueError("E_REVIEW_FINALIZE_BINDING")
            _regular_hash(path)
    except (OSError, ValueError, RuntimeError) as error:
        raise ValueError("E_REVIEW_FINALIZE_BINDING") from error


def finalize_review(
    authorization: dict[str, object],
    result: dict[str, object],
    attestation: dict[str, object],
    private: Ed25519PrivateKey,
    *,
    now: datetime | None = None,
    external_seal: dict[str, object] | None = None,
) -> dict[str, object]:
    _ = (now or datetime.now(UTC)).astimezone(UTC)
    _validate_result(result, authorization.get("review_role"))
    verify_review_result_binding(result, authorization)
    current = authorization.get("schema_version") == "review-launch-authorization/v2"
    if current:
        _validate_current_workspace(authorization, attestation)
    if current and (
        external_seal is None
        or external_seal.get("schema_version") != "external-seal-attestation/v7"
        or external_seal.get("artifact_type") != "RUNTIME_PACK"
        or review_identity(external_seal) != review_identity(authorization)
        or external_seal.get("zip_sha256") != authorization["pack_zip_sha256"]
        or external_seal.get("manifest_sha256") != authorization["pack_manifest_sha256"]
    ):
        raise ValueError("E_REVIEW_FINALIZE_BINDING")
    _validate_preparation(attestation, authorization.get("review_role"))
    if (
        result.get("review_role") != authorization.get("review_role")
        or result.get("review_run_id") != authorization.get("review_run_id")
        or result.get("pack_zip_sha256") != authorization.get("pack_zip_sha256")
        or result.get("repo0_receipt_sha256") != authorization.get("repo0_receipt_sha256")
        or result.get("authorized_production_phases") != "NONE"
        or not isinstance(attestation.get("fresh_session_attestation"), dict)
        or attestation.get("unexpected_changed_paths") != []
    ):
        raise ValueError("E_REVIEW_FINALIZE_BINDING")
    receipt = sign_review_execution_receipt(
        {
            "schema_version": "review-execution-receipt/v2"
            if current
            else "review-execution-receipt/v1",
            "authorization_id": authorization["authorization_id"],
            **(review_identity(authorization) if current else {}),
            "issuer_role": "HOST_REVIEW_AUTHORITY",
            "review_role": authorization["review_role"],
            "review_run_id": authorization["review_run_id"],
            "workspace_root": authorization["workspace_root"],
            "workspace_attestation_sha256": hashlib.sha256(
                rfc8785.dumps(cast(Any, attestation))
            ).hexdigest(),
            "input_content_roots": [
                item["content_root_sha256"]
                for item in cast(list[dict[str, object]], authorization["input_mounts"])
            ],
            "result_sha256": hashlib.sha256(rfc8785.dumps(cast(Any, result))).hexdigest(),
            "commands_executed_root": attestation["commands_executed_root"],
            "allowed_changed_paths": attestation["allowed_changed_paths"],
            "unexpected_changed_paths": [],
            "started_at": attestation["started_at"],
            "finished_at": attestation["finished_at"],
            "authorization_consumed_at": attestation["authorization_consumed_at"],
            "fresh_session_attestation": attestation["fresh_session_attestation"],
            "production_authority": "NONE",
            "signature_algorithm": "Ed25519",
            "host_boot_id": authorization["host_boot_id"],
            "trust_epoch": authorization["trust_epoch"],
            "preparation_commands_root": attestation["preparation_commands_root"],
        },
        private,
    )
    return receipt


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--authorization", required=True, type=Path)
    parser.add_argument("--result", required=True, type=Path)
    parser.add_argument("--receipt", required=True, type=Path)
    args = parser.parse_args()
    authorization = json.loads(args.authorization.read_text())
    workspace = Path(cast(str, authorization["workspace_root"]))
    authority = json.loads((RUNTIME_ROOT / "review-config/review-authority.v1.json").read_text())
    context = None
    if authorization.get("schema_version") == "review-launch-authorization/v2":
        context = authorized_review_context(authorization, authority, runtime_root=RUNTIME_ROOT)
        _validate_current_delivery(authorization, args.result, args.receipt)
    result = json.loads(args.result.read_text())
    attestation = json.loads(
        (
            Path(cast(str, authorization["allowed_output_root"])) / "workspace-attestation.json"
        ).read_text()
    )
    if context is not None:
        _validate_result(result, authorization.get("review_role"))
        verify_review_result_binding(result, authorization)
        _validate_current_workspace(authorization, attestation)
        review_config = cast(dict[str, object], context["config"])
        validate_review_scope(review_config, result)
        validate_host_execution(authorization, authority, review_config, attestation)
        recheck_review_context(context)
    bootstrap_review_authority(authority, initialize_if_absent=False)
    _validate_consumed_authorization(authorization, authority)
    private = serialization.load_pem_private_key(
        Path(cast(str, authority["private_key_path"])).read_bytes(), password=None
    )
    if not isinstance(private, Ed25519PrivateKey) or workspace.is_symlink():
        raise ValueError("E_REVIEW_FINALIZE_BINDING")
    verify_review_launch_authorization(
        authorization,
        private.public_key(),
        cast(str, authorization["review_role"]),
        cast(str, authorization["workspace_root"]),
        cast(str, authorization["pack_zip_sha256"]),
        expected_host_boot_id=Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
        expected_trust_epoch=cast(int, authorization["trust_epoch"]),
    )
    if context is not None:
        recheck_review_context(context)
        _validate_current_delivery(authorization, args.result, args.receipt)
    receipt = finalize_review(
        authorization,
        result,
        attestation,
        private,
        external_seal=cast(dict[str, object], context["seal"]) if context is not None else None,
    )
    public = serialization.load_pem_private_key(
        Path(cast(str, authority["private_key_path"])).read_bytes(), password=None
    )
    if not isinstance(public, Ed25519PrivateKey):
        raise ValueError("E_REVIEW_FINALIZE_BINDING")
    verify_review_execution_receipt(
        receipt,
        authorization,
        public.public_key(),
        result_sha256=cast(str, receipt["result_sha256"]),
        expected_host_boot_id=Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
        expected_trust_epoch=cast(int, authorization["trust_epoch"]),
    )
    receipt_text = json.dumps(receipt, sort_keys=True, separators=(",", ":")) + "\n"
    if context is not None:
        _validate_current_delivery(authorization, args.result, args.receipt)
        try:
            with args.receipt.open("x") as output:
                output.write(receipt_text)
        except OSError as error:
            raise ValueError("E_REVIEW_FINALIZE_BINDING") from error
    else:
        args.receipt.parent.mkdir(parents=True, exist_ok=True)
        args.receipt.write_text(receipt_text)
    print(json.dumps(receipt, sort_keys=True))


if __name__ == "__main__":
    main()"""Strict source-owned inputs for the full candidate controller."""

from __future__ import annotations

import hashlib
import json
import re
import stat
from dataclasses import dataclass
from pathlib import Path
from typing import TYPE_CHECKING, Any, Literal, NoReturn, cast

from tools.retained_artifact_io import canonical_recorded_locator

if TYPE_CHECKING:
    from tools.retained_artifact_io import RetainedArtifactIO


@dataclass(frozen=True)
class QualificationEvidenceConfig:
    full_repair_aggregate: Path
    full_repair_inventory: Path
    environment_qualification_aggregate: Path
    environment_qualification_inventory: Path
    p03_proof: Path
    p04_proof: Path

    def binding(self) -> dict[str, str]:
        return {
            "full_repair_aggregate": str(self.full_repair_aggregate),
            "full_repair_inventory": str(self.full_repair_inventory),
            "environment_qualification_aggregate": str(self.environment_qualification_aggregate),
            "environment_qualification_inventory": str(self.environment_qualification_inventory),
            "p03_proof": str(self.p03_proof),
            "p04_proof": str(self.p04_proof),
        }


@dataclass(frozen=True)
class FullVerifierConfig:
    schema_version: str
    production_authority: str
    accepted_authoring_ancestor: str
    current_checkout_root: Path
    governed_source_pack: Path
    evidence_root: Path
    external_authoring_tests: Path
    external_authoring_source_sha256: str
    external_authoring_cwd: Path
    external_authoring_argv: tuple[str, ...]
    uv_cache: Path
    pnpm_store: Path
    chrome_path: Path
    chrome_sha256: str
    authoring_repository_receipt: Path
    candidate_command_evidence: Path
    proof_coverage_evidence: Path
    candidate_issuance_evidence: Path
    candidate_qualification_receipt: Path
    audited_runtime_ancestor: str | None
    qualification_evidence: QualificationEvidenceConfig | None
    descendant_repository_receipt: Path | None
    source_path: Path
    source_sha256: str

    def binding(self) -> dict[str, object]:
        binding: dict[str, object] = {
            "schema_version": (
                "full-verifier-controller-binding/v2"
                if self.schema_version == "full-verifier-controller/v2"
                else "full-verifier-controller-binding/v1"
            ),
            "config_sha256": self.source_sha256,
            "accepted_authoring_ancestor": self.accepted_authoring_ancestor,
            "current_checkout_root": str(self.current_checkout_root),
            "governed_source_pack": str(self.governed_source_pack),
            "evidence_root": str(self.evidence_root),
            "external_authoring_tests": str(self.external_authoring_tests),
            "external_authoring_source_sha256": self.external_authoring_source_sha256,
            "external_authoring_command": {
                "cwd": str(self.external_authoring_cwd),
                "argv": list(self.external_authoring_argv),
            },
            "uv_cache": str(self.uv_cache),
            "pnpm_store": str(self.pnpm_store),
            "chrome": {"path": str(self.chrome_path), "sha256": self.chrome_sha256},
            "receipts": {
                "authoring_repository": str(self.authoring_repository_receipt),
                "candidate_command_evidence": str(self.candidate_command_evidence),
                "proof_coverage_evidence": str(self.proof_coverage_evidence),
                "candidate_issuance_evidence": str(self.candidate_issuance_evidence),
                "candidate_qualification": str(self.candidate_qualification_receipt),
            },
        }
        if self.schema_version == "full-verifier-controller/v2":
            if (
                self.audited_runtime_ancestor is None
                or self.qualification_evidence is None
                or self.descendant_repository_receipt is None
            ):
                _fail()
            binding["audited_runtime_ancestor"] = self.audited_runtime_ancestor
            binding["qualification_evidence"] = self.qualification_evidence.binding()
            receipts = cast(dict[str, str], binding["receipts"])
            receipts["descendant_repository"] = str(self.descendant_repository_receipt)
        return binding


def _fail() -> NoReturn:
    raise ValueError("E_CONTROLLER_CONFIG")


def _absolute(value: object) -> Path:
    if not isinstance(value, str):
        _fail()
    path = Path(value)
    if not path.is_absolute() or any(part in {"", ".", ".."} for part in path.parts):
        _fail()
    return path


def load_controller_config(
    path: Path,
    *,
    mode: Literal["LIVE", "SEALED"] = "LIVE",
    artifacts: RetainedArtifactIO | None = None,
    recorded_locator: str | None = None,
) -> FullVerifierConfig:
    if mode not in {"LIVE", "SEALED"}:
        _fail()
    if mode == "LIVE" and (artifacts is not None or recorded_locator is not None):
        _fail()
    if mode == "SEALED" and (artifacts is None or recorded_locator is None):
        _fail()
    try:
        info = path.lstat()
        canonical_path = path.resolve(strict=True)
        if mode == "SEALED":
            assert artifacts is not None and recorded_locator is not None
            recorded_boundary = artifacts.recorded_boundary(recorded_locator)
            mapped = artifacts.physical_path(recorded_locator, recorded_boundary=recorded_boundary)
            if canonical_path != mapped.resolve(strict=True):
                _fail()
            raw = artifacts.read_bytes(recorded_locator, recorded_boundary=recorded_boundary)
        else:
            raw = path.read_bytes()
        value = json.loads(raw)
    except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as error:
        raise ValueError("E_CONTROLLER_CONFIG") from error
    schema_version = value.get("schema_version") if isinstance(value, dict) else None
    base_keys = {
        "schema_version",
        "production_authority",
        "accepted_authoring_ancestor",
        "current_checkout_root",
        "governed_source_pack",
        "evidence_root",
        "external_authoring_tests",
        "external_authoring_source_sha256",
        "external_authoring_command",
        "uv_cache",
        "pnpm_store",
        "chrome",
        "receipts",
    }
    expected_keys = (
        base_keys | {"audited_runtime_ancestor", "qualification_evidence"}
        if schema_version == "full-verifier-controller/v2"
        else base_keys
    )
    if (
        path.is_symlink()
        or not stat.S_ISREG(info.st_mode)
        or info.st_nlink != 1
        or not isinstance(value, dict)
        or set(value) != expected_keys
        or schema_version not in {"full-verifier-controller/v1", "full-verifier-controller/v2"}
        or value.get("production_authority") != "NONE"
        or not isinstance(value.get("accepted_authoring_ancestor"), str)
        or re.fullmatch(r"[0-9a-f]{40}", cast(str, value.get("accepted_authoring_ancestor")))
        is None
        or not isinstance(value.get("external_authoring_source_sha256"), str)
        or re.fullmatch(r"[0-9a-f]{64}", cast(str, value.get("external_authoring_source_sha256")))
        is None
    ):
        _fail()
    chrome = value.get("chrome")
    receipts = value.get("receipts")
    external_command = value.get("external_authoring_command")
    receipt_keys = {
        "authoring_repository",
        "candidate_command_evidence",
        "proof_coverage_evidence",
        "candidate_issuance_evidence",
        "candidate_qualification",
    }
    if schema_version == "full-verifier-controller/v2":
        receipt_keys.add("descendant_repository")
    qualification = value.get("qualification_evidence")
    qualification_keys = {
        "full_repair_aggregate",
        "full_repair_inventory",
        "environment_qualification_aggregate",
        "environment_qualification_inventory",
        "p03_proof",
        "p04_proof",
    }
    if (
        not isinstance(chrome, dict)
        or set(chrome) != {"path", "sha256"}
        or not isinstance(chrome.get("sha256"), str)
        or re.fullmatch(r"[0-9a-f]{64}", cast(str, chrome["sha256"])) is None
        or not isinstance(receipts, dict)
        or not isinstance(external_command, dict)
        or set(external_command) != {"cwd", "argv"}
        or not isinstance(external_command.get("argv"), list)
        or not external_command["argv"]
        or any(not isinstance(item, str) or not item for item in external_command["argv"])
        or set(receipts) != receipt_keys
        or (
            schema_version == "full-verifier-controller/v2"
            and (
                not isinstance(value.get("audited_runtime_ancestor"), str)
                or re.fullmatch(r"[0-9a-f]{40}", cast(str, value.get("audited_runtime_ancestor")))
                is None
                or not isinstance(qualification, dict)
                or set(qualification) != qualification_keys
            )
        )
        or (schema_version == "full-verifier-controller/v1" and qualification is not None)
    ):
        _fail()
    values = cast(dict[str, Any], value)
    evidence_root = _absolute(values["evidence_root"])
    receipt_paths = {key: _absolute(item) for key, item in receipts.items()}
    qualification_paths = (
        {key: _absolute(item) for key, item in cast(dict[str, object], qualification).items()}
        if schema_version == "full-verifier-controller/v2"
        else {}
    )
    checkout_root = _absolute(values["current_checkout_root"])
    source_pack = _absolute(values["governed_source_pack"])
    external_tests = _absolute(values["external_authoring_tests"])
    external_cwd = _absolute(external_command["cwd"])
    protected = (checkout_root, source_pack, external_tests.parent)
    paths_to_protect = (evidence_root, *receipt_paths.values(), *qualification_paths.values())
    if (
        len(set((*receipt_paths.values(), *qualification_paths.values())))
        != len(receipt_paths) + len(qualification_paths)
        or any(
            not item.is_relative_to(evidence_root)
            for item in (*receipt_paths.values(), *qualification_paths.values())
        )
        or any(
            (mode == "LIVE" and candidate.resolve(strict=False) != candidate)
            or candidate == boundary
            or candidate.is_relative_to(boundary)
            or boundary.is_relative_to(candidate)
            for candidate in paths_to_protect
            for boundary in protected
        )
    ):
        _fail()
    version_number = "v1" if schema_version == "full-verifier-controller/v1" else "v2"
    source_copy = source_pack / f"docs/configs/full-verifier-controller.{version_number}.json"
    try:
        source_raw = (
            artifacts.read_bytes(str(source_copy), recorded_boundary=str(source_pack))
            if mode == "SEALED" and artifacts is not None
            else source_copy.read_bytes()
        )
        if source_raw != raw:
            _fail()
    except (OSError, ValueError) as error:
        raise ValueError("E_CONTROLLER_CONFIG") from error
    return FullVerifierConfig(
        schema_version=cast(str, schema_version),
        production_authority="NONE",
        accepted_authoring_ancestor=cast(str, values["accepted_authoring_ancestor"]),
        current_checkout_root=checkout_root,
        governed_source_pack=source_pack,
        evidence_root=evidence_root,
        external_authoring_tests=external_tests,
        external_authoring_source_sha256=cast(str, values["external_authoring_source_sha256"]),
        external_authoring_cwd=external_cwd,
        external_authoring_argv=tuple(cast(list[str], external_command["argv"])),
        uv_cache=_absolute(values["uv_cache"]),
        pnpm_store=_absolute(values["pnpm_store"]),
        chrome_path=_absolute(chrome["path"]),
        chrome_sha256=cast(str, chrome["sha256"]),
        authoring_repository_receipt=receipt_paths["authoring_repository"],
        candidate_command_evidence=receipt_paths["candidate_command_evidence"],
        proof_coverage_evidence=receipt_paths["proof_coverage_evidence"],
        candidate_issuance_evidence=receipt_paths["candidate_issuance_evidence"],
        candidate_qualification_receipt=receipt_paths["candidate_qualification"],
        audited_runtime_ancestor=cast(str, values["audited_runtime_ancestor"])
        if schema_version == "full-verifier-controller/v2"
        else None,
        qualification_evidence=QualificationEvidenceConfig(**qualification_paths)
        if schema_version == "full-verifier-controller/v2"
        else None,
        descendant_repository_receipt=receipt_paths.get("descendant_repository"),
        source_path=Path(canonical_recorded_locator(cast(str, recorded_locator)))
        if mode == "SEALED" else canonical_path,
        source_sha256=hashlib.sha256(raw).hexdigest(),
    )"""Execute registered generation/coherence operations on the governed SQLite schema."""

from __future__ import annotations

import argparse
import copy
import hashlib
import json
import os
import signal
import sqlite3
import sys
from contextlib import closing
from pathlib import Path
from time import sleep
from typing import Any

if __package__ in {None, ""}:
    root = Path(__file__).resolve().parents[1]
    sys.path[:0] = [str(root / "src"), str(root)]

from moj_discovery.canonical import (  # noqa: E402
    canonical_content_hash,
    verify_canonical_content_hash,
)
from moj_discovery.generation import GenerationController  # noqa: E402
from moj_discovery.ingest import Ingestor  # noqa: E402
from moj_discovery.schema_registry import validate_artifact  # noqa: E402
from moj_discovery.store import VENDOR, RunStore, read_journal  # noqa: E402
from tools.gap_state_reader import read_gap_state  # noqa: E402
from tools.loopback_ack_crash_child import (  # noqa: E402
    BEFORE_STATEMENT,
    CheckpointStore,
    apply_result,
    provision,
)


def _identity(args: argparse.Namespace) -> dict[str, Any]:
    return {
        "run_id": args.run_id,
        "case_id": args.case_id,
        "checkpoint_id": args.checkpoint_id,
        "component": args.component,
        "pid": os.getpid(),
        "ordinal": args.ordinal,
        "test_nonce": args.test_nonce,
    }


def _checkpoint(
    args: argparse.Namespace,
    connection: sqlite3.Connection,
    operation: str,
    *,
    hold: bool,
) -> None:
    identity = _identity(args)
    boundary = {
        "identity": identity,
        "operation": operation,
        "in_transaction": connection.in_transaction,
        "tables": read_journal(connection),
    }
    args.ready.with_name("boundary.json").write_text(json.dumps(boundary, sort_keys=True))
    temporary = args.ready.with_suffix(".tmp")
    temporary.write_text(json.dumps(identity, sort_keys=True))
    temporary.replace(args.ready)
    if hold:
        while True:
            signal.pause()
    release = args.ready.with_name("continue.json")
    while not release.is_file():
        sleep(0.02)


def _mapping(connection: sqlite3.Connection, run_id: str, suffix: str = "0") -> str:
    mapping = f"mapping:{suffix}"
    connection.execute(
        "INSERT INTO clock_mappings VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (
            mapping,
            run_id,
            f"source:{suffix}",
            f"source-boot:{suffix}",
            "EXTENSION_SERVICE_WORKER",
            f"target:{suffix}",
            f"target-boot:{suffix}",
            "BACKEND_PROCESS",
            "MICROSECOND",
            8,
            0,
            0,
            2,
            1,
            1,
            0,
            100,
            0,
            10,
            "OPEN",
            0,
        ),
    )
    return mapping


def _close_mapping(connection: sqlite3.Connection, mapping: str) -> None:
    connection.execute(
        "INSERT INTO clock_mapping_closures VALUES (?,?,?,?,?,?,?,?,?)",
        (
            "mapping-close:" + mapping,
            mapping,
            "SLEEP_RESUME",
            "source:0",
            "source-boot:0",
            5,
            1,
            0,
            5,
        ),
    )


def _shock_close(
    connection: sqlite3.Connection,
    run_id: str,
    suffix: str = "0",
    shock_type: str = "MAPPING_CLOSURE",
) -> None:
    controller = connection.execute(
        "SELECT * FROM coherence_controllers WHERE run_id=?", (run_id,)
    ).fetchone()
    shock, transition = f"shock:{suffix}", f"shock-transition:{suffix}"
    connection.execute(
        "INSERT INTO shock_observations VALUES (?,?,?,?,?,?,?,?)",
        (shock, run_id, "fixture:test", shock_type, 6, 6, f"{int(suffix) + 1:064x}", 6),
    )
    connection.execute(
        "INSERT INTO coherence_transitions VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (
            transition,
            controller["coherence_controller_id"],
            controller["fixture_id"],
            controller["controller_state"],
            "SHOCKED_CLOSED",
            controller["current_epoch_id"],
            None,
            shock,
            None,
            None,
            1,
            "SHOCK_ATOMIC_CLOSE",
            6,
        ),
    )
    connection.execute(
        "UPDATE coherence_controllers SET controller_state='SHOCKED_CLOSED',"
        "active_shock_observation_id=?,controller_revision=controller_revision+1,updated_at_us=6 "
        "WHERE coherence_controller_id=?",
        (shock, controller["coherence_controller_id"]),
    )


def _waiting(connection: sqlite3.Connection, run_id: str) -> None:
    controller = connection.execute(
        "SELECT * FROM coherence_controllers WHERE run_id=?", (run_id,)
    ).fetchone()
    connection.execute(
        "INSERT INTO coherence_transitions VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (
            "close-recorded",
            controller["coherence_controller_id"],
            controller["fixture_id"],
            "SHOCKED_CLOSED",
            "WAITING_FOR_RESNAPSHOT",
            controller["current_epoch_id"],
            None,
            controller["active_shock_observation_id"],
            None,
            None,
            1,
            "CLOSE_RECORDED",
            7,
        ),
    )
    connection.execute(
        "UPDATE coherence_controllers SET controller_state='WAITING_FOR_RESNAPSHOT',"
        "controller_revision=controller_revision+1,updated_at_us=7 WHERE run_id=?",
        (run_id,),
    )


def _pending(connection: sqlite3.Connection, scenario: dict[str, Any]) -> None:
    run_id = scenario["run_id"]
    controller = connection.execute(
        "SELECT * FROM coherence_controllers WHERE run_id=?", (run_id,)
    ).fetchone()
    mappings = tuple(_mapping(connection, run_id, str(index + 1)) for index in range(3))
    freshness, proof, candidate = "freshness:1", "proof:1", "epoch:1"
    connection.execute(
        "INSERT INTO input_freshness_vectors VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
        (
            freshness,
            run_id,
            "fixture:test",
            "FRESH",
            "FRESH",
            "FRESH",
            "FRESH",
            "FRESH",
            "FRESH",
            "FRESH",
            "a" * 64,
            8,
        ),
    )
    connection.execute(
        "INSERT INTO coherence_epochs VALUES (?,?,?,?,?,?,?,?,?,?)",
        (
            candidate,
            run_id,
            "fixture:test",
            1,
            controller["current_epoch_id"],
            "OPEN",
            freshness,
            proof,
            8,
            1,
        ),
    )
    cursor = connection.execute(
        "SELECT reducer_cursor_id FROM reducer_cursors WHERE generation=1 LIMIT 1"
    ).fetchone()
    if cursor is None:
        raise ValueError("E_EPOCH_CURSOR_PREREQUISITE")
    connection.execute(
        "INSERT INTO authoritative_resnapshot_proofs VALUES "
        "(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (
            proof,
            run_id,
            "fixture:test",
            controller["current_epoch_id"],
            candidate,
            controller["active_shock_observation_id"],
            "OBSERVED",
            "capability:test",
            freshness,
            *mappings,
            "b" * 64,
            cursor[0],
            "c" * 64,
            1,
            1,
            1,
            "SATISFIED",
            "d" * 64,
            8,
        ),
    )
    connection.execute(
        "INSERT INTO coherence_transitions VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (
            "candidate-accepted",
            controller["coherence_controller_id"],
            "fixture:test",
            "WAITING_FOR_RESNAPSHOT",
            "NEW_EPOCH_PENDING",
            controller["current_epoch_id"],
            candidate,
            controller["active_shock_observation_id"],
            freshness,
            proof,
            1,
            "RESNAPSHOT_CANDIDATE_ACCEPTED",
            8,
        ),
    )
    connection.execute(
        "UPDATE coherence_controllers SET controller_state='NEW_EPOCH_PENDING',"
        "candidate_epoch_id=?,predecessor_epoch_id=current_epoch_id,"
        "controller_revision=controller_revision+1,updated_at_us=8 "
        "WHERE run_id=?",
        (candidate, run_id),
    )


def _seed_epoch_continuity(store: RunStore, scenario: dict[str, Any]) -> None:
    """Create an independent generation-1 cursor used only by the epoch proof."""
    observation = copy.deepcopy(scenario["observation"])
    observation.update(
        raw_observation_id="observation:" + "9" * 64,
        stream_id="00000000-0000-4000-8000-000000000099",
        generation="1",
        sequence="1",
    )
    observation["content_hash"] = canonical_content_hash(
        "RawObservation",
        observation,
        registry_path=VENDOR / "registries/canonical-hash-domains.v1.json",
    )
    with closing(store.connect()) as connection, connection:
        controller = connection.execute(
            "SELECT * FROM coherence_controllers WHERE run_id=?", (scenario["run_id"],)
        ).fetchone()
        transition = connection.execute(
            "SELECT * FROM coherence_transitions WHERE coherence_controller_id=? "
            "AND to_state='SHOCKED_CLOSED' ORDER BY transitioned_at_us DESC LIMIT 1",
            (controller["coherence_controller_id"],),
        ).fetchone()
        if transition is None or controller["controller_state"] != "SHOCKED_CLOSED":
            raise ValueError("E_EPOCH_CONTINUITY_CLOSURE")
        key = (
            scenario["run_id"],
            observation["context"]["browser_run_id"],
            observation["clock_context"]["clock_domain_id"],
            observation["stream_id"],
        )
        connection.execute(
            "INSERT INTO stream_generations VALUES (?,?,?,?,?,0,NULL,'ACTIVE',0,NULL,NULL)",
            ("epoch-proof-generation:0", *key),
        )
        connection.execute(
            "INSERT INTO gap_records VALUES (?,?,?,?,?,0,1,1,1,2,'MISSING_SEQUENCE','OPEN',0,2)",
            ("epoch-proof-gap", *key),
        )
        connection.execute(
            "INSERT INTO gap_epoch_bindings VALUES "
            "(?,?,?,?,?,?,'AFFECTED_EPOCH_PERMANENTLY_CLOSED',2)",
            (
                "epoch-proof-binding",
                "epoch-proof-gap",
                controller["current_epoch_id"],
                controller["coherence_controller_id"],
                controller["active_shock_observation_id"],
                transition["coherence_transition_id"],
            ),
        )
        connection.execute(
            "UPDATE stream_generations SET generation_state='QUARANTINED_GAP',closed_at_us=2,"
            "close_reason='MISSING_SEQUENCE' WHERE generation_id='epoch-proof-generation:0'"
        )
        connection.execute(
            "INSERT INTO generation_transitions VALUES (?,?,?,?,?,?,0,1,'GAP',2)",
            ("epoch-proof-generation-transition", "epoch-proof-gap", *key),
        )
        connection.execute(
            "INSERT INTO stream_generations VALUES (?,?,?,?,?,1,0,'ACTIVE',2,NULL,NULL)",
            ("epoch-proof-generation:1", *key),
        )
    Ingestor(store).apply(observation)


def _release(connection: sqlite3.Connection, run_id: str) -> None:
    controller = connection.execute(
        "SELECT * FROM coherence_controllers WHERE run_id=?", (run_id,)
    ).fetchone()
    connection.execute(
        "INSERT INTO coherence_transitions VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (
            "epoch-release",
            controller["coherence_controller_id"],
            "fixture:test",
            "NEW_EPOCH_PENDING",
            "NEW_EPOCH_OPEN",
            controller["current_epoch_id"],
            controller["candidate_epoch_id"],
            controller["active_shock_observation_id"],
            "freshness:1",
            "proof:1",
            1,
            "RELEASE_PREDICATE_SATISFIED",
            9,
        ),
    )
    connection.execute(
        "UPDATE coherence_controllers SET controller_state='NEW_EPOCH_OPEN',"
        "current_epoch_id=candidate_epoch_id,candidate_epoch_id=NULL,"
        "controller_revision=controller_revision+1,updated_at_us=9 WHERE run_id=?",
        (run_id,),
    )


def _new_shock_pending(connection: sqlite3.Connection, run_id: str) -> None:
    controller = connection.execute(
        "SELECT * FROM coherence_controllers WHERE run_id=?", (run_id,)
    ).fetchone()
    shock = "shock:1"
    connection.execute(
        "INSERT INTO shock_observations VALUES (?,?,?,?,?,?,?,?)",
        (shock, run_id, "fixture:test", "GOAL", 10, 10, "e" * 64, 10),
    )
    connection.execute(
        "INSERT INTO coherence_epochs VALUES (?,?,?,?,?,?,?,?,?,?)",
        (
            "epoch:2",
            run_id,
            "fixture:test",
            2,
            controller["candidate_epoch_id"],
            "OPEN",
            "freshness:1",
            "proof:1",
            10,
            1,
        ),
    )
    connection.execute(
        "INSERT INTO coherence_transitions VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (
            "pending-new-shock",
            controller["coherence_controller_id"],
            "fixture:test",
            "NEW_EPOCH_PENDING",
            "WAITING_FOR_RESNAPSHOT",
            controller["current_epoch_id"],
            controller["candidate_epoch_id"],
            shock,
            "freshness:1",
            "proof:1",
            1,
            "NEW_SHOCK_CLOSED_CANDIDATE",
            10,
        ),
    )
    connection.execute(
        "UPDATE coherence_controllers SET controller_state='WAITING_FOR_RESNAPSHOT',"
        "candidate_epoch_id=NULL,active_shock_observation_id=?,"
        "controller_revision=controller_revision+1,updated_at_us=10 "
        "WHERE run_id=?",
        (shock, run_id),
    )


def _bootstrap(scenario: dict[str, Any], database: Path) -> RunStore:
    store = provision(database.parent.parent, scenario["observation"])
    for value in scenario.get("setup_deliveries", []):
        result = apply_result(store, value)
        if "error" in result and result["error"] not in {
            "E_INGEST_GAP",
            "E_INGEST_CONFLICT",
            "E_INGEST_GENERATION_CLOSED",
        }:
            raise ValueError("E_GAP_SETUP")
    return store


def _recover(case: Path) -> None:
    (case / "recovery-process.json").write_text(
        json.dumps(
            {
                "pid": os.getpid(),
                "ppid": os.getppid(),
                "pgid": os.getpgid(0),
                "start_ticks": Path("/proc/self/stat").read_text().split()[21],
                "executable": str(Path(sys.executable).resolve()),
                "executable_sha256": hashlib.sha256(
                    Path(sys.executable).resolve().read_bytes()
                ).hexdigest(),
                "argv": sys.argv,
            },
            sort_keys=True,
        )
    )
    scenario = json.loads((case / "scenario.json").read_text())
    store = RunStore(case / scenario["run_id"] / "run.sqlite3")
    with closing(store.connect()) as connection:
        tables = read_journal(connection)
        controller = tables["coherence_controllers"][0]["controller_state"]
        if scenario["operation"] == "GAP" and not tables["gap_records"]:
            apply_result(store, scenario["delivery"])
        elif scenario["operation"] == "CLOCK":
            closure = connection.execute("SELECT 1 FROM clock_mapping_closures LIMIT 1").fetchone()
            if closure is None:
                with connection:
                    mapping = connection.execute(
                        "SELECT clock_mapping_id FROM clock_mappings"
                    ).fetchone()[0]
                    _close_mapping(connection, mapping)
            shock = connection.execute("SELECT 1 FROM shock_observations LIMIT 1").fetchone()
            if shock is None:
                with connection:
                    _shock_close(connection, scenario["run_id"])
        elif scenario["operation"] == "EPOCH":
            with connection:
                if controller == "OPEN":
                    _shock_close(
                        connection,
                        scenario["run_id"],
                        shock_type="EQUIVALENT_UNKNOWN_SHOCK",
                    )
                    controller = "SHOCKED_CLOSED"
                if controller == "SHOCKED_CLOSED":
                    _waiting(connection, scenario["run_id"])
                    controller = "WAITING_FOR_RESNAPSHOT"
                if (
                    controller == "WAITING_FOR_RESNAPSHOT"
                    and scenario.get("candidate")
                    and scenario.get("epoch_step") != "new_shock"
                ):
                    _pending(connection, scenario)
                    controller = "NEW_EPOCH_PENDING"
                if controller == "NEW_EPOCH_PENDING" and scenario.get("release"):
                    _release(connection, scenario["run_id"])


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--recover", type=Path)
    parser.add_argument("--commit-shim", type=Path)
    parser.add_argument("--vector-id")
    parser.add_argument("--ready", type=Path)
    parser.add_argument("--run-id")
    parser.add_argument("--case-id")
    parser.add_argument("--checkpoint-id")
    parser.add_argument("--component")
    parser.add_argument("--ordinal", type=int, default=0)
    parser.add_argument("--test-nonce", default="recovery")
    parser.add_argument("--hold", action="store_true")
    parser.add_argument("--launch-ready", type=Path)
    args = parser.parse_args()
    if args.recover:
        _recover(args.recover)
        return
    if not args.hold or not args.ready:
        raise ValueError("E_GAP_SCENARIO")
    case = args.ready.parent
    scenario = json.loads((case / "scenario.json").read_text())
    database = case / scenario["run_id"] / "run.sqlite3"
    store = RunStore(database) if database.is_file() else _bootstrap(scenario, database)
    if args.launch_ready:
        temporary = args.launch_ready.with_suffix(".tmp")
        temporary.write_text(json.dumps(_identity(args), sort_keys=True))
        temporary.replace(args.launch_ready)
        release = args.launch_ready.with_name("launch-continue.json")
        while not release.is_file():
            sleep(0.02)
    validate_artifact(
        scenario["delivery"], "raw-observation.schema.json", bootstrap_only=True, vendor=VENDOR
    )
    verify_canonical_content_hash(
        "RawObservation",
        scenario["delivery"],
        scenario["delivery"]["content_hash"],
        registry_path=VENDOR / "registries/canonical-hash-domains.v1.json",
    )
    phase, operation = scenario["phase"], scenario["operation"]
    fresh_case = not (case / "baseline-state.json").is_file()
    if fresh_case and scenario.get("prepare_successor"):
        _seed_epoch_continuity(store, scenario)
        with closing(store.connect()) as connection, connection:
            _waiting(connection, scenario["run_id"])
            _pending(connection, scenario)
            _release(connection, scenario["run_id"])
    elif fresh_case and (scenario.get("prepare_waiting") or scenario.get("prepare_pending")):
        with closing(store.connect()) as connection, connection:
            _shock_close(
                connection,
                scenario["run_id"],
                shock_type="EQUIVALENT_UNKNOWN_SHOCK",
            )
        if scenario.get("candidate"):
            _seed_epoch_continuity(store, scenario)
        with closing(store.connect()) as connection, connection:
            _waiting(connection, scenario["run_id"])
            if scenario.get("prepare_pending"):
                _pending(connection, scenario)
    if fresh_case:
        (case / "baseline-state.json").write_text(
            json.dumps(read_gap_state(store.db_path.parent), sort_keys=True)
        )
        if scenario.get("spool_append"):
            (case / "spool-events.jsonl").write_text(
                json.dumps(
                    {
                        "raw_observation_id": scenario["delivery"]["raw_observation_id"],
                        "status": "UNACKNOWLEDGED",
                    },
                    sort_keys=True,
                )
                + "\n"
            )

    def pause(connection: sqlite3.Connection) -> None:
        _checkpoint(args, connection, phase, hold=True)

    if phase in BEFORE_STATEMENT:
        store = CheckpointStore(store.db_path, phase, pause)
    if scenario.get("during_commit") and os.environ.get("BH_GAP_COMMIT_REEXEC") != "1":
        if not args.commit_shim or not args.commit_shim.is_file():
            raise ValueError("E_GAP_COMMIT_SHIM")
        environment = dict(os.environ)
        environment.update(
            LD_PRELOAD=str(args.commit_shim.resolve()),
            BH_GAP_COMMIT_REEXEC="1",
            BH_SQL_COMMIT_ARMED="0",
            BH_SQL_COMMIT_READY=str(args.ready),
            BH_SQL_COMMIT_BOUNDARY=str(args.ready.with_name("boundary.json")),
            BH_SQL_COMMIT_IDENTITY=json.dumps(_identity(args), sort_keys=True),
            BH_SQL_DATABASE_SUFFIX="run.sqlite3",
        )
        os.execve(  # noqa: S606 -- fixed current interpreter and owned test child
            sys.executable,
            [sys.executable, "-I", str(Path(__file__).resolve()), *sys.argv[1:]],
            environment,
        )
    if scenario.get("during_commit"):
        original = store.connect

        def armed_connect() -> sqlite3.Connection:
            connection = original()
            connection.set_trace_callback(
                lambda statement: (
                    os.environ.__setitem__("BH_SQL_COMMIT_ARMED", "1")
                    if statement == "COMMIT"
                    else None
                )
            )
            return connection

        store.connect = armed_connect  # type: ignore[method-assign]
    if operation == "GAP":
        if phase == "after_late_rejection":
            Ingestor(store).store_late_repair(scenario["delivery"])
            with closing(store.connect()) as connection, connection:
                _waiting(connection, scenario["run_id"])
        else:
            apply_result(store, scenario["delivery"])
        if scenario.get("during_commit"):
            raise RuntimeError("E_GAP_COMMIT_BOUNDARY")
        if phase not in BEFORE_STATEMENT:
            with closing(store.connect()) as connection:
                _checkpoint(args, connection, phase, hold=not scenario["no_kill"])
    else:
        with closing(store.connect()) as connection:
            if operation == "CAPACITY":
                decision = GenerationController().capacity_decision(
                    used=7, incoming=1, normal_limit=7, terminal_reserve=1
                )
                (case / "capacity-decision.json").write_text(
                    json.dumps(
                        {
                            **decision,
                            "normal_limit": 7,
                            "terminal_reserve": 1,
                            "used": 7,
                            "incoming": 1,
                            "unacknowledged_rows": read_gap_state(store.db_path.parent)["spool"][
                                "count"
                            ],
                        },
                        sort_keys=True,
                    )
                )
                if decision["accepted"]:
                    raise ValueError("E_CAPACITY_EXPECTED_STOP")
                current = connection.execute("SELECT * FROM stream_generations").fetchone()
                connection.execute("BEGIN IMMEDIATE")
                Ingestor._gap(connection, current, 0, 2, "f" * 64, 10, "STORAGE_SAFETY_STOP")
                connection.commit()
            elif operation == "CLOCK":
                if not connection.execute("SELECT 1 FROM clock_mappings").fetchone():
                    with connection:
                        mapping = _mapping(connection, scenario["run_id"])
                else:
                    mapping = connection.execute(
                        "SELECT clock_mapping_id FROM clock_mappings"
                    ).fetchone()[0]
                connection.execute("BEGIN IMMEDIATE")
                _close_mapping(connection, mapping)
                if phase == "after_mapping_closure_insert":
                    _checkpoint(args, connection, phase, hold=True)
                connection.commit()
            elif operation == "EPOCH":
                connection.execute("BEGIN IMMEDIATE")
                if scenario["epoch_step"] == "shock":
                    _shock_close(
                        connection,
                        scenario["run_id"],
                        shock_type="EQUIVALENT_UNKNOWN_SHOCK",
                    )
                elif scenario["epoch_step"] == "pending":
                    _pending(connection, scenario)
                elif scenario["epoch_step"] == "release":
                    _release(connection, scenario["run_id"])
                elif scenario["epoch_step"] == "new_shock":
                    _new_shock_pending(connection, scenario["run_id"])
                if scenario.get("checkpoint_before_commit"):
                    _checkpoint(args, connection, phase, hold=True)
                connection.commit()
            _checkpoint(args, connection, phase, hold=not scenario["no_kill"])


if __name__ == "__main__":
    main()"""Independent read-only reader for governed generation/coherence SQLite facts."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import sqlite3
import sys
from contextlib import closing
from pathlib import Path
from typing import Any

if __package__ in {None, ""}:
    import sys

    root = Path(__file__).resolve().parents[1]
    sys.path[:0] = [str(root / "src"), str(root)]

from moj_discovery.store import verified_ddl  # noqa: E402
from tools.restart_state_reader import read_restart_state  # noqa: E402


def read_gap_state(run_dir: Path) -> dict[str, Any]:
    state = read_restart_state(run_dir)
    path = run_dir / "run.sqlite3"
    with closing(sqlite3.connect(path.resolve().as_uri() + "?mode=ro", uri=True)) as connection:
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA query_only=ON")
        table_names = [
            row[0]
            for row in connection.execute(
                "SELECT name FROM sqlite_schema WHERE type='table' AND name NOT LIKE 'sqlite_%'"
            )
        ]
        extras = {
            table: sorted(
                (dict(row) for row in connection.execute(f'SELECT * FROM "{table}"')),  # noqa: S608
                key=lambda row: json.dumps(row, sort_keys=True),
            )
            for table in table_names
            if table not in state["tables"]
        }
    spool_path = run_dir.parent / "spool-events.jsonl"
    spool_rows = (
        [json.loads(line) for line in spool_path.read_text().splitlines() if line]
        if spool_path.is_file()
        else []
    )
    capacity_path = run_dir.parent / "capacity-decision.json"
    capacity = json.loads(capacity_path.read_text()) if capacity_path.is_file() else None
    return {
        **state,
        "ddl_sha256": hashlib.sha256(verified_ddl().encode()).hexdigest(),
        "tables": {**state["tables"], **extras},
        "spool": {"count": len(spool_rows), "rows": spool_rows},
        "capacity": capacity,
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("run_dir", type=Path)
    parser.add_argument("--identity", required=True, type=Path)
    args = parser.parse_args()
    identity = json.loads(args.identity.read_text())
    state = read_gap_state(args.run_dir)
    if state["run_id"] != identity.get("run_id"):
        raise ValueError("E_GAP_READER_IDENTITY")
    print(
        json.dumps(
            {
                "identity": identity,
                "state": state,
                "process": {
                    "pid": os.getpid(),
                    "ppid": os.getppid(),
                    "pgid": os.getpgid(0),
                    "start_ticks": Path("/proc/self/stat").read_text().split()[21],
                    "executable": str(Path(sys.executable).resolve()),
                    "executable_sha256": hashlib.sha256(
                        Path(sys.executable).resolve().read_bytes()
                    ).hexdigest(),
                    "argv": sys.argv,
                },
            },
            sort_keys=True,
        )
    )


if __name__ == "__main__":
    main()"""Fail-closed restart-state inspection and local process-crash execution."""

from __future__ import annotations

import hashlib
import json
import os
import secrets
import signal
import uuid
from collections.abc import Callable, Mapping
from pathlib import Path
from subprocess import Popen, TimeoutExpired
from time import monotonic, sleep
from typing import Any

ActualStateReader = Callable[[Path], Mapping[str, Any]]
CHECKPOINT_TIMEOUT_SECONDS = 10.0
CHECKPOINT_FIELDS = {
    "run_id",
    "case_id",
    "checkpoint_id",
    "component",
    "pid",
    "ordinal",
    "test_nonce",
}


def inspect_restart_state(
    observed: dict[str, object], expected: dict[str, object]
) -> dict[str, object]:
    if observed != expected:
        raise ValueError("E_RESTART_STATE_MISMATCH")
    return {"result": "PASS", "state": observed}


def _require_supported_termination() -> None:
    if os.name != "posix":
        raise RuntimeError(f"E_CRASH_TERMINATION_UNSUPPORTED:{os.name}")


def _kill_owned_child(child: Popen[bytes]) -> bool:
    _require_supported_termination()
    if child.poll() is not None:
        return False
    try:
        os.killpg(child.pid, signal.SIGKILL)
    except ProcessLookupError:
        return False
    return True


def _checkpoint(
    ready: Path, child: Popen[bytes], identity: dict[str, object], vector_id: str
) -> None:
    deadline = monotonic() + CHECKPOINT_TIMEOUT_SECONDS
    while not ready.is_file() and monotonic() < deadline:
        return_code = child.poll()
        if return_code is not None:
            raise RuntimeError(f"E_CRASH_CHILD_FAILED:{vector_id}:{return_code}")
        sleep(0.02)
    if not ready.is_file():
        raise RuntimeError(f"E_CRASH_CHECKPOINT_MISSING:{vector_id}")
    try:
        record = json.loads(ready.read_text())
    except (OSError, json.JSONDecodeError) as error:
        raise RuntimeError(f"E_CRASH_CHECKPOINT_INVALID:{vector_id}") from error
    if not isinstance(record, dict) or set(record) != CHECKPOINT_FIELDS or record != identity:
        raise RuntimeError(f"E_CRASH_CHECKPOINT_MISMATCH:{vector_id}")


def execute_crash_matrix(
    entries: list[dict[str, object]],
    command_prefix: list[str],
    workspace: Path,
    *,
    state_reader: ActualStateReader | None = None,
    prepare_case: Callable[[Path], None] | None = None,
    recover_case: Callable[[Path], None] | None = None,
    validate_boundary: Callable[[Path, dict[str, object]], None] | None = None,
    compare_state: Callable[
        [dict[str, object], dict[str, object]], dict[str, object]
    ] = inspect_restart_state,
) -> dict[str, object]:
    if state_reader is None:
        raise ValueError("E_ACTUAL_STATE_READER_REQUIRED")
    _require_supported_termination()
    workspace.mkdir(parents=True, exist_ok=True)
    run_id = str(uuid.uuid4())
    run_directory = workspace / f"run-{run_id}"
    run_directory.mkdir()
    executed: list[str] = []
    records: list[dict[str, object]] = []
    for ordinal, entry in enumerate(entries):
        vector_id = entry.get("vector_id")
        checkpoint_id = entry.get("crash_checkpoint")
        component = entry.get("harness")
        expected = entry.get("expected_post_restart_state")
        if (
            not isinstance(vector_id, str)
            or not vector_id
            or not isinstance(checkpoint_id, str)
            or not checkpoint_id
            or not isinstance(component, str)
            or not component
            or not isinstance(expected, dict)
        ):
            raise ValueError("E_CRASH_CASE_INVALID")
        case_directory = run_directory / f"case-{ordinal:04d}"
        case_directory.mkdir()
        if prepare_case is not None:
            prepare_case(case_directory)
        ready = case_directory / "checkpoint.json"
        nonce = secrets.token_hex(16)
        with (
            (case_directory / "child.stdout").open("wb") as stdout,
            (case_directory / "child.stderr").open("wb") as stderr,
        ):
            child = Popen(  # noqa: S603 - command is a closed caller-supplied test harness
                [
                    *command_prefix,
                    "--vector-id",
                    vector_id,
                    "--ready",
                    str(ready),
                    "--run-id",
                    run_id,
                    "--case-id",
                    vector_id,
                    "--checkpoint-id",
                    checkpoint_id,
                    "--component",
                    component,
                    "--ordinal",
                    str(ordinal),
                    "--test-nonce",
                    nonce,
                    "--hold",
                ],
                stdout=stdout,
                stderr=stderr,
                start_new_session=True,
            )
            identity: dict[str, object] = {
                "run_id": run_id,
                "case_id": vector_id,
                "checkpoint_id": checkpoint_id,
                "component": component,
                "pid": child.pid,
                "ordinal": ordinal,
                "test_nonce": nonce,
            }
            try:
                _checkpoint(ready, child, identity, vector_id)
                if validate_boundary is not None:
                    validate_boundary(case_directory, identity)
                killed = _kill_owned_child(child)
                return_code = child.wait(timeout=5)
                if not killed or return_code != -signal.SIGKILL:
                    if return_code != 0:
                        raise RuntimeError(f"E_CRASH_CHILD_FAILED:{vector_id}:{return_code}")
                    raise RuntimeError(f"E_CRASH_CHILD_NOT_KILLED:{vector_id}")
                if recover_case is not None:
                    recover_case(case_directory)
                try:
                    observed = dict(state_reader(case_directory))
                except Exception as error:
                    raise RuntimeError(f"E_ACTUAL_STATE_READER_FAILED:{vector_id}") from error
                observation_path = case_directory / "comparison-state.json"
                observation_path.write_text(json.dumps(observed, sort_keys=True))
                # Only the parent writes the oracle, after all child work has finished.
                (case_directory / "expected-state.json").write_text(
                    json.dumps(expected, sort_keys=True)
                )
                comparison = compare_state(observed, expected)
                executed.append(vector_id)
                records.append(
                    {
                        "vector_id": vector_id,
                        "case_directory": str(case_directory),
                        "pid": child.pid,
                        "command": child.args,
                        "termination_returncode": return_code,
                        "termination_mechanism": "POSIX_OWNED_PROCESS_GROUP_SIGKILL",
                        "checkpoint": identity,
                        "checkpoint_sha256": hashlib.sha256(ready.read_bytes()).hexdigest(),
                        "actual_state_sha256": hashlib.sha256(
                            observation_path.read_bytes()
                        ).hexdigest(),
                        "comparison": comparison["result"],
                    }
                )
            except Exception as error:
                (case_directory / "failure.json").write_text(
                    json.dumps(
                        {
                            "vector_id": vector_id,
                            "status": "FAIL",
                            "error": str(error),
                            "checkpoint_identity": identity,
                        },
                        sort_keys=True,
                    )
                )
                raise
            finally:
                _kill_owned_child(child)
                try:
                    child.wait(timeout=5)
                except TimeoutExpired as error:
                    raise RuntimeError(f"E_CRASH_CHILD_REAP_FAILED:{vector_id}") from error
    return {
        "result": "PASS",
        "executed_vector_ids": executed,
        "killed_child_count": len(executed),
        "records": records,
    }"""Issue one host-authority review launch authorization after all bindings are measured."""

# ruff: noqa: E402, I001, E501
from __future__ import annotations

import argparse
import base64
import hashlib
import json
import secrets
import shutil
import sqlite3
import stat
import sys
import uuid
from contextlib import closing
from datetime import UTC, datetime, timedelta
from pathlib import Path
from typing import Any, cast

RUNTIME_ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(RUNTIME_ROOT), str(RUNTIME_ROOT / "src")]

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey, Ed25519PublicKey
import rfc8785
from moj_discovery.canonical import parse_strict_json

from tools.bootstrap_review_authority import bootstrap_review_authority
from moj_discovery.review_authorization import (
    review_identity,
    sign_review_launch_authorization,
    verify_review_launch_authorization,
)


def review_public_key(authority_config: dict[str, object]) -> tuple[Ed25519PublicKey, int]:
    record_path = Path(cast(str, authority_config["public_key_path"]))
    _regular_hash(record_path)
    record = json.loads(record_path.read_text())
    encoded = record.get("public_key_b64url") if isinstance(record, dict) else None
    epoch = record.get("trust_epoch") if isinstance(record, dict) else None
    if not isinstance(encoded, str) or type(epoch) is not int or epoch < 0:
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    raw = base64.urlsafe_b64decode(encoded + "=" * (-len(encoded) % 4))
    if len(raw) != 32 or base64.urlsafe_b64encode(raw).decode().rstrip("=") != encoded:
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    return Ed25519PublicKey.from_public_bytes(raw), epoch


def authorized_review_context(
    authorization: dict[str, object],
    authority: dict[str, object],
    *,
    runtime_root: Path = RUNTIME_ROOT,
) -> dict[str, object]:
    config = review_config_for_authorization(authorization, runtime_root=runtime_root)
    public, epoch = review_public_key(authority)
    verify_review_launch_authorization(
        authorization,
        public,
        cast(str, config["role"]),
        cast(str, config["workspace_root"]),
        cast(str, authorization["pack_zip_sha256"]),
        expected_host_boot_id=Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
        expected_trust_epoch=epoch,
    )
    return measure_review_context(config, authorization)


def review_config_for_role(
    role: str, version: int, *, runtime_root: Path = RUNTIME_ROOT
) -> dict[str, object]:
    names = {"IMPLEMENTATION_READINESS_REVIEWER": "review-a", "CYBERSECURITY_REVIEWER": "review-b"}
    if role not in names or type(version) is not int or version not in {1, 2, 3}:
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    path = runtime_root / "review-config" / f"{names[role]}.v{version}.json"
    _regular_hash(path)
    config = json.loads(path.read_bytes())
    if (
        not isinstance(config, dict)
        or config.get("role") != role
        or config.get("schema_version") != f"review-config/v{version}"
    ):
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    return cast(dict[str, object], config)


def resolve_review_run(template: dict[str, object], run_id: str) -> dict[str, object]:
    """Resolve only the frozen role's output/scratch prefixes with a canonical UUID."""
    if template.get("schema_version") != "review-config/v3":
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    parsed = uuid.UUID(run_id)
    if str(parsed) != run_id or parsed.version != 4:
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    workspace = cast(str, template["workspace_root"])
    output = cast(str, template["output_root"])

    def resolve(value: Any) -> Any:
        if isinstance(value, str):
            for prefix in (workspace, output):
                if value == prefix or value.startswith(prefix + "/"):
                    return prefix + "/" + run_id + value[len(prefix) :]
        elif isinstance(value, list):
            return [resolve(item) for item in value]
        elif isinstance(value, dict):
            return {key: resolve(item) for key, item in value.items()}
        return value

    config = cast(dict[str, object], resolve(template))
    input_root = Path(cast(str, template["scope_input_root"])) / run_id
    config.update(
        review_run_id=run_id,
        prompt_template_path=template["prompt_path"],
        prompt_path=str(input_root / "prompt.md"),
        scope_path=str(input_root / "scope.json"),
    )
    launch_path = Path(cast(str, template["authorization_path"]))
    config["authorization_path"] = str(launch_path.with_name(run_id + ".json"))
    return config


def review_config_for_authorization(
    authorization: dict[str, object],
    *,
    runtime_root: Path = RUNTIME_ROOT,
) -> dict[str, object]:
    role = cast(str, authorization["review_role"])
    if authorization.get("schema_version") != "review-launch-authorization/v2":
        return review_config_for_role(role, 1, runtime_root=runtime_root)
    label = "a" if role == "IMPLEMENTATION_READINESS_REVIEWER" else "b"
    if (runtime_root / f"review-config/review-{label}.v3.json").exists():
        template = review_config_for_role(role, 3, runtime_root=runtime_root)
        resolved = resolve_review_run(template, cast(str, authorization["review_run_id"]))
        if authorization["workspace_root"] == resolved["workspace_root"]:
            return resolved
    return review_config_for_role(role, 2, runtime_root=runtime_root)


def _scope_finding_id(role: object, scope: dict[str, Any]) -> str:
    if scope.get("kind") == "CANDIDATE_READINESS":
        suffix = {"IMPLEMENTATION_READINESS_REVIEWER": "A", "CYBERSECURITY_REVIEWER": "B"}.get(
            cast(str, role)
        )
        if suffix is not None:
            return "PART-B-CANDIDATE-" + suffix
    elif role == "CYBERSECURITY_REVIEWER" and scope.get("kind") in {
        "OPERATOR_DISCOVERY_TOOL",
        "CAPTURE_PROFILE",
        "LIVE_SECURITY",
    }:
        return "PART-B-SCOPE"
    raise ValueError("E_REVIEW_SCOPE_INPUT")


def _scope_prompt(template: bytes, record: dict[str, Any], role: object) -> bytes:
    return (
        template
        + b"\n\n## Exact review scope\n\n"
        + rfc8785.dumps(record)
        + (
            b"\n\nReview the named bytes. Include exactly one non-blocking "
            + _scope_finding_id(role, record["scope"]).encode()
            + b" finding "
            b"whose sole evidence ID is sha256: followed by the SHA-256 of the canonical scope. "
            b"Missing observations remain HOLD. Production authority is NONE.\n"
        )
    )


def _validate_scope_inputs(
    role: object,
    scope: dict[str, Any],
    contents: dict[str, bytes],
) -> None:
    """Require the complete named scope, including raw versus canonical hash semantics."""
    _scope_finding_id(role, scope)
    kind = scope["kind"]
    fields = {
        "CANDIDATE_READINESS": {"kind", "expires_at"},
        "OPERATOR_DISCOVERY_TOOL": {
            "kind",
            "expires_at",
            "source_tree_sha256",
            "capture_source_sha256",
            "config_sha256",
            "fixture_ids",
            "exact_url",
            "selectors",
            "profile_name",
            "max_duration_seconds",
            "max_http_attempts",
        },
        "CAPTURE_PROFILE": {
            "kind",
            "expires_at",
            "source_tree_sha256",
            "capture_source_sha256",
            "profile_sha256",
            "bindings",
            "sample_refs",
            "max_matches",
        },
        "LIVE_SECURITY": {
            "kind",
            "expires_at",
            "source_tree_sha256",
            "config_sha256",
            "artifacts",
            "max_matches",
            "previous_scope_refs",
        },
    }
    if set(scope) != fields[kind]:
        raise ValueError("E_REVIEW_SCOPE_INPUT")
    hashes = {name: hashlib.sha256(raw).hexdigest() for name, raw in contents.items()}
    expected: dict[str, str] = {}
    if kind in {"OPERATOR_DISCOVERY_TOOL", "LIVE_SECURITY"}:
        matches = [name for name, digest in hashes.items() if digest == scope["config_sha256"]]
        if len(matches) != 1:
            raise ValueError("E_REVIEW_SCOPE_INPUT")
        config_name = matches[0]
        expected[config_name] = scope["config_sha256"]
        if kind == "LIVE_SECURITY":
            cfg = cast(dict[str, Any], parse_strict_json(contents[config_name]))
            refs = {
                "provider": cfg["gates"]["provider_feasibility_path"],
                "capture": cfg["gates"]["capture_review_path"],
                "profile": cfg["operator"]["capture_profile_path"],
                "platform": cfg["runtime"]["platform_qualification_path"],
                "offline": cfg["gates"]["offline_result_path"],
            }
            if set(scope["artifacts"]) != set(refs) or len(set(refs.values())) != len(refs):
                raise ValueError("E_REVIEW_SCOPE_INPUT")
            expected.update({path: scope["artifacts"][name] for name, path in refs.items()})
            for ref in scope["previous_scope_refs"].values():
                if set(ref) != {"path", "sha256"} or ref["path"] in expected:
                    raise ValueError("E_REVIEW_SCOPE_INPUT")
                expected[ref["path"]] = ref["sha256"]
    elif kind == "CAPTURE_PROFILE":
        expected.update(scope["sample_refs"])
        profiles = [
            name
            for name, raw in contents.items()
            if name not in expected
            and hashlib.sha256(rfc8785.dumps(cast(Any, parse_strict_json(raw)))).hexdigest()
            == scope["profile_sha256"]
        ]
        if len(profiles) != 1 or not expected:
            raise ValueError("E_REVIEW_SCOPE_INPUT")
        expected[profiles[0]] = hashes[profiles[0]]
    if hashes != expected:
        raise ValueError("E_REVIEW_SCOPE_INPUT")


def _scope_record(config: dict[str, object]) -> tuple[dict[str, Any], dict[str, str]]:
    path = Path(cast(str, config["scope_path"]))
    snapshots = {str(path): _regular_hash(path)}
    raw = path.read_bytes()
    if len(raw) > 65536:
        raise ValueError("E_REVIEW_SCOPE_INPUT")
    value = parse_strict_json(raw)
    if (
        not isinstance(value, dict)
        or set(value) != {"schema_version", "scope", "files"}
        or value["schema_version"] != "part-b-review-inputs/v1"
        or not isinstance(value["scope"], dict)
        or not isinstance(value["files"], list)
        or len(value["files"]) > 32
    ):
        raise ValueError("E_REVIEW_SCOPE_INPUT")
    expires = datetime.fromisoformat(str(value["scope"].get("expires_at")))
    if expires.tzinfo is None or expires <= datetime.now(UTC):
        raise ValueError("E_REVIEW_SCOPE_INPUT")
    expected_names = {"scope.json", "prompt.md"}
    contents = {}
    for index, row in enumerate(value["files"]):
        name = f"input-{index:02d}.json"
        if (
            not isinstance(row, dict)
            or set(row) != {"name", "path", "sha256"}
            or row["name"] != name
            or not isinstance(row["path"], str)
            or not row["path"].startswith(".local/part-b/")
            or ".." in Path(row["path"]).parts
            or row["path"] in contents
        ):
            raise ValueError("E_REVIEW_SCOPE_INPUT")
        selected = path.parent / name
        if selected.stat().st_size > 1048576 or _regular_hash(selected) != row["sha256"]:
            raise ValueError("E_REVIEW_SCOPE_INPUT")
        snapshots[str(selected)] = row["sha256"]
        contents[row["path"]] = selected.read_bytes()
        expected_names.add(name)
    _validate_scope_inputs(config["role"], value["scope"], contents)
    if {item.name for item in path.parent.iterdir()} != expected_names:
        raise ValueError("E_REVIEW_SCOPE_INPUT")
    template = Path(cast(str, config["prompt_template_path"]))
    prompt = Path(cast(str, config["prompt_path"]))
    snapshots[str(template)] = _regular_hash(template)
    snapshots[str(prompt)] = _regular_hash(prompt)
    if prompt.read_bytes() != _scope_prompt(template.read_bytes(), value, config["role"]):
        raise ValueError("E_REVIEW_SCOPE_INPUT")
    return cast(dict[str, Any], value), snapshots


def prepare_review_scope(
    config: dict[str, object],
    scope: dict[str, Any],
    inputs: list[Path],
) -> None:
    """Copy only explicitly named non-secret local JSON; never discover credentials."""
    boundary = Path(cast(list[str], config["input_roots"])[1]) / ".local/part-b"
    if len(inputs) > 32 or len(set(inputs)) != len(inputs):
        raise ValueError("E_REVIEW_SCOPE_INPUT")
    contents = {}
    for path in inputs:
        if (
            not path.is_relative_to(boundary)
            or path.suffix != ".json"
            or path != path.resolve(strict=True)
            or path.stat().st_size > 1048576
        ):
            raise ValueError("E_REVIEW_SCOPE_INPUT")
        before = _regular_hash(path)
        raw = path.read_bytes()
        if hashlib.sha256(raw).hexdigest() != before:
            raise ValueError("E_REVIEW_SCOPE_INPUT")
        contents[str(path.relative_to(boundary.parents[1]))] = raw
    _validate_scope_inputs(config["role"], scope, contents)
    folder = Path(cast(str, config["scope_path"])).parent
    if folder != folder.resolve():
        raise ValueError("E_REVIEW_SCOPE_INPUT")
    folder.mkdir(parents=True, exist_ok=False, mode=0o700)
    rows = []
    for index, (source, raw) in enumerate(contents.items()):
        name = f"input-{index:02d}.json"
        with (folder / name).open("xb") as stream:
            stream.write(raw)
        rows.append({"name": name, "path": source, "sha256": hashlib.sha256(raw).hexdigest()})
    record: dict[str, Any] = {
        "schema_version": "part-b-review-inputs/v1",
        "scope": scope,
        "files": rows,
    }
    with (folder / "scope.json").open("xb") as stream:
        stream.write(rfc8785.dumps(record) + b"\n")
    template = Path(cast(str, config["prompt_template_path"]))
    _regular_hash(template)
    with (folder / "prompt.md").open("xb") as stream:
        stream.write(_scope_prompt(template.read_bytes(), record, config["role"]))
    _scope_record(config)


def validate_review_scope(config: dict[str, object], result: dict[str, Any]) -> None:
    if config.get("schema_version") != "review-config/v3":
        return
    record, _ = _scope_record(config)
    finding_id = _scope_finding_id(config["role"], record["scope"])
    findings = [row for row in result["findings"] if row["finding_id"] == finding_id]
    if len(findings) != 1 or findings[0]["evidence_ids"] != [
        "sha256:" + hashlib.sha256(rfc8785.dumps(record["scope"])).hexdigest()
    ]:
        raise ValueError("E_REVIEW_SCOPE_INPUT")


def validate_review_authority_state(
    authorization: dict[str, object],
    authority: dict[str, object],
) -> None:
    # Public trust metadata determines the state location; no signing key is read.
    path = Path(cast(str, authority["public_key_path"])).parent / "state.sqlite"
    _regular_hash(path)
    with closing(sqlite3.connect(f"file:{path}?mode=ro", uri=True)) as connection:
        epoch = connection.execute(
            "SELECT trust_epoch FROM authority_state WHERE key_id = ?",
            (authorization["issuer_key_id"],),
        ).fetchone()
        consumed = connection.execute(
            "SELECT 1 FROM consumed_serials WHERE authority_key_id = ? AND one_use_serial = ?",
            (authorization["issuer_key_id"], authorization["one_use_serial"]),
        ).fetchone()
        revoked = connection.execute(
            "SELECT 1 FROM revocations WHERE authorization_id = ?",
            (authorization["authorization_id"],),
        ).fetchone()
    if epoch != (authorization["trust_epoch"],) or consumed is None or revoked is not None:
        raise ValueError("E_REVIEW_AUTHORITY_STATE")


def review_execution_root(authorization: dict[str, object], authority: dict[str, object]) -> Path:
    run_id = cast(str, authorization["review_run_id"])
    parsed = uuid.UUID(run_id)
    if str(parsed) != run_id or parsed.version != 4:
        raise ValueError("E_REVIEW_EXECUTION")
    public = Path(cast(str, authority["public_key_path"]))
    _regular_hash(public)
    root = public.parent / "executions" / run_id
    if root != root.resolve() or any(
        root.is_relative_to(Path(cast(str, row["source_root"])))
        for row in cast(list[dict[str, object]], authorization["input_mounts"])
    ):
        raise ValueError("E_REVIEW_EXECUTION")
    return root


def _regular_hash(path: Path) -> str:
    if (
        path.is_symlink()
        or not path.is_file()
        or stat.S_ISLNK(path.lstat().st_mode)
        or path.stat().st_nlink != 1
        or path != path.resolve(strict=True)
    ):
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _review_environment_binding(metadata: dict[str, object]) -> str:
    """Reuse the qualified byte projections, never executable names or stat caches."""
    from tools.prepare_review_workspace import _dependency_projection, _sha256, _python_runtime_projection
    from tools.run_native_ingestor_qualification import dependency_binding
    from tools.verify_repair_evidence import capture_binding, _typescript_compile_binding

    declaration = cast(dict[str, Any], metadata["producer_environment"])
    runtime = Path(cast(list[str], metadata["input_roots"])[1])
    qualified = Path(declaration["python_environment"])
    current = capture_binding()
    executables = {}
    for name in ("uv", "pnpm", "node", "bwrap"):
        selected = shutil.which(name)
        if selected is None:
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        resolved = Path(selected).resolve(strict=True)
        executables[name] = {
            "path": selected,
            "resolved": str(resolved),
            "sha256": _sha256(resolved),
        }
    paths = [
        *declaration["live_files"],
        declaration["path_translation_executable"],
        declaration["python_executable"],
        declaration["node_executable"],
    ]
    python_runtime = _python_runtime_projection(metadata)
    payload = {
        "standalone_python": None if python_runtime is None else (str(python_runtime[0]), python_runtime[1]),
        "environment": current["environment"],
        "compiler": _typescript_compile_binding(current),
        "executables": executables,
        "live_files": {name: _sha256(Path(name).resolve(strict=True)) for name in paths},
        "python": _dependency_projection(qualified / "lib", qualified, python=True),
        "node": _dependency_projection(runtime / "node_modules", runtime, python=False),
        "extension": _dependency_projection(
            runtime / "extension/node_modules", runtime, python=False
        ),
        "native": dependency_binding(),
    }
    return hashlib.sha256(rfc8785.dumps(payload)).hexdigest()


def recheck_review_context(context: dict[str, object]) -> None:
    for name, expected in cast(dict[str, str], context["snapshots"]).items():
        if _regular_hash(Path(name)) != expected:
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
    if "pack_files" in context:
        from tools.seal_review_pack import _safe_files

        pack = Path(cast(str, context["pack"]))
        if [
            name for name, _ in _safe_files(pack, include_manifest=True, strict_directories=True)
        ] != context["pack_files"]:
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
    if "inventory" in context:
        from tools.build_candidate_qualification_receipt import _inventory
        from tools.run_command_registry import collect_generated_outputs

        runtime = Path(cast(str, context["runtime"]))
        if _inventory(runtime, collect_generated_outputs(runtime)) != context["inventory"]:
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
    if (
        "environment_binding" in context
        and _review_environment_binding(cast(dict[str, object], context["environment_config"]))
        != context["environment_binding"]
    ):
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    config = cast(dict[str, object], context.get("config", {}))
    if config.get("schema_version") == "review-config/v3":
        _scope_record(config)


def measure_review_context(
    config: dict[str, object], authorization: dict[str, object] | None = None
) -> dict[str, object]:
    """Bounded locator extraction, then actual sealed verification, before authority."""
    from tools.build_candidate_qualification_receipt import _read_bytes
    from tools.seal_review_pack import verify_sealed_review_pack

    try:
        if config.get("schema_version") not in {"review-config/v2", "review-config/v3"}:
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        version = 3 if config["schema_version"] == "review-config/v3" else 2
        inputs = cast(list[str], config["input_roots"])
        if not isinstance(inputs, list) or len(inputs) != 5:
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        pack, runtime = Path(inputs[0]), Path(inputs[1])
        if pack != pack.resolve(strict=True) or runtime != runtime.resolve(strict=True):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        manifest_path = pack / "MANIFEST_SHA256.json"
        snapshots = {str(manifest_path): _regular_hash(manifest_path)}
        manifest = json.loads(manifest_path.read_bytes())
        entries = manifest["entries"]
        if manifest.get("schema_version") != "manifest-sha256/v1" or not isinstance(entries, list):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")

        def member(path: Path) -> bytes:
            relative = path.relative_to(pack).as_posix()
            if path != path.resolve(strict=True):
                raise ValueError("E_REVIEW_LAUNCH_INPUT")
            digest = _regular_hash(path)
            raw = path.read_bytes()
            rows = [row for row in entries if isinstance(row, dict) and row.get("path") == relative]
            if rows != [{"path": relative, "size": str(len(raw)), "sha256": digest}]:
                raise ValueError("E_REVIEW_LAUNCH_INPUT")
            snapshots[str(path)] = digest
            return raw

        metadata = review_config_for_role(
            "IMPLEMENTATION_READINESS_REVIEWER", version, runtime_root=runtime
        )
        if version == 3:
            metadata = resolve_review_run(metadata, cast(str, config["review_run_id"]))
        used: dict[str, bytes] = {}
        for selected in (config, metadata):
            role = cast(str, selected["role"])
            template = review_config_for_role(role, version, runtime_root=runtime)
            expected = (
                resolve_review_run(template, cast(str, config["review_run_id"]))
                if version == 3
                else template
            )
            if selected != expected:
                raise ValueError("E_REVIEW_LAUNCH_INPUT")
            label = "a" if role == "IMPLEMENTATION_READINESS_REVIEWER" else "b"
            relative = f"docs/configs/review-{label}.v{version}.json"
            raw = member(pack / relative)
            materialized = runtime / f"review-config/review-{label}.v{version}.json"
            snapshots[str(materialized)] = _regular_hash(materialized)
            if materialized.read_bytes() != raw or json.loads(raw) != template:
                raise ValueError("E_REVIEW_LAUNCH_INPUT")
            used[relative] = raw
            registry_relative = "docs/registries/" + (
                "review-command-registry.v1.json"
                if label == "a"
                else "cybersecurity-command-registry.v1.json"
            )
            if selected["command_registry_path"] != str(pack / registry_relative):
                raise ValueError("E_REVIEW_LAUNCH_INPUT")
            used[registry_relative] = member(pack / registry_relative)
        if any(
            config[key] != metadata[key]
            for key in ("input_roots", "input_mounts", "seal_inputs", "repository_identity")
        ):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        registry = json.loads(used["docs/registries/review-command-registry.v1.json"])
        if (
            set(registry) != {"schema_version", "commands"}
            or registry["schema_version"] != "review-command-registry/v1"
        ):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        rows = registry["commands"]
        if not isinstance(rows, list) or len({row["command_id"] for row in rows}) != len(rows):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        leaf = [row for row in rows if row.get("command_id") == "A_CHECK_DESCENDANT"]
        if (
            len(leaf) != 1
            or not isinstance(leaf[0].get("argv"), list)
            or len(leaf[0]["argv"]) != 21
        ):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        recorded = leaf[0]["argv"][16]
        if recorded != str(
            runtime / "vendor/hybrid-discovery-v6.3.6/docs/configs/full-verifier-controller.v2.json"
        ):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        named_config = pack / "docs/configs/full-verifier-controller.v2.json"
        named_receipt = pack / "docs/receipts/descendant-repository-qualification-receipt.json"
        retained_manifest, retained_root = (
            pack / "evidence/retained-artifact-manifest.json",
            pack / "evidence/retained",
        )
        argv = [
            "uv",
            "run",
            "--frozen",
            "--offline",
            "python",
            "tools/qualify_descendant_repository.py",
            "--root",
            str(runtime),
            "--config",
            str(named_config),
            "--check-only",
            "--receipt",
            str(named_receipt),
            "--pack",
            str(pack),
            "--recorded-config",
            recorded,
            "--retained-manifest",
            str(retained_manifest),
            "--retained-root",
            str(retained_root),
        ]
        expected_row = {
            "command_id": "A_CHECK_DESCENDANT",
            "purpose": "A_CHECK_DESCENDANT",
            "cwd": str(runtime),
            "argv": argv,
            "expected_exit": 0,
            "kind": "review-leaf",
            "available_at": "SEALED",
            "network": "DENY",
            "authenticated_operator_access": "DENY",
            "provider_access": "DENY",
        }
        if leaf != [expected_row] or config["repository_identity"] != {
            "kind": "DESCENDANT",
            "receipt": str(named_receipt),
        }:
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        seal_inputs = cast(dict[str, str], config["seal_inputs"])
        if seal_inputs != {"attestation": inputs[2], "zip": inputs[3], "sidecar": inputs[4]}:
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        for path in (
            named_config,
            named_receipt,
            retained_manifest,
            Path(cast(str, config["prompt_template_path" if version == 3 else "prompt_path"])),
        ):
            member(path)
        if version == 3:
            _scope, scope_snapshots = _scope_record(config)
            snapshots.update(scope_snapshots)
        for locator in inputs[2:]:
            snapshots[locator] = _regular_hash(Path(locator))
        mounts = cast(list[dict[str, object]], config["input_mounts"])
        if mounts != [
            {"source_root": value, "workspace_mount": value, "mode": "READ_ONLY"}
            for value in inputs
        ]:
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        if authorization is not None and (
            authorization.get("schema_version") != "review-launch-authorization/v2"
            or authorization.get("review_role") != config["role"]
            or authorization.get("workspace_root") != config["workspace_root"]
            or authorization.get("allowed_output_root") != config["output_root"]
            or authorization.get("excluded_roots") != config["excluded_roots"]
            or authorization.get("pack_manifest_sha256") != snapshots[str(manifest_path)]
            or authorization.get("command_registry_sha256")
            != snapshots[cast(str, config["command_registry_path"])]
            or authorization.get("prompt_sha256") != snapshots[cast(str, config["prompt_path"])]
        ):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        from tools.build_candidate_qualification_receipt import _inventory
        from tools.run_command_registry import collect_generated_outputs
        from tools.seal_review_pack import _safe_files

        pack_files = _safe_files(pack, include_manifest=True, strict_directories=True)
        snapshots.update({str(path): _regular_hash(path) for _, path in pack_files})
        inventory = _inventory(runtime, collect_generated_outputs(runtime))
        environment_binding = _review_environment_binding(metadata)
        measured: dict[str, Any] = {}
        seal = verify_sealed_review_pack(
            pack,
            Path(inputs[3]),
            Path(inputs[4]),
            Path(inputs[2]),
            config_path=named_config,
            recorded_config_locator=recorded,
            retained_manifest=retained_manifest,
            retained_root=retained_root,
            context_out=measured,
        )
        controller, artifacts = measured["controller"], measured["artifacts"]
        if (
            controller.current_checkout_root != runtime
            or controller.descendant_repository_receipt is None
        ):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        for relative, raw in used.items():
            if raw != _read_bytes(controller.governed_source_pack / relative, artifacts):
                raise ValueError("E_REVIEW_LAUNCH_INPUT")
        if named_receipt.read_bytes() != _read_bytes(
            controller.descendant_repository_receipt, artifacts
        ):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        identity = review_identity(seal)
        roots = [
            seal["governed_content_root"],
            identity["repository_file_tree_root_sha256"],
            *[snapshots[path] for path in inputs[2:]],
        ]
        measured_mounts = [
            {**mount, "content_root_sha256": root}
            for mount, root in zip(mounts, roots, strict=True)
        ]
        if (
            seal["schema_version"] != "external-seal-attestation/v7"
            or seal["artifact_type"] != "RUNTIME_PACK"
            or seal["zip_sha256"] != snapshots[inputs[3]]
            or seal["manifest_sha256"] != snapshots[str(manifest_path)]
        ):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        if authorization is not None and (
            review_identity(authorization) != identity
            or authorization["input_mounts"] != measured_mounts
            or authorization["pack_zip_sha256"] != seal["zip_sha256"]
        ):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        context: dict[str, object] = {
            "seal": seal,
            "mounts": measured_mounts,
            "snapshots": snapshots,
            "transport": expected_row,
            "controller": controller,
            "artifacts": artifacts,
            "config": config,
        }
        # All sealed members and the current inventory are checked at reuse points;
        # a caller-supplied PASS or unchanged stat metadata is never sufficient.
        context.update(
            pack=str(pack),
            pack_files=[name for name, _ in pack_files],
            runtime=str(runtime),
            inventory=inventory,
            environment_binding=environment_binding,
            environment_config=metadata,
        )
        recheck_review_context(context)
        return context
    except (OSError, ValueError, KeyError, TypeError, AttributeError) as error:
        raise ValueError("E_REVIEW_LAUNCH_INPUT") from error


def _directory_root(path: Path, record: str, field: str) -> str:
    if path.is_symlink() or not path.is_dir() or stat.S_ISLNK(path.lstat().st_mode):
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    value = json.loads((path / record).read_text())
    root = value.get(field) if isinstance(value, dict) else None
    if not isinstance(root, str) or len(root) != 64:
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    return root


def _runtime_root(path: Path, receipt_path: Path) -> str:
    from tools.qualify_zero_parent_baseline import _repository_identity

    receipt = json.loads(receipt_path.read_text())
    commit, tree, root = _repository_identity(path)
    if not isinstance(receipt, dict) or (
        receipt.get("baseline_commit"),
        receipt.get("baseline_tree"),
        receipt.get("baseline_file_root_sha256"),
    ) != (commit, tree, root):
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    return root


def _mount_roots(config: dict[str, object]) -> list[dict[str, object]]:
    if config.get("schema_version") == "review-config/v2":
        return cast(list[dict[str, object]], measure_review_context(config)["mounts"])
    mounts = config.get("input_mounts")
    inputs = config.get("input_roots")
    if (
        not isinstance(mounts, list)
        or not isinstance(inputs, list)
        or len(mounts) != 5
        or len(inputs) != 5
    ):
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    result: list[dict[str, object]] = []
    for index, mount in enumerate(mounts):
        if not isinstance(mount, dict) or mount.get("mode") != "READ_ONLY":
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        source = mount.get("source_root")
        if (
            source != mount.get("workspace_mount")
            or source != inputs[index]
            or not isinstance(source, str)
        ):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        path = Path(source)
        if index == 0:
            root = _directory_root(path, "GOVERNED_CONTENT_ROOT.json", "root_sha256")
        elif index == 1:
            root = _runtime_root(
                path,
                Path(cast(str, inputs[0])) / "docs/receipts/repo0-baseline-receipt.json",
            )
        else:
            root = _regular_hash(path)
        result.append({**mount, "content_root_sha256": root})
    if len({cast(str, item["source_root"]) for item in result}) != 5:
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    return result


def issue_review_launch_authorization(
    config: dict[str, object],
    authority_config: dict[str, object],
    output: Path,
    *,
    now: datetime | None = None,
    scope: dict[str, Any] | None = None,
    scope_inputs: list[Path] | None = None,
) -> dict[str, object]:
    if (
        config.get("network") != "DENY"
        or config.get("role") not in {"IMPLEMENTATION_READINESS_REVIEWER", "CYBERSECURITY_REVIEWER"}
        or authority_config.get("production_authority") != "NONE"
    ):
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    if config.get("schema_version") not in {
        "review-config/v1",
        "review-config/v2",
        "review-config/v3",
    }:
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    trusted_now = (now or datetime.now(UTC)).astimezone(UTC)
    duration = 28800 if config.get("schema_version") == "review-config/v3" else 14400
    run_id = str(uuid.uuid4())
    if config.get("schema_version") == "review-config/v3":
        if config != review_config_for_role(
            cast(str, config["role"]), 3, runtime_root=RUNTIME_ROOT
        ):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        if config.get("scope_input_root") != str(RUNTIME_ROOT / ".local/part-b/review-inputs"):
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        config = resolve_review_run(config, run_id)
        if output != Path(cast(str, config["authorization_path"])).parent:
            raise ValueError("E_REVIEW_LAUNCH_INPUT")
        prepare_review_scope(
            config,
            scope
            if scope is not None
            else {
                "kind": "CANDIDATE_READINESS",
                "expires_at": (trusted_now + timedelta(seconds=duration)).isoformat(),
            },
            scope_inputs or [],
        )
        output = Path(cast(str, config["authorization_path"]))
    elif scope is not None or scope_inputs:
        raise ValueError("E_REVIEW_SCOPE_INPUT")
    current = config.get("schema_version") in {"review-config/v2", "review-config/v3"}
    context = measure_review_context(config) if current else None
    if context is not None:
        recheck_review_context(context)
    bootstrap_review_authority(authority_config, initialize_if_absent=False)
    private_path = Path(cast(str, authority_config["private_key_path"]))
    public = json.loads(Path(cast(str, authority_config["public_key_path"])).read_text())
    private = serialization.load_pem_private_key(private_path.read_bytes(), password=None)
    if not isinstance(private, Ed25519PrivateKey) or not isinstance(public, dict):
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    seal_inputs = config.get("seal_inputs")
    if not isinstance(seal_inputs, dict):
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    attestation_path = Path(cast(str, seal_inputs["attestation"]))
    attestation = json.loads(attestation_path.read_text())
    if not isinstance(attestation, dict):
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    mounts = (
        cast(list[dict[str, object]], context["mounts"])
        if context is not None
        else _mount_roots(config)
    )
    serial = secrets.token_hex(16)
    input_roots = cast(list[str], config["input_roots"])
    runtime_receipt = (
        {}
        if current
        else json.loads(
            (Path(input_roots[0]) / "docs/receipts/repo0-baseline-receipt.json").read_text()
        )
    )
    value: dict[str, object] = {
        "schema_version": "review-launch-authorization/v2"
        if current
        else "review-launch-authorization/v1",
        "issuer_role": "HOST_REVIEW_AUTHORITY",
        "audience": "hybrid-discovery:independent-review-launcher:v1",
        "review_role": config["role"],
        "review_run_id": run_id,
        "pack_zip_sha256": _regular_hash(Path(cast(str, seal_inputs["zip"]))),
        "pack_manifest_sha256": attestation["manifest_sha256"],
        **(
            review_identity(attestation)
            if current
            else {
                "repo0_receipt_sha256": attestation["repo0_receipt_sha256"],
                "repo0_commit_oid": runtime_receipt["baseline_commit"],
                "repo0_tree_oid": runtime_receipt["baseline_tree"],
                "repo0_file_tree_root_sha256": mounts[1]["content_root_sha256"],
            }
        ),
        "workspace_root": config["workspace_root"],
        "input_mounts": mounts,
        "excluded_roots": config["excluded_roots"],
        "allowed_output_root": config["output_root"],
        "prompt_sha256": _regular_hash(Path(cast(str, config["prompt_path"]))),
        "command_registry_sha256": _regular_hash(Path(cast(str, config["command_registry_path"]))),
        "issued_at": trusted_now.isoformat(),
        "not_before": trusted_now.isoformat(),
        "expires_at": (trusted_now + timedelta(seconds=duration)).isoformat(),
        "maximum_duration_seconds": duration,
        "one_use_serial": serial,
        "nonce": secrets.token_urlsafe(32),
        "fresh_session_required": True,
        "production_authority": "NONE",
        "signature_algorithm": "Ed25519",
        "host_boot_id": Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
        "trust_epoch": public["trust_epoch"],
    }
    if context is not None:
        recheck_review_context(context)
    signed = sign_review_launch_authorization(value, private)
    output.parent.mkdir(parents=True, exist_ok=True)
    if output != output.resolve():
        raise ValueError("E_REVIEW_LAUNCH_INPUT")
    with output.open("x") as stream:
        stream.write(json.dumps(signed, sort_keys=True, separators=(",", ":")) + "\n")
    return signed


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument("--scope", type=Path)
    parser.add_argument("--scope-input", type=Path, action="append", default=[])
    args = parser.parse_args()
    config = json.loads(args.config.read_text())
    scope = parse_strict_json(args.scope.read_bytes()) if args.scope is not None else None
    if scope is not None and not isinstance(scope, dict):
        raise ValueError("E_REVIEW_SCOPE_INPUT")
    authority_path = Path(cast(str, config["authority_config"]))
    print(
        json.dumps(
            issue_review_launch_authorization(
                config,
                json.loads(authority_path.read_text()),
                args.output,
                scope=scope,
                scope_inputs=args.scope_input,
            ),
            sort_keys=True,
        )
    )


if __name__ == "__main__":
    main()"""Vietnamese user-terminal workflow; source actions retain their own gates."""

