from moj_discovery.canonical import canonical_content_hash  # noqa: E402
from moj_discovery.ingest import Ingestor  # noqa: E402
from moj_discovery.store import VENDOR, RunStore, read_journal  # noqa: E402
from tools.restart_state_reader import read_restart_state  # noqa: E402

# SQLite traces a statement BEFORE executing it. Pause before the next statement,
# never pretend the COMMIT trace is a checkpoint inside SQLite's commit machinery.
BEFORE_STATEMENT = {
    "after_raw_insert": "INSERT INTO application_records",
    "after_application_insert": "INSERT INTO derived_revisions",
    "after_revision_insert": "INSERT INTO reducer_cursors",
    "after_cursor_insert": "INSERT INTO ack_outbox",
    "after_outbox_insert": "COMMIT",
    "after_gap_insert": "INSERT INTO shock_observations",
    "after_shock_insert": "INSERT INTO coherence_transitions",
    "after_coherence_transition": "UPDATE coherence_controllers",
    "after_controller_close": "INSERT INTO gap_epoch_bindings",
    "after_epoch_binding": "UPDATE stream_generations",
    "after_predecessor_close": "INSERT INTO generation_transitions",
    "after_generation_transition": "INSERT INTO stream_generations",
    "after_successor_insert": "COMMIT",
}


def contract_not_implemented() -> None:
    raise RuntimeError("E_CONTRACT_NOT_IMPLEMENTED:V636-P01-T04")


def position(base: dict[str, Any], sequence: int) -> dict[str, Any]:
    value = json.loads(json.dumps(base))
    value["sequence"] = str(sequence)
    value["raw_observation_id"] = "observation:" + f"{sequence:064x}"
    value["content_hash"] = canonical_content_hash(
        "RawObservation", value, registry_path=VENDOR / "registries/canonical-hash-domains.v1.json"
    )
    return dict(value)


def provision(case: Path, base: dict[str, Any]) -> RunStore:
    run_dir = case / base["discovery_run_id"]
    run_dir.mkdir()
    store = RunStore(run_dir / "run.sqlite3")
    store.bootstrap_v1()
    run, browser, producer, stream = (
        base["discovery_run_id"],
        base["context"]["browser_run_id"],
        base["clock_context"]["clock_domain_id"],
        base["stream_id"],
    )
    with closing(store.connect()) as connection, connection:
        connection.execute(
            "INSERT INTO run_meta VALUES (?,1,'OPEN','test-only:offline',?,?,0,NULL)",
            (run, base["pack_hash"], base["build_hash"]),
        )
        connection.execute(
            "INSERT INTO stream_generations VALUES ('generation:0',?,?,?,?,0,NULL,"
            "'ACTIVE',0,NULL,NULL)",
            (run, browser, producer, stream),
        )
        connection.execute(
            "INSERT INTO coherence_epochs VALUES ('epoch:0',?,'fixture:test',0,NULL,"
            "'OPEN',NULL,NULL,0,0)",
            (run,),
        )
        connection.execute(
            "INSERT INTO coherence_controllers VALUES ('controller:test',?,'fixture:test',"
            "'OPEN','epoch:0',NULL,NULL,NULL,0,0)",
            (run,),
        )
    return store


class CheckpointStore(RunStore):
    """Only this test child installs the observer; runtime transaction code is unchanged."""

    def __init__(self, path: Path, phase: str, pause: Callable[[sqlite3.Connection], None]) -> None:
        super().__init__(path)
        self.phase, self.pause = phase, pause

    def connect(self) -> sqlite3.Connection:
        connection = super().connect()

        def trace(statement: str) -> None:
            if statement.startswith(BEFORE_STATEMENT[self.phase]):
                connection.set_trace_callback(None)
                self.pause(connection)

        connection.set_trace_callback(trace)
        return connection


class CommitIoStore(RunStore):
    """Arm the test-only preload hook immediately before SQLite enters COMMIT."""

    def connect(self) -> sqlite3.Connection:
        connection = super().connect()

        def trace(statement: str) -> None:
            if statement == "COMMIT":
                connection.set_trace_callback(None)
                os.environ["BH_SQL_COMMIT_ARMED"] = "1"

        connection.set_trace_callback(trace)
        return connection


def apply_result(store: RunStore, value: dict[str, Any]) -> dict[str, Any]:
    try:
        return {"ack": Ingestor(store).apply(value)}
    except ValueError as error:
        return {"error": str(error)}


def recover(case: Path, *, replay: bool = False) -> None:
    scenario = json.loads((case / "scenario.json").read_text())
    store = RunStore(case / scenario["observation"]["discovery_run_id"] / "run.sqlite3")
    # A read-write reopen performs SQLite's hot journal recovery before the
    # separate read-only inspector. Reopen must never bootstrap a missing store.
    with closing(store.connect()):
        pass
    if not replay:
        (case / "reopened.json").write_text(json.dumps({"pid": os.getpid()}))
        return
    result = apply_result(store, scenario["delivery"])
    after = read_restart_state(store.db_path.parent)
    (case / "recovery.json").write_text(
        json.dumps(
            {
                "pid": os.getpid(),
                "replay": result,
                "after": after,
            },
            sort_keys=True,
        )
    )


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--recover", type=Path)
    parser.add_argument("--browser-server", type=Path)
    parser.add_argument("--replay", action="store_true")
    parser.add_argument("--vector-id")
    parser.add_argument("--ready", type=Path)
    parser.add_argument("--run-id")
    parser.add_argument("--case-id")
    parser.add_argument("--checkpoint-id")
    parser.add_argument("--component")
    parser.add_argument("--ordinal", type=int)
    parser.add_argument("--test-nonce")
    parser.add_argument("--hold", action="store_true")
    args = parser.parse_args()
    if args.browser_server is not None:
        browser_server(args.browser_server)
        return
    if args.recover is not None:
        recover(args.recover, replay=args.replay)
        return
    if args.ready is None or not args.hold:
        raise ValueError("E_CRASH_SCENARIO_REQUIRED")
    case = args.ready.parent
    scenario = json.loads((case / "scenario.json").read_text())
    phase = scenario["phase"]
    store = provision(case, scenario["observation"])
    for value in scenario["setup_deliveries"]:
        result = apply_result(store, value)
        if "error" in result and result["error"] != "E_INGEST_GAP":
            raise ValueError("E_CRASH_SETUP_FAILED")
    identity = {
        "run_id": args.run_id,
        "case_id": args.case_id,
        "checkpoint_id": args.checkpoint_id,
        "component": args.component,
        "pid": os.getpid(),
        "ordinal": args.ordinal,
        "test_nonce": args.test_nonce,
    }
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as listener:
        listener.bind(("127.0.0.1", 0))
        listener.listen(1)
        address = listener.getsockname()
        with socket.create_connection(address, timeout=5) as sender:
            sender.sendall(json.dumps(scenario["delivery"]).encode() + b"\n")
            receiver, _ = listener.accept()
            with receiver, receiver.makefile("rb") as incoming:
                received = json.loads(incoming.readline(65537))
                wire_ack: dict[str, Any] | None = None
                ingest_result: dict[str, Any] | None = None

                def pause(connection: sqlite3.Connection) -> None:
                    witness = {
                        "identity": identity,
                        "phase": phase,
                        "in_transaction": connection.in_transaction,
                        "tables": read_journal(connection),
                        "received_observation_hash": received["content_hash"],
                        "transport_address": address,
                        "wire_ack": wire_ack,
                        "ingest_result": ingest_result,
                    }
                    (case / "boundary.json").write_text(json.dumps(witness, sort_keys=True))
                    temporary = args.ready.with_suffix(".tmp")
                    temporary.write_text(json.dumps(identity, sort_keys=True))
                    temporary.replace(args.ready)
                    while True:
                        signal.pause()

                if phase == "after_receive_before_begin":
                    with closing(store.connect()) as connection:
                        pause(connection)
                if phase in BEFORE_STATEMENT:
                    store = CheckpointStore(store.db_path, phase, pause)
                elif phase == "during_commit":
                    store = CommitIoStore(store.db_path)
                result = apply_result(store, received)
                ingest_result = result
                if phase == "after_duplicate_ack":
                    receiver.sendall(json.dumps(result).encode() + b"\n")
                    with sender.makefile("rb") as outgoing:
                        wire_ack = json.loads(outgoing.readline(65537))
                if phase in {
                    "after_commit_before_send",
                    "after_gap_commit",
                    "after_duplicate_ack",
                    "after_late_rejection",
                }:
                    with closing(store.connect()) as connection:
                        pause(connection)
                raise RuntimeError("E_CRASH_BOUNDARY_NOT_REACHED")


def browser_server(input_path: Path) -> None:
    """Disposable loopback transport. Token authorizes this fixture only, never discovery."""
    config = json.loads(input_path.read_text())
    if set(config) != {"identity", "observation", "origin", "token", "restart"}:
        raise ValueError("E_ACK_SERVER_INPUT")
    case = input_path.parent
    identity = {**config["identity"], "pid": os.getpid()}
    base = config["observation"]
    store = (
        RunStore(case / base["discovery_run_id"] / "run.sqlite3")
        if config["restart"]
        else provision(case, base)
    )
    with closing(store.connect()):
        pass
    checkpoint = identity["checkpoint_id"] if not config["restart"] else ""
    serial = 0

    class Handler(BaseHTTPRequestHandler):
        def log_message(self, _format: str, *args: object) -> None:
            pass

        def do_OPTIONS(self) -> None:
            self.send_response(204)
            self.send_header("Access-Control-Allow-Origin", config["origin"])
            self.send_header("Access-Control-Allow-Headers", "Content-Type")
            self.send_header("Access-Control-Allow-Methods", "POST")
            self.end_headers()

        def do_POST(self) -> None:
            nonlocal serial
            size = int(self.headers.get("Content-Length", "0"))
            (case / "request-metadata.json").write_text(
                json.dumps(
                    {
                        "origin": self.headers.get("Origin"),
                        "path": self.path,
                        "size": size,
                    }
                )
            )
            if (
                self.headers.get("Origin") != config["origin"]
                or not 0 < size < 65536
                or self.path not in {"/ingest", "/confirm"}
            ):
                self.send_error(403)
                return
            request = json.loads(self.rfile.read(size))
            if set(request) != {"token", "value"} or request["token"] != config["token"]:
                self.send_error(403)
                return
            serial += 1
            value = request["value"]

            def pause() -> None:
                with closing(store.connect()) as connection:
                    witness = {
                        "identity": identity,
                        "path": self.path,
                        "value": value,
                        "in_transaction": connection.in_transaction,
                        "tables": read_journal(connection),
                    }
                (case / "backend-boundary.json").write_text(json.dumps(witness, sort_keys=True))
                ready = case / "backend-checkpoint.json"
                temporary = ready.with_suffix(".tmp")
                temporary.write_text(json.dumps(identity, sort_keys=True))
                temporary.replace(ready)
                while True:
                    signal.pause()

            if self.path == "/ingest":
                if value != base:
                    raise ValueError("E_ACK_SERVER_OBSERVATION")
                if checkpoint == "send_01_after_send_before_backend_begin":
                    pause()
                result = {"ack": Ingestor(store).apply(value)}
            else:
                if checkpoint == "ack_04_before_backend_confirmation_commit":
                    pause()
                result = {"confirmation": Ingestor(store).confirm_ack(value)}
                if checkpoint == "ack_05_after_backend_confirmation_commit":
                    pause()
            record = {
                "identity": identity,
                "request": request,
                "path": self.path,
                "response": result,
                "serial": serial,
            }
            (case / f"wire-{int(config['restart'])}-{serial}.json").write_text(
                json.dumps(record, sort_keys=True)
            )
            data = json.dumps(result, sort_keys=True).encode()
            self.send_response(200)
            self.send_header("Access-Control-Allow-Origin", config["origin"])
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

    with HTTPServer(("127.0.0.1", 0), Handler) as server:
        ready = {"identity": identity, "address": list(server.server_address)}
        (case / f"server-{int(config['restart'])}.json").write_text(json.dumps(ready))
        server.serve_forever(poll_interval=0.05)


if __name__ == "__main__":
    main()import json
import stat
from pathlib import Path, PurePosixPath

TASK_ID = "V636-P01-T02"
STUB_ERROR = f"E_CONTRACT_NOT_IMPLEMENTED:{TASK_ID}"
REGISTRY_NAME = ".contract-stub-registry.json"


def _task_outputs(root: Path) -> list[dict[str, str]]:
    manifest_path = root.parent / "plan-input/docs/tasks/task-manifest.v6.3.6.json"
    if not manifest_path.exists() and not manifest_path.is_symlink():
        manifest_path = root / "vendor/hybrid-discovery-v6.3.6/docs/tasks/task-manifest.v6.3.6.json"
    manifest = json.loads(manifest_path.read_text())
    tasks = manifest.get("tasks")
    if not isinstance(tasks, list):
        raise ValueError("E_CONTRACT_STUBS:MANIFEST")
    matches = [task for task in tasks if isinstance(task, dict) and task.get("task_id") == TASK_ID]
    if len(matches) != 1 or not isinstance(matches[0].get("outputs"), list):
        raise ValueError("E_CONTRACT_STUBS:TASK")
    entries: list[dict[str, str]] = []
    for output in matches[0]["outputs"]:
        if not isinstance(output, str):
            raise ValueError("E_CONTRACT_STUBS:OUTPUT")
        path = PurePosixPath(output)
        if output.startswith("runtime/"):
            if path.is_absolute() or any(part in {"", ".", ".."} for part in path.parts):
                raise ValueError("E_CONTRACT_STUBS:PATH")
            entries.append({"path": output, "classification": "internal"})
        elif path.is_absolute():
            entries.append({"path": output, "classification": "external"})
        else:
            raise ValueError("E_CONTRACT_STUBS:PATH")
    return entries


def _stub_text(path: Path) -> str:
    if path.suffix == ".py":
        if "tests/" in path.as_posix():
            return "def test_contract_stub() -> None:\n    assert True\n"
        return (
            f"def contract_not_implemented() -> None:\n"
            f"    raise RuntimeError({STUB_ERROR!r})\n\n"
            '\nif __name__ == "__main__":\n'
            "    contract_not_implemented()\n"
        )
    if path.suffix == ".ts":
        return (
            "export const contractNotImplemented = (): never => {\n"
            f"  throw new Error({STUB_ERROR!r});\n"
            "};\n"
        )
    raise ValueError(f"E_CONTRACT_STUBS:UNSUPPORTED:{path.suffix}")


def materialize_declared_stubs(root: Path, *, check: bool = False) -> list[str]:
    root = root.resolve()
    try:
        entries = _task_outputs(root)
    except (OSError, ValueError, json.JSONDecodeError):
        return ["E_CONTRACT_STUBS:MANIFEST"]
    registry = {
        "schema_version": "contract-stub-registry/v1",
        "task_id": TASK_ID,
        "entries": entries,
    }
    registry_path = root / REGISTRY_NAME
    if check:
        try:
            registry_stat = registry_path.lstat()
            if (
                registry_path.is_symlink()
                or not stat.S_ISREG(registry_stat.st_mode)
                or registry_stat.st_nlink != 1
                or json.loads(registry_path.read_text()) != registry
            ):
                return ["E_CONTRACT_STUBS:REGISTRY"]
        except (OSError, json.JSONDecodeError):
            return ["E_CONTRACT_STUBS:REGISTRY"]
    else:
        registry_path.write_text(json.dumps(registry, indent=2) + "\n")
    errors: list[str] = []
    for entry in entries:
        if entry["classification"] != "internal" or entry["path"] == f"runtime/{REGISTRY_NAME}":
            continue
        path = root / Path(*PurePosixPath(entry["path"]).parts[1:])
        if path.exists() or path.is_symlink():
            if not path.is_file() or path.is_symlink():
                errors.append(f"E_CONTRACT_STUBS:FILE:{entry['path']}")
            continue
        if check:
            errors.append(f"E_CONTRACT_STUBS:MISSING:{entry['path']}")
            continue
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(_stub_text(path))
        except (OSError, ValueError):
            errors.append(f"E_CONTRACT_STUBS:WRITE:{entry['path']}")
    return errors


if __name__ == "__main__":
    raise SystemExit(bool(materialize_declared_stubs(Path(__file__).parents[1])))"""Native Windows test controller: real RunStore, owned handles, no ingest oracle."""

from __future__ import annotations

import ctypes
import hashlib
import json
import os
import platform
import sqlite3
import subprocess
import sys
import time
from collections.abc import Callable
from contextlib import closing
from pathlib import Path
from typing import Any
from urllib.request import urlopen


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def save(path: Path, value: Any) -> dict[str, str]:
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(value, sort_keys=True), encoding="utf-8")
    temporary.replace(path)
    return {"path": str(path), "sha256": sha(path)}


def observe(child: subprocess.Popen[bytes]) -> dict[str, Any]:
    """Query the live process through the exact owned native handle, not its label."""
    if child.poll() is not None:
        raise RuntimeError("E_ENV_NATIVE_HANDLE")
    return observe_handle(child.pid, int(child._handle), child.args)  # type: ignore[attr-defined]


def observe_handle(pid: int, handle: int, argv: Any) -> dict[str, Any]:
    """Read an already owned handle; the controller verifies its parent chain."""
    kernel = ctypes.WinDLL("kernel32", use_last_error=True)  # type: ignore[attr-defined]
    query = kernel.QueryFullProcessImageNameW
    query.argtypes = [
        ctypes.c_void_p,
        ctypes.c_ulong,
        ctypes.c_wchar_p,
        ctypes.POINTER(ctypes.c_ulong),
    ]
    query.restype = ctypes.c_int
    buffer = ctypes.create_unicode_buffer(32768)
    size = ctypes.c_ulong(len(buffer))
    if not query(handle, 0, buffer, ctypes.byref(size)):
        raise RuntimeError("E_ENV_NATIVE_HANDLE")
    command = subprocess.run(  # noqa: S603 -- read-only exact PID observation.
        [
            "C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe",
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            f"Get-CimInstance Win32_Process -Filter 'ProcessId={pid}' | "
            "Select-Object ProcessId,ParentProcessId,ExecutablePath,CommandLine,CreationDate | "
            "ConvertTo-Json -Compress",
        ],
        capture_output=True,
        check=True,
        timeout=15,
    )
    return {
        "pid": pid,
        "handle": handle,
        "executable": buffer.value,
        "sha256": sha(Path(buffer.value)),
        "argv": argv,
        "cim": json.loads(command.stdout),
        "cim_raw": command.stdout.decode().strip(),
    }


def component(mode: str, config: dict[str, Any]) -> None:
    gate = Path(config["ready"]).parent
    save(gate / f"{mode}.started.json", {"pid": os.getpid(), "mode": mode})
    deadline = time.monotonic() + 20
    while not (gate / f"{mode}.start").is_file():
        if time.monotonic() > deadline:
            raise RuntimeError("E_ENV_NATIVE_CONTROLLER_MISSING")
        time.sleep(0.02)
    sys.path[:0] = [str(Path(config["root"]) / "src"), config["root"], config["dependency_root"]]
    from moj_discovery.store import RunStore
    from tools.restart_state_reader import read_restart_state

    run_dir = Path(config["run_dir"])
    store = RunStore(run_dir / "run.sqlite3")
    if mode == "setup":
        run_dir.mkdir()
        store.bootstrap_v1()
        with closing(store.connect()) as connection, connection:
            connection.execute(
                "INSERT INTO run_meta VALUES (?,1,'OPEN','test-only:offline',?,?,0,NULL)",
                (run_dir.name, "a" * 64, "b" * 64),
            )
    elif mode == "write":
        with closing(store.connect()) as connection:
            connection.execute("BEGIN IMMEDIATE")
            connection.execute("UPDATE run_meta SET run_status='CLOSED',closed_at_us=1")
            if config["phase"] == "after_commit":
                connection.commit()
            save(
                Path(config["ready"]),
                {
                    "pid": os.getpid(),
                    "run_id": run_dir.name,
                    "phase": config["phase"],
                    "in_transaction": connection.in_transaction,
                    "tables": {
                        "run_meta": [
                            dict(row) for row in connection.execute("SELECT * FROM run_meta")
                        ]
                    },
                },
            )
            while True:
                time.sleep(1)
    elif mode == "reopen":
        with closing(store.connect()):
            pass
    elif mode != "read":
        raise ValueError("E_ENV_NATIVE_MODE")
    print(json.dumps({"pid": os.getpid(), "state": read_restart_state(run_dir)}, sort_keys=True))


def storage(config: dict[str, Any]) -> dict[str, Any]:
    workspace = Path(config["workspace"])
    cases = []
    script = str(Path(__file__).resolve())
    for phase in ("before_commit", "after_commit"):
        case = workspace / phase
        case.mkdir()
        cfg = {
            "root": config["root"],
            "dependency_root": config["dependency_root"],
            "run_dir": str(case / config["run_id"]),
            "phase": phase,
            "ready": str(case / "checkpoint.json"),
        }
        input_file = case / "input.json"
        save(input_file, cfg)
        processes: list[dict[str, Any]] = []

        def launch(
            mode: str,
            held: bool = False,
            *,
            case: Path = case,
            input_file: Path = input_file,
            processes: list[dict[str, Any]] = processes,
        ) -> tuple[Any, dict[str, Any]]:
            command = [sys.executable, "-I", script, mode, str(input_file)]
            with (
                (case / f"{mode}.stdout").open("wb") as stdout,
                (case / f"{mode}.stderr").open("wb") as stderr,
            ):
                child = subprocess.Popen(command, stdout=stdout, stderr=stderr)  # noqa: S603
            deadline = time.monotonic() + 15
            started = case / f"{mode}.started.json"
            while not started.is_file() and child.poll() is None and time.monotonic() < deadline:
                time.sleep(0.02)
            if json.loads(started.read_text())["pid"] != child.pid:
                child.kill()
                child.wait(timeout=10)
                raise RuntimeError("E_ENV_NATIVE_START_IDENTITY")
            observation = observe(child)
            (case / f"{mode}.start").touch(exist_ok=False)
            if held:
                return child, observation
            code = child.wait(timeout=20)
            out = (case / f"{mode}.stdout").read_bytes()
            err = (case / f"{mode}.stderr").read_bytes()
            if code or err:
                raise RuntimeError(f"E_ENV_NATIVE_CHILD:{mode}:{code}:{err.decode()}")
            value = json.loads(out)
            if value["pid"] != child.pid:
                raise RuntimeError("E_ENV_NATIVE_READER_PID")
            processes.append(
                {
                    "mode": mode,
                    "pid": child.pid,
                    "argv": command,
                    "exit": code,
                    "observed": observation,
                    "stdout": {
                        "path": str(case / f"{mode}.stdout"),
                        "sha256": sha(case / f"{mode}.stdout"),
                    },
                    "stderr": {
                        "path": str(case / f"{mode}.stderr"),
                        "sha256": sha(case / f"{mode}.stderr"),
                    },
                }
            )
            return value, processes[-1]

        baseline, _ = launch("setup")
        writer, writer_start = launch("write", True)
        try:
            deadline = time.monotonic() + 15
            while (
                not Path(cfg["ready"]).is_file()
                and writer.poll() is None
                and time.monotonic() < deadline
            ):
                time.sleep(0.02)
            checkpoint = json.loads(Path(cfg["ready"]).read_text())
            observed = observe(writer)
            if checkpoint["pid"] != writer.pid or checkpoint["phase"] != phase:
                raise RuntimeError("E_ENV_NATIVE_CHECKPOINT")
            writer.kill()  # Windows Popen uses TerminateProcess on its retained owned handle.
            code = writer.wait(timeout=10)
            if code != 1:
                raise RuntimeError("E_ENV_NATIVE_TERMINATION")
        finally:
            if writer.poll() is None:
                writer.kill()
                writer.wait(timeout=10)
        reopened, _ = launch("reopen")
        after, _ = launch("read")
        cases.append(
            {
                "phase": phase,
                "input": {"path": str(input_file), "sha256": sha(input_file)},
                "before": baseline["state"],
                "after": after["state"],
                "reopened": reopened["state"],
                "checkpoint": checkpoint,
                "writer": observed,
                "writer_start": writer_start,
                "processes": processes,
                "writer_stdout": {
                    "path": str(case / "write.stdout"),
                    "sha256": sha(case / "write.stdout"),
                },
                "writer_stderr": {
                    "path": str(case / "write.stderr"),
                    "sha256": sha(case / "write.stderr"),
                },
                "termination": {
                    "mechanism": "WINDOWS_TERMINATE_PROCESS_OWNED_HANDLE",
                    "exit": code,
                    "pid": writer.pid,
                },
            }
        )
    runtime = Path(sys.executable).parent
    return {
        "result": "PASS",
        "cases": cases,
        "system": platform.system(),
        "platform": platform.platform(),
        "python_version": sys.version,
        "sqlite_version": sqlite3.sqlite_version,
        "pid": os.getpid(),
        "executable": str(Path(sys.executable)),
        "runtime_files": [
            {"path": str(path), "sha256": sha(path)}
            for path in [
                Path(sys.executable),
                runtime / "python312.dll",
                runtime / "DLLs/_sqlite3.pyd",
                runtime / "DLLs/sqlite3.dll",
            ]
        ],
        "physical_power_loss": "HOLD_NOT_EXECUTED",
        "native_ingestor": "HOLD_MISSING_NATIVE_SCHEMA_DEPENDENCIES",
    }


def browser_leader(config: dict[str, Any]) -> None:
    """The leader owns the sole job handle; its death kills inherited Chrome members."""
    from ctypes import wintypes

    class Basic(ctypes.Structure):
        _fields_ = [
            ("process_time", ctypes.c_int64),
            ("job_time", ctypes.c_int64),
            ("flags", wintypes.DWORD),
            ("minimum", ctypes.c_size_t),
            ("maximum", ctypes.c_size_t),
            ("active", wintypes.DWORD),
            ("affinity", ctypes.c_size_t),
            ("priority", wintypes.DWORD),
            ("scheduling", wintypes.DWORD),
        ]

    class Extended(ctypes.Structure):
        _fields_ = [
            ("basic", Basic),
            ("io", ctypes.c_uint64 * 6),
            ("process_memory", ctypes.c_size_t),
            ("job_memory", ctypes.c_size_t),
            ("peak_process", ctypes.c_size_t),
            ("peak_job", ctypes.c_size_t),
        ]

    kernel = ctypes.WinDLL("kernel32", use_last_error=True)  # type: ignore[attr-defined]
    kernel.CreateJobObjectW.restype = wintypes.HANDLE
    kernel.GetCurrentProcess.restype = wintypes.HANDLE
    kernel.SetInformationJobObject.argtypes = [
        wintypes.HANDLE,
        ctypes.c_int,
        ctypes.c_void_p,
        wintypes.DWORD,
    ]
    kernel.AssignProcessToJobObject.argtypes = [wintypes.HANDLE, wintypes.HANDLE]
    job = kernel.CreateJobObjectW(None, None)
    limits = Extended()
    limits.basic.flags = 0x2000  # JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE
    if (
        not job
        or not kernel.SetInformationJobObject(job, 9, ctypes.byref(limits), ctypes.sizeof(limits))
        or not kernel.AssignProcessToJobObject(job, kernel.GetCurrentProcess())
    ):
        raise RuntimeError("E_ENV_WINDOWS_JOB")
    if config.get("transport") == "pipe":
        sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
        from tools.qualify_chrome_indexeddb import _pipe_node_environment

        case = Path(config["workspace"])
        with (case / "node.stdout").open("wb") as out, (case / "node.stderr").open("wb") as err:
            child = subprocess.Popen(  # noqa: S603 -- exact retained pipe program, owned job.
                [config["node"], config["script"], config["input_path"]],
                stdout=out,
                stderr=err,
                env=_pipe_node_environment(),
            )
        save(
            case / "node-ready.json",
            {
                "leader_pid": os.getpid(),
                "job_handle": int(job),
                "job_kill_on_close": True,
                "node": observe(child),
            },
        )
        while child.poll() is None:
            time.sleep(0.05)
        raise RuntimeError("E_ENV_PIPE_OWNER_EXIT")
    with (Path(config["workspace"]) / "chrome.log").open("wb") as log:
        child = subprocess.Popen(config["command"], stdout=log, stderr=log)  # noqa: S603 -- fixed approved browser command.
    save(
        Path(config["workspace"]) / "browser-ready.json",
        {
            "leader_pid": os.getpid(),
            "job_handle": int(job),
            "job_kill_on_close": True,
            "browser": observe(child),
        },
    )
    while True:
        time.sleep(1)


def _wait_for_job_cleanup(
    command: list[str], complete: Callable[[bytes], bool]
) -> subprocess.CompletedProcess[bytes]:
    """Observe only the owned descendants until asynchronous job termination settles."""
    deadline = time.monotonic() + 10
    while (remaining := deadline - time.monotonic()) > 0:
        result = subprocess.run(  # noqa: S603 -- fixed read-only owned-descendant query.
            command, capture_output=True, check=True, timeout=remaining
        )
        if time.monotonic() >= deadline:
            break
        if complete(result.stdout):
            return result
        time.sleep(min(0.05, max(0, deadline - time.monotonic())))
    raise RuntimeError("E_ENV_WINDOWS_JOB_CLEANUP_TIMEOUT")


def browser(config: dict[str, Any], input_path: Path) -> dict[str, Any]:
    if config.get("transport") == "pipe":
        return pipe_browser(config, input_path)
    case = Path(config["workspace"])
    with (case / "leader.stdout").open("wb") as out, (case / "leader.stderr").open("wb") as err:
        leader = subprocess.Popen(  # noqa: S603 -- fixed native leader and owned input.
            [
                sys.executable,
                "-I",
                str(Path(__file__).resolve()),
                "browser-leader",
                str(input_path),
            ],
            stdout=out,
            stderr=err,
        )  # noqa: S603
    pages: list[dict[str, Any]] = []
    try:
        deadline = time.monotonic() + 20
        ready = case / "browser-ready.json"
        while not ready.is_file() and leader.poll() is None and time.monotonic() < deadline:
            time.sleep(0.05)
        raw = json.loads(ready.read_text())
        observed = observe(leader)
        if raw["leader_pid"] != leader.pid:
            raise RuntimeError("E_ENV_BROWSER_LEADER")
        deadline = time.monotonic() + 10
        while time.monotonic() < deadline:
            try:
                with urlopen(f"http://127.0.0.1:{config['port']}/json/list", timeout=1) as response:
                    pages = json.loads(response.read())
            except OSError:
                time.sleep(0.1)
                continue
            if any(page.get("url") == config["origin"] + "/repair-probe.html" for page in pages):
                break
            time.sleep(0.1)
        matched = any(page.get("url") == config["origin"] + "/repair-probe.html" for page in pages)
        document = None
        if matched:
            target = next(
                page for page in pages if page.get("url") == config["origin"] + "/repair-probe.html"
            )
            evaluation = subprocess.run(  # noqa: S603 -- bound local CDP program.
                [
                    config["node"],
                    "-e",
                    config["cdp_script"],
                    target["webSocketDebuggerUrl"],
                    "({origin:location.origin,protocol:location.protocol,"
                    "probe:Boolean(globalThis.repairProbe),"
                    "extensionId:globalThis.chrome?.runtime?.id ?? null})",
                ],
                capture_output=True,
                check=True,
                timeout=15,
            )  # noqa: S603 -- bound fixed local CDP program.
            document = json.loads(evaluation.stdout)
            save(case / "document-observation.json", document)
            matched = (
                document["origin"] == config["origin"]
                and document["protocol"] == "chrome-extension:"
                and document["probe"]
                and document["extensionId"] == config["origin"].split("://")[1]
            )
        enumeration = subprocess.run(  # noqa: S603 -- read only the owned descendant tree.
            [
                "C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe",
                "-NoProfile",
                "-NonInteractive",
                "-Command",
                "$queue=[System.Collections.Generic.Queue[int]]::new(); "
                f"$queue.Enqueue({leader.pid}); $rows=@(); "
                "while($queue.Count){$taskpid=$queue.Dequeue(); "
                '$children=@(Get-CimInstance Win32_Process -Filter "ParentProcessId=$taskpid"); '
                "foreach($child in $children){$rows += $child | "
                "Select-Object ProcessId,ParentProcessId,ExecutablePath,CreationDate; "
                "$queue.Enqueue($child.ProcessId)}}; "
                "ConvertTo-Json -InputObject @($rows) -Compress",
            ],
            capture_output=True,
            check=True,
            timeout=20,
        )  # noqa: S603 -- observe this owned job tree only.
        descendants = json.loads(enumeration.stdout)
        if raw["browser"]["pid"] not in {item["ProcessId"] for item in descendants}:
            raise RuntimeError("E_ENV_BROWSER_DESCENDANTS")
    finally:
        if leader.poll() is None:
            leader.kill()
        code = leader.wait(timeout=10)
    browser_pid = raw["browser"]["pid"]
    # A terminated job must not leave the named browser process alive.
    owned_ids = [item["ProcessId"] for item in descendants]
    pid_filter = " OR ".join(f"ProcessId={pid}" for pid in owned_ids)
    check = _wait_for_job_cleanup(
        [
            "C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe",
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            f"@(Get-CimInstance Win32_Process -Filter '{pid_filter}').Count",
        ],
        lambda raw: raw.strip() == b"0",
    )
    if code != 1 or check.stdout.strip() != b"0":
        raise RuntimeError("E_ENV_BROWSER_JOB_SURVIVOR")
    return {
        "result": "PASS" if matched else "HOLD",
        "observed_error": None if matched else "E_EXTENSION_TARGET_UNAVAILABLE",
        "origin": config["origin"],
        "pages": pages,
        "document": document,
        "leader": observed,
        "descendants_before": descendants,
        "descendants_raw": enumeration.stdout.decode().strip(),
        "descendant_cleanup_raw": check.stdout.decode().strip(),
        **raw,
        "termination": {
            "mechanism": "WINDOWS_JOB_KILL_ON_CONTROLLER_TERMINATION",
            "leader_exit": code,
            "browser_pid": browser_pid,
            "remaining_named_browser_processes": 0,
            "observed_descendant_pids": owned_ids,
            "remaining_observed_descendants": 0,
        },
        "scope": "UNPACKED_EXTENSION_TARGET_AVAILABILITY_ONLY",
        "physical_power_loss": "HOLD_NOT_EXECUTED",
    }


def pipe_browser(config: dict[str, Any], input_path: Path) -> dict[str, Any]:
    """Force the first owned job down, then run the independent successor reader."""
    from ctypes import wintypes

    sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
    from tools.qualify_chrome_indexeddb import _pipe_work

    phases = []
    for phase in ("before", "after"):
        case = Path(config["workspace"]) / phase
        case.mkdir()
        request = dict(config["requests"][phase])
        phase_cfg = {
            key: config[key]
            for key in ("transport", "command", "extension", "origin", "node", "script")
        }
        phase_cfg.update(workspace=str(case), input_path=str(case / "input.json"))
        save(case / "input.json", phase_cfg)
        invocation = [
            sys.executable,
            "-I",
            str(Path(__file__).resolve()),
            "browser-leader",
            str(case / "input.json"),
        ]
        with (case / "leader.stdout").open("wb") as out, (case / "leader.stderr").open("wb") as err:
            leader = subprocess.Popen(invocation, stdout=out, stderr=err)  # noqa: S603
        try:
            deadline = time.monotonic() + 30
            while not all(
                (case / name).is_file() for name in ("node-ready.json", "pipe-ready.json")
            ):
                if leader.poll() is not None or time.monotonic() > deadline:
                    raise RuntimeError("E_ENV_PIPE_READY")
                time.sleep(0.02)
            observed = observe(leader)
            ready = json.loads((case / "node-ready.json").read_text())
            pipe_ready = json.loads((case / "pipe-ready.json").read_text())
            if pipe_ready["node_pid"] != ready["node"]["pid"]:
                raise RuntimeError("E_ENV_PIPE_PARENT")
            kernel = ctypes.WinDLL("kernel32", use_last_error=True)  # type: ignore[attr-defined]
            kernel.OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
            kernel.OpenProcess.restype = wintypes.HANDLE
            kernel.CloseHandle.argtypes = [wintypes.HANDLE]
            handle = kernel.OpenProcess(0x1000 | 0x100000, False, pipe_ready["pid"])
            if not handle:
                raise RuntimeError("E_ENV_PIPE_CHROME_HANDLE")
            try:
                chrome = observe_handle(pipe_ready["pid"], int(handle), config["command"])
            finally:
                kernel.CloseHandle(handle)
            if chrome["cim"]["ParentProcessId"] != ready["node"]["pid"]:
                raise RuntimeError("E_ENV_PIPE_CHROME_PARENT")
            request["identity"] = {
                "run_id": config["profile_id"],
                "pid": chrome["pid"],
                "phase": phase,
            }
            work = _pipe_work(config["profile_id"], phase, config["worker_ids"][phase], request)
            save(case / "start.json", work)
            deadline = time.monotonic() + 35
            while not (case / "pipe-result.json").is_file():
                if (case / "pipe-error.json").is_file():
                    raise RuntimeError(
                        "E_ENV_PIPE_EXECUTION:" + (case / "pipe-error.json").read_text()
                    )
                if leader.poll() is not None or time.monotonic() > deadline:
                    raise RuntimeError("E_ENV_PIPE_RESULT")
                time.sleep(0.02)
            result = json.loads((case / "pipe-result.json").read_text())
            enumeration = subprocess.run(  # noqa: S603 -- only owned descendants, read-only.
                [
                    "C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe",
                    "-NoProfile",
                    "-NonInteractive",
                    "-Command",
                    "function Desc([int]$taskpid){$children=@(Get-CimInstance "
                    "Win32_Process -Filter "
                    '"ParentProcessId=$taskpid");foreach($c in $children){$c | Select-Object '
                    "ProcessId,ParentProcessId,CreationDate,ExecutablePath,CommandLine;"
                    "Desc $c.ProcessId}};"
                    f"ConvertTo-Json -InputObject @(Desc {leader.pid}) -Compress",
                ],
                capture_output=True,
                check=True,
                timeout=15,
            )
            descendants = json.loads(enumeration.stdout)
        finally:
            if leader.poll() is None:
                leader.kill()  # Owned leader handle; inherited job kills Node/Chrome.
            code = leader.wait(timeout=10)
        ids = [row["ProcessId"] for row in descendants]

        def descendants_gone(raw: bytes, owned: list[dict[str, Any]] = descendants) -> bool:
            return not any(old in json.loads(raw) for old in owned)

        cleanup = _wait_for_job_cleanup(
            [
                "C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe",
                "-NoProfile",
                "-NonInteractive",
                "-Command",
                "ConvertTo-Json -InputObject @(Get-CimInstance Win32_Process -Filter '"
                + " OR ".join(f"ProcessId={pid}" for pid in ids)
                + "' | Select-Object ProcessId,ParentProcessId,CreationDate,"
                "ExecutablePath,CommandLine) -Compress",
            ],
            descendants_gone,
        )
        survivors = [old for old in descendants if old in json.loads(cleanup.stdout)]
        if code != 1 or survivors:
            raise RuntimeError("E_ENV_PIPE_JOB_SURVIVOR")
        phases.append(
            {
                "phase": phase,
                "config": phase_cfg,
                "leader": observed,
                **ready,
                "browser": chrome,
                "result": result,
                "work": work,
                "descendants": descendants,
                "descendants_raw": enumeration.stdout.decode(),
                "cleanup_raw": cleanup.stdout.decode(),
                "cleanup_command": cleanup.args,
                "termination": {
                    "mechanism": "WINDOWS_JOB_KILL_ON_CONTROLLER_TERMINATION",
                    "leader_exit": code,
                    "remaining_observed_descendants": 0,
                    "graceful": False,
                },
            }
        )
    return {
        "phases": phases,
        "input_path": str(input_path),
        "controller": observe_handle(
            os.getpid(),
            -1,
            [sys.executable, "-I", str(Path(__file__).resolve()), "browser", str(input_path)],
        ),
    }


if __name__ == "__main__":
    if os.name != "nt":
        raise RuntimeError("E_ENV_NATIVE_WINDOWS_REQUIRED")
    configuration = json.loads(Path(sys.argv[2]).read_text(encoding="utf-8"))
    if sys.argv[1] == "storage":
        print(json.dumps(storage(configuration), sort_keys=True))
    elif sys.argv[1] == "browser":
        print(json.dumps(browser(configuration, Path(sys.argv[2])), sort_keys=True))
    elif sys.argv[1] == "browser-leader":
        browser_leader(configuration)
    else:
        component(sys.argv[1], configuration)"""Disposable native Ingestor owner; no expected state, TCP or commit-I/O claim."""

from __future__ import annotations

import hashlib
import importlib
import importlib.metadata
import json
import os
import subprocess
import sys
import time
from contextlib import closing
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
PREPARATION_SHA256 = "51d5a2baac9bb59e3b5bedd9b8184421c705c61a460faf4515cbc400ff2b0ae1"
PHASES = ("NATIVE-INGEST-OUTBOX-PRECOMMIT", "NATIVE-INGEST-COMMITTED-PRE-OWNER-ACK")
COMMIT_PHASE = "NATIVE-WINDOWS-SQL06-COMMIT-IO"
MODULES = {
    "jsonschema": "jsonschema",
    "jsonschema-specifications": "jsonschema_specifications",
    "referencing": "referencing",
    "rpds-py": "rpds",
    "attrs": "attrs",
    "typing-extensions": "typing_extensions",
    "rfc8785": "rfc8785",
}


def loaded_dependencies(root: Path) -> dict[str, Any]:
    def descriptor(module: str) -> dict[str, str]:
        filename = importlib.import_module(module).__file__
        if filename is None:
            raise ValueError("E_NATIVE_DEPENDENCY_IMPORT")
        path = Path(filename).resolve()
        if not path.is_relative_to(root / "site-packages"):
            raise ValueError("E_NATIVE_DEPENDENCY_IMPORT")
        return {"path": str(path), "sha256": hashlib.sha256(path.read_bytes()).hexdigest()}

    return {
        "modules": {
            name: {**descriptor(module), "version": importlib.metadata.version(name)}
            for name, module in MODULES.items()
        },
        "native_rpds": descriptor("rpds.rpds"),
    }


def dependency_payload(root: Path) -> dict[str, str]:
    """Pinned preparation is authority for these exact previously approved bytes."""
    raw = (root / "preparation.json").read_bytes()
    if hashlib.sha256(raw).hexdigest() != PREPARATION_SHA256:
        raise ValueError("E_NATIVE_DEPENDENCY_PREPARATION")
    prepared = json.loads(raw)
    payload = root / "site-packages"
    files = {
        path.relative_to(payload).as_posix(): hashlib.sha256(path.read_bytes()).hexdigest()
        for path in payload.rglob("*")
        if path.is_file()
    }
    if any(path.is_symlink() for path in payload.rglob("*")) or files != prepared["file_sha256"]:
        raise ValueError("E_NATIVE_DEPENDENCY_PAYLOAD")
    return files


def component(mode: str, config: dict[str, Any]) -> None:
    from tools.native_environment_probe import save

    required = {"root", "dependency_root", "run_dir", "identity"}
    if mode in {"setup", "write", "replay", "replay-again"}:
        required.add("delivery")
    if mode == "write" and config.get("identity", {}).get("case_id") == COMMIT_PHASE:
        required.add("commit_io")
    if set(config) != required or set(config["identity"]) != {"run_id", "case_id", "checkpoint_id"}:
        raise ValueError("E_NATIVE_INGESTOR_INPUT")
    identity = config["identity"]
    run_dir = Path(config["run_dir"])
    if (
        Path(config["root"]) != ROOT
        or run_dir.name != identity["run_id"]
        or identity["case_id"] not in (*PHASES, COMMIT_PHASE)
        or identity["checkpoint_id"] != identity["case_id"]
    ):
        raise ValueError("E_NATIVE_INGESTOR_IDENTITY")
    dependency_payload(Path(config["dependency_root"]))
    case = run_dir.parent
    save(case / f"{mode}.started.json", {"pid": os.getpid(), "identity": identity})
    deadline = time.monotonic() + 20
    while not (case / f"{mode}.start").is_file():
        if time.monotonic() > deadline:
            raise ValueError("E_NATIVE_INGESTOR_CONTROLLER")
        time.sleep(0.02)
    sys.path[:0] = [str(ROOT / "src"), str(Path(config["dependency_root"]) / "site-packages")]
    from moj_discovery.ingest import Ingestor
    from moj_discovery.store import RunStore, read_journal
    from tools.loopback_ack_crash_child import CheckpointStore, provision
    from tools.restart_state_reader import read_restart_state

    loaded = loaded_dependencies(Path(config["dependency_root"]))
    ack = None
    if mode == "setup":
        store = provision(case, config["delivery"])
    else:
        if not (run_dir / "run.sqlite3").is_file():
            raise ValueError("E_RESTART_MISSING_DATABASE")
        store = RunStore(run_dir / "run.sqlite3")
    if mode == "write":

        def snapshot(connection: Any) -> dict[str, Any]:
            return {
                "identity": {**identity, "pid": os.getpid()},
                "in_transaction": connection.in_transaction,
                "tables": read_journal(connection),
                "ingest_ack": ack,
                "owner_ack_published": False,
                "loaded_dependencies": loaded,
            }

        def pause(connection: Any) -> None:
            save(case / "checkpoint.json", snapshot(connection))
            while True:
                time.sleep(1)

        if identity["case_id"] == COMMIT_PHASE:
            from tools.native_sqlite_commit_io import CommitIoHook

            hook = CommitIoHook(store.db_path, case, config["commit_io"])

            class IoStore(RunStore):
                def connect(self) -> Any:
                    connection = super().connect()

                    def trace(statement: str) -> None:
                        if statement == "COMMIT":
                            connection.set_trace_callback(None)
                            hook.arm(connection, snapshot(connection))

                    connection.set_trace_callback(trace)
                    return connection

            ack = Ingestor(IoStore(store.db_path)).apply(config["delivery"])
            with closing(store.connect()) as connection:
                hook.fallback(snapshot(connection))
        if identity["case_id"] == PHASES[0]:
            store = CheckpointStore(store.db_path, "after_outbox_insert", pause)
        ack = Ingestor(store).apply(config["delivery"])
        with closing(store.connect()) as connection:
            pause(connection)
    elif mode in {"replay", "replay-again"}:
        ack = Ingestor(store).apply(config["delivery"])
    elif mode == "reopen":
        with closing(store.connect()):
            pass
    elif mode not in {"setup", "read", "final-read"}:
        raise ValueError("E_NATIVE_INGESTOR_MODE")
    print(
        json.dumps(
            {
                "pid": os.getpid(),
                "identity": identity,
                "state": read_restart_state(run_dir),
                "ack": ack,
                "loaded_dependencies": loaded,
            },
            sort_keys=True,
        )
    )


def owner(config: dict[str, Any], input_path: Path) -> dict[str, Any]:
    from tools.native_environment_probe import observe, observe_handle, save, sha

    extra = {"commit_io"} if "commit_io" in config else set()
    if set(config) != {"workspace", "root", "dependency_root", "delivery"} | extra:
        raise ValueError("E_NATIVE_INGESTOR_INPUT")
    if extra and config["commit_io"] not in {"armed", "bypass", "unarmed", "postcommit"}:
        raise ValueError("E_NATIVE_COMMIT_IO_MODE")
    dependency_payload(Path(config["dependency_root"]))
    workspace = Path(config["workspace"])
    cases = []
    for phase in (COMMIT_PHASE,) if extra else PHASES:
        case = workspace / phase
        case.mkdir()
        identity = {
            "run_id": config["delivery"]["discovery_run_id"],
            "case_id": phase,
            "checkpoint_id": phase,
        }
        base = {
            "root": config["root"],
            "dependency_root": config["dependency_root"],
            "run_dir": str(case / identity["run_id"]),
            "identity": identity,
        }
        inputs: dict[str, Any] = {}
        processes: list[dict[str, Any]] = []

        def launch(
            mode: str,
            held: bool = False,
            *,
            base: dict[str, Any] = base,
            case: Path = case,
            inputs: dict[str, Any] = inputs,
            identity: dict[str, Any] = identity,
            processes: list[dict[str, Any]] = processes,
            phase: str = phase,
        ) -> tuple[Any, dict[str, Any]]:
            cfg = {
                **base,
                **(
                    {"delivery": config["delivery"]}
                    if mode in {"setup", "write", "replay", "replay-again"}
                    else {}
                ),
            }
            if phase == COMMIT_PHASE and mode == "write":
                cfg["commit_io"] = config["commit_io"]
            input_file = case / f"{mode}.input.json"
            inputs[mode] = {"value": cfg, "artifact": save(input_file, cfg)}
            command = [
                sys.executable,
                "-I",
                "-B",
                str(Path(__file__).resolve()),
                mode,
                str(input_file),
            ]
            with (
                (case / f"{mode}.stdout").open("wb") as out,
                (case / f"{mode}.stderr").open("wb") as err,
            ):
                child = subprocess.Popen(command, stdout=out, stderr=err)  # noqa: S603
            try:
                started = case / f"{mode}.started.json"
                deadline = time.monotonic() + 20
                while (
                    not started.is_file() and child.poll() is None and time.monotonic() < deadline
                ):
                    time.sleep(0.02)
                if json.loads(started.read_text()) != {"pid": child.pid, "identity": identity}:
                    raise ValueError("E_NATIVE_INGESTOR_STARTED")
                observed = observe(child)
                (case / f"{mode}.start").touch(exist_ok=False)
                if held:
                    return child, observed
                code = child.wait(timeout=25)
                output = (case / f"{mode}.stdout").read_bytes()
                if code or (case / f"{mode}.stderr").read_bytes():
                    raise ValueError("E_NATIVE_INGESTOR_CHILD:" + mode)
                value = json.loads(output)
                if value["pid"] != child.pid or value["identity"] != identity:
                    raise ValueError("E_NATIVE_INGESTOR_READER")
                process = {
                    "mode": mode,
                    "observed": observed,
                    "exit": code,
                    "value": value,
                    "stdout": {
                        "path": str(case / f"{mode}.stdout"),
                        "sha256": sha(case / f"{mode}.stdout"),
                    },
                    "stderr": {
                        "path": str(case / f"{mode}.stderr"),
                        "sha256": sha(case / f"{mode}.stderr"),
                    },
                }
                processes.append(process)
                return value, process
            finally:
                if not held or sys.exc_info()[0] is not None:
                    if child.poll() is None:
                        child.kill()
                    child.wait(timeout=10)

        before, _ = launch("setup")
        writer, initial = launch("write", True)
        try:
            ready = case / "checkpoint.json"
            deadline = time.monotonic() + 20
            while not ready.is_file() and writer.poll() is None and time.monotonic() < deadline:
                time.sleep(0.02)
            code = writer.poll()
            if code is not None or not ready.is_file():
                diagnostic = (
                    "E_NATIVE_INGESTOR_CHECKPOINT_TIMEOUT"
                    if code is None
                    else "E_NATIVE_INGESTOR_WRITER_EXIT"
                    if code
                    else "E_NATIVE_INGESTOR_CHECKPOINT_MISSING"
                )
                if code is None:
                    writer.kill()
                    code = writer.wait(timeout=10)
                stderr = case / "write.stderr"
                lines = stderr.read_text(errors="replace").splitlines()
                allowed = {
                    "ValueError: HOLD_NATIVE_COMMIT_IO_" + suffix
                    for suffix in ("DLL", "LOADED_DLL", "VFS", "SYSCALL", "INSTALL")
                }
                if code and lines and lines[-1] in allowed:
                    diagnostic = lines[-1].removeprefix("ValueError: ")
                failure = save(
                    case / "writer-failure.json",
                    {
                        "diagnostic": diagnostic,
                        "exit": code,
                        "writer": initial,
                        "checkpoint_present": ready.is_file(),
                        "stdout": {
                            "path": str(case / "write.stdout"),
                            "sha256": sha(case / "write.stdout"),
                        },
                        "stderr": {"path": str(stderr), "sha256": sha(stderr)},
                    },
                )
                raise ValueError(diagnostic + ":" + json.dumps(failure, sort_keys=True))
            checkpoint = json.loads(ready.read_text())
            observed = observe(writer)
            if checkpoint["identity"] != {**identity, "pid": writer.pid}:
                raise ValueError("E_NATIVE_INGESTOR_CHECKPOINT")
            journal = None
            if extra and checkpoint["commit_io"]["handle"]:
                from tools.native_sqlite_commit_io import duplicate_journal

                journal = duplicate_journal(writer, checkpoint["commit_io"]["handle"])
            writer.kill()
            code = writer.wait(timeout=10)
            if code != 1:
                raise ValueError("E_NATIVE_INGESTOR_TERMINATION")
        finally:
            if writer.poll() is None:
                writer.kill()
                writer.wait(timeout=10)
        reopened, _ = launch("reopen")
        after, _ = launch("read")
        replayed, _ = launch("replay")
        again, _ = launch("replay-again")
        final, _ = launch("final-read")
        cases.append(
            {
                "case_id": phase,
                **(
                    {
                        "journal_observation": journal,
                        "commit_io_events": {
                            "path": str(case / "commit-io-events.json"),
                            "sha256": sha(case / "commit-io-events.json"),
                        },
                    }
                    if extra
                    else {}
                ),
                "inputs": inputs,
                "processes": processes,
                "before": before["state"],
                "reopened": reopened["state"],
                "after": after["state"],
                "replayed": replayed["state"],
                "replayed_again": again["state"],
                "final": final["state"],
                "checkpoint": checkpoint,
                "checkpoint_artifact": {"path": str(ready), "sha256": sha(ready)},
                "writer": observed,
                "writer_start": initial,
                "writer_stdout": {
                    "path": str(case / "write.stdout"),
                    "sha256": sha(case / "write.stdout"),
                },
                "writer_stderr": {
                    "path": str(case / "write.stderr"),
                    "sha256": sha(case / "write.stderr"),
                },
                "termination": {
                    "mechanism": "WINDOWS_TERMINATE_PROCESS_OWNED_HANDLE",
                    "exit": code,
                    "pid": writer.pid,
                    "graceful": False,
                },
            }
        )
    return {
        "cases": cases,
        "system": os.name,
        "python_version": sys.version,
        "runtime_files": [
            {"path": str(path), "sha256": sha(path)}
            for path in [
                Path(sys.executable),
                Path(sys.executable).parent / "python312.dll",
                Path(sys.executable).parent / "DLLs/_sqlite3.pyd",
                Path(sys.executable).parent / "DLLs/sqlite3.dll",
            ]
        ],
        "controller": observe_handle(
            os.getpid(),
            -1,
            [sys.executable, "-I", "-B", str(Path(__file__).resolve()), "owner", str(input_path)],
        ),
    }


if __name__ == "__main__":
    if os.name != "nt":
        raise ValueError("E_NATIVE_INGESTOR_WINDOWS_REQUIRED")
    sys.path.insert(0, str(ROOT))
    source = Path(sys.argv[2])
    config = json.loads(source.read_text())
    if sys.argv[1] == "owner":
        print(json.dumps(owner(config, source), sort_keys=True))
    else:
        component(sys.argv[1], config)"""Process-local SQLite win32 VFS testing hook; never replaces the VFS or OS API."""

