def run_meta(case: str, root: Path, verify: Callable[[Path], dict[str, Any]]) -> None:
    directory = root / case
    directory.mkdir()
    if case == "OFF-20":
        value = verify(root / "reference.json")
        value["cases"][0]["reason"] = (
            '<script>alert("synthetic")</script><img src=https://example.invalid/x>'
        )
        (directory / "input.json").write_text(json.dumps(value))
        (directory / "diagnostic.html").write_text(render_diagnostic(value))
    elif case == "OFF-21":
        config = json.loads((ROOT / "config/live.example.json").read_text())
        (directory / "config.json").write_text(json.dumps(config))
        with (
            patch.object(socket, "socket", side_effect=AssertionError("NETWORK_ATTEMPT")) as direct,
            patch.object(
                socket, "create_connection", side_effect=AssertionError("NETWORK_ATTEMPT")
            ) as connection,
        ):
            result = check_live_readiness(config, {}, {})
            observed = {
                "result": result,
                "network_attempts": direct.call_count + connection.call_count,
            }
        (directory / "observed.json").write_text(json.dumps(observed))
    elif case == "OFF-22":
        value = json.loads((root / "reference.json").read_text())
        targets = []
        for mutation in ["missing", "tampered", "duplicate", "forged"]:
            poisoned = copy.deepcopy(value)
            if mutation in {"missing", "tampered"}:
                artifact = poisoned["records"][0]["artifacts"][0]
                target = directory / (mutation + ".bin")
                if mutation == "tampered":
                    target.write_bytes((root / artifact["relative_path"]).read_bytes() + b"changed")
                artifact["relative_path"] = str(target.relative_to(root))
            elif mutation == "duplicate":
                poisoned["records"].append(copy.deepcopy(poisoned["records"][0]))
            else:
                poisoned["OFFLINE_SLICE_PASS"] = "YES"  # noqa: S105 -- qualification status, not a secret
            target = root / ("negative-" + case + "-" + mutation + ".json")
            target.write_text(json.dumps(poisoned))
            try:
                verify(target)
            except (ValueError, OSError, AssertionError):
                targets.append(target.name)
            else:
                raise AssertionError("E_OFFLINE_GATE_NEGATIVE_ACCEPTED")
        (directory / "observed.json").write_text(json.dumps({"rejected_inputs": targets}))
    elif case == "OFF-25":
        target = ROOT / "config/live.example.json"
        original = target.read_bytes()
        (directory / "original-config.json").write_bytes(original)
        changed = original + b"\n"
        (directory / "changed-config.json").write_bytes(changed)
        try:
            target.write_bytes(changed)
            (directory / "changed-sources.json").write_text(json.dumps(source_hashes()))
            try:
                verify(root / "reference.json")
            except ValueError as error:
                if str(error) != "E_OFFLINE_SOURCE_STALE":
                    raise
            else:
                raise AssertionError("E_OFFLINE_SOURCE_CHANGE_ACCEPTED")
        finally:
            target.write_bytes(original)
        (directory / "observed.json").write_text(
            json.dumps({"source_path": "config/live.example.json"})
        )
    else:
        raise ValueError("E_OFFLINE_META_CASE")


def check_meta(case: str, root: Path, verify: Callable[[Path], dict[str, Any]]) -> dict[str, Any]:
    if not __debug__:
        raise RuntimeError("E_OFFLINE_OPTIMIZED_EXECUTION")
    import hashlib
    from html.parser import HTMLParser

    directory = root / case
    if case == "OFF-20":
        actual = json.loads((directory / "input.json").read_text())
        base = verify(root / "reference.json")
        base["cases"][0]["reason"] = (
            '<script>alert("synthetic")</script><img src=https://example.invalid/x>'
        )
        assert actual == base
        content = (directory / "diagnostic.html").read_text()
        assert content == render_diagnostic(actual)
        tags: list[tuple[str, Any]] = []

        class TagReader(HTMLParser):
            def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
                tags.append((tag, attrs))

        parser = TagReader()
        parser.feed(content)
        assert not any(
            tag in {"script", "img", "iframe", "object", "embed", "link"} for tag, _ in tags
        )
        assert "UNKNOWN" in content and "&lt;script&gt;" in content
        try:
            render_diagnostic({**actual, "verified": False})
        except ValueError:
            pass
        else:
            raise AssertionError("E_OFFLINE_BAD_DIAGNOSTIC_ACCEPTED")
    elif case == "OFF-21":
        config = json.loads((directory / "config.json").read_text())
        assert config == json.loads((ROOT / "config/live.example.json").read_text())
        with (
            patch.object(socket, "socket", side_effect=AssertionError("NETWORK_ATTEMPT")) as direct,
            patch.object(
                socket, "create_connection", side_effect=AssertionError("NETWORK_ATTEMPT")
            ) as connection,
        ):
            result = check_live_readiness(config, {}, {})
            actual = {
                "result": result,
                "network_attempts": direct.call_count + connection.call_count,
            }
        assert actual == json.loads((directory / "observed.json").read_text())
        assert actual["network_attempts"] == 0
        assert result["LIVE_READ_ONLY_READY"] == "PENDING_REAL_INPUTS_AND_LIVE_REVIEW"
        assert result["checks"]["provider_key"] == "PENDING_KEY"
        assert result["checks"]["capture_profile"] == "PENDING_REAL_INPUTS"
    elif case == "OFF-22":
        verify(root / "reference.json")
        actual = json.loads((directory / "observed.json").read_text())
        required = [
            "negative-" + case + "-" + kind + ".json"
            for kind in ["missing", "tampered", "duplicate", "forged"]
        ]
        assert actual == {"rejected_inputs": required}
        baseline = json.loads((root / "reference.json").read_text())
        for kind, name in zip(
            ["missing", "tampered", "duplicate", "forged"], required, strict=True
        ):
            expected = copy.deepcopy(baseline)
            if kind in {"missing", "tampered"}:
                ref = expected["records"][0]["artifacts"][0]
                if kind == "tampered":
                    assert (directory / "tampered.bin").read_bytes() == (
                        (root / ref["relative_path"]).read_bytes() + b"changed"
                    )
                ref["relative_path"] = f"{case}/{kind}.bin"
            elif kind == "duplicate":
                expected["records"].append(copy.deepcopy(expected["records"][0]))
            else:
                expected["OFFLINE_SLICE_PASS"] = "YES"  # noqa: S105 -- status
            assert json.loads((root / name).read_text()) == expected
            try:
                verify(root / name)
            except FileNotFoundError:
                assert kind == "missing"
            except ValueError as exc:
                assert str(exc) == {
                    "tampered": "E_OFFLINE_ARTIFACT_HASH",
                    "duplicate": "E_OFFLINE_CASE_INVENTORY",
                    "forged": "E_OFFLINE_FORGED_PASS",
                }.get(kind)
            else:
                raise AssertionError("E_OFFLINE_GATE_NEGATIVE_ACCEPTED")
    elif case == "OFF-25":
        verify(root / "reference.json")
        actual = json.loads((directory / "observed.json").read_text())
        assert actual == {"source_path": "config/live.example.json"}
        original = (directory / "original-config.json").read_bytes()
        changed = (directory / "changed-config.json").read_bytes()
        assert original == (ROOT / actual["source_path"]).read_bytes() and changed != original
        current = source_hashes()
        expected_changed = {**current, actual["source_path"]: hashlib.sha256(changed).hexdigest()}
        assert json.loads((directory / "changed-sources.json").read_text()) == expected_changed
        baseline = json.loads((root / "reference.json").read_text())["provenance"][
            "source_tree_sha256"
        ]
        assert (
            hashlib.sha256(json.dumps(expected_changed, sort_keys=True).encode()).hexdigest()
            != baseline
        )
    else:
        raise ValueError("E_OFFLINE_META_CASE")
    return {"case_id": case, "oracle_passed": True, "reason": "VERIFIED_REPORT_OR_NEGATIVE_CONTROL"}"""Parent-only expectations. Never imported by browser, receiver, or storage readers."""

import base64
import hashlib
import json
from pathlib import Path
from typing import Any

import rfc8785

from moj_discovery.canonical import canonical_content_hash
from moj_discovery.input_journal import InputJournal
from moj_discovery.offline_projection import semantic_projection
from moj_discovery.store import VENDOR
from moj_discovery.synthetic_source import load_synthetic_observations
from tools.offline_harness import poison_inputs


def assert_case(case_id: str, run_dir: Path) -> dict[str, Any]:
    if not __debug__:
        raise RuntimeError("E_OFFLINE_OPTIMIZED_EXECUTION")
    directory = run_dir.parent
    timing = json.loads((directory / "timings.json").read_text())
    assert timing["execution_and_replay_seconds"] <= (120 if case_id == "OFF-19" else 30)
    observed = json.loads((directory / "readback.json").read_text())
    reader = observed["reader"]
    assert reader["status"] == "OK"
    actual = semantic_projection(run_dir / "run.sqlite3")
    count = len(actual["raw_commits"])
    expected = {
        "OFF-08": 1,
        "OFF-09": 0,
        "OFF-10": 0,
        "OFF-23": 1,
        "OFF-01": 3,
        "OFF-02": 3,
        "OFF-03": 1,
        "OFF-04": 1,
        "OFF-05": 0,
        "OFF-06": 1,
        "OFF-07": 1,
        "OFF-11": 0,
        "OFF-12": 0,
        "OFF-13": 1,
        "OFF-14": 1,
        "OFF-15": 1,
        "OFF-16": 3,
        "OFF-17": 3,
        "OFF-18": 0,
        "OFF-19": 1000,
        "OFF-24": 1,
        "OFF-26": 0,
        "OFF-27": 2,
    }
    assert count == expected[case_id]
    ack = int(reader["state"]["ackSequence"])
    expected_ack = (
        0
        if case_id
        in {
            "OFF-05",
            "OFF-08",
            "OFF-09",
            "OFF-10",
            "OFF-23",
            "OFF-11",
            "OFF-12",
            "OFF-15",
            "OFF-18",
            "OFF-26",
            "OFF-27",
        }
        else count
    )
    assert ack == expected_ack
    writer = observed["writer"]
    if case_id in {"OFF-08", "OFF-09", "OFF-10", "OFF-23"}:
        wire = json.loads((directory / "wire-observed.json").read_text())["observed"]
        assert sum("rejected" in item for item in wire) == (
            4 if case_id == "OFF-23" else (2 if case_id == "OFF-10" else 1)
        )
        if case_id == "OFF-10":
            assert all(
                item.get("rejected") == "HTTP" and item.get("status") == 403 for item in wire
            )
        elif case_id in {"OFF-08", "OFF-09"}:
            assert all(item.get("after_ready") is True for item in wire if "rejected" in item)
        else:
            assert all(item.get("after_ready") is False for item in wire if "rejected" in item)
    if case_id in {"OFF-11", "OFF-12", "OFF-15", "OFF-18", "OFF-26"}:
        code = {
            "OFF-11": "E_OFFLINE_SCHEMA",
            "OFF-12": "E_OFFLINE_SOURCE_BINDING",
            "OFF-15": "E_SPOOL_ACK",
            "OFF-18": "E_SPOOL_CAPACITY",
            "OFF-26": "E_SPOOL_SCHEMA",
        }[case_id]
        assert any(item.get("status") == "REJECTED" and item.get("code") == code for item in writer)
    if case_id == "OFF-11":
        rejected = [r for r in writer if r.get("status") == "REJECTED"]
        assert len(rejected) == 5 and all(r["code"] == "E_OFFLINE_SCHEMA" for r in rejected)
        assert reader["retained"] == [] and reader["state"]["nextSequence"] == "1"
        raw = load_synthetic_observations(directory / "scenario.json")[0]
        needles: set[bytes] = set()
        for poisoned in poison_inputs(raw):
            key = next(key for key in poisoned if key not in raw)
            value = poisoned[key].encode()
            needles.update(
                [
                    value,
                    base64.b64encode(value),
                    value.hex().encode(),
                    hashlib.sha256(value).hexdigest().encode(),
                ]
            )
            for data in [
                rfc8785.dumps(poisoned),
                json.dumps(poisoned, separators=(",", ":")).encode(),
            ]:
                needles.add(hashlib.sha256(data).hexdigest().encode())
            needles.add(
                canonical_content_hash(
                    "RawObservation",
                    poisoned,
                    registry_path=VENDOR / "registries/canonical-hash-domains.v1.json",
                ).encode()
            )
        overlap = max(map(len, needles)) - 1
        for path in directory.rglob("*"):
            if path.is_file():
                with path.open("rb") as stream:
                    tail = b""
                    while chunk := stream.read(1048576):
                        block = tail + chunk
                        assert not any(needle in block for needle in needles), (
                            "E_OFFLINE_POISON_LEAK"
                        )
                        tail = block[-overlap:]
    if case_id == "OFF-18":
        assert 0 < len(reader["retained"]) < 3
        assert int(reader["state"]["nextSequence"]) == len(reader["retained"]) + 1
    if case_id in {"OFF-13", "OFF-14"}:
        assert actual["stream_generations"][0]["generation_state"] != "ACTIVE"
        assert actual["gap_records"]
        frames = [frame for item in writer for frame in item.get("frames", [])]
        assert frames[-1]["message_type"] == "NACK"
        assert frames[-1]["body"]["code"] == ("GAP" if case_id == "OFF-13" else "CONFLICT")
    if case_id == "OFF-05":
        checkpoints = [point for item in writer for point in item.get("checkpoints", [])]
        assert checkpoints[-1]["stage"] == "BEFORE_IDB_COMMIT"
        assert checkpoints[-1]["workerId"] != reader["workerId"]
        assert reader["retained"] == [] and reader["state"]["nextSequence"] == "1"
    if case_id == "OFF-06":
        restarts = [r for r in writer if r.get("operation") == "RESTART_WORKER"]
        assert len(restarts) == 2 and all(r["status"] == "WORKER_TERMINATED" for r in restarts)
        initializations = [r for r in writer if r.get("operation") == "INIT"]
        assert len(initializations) == 3
        assert len({r["workerId"] for r in initializations}) == 3
        for resumed in initializations[1:]:
            assert resumed["state"]["nextSequence"] == "2"
            assert resumed["state"]["ackSequence"] == "0"
            assert resumed["state"]["pendingCount"] == 1
        points = [
            p
            for r in writer
            for p in r.get("checkpoints", [])
            if p.get("stage") == "AFTER_ACK_BEFORE_LOCAL_PERSIST"
        ]
        assert points and points[-1]["workerId"] == initializations[1]["workerId"]
        assert points[-1]["sequence"] == "1"
        assert points[-1]["cursorHash"] == actual["ack_outbox"][0]["cursor_hash"]
    if case_id in {"OFF-04", "OFF-24"}:
        checkpoint = json.loads((run_dir / "checkpoint.json").read_text())
        killed = json.loads((directory / "backend.json").read_text())
        restarted = json.loads((directory / "backend-restarted.json").read_text())
        assert checkpoint["pid"] == killed["pid"] != restarted["pid"] and killed["exit"] == -9
        assert checkpoint["run_id"] == InputJournal(run_dir).context["run_id"]
        assert checkpoint["stage"] == ("AFTER_APPLY" if case_id == "OFF-04" else "AFTER_RECEIVED")
    if case_id == "OFF-27":
        frames = [frame for item in writer for frame in item.get("frames", [])]
        assert [frame["message_type"] for frame in frames] == ["ACK", "NACK"]
        assert frames[0]["body"]["highest_contiguous_sequence"] == "2"
        assert frames[1]["body"]["code"] == "STORAGE_FAILED"
        assert (run_dir / "sqlite-faults.jsonl").is_file()
    if case_id == "OFF-16":
        assert json.loads((directory / "replay-rejected.json").read_text()) == {"rejected": True}
    else:
        replay = json.loads((directory / "replay/replay-result.json").read_text())
        assert replay["equal"] is True
        if case_id in {"OFF-02", "OFF-03", "OFF-06"}:
            assert replay["deliveries"] == count + 1
        if case_id == "OFF-17":
            before = (directory / "readback.json").read_bytes()
            try:
                assert count == 999999
            except AssertionError:
                pass
            else:
                raise AssertionError("E_OFFLINE_ORACLE_CONTROL")
            assert (directory / "readback.json").read_bytes() == before
    if case_id == "OFF-19":
        assert replay["deliveries"] == 1001
        assert [
            row["sequence"]
            for row in sorted(actual["raw_commits"], key=lambda row: row["sequence"])
        ] == list(range(1, 1001))
        assert reader["state"]["pendingCount"] == 0
        assert observed["elapsed_seconds"] <= 120
    else:
        assert observed["elapsed_seconds"] <= 30
    return {
        "case_id": case_id,
        "actual_count": count,
        "ack": ack,
        "oracle_passed": True,
        "highest_sequence": max((row["sequence"] for row in actual["raw_commits"]), default=0),
        "gap_count": len(actual["gap_records"]),
        "replay": "EXPECTED_REJECTION" if case_id == "OFF-16" else "EQUAL",
    }"""Parent aggregation of observed executions, with exact source provenance."""

import hashlib
import json
import subprocess
from pathlib import Path
from typing import Any, cast
from uuid import uuid4

from tools.offline_browser import ROOT
from tools.offline_harness import source_hashes


def reference(path: Path, root: Path) -> dict[str, Any]:
    data = path.read_bytes()
    return {
        "relative_path": str(path.relative_to(root)),
        "sha256": hashlib.sha256(data).hexdigest(),
        "bytes": len(data),
    }


def inventory() -> list[dict[str, Any]]:
    return cast(
        list[dict[str, Any]],
        json.loads((ROOT / "registries/offline-cases.json").read_text())["cases"],
    )


def build_result(
    root: Path,
    scenario: str,
    records: list[dict[str, Any]],
    diagnostic_name: str = "diagnostic.html",
) -> dict[str, Any]:
    first = json.loads((root / "OFF-01/browser/identity.json").read_text())
    context = json.loads((root / "OFF-01/run/context.json").read_text())
    current = source_hashes()
    provenance = {
        "schema_version": "offline-provenance/v1",
        "source_kind": "SYNTHETIC_TEST",
        "run_id": str(uuid4()),
        "scenario_id": scenario,
        "code_revision": subprocess.check_output(
            ["/usr/bin/git", "rev-parse", "HEAD"], cwd=ROOT, text=True
        ).strip(),
        "source_tree_sha256": hashlib.sha256(
            json.dumps(current, sort_keys=True).encode()
        ).hexdigest(),
        "browser_sha256": first["binary_sha256"],
        "browser_version": first["version"]["product"],
        "extension_origin": context["allowed_extension_origin"],
        "termination_kind": "OWNED_POSIX_PROCESS",
        "power_loss_qualified": False,
        "production_authority": "NONE",
    }
    for field, path in {
        "vendor_sha256": "vendor/hybrid-discovery-v6.3.6/SCHEMA_SHA256.json",
        "python_lock_sha256": "uv.lock",
        "node_lock_sha256": "pnpm-lock.yaml",
        "scenario_sha256": "registries/offline-cases.json",
    }.items():
        provenance[field] = hashlib.sha256((ROOT / path).read_bytes()).hexdigest()
    required = [row["case_id"] for row in inventory()] if scenario == "acceptance" else ["OFF-01"]
    return {
        "schema_version": "offline-slice-result/v1",
        "source_kind": "SYNTHETIC_TEST",
        "run_id": provenance["run_id"],
        "OFFLINE_SLICE_PASS": "YES"
        if scenario == "acceptance"
        and [r["case_id"] for r in records] == required
        and all(r["status"] == "PASS" for r in records)
        else "NO",
        "LIVE_PREFLIGHT_IMPLEMENTED": "YES",
        "LIVE_READ_ONLY_READY": "PENDING_REAL_INPUTS_AND_LIVE_REVIEW",
        "MONEY_READY": "NO",
        "LEGACY_FULL_QUALIFICATION": "HOLD",
        "INDEPENDENT_SECURITY_REVIEW": "NOT_RUN",
        "provenance": provenance,
        "required_case_ids": required,
        "records": records,
        "diagnostic": reference(root / diagnostic_name, root),
        "production_authority": "NONE",
    }


def artifacts(root: Path, case: str) -> list[dict[str, Any]]:
    return [
        reference(path, root)
        for path in sorted((root / case).rglob("*"))
        if path.is_file() and "profile" not in path.parts and "offline-extension" not in path.parts
    ]


def gate_view(result: dict[str, Any], cases: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        "verified": True,
        "OFFLINE_SLICE_PASS": result["OFFLINE_SLICE_PASS"],
        "run_id": result["run_id"],
        "source_kind": "SYNTHETIC_TEST",
        "code_revision": result["provenance"]["code_revision"],
        "cases": cases,
        "production_authority": "NONE",
        "MONEY_READY": "NO",
        "LIVE_READ_ONLY_READY": "PENDING_REAL_INPUTS_AND_LIVE_REVIEW",
    }"""Adversarial real WebSocket peer; keys remain in the parent process memory."""

import asyncio
import hashlib
import hmac
import json
import secrets
from typing import Any
from uuid import uuid4

import rfc8785
from websockets.asyncio.client import connect
from websockets.exceptions import ConnectionClosed, InvalidStatus
from websockets.typing import Origin

from moj_discovery.offline_protocol import SessionState, encode_frame, verify_frame


def run_wire_case(
    case_id: str,
    context: dict[str, Any],
    credentials: list[dict[str, Any]],
    rows: list[dict[str, Any]],
) -> dict[str, Any]:
    async def run() -> dict[str, Any]:
        observed: list[dict[str, Any]] = []
        attempts = 5 if case_id == "OFF-23" else (2 if case_id == "OFF-10" else 1)
        for attempt in range(attempts):
            credential = credentials[0 if case_id == "OFF-23" and attempt == 3 else attempt]
            key = bytes(credential["key"])
            state = SessionState(credential["sessionId"], context["run_id"], "CLIENT")
            url = context["backend_url"]
            origin = context["allowed_extension_origin"]
            if case_id == "OFF-10":
                if attempt == 0:
                    origin = "https://example.invalid"
                else:
                    url += "/forbidden"
            try:
                async with connect(
                    url, origin=Origin(origin), compression=None, open_timeout=5, close_timeout=2
                ) as socket:
                    if case_id == "OFF-23" and attempt in {1, 2}:
                        body = {
                            "run_id": context["run_id"],
                            "client_nonce": secrets.token_urlsafe(32),
                        }
                        if attempt == 2:
                            body["server_nonce"] = secrets.token_urlsafe(32)
                        frame = {
                            "protocol": "BH_OFFLINE_WIRE_V1",
                            "session_id": state.session_id,
                            "direction": "BACKEND_TO_CLIENT"
                            if attempt == 1
                            else "CLIENT_TO_BACKEND",
                            "counter": "1",
                            "message_type": "HELLO" if attempt == 1 else "READY",
                            "body": body,
                        }
                        # Deliberate invalid-direction/order peer; normal codec rejects it locally.
                        frame["mac"] = hmac.new(
                            key, b"BH-OFFLINE-WIRE/v1\0" + rfc8785.dumps(frame), hashlib.sha256
                        ).hexdigest()
                        await socket.send(rfc8785.dumps(frame).decode())
                        await asyncio.wait_for(socket.recv(), 5)
                        raise AssertionError("E_OFFLINE_HANDSHAKE_BYPASS_ACCEPTED")
                    await socket.send(
                        state.send(
                            "HELLO",
                            {
                                "run_id": context["run_id"],
                                "client_nonce": secrets.token_urlsafe(32),
                            },
                            key,
                        ).decode()
                    )
                    welcome = verify_frame(
                        (await asyncio.wait_for(socket.recv(decode=True), 5)).encode(), key, state
                    )
                    if case_id == "OFF-23" and attempt == 0:
                        forged = {**welcome["body"], "server_nonce": secrets.token_urlsafe(32)}
                        await socket.send(
                            encode_frame(
                                {
                                    "protocol": "BH_OFFLINE_WIRE_V1",
                                    "session_id": state.session_id,
                                    "direction": "CLIENT_TO_BACKEND",
                                    "counter": "2",
                                    "message_type": "READY",
                                    "body": forged,
                                },
                                key,
                            ).decode()
                        )
                        await asyncio.wait_for(socket.recv(), 5)
                        raise AssertionError("E_OFFLINE_NONCE_ACCEPTED")
                    await socket.send(state.send("READY", welcome["body"], key).decode())
                    verify_frame(
                        (await asyncio.wait_for(socket.recv(decode=True), 5)).encode(), key, state
                    )
                    body = {
                        name: context[name]
                        for name in (
                            "run_id",
                            "browser_run_id",
                            "producer_id",
                            "stream_id",
                            "generation",
                        )
                    }
                    body.update(
                        batch_id=str(uuid4()),
                        first_sequence="1",
                        last_sequence="1",
                        observations=rows[:1],
                    )
                    data = state.send("BATCH", body, key).decode()
                    if case_id == "OFF-09":
                        frame = json.loads(data)
                        frame["mac"] = "0" * 64
                        data = json.dumps(frame)
                    await socket.send(data)
                    response = verify_frame(
                        (await asyncio.wait_for(socket.recv(decode=True), 5)).encode(), key, state
                    )
                    observed.append(
                        {"message_type": response["message_type"], "body": response["body"]}
                    )
                    if case_id == "OFF-08":
                        await socket.send(data)
                        await asyncio.wait_for(socket.recv(), 5)
                        raise AssertionError("E_OFFLINE_COUNTER_ACCEPTED")
            except InvalidStatus as error:
                observed.append({"rejected": "HTTP", "status": error.response.status_code})
            except ConnectionClosed:
                observed.append({"rejected": "CONNECTION_CLOSED", "after_ready": state.ready})
        return {"case_id": case_id, "observed": observed}

    return asyncio.run(run())"""Isolated ordinary SQL/browser owner entrypoints; never receives an oracle."""

from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path
from time import monotonic, sleep

if __package__ in {None, ""}:
    root = Path(__file__).resolve().parents[1]
    sys.path[:0] = [str(root / "src"), str(root)]

from moj_discovery.ingest import Ingestor  # noqa: E402
from moj_discovery.store import RunStore  # noqa: E402
from tools.loopback_ack_crash_child import provision  # noqa: E402
from tools.restart_state_reader import read_restart_state  # noqa: E402
from tools.run_indexeddb_crash_matrix import PACK, run_indexeddb_case  # noqa: E402


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("mode", choices=("case", "sql-setup", "sql-input", "sql-read"))
    parser.add_argument("input", type=Path)
    parser.add_argument("--start", required=True, type=Path)
    args = parser.parse_args()
    args.start.with_suffix(".ready").write_text(str(os.getpid()))
    deadline = monotonic() + 20
    while not args.start.exists():
        if monotonic() > deadline:
            raise ValueError("E_OWNER_MUTATION_START")
        sleep(0.01)
    request = json.loads(args.input.read_text())
    case = args.input.parent
    if args.mode == "case":
        entry = next(
            item
            for item in json.loads(
                (PACK / "docs/registries/crash-harness-registry.v1.json").read_text()
            )["entries"]
            if item["vector_id"] == request["case_id"]
        )
        if entry["harness"] == "SQLITE_TRANSACTION":
            from tools.owner_mutation_evidence import run_sql_input
            from tools.run_sqlite_crash_matrix import run_sqlite_crash_matrix

            result = (
                run_sql_input(entry, case / "execution")
                if request["kind"] == "INPUT"
                else run_sqlite_crash_matrix(
                    PACK, case / "execution", entries=[entry], include_mutations=False
                )["records"][0]
            )
        else:
            result = run_indexeddb_case(
                entry,
                case / "execution",
                full=True,
                operation="crash" if entry["harness"] == "CHROME_INDEXEDDB" else "deliver",
                input_rejection=request["kind"] == "INPUT",
            )
    elif args.mode == "sql-setup":
        provision(case, request["observation"])
        result = {"completed": True}
    elif args.mode == "sql-read":
        result = read_restart_state(case / request["run_id"])
    else:
        result = Ingestor(RunStore(case / request["run_id"] / "run.sqlite3")).apply(
            request["observation"]
        )
    print(json.dumps({"pid": os.getpid(), "result": result}, sort_keys=True))


if __name__ == "__main__":
    try:
        main()
    except ValueError as error:
        print(json.dumps({"pid": os.getpid(), "result": {"observed_error": str(error)}}))
        raise SystemExit(1) from error"""Fresh registered mutation executions using the approved ordinary owners."""

from __future__ import annotations

import copy
import json
import subprocess
import sys
from collections.abc import Callable
from pathlib import Path
from time import monotonic, sleep
from typing import Any
from uuid import uuid4

from tools.inspect_restart_state import _kill_owned_child, inspect_restart_state
from tools.run_gap_coherence_crash_matrix import (
    _artifact,
    _proc_observation,
    _verify_proc_observation,
)
from tools.run_indexeddb_crash_matrix import PACK, ROOT, _observations

CHILD = ROOT / "tools/owner_mutation_child.py"


def save(path: Path, value: Any) -> dict[str, str]:
    path.write_text(json.dumps(value, sort_keys=True, separators=(",", ":")))
    return _artifact(path)


def process(
    case: Path, mode: str, request: dict[str, Any], name: str, *, rejection: bool = False
) -> tuple[Any, dict[str, Any]]:
    descriptor = save(case / (name + "-input.json"), request)
    start = case / (name + ".start")
    command = [
        str(Path(sys.executable).absolute()),
        "-I",
        str(CHILD),
        mode,
        descriptor["path"],
        "--start",
        str(start),
    ]
    stdout, stderr = case / (name + ".stdout"), case / (name + ".stderr")
    with stdout.open("wb") as output, stderr.open("wb") as error:
        child = subprocess.Popen(command, stdout=output, stderr=error, start_new_session=True)  # noqa: S603
        try:
            deadline = monotonic() + 20
            ready = start.with_suffix(".ready")
            while not ready.exists():
                if child.poll() is not None or monotonic() > deadline:
                    raise ValueError("E_OWNER_MUTATION_START:" + stderr.read_text())
                sleep(0.01)
            observed, raw = _proc_observation(child, case / (name + "-process.json"))
            if ready.read_text() != str(child.pid):
                raise ValueError("E_OWNER_MUTATION_PROCESS")
            start.write_text(str(child.pid))
            code = child.wait(timeout=90)
        finally:
            if child.poll() is None:
                _kill_owned_child(child)
                child.wait(timeout=5)
    if code != int(rejection) or stderr.read_bytes():
        raise ValueError("E_OWNER_MUTATION_CHILD:" + stdout.read_text() + stderr.read_text())
    envelope = json.loads(stdout.read_text())
    if set(envelope) != {"pid", "result"} or envelope["pid"] != child.pid:
        raise ValueError("E_OWNER_MUTATION_PROCESS")
    return envelope["result"], {
        "name": name,
        "mode": mode,
        "command": command,
        "pid": child.pid,
        "pgid": child.pid,
        "exit": code,
        "observed": observed,
        "raw": raw,
        "input": descriptor,
        "stdout": _artifact(stdout),
        "stderr": _artifact(stderr),
    }


def verify_process(
    row: dict[str, Any],
    case: Path,
    mode: str,
    name: str,
    request: dict[str, Any],
    result: Any,
    *,
    rejection: bool = False,
) -> None:
    from tools.verify_repair_evidence import _read_retained, _sqlite_descriptor, _sqlite_file

    owner = {"case_directory": str(case)}
    command = [
        str(Path(sys.executable).absolute()),
        "-I",
        str(CHILD),
        mode,
        str(case / (name + "-input.json")),
        "--start",
        str(case / (name + ".start")),
    ]
    _verify_proc_observation(row["observed"], row["raw"], command)
    if (
        row["command"] != command
        or row["name"] != name
        or row["mode"] != mode
        or row["pid"] != row["pgid"]
        or row["pid"] != row["observed"]["pid"]
        or row["pgid"] != row["observed"]["pgid"]
        or row["exit"] != int(rejection)
        or row["input"]["path"] != command[4]
        or _sqlite_descriptor(owner, row["input"], "E_OWNER_MUTATION_INPUT") != request
    ):
        raise ValueError("E_OWNER_MUTATION_PROCESS")
    for stream in ("stdout", "stderr"):
        descriptor = row[stream]
        path = _sqlite_file(
            owner, descriptor["path"], descriptor["sha256"], "E_OWNER_MUTATION_OUTPUT"
        )
        if path != case / (name + "." + stream):
            raise ValueError("E_OWNER_MUTATION_OUTPUT")
        if stream == "stderr" and _read_retained(path):
            raise ValueError("E_OWNER_MUTATION_OUTPUT")
    if _sqlite_descriptor(owner, row["stdout"], "E_OWNER_MUTATION_OUTPUT") != {
        "pid": row["pid"],
        "result": result,
    }:
        raise ValueError("E_OWNER_MUTATION_OUTPUT")


def run_sql_input(entry: dict[str, Any], case: Path) -> dict[str, Any]:
    case.mkdir(parents=True, exist_ok=False)
    run_id = str(uuid4())
    original = _observations(run_id)[0]
    altered = {**original, "content_hash": "0" * 64}
    _, setup = process(case, "sql-setup", {"observation": original}, "setup")
    before, reader_before = process(case, "sql-read", {"run_id": run_id}, "reader-before")
    result, trial = process(
        case, "sql-input", {"run_id": run_id, "observation": altered}, "trial", rejection=True
    )
    after, reader_after = process(case, "sql-read", {"run_id": run_id}, "reader-after")
    return {
        "case_id": entry["vector_id"],
        "case_directory": str(case),
        "identity": {
            "run_id": run_id,
            "case_id": entry["vector_id"],
            "checkpoint_id": entry["crash_checkpoint"],
        },
        "original_input": original,
        "mutated_input": altered,
        "before": before,
        "after": after,
        "observed_error": result.get("observed_error"),
        "processes": [setup, reader_before, trial, reader_after],
    }


def compare_mutation(execution: dict[str, Any], oracle: dict[str, Any]) -> None:
    actual: dict[str, object]
    if execution.get("execution_kind") == "SQLITE_TRANSACTION_PROCESS_CRASH":
        actual = {"retained_rows": len(execution["actual"]["before"]["tables"]["raw_commits"])}
    else:
        actual = {"retained_rows": len(execution["actual"]["entries"])}
    inspect_restart_state(actual, oracle)


def campaign(
    entries: list[dict[str, Any]], workspace: Path, controls: list[dict[str, Any]]
) -> list[dict[str, Any]]:
    from tools.verify_repair_evidence import capture_binding

    binding = capture_binding()
    mutations = []
    for entry, control in zip(entries, controls, strict=True):
        for kind, mutation_id in zip(
            ("EXPECTED", "INPUT"), entry["mutation_vector_ids"], strict=True
        ):
            case = (workspace / mutation_id).resolve()
            case.mkdir(parents=True, exist_ok=False)
            request = {"case_id": entry["vector_id"], "kind": kind}
            execution, launched = process(case, "case", request, "owner")
            oracle = {"retained_rows": 99} if kind == "EXPECTED" else None
            if kind == "EXPECTED":
                assert oracle is not None
                try:
                    compare_mutation(execution, oracle)
                except ValueError as error:
                    observed_error = str(error)
                else:
                    raise ValueError("E_OWNER_MUTATION_SURVIVOR")
            else:
                observed_error = execution["observed_error"]
            row = {
                "mutation": mutation_id,
                "vector_id": entry["vector_id"],
                "kind": kind,
                "case_directory": str(case),
                "execution": execution,
                "process": launched,
                "control": control,
                "oracle": oracle,
                "oracle_artifact": save(case / "oracle.json", oracle),
                "observed_error": observed_error,
                "detected": True,
                "evidence_binding": binding,
                "revision": binding["revision"],
                "environment": binding["environment"],
            }
            verify_mutation(entry["harness"], row, binding, terminal=False)
            row["terminal_artifact"] = save(case / "mutation-terminal.json", row)
            mutations.append(row)
    return mutations


def verify_mutation(
    harness: str, row: dict[str, Any], binding: dict[str, Any], *, terminal: bool = True
) -> None:
    from jsonschema.exceptions import ValidationError  # type: ignore[import-untyped]

    from moj_discovery.canonical import canonical_content_hash
    from moj_discovery.schema_registry import validate_artifact
    from tools.verify_repair_evidence import (
        _contains_expected,
        _sqlite_descriptor,
        _validate_sqlite_state,
        _verify_executed,
    )

    required = {
        "mutation",
        "vector_id",
        "kind",
        "execution",
        "process",
        "control",
        "oracle",
        "oracle_artifact",
        "observed_error",
        "detected",
        "evidence_binding",
        "revision",
        "environment",
        "case_directory",
    }
    if not required.issubset(row):
        raise ValueError("E_OWNER_MUTATION_BINDING")
    if terminal and "terminal_artifact" not in row:
        raise ValueError("E_OWNER_MUTATION_TERMINAL")
    entries = [
        item
        for item in json.loads(
            (PACK / "docs/registries/crash-harness-registry.v1.json").read_text()
        )["entries"]
        if item["vector_id"] == row["vector_id"]
    ]
    if len(entries) != 1:
        raise ValueError("E_OWNER_MUTATION_BINDING")
    entry = entries[0]
    kind = row["kind"]
    if (
        harness != entry["harness"]
        or kind not in {"INPUT", "EXPECTED"}
        or row["mutation"] != entry["mutation_vector_ids"][int(kind == "INPUT")]
        or row["evidence_binding"] != binding
        or row["revision"] != binding["revision"]
        or row["environment"] != binding["environment"]
        or row["detected"] is not True
    ):
        raise ValueError("E_OWNER_MUTATION_BINDING")
    execution, control = row["execution"], row["control"]
    if control.get("status") != "PASS" or control.get("result") != "PASS":
        raise ValueError("E_OWNER_MUTATION_CONTROL")
    _verify_executed(control, binding)
    if (
        execution["case_id"] != row["vector_id"]
        or control["case_id"] != row["vector_id"]
        or execution["identity"]["run_id"] == control["identity"]["run_id"]
        or Path(execution["case_directory"]).is_relative_to(Path(control["case_directory"]))
    ):
        raise ValueError("E_OWNER_MUTATION_IDENTITY")
    case = Path(row["case_directory"])
    if not Path(execution["case_directory"]).is_relative_to(case / "execution"):
        raise ValueError("E_OWNER_MUTATION_IDENTITY")
    verify_process(
        row["process"],
        case,
        "case",
        "owner",
        {"case_id": row["vector_id"], "kind": kind},
        execution,
    )
    if _sqlite_descriptor(row, row["oracle_artifact"], "E_OWNER_MUTATION_ORACLE") != row["oracle"]:
        raise ValueError("E_OWNER_MUTATION_ORACLE")
    if kind == "EXPECTED":
        if execution.get("status") != "PASS" or execution.get("result") != "PASS":
            raise ValueError("E_OWNER_MUTATION_TRIAL")
        _verify_executed(execution, binding)
        if (
            row["oracle"] != {"retained_rows": 99}
            or row["observed_error"] != "E_RESTART_STATE_MISMATCH"
        ):
            raise ValueError("E_OWNER_MUTATION_ORACLE")
        try:
            compare_mutation(execution, row["oracle"])
        except ValueError as error:
            if str(error) != row["observed_error"]:
                raise ValueError("E_OWNER_MUTATION_REJECTION") from error
        else:
            raise ValueError("E_OWNER_MUTATION_SURVIVOR")
    elif harness == "SQLITE_TRANSACTION":
        original, altered = execution["original_input"], execution["mutated_input"]
        for observation in (original, altered):
            if _contains_expected(observation):
                raise ValueError("E_OWNER_MUTATION_INPUT")
            try:
                validate_artifact(
                    observation, "raw-observation.schema.json", bootstrap_only=True, vendor=PACK
                )
            except (ValidationError, ValueError) as error:
                raise ValueError("E_OWNER_MUTATION_INPUT") from error
        if (
            altered != {**original, "content_hash": "0" * 64}
            or canonical_content_hash(
                "RawObservation",
                original,
                registry_path=PACK / "registries/canonical-hash-domains.v1.json",
            )
            != original["content_hash"]
            or execution["before"] != execution["after"]
            or row["oracle"] is not None
            or row["observed_error"] != "CONTENT_HASH_MISMATCH"
            or execution["observed_error"] != row["observed_error"]
        ):
            raise ValueError("E_OWNER_MUTATION_INPUT")
        _validate_sqlite_state(execution["before"], {"observation": original}, 0)
        run_id = original["discovery_run_id"]
        if execution["identity"] != {
            "run_id": run_id,
            "case_id": entry["vector_id"],
            "checkpoint_id": entry["crash_checkpoint"],
        }:
            raise ValueError("E_OWNER_MUTATION_IDENTITY")
        values = [
            ("sql-setup", "setup", {"observation": original}, {"completed": True}, False),
            ("sql-read", "reader-before", {"run_id": run_id}, execution["before"], False),
            (
                "sql-input",
                "trial",
                {"run_id": run_id, "observation": altered},
                {"observed_error": "CONTENT_HASH_MISMATCH"},
                True,
            ),
            ("sql-read", "reader-after", {"run_id": run_id}, execution["after"], False),
        ]
        if len(execution["processes"]) != 4 or len({p["pid"] for p in execution["processes"]}) != 4:
            raise ValueError("E_OWNER_MUTATION_PROCESS")
        for p, (mode, name, request, result, rejected) in zip(
            execution["processes"], values, strict=True
        ):
            verify_process(
                p,
                Path(execution["case_directory"]),
                mode,
                name,
                request,
                result,
                rejection=rejected,
            )
    else:
        from tools.verify_repair_evidence import _verify_browser_ack

        _verify_browser_ack(execution, binding, input_mutation=True)
        if row["oracle"] is not None or row["observed_error"] != "E_SPOOL_OBSERVATION_BINDING":
            raise ValueError("E_OWNER_MUTATION_REJECTION")
    if "terminal_artifact" in row and _sqlite_descriptor(
        row, row["terminal_artifact"], "E_OWNER_MUTATION_TERMINAL"
    ) != {k: v for k, v in row.items() if k != "terminal_artifact"}:
        raise ValueError("E_OWNER_MUTATION_TERMINAL")


def browser_input(
    entry: dict[str, Any],
    case: Path,
    socket: str,
    request: dict[str, Any],
    identity: dict[str, Any],
    binding: dict[str, Any],
    extension: Path,
    binary: Path,
    observations: list[dict[str, Any]],
    browser_process: subprocess.Popen[bytes],
    profile: Path,
    sentinel: str,
    inputs: dict[str, Any],
    artifacts: dict[str, Any],
    processes: list[dict[str, Any]],
    readers: list[dict[str, Any]],
    loaded_assets: dict[str, Any],
    marker: dict[str, Any],
    profile_before: dict[str, Any],
    browser_before: dict[str, Any],
    launch: dict[str, Any],
    retain: Callable[..., Any],
    read_browser: Callable[..., Any],
    read_backend: Callable[..., Any],
    stop: Callable[..., Any],
) -> dict[str, Any]:
    from tools.qualify_chrome_indexeddb import _browser_process_observation, _evaluate
    from tools.run_indexeddb_crash_matrix import _call
    from tools.verify_repair_evidence import _verify_browser_ack

    module_hashes_before = {
        str(path.relative_to(extension)): _artifact(path)["sha256"]
        for path in sorted(extension.rglob("*.js"))
    }
    initialize = {
        "identity": request["identity"],
        "options": request["options"],
        "operation": "initialize",
        "observations": [],
    }
    retain("initialize-worker", initialize, is_input=True)
    initialize_id = str(uuid4())
    retain("initialize-output", _call(socket, "startWorker", initialize_id, initialize))
    _call(socket, "terminateWorker", initialize_id)
    before = read_browser("before")
    backend_before, reader_before = process(
        case, "sql-read", {"run_id": identity["run_id"]}, "mutation-reader-before"
    )
    altered = copy.deepcopy(request)
    raw = json.loads(altered["observations"][0])
    raw["content_hash"] = "0" * 64
    altered["observations"][0] = json.dumps(raw, sort_keys=True, separators=(",", ":"))
    retain("mutated-worker", altered, is_input=True)
    worker_id = str(uuid4())
    result = _evaluate(
        socket,
        "globalThis.repairProbe.startWorker("
        + json.dumps(worker_id)
        + ","
        + json.dumps(altered)
        + ")",
    )
    termination = _call(socket, "terminateWorker", worker_id)
    retain("rejection", result)
    if result != {"error": "Error: E_SPOOL_OBSERVATION_BINDING", "worker_id": worker_id}:
        raise ValueError("E_OWNER_MUTATION_REJECTION:" + str(result))
    after = read_browser("after")
    backend_after, reader_after = process(
        case, "sql-read", {"run_id": identity["run_id"]}, "mutation-reader-after"
    )
    readers.extend((reader_before, reader_after))
    stop(False)
    profile_after = retain(
        "profile-after",
        {
            "profile_path": str(profile.resolve()),
            "marker": (profile / "BH_R05_PROFILE_ID").read_text(),
            "sentinel": _call(socket, "readSentinel", identity["profile_id"]),
        },
    )
    browser_after = retain("browser-process-after", _browser_process_observation(browser_process))
    retain("backend-before", backend_before)
    retain("backend-after", backend_after)
    retain("expected", entry["expected_post_restart_state"])
    module_hashes_after = {
        str(path.relative_to(extension)): _artifact(path)["sha256"]
        for path in sorted(extension.rglob("*.js"))
    }
    execution_binding = {"before": module_hashes_before, "after": module_hashes_after}
    execution_binding_path = case / "typescript-execution-binding.json"
    retain("typescript-execution-binding", execution_binding)
    row = {
        "case_id": entry["vector_id"],
        "vector_id": entry["vector_id"],
        "case_directory": str(case.resolve()),
        "status": "PASS",
        "result": "PASS",
        "executed": True,
        "launch_attempted": True,
        "qualification_scope": "BROWSER_LOOPBACK_ACK",
        "execution_kind": "BROWSER_LOOPBACK_ACK",
        "input_rejection": True,
        "identity": identity,
        "worker_id": worker_id,
        "termination": termination,
        "actual": before,
        "browser_after": after,
        "backend_before": backend_before,
        "backend_after": backend_after,
        "observations": observations,
        "expected": entry["expected_post_restart_state"],
        "observed_error": "E_SPOOL_OBSERVATION_BINDING",
        "comparison": {"matched": True},
        "evidence_binding": binding,
        "revision": binding["revision"],
        "environment": binding["environment"],
        "inputs": inputs,
        "artifacts": artifacts,
        "reader_runs": readers,
        "backend_processes": processes,
        "browser": {"executable": str(binary), "sha256": _artifact(binary)["sha256"]},
        "loaded_assets": loaded_assets,
        "profile_readbacks": {
            "before": profile_before,
            "after": profile_after,
            "marker": marker,
            "sentinel": sentinel,
        },
        "browser_provenance": {"launch": launch, "before": browser_before, "after": browser_after},
        "module_hashes": module_hashes_after,
        "typescript_execution_binding": execution_binding,
        "typescript_execution_binding_artifact": _artifact(execution_binding_path),
    }
    _verify_browser_ack(row, binding, terminal=False, input_mutation=True)
    row["terminal_artifact"] = save(case / "terminal-result.json", row)
    return row


def verify_browser_input(
    row: dict[str, Any], inputs: dict[str, Any], artifacts: dict[str, Any], *, terminal: bool
) -> None:
    from tools.run_indexeddb_crash_matrix import PRODUCER, REGISTRY, STREAM, compare_indexeddb_state
    from tools.verify_repair_evidence import (
        _contains_expected,
        _sqlite_descriptor,
        _sqlite_process_prefix,
        _validate_sqlite_state,
    )

    identity = row["identity"]
    expected_identity = {
        k: identity[k]
        for k in (
            "run_id",
            "case_id",
            "checkpoint_id",
            "test_nonce",
            "profile_id",
            "component",
            "ordinal",
            "pid",
        )
    }
    options = {
        "browser_run_id": identity["run_id"],
        "producer_id": PRODUCER,
        "stream_id": STREAM,
        "generation": "0",
        "registry": json.loads(REGISTRY.read_text()),
    }
    worker = inputs["worker"]
    if set(inputs) != {
        "server-input-0",
        "worker",
        "initialize-worker",
        "mutated-worker",
        "browser-reader-before",
        "browser-reader-after",
    } or _contains_expected(inputs):
        raise ValueError("E_OWNER_MUTATION_INPUT")
    wanted = {
        "identity": expected_identity,
        "options": options,
        "operation": "crash" if identity["component"] == "CHROME_INDEXEDDB" else "deliver",
        "observations": [
            json.dumps(value, sort_keys=True, separators=(",", ":"))
            for value in row["observations"]
        ],
        "transport": worker["transport"],
    }
    altered = copy.deepcopy(wanted)
    original = row["observations"][0]
    altered["observations"][0] = json.dumps(
        {**original, "content_hash": "0" * 64}, sort_keys=True, separators=(",", ":")
    )
    if (
        worker != wanted
        or inputs["mutated-worker"] != altered
        or original["discovery_run_id"] != identity["run_id"]
    ):
        raise ValueError("E_OWNER_MUTATION_INPUT")
    from moj_discovery.canonical import canonical_content_hash

    if original["content_hash"] != canonical_content_hash(
        "RawObservation", original, registry_path=REGISTRY
    ):
        raise ValueError("E_OWNER_MUTATION_INPUT")
    initialize = {
        "identity": expected_identity,
        "options": options,
        "operation": "initialize",
        "observations": [],
    }
    if inputs["initialize-worker"] != initialize:
        raise ValueError("E_OWNER_MUTATION_INPUT")
    states = (artifacts["initialize-output"], row["actual"], row["browser_after"])
    for state in states:
        compare_indexeddb_state(state, identity, row["observations"], 0)
    workers = [state["worker_id"] for state in states] + [row["worker_id"]]
    if len(set(workers)) != 4 or row["termination"] != {
        "method": "Worker.terminate",
        "worker_id": row["worker_id"],
    }:
        raise ValueError("E_OWNER_MUTATION_PROCESS")
    if (
        artifacts["rejection"]
        != {"error": "Error: E_SPOOL_OBSERVATION_BINDING", "worker_id": row["worker_id"]}
        or row["observed_error"] != "E_SPOOL_OBSERVATION_BINDING"
    ):
        raise ValueError("E_OWNER_MUTATION_REJECTION")
    if row["backend_before"] != row["backend_after"] or len(row["backend_processes"]) != 1:
        raise ValueError("E_OWNER_MUTATION_STATE")
    server = row["backend_processes"][0]
    prefix = _sqlite_process_prefix(
        server["provenance"],
        ROOT / "tools/loopback_ack_crash_child.py",
        row["evidence_binding"],
        "E_OWNER_MUTATION_PROCESS",
    )
    command = [*prefix, "--browser-server", row["inputs"]["server-input-0"]["path"]]
    _verify_proc_observation(server["observed"], server["raw_process"], command)
    server_identity = {k: v for k, v in expected_identity.items() if k not in {"pid", "profile_id"}}
    config = inputs["server-input-0"]
    ready = artifacts["server-ready-0"]
    if (
        server["argv"] != command
        or server["pid"] != server["observed"]["pid"]
        or server["pgid"] != server["pid"]
        or server["exit"] != -15
        or server["mechanism"] != "POSIX_OWNED_PROCESS_GROUP_SIGTERM_CLEANUP"
        or config
        != {
            "identity": server_identity,
            "observation": original,
            "origin": identity["origin"],
            "token": config["token"],
            "restart": False,
        }
        or ready["identity"] != {**server_identity, "pid": server["pid"]}
        or _sqlite_descriptor(row, server["ready"], "E_OWNER_MUTATION_PROCESS") != ready
        or ready["address"][0] != "127.0.0.1"
        or worker["transport"]
        != {"endpoint": "http://127.0.0.1:" + str(ready["address"][1]), "token": config["token"]}
    ):
        raise ValueError("E_OWNER_MUTATION_PROCESS")
    if [r["name"] for r in row["reader_runs"]] != [
        "mutation-reader-before",
        "mutation-reader-after",
    ] or len({r["pid"] for r in row["reader_runs"]}) != 2:
        raise ValueError("E_OWNER_MUTATION_READER")
    for phase, state in (("before", row["actual"]), ("after", row["browser_after"])):
        if (
            artifacts["browser-" + phase] != state
            or artifacts["backend-" + phase] != row["backend_" + phase]
            or inputs["browser-reader-" + phase] != {**initialize, "operation": "read"}
        ):
            raise ValueError("E_OWNER_MUTATION_READER")
        _validate_sqlite_state(row["backend_" + phase], {"observation": original}, 0)
        reader = next(r for r in row["reader_runs"] if r["name"] == "mutation-reader-" + phase)
        verify_process(
            reader,
            Path(row["case_directory"]),
            "sql-read",
            "mutation-reader-" + phase,
            {"run_id": identity["run_id"]},
            row["backend_" + phase],
        )
    if artifacts["expected"] != row["expected"]:
        raise ValueError("E_OWNER_MUTATION_ORACLE")
    if terminal and _sqlite_descriptor(
        row, row["terminal_artifact"], "E_OWNER_MUTATION_TERMINAL"
    ) != {k: v for k, v in row.items() if k != "terminal_artifact"}:
        raise ValueError("E_OWNER_MUTATION_TERMINAL")"""Build a reviewable extension/launcher ZIP; never install or grant live access."""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import shutil
import sys
import zipfile
from pathlib import Path, PurePosixPath
from typing import Any, cast

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT), str(ROOT / "src")]


def inventory(root: Path) -> dict[str, dict[str, Any]]:
    if root.resolve() != root:
        raise ValueError("E_DELIVERY_PATH")
    result = {}
    for path in sorted(root.rglob("*")):
        if path.resolve() != path:
            raise ValueError("E_DELIVERY_PATH")
        if path.is_dir():
            continue
        if not path.is_file() or path.stat().st_nlink != 1:
            raise ValueError("E_DELIVERY_PATH")
        name = path.relative_to(root).as_posix()
        if name != "DELIVERY_MANIFEST.json":
            raw = path.read_bytes()
            result[name] = {"size_bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest()}
    return result


def validate_delivery(root: Path) -> dict[str, Any]:
    try:
        path = root / "DELIVERY_MANIFEST.json"
        if path.resolve() != path or path.stat().st_nlink != 1 or path.stat().st_size > 1024 * 1024:
            raise ValueError()
        value = json.loads(path.read_bytes())
        files = value["files"]
        if (
            value["schema_version"] != "part-b-delivery/v1"
            or re.fullmatch("[0-9a-f]{40}", value["source_commit"]) is None
            or value["model_enabled"] is not False
            or value["money_ready"] is not False
        ):
            raise ValueError()
        if len({name.casefold() for name in files}) != len(files):
            raise ValueError()
        for name in files:
            if (
                not name
                or "\\" in name
                or PurePosixPath(name).is_absolute()
                or PurePosixPath(name).as_posix() != name
                or any(part in {"", ".", ".."} for part in name.split("/"))
            ):
                raise ValueError()
        if files != inventory(root):
            raise ValueError()
        return cast(dict[str, Any], value)
    except (OSError, KeyError, TypeError, ValueError):
        raise ValueError("E_DELIVERY_INTEGRITY") from None


def package(output: Path) -> dict[str, Any]:
    from moj_discovery.live_intent import source_tree_hash
    from moj_discovery.windows_credential_store import NATIVE_PYTHON
    from tools.qualify_live_platform import build_live_extension
    from tools.run_command_registry import _git_source_identity

    if output.resolve() != output or output.is_relative_to(ROOT) or output.exists():
        raise ValueError("E_DELIVERY_OUTPUT")
    before = _git_source_identity(ROOT)
    source_hash = source_tree_hash(ROOT)
    extension, origin = build_live_extension(output / "build")
    manifest = json.loads((extension / "manifest.json").read_bytes())
    if (
        set(manifest["permissions"]) != {"storage", "sidePanel", "scripting", "activeTab"}
        or manifest["optional_host_permissions"] != ["https://miseojeuplus.espacejeux.com/*"]
        or manifest.get("host_permissions", []) != []
        or manifest["manifest_version"] != 3
    ):
        raise ValueError("E_DELIVERY_PERMISSIONS")
    payload = output / "BettingHelper"
    payload.mkdir()
    shutil.copytree(extension, payload / "extension")
    for name in ("launch_part_b.py", "package_part_b.py"):
        shutil.copyfile(ROOT / "tools" / name, payload / name)
    for name in ("INSTALL_PART_B_VI.md", "RUN_ONE_MATCH_VI.md"):
        shutil.copyfile(ROOT / "docs/runbooks" / name, payload / name)
    native = (
        r"C:\Users\thenam\.cache\codex-runtimes\codex-primary-runtime"
        r"\dependencies\python\python.exe"
    )
    (payload / "Install.cmd").write_bytes(
        (f'@echo off\r\n"{native}" -I -B "%~dp0launch_part_b.py" --install\r\npause\r\n').encode()
    )
    (payload / "Betting Helper.cmd").write_bytes(
        (f'@echo off\r\n"{native}" -I -B "%~dp0launch_part_b.py"\r\npause\r\n').encode()
    )
    (payload / "create-shortcut.vbs").write_text(
        'Set shell = CreateObject("WScript.Shell")\n'
        "Set link = shell.CreateShortcut(WScript.Arguments(0))\n"
        "link.TargetPath = WScript.Arguments(1)\n"
        'link.Arguments = "-I -B " & Chr(34) & WScript.Arguments(2) & Chr(34)\n'
        "link.WorkingDirectory = WScript.Arguments(3)\n"
        'link.Description = "Betting Helper - read only"\n'
        "link.Save\n",
        encoding="ascii",
    )
    credential_files = (
        "tools/windows_credential_helper.py",
        "tools/launch_part_b.py",
        "src/moj_discovery/windows_credential_store.py",
        "src/moj_discovery/secrets_local.py",
    )
    record = {
        "schema_version": "part-b-delivery/v1",
        "source_commit": before["head"],
        "source_tree": before["tree"],
        "source_tree_sha256": source_hash,
        "platform": "WINDOWS_CHROME_WSL2",
        "extension_origin": origin,
        "release_state": "CANDIDATE_WAITING_REVIEW",
        "model_enabled": False,
        "money_ready": False,
        "native_python_sha256": hashlib.sha256(NATIVE_PYTHON.read_bytes()).hexdigest(),
        "backend_credential_files": {
            name: hashlib.sha256((ROOT / name).read_bytes()).hexdigest()
            for name in credential_files
        },
        "files": inventory(payload),
    }
    (payload / "DELIVERY_MANIFEST.json").write_text(json.dumps(record, indent=2) + "\n")
    validate_delivery(payload)
    if before != _git_source_identity(ROOT) or source_tree_hash(ROOT) != source_hash:
        raise ValueError("E_DELIVERY_SOURCE_CHANGED")
    archive = output / "betting-helper-part-b.zip"
    with zipfile.ZipFile(archive, "x", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as stream:
        for path in sorted(payload.rglob("*")):
            if path.is_file():
                entry = zipfile.ZipInfo(
                    "BettingHelper/" + path.relative_to(payload).as_posix(),
                    date_time=(2020, 1, 1, 0, 0, 0),
                )
                entry.external_attr = 0o100644 << 16
                entry.compress_type = zipfile.ZIP_DEFLATED
                stream.writestr(entry, path.read_bytes(), compresslevel=9)
    digest = hashlib.sha256(archive.read_bytes()).hexdigest()
    (output / (archive.name + ".sha256")).write_text(digest + "  " + archive.name + "\n")
    return {
        "zip": str(archive),
        "sha256": digest,
        "source_commit": before["head"],
        "release_state": "CANDIDATE_WAITING_REVIEW",
        "authority": "NONE",
    }


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, required=True)
    print(json.dumps(package(parser.parse_args().output), indent=2))"""Produce ordinary phase proofs from actual registered invocations and logs."""

from __future__ import annotations

import base64
import hashlib
import json
from pathlib import Path
from typing import Any, cast

from tools import run_command_registry as commands
from tools.full_verifier_config import FullVerifierConfig
from tools.retained_artifact_io import RetainedArtifactIO

CONTRACT = "docs/contracts/part-b-one-ready.v1.json"
CURRENT_COMMANDS = {"VALIDATE_CURRENT_DECLARATION", "VALIDATE_CURRENT_DESCENDANT_MIGRATION"}
RESULT_KEYS = {
    "argv",
    "command_id",
    "cwd",
    "expected_exit",
    "exit_code",
    "passed",
    "stdout_sha256",
    "stdout_size_bytes",
    "stderr_sha256",
    "stderr_size_bytes",
}


def read(path: Path, artifacts: RetainedArtifactIO | None = None) -> bytes:
    if artifacts is not None:
        return artifacts.read_bytes(
            str(path), recorded_boundary=artifacts.recorded_boundary(str(path))
        )
    if path.resolve() != path or not path.is_file() or path.stat().st_nlink != 1:
        raise ValueError("E_PHASE_EVIDENCE")
    return path.read_bytes()


def contract(
    config: FullVerifierConfig, artifacts: RetainedArtifactIO | None = None
) -> dict[str, Any] | None:
    registry = json.loads(
        read(
            config.governed_source_pack / "docs/registries/task-command-registry.v1.json", artifacts
        )
    )
    ids = {row["command_id"] for row in registry["commands"]}
    if not ids & CURRENT_COMMANDS:
        return None  # Unamended historical contract keeps its original semantics.
    if not ids >= CURRENT_COMMANDS:
        raise ValueError("E_PHASE_EVIDENCE")
    value = json.loads(read(config.governed_source_pack / CONTRACT, artifacts))
    if (
        value.get("schema_version") != "part-b-one-ready/v1"
        or value.get("production_authority") != "NONE"
        or len(value.get("phases", {})) != 9
    ):
        raise ValueError("E_PHASE_EVIDENCE")
    return cast(dict[str, Any], value)


def expected_commands(
    config: FullVerifierConfig, artifacts: RetainedArtifactIO | None = None
) -> dict[str, dict[str, Any]]:
    registry = json.loads(
        read(
            config.governed_source_pack / "docs/registries/task-command-registry.v1.json", artifacts
        )
    )

    def rebind(value: str) -> str:
        for old, new in (
            (commands.LEGACY_AUTHORING_RUNTIME, str(config.current_checkout_root)),
            (commands.LEGACY_AUTHORING_PACK, str(config.governed_source_pack)),
        ):
            if value == old or value.startswith(old + "/"):
                return new + value[len(old) :]
        return value

    return {
        row["command_id"]: {
            **row,
            "cwd": rebind(row["cwd"]),
            "argv": [rebind(a) for a in row["argv"]],
        }
        for row in registry["commands"]
    }


def validate_execution(command: dict[str, Any], execution: dict[str, Any]) -> None:
    try:
        result = execution["result"]
        if (
            set(execution) != {"result", "stdout", "stderr"}
            or set(result) != RESULT_KEYS
            or any(
                result.get(k) != command[k] for k in ("argv", "command_id", "cwd", "expected_exit")
            )
        ):
            raise ValueError("E_PHASE_EVIDENCE")
        if (
            type(result["exit_code"]) is not int
            or result["exit_code"] != 0
            or command["expected_exit"] != 0
            or result["passed"] is not True
        ):
            raise ValueError("E_PHASE_EVIDENCE")
        for stream in ("stdout", "stderr"):
            raw = base64.b64decode(execution[stream], validate=True)
            if (
                hashlib.sha256(raw).hexdigest() != result[stream + "_sha256"]
                or str(len(raw)) != result[stream + "_size_bytes"]
            ):
                raise ValueError("E_PHASE_EVIDENCE")
    except (KeyError, TypeError, ValueError) as error:
        raise ValueError("E_PHASE_EVIDENCE") from error


def validate_current_output(
    identifier: str,
    execution: dict[str, Any],
    config: FullVerifierConfig,
    identity: dict[str, object],
    artifacts: RetainedArtifactIO | None = None,
) -> None:
    if identifier not in CURRENT_COMMANDS:
        return
    value = json.loads(base64.b64decode(execution["stdout"], validate=True))
    spec = contract(config, artifacts)
    assert spec is not None
    names = [
        "tasks/task-manifest.v6.3.6.json",
        "registries/artifact-ownership.v1.json",
        "schemas/artifact-ownership.schema.json",
        *[
            "registries/" + n
            for n in (
                "task-command-registry.v1.json",
                "review-command-registry.v1.json",
                "cybersecurity-command-registry.v1.json",
                "baseline-replay-command-registry.v1.json",
            )
        ],
    ]
    expected_gate = (
        "CURRENT_DECLARATION_VALID"
        if identifier == "VALIDATE_CURRENT_DECLARATION"
        else "CURRENT_DESCENDANT_SOURCE_VALID"
    )
    if (
        value.get("gate") != expected_gate
        or value.get("result") != "PASS"
        or value.get("production_authority") != "NONE"
        or value.get("source_identity") != identity
        or value.get("contract_sha256")
        != hashlib.sha256(read(config.governed_source_pack / CONTRACT, artifacts)).hexdigest()
        or value.get("input_hashes")
        != {
            name: hashlib.sha256(
                read(config.governed_source_pack / "docs" / name, artifacts)
            ).hexdigest()
            for name in names
        }
    ):
        raise ValueError("E_PHASE_CURRENT_INPUT")
    if identifier == "VALIDATE_CURRENT_DESCENDANT_MIGRATION" and (
        value.get("adopted_source") != spec["adopted_source"]
        or value.get("historical_receipt_sha256") != spec["historical_migration_sha256"]
        or value.get("historical_regressions", {}).get("exit_code") != 0
        or value.get("historical_acceptance") != "NOT_INFERRED"
    ):
        raise ValueError("E_PHASE_CURRENT_INPUT")


def issue_phases(
    config: FullVerifierConfig, extra_results: list[dict[str, object]], identity: dict[str, object]
) -> None:
    spec = contract(config)
    if spec is None:
        return
    before = commands._git_source_identity(config.current_checkout_root)
    if before != identity:
        raise ValueError("E_PHASE_SOURCE_DRIFT")
    candidate = json.loads(read(config.candidate_command_evidence))
    results = [*candidate["results"], *extra_results]
    by_id = {r["command_id"]: r for r in results}
    if len(by_id) != len(results) or candidate["controller_binding"] != config.binding():
        raise ValueError("E_PHASE_EVIDENCE")
    registry = expected_commands(config)
    proofs = {}
    for phase, identifiers in spec["phases"].items():
        executions = []
        for identifier in identifiers:
            result = by_id.get(identifier)
            if result is None:
                raise ValueError("E_PHASE_EVIDENCE")
            execution = {
                "result": result,
                **{
                    stream: base64.b64encode(
                        read(config.evidence_root / "command-logs" / f"{identifier}.{stream}")
                    ).decode()
                    for stream in ("stdout", "stderr")
                },
            }
            validate_execution(registry[identifier], execution)
            validate_current_output(identifier, execution, config, identity)
            executions.append(execution)
        proofs[phase] = {
            "schema_version": "current-phase-proof/v1",
            "task_id": phase,
            "result": "PASS",
            "production_authority": "NONE",
            "controller_binding": config.binding(),
            "source_identity": before,
            "contract_sha256": hashlib.sha256(
                read(config.governed_source_pack / CONTRACT)
            ).hexdigest(),
            "commands": executions,
        }
    if commands._git_source_identity(config.current_checkout_root) != before:
        raise ValueError("E_PHASE_EVIDENCE")
    if any((config.evidence_root / f"{phase}.json").exists() for phase in proofs):
        raise ValueError("E_PHASE_EVIDENCE_EXISTS")
    for phase, proof in proofs.items():
        with (config.evidence_root / f"{phase}.json").open("x") as stream:
            json.dump(proof, stream, sort_keys=True, separators=(",", ":"))
            stream.write("\n")


def verify_phase(
    evidence: dict[str, Any],
    config: FullVerifierConfig,
    artifacts: RetainedArtifactIO | None = None,
) -> None:
    spec = contract(config, artifacts)
    if spec is None:
        return
    phase = evidence.get("task_id")
    if (
        set(evidence)
        != {
            "schema_version",
            "task_id",
            "result",
            "production_authority",
            "controller_binding",
            "source_identity",
            "contract_sha256",
            "commands",
        }
        or evidence["schema_version"] != "current-phase-proof/v1"
        or evidence["result"] != "PASS"
        or evidence["production_authority"] != "NONE"
        or evidence["controller_binding"] != config.binding()
        or phase not in spec["phases"]
        or evidence["contract_sha256"]
        != hashlib.sha256(read(config.governed_source_pack / CONTRACT, artifacts)).hexdigest()
    ):
        raise ValueError("E_PHASE_EVIDENCE")
    expected = spec["phases"][phase]
    executions = evidence["commands"]
    if not isinstance(executions, list) or len(executions) != len(expected):
        raise ValueError("E_PHASE_EVIDENCE")
    registry = expected_commands(config, artifacts)
    for identifier, execution in zip(expected, executions, strict=True):
        validate_execution(registry[identifier], execution)
    if artifacts is None:
        identity = commands._git_source_identity(config.current_checkout_root)
    else:
        assert config.descendant_repository_receipt is not None
        receipt = json.loads(read(config.descendant_repository_receipt, artifacts))
        identity = {
            "head": receipt["repository_commit"],
            "tree": receipt["repository_tree"],
            "source_diff": "",
        }
    if evidence["source_identity"] != identity:
        raise ValueError("E_PHASE_EVIDENCE")
    for identifier, execution in zip(expected, executions, strict=True):
        validate_current_output(identifier, execution, config, identity, artifacts)


def main() -> None:
    import argparse

    from tools.full_verifier_config import load_controller_config

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, required=True)
    args = parser.parse_args()
    config = load_controller_config(args.config)
    inputs = json.loads(read(config.evidence_root / "CURRENT_INPUTS.json"))
    if (
        set(inputs) != {"source_identity", "results", "controller_binding"}
        or inputs["controller_binding"] != config.binding()
    ):
        raise ValueError("E_PHASE_CURRENT_INPUT")
    issue_phases(config, inputs["results"], inputs["source_identity"])
    print("CURRENT_PHASE_PROOFS_ISSUED: SOURCE_VALIDATION_ONLY")


if __name__ == "__main__":
    main()"""Write a nonsecret, unconsumed scope preview. This command does not authorize I/O."""

# ruff: noqa: E402
import json
import os
import sys
from datetime import UTC, datetime, timedelta
from pathlib import Path
from typing import Any
from uuid import uuid4

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT), str(ROOT / "src")]
from moj_discovery.live_config import load_live_config, private_path
from moj_discovery.live_intent import RunIntent, _validate, source_tree_hash
from tools.run_with_api_football_key import SafeParser

STAGES = {
    "provider-probe": "PROVIDER_PROBE",
    "operator-discovery": "OPERATOR_DISCOVERY",
    "live-readonly": "LIVE_READ_ONLY",
}


def main(argv: list[str] | None = None) -> int:
    try:
        parser = SafeParser(description=__doc__, allow_abbrev=False)
        parser.add_argument("--stage", choices=tuple(STAGES), required=True)
        parser.add_argument("--config", type=Path, required=True)
        parser.add_argument("--output", type=Path, required=True)
        parser.add_argument("--duration", type=int)
        parser.add_argument("--attempts", type=int)
        parser.add_argument("--operator-url", action="append", default=[])
        parser.add_argument("--lookup-date")
        args = parser.parse_args(argv)
        config = load_live_config(args.config)
        stage = STAGES[args.stage]
        duration, attempts = {
            "PROVIDER_PROBE": (300, 20),
            "OPERATOR_DISCOVERY": (600, 0),
            "LIVE_READ_ONLY": (
                config.public["runtime"]["max_run_minutes"] * 60,
                config.public["provider"]["max_requests_per_run"],
            ),
        }[stage]
        relative = (
            str(args.output.relative_to(ROOT)) if args.output.is_absolute() else str(args.output)
        )
        target = private_path(relative, root=ROOT)
        now = datetime.now(UTC)
        value = dict(
            schema_version="part-b-run-intent/v1",
            intent_id=str(uuid4()),
            stage=stage,
            config_sha256=config.sha256,
            source_tree_sha256=source_tree_hash(ROOT),
            fixture_ids=list(config.fixture_ids),
            operator_urls=args.operator_url,
            max_duration_seconds=duration if args.duration is None else args.duration,
            max_http_attempts=attempts if args.attempts is None else args.attempts,
            issued_at=now.isoformat(),
            expires_at=(now + timedelta(minutes=15)).isoformat(),
            user_confirmation_required=True,
            money_authority=False,
        )
        if args.lookup_date is not None:
            value["lookup_date"] = args.lookup_date
        _validate(RunIntent(value, "0" * 64, ROOT), config, now)
        if stage == "LIVE_READ_ONLY" and relative != config.public["gates"]["live_intent_path"]:
            raise ValueError()
        target.parent.mkdir(parents=True, mode=0o700, exist_ok=True)
        fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        with os.fdopen(fd, "w") as handle:
            json.dump(value, handle, indent=2)
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        print("INTENT_PREPARED: USER_TERMINAL_CONFIRMATION_REQUIRED")
        print("MAX_DURATION_SECONDS: " + str(value["max_duration_seconds"]))
        print("MAX_HTTP_ATTEMPTS: " + str(value["max_http_attempts"]))
        return 0
    except Exception:
        print("INTENT_NOT_CREATED: INVALID_SCOPE_OR_EXISTING_FILE")
        return 2


def execute_discovery(argv: list[str]) -> int:
    """User-terminal execution only. No API key acquisition or browser attachment."""
    import asyncio

    from moj_discovery.canonical import parse_strict_json
    from moj_discovery.live_intent import (
        consume_user_intent,
        discovery_review_scope,
        load_run_intent,
        serve_operator_discovery,
    )
    from moj_discovery.live_preflight_batched import verify_external_review
    from moj_discovery.secrets_local import controlling_tty

    try:
        parser = SafeParser(allow_abbrev=False)
        parser.add_argument("--config", required=True, type=Path)
        parser.add_argument("--intent", required=True, type=Path)
        mode = parser.add_mutually_exclusive_group(required=True)
        mode.add_argument("--selectors", type=Path)
        mode.add_argument("--selected-region", action="store_true")
        parser.add_argument("--review", required=True, type=Path)
        parser.add_argument("--profile-name", required=True)
        args = parser.parse_args(argv)
        config = load_live_config(args.config)
        intent = load_run_intent(args.intent, config, "OPERATOR_DISCOVERY", root=ROOT)

        def read(path: Path) -> dict[str, Any]:
            relative = str(path.relative_to(ROOT)) if path.is_absolute() else str(path)
            checked = private_path(relative, root=ROOT, must_exist=True)
            if checked.stat().st_size > 65536:
                raise ValueError()
            value = parse_strict_json(checked.read_bytes())
            if type(value) is not dict:
                raise ValueError()
            return value

        selectors = (
            {"selection_mode": "USER_SELECTED_REGION_V1"}
            if args.selected_region
            else read(args.selectors)
        )
        review = read(args.review)
        scope = discovery_review_scope(
            intent,
            config,
            selectors,
            args.profile_name,
            review.get("scope", {}).get("expires_at", ""),
        )
        # No prompt to grant capture until the real independent tool review verifies.
        verified = verify_external_review(review, scope, ROOT, datetime.now(UTC))
        print("STAGE: OPERATOR_DISCOVERY")
        print("PROFILE: " + args.profile_name)
        print("EXACT_URL: " + scope["exact_url"])
        print("MAX_DURATION_SECONDS: " + str(scope["max_duration_seconds"]))
        print("MAX_PROVIDER_REQUESTS: 0")
        print("PROFILE_ACCEPTED: false")
        if args.selected_region:
            print(
                "MAPPING: Selected visible match region only; <=32 candidates; unadmitted."
            )
        print("Type ALLOW OPERATOR OBSERVATION to confirm this exact scope:")
        with controlling_tty() as terminal:
            confirmation = terminal.readline(65).rstrip("\r\n")
        receipt = consume_user_intent(intent, config, confirmation)
        output = ROOT / ".local/part-b/operator-discovery" / receipt.run_id / "result.json"
        result = asyncio.run(
            serve_operator_discovery(
                receipt, selectors, args.profile_name, review, output, verified_review=verified
            )
        )
        print("DISCOVERY_RESULT: " + result["status"])
        print("PROFILE_ACCEPTED: false")
        if args.selected_region:
            print(
                "MAPPING: Selected visible match region only; <=32 candidates; unadmitted."
            )
        return 0 if result["status"] == "UNADMITTED_SAMPLE_SAVED" else 2
    except (Exception, KeyboardInterrupt):
        print("DISCOVERY_NOT_STARTED_OR_REJECTED: CHECK_SCOPE_REVIEW_AND_TERMINAL")
        return 2


if __name__ == "__main__":
    if sys.argv[1:2] == ["execute-discovery"]:
        raise SystemExit(execute_discovery(sys.argv[2:]))
    raise SystemExit(main())"""Prepare a one-use, read-only Bubblewrap review workspace."""

