PREPARATION_DOMAIN = b"HD636/REVIEW-PREPARATION/v1\0"
HOST_PNPM_STORE = Path("/home/thenam176/.local/share/pnpm/store/v10")
HOST_UV_CACHE = Path("/home/thenam176/.cache/uv")
NAMESPACE_SOCKET = Path(os.sep) / "tmp/namespace.sock"
Run = Callable[..., subprocess.CompletedProcess[bytes]]


def _regular(path: Path) -> None:
    if path.is_symlink() or not path.is_file() or stat.S_ISLNK(path.lstat().st_mode):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")


def _directory(path: Path) -> None:
    if path.is_symlink() or not path.is_dir() or stat.S_ISLNK(path.lstat().st_mode):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")


def _sha256(path: Path) -> str:
    _regular(path)
    return hashlib.sha256(path.read_bytes()).hexdigest()


def prepare_review_workspace(config: dict[str, object]) -> dict[str, object]:
    if config.get("schema_version") in {"review-config/v2", "review-config/v3"}:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    return _prepare_review_directories(config)


def _prepare_review_directories(config: dict[str, object]) -> dict[str, object]:
    if config.get("network") != "DENY":
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    excluded_roots = config.get("excluded_roots")
    excluded = set(excluded_roots) if isinstance(excluded_roots, list) else set()
    mounts = config.get("input_mounts")
    if not excluded or not isinstance(mounts, list):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    for mount in mounts:
        if (
            not isinstance(mount, dict)
            or mount.get("mode") != "READ_ONLY"
            or mount.get("source_root") in excluded
            or mount.get("workspace_mount") in excluded
        ):
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    workspace = Path(cast(str, config["workspace_root"]))
    output = Path(cast(str, config["output_root"]))
    if workspace != workspace.resolve() or output != output.resolve():
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    reuse_legacy = config.get("schema_version") != "review-config/v3"
    workspace.mkdir(parents=True, exist_ok=reuse_legacy)
    output.mkdir(parents=True, exist_ok=reuse_legacy)
    return {"result": "PASS", "workspace_root": str(workspace), "output_root": str(output)}


def _config_for_role(role: str, version: int = 1) -> dict[str, object]:
    return review_config_for_role(role, version, runtime_root=RUNTIME_ROOT)


def _config_template(config: dict[str, object]) -> dict[str, object]:
    version = 3 if config.get("schema_version") == "review-config/v3" else 2
    template = _config_for_role(cast(str, config["role"]), version)
    expected = (
        resolve_review_run(template, cast(str, config["review_run_id"]))
        if version == 3
        else template
    )
    if config != expected:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    return template


def _public_key(authority_config: dict[str, object]) -> tuple[Ed25519PublicKey, int]:
    try:
        return review_public_key(authority_config)
    except (OSError, ValueError) as error:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION") from error


def _authority_state(
    authorization: dict[str, object], authority: dict[str, object], *, consume: bool
) -> None:
    state = Path(cast(str, authority["private_key_path"])).parent / "state.sqlite"
    _regular(state)
    connection = sqlite3.connect(state)
    try:
        connection.execute("BEGIN IMMEDIATE")
        key = cast(str, authorization["issuer_key_id"])
        serial = cast(str, authorization["one_use_serial"])
        epoch = connection.execute(
            "SELECT trust_epoch FROM authority_state WHERE key_id = ?", (key,)
        ).fetchone()
        revoked = connection.execute(
            "SELECT 1 FROM revocations WHERE authorization_id = ?",
            (authorization["authorization_id"],),
        ).fetchone()
        consumed = connection.execute(
            "SELECT 1 FROM consumed_serials WHERE authority_key_id = ? AND one_use_serial = ?",
            (key, serial),
        ).fetchone()
        if epoch != (authorization["trust_epoch"],) or revoked is not None:
            raise ValueError("E_REVIEW_LAUNCH_CONSUMED")
        if consume:
            if consumed is not None:
                raise ValueError("E_REVIEW_LAUNCH_CONSUMED")
            connection.execute("INSERT INTO consumed_serials VALUES (?, ?)", (key, serial))
        elif consumed is None:
            raise ValueError("E_REVIEW_LAUNCH_CONSUMED")
        connection.commit()
    except BaseException:
        connection.rollback()
        raise
    finally:
        connection.close()


def _preparation_commands(config: dict[str, object]) -> list[dict[str, object]]:
    leaf_registry = Path(cast(str, config["command_registry_path"]))
    registry_path = leaf_registry.with_name("review-command-registry.v1.json")
    _regular(registry_path)
    registry = json.loads(registry_path.read_text())
    rows = registry.get("commands") if isinstance(registry, dict) else None
    ids = config.get("preparation_command_ids")
    if (
        not isinstance(registry, dict)
        or registry.get("schema_version") != "review-command-registry/v1"
        or not isinstance(rows, list)
        or not isinstance(ids, list)
    ):
        raise ValueError("E_REVIEW_PREPARATION")
    mapped: dict[str, dict[str, object]] = {}
    for row in rows:
        if not isinstance(row, dict) or not isinstance(row.get("command_id"), str):
            raise ValueError("E_REVIEW_PREPARATION")
        command_id = cast(str, row["command_id"])
        if command_id in mapped:
            raise ValueError("E_REVIEW_PREPARATION")
        mapped[command_id] = row
    if len(ids) != 2 or not all(isinstance(item, str) for item in ids):
        raise ValueError("E_REVIEW_PREPARATION")
    commands = [mapped.get(cast(str, item)) for item in ids]
    if any(item is None for item in commands):
        raise ValueError("E_REVIEW_PREPARATION")
    result = cast(list[dict[str, object]], commands)
    for command in result:
        argv = command.get("argv")
        if (
            command.get("kind") != "review-operation"
            or command.get("expected_exit") != 0
            or any(
                command.get(key) != "DENY"
                for key in ("network", "authenticated_operator_access", "provider_access")
            )
            or not isinstance(command.get("cwd"), str)
            or not isinstance(argv, list)
            or not argv
            or not all(isinstance(token, str) and token for token in argv)
        ):
            raise ValueError("E_REVIEW_PREPARATION")
    if config.get("schema_version") == "review-config/v3":
        template = _config_template(config)
        before = cast(dict[str, object], template["node_environment"])["project_root"]
        after = cast(dict[str, object], config["node_environment"])["project_root"]
        result = [{**row, "cwd": after} if row["cwd"] == before else row for row in result]
    return result


def _copy_node_inputs(config: dict[str, object]) -> None:
    node = config.get("node_environment")
    scratch = Path(cast(str, config["scratch_root"]))
    if not isinstance(node, dict) or scratch.exists() or scratch.is_symlink():
        raise ValueError("E_REVIEW_PREPARATION")
    project = Path(cast(str, node.get("project_root")))
    if project.parent != scratch or project.is_symlink():
        raise ValueError("E_REVIEW_PREPARATION")
    inputs = node.get("project_inputs")
    if not isinstance(inputs, list) or len(inputs) != 4:
        raise ValueError("E_REVIEW_PREPARATION")
    project.mkdir(parents=True)
    for item in inputs:
        if (
            not isinstance(item, dict)
            or not isinstance(item.get("source"), str)
            or not isinstance(item.get("destination"), str)
        ):
            raise ValueError("E_REVIEW_PREPARATION")
        source = Path(cast(str, item["source"]))
        destination = PurePosixPath(cast(str, item["destination"]))
        if destination.is_absolute() or any(part in {"", ".", ".."} for part in destination.parts):
            raise ValueError("E_REVIEW_PREPARATION")
        _regular(source)
        target = project.joinpath(*destination.parts)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target, follow_symlinks=False)
        if _sha256(source) != _sha256(target):
            raise ValueError("E_REVIEW_PREPARATION")


def _environment(config: dict[str, object]) -> dict[str, str]:
    supplied = config.get("environment")
    scratch = Path(cast(str, config["scratch_root"]))
    if not isinstance(supplied, dict) or not all(
        isinstance(key, str) and isinstance(value, str) for key, value in supplied.items()
    ):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    home = scratch / "home"
    home.mkdir(parents=True, exist_ok=True)
    tool_paths = filter(None, (shutil.which(command) for command in ("uv", "pnpm")))
    path_entries = {str(Path(path).parent) for path in tool_paths}
    path_entries.update({"/usr/bin", "/bin"})
    return {
        "HOME": str(home),
        "PATH": os.pathsep.join(sorted(path_entries)),
        **cast(dict[str, str], supplied),
    }


def _preparation_environment(
    command: dict[str, object], environment: dict[str, str]
) -> dict[str, str]:
    argv = cast(list[str], command["argv"])
    if argv[0] == "uv":
        _directory(HOST_UV_CACHE)
        return {**environment, "UV_CACHE_DIR": str(HOST_UV_CACHE)}
    if argv[0] != "pnpm":
        return environment
    _directory(HOST_PNPM_STORE)
    node = _node_binary()
    return {
        **environment,
        "PATH": str(node.parent) + os.pathsep + environment["PATH"],
        "npm_config_store_dir": str(HOST_PNPM_STORE),
    }


def _run_preparation(
    config: dict[str, object],
    commands: list[dict[str, object]],
    *,
    execute: Run = subprocess.run,
    log_root: Path | None = None,
) -> list[dict[str, object]]:
    _copy_node_inputs(config)
    environment = _environment(config)
    runtime = _python_runtime_projection(config)
    if runtime is not None:
        environment["UV_PYTHON"] = str(runtime[0] / "bin/python3.12")
    records: list[dict[str, object]] = []
    for command in commands:
        command_environment = _preparation_environment(command, environment)
        cwd = Path(cast(str, command["cwd"]))
        _directory(cwd)
        snapshots = {
            path: _sha256(cwd / path)
            for path in ("pyproject.toml", "uv.lock")
            if (cwd / path).exists()
        }
        completed = execute(
            cast(list[str], command["argv"]),
            cwd=cwd,
            env=command_environment,
            capture_output=True,
        )
        if log_root is not None:
            for stream in ("stdout", "stderr"):
                with (log_root / f"{len(records):02d}.{stream}").open("xb") as output:
                    output.write(getattr(completed, stream))
        after = {path: _sha256(cwd / path) for path in snapshots}
        if completed.returncode != command["expected_exit"] or snapshots != after:
            raise ValueError("E_REVIEW_PREPARATION")
        records.append(
            {
                "command_id": command["command_id"],
                "argv": command["argv"],
                "cwd": str(cwd),
                "environment": command_environment,
                "exit_code": completed.returncode,
                "stdout_sha256": hashlib.sha256(completed.stdout).hexdigest(),
                "stderr_sha256": hashlib.sha256(completed.stderr).hexdigest(),
            }
        )
    return records


def _preparation_root(records: list[dict[str, object]]) -> str:
    return hashlib.sha256(PREPARATION_DOMAIN + rfc8785.dumps(cast(Any, records))).hexdigest()


def _parent_dirs(paths: list[Path]) -> list[str]:
    result: set[Path] = set()
    for path in paths:
        current = path.parent
        while current != Path("/"):
            result.add(current)
            current = current.parent
    return [str(path) for path in sorted(result, key=lambda item: (len(item.parts), str(item)))]


def _prepared_python_environment(config: dict[str, object]) -> Path:
    environment = config.get("environment")
    scratch = Path(cast(str, config["scratch_root"]))
    path = (
        Path(cast(str, environment["UV_PROJECT_ENVIRONMENT"]))
        if (
            isinstance(environment, dict)
            and isinstance(environment.get("UV_PROJECT_ENVIRONMENT"), str)
        )
        else None
    )
    if path is None or path.parent != scratch:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    _directory(path)
    if not (path / "bin/python").exists():
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    return path


def _registered_leaf_commands(
    config: dict[str, object], authorization: dict[str, object]
) -> list[dict[str, object]]:
    registry_path = Path(cast(str, config["command_registry_path"]))
    raw = registry_path.read_bytes()
    if registry_path.is_symlink() or hashlib.sha256(raw).hexdigest() != authorization.get(
        "command_registry_sha256"
    ):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    registry = json.loads(raw)
    rows = registry.get("commands") if isinstance(registry, dict) else None
    configured = config.get("mechanical_command_ids")
    if not isinstance(rows, list) or not isinstance(configured, list):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    found: dict[str, dict[str, object]] = {}
    for row in rows:
        if not isinstance(row, dict) or not isinstance(row.get("command_id"), str):
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
        command_id = cast(str, row["command_id"])
        if command_id in found:
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
        found[command_id] = row
    if not configured or not all(isinstance(item, str) for item in configured):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    commands = [found.get(cast(str, item)) for item in configured]
    if any(command is None for command in commands):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    result = cast(list[dict[str, object]], commands)
    for command in result:
        argv, cwd = command.get("argv"), command.get("cwd")
        if (
            command.get("kind") != "review-leaf"
            or command.get("network") != "DENY"
            or command.get("authenticated_operator_access") != "DENY"
            or command.get("provider_access") != "DENY"
            or command.get("expected_exit") != 0
            or not isinstance(cwd, str)
            or not isinstance(argv, list)
            or not argv
            or not all(isinstance(token, str) and token for token in argv)
        ):
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    return result


def _node_binary() -> Path:
    mise = shutil.which("mise")
    if mise is None:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    completed = subprocess.run(  # noqa: S603 - fixed locally resolved tool, output is validated below
        [mise, "which", "node"], check=False, capture_output=True, text=True
    )
    source = Path(completed.stdout.strip()) if completed.returncode == 0 else Path()
    if not source.is_file() or source.is_symlink():
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    return source


def _tool_mounts(
    commands: list[dict[str, object]],
) -> tuple[list[tuple[Path, Path]], list[tuple[str, str]]]:
    names = {cast(list[str], command["argv"])[0] for command in commands}
    if any(
        command.get("command_id")
        in {
            "A_CHECK_BASELINE",
            "A_CHECK_DESCENDANT",
            "SEC_CDP_REACHABILITY",
            "SEC_DYNAMIC_DISPATCH",
            "SEC_TARGET_ESCAPE",
            "SEC_MESSAGE_SMUGGLING",
            "SEC_OUTBOUND_NETWORK",
        }
        for command in commands
    ):
        names.update({"node", "pnpm"})
    mounts: list[tuple[Path, Path]] = []
    links: list[tuple[str, str]] = []
    for name in sorted(names):
        if name == "node":
            source = _node_binary()
        else:
            resolved = shutil.which(name)
            source = Path(resolved).resolve() if resolved else Path()
        if not source.is_file() or source.is_symlink():
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
        if name == "pnpm":
            package = source.parents[1]
            _directory(package)
            mounts.append((package, Path("/review-tools/pnpm")))
            links.append(("/review-tools/pnpm/bin/pnpm.cjs", "/review-bin/pnpm"))
        else:
            mounts.append((source, Path(f"/review-bin/{name}")))
    if "pnpm" in names and "node" not in names:
        mounts.append((_node_binary(), Path("/review-bin/node")))
    return mounts, links


def _reject_unvalidated_python_bytecode(environment: Path) -> None:
    """A projected prepared environment must not expose excluded executable caches."""
    _directory(environment)

    def failed_walk(_error: OSError) -> None:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")

    try:
        for directory, names, files in os.walk(
            environment, followlinks=True, onerror=failed_walk
        ):
            parent = Path(directory)
            for name in (*names, *files):
                entry = parent / name
                if name == "__pycache__" or name.lower().endswith((".pyc", ".pyo")):
                    raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
                if entry.is_symlink():
                    resolved = entry.resolve(strict=True)
                    if ("__pycache__" in resolved.parts
                            or resolved.suffix.lower() in {".pyc", ".pyo"}):
                        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
            for name in names:
                resolved = (parent / name).resolve(strict=True)
                if not resolved.is_relative_to(environment) or any(
                    ancestor.resolve() == resolved for ancestor in (parent, *parent.parents)
                ):
                    raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    except (OSError, RuntimeError) as error:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION") from error


def _dependency_projection(root: Path, boundary: Path, *, python: bool) -> dict[str, str]:
    """Compare package source bytes; only a cache-free prepared tree is projectable."""
    _directory(root)
    result: dict[str, str] = {}
    for directory, names, files in os.walk(root, followlinks=True):
        parent = Path(directory)
        names[:] = [name for name in names if name not in {"__pycache__", ".bin"}]
        for name in list(names):
            entry = parent / name
            resolved = entry.resolve(strict=True)
            if not python and entry.is_symlink() and resolved == boundary / "extension":
                # pnpm's declared local workspace resolves to the mounted governed source.
                result[entry.relative_to(root).as_posix()] = "workspace:extension"
                names.remove(name)
                continue
            if not resolved.is_relative_to(boundary) or any(
                ancestor.resolve() == resolved for ancestor in (parent, *parent.parents)
            ):
                raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
        for name in files:
            path = parent / name
            if name.endswith((".pyc", ".pyo")) or name in {
                ".modules.yaml", ".pnpm-workspace-state-v1.json",
            }:
                continue
            if not path.resolve(strict=True).is_relative_to(boundary) or not path.is_file():
                raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
            content = path.read_bytes()
            if python and name == "RECORD" and parent.name.endswith(".dist-info"):
                rows = list(csv.reader(content.decode().splitlines()))
                if any(len(row) != 3 for row in rows):
                    raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
                # Console wrappers are not imported; frozen uv checks them as installed scripts.
                content = json.dumps([row for row in rows if not row[0].startswith(
                    "../../../bin/"
                )], sort_keys=True).encode()
            result[path.relative_to(root).as_posix()] = hashlib.sha256(content).hexdigest()
    if not result:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    return result


def _python_runtime_projection(config: dict[str, object]) -> tuple[Path, str] | None:
    """Verify the finite source-declared standalone Python tree before mounting it."""
    declared = config.get("python_runtime")
    if declared is None:
        return None
    if not isinstance(declared, dict) or set(declared) != {"root", "sha256"}:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    root = Path(str(declared["root"]))
    if not root.is_absolute() or root != root.resolve(strict=True):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    _reject_unvalidated_python_bytecode(root)
    projection = _dependency_projection(root, root, python=True)
    digest = hashlib.sha256(rfc8785.dumps(cast(Any, projection))).hexdigest()
    if digest != declared["sha256"]:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    return root, digest


def _validate_prepared_dependencies(config: dict[str, object]) -> None:
    qualified = RUNTIME_ROOT / ".venv"
    prepared = _prepared_python_environment(config)
    _reject_unvalidated_python_bytecode(prepared)
    for alias in ("python", "python3", "python3.12"):
        path = prepared / "bin" / alias
        if not path.is_symlink() or path.resolve(strict=True) != (
            qualified / "bin" / alias
        ).resolve(strict=True):
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    if (prepared / "pyvenv.cfg").read_bytes() != (qualified / "pyvenv.cfg").read_bytes():
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    if _dependency_projection(qualified / "lib", qualified, python=True) != _dependency_projection(
        prepared / "lib", prepared, python=True
    ):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    node_environment = cast(dict[str, object], config["node_environment"])
    project = Path(cast(str, node_environment["project_root"]))
    for item in cast(list[dict[str, str]], node_environment["project_inputs"]):
        if (project / item["destination"]).read_bytes() != Path(item["source"]).read_bytes():
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    if _dependency_projection(RUNTIME_ROOT / "node_modules", RUNTIME_ROOT, python=False) != (
        _dependency_projection(project / "node_modules", project, python=False)
    ) or _dependency_projection(
        RUNTIME_ROOT / "extension/node_modules", RUNTIME_ROOT, python=False
    ) != _dependency_projection(project / "extension/node_modules", project, python=False):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")


def _producer_projection(
    config: dict[str, object], commands: list[dict[str, object]],
) -> tuple[list[tuple[Path, Path]], list[tuple[str, str]], dict[str, str]]:
    """Validate source-owned exact live identities before creating read-only projections."""
    if config.get("schema_version") in {"review-config/v2", "review-config/v3"}:
        _validate_prepared_dependencies(config)
    if not any(row.get("command_id") == "A_CHECK_DESCENDANT" for row in commands):
        return [], [], {}
    from tools.run_environment_qualification import NATIVE
    from tools.run_indexeddb_crash_matrix import CHROME
    from tools.run_native_ingestor_qualification import DEPENDENCIES, dependency_binding
    from tools.verify_repair_evidence import _resolved_node_executable

    if config.get("schema_version") not in {"review-config/v2", "review-config/v3"}:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    _config_template(config)
    declaration = config.get("producer_environment")
    if not isinstance(declaration, dict) or set(declaration) != {
        "schema_version", "mode", "python_environment", "python_executable",
        "python_executable_sha256", "node_lookup", "node_executable", "node_executable_sha256",
        "native_dependency_root", "live_files",
        "path_translation_executable", "path_translation_sha256",
        "wsl_distro", "runtime_unc",
    } or declaration.get("schema_version") != "review-producer-environment/v1" or declaration.get(
        "mode"
    ) != "VERIFIED_READ_ONLY_PROJECTION":
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    qualified = Path(cast(str, declaration["python_environment"]))
    python = Path(cast(str, declaration["python_executable"]))
    node = Path(cast(str, declaration["node_executable"]))
    lookup = Path(cast(str, declaration["node_lookup"]))
    prepared = _prepared_python_environment(config)
    translation = Path(cast(str, declaration["path_translation_executable"]))
    python_configs = []
    for path in (qualified, prepared):
        _directory(path / "bin")
        _regular(path / "pyvenv.cfg")
        lines = (path / "pyvenv.cfg").read_text().splitlines()
        settings = dict(line.split(" = ", 1) for line in lines)
        if len(settings) != len(lines):
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
        settings["home"] = str(Path(settings["home"]).resolve(strict=True))
        python_configs.append(settings)
    if (
        qualified != RUNTIME_ROOT / ".venv" or python != qualified / "bin/python3"
        or shutil.which("node") != str(lookup) or _resolved_node_executable() != node
        or _sha256(node) != declaration["node_executable_sha256"]
        or _sha256(python.resolve(strict=True)) != declaration["python_executable_sha256"]
        or (prepared / "bin/python3").resolve(strict=True) != python.resolve(strict=True)
        or any(
            not (environment / "bin" / alias).is_symlink()
            or (environment / "bin" / alias).resolve(strict=True) != python.resolve(strict=True)
            for environment in (qualified, prepared)
            for alias in ("python", "python3", "python3.12")
        )
        or python_configs[0] != python_configs[1]
        or translation != Path("/init")
        or Path("/usr/bin/wslpath").resolve(strict=True) != translation
        or _sha256(translation) != declaration["path_translation_sha256"]
    ):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    _reject_unvalidated_python_bytecode(prepared)
    distro = declaration["wsl_distro"]
    runtime_unc = declaration["runtime_unc"]
    if (
        distro != "Ubuntu"
        or runtime_unc != "\\\\wsl.localhost\\Ubuntu" + str(RUNTIME_ROOT).replace("/", "\\")
    ):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    for option, operand, expected in (
        ("-w", str(RUNTIME_ROOT), runtime_unc), ("-u", runtime_unc, str(RUNTIME_ROOT)),
    ):
        translated = subprocess.run(  # noqa: S603 -- fixed source-owned path translation only.
            ["/usr/bin/wslpath", option, operand], env={"PATH": "/usr/bin"},
            capture_output=True, text=True, check=False, timeout=10,
        )
        if translated.returncode or translated.stdout.strip() != expected:
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    uv = shutil.which("uv")
    if uv is None:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    for environment_root in (qualified, prepared):
        checked = subprocess.run(  # noqa: S603 -- pinned offline read-only lock/environment check.
            [uv, "sync", "--check", "--frozen", "--offline"], cwd=RUNTIME_ROOT,
            env={**_environment(config), "UV_PROJECT_ENVIRONMENT": str(environment_root)},
            capture_output=True, check=False, timeout=60,
        )
        if checked.returncode:
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    dependency = dependency_binding()  # Includes independent wheel, lock and rfc8785 provenance.
    preparation = json.loads((DEPENDENCIES / "preparation.json").read_text())
    expected_files = {
        CHROME, Path("/mnt/c/Program Files/Google/Chrome/Application/chrome.exe"), NATIVE,
        NATIVE.parent / "python312.dll", NATIVE.parent / "DLLs/_sqlite3.pyd",
        NATIVE.parent / "DLLs/sqlite3.dll", NATIVE.parent.parent / "node/bin/node.exe",
        *(Path(row["path"]) for row in dependency["wheels"]),
        *(Path(row["independent_source"]) for row in preparation["rfc8785"]["files"]),
    }
    live_files = declaration["live_files"]
    if (
        declaration["native_dependency_root"] != str(DEPENDENCIES)
        or not isinstance(live_files, list)
        or len(live_files) != len(expected_files)
        or set(live_files) != {str(path) for path in expected_files}
    ):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    for path in expected_files:
        _regular(path)
    _directory(DEPENDENCIES)
    mounts = [
        (node, node), (translation, translation), (DEPENDENCIES, DEPENDENCIES),
        (prepared, qualified),
    ]
    mounts.extend((path, path) for path in sorted(expected_files))
    return mounts, [(str(node), str(lookup))], {
        "PATH": f"{lookup.parent}:/review-bin:/usr/bin",
        "UV_PROJECT_ENVIRONMENT": str(qualified),
        "WSL_DISTRO_NAME": distro,
    }


def build_bubblewrap_argv(
    config: dict[str, object],
    command: dict[str, object],
    *,
    leaf_commands: list[dict[str, object]] | None = None,
) -> list[str]:
    if shutil.which("bwrap") != "/usr/bin/bwrap":
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    argv = command.get("argv")
    cwd = command.get("cwd")
    mounts = config.get("input_mounts")
    node = config.get("node_environment")
    if (
        not isinstance(argv, list)
        or not argv
        or not isinstance(cwd, str)
        or not isinstance(mounts, list)
        or not isinstance(node, dict)
    ):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    scratch = Path(cast(str, config["scratch_root"]))
    output = Path(cast(str, config["output_root"]))
    writable = [scratch / "control", scratch / "home", scratch / "tmp", output]
    readonly: list[tuple[Path, Path]] = []
    for mount in mounts:
        if not isinstance(mount, dict) or mount.get("mode") != "READ_ONLY":
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
        source = Path(cast(str, mount.get("source_root")))
        target = Path(cast(str, mount.get("workspace_mount")))
        if source != target or str(source) in cast(list[str], config["excluded_roots"]):
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
        if source.is_dir():
            _directory(source)
        else:
            _regular(source)
        readonly.append((source, target))
    dependencies = node.get("dependency_mounts")
    if not isinstance(dependencies, list) or len(dependencies) != 2:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    for mount in dependencies:
        if not isinstance(mount, dict) or mount.get("mode") != "READ_ONLY":
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
        source = Path(cast(str, mount.get("source_root")))
        target = Path(cast(str, mount.get("workspace_mount")))
        if scratch not in source.parents or source.is_symlink() or not source.is_dir():
            raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
        readonly.append((source, target))
    python_runtime = _python_runtime_projection(config)
    if python_runtime is not None:
        readonly.append((python_runtime[0], python_runtime[0]))
    prepared_python = _prepared_python_environment(config) if leaf_commands is not None else None
    if prepared_python is not None:
        readonly.append((prepared_python, prepared_python))
    executable = shutil.which(cast(str, argv[0]), path=os.environ.get("PATH"))
    if executable is None:
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    executable_path = Path(executable).resolve(strict=True)
    _regular(executable_path)
    tools, links = _tool_mounts(leaf_commands or [command])
    projected, projected_links, projected_environment = _producer_projection(
        config, leaf_commands or [command]
    )
    readonly.extend(projected)
    links.extend(projected_links)
    if leaf_commands is None and not any(target.name == argv[0] for _, target in tools):
        tools.append((executable_path, Path(f"/review-bin/{argv[0]}")))
    temporary_target = Path(os.sep) / "tmp"
    destinations = (
        [target for _, target in readonly]
        + writable
        + [
            temporary_target,
            Path("/review-bin"),
            Path("/review-tools"),
        ]
        + [Path(target) for _source, target in links]
        + [target for _source, target in tools]
    )
    result = [
        "/usr/bin/bwrap",
        "--unshare-user",
        "--unshare-pid",
        "--unshare-net",
        "--unshare-ipc",
        "--unshare-uts",
        "--new-session",
        "--cap-drop",
        "ALL",
        "--clearenv",
        "--ro-bind",
        "/usr",
        "/usr",
    ]
    for system_path in ("/bin", "/lib", "/lib64"):
        path = Path(system_path)
        if projected and path.is_symlink():
            if not path.resolve(strict=True).is_relative_to("/usr"):
                raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
            result.extend(["--symlink", os.readlink(path), system_path])
        else:
            result.extend(["--ro-bind", system_path, system_path])
    for directory in _parent_dirs(destinations):
        result.extend(["--dir", directory])
    result.extend(
        ["--dir", "/review-bin", "--dir", "/review-tools", "--proc", "/proc", "--dev", "/dev"]
    )
    for source, target in readonly:
        result.extend(["--ro-bind", str(source), str(target)])
    for path in writable:
        _directory(path)
        bind_target = temporary_target if path == scratch / "tmp" else path
        result.extend(["--bind", str(path), str(bind_target)])
    for source, target in tools:
        result.extend(["--ro-bind", str(source), str(target)])
    for link_source, link_target in links:
        result.extend(["--symlink", link_source, link_target])
    environment = _environment(config)
    environment["PATH"] = "/review-bin:/usr/bin"
    environment.update(projected_environment)
    for key, value in sorted(environment.items()):
        result.extend(["--setenv", key, value])
    result.extend(["--chdir", cwd, "--", *cast(list[str], argv)])
    return result


def _namespace_state_path(config: dict[str, object]) -> Path:
    return Path(cast(str, config["scratch_root"])) / "control/namespace-state.json"


def _namespace_facts(pid: int) -> dict[str, object]:
    if type(pid) is not int or pid <= 1:
        raise ValueError("E_REVIEW_NAMESPACE_STALE")
    try:
        fields = Path(f"/proc/{pid}/stat").read_text().rsplit(") ", 1)
        if len(fields) != 2 or len(fields[1].split()) < 20 or fields[1].split()[0] == "Z":
            raise ValueError("E_REVIEW_NAMESPACE_STALE")
        namespaces = {
            name: os.stat(f"/proc/{pid}/ns/{name}").st_ino for name in ("user", "pid", "mnt", "net")
        }
    except OSError as error:
        raise ValueError("E_REVIEW_NAMESPACE_STALE") from error
    return {"pid": pid, "start_ticks": fields[1].split()[19], "namespaces": namespaces}


def _remaining(deadline: float) -> float:
    remaining = deadline - time.monotonic()
    if remaining <= 0:
        raise ValueError("E_REVIEW_NAMESPACE_EXPIRED")
    return remaining


def _lease_deadline(expires_at: object) -> float:
    expires = datetime.fromisoformat(str(expires_at))
    if expires.tzinfo is None:
        raise ValueError("E_REVIEW_NAMESPACE_EXPIRED")
    remaining = (expires.astimezone(UTC) - datetime.now(UTC)).total_seconds()
    if remaining <= 0:
        raise ValueError("E_REVIEW_NAMESPACE_EXPIRED")
    return time.monotonic() + min(28800, remaining)


def _read_frame(connection: socket.socket, limit: int, deadline: float) -> dict[str, Any]:
    raw = bytearray()
    while b"\n" not in raw:
        connection.settimeout(_remaining(deadline))
        chunk = connection.recv(min(65536, limit + 1 - len(raw)))
        if not chunk:
            raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
        raw.extend(chunk)
        if len(raw) > limit:
            raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
    if raw.count(b"\n") != 1 or not raw.endswith(b"\n"):
        raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
    value = parse_strict_json(bytes(raw))
    if not isinstance(value, dict):
        raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
    return cast(dict[str, Any], value)


def _namespace_exchange(
    socket_path: Path,
    payload: dict[str, object],
    deadline: float,
    expected_peer: dict[str, object] | None = None,
) -> tuple[dict[str, Any], int]:
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode() + b"\n"
    if len(encoded) > 4096:
        raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
    directory = os.open(socket_path.parent, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as connection:
            connection.settimeout(_remaining(deadline))
            connection.connect(f"/proc/self/fd/{directory}/{socket_path.name}")
            pid, uid, _gid = struct.unpack(
                "3i", connection.getsockopt(socket.SOL_SOCKET, socket.SO_PEERCRED, 12)
            )
            if uid != os.getuid():
                raise ValueError("E_REVIEW_NAMESPACE_STALE")
            if expected_peer is not None:
                facts = _namespace_facts(pid)
                if any(expected_peer.get(name) != value for name, value in facts.items()):
                    raise ValueError("E_REVIEW_NAMESPACE_STALE")
            connection.sendall(encoded)
            response = _read_frame(connection, 1 << 20, deadline)
            _remaining(deadline)
            return response, pid
    finally:
        os.close(directory)


def _namespace_status(
    socket_path: Path,
    authorization: dict[str, object],
    deadline: float,
    expected_peer: dict[str, object] | None = None,
) -> dict[str, object]:
    response, pid = _namespace_exchange(
        socket_path,
        {"authorization_id": authorization["authorization_id"], "kind": "STATUS"},
        deadline,
        expected_peer,
    )
    expected = {
        name: authorization[name]
        for name in ("authorization_id", "command_registry_sha256", "expires_at")
    }
    if (
        set(response) != {*expected, "sequence"}
        or any(response.get(key) != value for key, value in expected.items())
        or type(response["sequence"]) is not int
        or response["sequence"] != 0
    ):
        raise ValueError("E_REVIEW_NAMESPACE_STALE")
    facts = _namespace_facts(pid)
    if any(
        inode == os.stat(f"/proc/self/ns/{name}").st_ino
        for name, inode in cast(dict[str, int], facts["namespaces"]).items()
    ):
        raise ValueError("E_REVIEW_NAMESPACE_STALE")
    return facts


def _write_json(path: Path, value: dict[str, object]) -> None:
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(value, sort_keys=True, separators=(",", ":")) + "\n")
    os.chmod(temporary, 0o600)
    os.replace(temporary, path)


def _start_namespace(
    config: dict[str, object], authorization: dict[str, object]
) -> dict[str, object]:
    version = (
        3
        if config.get("schema_version") == "review-config/v3"
        else (2 if authorization.get("schema_version") == "review-launch-authorization/v2" else 1)
    )
    if version >= 2:
        _config_template(config)
    commands = _registered_leaf_commands(config, authorization)
    scratch = Path(cast(str, config["scratch_root"]))
    control, home, temporary = scratch / "control", scratch / "home", scratch / "tmp"
    _directory(home)
    for path in (control, temporary):
        path.mkdir(parents=True, exist_ok=False)
        _directory(path)
    python = _prepared_python_environment(config) / "bin/python"
    socket_path = temporary / "namespace.sock"
    label = "a" if config["role"] == "IMPLEMENTATION_READINESS_REVIEWER" else "b"
    config_name = f"review-{label}.v{version}.json"
    broker: dict[str, object] = {
        "argv": [
            str(python),
            str(Path(__file__).resolve()),
            "--namespace-broker",
            "--config",
            str(RUNTIME_ROOT / "review-config" / config_name),
            "--authorization-id",
            str(authorization["authorization_id"]),
            "--registry-sha256",
            str(authorization["command_registry_sha256"]),
            "--socket",
            str(NAMESPACE_SOCKET),
            "--expires-at",
            str(authorization["expires_at"]),
            *(["--review-run-id", str(authorization["review_run_id"])] if version == 3 else []),
        ],
        "cwd": str(RUNTIME_ROOT),
    }
    lease_deadline = _lease_deadline(authorization["expires_at"])
    reader, writer = os.pipe()
    process = None
    sandbox: dict[str, object] | None = None
    sandbox_fd = -1
    try:
        argv = build_bubblewrap_argv(config, broker, leaf_commands=commands)
        argv[1:1] = ["--info-fd", str(writer)]
        deadline = min(time.monotonic() + 5, lease_deadline)
        _remaining(deadline)
        with (control / "broker.stderr").open("xb") as error:
            os.fchmod(error.fileno(), 0o600)
            process = subprocess.Popen(  # noqa: S603 - fixed bwrap and signed registry
                argv,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                stderr=error,
                start_new_session=True,
                pass_fds=(writer,),
            )
        os.close(writer)
        writer = -1
        info = bytearray()
        while True:
            ready, _, _ = select.select([reader], [], [], _remaining(deadline))
            if not ready:
                raise ValueError("E_REVIEW_NAMESPACE_START")
            chunk = os.read(reader, 4097 - len(info))
            if not chunk:
                break
            info.extend(chunk)
            if len(info) > 4096:
                raise ValueError("E_REVIEW_NAMESPACE_START")
        decoded = parse_strict_json(bytes(info))
        if not isinstance(decoded, dict) or type(decoded.get("child-pid")) is not int:
            raise ValueError("E_REVIEW_NAMESPACE_START")
        sandbox = _namespace_facts(decoded["child-pid"])
        sandbox_fd = os.pidfd_open(decoded["child-pid"])
        while _remaining(deadline):
            if process.poll() is not None:
                raise ValueError("E_REVIEW_NAMESPACE_START")
            if socket_path.exists():
                peer = _namespace_status(socket_path, authorization, deadline)
                # bwrap can enter its final user namespace after writing --info-fd.
                ready_sandbox = _namespace_facts(cast(int, sandbox["pid"]))
                if (
                    ready_sandbox["start_ticks"] != sandbox["start_ticks"]
                    or peer["namespaces"] != ready_sandbox["namespaces"]
                ):
                    raise ValueError("E_REVIEW_NAMESPACE_START")
                state = {
                    "schema_version": "review-namespace/v2",
                    "authorization_id": authorization["authorization_id"],
                    "command_registry_sha256": authorization["command_registry_sha256"],
                    "expires_at": authorization["expires_at"],
                    "socket_path": str(socket_path),
                    "host_boot_id": Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
                    **peer,
                }
                _write_json(_namespace_state_path(config), state)
                return state
            time.sleep(min(0.02, _remaining(deadline)))
    except (OSError, ValueError) as error:
        if sandbox_fd != -1:
            with suppress(OSError):
                signal.pidfd_send_signal(sandbox_fd, signal.SIGTERM)
        if process is not None and process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait(timeout=1)
        raise ValueError("E_REVIEW_NAMESPACE_START") from error
    finally:
        os.close(reader)
        if writer != -1:
            os.close(writer)
        if sandbox_fd != -1:
            os.close(sandbox_fd)
    raise ValueError("E_REVIEW_NAMESPACE_START")


def _active_namespace(
    config: dict[str, object], authorization: dict[str, object]
) -> dict[str, object]:
    state_path = _namespace_state_path(config)
    _regular(state_path)
    state = json.loads(state_path.read_text())
    if not isinstance(state, dict):
        raise ValueError("E_REVIEW_NAMESPACE_STALE")
    expected = {
        "schema_version": "review-namespace/v2",
        "authorization_id": authorization["authorization_id"],
        "command_registry_sha256": authorization["command_registry_sha256"],
        "expires_at": authorization["expires_at"],
        "socket_path": str(Path(cast(str, config["scratch_root"])) / "tmp/namespace.sock"),
        "host_boot_id": Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
    }
    if any(state.get(key) != value for key, value in expected.items()) or not isinstance(
        state.get("pid"), int
    ):
        raise ValueError("E_REVIEW_NAMESPACE_STALE")
    facts = _namespace_facts(cast(int, state["pid"]))
    if (
        state.get("start_ticks") != facts["start_ticks"]
        or state.get("namespaces") != facts["namespaces"]
    ):
        raise ValueError("E_REVIEW_NAMESPACE_STALE")
    _namespace_status(
        Path(cast(str, state["socket_path"])),
        authorization,
        min(time.monotonic() + 5, _lease_deadline(authorization["expires_at"])),
        state,
    )
    return state


def _namespace_request(
    socket_path: Path,
    payload: dict[str, object],
    *,
    deadline: float | None = None,
    expected_peer: dict[str, object] | None = None,
) -> subprocess.CompletedProcess[bytes]:
    decoded, _pid = _namespace_exchange(
        socket_path,
        payload,
        deadline if deadline is not None else time.monotonic() + 60,
        expected_peer,
    )
    try:
        stdout = base64.b64decode(decoded["stdout"], validate=True)
        stderr = base64.b64decode(decoded["stderr"], validate=True)
    except (KeyError, TypeError, ValueError, json.JSONDecodeError) as error:
        raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL") from error
    if set(decoded) != {"exit_code", "stdout", "stderr"} or type(decoded["exit_code"]) is not int:
        raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
    return subprocess.CompletedProcess([], decoded["exit_code"], stdout, stderr)


def _execute_in_namespace(
    config: dict[str, object],
    authorization: dict[str, object],
    context: dict[str, object] | None = None,
    log_root: Path | None = None,
) -> Run:
    commands = _registered_leaf_commands(config, authorization)
    mapped = {
        (
            tuple(cast(list[str], command["argv"])),
            cast(str, command["cwd"]),
        ): cast(str, command["command_id"])
        for command in commands
    }
    sequence = 0
    state = _active_namespace(config, authorization)
    deadline = _lease_deadline(authorization["expires_at"])

    def execute(argv: list[str], **kwargs: object) -> subprocess.CompletedProcess[bytes]:
        nonlocal sequence
        cwd = kwargs.get("cwd")
        if not isinstance(cwd, str):
            raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
        command_id = mapped.get((tuple(argv), cwd))
        if command_id is None:
            raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
        authority = json.loads(Path(cast(str, config["authority_config"])).read_bytes())
        public, epoch = _public_key(authority)
        verify_review_launch_authorization(
            authorization,
            public,
            cast(str, config["role"]),
            cast(str, config["workspace_root"]),
            cast(str, authorization["pack_zip_sha256"]),
            expected_host_boot_id=Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
            expected_trust_epoch=epoch,
        )
        _authority_state(authorization, authority, consume=False)
        if context is not None:
            recheck_review_context(context)
            _validate_prepared_dependencies(config)
        from tools.run_review_a_checks import review_environment

        if kwargs.get("env") != review_environment(config):
            raise ValueError("E_REVIEW_EXECUTION_ENVIRONMENT")
        result = _namespace_request(
            Path(cast(str, state["socket_path"])),
            {
                "authorization_id": authorization["authorization_id"],
                "sequence": sequence,
                "command_id": command_id,
            },
            deadline=min(deadline, _lease_deadline(authorization["expires_at"])),
            expected_peer=state,
        )
        if log_root is not None:
            for stream, data in (("stdout", result.stdout), ("stderr", result.stderr)):
                with (log_root / f"{sequence:02d}.{stream}").open("xb") as output:
                    output.write(data)
        sequence += 1
        return result

    return execute


def _broker_commands(
    config: dict[str, object], expected_sha256: str
) -> dict[str, dict[str, object]]:
    registry = Path(cast(str, config["command_registry_path"]))
    raw = registry.read_bytes()
    if registry.is_symlink() or hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
    decoded = json.loads(raw)
    rows = decoded.get("commands") if isinstance(decoded, dict) else None
    wanted = config.get("mechanical_command_ids")
    if not isinstance(rows, list) or not isinstance(wanted, list):
        raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
    result: dict[str, dict[str, object]] = {}
    for row in rows:
        if isinstance(row, dict) and isinstance(row.get("command_id"), str):
            result[cast(str, row["command_id"])] = row
    if not all(isinstance(item, str) and item in result for item in wanted):
        raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
    selected = {item: result[item] for item in cast(list[str], wanted)}
    if any(command.get("kind") != "review-leaf" for command in selected.values()):
        raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
    return selected


def _run_broker_command(
    command: dict[str, object],
    environment: dict[str, str],
    deadline: float,
    expires_at: datetime,
) -> dict[str, object]:
    def remaining() -> float:
        if expires_at.tzinfo is None or datetime.now(UTC) >= expires_at:
            raise ValueError("E_REVIEW_NAMESPACE_TIMEOUT")
        return _remaining(deadline)

    remaining()
    child = subprocess.Popen(  # noqa: S603 - exact signed registry argv, never client argv
        cast(list[str], command["argv"]),
        cwd=cast(str, command["cwd"]),
        env=environment,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        start_new_session=True,
    )
    assert child.stdout is not None and child.stderr is not None
    output = {"stdout": bytearray(), "stderr": bytearray()}
    try:
        with child.stdout, child.stderr, selectors.DefaultSelector() as selector:
            for stream, name in ((child.stdout, "stdout"), (child.stderr, "stderr")):
                os.set_blocking(stream.fileno(), False)
                selector.register(stream, selectors.EVENT_READ, name)
            while selector.get_map() or child.returncode is None:
                # Keep the leader unreaped until its group is stopped: no PID reuse.
                if (
                    child.returncode is None
                    and os.waitid(os.P_PID, child.pid, os.WEXITED | os.WNOHANG | os.WNOWAIT)
                    is not None
                ):
                    with suppress(ProcessLookupError):
                        os.killpg(child.pid, signal.SIGKILL)
                    child.wait(timeout=1)
                for ready, _ in selector.select(min(0.05, remaining())):
                    chunk = os.read(ready.fd, 65536)
                    if not chunk:
                        selector.unregister(ready.fileobj)
                    else:
                        output[ready.data].extend(chunk)
                        if sum(map(len, output.values())) > 750000:
                            raise ValueError("E_REVIEW_NAMESPACE_OUTPUT_LIMIT")
            remaining()
            return {
                "exit_code": child.returncode,
                **{name: base64.b64encode(value).decode() for name, value in output.items()},
            }
    finally:
        if child.returncode is None:
            with suppress(ProcessLookupError):
                os.killpg(child.pid, signal.SIGKILL)
            child.wait(timeout=1)


def _broker_environment(
    config: dict[str, object], commands: dict[str, dict[str, object]],
) -> dict[str, str]:
    from tools.run_review_a_checks import review_environment

    environment = review_environment({**config, "mechanical_command_ids": list(commands)})
    if "A_CHECK_DESCENDANT" in commands and any(
        os.environ.get(name) != environment[name]
        for name in ("PATH", "UV_PROJECT_ENVIRONMENT", "WSL_DISTRO_NAME")
    ):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    return environment


def _run_namespace_broker(args: argparse.Namespace) -> None:
    config = json.loads(Path(args.config).read_text())
    if not isinstance(config, dict) or config.get("network") != "DENY":
        raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
    if config.get("schema_version") == "review-config/v3":
        config = resolve_review_run(config, args.review_run_id)
    elif args.review_run_id is not None:
        raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
    commands = _broker_commands(config, args.registry_sha256)
    expected = list(cast(list[str], config["mechanical_command_ids"]))
    environment = _broker_environment(config, commands)
    endpoint = Path(args.socket)
    if endpoint != NAMESPACE_SOCKET or endpoint.exists():
        raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
    deadline = _lease_deadline(args.expires_at)
    with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as server:
        server.bind(str(endpoint))
        os.chmod(endpoint, 0o600)
        server.listen(1)
        sequence = 0
        while sequence < len(expected):
            server.settimeout(_remaining(deadline))
            connection, _ = server.accept()
            with connection:
                request = _read_frame(connection, 4096, min(deadline, time.monotonic() + 5))
                if request == {"authorization_id": args.authorization_id, "kind": "STATUS"}:
                    reply = {
                        "authorization_id": args.authorization_id,
                        "command_registry_sha256": args.registry_sha256,
                        "expires_at": args.expires_at,
                        "sequence": sequence,
                    }
                    connection.settimeout(_remaining(deadline))
                    connection.sendall(json.dumps(reply, sort_keys=True).encode() + b"\n")
                    continue
                command_id = expected[sequence]
                if (
                    not isinstance(request, dict)
                    or set(request) != {"authorization_id", "sequence", "command_id"}
                    or request.get("authorization_id") != args.authorization_id
                    or type(request.get("sequence")) is not int
                    or request.get("sequence") != sequence
                    or request.get("command_id") != command_id
                ):
                    raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
                if datetime.now(UTC) >= datetime.fromisoformat(args.expires_at).astimezone(UTC):
                    raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
                if _broker_commands(config, args.registry_sha256) != commands:
                    raise ValueError("E_REVIEW_NAMESPACE_PROTOCOL")
                reply = _run_broker_command(
                    commands[command_id],
                    environment,
                    min(deadline, _lease_deadline(args.expires_at)),
                    datetime.fromisoformat(args.expires_at),
                )
                connection.settimeout(_remaining(min(deadline, _lease_deadline(args.expires_at))))
                connection.sendall(
                    json.dumps(reply, sort_keys=True, separators=(",", ":")).encode() + b"\n"
                )
                sequence += 1


def _consume(
    config: dict[str, object], authorization: dict[str, object], *, execute: bool
) -> dict[str, object]:
    authority = json.loads(Path(cast(str, config["authority_config"])).read_text())
    if not isinstance(authority, dict):
        raise ValueError("E_REVIEW_WORKSPACE_ISOLATION")
    public_key, trust_epoch = _public_key(cast(dict[str, object], authority))
    verify_review_launch_authorization(
        authorization,
        public_key,
        cast(str, config["role"]),
        cast(str, config["workspace_root"]),
        cast(str, authorization["pack_zip_sha256"]),
        expected_host_boot_id=Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
        expected_trust_epoch=trust_epoch,
    )
    context = None
    if authorization.get("schema_version") == "review-launch-authorization/v2" or config.get(
        "schema_version"
    ) in {"review-config/v2", "review-config/v3"}:
        context = measure_review_context(config, authorization)
        recheck_review_context(context)
    _authority_state(authorization, cast(dict[str, object], authority), consume=not execute)
    output = Path(cast(str, config["output_root"]))
    attestation_path = output / "workspace-attestation.json"
    if execute:
        _regular(attestation_path)
        prior = json.loads(attestation_path.read_text())
        from tools.finalize_review import validate_host_preparation

        validate_host_preparation(authorization, authority, prior)
        registry = json.loads(Path(cast(str, config["command_registry_path"])).read_text())
        runner = (
            run_review_a_checks
            if config["role"] == "IMPLEMENTATION_READINESS_REVIEWER"
            else run_review_b_checks
        )
        host_root = review_execution_root(authorization, authority)
        host_root.mkdir(parents=True, exist_ok=False, mode=0o700)
        execution = runner(
            config,
            registry,
            execute=_execute_in_namespace(
                config,
                authorization,
                context,
                host_root,
            ),
        )
        if context is not None:
            recheck_review_context(context)
        _authority_state(authorization, authority, consume=False)
        with (host_root / "execution.json").open("x") as stream:
            json.dump(
                {"authorization_id": authorization["authorization_id"], **execution},
                stream,
                sort_keys=True,
                separators=(",", ":"),
            )
            stream.write("\n")
        prior.update(
            {
                "commands_executed_root": execution["commands_executed_root"],
                "finished_at": datetime.now(UTC).isoformat(),
            }
        )
        attestation_path.write_text(json.dumps(prior, sort_keys=True, separators=(",", ":")) + "\n")
        return execution
    _authority_state(authorization, cast(dict[str, object], authority), consume=False)
    prepared = (
        _prepare_review_directories(config)
        if context is not None
        else prepare_review_workspace(config)
    )
    commands = _preparation_commands(config)
    preparation_root = review_execution_root(authorization, authority).with_name(
        str(authorization["review_run_id"]) + "-preparation"
    )
    preparation_root.mkdir(parents=True, exist_ok=False, mode=0o700)
    records = _run_preparation(config, commands, log_root=preparation_root)
    with (preparation_root / "preparation.json").open("x") as stream:
        json.dump(
            {
                "authorization_id": authorization["authorization_id"],
                "commands": records,
                "preparation_commands_root": _preparation_root(records),
            },
            stream,
            sort_keys=True,
        )
        stream.write("\n")
    namespace = _start_namespace(config, authorization)
    now = datetime.now(UTC).isoformat()
    attestation = {
        "authorization_consumed_at": now,
        "started_at": now,
        "workspace_root": prepared["workspace_root"],
        "allowed_changed_paths": [
            "result.json",
            "execution-receipt.json",
            "workspace-attestation.json",
        ],
        "unexpected_changed_paths": [],
        "fresh_session_attestation": None,
        "preparation_commands": records,
        "preparation_commands_root": _preparation_root(records),
        "commands_executed_root": "0" * 64,
        "namespace": namespace,
    }
    attestation_path.write_text(
        json.dumps(attestation, sort_keys=True, separators=(",", ":")) + "\n"
    )
    return prepared


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", type=Path)
    parser.add_argument("--authorization", type=Path)
    parser.add_argument("--execute", action="store_true")
    parser.add_argument("--namespace-broker", action="store_true")
    parser.add_argument("--authorization-id")
    parser.add_argument("--registry-sha256")
    parser.add_argument("--socket")
    parser.add_argument("--expires-at")
    parser.add_argument("--review-run-id")
    args = parser.parse_args()
    if args.namespace_broker:
        if not all(
            (args.config, args.authorization_id, args.registry_sha256, args.socket, args.expires_at)
        ):
            parser.error("namespace broker requires complete fixed arguments")
            return
        _run_namespace_broker(args)
        return
    elif args.config is not None and args.authorization is None and not args.execute:
        result = prepare_review_workspace(json.loads(args.config.read_text()))
    elif args.authorization is not None and args.config is None:
        authorization = json.loads(args.authorization.read_text())
        result = _consume(
            review_config_for_authorization(authorization, runtime_root=RUNTIME_ROOT),
            authorization,
            execute=args.execute,
        )
    else:
        parser.error("provide exactly --config or --authorization")
        return
    print(json.dumps(result, sort_keys=True))


if __name__ == "__main__":
    main()"""Bounded direct-provider probe dispatched only by the user-terminal key launcher."""

# ruff: noqa: E402
import json
import os
import re
import sys
import time
from dataclasses import asdict
from datetime import UTC, datetime
from pathlib import Path
from typing import Any
from uuid import uuid4

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT), str(ROOT / "src")]
from moj_discovery.live_config import LiveConfig, private_path
from moj_discovery.live_intent import RunIntentReceipt, claim_receipt
from moj_discovery.live_preflight_batched import provider_config_scope
from moj_discovery.provider_protocol import ProviderScope
from moj_discovery.providers.api_football import ApiFootballClient, ProviderError
from moj_discovery.providers.football_normalizer import ObservationStamp, normalize_bundle
from moj_discovery.providers.poll_budget import PollSegment, estimate_requests
from moj_discovery.providers.quota import QuotaLedger
from moj_discovery.secrets_local import SecretValue

ProbeResult = dict[str, Any]


def inspect_fixture_lookup(client: ApiFootballClient) -> ProbeResult:
    """Two fixed request purposes; output only validated fixture identities."""
    result: ProbeResult = dict(
        KEY_CHECK="NOT_CHECKED",
        SUBSCRIPTION_CHECK="UNKNOWN",
        PROBE_RESULT="PARTIAL",
        REQUEST_ATTEMPTS=0,
        MISSING_CAPABILITIES=["EXACT_FIXTURE_PROBE_REQUIRED"],
        PROVIDER_DIAGNOSTIC="NONE",
        fixture_candidates=[],
    )
    try:
        status = client.get_status()
        result["KEY_CHECK"] = "AUTHENTICATED"
        if not status.active:
            raise ValueError()
        scope = client.scope
        assert scope.lookup_date is not None
        response = client.get_fixtures_for_date(scope.league_id, scope.season, scope.lookup_date)
        rows = []
        for row in response.rows:
            fixture, league, teams = row["fixture"], row["league"], row["teams"]
            stamp = datetime.fromisoformat(fixture["date"])
            if (
                len(response.rows) > 20
                or league != {"id": scope.league_id, "season": scope.season}
                or stamp.tzinfo is None
                or stamp.astimezone(UTC).date().isoformat() != scope.lookup_date
                or any(
                    type(teams[s]["id"]) is not int
                    or teams[s]["id"] <= 0
                    or type(teams[s]["name"]) is not str
                    or not re.fullmatch(r"[^\x00-\x1f\x7f-\x9f]{1,100}", teams[s]["name"])
                    for s in ("home", "away")
                )
            ):
                raise ValueError()
            rows.append(
                {
                    "fixture_id": fixture["id"],
                    "kickoff_utc": stamp.astimezone(UTC).isoformat(),
                    "home": teams["home"],
                    "away": teams["away"],
                }
            )
        result["fixture_candidates"] = rows
    except ProviderError as error:
        result.update(
            PROBE_RESULT="FAIL",
            PROVIDER_DIAGNOSTIC=error.diagnostic,
            MISSING_CAPABILITIES=[
                "AUTH_FAILED" if error.code == "AUTH_FAILED" else "PROVIDER_UNAVAILABLE"
            ],
        )
        if error.code == "AUTH_FAILED":
            result["KEY_CHECK"] = "FAILED"
    except (ValueError, KeyError, TypeError):
        result.update(PROBE_RESULT="FAIL", MISSING_CAPABILITIES=["PROVIDER_UNAVAILABLE"])
    result["REQUEST_ATTEMPTS"] = client.http_attempts
    result["source_kind"] = client.scope.source_kind
    result["requests"] = client.request_log
    return result


def inspect_provider(config: LiveConfig, client: ApiFootballClient) -> ProbeResult:
    """Shared finite sequence for real and injected MOCK transports; no fallback polling."""
    result: ProbeResult = {
        "KEY_CHECK": "NOT_CHECKED",
        "SUBSCRIPTION_CHECK": "UNKNOWN",
        "PROBE_RESULT": "FAIL",
        "REQUEST_ATTEMPTS": 0,
        "MISSING_CAPABILITIES": [],
        "PROVIDER_DIAGNOSTIC": "NONE",
    }
    missing: set[str] = set()
    cfg = config.public
    domain, started = str(uuid4()), client._mono()
    observations: list[dict[str, Any]] = []
    quota: dict[str, Any] | None = None
    coverage: dict[str, Any] | None = None
    try:
        status = client.get_status()
        result["KEY_CHECK"] = "AUTHENTICATED"
        quota = asdict(status)
        cost = estimate_requests([PollSegment(0, cfg["runtime"]["max_run_minutes"] * 60, 15)])
        if status.daily_limit is None or status.daily_remaining is None:
            missing.add("QUOTA_UNKNOWN")
        elif (
            not status.active
            or status.daily_remaining - (status.daily_limit + 4) // 5 < cost.with_reserve
        ):
            result["SUBSCRIPTION_CHECK"] = "INSUFFICIENT"
            missing.add("QUOTA_INSUFFICIENT")
        else:
            result["SUBSCRIPTION_CHECK"] = "CONFIRMED"
        coverage = client.get_coverage(cfg["provider"]["league_id"], cfg["provider"]["season"])
        if coverage["coverage"]["events"] is not True:
            missing.add("COVERAGE_UNKNOWN")
        previous: dict[int, dict[str, Any]] = {}
        for _ in range(2):
            response = client.get_fixture_bundle(config.fixture_ids)
            projected = normalize_bundle(
                response,
                config.fixture_ids,
                ObservationStamp(
                    client._utc(),
                    int(client._mono() * 1000000),
                    domain,
                    str(uuid4()),
                    cfg["provider"]["league_id"],
                    cfg["provider"]["season"],
                    previous,
                ),
            )
            if (
                projected.missing_ids
                or projected.rejected
                or set(projected.states) != set(config.fixture_ids)
            ):
                missing.add("BUNDLE_MISSING")
            for state in projected.states.values():
                if state["events_status"] not in {"OBSERVED", "OBSERVED_EMPTY"}:
                    missing.add("EVENTS_UNKNOWN")
            observations.append(
                {
                    "request_id": response.request_id,
                    "states": projected.states,
                    "missing_ids": list(projected.missing_ids),
                    "rejected": projected.rejected,
                }
            )
            previous = projected.states
    except ProviderError as error:
        result["PROVIDER_DIAGNOSTIC"] = error.diagnostic
        if error.code == "AUTH_FAILED":
            result["KEY_CHECK"] = "FAILED"
        missing.add(
            {
                "AUTH_FAILED": "AUTH_FAILED",
                "SESSION_BUDGET": "BUDGET_LIMIT",
                "DAILY_BUDGET": "BUDGET_LIMIT",
                "MINUTE_BUDGET": "BUDGET_LIMIT",
                "PROVIDER_DAILY_RESERVE": "QUOTA_INSUFFICIENT",
                "RUN_DEADLINE_OR_AUTHORITY": "TIME_LIMIT",
            }.get(error.code, "PROVIDER_UNAVAILABLE")
        )
    except (ValueError, KeyboardInterrupt):
        missing.add("PROVIDER_UNAVAILABLE")
    if client._mono() >= client.scope.deadline_mono:
        missing.add("TIME_LIMIT")
    result.update(
        PROBE_RESULT="PASS"
        if not missing
        else "PARTIAL"
        if result["KEY_CHECK"] == "AUTHENTICATED"
        else "FAIL",
        REQUEST_ATTEMPTS=client.quota.count_attempts(),
        MISSING_CAPABILITIES=sorted(missing),
    )
    result["evidence"] = {
        "source_kind": client.scope.source_kind,
        "fixture_ids": list(config.fixture_ids),
        "quota": quota,
        "coverage": coverage,
        "observations": observations,
        "http_attempts": client.http_attempts,
        "requests": client.request_log,
        "elapsed_us": max(0, int((client._mono() - started) * 1000000)),
        "source_age": "UNKNOWN",
        "source_latency_measured": False,
        "events_fallback_enabled": False,
        "events_comparison_attempts": 0,
        "model_enabled": False,
        "money_ready": False,
    }
    return result


def run_probe(config: LiveConfig, secret: SecretValue, intent: RunIntentReceipt) -> ProbeResult:
    claim_receipt(intent, "PROVIDER_PROBE")
    if config.sha256 != intent.config.sha256:
        raise ValueError("E_PROBE_CONFIG")
    scope = ProviderScope(
        intent.run_id,
        config.fixture_ids,
        config.public["provider"]["league_id"],
        config.public["provider"]["season"],
        intent.deadline_mono,
        source_kind="OBSERVED_REAL",
        stage="PROVIDER_PROBE",
        max_attempts=intent.intent.public["max_http_attempts"],
        config_sha256=config.sha256,
        source_tree_sha256=intent.intent.public["source_tree_sha256"],
        receipt=intent,
        lookup_date=intent.intent.public.get("lookup_date"),
    )
    # Admission is checked before constructing the fixed HTTPS opener, including on every attempt.
    from moj_discovery.live_intent import verify_provider_receipt

    verify_provider_receipt(intent, scope, "STATUS")
    directory = private_path(".local/part-b/provider-probes/" + intent.run_id, root=ROOT)
    directory.mkdir(parents=True, mode=0o700, exist_ok=False)
    ledger = private_path(".local/part-b/quota/api-football-primary.sqlite3", root=ROOT)
    ledger.parent.mkdir(parents=True, mode=0o700, exist_ok=True)
    provider = config.public["provider"]
    with (
        QuotaLedger(
            ledger,
            scope_id=intent.run_id,
            daily_cap=provider["daily_soft_cap"],
            session_cap=scope.max_attempts,
            minute_cap=provider["max_requests_per_minute"],
            allow_status_bootstrap=True,
        ) as quota,
        ApiFootballClient(secret, quota, scope) as client,
    ):
        result = (
            inspect_fixture_lookup(client)
            if scope.lookup_date
            else inspect_provider(config, client)
        )
    report = {
        **result,
        "run_id": intent.run_id,
        "config_sha256": config.sha256,
        "source_tree_sha256": scope.source_tree_sha256,
        "intent_sha256": intent.intent.sha256,
        "confirmation_kind": intent.confirmation_kind,
        "finished_before_deadline": time.monotonic() < intent.deadline_mono,
        "finished_at_utc": datetime.now(UTC).isoformat(),
        "provider_config_scope": provider_config_scope(config),
    }
    data = json.dumps(report, indent=2).encode()
    if len(data) > 16 * 1024 * 1024:
        raise ValueError("E_PROBE_EVIDENCE_CAP")
    fd = os.open(
        directory / "result.json", os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600
    )
    with os.fdopen(fd, "wb") as output:
        output.write(data)
        output.flush()
        os.fsync(output.fileno())
    if scope.lookup_date and result["fixture_candidates"]:
        from moj_discovery.secrets_local import controlling_tty

        with controlling_tty() as terminal:
            terminal.write("Lookup only. Select the exact match ID for a separate fixture probe.\n")
            for row in result["fixture_candidates"]:
                terminal.write(
                    str(row["fixture_id"])
                    + ": "
                    + row["home"]["name"]
                    + " - "
                    + row["away"]["name"]
                    + " ("
                    + row["kickoff_utc"]
                    + ")\n"
                )
            terminal.flush()
    return result


if __name__ == "__main__":
    print("PROBE_NOT_STARTED: USE_USER_TERMINAL_KEY_LAUNCHER")
    raise SystemExit(2)"""Qualify real extension-origin IndexedDB durability in an isolated Chrome."""

from __future__ import annotations

import argparse
import base64
import hashlib
import json
import os
import platform
import shutil
import signal
from pathlib import Path
from secrets import token_hex
from subprocess import DEVNULL, Popen, run
from time import monotonic, sleep
from typing import Any, cast
from urllib.request import urlopen
from uuid import uuid4

# Native Windows imports only the transport helpers; POSIX termination stays opt-in.
SIGKILL = getattr(signal, "SIGKILL", 9)

_CDP = r"""
const socket = new WebSocket(process.argv[1]);
const expression = process.argv[2];
let nextId = 1;
const pending = new Map();
const opened = new Promise((resolve, reject) => {
  socket.onopen = resolve;
  socket.onerror = reject;
});
socket.onmessage = event => {
  const message = JSON.parse(event.data);
  const resolve = pending.get(message.id);
  if (resolve) { pending.delete(message.id); resolve(message); }
};
const call = (method, params) => new Promise(resolve => {
  const id = nextId++;
  pending.set(id, resolve);
  socket.send(JSON.stringify({id, method, params}));
});
(async () => {
  await opened;
  const response = await call("Runtime.evaluate", {
    expression, awaitPromise: true, returnByValue: true
  });
  socket.close();
  if (response.error || response.result.exceptionDetails) {
    throw new Error(JSON.stringify(response));
  }
  process.stdout.write(JSON.stringify(response.result.result.value));
})().catch(error => { console.error(String(error)); process.exit(1); });
"""


class QualificationRejected(RuntimeError):
    """Raised when purported PASS evidence violates the qualification contract."""


class _EnvironmentBlocked(RuntimeError):
    def __init__(self, code: str, detail: str) -> None:
        super().__init__(f"{code}:{detail}")
        self.code = code
        self.detail = detail


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _extension_id(encoded_public_key: str) -> str:
    digest = hashlib.sha256(base64.b64decode(encoded_public_key)).hexdigest()[:32]
    return "".join(chr(ord("a") + int(nibble, 16)) for nibble in digest)


def _dict(value: object, code: str) -> dict[str, object]:
    if not isinstance(value, dict):
        raise QualificationRejected(code)
    return cast(dict[str, object], value)


def _reject_unless(condition: bool, code: str) -> None:
    if not condition:
        raise QualificationRejected(code)


def validate_qualification_evidence(evidence: dict[str, object]) -> None:
    """Reject identity drift, non-extension execution, or graceful-only shutdown."""
    _reject_unless(evidence.get("result") == "PASS", "E_QUALIFICATION_NOT_PASS")
    if evidence.get("transport") == "pipe":
        _verify_hosted_pipe(evidence)
    browser = _dict(evidence.get("browser"), "E_BROWSER_EVIDENCE")
    expected_executable = browser.get("expected_executable")
    _reject_unless(
        isinstance(expected_executable, str)
        and browser.get("first_process_executable") == expected_executable
        and browser.get("second_process_executable") == expected_executable,
        "E_BROWSER_BINARY_MISMATCH",
    )
    expected_browser_hash = browser.get("sha256")
    _reject_unless(
        isinstance(expected_browser_hash, str)
        and len(expected_browser_hash) == 64
        and browser.get("first_process_sha256") == expected_browser_hash
        and browser.get("second_process_sha256") == expected_browser_hash,
        "E_BROWSER_BINARY_MISMATCH",
    )

    profile = _dict(evidence.get("profile"), "E_PROFILE_EVIDENCE")
    expected_profile = profile.get("expected_id")
    _reject_unless(
        profile.get("fresh") is True
        and isinstance(expected_profile, str)
        and profile.get("first_id") == expected_profile
        and profile.get("second_id") == expected_profile,
        "E_PROFILE_MISMATCH",
    )

    extension = _dict(evidence.get("extension"), "E_EXTENSION_EVIDENCE")
    expected_extension = extension.get("expected_id")
    expected_origin = f"chrome-extension://{expected_extension}"
    _reject_unless(
        isinstance(expected_extension, str)
        and len(expected_extension) == 32
        and extension.get("first_id") == expected_extension
        and extension.get("second_id") == expected_extension,
        "E_EXTENSION_IDENTITY_MISMATCH",
    )
    _reject_unless(
        extension.get("first_protocol") == "chrome-extension:"
        and extension.get("second_protocol") == "chrome-extension:"
        and extension.get("first_origin") == expected_origin
        and extension.get("second_origin") == expected_origin,
        "E_EXTENSION_ORIGIN",
    )

    module = _dict(evidence.get("module"), "E_MODULE_EVIDENCE")
    expected_module_hash = module.get("expected_sha256")
    expected_module_url = f"{expected_origin}/src/spool.js"
    _reject_unless(
        isinstance(expected_module_hash, str)
        and len(expected_module_hash) == 64
        and module.get("first_sha256") == expected_module_hash
        and module.get("second_sha256") == expected_module_hash
        and module.get("first_url") == expected_module_url
        and module.get("second_url") == expected_module_url,
        "E_MODULE_IDENTITY_MISMATCH",
    )

    sentinel = _dict(evidence.get("sentinel"), "E_SENTINEL_EVIDENCE")
    expected_sentinel = sentinel.get("expected")
    _reject_unless(
        isinstance(expected_sentinel, str)
        and bool(expected_sentinel)
        and sentinel.get("committed") == expected_sentinel
        and sentinel.get("durable") == expected_sentinel,
        "E_SENTINEL_DURABILITY",
    )
    _reject_unless(sentinel.get("profile_id") == expected_profile, "E_PROFILE_MISMATCH")

    termination = _dict(evidence.get("termination"), "E_TERMINATION_EVIDENCE")
    _reject_unless(
        termination.get("method") == "SIGKILL_PROCESS_GROUP"
        and termination.get("signal") == SIGKILL
        and termination.get("returncode") == -SIGKILL
        and termination.get("graceful") is False
        and termination.get("owned_process_group") is True,
        "E_GRACEFUL_ONLY_SHUTDOWN",
    )


def _free_port() -> int:
    from socket import socket

    with socket() as candidate:
        candidate.bind(("127.0.0.1", 0))
        return int(candidate.getsockname()[1])


def _canonical_browser_executable(command: Path) -> Path:
    resolved = command.resolve(strict=True)
    chrome_binary = resolved.with_name("chrome")
    if resolved.name in {"google-chrome", "google-chrome-stable"} and chrome_binary.is_file():
        return chrome_binary.resolve(strict=True)
    return resolved


def _process_executable(process: Popen[bytes]) -> Path:
    try:
        return Path(f"/proc/{process.pid}/exe").resolve(strict=True)
    except OSError as error:
        raise QualificationRejected(f"E_BROWSER_PROCESS_IDENTITY:{error}") from error


def _browser_process_observation(process: Popen[bytes]) -> dict[str, object]:
    """Observe the owned live process, retaining raw proc data for later parsing."""
    if process.poll() is not None:
        raise QualificationRejected("E_BROWSER_PROCESS_EXITED")
    return _pid_process_observation(process.pid)


def _pid_process_observation(pid: int) -> dict[str, object]:
    executable = Path(f"/proc/{pid}/exe").resolve(strict=True)
    proc = Path(f"/proc/{pid}")
    cmdline = (proc / "cmdline").read_bytes()
    return {
        "pid": pid,
        "pgid": os.getpgid(pid),
        "executable": str(executable),
        "sha256": _sha256(executable),
        "argv": cmdline.rstrip(b"\0").decode().split("\0"),
        "proc_cmdline_hex": cmdline.hex(),
        "proc_stat": (proc / "stat").read_text(),
    }


def _browser_command(
    command: Path,
    profile: Path,
    extension: Path,
    extension_url: str,
    port: int,
) -> list[str]:
    """Pinned isolated-browser launch; external requests cannot bypass a system proxy."""
    return [
        str(command.resolve()),
        "--headless=new",
        "--disable-background-networking",
        "--disable-component-update",
        "--disable-component-extensions-with-background-pages",
        "--disable-default-apps",
        "--disable-gpu",
        "--disable-sync",
        "--metrics-recording-only",
        "--host-resolver-rules=MAP * ~NOTFOUND, EXCLUDE localhost, EXCLUDE 127.0.0.1",
        "--proxy-server=http://127.0.0.1:9",
        "--proxy-bypass-list=127.0.0.1;localhost",
        "--no-first-run",
        "--no-default-browser-check",
        "--remote-debugging-address=127.0.0.1",
        f"--remote-debugging-port={port}",
        f"--user-data-dir={profile.resolve()}",
        f"--disable-extensions-except={extension.resolve()}",
        f"--load-extension={extension.resolve()}",
        extension_url,
    ]


def _pipe_browser_command(command: Path, profile: Path) -> list[str]:
    """Explicit opt-in; established CfT owner launch defaults remain unchanged."""
    legacy = _browser_command(command, profile, profile, "about:blank", 0)
    return [
        arg
        for arg in legacy
        if not arg.startswith(
            (
                "--remote-debugging-address=",
                "--remote-debugging-port=",
                "--disable-extensions-except=",
                "--load-extension=",
            )
        )
    ][:-1] + ["--remote-debugging-pipe", "--enable-unsafe-extension-debugging", "about:blank"]


def _pipe_node_environment() -> dict[str, str]:
    """Do not let inherited Node preloads replace the hash-bound pipe program."""
    return {
        key: value
        for key, value in os.environ.items()
        if key.upper() not in {"NODE_OPTIONS", "NODE_PATH"}
    }


def _pipe_work(profile_id: str, phase: str, worker_id: str, request: object) -> dict[str, object]:
    arguments = (
        f"{json.dumps(profile_id)},{json.dumps(profile_id)}"
        if phase == "before"
        else json.dumps(profile_id)
    )
    method = "writeSentinel" if phase == "before" else "readSentinel"
    return {
        "worker_id": worker_id,
        "request": request,
        "sentinel_expression": f"globalThis.repairProbe.{method}({arguments})",
        "worker_expression": (
            f"globalThis.repairProbe.startWorker({json.dumps(worker_id)},"
            f"{json.dumps(request, sort_keys=True)})"
            if request is not None
            else None
        ),
    }


def _verify_pipe_transcript(
    content: bytes,
    config: dict[str, object],
    work: dict[str, object],
    result: dict[str, object],
) -> None:
    """Require exact critical requests and their real, unique successful replies."""
    requests: list[dict[str, object]] = []
    replies: dict[int, dict[str, object]] = {}
    for line in content.splitlines():
        row = json.loads(line)
        if row["direction"] == "send":
            request = row["request"]
            if request["id"] != len(requests) + 1:
                raise ValueError("E_PIPE_TRANSCRIPT_SEQUENCE")
            requests.append(request)
        elif row["direction"] == "receive":
            response = json.loads(row["raw"])
            if "id" in response:
                identity = response["id"]
                if identity in replies or not 1 <= identity <= len(requests) or "error" in response:
                    raise ValueError("E_PIPE_TRANSCRIPT_RESPONSE")
                replies[identity] = response["result"]
        else:
            raise ValueError("E_PIPE_TRANSCRIPT_DIRECTION")
    if set(replies) != set(range(1, len(requests) + 1)) or len(requests) < 6:
        raise ValueError("E_PIPE_TRANSCRIPT_MISSING")
    prefix = [
        ("Browser.getVersion", {}),
        ("Extensions.loadUnpacked", {"path": config["extension"]}),
        ("Target.createTarget", {"url": str(config["origin"]) + "/repair-probe.html"}),
        ("Target.attachToTarget", {"targetId": replies[3]["targetId"], "flatten": True}),
    ]
    for request, (method, params) in zip(requests[:4], prefix, strict=True):
        if request != {"id": request["id"], "method": method, "params": params}:
            raise ValueError("E_PIPE_TRANSCRIPT_REQUEST")
    if replies[1] != result["version"] or replies[2] != result["loaded"]:
        raise ValueError("E_PIPE_TRANSCRIPT_IDENTITY")
    loaded = _dict(result["loaded"], "E_PIPE_LOAD")
    if loaded != {"id": str(config["origin"]).split("://")[1]}:
        raise ValueError("E_PIPE_EXTENSION_ID")
    document_expression = (
        "({origin:location.origin,protocol:location.protocol,"
        "probe:Boolean(globalThis.repairProbe),extensionId:globalThis.chrome?.runtime?.id??null})"
    )
    tail = [(work["sentinel_expression"], result["sentinel"])]
    if work["worker_expression"] is not None:
        tail.append((work["worker_expression"], result["worker"]))
    document_count = len(requests) - 4 - len(tail)
    if document_count < 1 or document_count > 100:
        raise ValueError("E_PIPE_DOCUMENT_WAIT")
    for index, request in enumerate(requests[4:], 4):
        expression = (
            document_expression
            if index < 4 + document_count
            else tail[index - 4 - document_count][0]
        )
        if request != {
            "id": index + 1,
            "method": "Runtime.evaluate",
            "sessionId": replies[4]["sessionId"],
            "params": {"expression": expression, "awaitPromise": True, "returnByValue": True},
        }:
            raise ValueError("E_PIPE_EXPRESSION")
        response = replies[index + 1]
        if "exceptionDetails" in response:
            raise ValueError("E_PIPE_EVALUATE")
        value = _dict(response["result"], "E_PIPE_VALUE")["value"]
        if index >= 4 + document_count and value != tail[index - 4 - document_count][1]:
            raise ValueError("E_PIPE_VALUE")
        if index == 3 + document_count and value != result["document"]:
            raise ValueError("E_PIPE_DOCUMENT")
    if result["document"] != {
        "origin": config["origin"],
        "protocol": "chrome-extension:",
        "extensionId": loaded["id"],
        "probe": True,
    }:
        raise ValueError("E_PIPE_ORIGIN")


def _wait_for_target(process: Popen[bytes], port: int, url: str) -> str:
    endpoint = f"http://127.0.0.1:{port}/json/list"
    deadline = monotonic() + 15
    observed: set[str] = set()
    while monotonic() < deadline:
        if process.poll() is not None:
            raise _EnvironmentBlocked("E_CHROME_START_FAILED", f"exit={process.returncode}")
        try:
            pages = json.loads(urlopen(endpoint, timeout=1).read())
            for page in pages:
                page_url = str(page.get("url", ""))
                if page_url:
                    observed.add(page_url)
                if page.get("type") == "page" and page_url == url:
                    return str(page["webSocketDebuggerUrl"])
        except (OSError, json.JSONDecodeError):
            pass
        sleep(0.1)
    raise _EnvironmentBlocked(
        "E_EXTENSION_TARGET_UNAVAILABLE", "observed=" + ",".join(sorted(observed))
    )


def _start_chrome(
    command: Path,
    profile: Path,
    extension: Path,
    extension_url: str,
    log_path: Path,
) -> tuple[Popen[bytes], str]:
    port = _free_port()
    with log_path.open("ab") as log:
        process = Popen(  # noqa: S603 - caller supplies the recorded local browser.
            _browser_command(command, profile, extension, extension_url, port),
            stdin=DEVNULL,
            stdout=log,
            stderr=log,
            start_new_session=True,
        )
    try:
        return process, _wait_for_target(process, port, extension_url)
    except Exception:
        if process.poll() is None:
            os.killpg(process.pid, SIGKILL)
            process.wait(timeout=10)
        raise


def _kill_owned_process_group(process: Popen[bytes]) -> dict[str, object]:
    if process.poll() is not None or os.getpgid(process.pid) != process.pid:
        raise QualificationRejected("E_UNOWNED_OR_EXITED_BROWSER_PROCESS")
    os.killpg(process.pid, SIGKILL)
    returncode = process.wait(timeout=10)
    evidence: dict[str, object] = {
        "method": "SIGKILL_PROCESS_GROUP",
        "signal": SIGKILL,
        "returncode": returncode,
        "graceful": False,
        "owned_process_group": True,
    }
    _reject_unless(returncode == -SIGKILL, "E_GRACEFUL_ONLY_SHUTDOWN")
    return evidence


def _evaluate(websocket_url: str, expression: str) -> object:
    node = shutil.which("node")
    if node is None:
        raise _EnvironmentBlocked("E_NODE_UNAVAILABLE", "node")
    completed = run(  # noqa: S603 - resolved installed Node runs a fixed controller.
        [node, "-e", _CDP, websocket_url, expression],
        capture_output=True,
        text=True,
        check=False,
        timeout=20,
    )
    if completed.returncode:
        raise QualificationRejected(f"E_CHROME_INDEXEDDB_EVALUATE:{completed.stderr.strip()}")
    return json.loads(completed.stdout)


def _wait_for_probe(websocket_url: str) -> None:
    deadline = monotonic() + 10
    while monotonic() < deadline:
        protocol = _evaluate(websocket_url, "location.protocol")
        if protocol != "chrome-extension:":
            raise _EnvironmentBlocked(
                "E_EXTENSION_TARGET_UNAVAILABLE", f"document_protocol={protocol}"
            )
        if _evaluate(websocket_url, "Boolean(globalThis.repairProbe)") is True:
            return
        sleep(0.1)
    raise QualificationRejected("E_REPAIR_PROBE_UNAVAILABLE")


def _prepare_test_extension(repository_root: Path, workspace: Path) -> tuple[Path, str, str]:
    source_root = repository_root / "extension"
    harness_root = source_root / "test-harness"
    build_root = source_root / ".test-build"
    required = {
        "manifest": harness_root / "repair-manifest.json",
        "html": harness_root / "repair-probe.html",
        "probe": build_root / "test-harness/repair-probe.js",
        "spool": build_root / "src/spool.js",
        "durable_idb": build_root / "src/storage/durable_idb.js",
        "errors": build_root / "src/errors.js",
    }
    missing = [str(path) for path in required.values() if not path.is_file()]
    if missing:
        raise _EnvironmentBlocked("E_TEST_EXTENSION_BUILD_MISSING", ",".join(missing))

    extension = workspace / "test-extension"
    (extension / "src").mkdir(parents=True)
    shutil.copy2(required["manifest"], extension / "manifest.json")
    shutil.copy2(required["html"], extension / "repair-probe.html")
    shutil.copy2(required["probe"], extension / "repair-probe.js")
    shutil.copy2(required["spool"], extension / "src/spool.js")
    (extension / "src/storage").mkdir()
    shutil.copy2(required["durable_idb"], extension / "src/storage/durable_idb.js")
    (extension / "src/offline").mkdir()
    run(  # noqa: S603 -- pinned local generator and owned output path
        ["node", str(repository_root / "tools/build_offline_validators.cjs"),  # noqa: S607

         str(extension / "src/offline/validators.js")], check=True, timeout=30)
    shutil.copy2(required["errors"], extension / "src/errors.js")
    # Resolve the installed ESM dependency inside this isolated test extension.
    canonical = (build_root / "src/canonical.js").read_text()
    (extension / "src/canonical.js").write_text(
        canonical.replace('from "canonicalize"', 'from "./canonicalize.js"')
    )
    shutil.copy2(
        source_root / "node_modules/canonicalize/lib/canonicalize.js",
        extension / "src/canonicalize.js",
    )
    shutil.copy2(
        build_root / "test-harness/indexeddb-crash-child.js", extension / "indexeddb-crash-child.js"
    )
    manifest = cast(dict[str, object], json.loads((extension / "manifest.json").read_text()))
    key = manifest.get("key")
    if not isinstance(key, str):
        raise QualificationRejected("E_TEST_EXTENSION_KEY")
    return extension, _extension_id(key), _sha256(extension / "src/spool.js")


def _probe_evidence(value: object) -> dict[str, object]:
    return _dict(value, "E_REPAIR_PROBE_EVIDENCE")


def qualify_chrome_indexeddb_environment(
    workspace: Path,
    *,
    browser_binary: Path | None = None,
    repository_root: Path | None = None,
    transport: str = "legacy",
) -> dict[str, object]:
    """Commit a random sentinel, SIGKILL owned Chrome, and read it after restart."""
    if transport == "pipe":
        return _qualify_hosted_pipe(workspace, browser_binary, repository_root)
    if transport != "legacy":
        raise QualificationRejected("E_BROWSER_TRANSPORT")
    workspace.mkdir(parents=True, exist_ok=True)
    repository_root = repository_root or Path(__file__).parents[1]
    if browser_binary is None:
        installed_browser = shutil.which("google-chrome")
        browser_binary = Path(installed_browser) if installed_browser else None
    profile = workspace / "chrome-profile"
    fresh_profile = not profile.exists()
    if not fresh_profile:
        raise QualificationRejected("E_PROFILE_NOT_FRESH")
    profile.mkdir()
    profile_id = f"bh-r04-{uuid4()}"
    (profile / "BH_R04_PROFILE_ID").write_text(profile_id)
    extension: Path | None = None
    extension_id = ""
    module_hash = ""
    browser: dict[str, object] = {}
    first: Popen[bytes] | None = None
    second: Popen[bytes] | None = None
    attempted = False
    try:
        extension, extension_id, module_hash = _prepare_test_extension(repository_root, workspace)
        if browser_binary is None or not browser_binary.is_file():
            raise _EnvironmentBlocked("E_BROWSER_UNAVAILABLE", str(browser_binary))
        expected_executable = _canonical_browser_executable(browser_binary)
        version = run(  # noqa: S603 - selected browser is identity-checked after launch.
            [str(browser_binary), "--version"],
            capture_output=True,
            text=True,
            check=True,
            timeout=10,
        ).stdout.strip()
        browser_hash = _sha256(expected_executable)
        browser = {
            "command": str(browser_binary),
            "expected_executable": str(expected_executable),
            "version": version,
            "sha256": browser_hash,
        }
        extension_url = f"chrome-extension://{extension_id}/repair-probe.html"
        attempted = True
        first, websocket_url = _start_chrome(
            browser_binary, profile, extension, extension_url, workspace / "chrome-first.log"
        )
        first_executable = _process_executable(first)
        first_profile_id = (profile / "BH_R04_PROFILE_ID").read_text()
        _wait_for_probe(websocket_url)
        sentinel = f"bh-r04-{token_hex(32)}"
        committed = _probe_evidence(
            _evaluate(
                websocket_url,
                "globalThis.repairProbe.writeSentinel("
                f"{json.dumps(sentinel)},{json.dumps(profile_id)})",
            )
        )
        termination = _kill_owned_process_group(first)
        first = None

        second, websocket_url = _start_chrome(
            browser_binary, profile, extension, extension_url, workspace / "chrome-second.log"
        )
        second_executable = _process_executable(second)
        second_profile_id = (profile / "BH_R04_PROFILE_ID").read_text()
        _wait_for_probe(websocket_url)
        durable = _probe_evidence(
            _evaluate(
                websocket_url,
                f"globalThis.repairProbe.readSentinel({json.dumps(profile_id)})",
            )
        )
        browser.update(
            {
                "first_process_executable": str(first_executable),
                "second_process_executable": str(second_executable),
                "first_process_sha256": _sha256(first_executable),
                "second_process_sha256": _sha256(second_executable),
            }
        )
        result: dict[str, object] = {
            "result": "PASS",
            "attempted_real_browser": attempted,
            "browser": browser,
            "host": {
                "system": platform.system(),
                "release": platform.release(),
                "machine": platform.machine(),
                "wsl": "microsoft" in platform.release().lower(),
            },
            "profile": {
                "path": str(profile),
                "expected_id": profile_id,
                "first_id": first_profile_id,
                "second_id": second_profile_id,
                "fresh": fresh_profile,
            },
            "extension": {
                "expected_id": extension_id,
                "first_id": committed.get("extensionId"),
                "second_id": durable.get("extensionId"),
                "first_origin": committed.get("origin"),
                "second_origin": durable.get("origin"),
                "first_protocol": committed.get("protocol"),
                "second_protocol": durable.get("protocol"),
                "load_requested": True,
            },
            "module": {
                "source_sha256": _sha256(repository_root / "extension/src/spool.ts"),
                "expected_sha256": module_hash,
                "first_sha256": committed.get("moduleSha256"),
                "second_sha256": durable.get("moduleSha256"),
                "first_url": committed.get("moduleUrl"),
                "second_url": durable.get("moduleUrl"),
            },
            "sentinel": {
                "expected": sentinel,
                "committed": committed.get("sentinel"),
                "durable": durable.get("sentinel"),
                "profile_id": durable.get("profileId"),
            },
            "termination": termination,
        }
        validate_qualification_evidence(result)
        return result
    except _EnvironmentBlocked as blocked:
        return {
            "result": "BLOCKED_ENVIRONMENT",
            "blocker_code": blocked.code,
            "blocker_detail": blocked.detail,
            "attempted_real_browser": attempted,
            "browser": browser,
            "host": {
                "system": platform.system(),
                "release": platform.release(),
                "machine": platform.machine(),
                "wsl": "microsoft" in platform.release().lower(),
            },
            "profile": {
                "path": str(profile),
                "expected_id": profile_id,
                "fresh": fresh_profile,
            },
            "extension": {
                "expected_id": extension_id,
                "path": str(extension) if extension is not None else None,
                "load_requested": True,
                "module_sha256": module_hash,
            },
        }
    finally:
        for process in (first, second):
            if process is not None and process.poll() is None:
                os.killpg(process.pid, SIGKILL)
                process.wait(timeout=10)


def _qualify_hosted_pipe(
    workspace: Path,
    browser_binary: Path | None,
    repository_root: Path | None,
) -> dict[str, object]:
    from tools.verify_repair_evidence import capture_binding

    if browser_binary is None or not browser_binary.is_file():
        return {
            "result": "BLOCKED_ENVIRONMENT",
            "blocker_code": "E_BROWSER_UNAVAILABLE",
            "blocker_detail": str(browser_binary),
            "attempted_real_browser": False,
        }
    root = repository_root or Path(__file__).resolve().parents[1]
    workspace.mkdir(parents=True, exist_ok=True)
    profile = workspace / "chrome-profile"
    if profile.exists():
        raise QualificationRejected("E_PROFILE_NOT_FRESH")
    profile.mkdir()
    profile_id = "bh-pipe-" + str(uuid4())
    (profile / "BH_R04_PROFILE_ID").write_text(profile_id)
    extension, extension_id, module_hash = _prepare_test_extension(root, workspace)
    script = workspace / "chrome_pipe.cjs"
    shutil.copy2(root / "tools/chrome_pipe.cjs", script)
    node = shutil.which("node")
    if node is None:
        raise _EnvironmentBlocked("E_NODE_UNAVAILABLE", "node")
    node = run(  # noqa: S603 -- resolved installed Node, preload environment removed.
        [node, "-p", "process.execPath"],
        env=_pipe_node_environment(),
        capture_output=True,
        text=True,
        check=True,
        timeout=10,
    ).stdout.strip()
    command = _pipe_browser_command(browser_binary, profile)
    origin = "chrome-extension://" + extension_id
    phases = []
    for phase in ("before", "after"):
        case = workspace / phase
        case.mkdir()
        config = {
            "command": command,
            "workspace": str(case.resolve()),
            "extension": str(extension.resolve()),
            "origin": origin,
        }
        input_path = case / "input.json"
        input_path.write_text(json.dumps(config))
        invocation = [node, str(script.resolve()), str(input_path.resolve())]
        with (case / "node.stdout").open("wb") as out, (case / "node.stderr").open("wb") as err:
            owner = Popen(  # noqa: S603 -- fixed retained pipe owner, closed preload environment.
                invocation,
                stdout=out,
                stderr=err,
                start_new_session=True,
                env=_pipe_node_environment(),
            )
        try:
            deadline = monotonic() + 20
            while not (case / "pipe-ready.json").is_file():
                if owner.poll() is not None or monotonic() > deadline:
                    raise QualificationRejected("E_PIPE_OWNER_READY")
                sleep(0.02)
            ready = json.loads((case / "pipe-ready.json").read_text())
            owner_record = _browser_process_observation(owner)
            browser_record = _pid_process_observation(ready["pid"])
            if ready["node_pid"] != owner.pid or browser_record["pgid"] != owner.pid:
                raise QualificationRejected("E_PIPE_OWNER_IDENTITY")
            work = _pipe_work(profile_id, phase, "", None)
            (case / "start.json").write_text(json.dumps(work))
            deadline = monotonic() + 30
            while not (case / "pipe-result.json").is_file():
                if (case / "pipe-error.json").is_file():
                    raise QualificationRejected((case / "pipe-error.json").read_text())
                if owner.poll() is not None or monotonic() > deadline:
                    raise QualificationRejected("E_PIPE_OWNER_RESULT")
                sleep(0.02)
            result = json.loads((case / "pipe-result.json").read_text())
        finally:
            termination = _kill_owned_process_group(owner)
        phases.append(
            {
                "phase": phase,
                "config": config,
                "work": work,
                "result": result,
                "owner": owner_record,
                "browser": browser_record,
                "invocation": invocation,
                "termination": termination,
                "artifacts": {
                    name: {"path": str((case / name).resolve()), "sha256": _sha256(case / name)}
                    for name in (
                        "input.json",
                        "start.json",
                        "pipe-result.json",
                        "pipe.ndjson",
                        "node.stdout",
                        "node.stderr",
                        "chrome.stdout",
                        "chrome.stderr",
                    )
                },
            }
        )
    first, second = [row["result"]["sentinel"] for row in phases]
    executable = str(_canonical_browser_executable(browser_binary))
    evidence: dict[str, Any] = {
        "result": "PASS",
        "transport": "pipe",
        "attempted_real_browser": True,
        "binding": capture_binding(),
        "workspace": str(workspace.resolve()),
        "pipe_phases": phases,
        "script_sha256": _sha256(script),
        "browser": {
            "expected_executable": executable,
            "sha256": _sha256(Path(executable)),
            "version": phases[0]["result"]["version"]["product"],
            "first_process_executable": phases[0]["browser"]["executable"],
            "second_process_executable": phases[1]["browser"]["executable"],
            "first_process_sha256": phases[0]["browser"]["sha256"],
            "second_process_sha256": phases[1]["browser"]["sha256"],
        },
        "profile": {
            "path": str(profile),
            "expected_id": profile_id,
            "first_id": profile_id,
            "second_id": (profile / "BH_R04_PROFILE_ID").read_text(),
            "fresh": True,
        },
        "extension": {
            "expected_id": extension_id,
            "first_id": first["extensionId"],
            "second_id": second["extensionId"],
            "first_protocol": first["protocol"],
            "second_protocol": second["protocol"],
            "first_origin": first["origin"],
            "second_origin": second["origin"],
            "load_requested": True,
        },
        "module": {
            "expected_sha256": module_hash,
            "first_sha256": first["moduleSha256"],
            "second_sha256": second["moduleSha256"],
            "first_url": first["moduleUrl"],
            "second_url": second["moduleUrl"],
        },
        "sentinel": {
            "expected": profile_id,
            "committed": first["sentinel"],
            "durable": second["sentinel"],
            "profile_id": second["profileId"],
        },
        "termination": phases[0]["termination"],
    }
    validate_qualification_evidence(evidence)
    return evidence


def _verify_hosted_pipe(evidence: dict[str, Any]) -> None:
    from tools.verify_repair_evidence import (
        _compiled_browser_module_hashes,
        _typescript_compile_binding,
        capture_binding,
    )

    try:
        current = capture_binding()
        workspace = Path(evidence["workspace"])
        profile = workspace / "chrome-profile"
        extension = workspace / "test-extension"
        root = Path(__file__).resolve().parents[1]
        if (
            evidence["binding"] != current
            or _sha256(workspace / "chrome_pipe.cjs") != evidence["script_sha256"]
            or (workspace / "chrome_pipe.cjs").read_bytes()
            != (root / "tools/chrome_pipe.cjs").read_bytes()
        ):
            raise ValueError("binding")
        for name, source in (
            ("manifest.json", "repair-manifest.json"),
            ("repair-probe.html", "repair-probe.html"),
        ):
            if (extension / name).read_bytes() != (
                root / "extension/test-harness" / source
            ).read_bytes():
                raise ValueError("asset")
        modules = {
            str(path.relative_to(extension)): _sha256(path) for path in extension.rglob("*.js")
        }
        if modules != _compiled_browser_module_hashes(_typescript_compile_binding(current)):
            raise ValueError("modules")
        profile_id = evidence["profile"]["expected_id"]
        if (profile / "BH_R04_PROFILE_ID").read_text() != profile_id:
            raise ValueError("profile")
        origin = "chrome-extension://" + _extension_id(
            json.loads((extension / "manifest.json").read_text())["key"]
        )
        pids = []
        for phase, row in zip(("before", "after"), evidence["pipe_phases"], strict=True):
            case = workspace / phase
            config: dict[str, Any] = {
                "command": _pipe_browser_command(
                    Path(evidence["browser"]["expected_executable"]), profile
                ),
                "workspace": str(case.resolve()),
                "extension": str(extension.resolve()),
                "origin": origin,
            }
            work = _pipe_work(profile_id, phase, "", None)
            if row["phase"] != phase or row["config"] != config or row["work"] != work:
                raise ValueError("input")
            contents = {}
            for name, descriptor in row["artifacts"].items():
                path = case / name
                if descriptor["path"] != str(path.resolve()) or descriptor["sha256"] != _sha256(
                    path
                ):
                    raise ValueError("artifact")
                contents[name] = path.read_bytes()
            if set(contents) != {
                "input.json",
                "start.json",
                "pipe-result.json",
                "pipe.ndjson",
                "node.stdout",
                "node.stderr",
                "chrome.stdout",
                "chrome.stderr",
            }:
                raise ValueError("artifact set")
            if (
                json.loads(contents["input.json"]) != config
                or json.loads(contents["start.json"]) != work
                or json.loads(contents["pipe-result.json"]) != row["result"]
                or any(contents[name] for name in ("node.stdout", "node.stderr", "chrome.stdout"))
            ):
                raise ValueError("output")
            owner, browser = row["owner"], row["browser"]
            if (
                owner["pid"] == browser["pid"]
                or owner["pid"] != owner["pgid"]
                or browser["pgid"] != owner["pid"]
            ):
                raise ValueError("group")
            for process, command in ((owner, row["invocation"]), (browser, config["command"])):
                raw = bytes.fromhex(process["proc_cmdline_hex"]).rstrip(b"\0").decode().split("\0")
                fields = process["proc_stat"][process["proc_stat"].rindex(")") + 2 :].split()
                headless = [
                    " ".join(
                        [
                            *command[:-1],
                            "--noerrdialogs",
                            "--ozone-platform=headless",
                            "--ozone-override-screen-size=800,600",
                            "--use-angle=swiftshader-webgl",
                            command[-1],
                        ]
                    )
                ]
                allowed = (command, headless) if process is browser else (command,)
                if (
                    process["pid"] in pids
                    or not process["proc_stat"].startswith(str(process["pid"]) + " ")
                    or int(fields[2]) != owner["pid"]
                    or raw != process["argv"]
                    or raw not in allowed
                    or process["sha256"] != _sha256(Path(process["executable"]))
                    or Path(process["executable"]) != Path(command[0]).resolve()
                ):
                    raise ValueError("process")
                pids.append(process["pid"])
            if (
                int(browser["proc_stat"][browser["proc_stat"].rindex(")") + 2 :].split()[1])
                != owner["pid"]
            ):
                raise ValueError("parent")
            if row["invocation"][1:] != [
                str((workspace / "chrome_pipe.cjs").resolve()),
                str((case / "input.json").resolve()),
            ]:
                raise ValueError("owner command")
            result = row["result"]
            if result["pid"] != browser["pid"] or result["node_pid"] != owner["pid"]:
                raise ValueError("result identity")
            _verify_pipe_transcript(contents["pipe.ndjson"], config, work, result)
            if (
                result["sentinel"]["sentinel"] != profile_id
                or result["sentinel"]["profileId"] != profile_id
                or result["sentinel"]["origin"] != origin
                or result["sentinel"]["moduleSha256"] != modules["src/spool.js"]
                or row["termination"]
                != {
                    "method": "SIGKILL_PROCESS_GROUP",
                    "signal": 9,
                    "returncode": -9,
                    "graceful": False,
                    "owned_process_group": True,
                }
            ):
                raise ValueError("restart")
        first, second = [row["result"]["sentinel"] for row in evidence["pipe_phases"]]
        if (
            evidence["sentinel"]
            != {
                "expected": profile_id,
                "committed": first["sentinel"],
                "durable": second["sentinel"],
                "profile_id": second["profileId"],
            }
            or evidence["termination"] != evidence["pipe_phases"][0]["termination"]
        ):
            raise ValueError("summary")
        if evidence["module"] != {
            "expected_sha256": modules["src/spool.js"],
            "first_sha256": first["moduleSha256"],
            "second_sha256": second["moduleSha256"],
            "first_url": first["moduleUrl"],
            "second_url": second["moduleUrl"],
        }:
            raise ValueError("module summary")
        expected_extension = origin.split("://")[1]
        if evidence["extension"] != {
            "expected_id": expected_extension,
            "first_id": first["extensionId"],
            "second_id": second["extensionId"],
            "first_protocol": first["protocol"],
            "second_protocol": second["protocol"],
            "first_origin": first["origin"],
            "second_origin": second["origin"],
            "load_requested": True,
        }:
            raise ValueError("extension summary")
        for name, row in zip(("first", "second"), evidence["pipe_phases"], strict=True):
            if (
                evidence["browser"][name + "_process_executable"] != row["browser"]["executable"]
                or evidence["browser"][name + "_process_sha256"] != row["browser"]["sha256"]
            ):
                raise ValueError("browser summary")
        if (
            evidence["browser"]["version"]
            != evidence["pipe_phases"][0]["result"]["version"]["product"]
        ):
            raise ValueError("version summary")
    except (KeyError, ValueError, TypeError, OSError) as error:
        raise QualificationRejected("E_PIPE_QUALIFICATION_EVIDENCE") from error


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--workspace", required=True, type=Path)
    parser.add_argument("--browser-binary", type=Path)
    parser.add_argument("--repository-root", type=Path)
    parser.add_argument("--transport", choices=("legacy", "pipe"), default="legacy")
    args = parser.parse_args()
    print(
        json.dumps(
            qualify_chrome_indexeddb_environment(
                args.workspace,
                browser_binary=args.browser_binary,
                repository_root=args.repository_root,
                transport=args.transport,
            ),
            sort_keys=True,
        )
    )


if __name__ == "__main__":
    main()"""Issue or verify the clean descendant repository qualification receipt."""

# ruff: noqa: E402

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import stat
import subprocess
import sys
from pathlib import Path
from typing import NoReturn, cast

RUNTIME_ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(RUNTIME_ROOT), str(RUNTIME_ROOT / "src")]

from moj_discovery.pack_verifier import compute_vendor_tree_root
from tools.build_candidate_qualification_receipt import (
    _inventory,
    _read_bytes,
    _read_evidence,
    validate_candidate_qualification_receipt,
)
from tools.full_verifier_config import FullVerifierConfig, load_controller_config
from tools.qualify_zero_parent_baseline import _normative_source_set
from tools.retained_artifact_io import RetainedArtifactIO
from tools.verify_toolchains import EXPECTED, dependency_lock_hashes, verify_toolchains


def _fail() -> NoReturn:
    raise ValueError("E_DESCENDANT_REPOSITORY")


def _canonical(value: object) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":")).encode()


def _git(root: Path, *args: str) -> str:
    git = shutil.which("git")
    if git is None:
        _fail()
    completed = subprocess.run(  # noqa: S603 - resolved Git, fixed read-only operations.
        [git, "-C", str(root), *args], capture_output=True, check=False, timeout=30
    )
    if completed.returncode != 0:
        _fail()
    return completed.stdout.decode().strip()


def descendant_repository_identity(root: Path, audited_ancestor: str) -> dict[str, str]:
    if (
        not root.is_absolute()
        or root != root.resolve()
        or root.is_symlink()
        or not root.is_dir()
        or re.fullmatch(r"[0-9a-f]{40}", audited_ancestor) is None
        or _git(root, "rev-parse", "--show-toplevel") != str(root.resolve())
        or _git(root, "rev-parse", "--show-object-format") != "sha1"
    ):
        _fail()
    head = _git(root, "rev-parse", "HEAD")
    tree = _git(root, "rev-parse", "HEAD^{tree}")
    if head == audited_ancestor:
        _fail()
    git = shutil.which("git")
    assert git is not None
    ancestor = subprocess.run(  # noqa: S603 - resolved Git, fixed read-only operation.
        [git, "-C", str(root), "merge-base", "--is-ancestor", audited_ancestor, head],
        capture_output=True,
        check=False,
        timeout=30,
    )
    if ancestor.returncode != 0:
        _fail()
    try:
        inventory = _inventory(root)
    except ValueError as error:
        raise ValueError("E_DESCENDANT_REPOSITORY") from error
    return {
        "repository_commit": head,
        "repository_tree": tree,
        "repository_file_root_sha256": hashlib.sha256(
            b"HD636/DESCENDANT-FILE-ROOT/v1\0" + _canonical(inventory)
        ).hexdigest(),
    }


def _regular_hash(path: Path, artifacts: RetainedArtifactIO | None = None) -> str:
    return hashlib.sha256(_read_bytes(path, artifacts)).hexdigest()


def _validate_issuance(config: FullVerifierConfig, artifacts: RetainedArtifactIO | None) -> None:
    """The controller's P07 T03 record binds the actual declared invocation."""
    record = _read_evidence(config.candidate_issuance_evidence, artifacts)
    registry = _read_evidence(config.current_checkout_root / "task-command-registry.json")
    rows = registry.get("commands")
    if not isinstance(rows, list):
        _fail()
    declared = next(
        (
            row
            for row in rows
            if isinstance(row, dict) and row.get("command_id") == "VERIFY_V636_P07_T03"
        ),
        None,
    )
    if declared is None:
        _fail()
    command = record.get("command")
    if (
        set(record)
        != {
            "schema_version",
            "result",
            "production_authority",
            "controller_binding",
            "command",
            "proof_coverage_sha256",
        }
        or record.get("schema_version") != "candidate-issuance-result/v1"
        or record.get("result") != "PASS"
        or record.get("production_authority") != "NONE"
        or record.get("controller_binding") != config.binding()
        or record.get("proof_coverage_sha256")
        != hashlib.sha256(_read_bytes(config.proof_coverage_evidence, artifacts)).hexdigest()
        or not isinstance(command, dict)
        or set(command)
        != {
            "command_id",
            "argv",
            "cwd",
            "expected_exit",
            "exit_code",
            "passed",
            "stdout_sha256",
            "stderr_sha256",
            "stdout_size_bytes",
            "stderr_size_bytes",
        }
        or any(
            command[key] != declared[key] for key in ("command_id", "argv", "cwd", "expected_exit")
        )
        or command["cwd"] != str(config.current_checkout_root)
        or type(command["exit_code"]) is not int
        or command["exit_code"] != 0
        or type(command["expected_exit"]) is not int
        or command["expected_exit"] != 0
        or command["passed"] is not True
    ):
        _fail()
    for stream in ("stdout", "stderr"):
        if (
            not isinstance(command[stream + "_sha256"], str)
            or re.fullmatch(r"[0-9a-f]{64}", command[stream + "_sha256"]) is None
            or not isinstance(command[stream + "_size_bytes"], str)
            or re.fullmatch(r"0|[1-9][0-9]*", command[stream + "_size_bytes"]) is None
        ):
            _fail()


def _validated_context(
    root: Path, config: FullVerifierConfig, artifacts: RetainedArtifactIO | None = None
) -> None:
    try:
        if (
            not isinstance(config, FullVerifierConfig)
            or config.schema_version != "full-verifier-controller/v2"
            or config.audited_runtime_ancestor is None
            or config.qualification_evidence is None
            or config.descendant_repository_receipt is None
            or root != root.resolve()
            or root != config.current_checkout_root
        ):
            _fail()
        if artifacts is None:
            reloaded = load_controller_config(config.source_path)
        else:
            recorded = str(config.source_path)
            physical = artifacts.physical_path(
                recorded, recorded_boundary=artifacts.recorded_boundary(recorded)
            )
            reloaded = load_controller_config(
                physical, mode="SEALED", artifacts=artifacts, recorded_locator=recorded
            )
        if reloaded != config:
            _fail()
    except (OSError, ValueError, TypeError, KeyError) as error:
        raise ValueError("E_DESCENDANT_REPOSITORY") from error


def _receipt_record(
    root: Path,
    config: FullVerifierConfig,
    artifacts: RetainedArtifactIO | None = None,
) -> dict[str, object]:
    try:
        _validated_context(root, config, artifacts)
        return _capture_receipt_record(root, config, artifacts)
    except (OSError, ValueError, TypeError, KeyError, subprocess.SubprocessError) as error:
        raise ValueError("E_DESCENDANT_REPOSITORY") from error


def _capture_receipt_record(
    root: Path, config: FullVerifierConfig, artifacts: RetainedArtifactIO | None
) -> dict[str, object]:
    if (
        config.schema_version != "full-verifier-controller/v2"
        or config.audited_runtime_ancestor is None
        or config.qualification_evidence is None
    ):
        _fail()
    _validate_issuance(config, artifacts)
    identity = descendant_repository_identity(root, config.audited_runtime_ancestor)
    candidate = _read_evidence(config.candidate_qualification_receipt, artifacts)
    validate_candidate_qualification_receipt(
        root,
        config.candidate_command_evidence,
        candidate,
        config,
        artifacts=artifacts,
    )
    if verify_toolchains():
        _fail()
    source_map, source_root, source_count = _normative_source_set(
        config.governed_source_pack, artifacts=artifacts
    )
    from tools.run_environment_qualification import verify_environment_qualification_evidence
    from tools.verify_full_repair_qualification import verify_full_repair_qualification

    qualification = config.qualification_evidence
    assert qualification is not None

    def mapped(path: Path) -> Path:
        if artifacts is None:
            return path
        recorded = str(path)
        return artifacts.physical_path(
            recorded, recorded_boundary=artifacts.recorded_boundary(recorded)
        )

    full_proof = verify_full_repair_qualification(
        mapped(qualification.full_repair_aggregate),
        mapped(qualification.full_repair_inventory),
        config,
        artifacts=artifacts,
    )
    p03 = _read_evidence(config.qualification_evidence.p03_proof, artifacts)
    p04 = _read_evidence(config.qualification_evidence.p04_proof, artifacts)
    environment = verify_environment_qualification_evidence(
        qualification.environment_qualification_aggregate,
        qualification.environment_qualification_inventory,
        config,
        artifacts=artifacts,
    )
    if (
        p03
        != {
            **full_proof,
            "schema_version": "full-repair-qualification/v1",
            "clock_proof_pending": True,
        }
        or p04 != full_proof
    ):
        _fail()
    candidate_inventory = candidate.get("inventory")
    if not isinstance(candidate_inventory, dict):
        _fail()
    return {
        "schema_version": "descendant-repository-qualification-receipt/v1",
        "repository_identity_kind": "DESCENDANT",
        "production_authority": "NONE",
        "audited_ancestor_commit": config.audited_runtime_ancestor,
        **identity,
        "candidate_qualification_sha256": _regular_hash(
            config.candidate_qualification_receipt, artifacts
        ),
        "candidate_command_evidence_sha256": _regular_hash(
            config.candidate_command_evidence, artifacts
        ),
        "proof_coverage_sha256": _regular_hash(config.proof_coverage_evidence, artifacts),
        "controller_config_sha256": config.source_sha256,
        "command_result_root": candidate["command_result_root"],
        "candidate_inventory_sha256": hashlib.sha256(
            b"HD636/CANDIDATE-INVENTORY/v1\0" + _canonical(candidate_inventory)
        ).hexdigest(),
        "toolchain_versions": EXPECTED,
        "lockfile_hashes": dependency_lock_hashes(root),
        "vendor_root_sha256": compute_vendor_tree_root(root / "vendor/hybrid-discovery-v6.3.6"),
        "normative_source_map_sha256": source_map,
        "normative_source_set_root": source_root,
        "normative_source_set_count": int(source_count),
        "full_repair_aggregate_sha256": _regular_hash(
            config.qualification_evidence.full_repair_aggregate, artifacts
        ),
        "full_repair_evidence_root_sha256": p03["evidence_root_sha256"],
        "environment_qualification_aggregate_sha256": _regular_hash(
            config.qualification_evidence.environment_qualification_aggregate,
            artifacts,
        ),
        "environment_qualification_evidence_root_sha256": environment["evidence_root_sha256"],
    }


def _outside_protected(output: Path, root: Path, config: FullVerifierConfig) -> None:
    if (
        output != config.descendant_repository_receipt
        or not output.is_absolute()
        or output.parent.resolve(strict=True) != output.parent
        or not output.parent.is_dir()
    ):
        _fail()
    try:
        output.lstat()
    except FileNotFoundError:
        pass
    else:
        _fail()
    candidate = output.resolve(strict=False)
    boundaries = (
        root.resolve(),
        config.governed_source_pack.resolve(),
        config.external_authoring_tests.parent.resolve(),
    )
    if any(
        candidate == boundary
        or candidate.is_relative_to(boundary)
        or boundary.is_relative_to(candidate)
        for boundary in boundaries
    ):
        _fail()


def issue_descendant_qualification_receipt(
    root: Path, config: FullVerifierConfig, output: Path
) -> dict[str, object]:
    owned_identity: tuple[int, int] | None = None
    try:
        _validated_context(root, config)
        _outside_protected(output, root, config)
        before = _receipt_record(root, config)
        encoded = _canonical(before) + b"\n"
        with output.open("x", encoding="utf-8") as stream:
            info = os.fstat(stream.fileno())
            owned_identity = (info.st_dev, info.st_ino)
            stream.write(encoded.decode())
            stream.flush()
            os.fsync(stream.fileno())
            after = _receipt_record(root, config)
            if before != after:
                _fail()
            for _ in range(2):
                info = output.lstat()
                if (
                    not stat.S_ISREG(info.st_mode)
                    or info.st_nlink != 1
                    or (info.st_dev, info.st_ino) != owned_identity
                ):
                    _fail()
                if _ == 0 and _read_bytes(output) != encoded:
                    _fail()
        return before
    except Exception as error:
        if owned_identity is not None:
            try:
                info = output.lstat()
                if (
                    stat.S_ISREG(info.st_mode)
                    and info.st_nlink == 1
                    and (info.st_dev, info.st_ino) == owned_identity
                ):
                    output.unlink()
            except OSError:
                pass
        raise ValueError("E_DESCENDANT_REPOSITORY") from error


def verify_descendant_qualification_receipt(
    root: Path,
    receipt_path: Path,
    *,
    pack: Path,
    config: FullVerifierConfig,
    artifacts: RetainedArtifactIO | None = None,
) -> dict[str, object]:
    try:
        _validated_context(root, config, artifacts)
        if (
            pack != config.governed_source_pack
            or receipt_path != config.descendant_repository_receipt
        ):
            _fail()
        receipt = _read_evidence(receipt_path, artifacts)
        expected = _receipt_record(root, config, artifacts)
        if receipt != expected:
            _fail()
        return receipt
    except (OSError, ValueError, TypeError, KeyError) as error:
        raise ValueError("E_DESCENDANT_REPOSITORY") from error


def main() -> None:
    parser = argparse.ArgumentParser(allow_abbrev=False)
    parser.add_argument("--root", required=True, type=Path)
    parser.add_argument("--config", required=True, type=Path)
    parser.add_argument("--receipt", type=Path)
    parser.add_argument("--output", type=Path)
    parser.add_argument("--pack", type=Path)
    parser.add_argument("--recorded-config")
    parser.add_argument("--retained-manifest", type=Path)
    parser.add_argument("--retained-root", type=Path)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--preflight", action="store_true")
    mode.add_argument("--issue", action="store_true")
    mode.add_argument("--check-only", action="store_true")
    args = parser.parse_args()
    flags = [token.split("=", 1)[0] for token in sys.argv[1:] if token.startswith("--")]
    transport = (args.pack, args.recorded_config, args.retained_manifest, args.retained_root)
    if (
        len(flags) != len(set(flags))
        or (not args.check_only and args.output is None)
        or ((args.issue or args.check_only) and args.receipt is None)
        or (
            any(value is not None for value in transport)
            and (not args.check_only or not all(value is not None for value in transport))
        )
    ):
        parser.error("invalid descendant operation/context")
    artifacts = None
    if args.pack is not None:
        from tools.assemble_review_pack import load_sealed_assembly_context

        config, artifacts = load_sealed_assembly_context(
            args.pack,
            args.config,
            args.recorded_config,
            args.retained_manifest,
            args.retained_root,
        )
        named_receipt = args.pack / "docs/receipts/descendant-repository-qualification-receipt.json"
        if config.descendant_repository_receipt is None:
            _fail()
        if (
            args.root != config.current_checkout_root
            or args.receipt != named_receipt
            or named_receipt.is_symlink()
            or not named_receipt.is_file()
            or named_receipt.read_bytes()
            != _read_bytes(config.descendant_repository_receipt, artifacts)
        ):
            _fail()
    else:
        config = load_controller_config(args.config)
    if args.issue:
        if args.receipt is None:
            _fail()
        result = issue_descendant_qualification_receipt(args.root, config, args.receipt)
    elif args.check_only:
        if args.receipt is None:
            _fail()
        result = verify_descendant_qualification_receipt(
            args.root,
            cast(Path, config.descendant_repository_receipt)
            if artifacts is not None
            else args.receipt,
            pack=config.governed_source_pack,
            config=config,
            artifacts=artifacts,
        )
    else:
        result = {
            "schema_version": "descendant-repository-preflight/v1",
            "result": "PASS",
            "production_authority": "NONE",
            **descendant_repository_identity(args.root, cast(str, config.audited_runtime_ancestor)),
            "controller_binding": config.binding(),
        }
    if args.output is not None:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        with args.output.open("x", encoding="utf-8") as stream:
            stream.write(json.dumps(result, sort_keys=True, separators=(",", ":")) + "\n")
    print(json.dumps(result, sort_keys=True))


