def _observations(browser: str) -> list[dict[str, Any]]:
    """Prevalidated synthetic accounting envelopes, not a production projector."""
    values = []
    for sequence in (1, 2, 3):
        value: dict[str, Any] = {
            "schema_version": "raw-observation/v1",
            "raw_observation_id": "observation:" + f"{sequence:064x}",
            "observation_kind": "TERMINAL",
            "pack_hash": "a" * 64,
            "build_hash": "b" * 64,
            "implementation_baseline_hash": "c" * 64,
            "capability_manifest_hash": "d" * 64,
            "discovery_run_id": browser,
            "run_receipt_hash": "e" * 64,
            "stream_id": STREAM,
            "generation": "0",
            "sequence": str(sequence),
            "context": {
                "context_kind": "RUN_BOUND_NOT_DOCUMENT",
                "browser_run_id": browser,
                "browser_boot_id": browser,
                "binding_reason": "TERMINAL_ACCOUNTING",
            },
            "clock_context": {
                "clock_domain_id": PRODUCER,
                "boot_id": browser,
                "unit": "MICROSECOND",
                "monotonic_value": str(sequence),
                "resolution_us": "1",
                "owner": "BACKEND",
                "mapping_id": "NOT_APPLICABLE",
                "mapping_status": "NOT_APPLICABLE",
            },
            "sanitizer_version": "sanitizer/v1",
            "content_hash": "0" * 64,
            "production_authority": "NONE",
            "facts": {
                "terminal_code": "MANUAL_STOP",
                "final_generation": "0",
                "final_sequence": str(sequence),
                "observation_count": str(sequence),
                "gap_count": "0",
                "safety_disposition": "PARTIAL_EVIDENCE_ONLY",
            },
        }
        value["content_hash"] = canonical_content_hash(
            "RawObservation", value, registry_path=REGISTRY
        )
        validate_artifact(value, "raw-observation.schema.json", bootstrap_only=True, vendor=PACK)
        values.append(value)
    return values


def _call(socket: str, method: str, *arguments: object) -> dict[str, Any]:
    value = _evaluate(
        socket,
        f"globalThis.repairProbe.{method}(" + ",".join(json.dumps(arg) for arg in arguments) + ")",
    )
    if not isinstance(value, dict) or "error" in value:
        raise QualificationRejected(f"E_INDEXEDDB_WORKER:{value}")
    return value


def compare_indexeddb_state(
    actual: dict[str, Any],
    identity: dict[str, Any],
    observations: list[dict[str, Any]],
    count: int,
    *,
    ack: int = 0,
) -> None:
    """Parent-only comparator over read-back rows, never checkpoint-derived state."""
    for field, value in identity.items():
        if actual.get(field) != value:
            raise ValueError("E_INDEXEDDB_IDENTITY:" + field)
    entries = actual["entries"]
    states = actual["states"]
    if len(entries) != count or len(states) != (1 if count else 0):
        raise ValueError("E_INDEXEDDB_STATE")
    previous = H0
    hashes = [H0]
    byte_count = 0
    for index, entry in enumerate(entries):
        raw = observations[index]
        record = entry["spool_record"]
        if (
            set(entry) != {"storage_schema_version", "spool_record", "sanitized_observation"}
            or entry["storage_schema_version"] != "browser-spool-entry/v1"
            or entry["sanitized_observation"] != raw
        ):
            raise ValueError("E_INDEXEDDB_ENVELOPE")
        validate_artifact(
            record, "durability-records.schema.json", bootstrap_only=True, vendor=PACK
        )
        cursor = canonical_content_hash(
            "CursorStep",
            {
                "schema_version": "cursor-step/v1",
                "discovery_run_id": raw["discovery_run_id"],
                "browser_run_id": raw["context"]["browser_run_id"],
                "producer_id": PRODUCER,
                "stream_id": STREAM,
                "generation": "0",
                "sequence": str(index + 1),
                "raw_observation_hash": raw["content_hash"],
                "previous_cursor_hash": previous,
            },
            registry_path=REGISTRY,
        )
        position = {
            "generation_key": {
                "stream": {
                    "browser_run_id": raw["context"]["browser_run_id"],
                    "producer_id": PRODUCER,
                    "stream_id": STREAM,
                },
                "generation": "0",
            },
            "sequence": str(index + 1),
        }
        size = len(json.dumps(raw, sort_keys=True, separators=(",", ":")).encode())
        if (
            record["position"] != position
            or record["previous_cursor_hash"] != previous
            or record["cursor_hash"] != cursor
            or record["raw_observation_id"] != raw["raw_observation_id"]
            or record["raw_observation_content_hash"] != raw["content_hash"]
            or record["payload_size_bytes"] != str(size)
            or record["content_hash"]
            != canonical_content_hash("SpoolRecord", record, registry_path=REGISTRY)
        ):
            raise ValueError("E_INDEXEDDB_CHAIN")
        previous = cursor
        hashes.append(cursor)
        byte_count += size
    if actual["keys"] != [[PRODUCER, STREAM, "0" * 19, str(i + 1).zfill(19)] for i in range(count)]:
        raise ValueError("E_INDEXEDDB_KEYS")
    if count and states != [
        {
            "storage_schema_version": "browser-stream-state/v1",
            "producer_id": PRODUCER,
            "stream_id": STREAM,
            "active_generation": "0",
            "next_sequence": str(count + 1),
            "last_cursor_hash": previous,
            "ack_generation": "0",
            "ack_sequence": str(ack),
            "ack_cursor_hash": hashes[ack],
            "normal_bytes_used": str(byte_count),
            "terminal_reserve_bytes_used": "0",
            "generation_state": "ACTIVE",
        }
    ]:
        raise ValueError("E_INDEXEDDB_STATE")


def run_indexeddb_case(
    entry: dict[str, Any],
    workspace: Path,
    *,
    browser_binary: Path | None = None,
    mutation: str | None = None,
    operation: str = "crash",
    full: bool = False,
    input_rejection: bool = False,
) -> dict[str, Any]:
    from tools.verify_repair_evidence import capture_binding

    browser_binary = browser_binary or Path(os.environ.get("BH_CHROME_BINARY", str(CHROME)))
    workspace.mkdir(parents=True, exist_ok=False)
    if not browser_binary.is_file():
        return {
            "result": "BLOCKED_ENVIRONMENT",
            "status": "BLOCKED_ENVIRONMENT",
            "blocker_code": "E_BROWSER_UNAVAILABLE",
            "reason": "E_BROWSER_UNAVAILABLE",
            "executed": False,
            "launch_attempted": False,
            "prerequisite": {"name": "Chrome for Testing", "available": False},
            "attempted_real_browser": False,
            "vector_id": entry["vector_id"],
            "case_id": entry["vector_id"],
        }
    evidence_binding = capture_binding()
    registered = json.loads((PACK / "docs/registries/crash-harness-registry.v1.json").read_text())[
        "entries"
    ]
    original = next(row for row in registered if row["vector_id"] == entry["vector_id"])
    if any(
        entry[field] != original[field]
        for field in ("harness", "crash_checkpoint", "kill_action", "source_boundary")
    ):
        raise ValueError("E_INDEXEDDB_REGISTERED_BOUNDARY")
    profile = workspace / "chrome-profile"
    profile.mkdir()
    profile_id = str(uuid4())
    (profile / "BH_R05_PROFILE_ID").write_text(profile_id)
    extension, extension_id, module_hash = _prepare_test_extension(ROOT, workspace)
    process = None
    try:
        origin = "chrome-extension://" + extension_id
        process, socket = _start_chrome(
            browser_binary,
            profile,
            extension,
            origin + "/repair-probe.html",
            workspace / "chrome.log",
        )
        binary = _process_executable(process)
        if binary != _canonical_browser_executable(browser_binary):
            raise ValueError("E_BROWSER_BINARY_MISMATCH")
        _wait_for_probe(socket)
        sentinel = token_hex(32)
        initial_sentinel = _call(socket, "writeSentinel", sentinel, profile_id)
        if (
            initial_sentinel.get("sentinel") != sentinel
            or initial_sentinel.get("profileId") != profile_id
        ):
            raise ValueError("E_INDEXEDDB_PROFILE")
        run_id = str(uuid4())
        observations = _observations(run_id)
        binding = {
            "run_id": run_id,
            "case_id": entry["vector_id"],
            "checkpoint_id": entry["crash_checkpoint"],
            "test_nonce": token_hex(16),
            "profile_id": profile_id,
            "component": entry["harness"],
            "ordinal": 0,
            "pid": process.pid,
        }
        identity = {
            **binding,
            "module_sha256": module_hash,
            "origin": origin,
            "protocol": "chrome-extension:",
            "module_url": origin + "/src/spool.js",
        }
        request = {
            "identity": binding,
            "operation": operation,
            "options": {
                "browser_run_id": run_id,
                "producer_id": PRODUCER,
                "stream_id": STREAM,
                "generation": "0",
                "registry": json.loads(REGISTRY.read_text()),
            },
            "observations": [
                json.dumps(value, sort_keys=True, separators=(",", ":")) for value in observations
            ],
        }
        if full:
            from tools.run_loopback_ack_crash_matrix import run_browser_handshake

            return run_browser_handshake(
                entry,
                workspace,
                socket,
                request,
                identity,
                evidence_binding,
                extension,
                binary,
                observations,
                browser_process=process,
                profile=profile,
                sentinel=sentinel,
                initial_sentinel=initial_sentinel,
                input_rejection=input_rejection,
            )
        worker_input = workspace / "input.json"
        worker_input.write_text(json.dumps(request, sort_keys=True))
        (workspace / "expected.json").write_text(
            json.dumps(entry["expected_post_restart_state"], sort_keys=True)
        )
        first_id = str(uuid4())
        checkpoint = _call(socket, "startWorker", first_id, request)
        if (
            any(checkpoint.get(key) != value for key, value in identity.items())
            or checkpoint.get("worker_id") != first_id
        ):
            raise ValueError("E_INDEXEDDB_CHECKPOINT_IDENTITY")
        if operation == "crash" and checkpoint.get("boundary") != entry["crash_checkpoint"]:
            raise ValueError("E_INDEXEDDB_CHECKPOINT")
        termination = _call(socket, "terminateWorker", first_id)
        if termination != {"method": "Worker.terminate", "worker_id": first_id}:
            raise ValueError("E_INDEXEDDB_TERMINATION")
        second_id = str(uuid4())
        # The reader receives a database identity only, no scenario or expected rows.
        reader = {
            "identity": binding,
            "options": request["options"],
            "operation": "read",
            "observations": [],
        }
        if mutation:
            reader["mutation"] = mutation
        reader_input = workspace / "reader-input.json"
        reader_input.write_text(json.dumps(reader, sort_keys=True))
        actual = _call(socket, "startWorker", second_id, reader)
        _call(socket, "terminateWorker", second_id)
        persisted = _call(socket, "readSentinel", profile_id)
        if (
            persisted.get("sentinel") != sentinel
            or persisted.get("profileId") != profile_id
            or (profile / "BH_R05_PROFILE_ID").read_text() != profile_id
        ):
            raise ValueError("E_INDEXEDDB_PROFILE")
        if actual.get("worker_id") != second_id:
            raise ValueError("E_INDEXEDDB_WORKER_IDENTITY")
        record = {
            "vector_id": entry["vector_id"],
            "case_id": entry["vector_id"],
            "identity": identity,
            "checkpoint": checkpoint,
            "termination": termination,
            "actual": actual,
            "execution_kind": "EXTENSION_DEDICATED_WORKER_TERMINATION",
            "executed": True,
            "launch_attempted": True,
            "evidence_binding": evidence_binding,
            "command_exit": {"browser": 0, "worker": 0, "reader": 0},
            "browser": {"executable": str(binary), "sha256": _sha256(binary)},
            "profile": str(profile),
            "source_sha256": _sha256(ROOT / "extension/src/spool.ts"),
            "observations": observations,
            "expected": entry["expected_post_restart_state"],
            "qualification_scope": "INDEXEDDB_SPOOL_ONLY",
            "legacy_full_qualification": "HOLD",
            "environment": {"system": platform.system(), "release": platform.release()},
            "input_sha256": _sha256(workspace / "input.json"),
            "expected_sha256": _sha256(workspace / "expected.json"),
            "module_hashes": {
                str(path.relative_to(extension)): _sha256(path)
                for path in sorted(extension.rglob("*.js"))
            },
        }
        (workspace / "observation.json").write_text(json.dumps(record, sort_keys=True))
        count = (
            2
            if operation == "exercise"
            else entry["expected_post_restart_state"]["indexeddb_spool_delta"]
        )
        compare_indexeddb_state(
            actual, identity, observations, count, ack=1 if operation == "exercise" else 0
        )
        if entry["expected_post_restart_state"] != original["expected_post_restart_state"]:
            raise ValueError("E_INDEXEDDB_EXPECTED")
        git = shutil.which("git")
        if git is None:
            raise ValueError("E_INDEXEDDB_REVISION_UNAVAILABLE")
        record["revision"] = run(  # noqa: S603 -- fixed local read-only revision query.
            [git, "rev-parse", "HEAD"],
            cwd=ROOT,
            check=True,
            capture_output=True,
            text=True,
            timeout=10,
        ).stdout.strip()
        record["result"] = "PASS"
        record["status"] = "PASS"
        record["comparison"] = {"matched": True, "scope": "INDEXEDDB_SPOOL_ONLY"}
        actual_artifact = workspace / "actual.json"
        actual_artifact.write_text(json.dumps(actual, sort_keys=True, separators=(",", ":")))
        record["actual_artifact"] = {
            "path": str(actual_artifact.resolve()),
            "sha256": _sha256(actual_artifact),
        }
        record["worker_input_artifact"] = {
            "path": str(worker_input.resolve()),
            "sha256": _sha256(worker_input),
        }
        record["reader_input_artifact"] = {
            "path": str(reader_input.resolve()),
            "sha256": _sha256(reader_input),
        }
        expected_artifact = workspace / "expected.json"
        record["expected_artifact"] = {
            "path": str(expected_artifact.resolve()),
            "sha256": _sha256(expected_artifact),
        }
        (workspace / "observation.json").write_text(json.dumps(record, sort_keys=True))
        record["artifact"] = str(workspace / "observation.json")
        record["artifact_sha256"] = _sha256(workspace / "observation.json")
        return record
    except _EnvironmentBlocked as error:
        return {
            "result": "BLOCKED_ENVIRONMENT",
            "status": "BLOCKED_ENVIRONMENT",
            "blocker_code": error.code,
            "blocker_detail": error.detail,
            "reason": error.code,
            "executed": False,
            "launch_attempted": False,
            "prerequisite": {"name": "Chrome for Testing extension origin", "available": False},
            "attempted_real_browser": True,
            "vector_id": entry["vector_id"],
            "case_id": entry["vector_id"],
        }
    finally:
        if process is not None and process.poll() is None:
            _kill_owned_process_group(process)


def run_full_repair_evidence(
    pack: Path,
    runtime: Path,
    workspace: Path,
    *,
    browser_binary: Path | None = None,
) -> dict[str, Any]:
    """Execute all registered durability owners and all governed clock vectors."""
    from tools.run_clock_vector_qualification import run_clock_vector_qualification
    from tools.run_destruction_crash_matrix import run_destruction_crash_matrix
    from tools.run_gap_coherence_crash_matrix import run_gap_coherence_crash_matrix
    from tools.run_loopback_ack_crash_matrix import run_loopback_ack_crash_matrix
    from tools.run_sqlite_crash_matrix import run_sqlite_crash_matrix
    from tools.verify_repair_evidence import aggregate_repair_evidence, full_required_ids

    workspace.mkdir(parents=True, exist_ok=False)
    registry = json.loads((pack / "docs/registries/crash-harness-registry.v1.json").read_text())
    owner_reports = {
        "SQLITE_TRANSACTION": run_sqlite_crash_matrix(pack, workspace / "sqlite"),
        "CHROME_INDEXEDDB": run_indexeddb_crash_matrix(
            pack, workspace / "indexeddb", browser_binary=browser_binary
        ),
        "LOOPBACK_ACK": run_loopback_ack_crash_matrix(
            pack, workspace / "loopback-ack", browser_binary=browser_binary
        ),
        "GAP_GENERATION_COHERENCE": run_gap_coherence_crash_matrix(
            pack, workspace / "gap-coherence"
        ),
        "WHOLE_RUN_DESTRUCTION": run_destruction_crash_matrix(pack, workspace / "destruction"),
    }
    crash_by_id: dict[str, dict[str, Any]] = {}
    for harness, report in owner_reports.items():
        expected = [
            entry["vector_id"] for entry in registry["entries"] if entry["harness"] == harness
        ]
        records = report.get("records", [])
        actual = [row.get("case_id", row.get("vector_id")) for row in records]
        if actual != expected or report.get("executed_vector_ids") != expected:
            raise ValueError("E_FULL_OWNER_REQUIRED_CASES:" + harness)
        for row in records:
            case_id = row.get("case_id", row.get("vector_id"))
            if case_id in crash_by_id:
                raise ValueError("E_FULL_OWNER_DUPLICATE:" + str(case_id))
            crash_by_id[str(case_id)] = row
    crash = [crash_by_id[entry["vector_id"]] for entry in registry["entries"]]
    clock = run_clock_vector_qualification(
        pack,
        runtime,
        evidence_dir=workspace / "clock",
    )
    records = [*crash, *clock["records"]]
    aggregate = aggregate_repair_evidence(full_required_ids(), records)
    try:
        mutation_summary = validate_full_mutation_reports(pack, owner_reports, clock)
    except (KeyError, TypeError, ValueError, OSError) as error:
        mutation_summary = {
            "required": 105,
            "verified": 0,
            "survivors": None,
            "complete": False,
            "error": str(error),
        }
        aggregate = {
            **aggregate,
            "result": "FAIL",
            "legacy_full_qualification": "HOLD",
            "errors": [*aggregate["errors"], {"case_id": "", "error": str(error)}],
        }
    result = {
        **aggregate,
        "records": records,
        "owner_reports": owner_reports,
        "clock_report": clock,
        "mutation_summary": mutation_summary,
    }
    if result["result"] == "PASS" and mutation_summary.get("complete") is True:
        from moj_discovery.durability_release import validate_full_durability_release

        required = full_required_ids()
        result["release_gate"] = validate_full_durability_release(
            required,
            required,
            mutation_survivors=0,
            evidence=records,
            mutation_summary=mutation_summary,
            mutation_evidence={"owner_reports": owner_reports, "clock_report": clock},
        )
    (workspace / "current-aggregate.json").write_text(json.dumps(result, sort_keys=True))
    return result


def required_clock_mutation_ids() -> list[str]:
    from tools.run_clock_vector_qualification import _MUTATION_NAMES

    return list(_MUTATION_NAMES)


def _owner_mutations(report: dict[str, Any]) -> list[dict[str, Any]]:
    if "mutation_results" in report:
        return list(report["mutation_results"])
    return [mutation for row in report.get("records", []) for mutation in row.get("mutations", [])]


def _mutation_id(row: dict[str, Any]) -> str:
    return str(row.get("mutation", row.get("vector_id", row.get("case_id", ""))))


def _mutation_control_id(row: dict[str, Any]) -> str:
    if "source_vector_id" in row:
        return str(row["source_vector_id"])
    if "mutation" in row:
        return str(row.get("vector_id", ""))
    execution = row.get("execution")
    return str(execution.get("case_id", "")) if isinstance(execution, dict) else ""


def full_control_records(
    pack: Path,
    owner_reports: dict[str, dict[str, Any]],
    clock_report: dict[str, Any],
) -> list[dict[str, Any]]:
    """Return exact registry-ordered controls after validating every owner inventory."""
    crash = json.loads((pack / "docs/registries/crash-harness-registry.v1.json").read_text())[
        "entries"
    ]
    clock = json.loads((pack / "docs/registries/clock-vector-coverage.v1.json").read_text())[
        "entries"
    ]
    harnesses = list(dict.fromkeys(entry["harness"] for entry in crash))
    if set(owner_reports) != set(harnesses):
        raise ValueError("E_FULL_CONTROL_OWNER_SET")
    controls: dict[str, dict[str, Any]] = {}
    for harness in harnesses:
        expected = [entry["vector_id"] for entry in crash if entry["harness"] == harness]
        report = owner_reports[harness]
        records = list(report.get("records", []))
        actual = [str(row.get("case_id", row.get("vector_id", ""))) for row in records]
        if actual != expected or report.get("executed_vector_ids") != expected:
            raise ValueError("E_FULL_CONTROL_OWNER_RECORDS:" + harness)
        if any(case_id in controls for case_id in actual):
            raise ValueError("E_FULL_CONTROL_DUPLICATE")
        controls.update(zip(actual, records, strict=True))
    clock_ids = [entry["vector_id"] for entry in clock]
    clock_records = list(clock_report.get("records", []))
    actual_clock = [str(row.get("case_id", row.get("vector_id", ""))) for row in clock_records]
    if actual_clock != clock_ids or clock_report.get("required_vector_ids") != clock_ids:
        raise ValueError("E_FULL_CONTROL_CLOCK_RECORDS")
    return [controls[entry["vector_id"]] for entry in crash] + clock_records


def _verify_owner_mutation(
    harness: str,
    row: dict[str, Any],
    binding: dict[str, Any],
    artifacts: RetainedArtifactIO | None = None,
) -> None:
    if harness == "GAP_GENERATION_COHERENCE":
        from tools.run_gap_coherence_crash_matrix import verify_gap_mutation

        verify_gap_mutation(row, binding, artifacts=artifacts)
    elif harness == "WHOLE_RUN_DESTRUCTION":
        from tools.verify_destruction_evidence import verify_destruction

        execution = row["execution"]
        verify_destruction(execution, binding, mutation_type=row["kind"], artifacts=artifacts)
    else:
        from tools.verify_repair_evidence import verify_owner_mutation

        verify_owner_mutation(harness, row, binding, artifacts=artifacts)


def _verify_clock_mutation(
    row: dict[str, Any],
    binding: dict[str, Any],
    artifacts: RetainedArtifactIO | None = None,
) -> None:
    from tools.run_clock_vector_qualification import verify_record

    if not verify_record(row, _current_binding=binding, artifacts=artifacts):
        raise ValueError("E_FULL_MUTATION_CLOCK_EVIDENCE")


def validate_full_mutation_reports(
    pack: Path,
    owner_reports: dict[str, dict[str, Any]],
    clock_report: dict[str, Any] | None,
    *,
    artifacts: RetainedArtifactIO | None = None,
) -> dict[str, Any]:
    """Require every registered mutation once and recursively verify its evidence."""
    from tools.verify_repair_evidence import _RETAINED_ARTIFACTS, capture_binding

    registry = json.loads((pack / "docs/registries/crash-harness-registry.v1.json").read_text())
    harnesses = list(dict.fromkeys(entry["harness"] for entry in registry["entries"]))
    if set(owner_reports) != set(harnesses):
        raise ValueError("E_FULL_MUTATION_OWNER_SET")
    if clock_report is None:
        raise ValueError("E_FULL_MUTATION_CLOCK_EVIDENCE")
    controls = full_control_records(pack, owner_reports, clock_report)
    control_ids = {str(row.get("case_id", row.get("vector_id", ""))) for row in controls}
    expected_by_harness = {
        harness: [
            (mutation, entry["vector_id"])
            for entry in registry["entries"]
            if entry["harness"] == harness
            for mutation in entry["mutation_vector_ids"]
        ]
        for harness in harnesses
    }
    binding = capture_binding()
    artifact_token = _RETAINED_ARTIFACTS.set(artifacts)
    verified = 0
    survivors = 0
    try:
        for harness, expected_pairs in expected_by_harness.items():
            mutations = _owner_mutations(owner_reports[harness])
            actual_pairs = [(_mutation_id(row), _mutation_control_id(row)) for row in mutations]
            if actual_pairs != expected_pairs:
                raise ValueError("E_FULL_MUTATION_REQUIRED_SET:" + harness)
            for row in mutations:
                if row.get("detected") is not True:
                    survivors += 1
                    raise ValueError("E_FULL_MUTATION_SURVIVOR:" + _mutation_id(row))
                if "control" in row and row["control"] != next(
                    control
                    for control in controls
                    if control.get("case_id", control.get("vector_id"))
                    == _mutation_control_id(row)
                ):
                    raise ValueError("E_FULL_MUTATION_CONTROL_LINK")
                if artifacts is None:
                    _verify_owner_mutation(harness, row, binding)
                else:
                    _verify_owner_mutation(harness, row, binding, artifacts)
                verified += 1
        clock_mutations = list(clock_report.get("mutation_records", []))
        expected_clock = required_clock_mutation_ids()
        if [_mutation_id(row) for row in clock_mutations] != expected_clock:
            raise ValueError("E_FULL_MUTATION_REQUIRED_SET:CLOCK")
        for row in clock_mutations:
            if row.get("detected") is not True or row.get("executed") is not True:
                raise ValueError("E_FULL_MUTATION_SURVIVOR:" + _mutation_id(row))
            if artifacts is None:
                _verify_clock_mutation(row, binding)
            else:
                _verify_clock_mutation(row, binding, artifacts)
            actual = row.get("actual", {})
            source = row.get("source_vector_id")
            if source is None and isinstance(actual, dict):
                control = actual.get("control", {})
                trial = actual.get("trial", {})
                if isinstance(control, dict) and isinstance(trial, dict):
                    if control.get("case_id") != trial.get("case_id"):
                        raise ValueError("E_FULL_MUTATION_CLOCK_CONTROL")
                    source = control.get("case_id")
            if source not in control_ids:
                raise ValueError("E_FULL_MUTATION_CLOCK_CONTROL")
            verified += 1
    finally:
        _RETAINED_ARTIFACTS.reset(artifact_token)
    return {
        "required": 105,
        "verified": verified,
        "survivors": survivors,
        "complete": verified == 105 and survivors == 0,
    }


def run_indexeddb_crash_matrix(
    pack: Path,
    workspace: Path,
    *,
    browser_binary: Path | None = None,
    full: bool = True,
    include_mutations: bool = True,
) -> dict[str, Any]:
    entries = json.loads((pack / "docs/registries/crash-harness-registry.v1.json").read_text())[
        "entries"
    ]
    selected = [entry for entry in entries if entry["harness"] == "CHROME_INDEXEDDB"]
    required = json.loads((PACK / "docs/registries/crash-harness-registry.v1.json").read_text())[
        "entries"
    ]
    required_ids = [
        entry["vector_id"] for entry in required if entry["harness"] == "CHROME_INDEXEDDB"
    ]
    if [entry["vector_id"] for entry in selected] != required_ids:
        raise ValueError("E_INDEXEDDB_REQUIRED_CASES")
    records = [
        run_indexeddb_case(
            entry,
            workspace / f"case-{uuid4()}",
            browser_binary=browser_binary,
            full=full,
        )
        for entry in selected
    ]
    from tools.owner_mutation_evidence import campaign

    mutations = (
        campaign(selected, workspace / "mutations", records) if full and include_mutations else []
    )
    return {
        "result": "PASS"
        if all(row["result"] == "PASS" for row in records)
        else "BLOCKED_ENVIRONMENT",
        "executed_vector_ids": [row["vector_id"] for row in records if row["result"] == "PASS"],
        "records": records,
        "mutation_results": mutations,
        "killed_child_count": sum(row["result"] == "PASS" for row in records),
        "qualification_scope": "BROWSER_LOOPBACK_ACK" if full else "INDEXEDDB_SPOOL_ONLY",
        "legacy_full_qualification": "HOLD",
    }"""Live service dispatch exclusively through a consumed user-terminal intent."""

# ruff: noqa: E402
import asyncio
import base64
import importlib
import json
import sys
import time
from collections.abc import Callable
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT), str(ROOT / "src")]

from moj_discovery.live_config import LiveConfig
from moj_discovery.live_service import LiveService, run_live_service
from moj_discovery.secrets_local import SecretValue, controlling_tty


def show_local_pairing(service: LiveService) -> None:
    """Deliver one-use extension pairing only to the user's controlling terminal."""
    with controlling_tty() as terminal:
        ticket: dict[str, Any] = {
            "version": 1,
            "runId": service.admitted.run_id,
            "durationSeconds": max(
                1, min(7200, int(service.admitted.deadline_mono - time.monotonic()))
            ),
        }
        for field, role in (("ui", "UI_SUBSCRIBER"), ("capture", "CAPTURE_PRODUCER")):
            item = service.pairing.issue(role)
            ticket[field] = {
                "sessionId": item.session_id,
                "key": base64.urlsafe_b64encode(item.key).decode().rstrip("="),
            }
        terminal.write(
            "Local pairing ticket, valid for 120 seconds. Paste only into the extension panel.\n"
        )
        terminal.write(json.dumps(ticket, separators=(",", ":")) + "\n")
        terminal.flush()


def enable_local_repair(service: LiveService) -> Callable[[], None]:
    """Only an explicit PAIR line in the same user terminal can renew pairing."""
    scope = controlling_tty()
    terminal = scope.__enter__()
    loop = asyncio.get_running_loop()
    descriptor = terminal.fileno()
    closed = False

    def close() -> None:
        nonlocal closed
        if not closed:
            closed = True
            loop.remove_reader(descriptor)
            scope.__exit__(None, None, None)

    def ready() -> None:
        line = terminal.readline(256)
        if line == "":
            close()
        elif line.strip() == "PAIR":
            try:
                show_local_pairing(service)
            except ValueError:
                terminal.write("PAIRING_UNAVAILABLE: existing ticket, cap or expired session.\n")
                terminal.flush()
        elif line.startswith("CHECK "):
            try:
                _, fixture, home, draw, away = line.split()
                service.record_manual_ft_check(int(fixture), (home, draw, away))
                terminal.write("FT_CHECK_RECORDED\n")
            except (ValueError, KeyError, StopIteration):
                terminal.write(
                    "FT_CHECK_REFUSED: not current, mismatched, duplicate or outside scope.\n"
                )
            terminal.flush()

    try:
        show_local_pairing(service)
        terminal.write("After worker restart, type PAIR here for a fresh local ticket.\n")
        terminal.write(
            "Compare the exact fixture, market and HOME/DRAW/AWAY selection IDs in both views.\n"
            "Then record the visible prices: CHECK fixture_id home_price draw_price away_price\n"
            "Record three distinct current FT captures per fixture, at least 30 seconds apart.\n"
        )
        terminal.flush()
        loop.add_reader(descriptor, ready)
    except BaseException:
        close()
        raise
    return close


def run_live_session(
    config: LiveConfig,
    secret: SecretValue,
    receipt: object,
    *,
    verified_evidence: Any = None,
) -> dict[str, Any]:
    try:
        gate = importlib.import_module("moj_discovery.live_preflight_batched")
        admission = gate.admit_live_run(config, receipt, verified=verified_evidence)
    except Exception:
        raise ValueError("E_LIVE_RUN_ADMISSION") from None
    result = run_live_service(config, secret, admission, on_ready=enable_local_repair)
    return {
        "LIVE_SESSION_RESULT": "CLOSED_PENDING_REPLAY",
        "REQUEST_ATTEMPTS": result.request_attempts,
        "REAL_HTTP_ATTEMPTS": result.real_http_attempts,
        "RUN_DIRECTORY": result.run_directory,
        "REPLAY_REQUIRED": True,
    }


def main(argv: list[str] | None = None) -> int:
    # This CLI has no credential/env bypass and cannot independently authorize a run.
    print("WAITING_REVIEW: use the no-echo user-terminal launcher after current run admission")
    return 2


if __name__ == "__main__":
    raise SystemExit(main())"""Backend-only evidence for inherited crash IDs; missing full contracts stay HOLD."""

from __future__ import annotations

import hashlib
import json
import os
import platform
import signal
import sqlite3
import subprocess
import sys
from contextlib import closing
from pathlib import Path
from secrets import token_hex
from time import monotonic, sleep
from typing import Any, cast
from uuid import uuid4

from moj_discovery.schema_registry import validate_artifact
from moj_discovery.store import TABLES, VENDOR
from tools.inspect_restart_state import execute_crash_matrix
from tools.loopback_ack_crash_child import BEFORE_STATEMENT, position
from tools.restart_state_reader import read_restart_state

PHASES = {
    "SEND-01": "after_receive_before_begin",
    "SQL-01": "after_raw_insert",
    "SQL-02": "after_application_insert",
    "SQL-03": "after_revision_insert",
    "SQL-04": "after_cursor_insert",
    "SQL-05": "after_outbox_insert",
    "SQL-06": "during_commit",
    "SQL-07": "after_commit_before_send",
    "ACK-06": "after_duplicate_ack",
    "GAP-01": "after_gap_insert",
    "GAP-02": "after_shock_insert",
    "GAP-03": "after_coherence_transition",
    "GAP-04": "after_controller_close",
    "GAP-05": "after_epoch_binding",
    "GAP-06": "after_predecessor_close",
    "GAP-07": "after_generation_transition",
    "GAP-08": "after_successor_insert",
    "GAP-10": "after_gap_commit",
    "LATE-01": "after_late_rejection",
}
CHAIN = ("raw_commits", "application_records", "derived_revisions", "reducer_cursors", "ack_outbox")
GAP_INSERTS = (
    "gap_records",
    "shock_observations",
    "coherence_transitions",
    "gap_epoch_bindings",
    "generation_transitions",
    "stream_generations",
)
H0 = "149300a0e3954885a1d6c0f13a9d1101227cc21cce37bd6b7c72eab641741c0c"


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _trusted_command() -> list[str]:
    return [
        str(Path(sys.executable).absolute()),
        "-I",
        str(Path(__file__).with_name("loopback_ack_crash_child.py").resolve()),
    ]


def _launch_provenance(
    command: list[str], *, trusted_command: list[str] | None = None
) -> dict[str, Any]:
    if command != (trusted_command or _trusted_command()):
        raise ValueError("E_CRASH_CHILD_PROVENANCE")
    return {
        "command_prefix": command,
        "executable": {
            "path": command[0],
            "resolved_path": str(Path(command[0]).resolve()),
            "sha256": _sha(Path(command[0])),
        },
        "entrypoint": {"path": command[2], "sha256": _sha(Path(command[2]))},
    }


def _snapshot(state: dict[str, Any]) -> dict[str, Any]:
    """Fixed observed projection; no vector/checkpoint/oracle data is consulted."""
    tables = state["tables"]
    return {
        "counts": {name: len(rows) for name, rows in tables.items()},
        "raw": [
            [row["sequence"], row["raw_observation_content_hash"], row["cursor_hash"]]
            for row in tables["raw_commits"]
        ],
        "generations": sorted(
            [[row["generation"], row["generation_state"]] for row in tables["stream_generations"]]
        ),
        "controllers": [
            [row["controller_state"], row["controller_revision"]]
            for row in tables["coherence_controllers"]
        ],
        "gap_ranges": [
            [row["missing_from_sequence"], row["missing_to_sequence"], row["detected_sequence"]]
            for row in tables["gap_records"]
        ],
        "ack_cursors": tables["ack_cursors"],
    }


def _oracle(base: dict[str, Any], committed: bool, gap: bool) -> dict[str, Any]:
    """Parent-only requirement oracle. Compute H1 independently from the published preimage."""
    step = {
        "schema_version": "cursor-step/v1",
        "discovery_run_id": base["discovery_run_id"],
        "browser_run_id": base["context"]["browser_run_id"],
        "producer_id": base["clock_context"]["clock_domain_id"],
        "stream_id": base["stream_id"],
        "generation": "0",
        "sequence": "1",
        "raw_observation_hash": base["content_hash"],
        "previous_cursor_hash": H0,
    }
    cursor = hashlib.sha256(
        b"HYBRID-DISCOVERY/v6.2/CursorStep/v1\0"
        + json.dumps(step, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()
    ).hexdigest()
    counts = dict.fromkeys(
        (
            *CHAIN,
            "raw_conflicts",
            "ack_cursors",
            "gap_records",
            "gap_epoch_bindings",
            "generation_transitions",
            "coherence_transitions",
            "shock_observations",
        ),
        0,
    )
    counts.update(run_meta=1, stream_generations=1, coherence_epochs=1, coherence_controllers=1)
    if committed:
        counts.update(dict.fromkeys(CHAIN, 1))
    if gap:
        counts.update(dict.fromkeys(GAP_INSERTS, 1))
        counts["stream_generations"] = 2
    return {
        "counts": counts,
        "raw": [[1, base["content_hash"], cursor]] if committed else [],
        "generations": [[0, "QUARANTINED_GAP"], [1, "ACTIVE"]] if gap else [[0, "ACTIVE"]],
        "controllers": [["SHOCKED_CLOSED", 1]] if gap else [["OPEN", 0]],
        "gap_ranges": [[2, 2, 3]] if gap else [],
        "ack_cursors": [],
    }


def run_backend_case(
    entry: dict[str, Any],
    observation: dict[str, Any],
    workspace: Path,
    *,
    command_prefix: list[str] | None = None,
    trusted_command: list[str] | None = None,
    reader_command: list[str] | None = None,
) -> dict[str, Any]:
    command = _trusted_command() if command_prefix is None else list(command_prefix)
    provenance = _launch_provenance(
        command, trusted_command=trusted_command
    )  # Reject substitutions before provision/launch.
    key = "-".join(entry["vector_id"].split("-")[:2])
    if key not in PHASES:
        raise ValueError("E_CRASH_BOUNDARY_NOT_IMPLEMENTED:" + key)
    registry = json.loads((VENDOR / "docs/registries/crash-harness-registry.v1.json").read_text())[
        "entries"
    ]
    matches = [row for row in registry if row["vector_id"] == entry["vector_id"]]
    if len(matches) != 1 or any(
        entry[field] != matches[0][field]
        for field in ("crash_checkpoint", "harness", "source_boundary", "kill_action")
    ):
        raise ValueError("E_CRASH_REGISTERED_BOUNDARY_MISMATCH")
    validate_artifact(
        observation, "raw-observation.schema.json", bootstrap_only=True, vendor=VENDOR
    )
    if observation["generation"] != "0" or observation["sequence"] != "1":
        raise ValueError("E_CRASH_SCENARIO_POSITION")
    phase = PHASES[key]
    is_gap = key.startswith("GAP")
    late = key == "LATE-01"
    base_committed = is_gap or late or key == "ACK-06"
    committed = base_committed or key == "SQL-07"
    gap_committed = key == "GAP-10" or late
    scenario: dict[str, Any] = {
        "phase": phase,
        "observation": observation,
        "setup_deliveries": (
            [observation, position(observation, 3)]
            if late
            else [observation]
            if base_committed
            else []
        ),
        "delivery": position(observation, 2 if late else 3) if is_gap or late else observation,
    }
    expected = _oracle(observation, committed, gap_committed)
    # Preserve inherited parent expectations for every SQL delta we actually cover.
    # Other vector fields (browser ACK/spool/release) remain unqualified below.
    if not late:
        for name, delta in entry["expected_post_restart_state"].get("sql_row_deltas", {}).items():
            if name in expected["counts"]:
                baseline = int(name in CHAIN and base_committed)
                baseline += int(
                    name
                    in {
                        "run_meta",
                        "coherence_epochs",
                        "coherence_controllers",
                        "stream_generations",
                    }
                )
                expected["counts"][name] = baseline + delta
    recovered_gap = is_gap or late
    expected_replay = (
        "E_INGEST_GENERATION_CLOSED" if gap_committed else "E_INGEST_GAP" if is_gap else "ACK"
    )
    expected_state: dict[str, Any]
    if key == "SQL-06":
        expected_state = {
            "allowed_atomic_outcomes": [
                {
                    "before": _oracle(observation, state, False),
                    "after": _oracle(observation, True, False),
                    "replay": "ACK",
                }
                for state in (False, True)
            ]
        }
    else:
        expected_state = {
            "before": expected,
            "after": _oracle(observation, True, recovered_gap),
            "replay": expected_replay,
        }

    def prepare(case: Path) -> None:
        (case / "scenario.json").write_text(json.dumps(scenario, sort_keys=True))
        (case / "launch-input.json").write_text(
            json.dumps(
                {
                    **provenance,
                    "scenario_sha256": _sha(case / "scenario.json"),
                },
                sort_keys=True,
            )
        )

    def boundary(case: Path, identity: dict[str, object]) -> None:
        if _launch_provenance(command, trusted_command=trusted_command) != provenance:
            raise ValueError("E_CRASH_CHILD_PROVENANCE")
        path = case / "boundary.json"
        if not path.is_file():
            raise RuntimeError("E_CRASH_BOUNDARY_MISSING")
        witness = json.loads(path.read_text())
        if key == "SQL-06":
            expected_fields = {
                "identity",
                "phase",
                "commit_armed",
                "operation",
                "target",
                "sqlite_path",
            }
            if (
                not isinstance(witness, dict)
                or set(witness) != expected_fields
                or witness["identity"] != identity
                or witness["phase"] != "during_commit"
                or witness["commit_armed"] is not True
                or witness["operation"] not in {"fsync", "fdatasync"}
                or witness["target"] not in {"rollback_journal", "database"}
                or not str(witness["sqlite_path"]).endswith(
                    ("run.sqlite3-journal", "run.sqlite3")
                )
            ):
                raise RuntimeError("E_CRASH_COMMIT_IO_WITNESS")
            (case / "prerequisite-state.json").write_text(
                json.dumps(witness, sort_keys=True)
            )
            return
        if (
            not isinstance(witness, dict)
            or set(witness)
            != {
                "identity",
                "phase",
                "received_observation_hash",
                "transport_address",
                "in_transaction",
                "tables",
                "ingest_result",
                "wire_ack",
            }
            or not isinstance(witness["tables"], dict)
            or set(witness["tables"]) != set(TABLES)
            or type(witness["in_transaction"]) is not bool
            or not isinstance(witness["transport_address"], list)
            or len(witness["transport_address"]) != 2
            or any(
                not isinstance(rows, list) or any(not isinstance(row, dict) for row in rows)
                for rows in witness["tables"].values()
            )
        ):
            raise RuntimeError("E_CRASH_BOUNDARY_SCHEMA")
        if (
            witness["identity"] != identity
            or witness["phase"] != phase
            or witness["received_observation_hash"] != scenario["delivery"]["content_hash"]
            or witness["transport_address"][0] != "127.0.0.1"
            or witness["in_transaction"] != (phase in BEFORE_STATEMENT)
        ):
            raise RuntimeError("E_CRASH_BOUNDARY_MISMATCH")
        tables = witness["tables"]
        # Separate reads see committed prerequisites, never the pending INSERTs.
        # The uncommitted witness belongs to the pinned child instrumentation.
        durable = read_restart_state(case / observation["discovery_run_id"])
        database = case / observation["discovery_run_id"] / "run.sqlite3"
        with closing(sqlite3.connect(database.resolve().as_uri() + "?mode=ro", uri=True)) as db:
            for name in TABLES:
                columns = {
                    item[0]
                    for item in db.execute(
                        f"SELECT * FROM {name} LIMIT 0"  # noqa: S608 -- fixed verified table allowlist
                    ).description
                }
                if any(set(row) != columns for row in tables[name]):
                    raise RuntimeError("E_CRASH_BOUNDARY_SCHEMA")
        baseline = (
            _oracle(observation, base_committed, late)
            if phase in BEFORE_STATEMENT
            else _oracle(observation, committed, gap_committed)
        )
        if _snapshot(durable) != baseline:
            raise RuntimeError("E_CRASH_BOUNDARY_DURABLE_STATE")
        (case / "prerequisite-state.json").write_text(json.dumps(durable, sort_keys=True))
        if phase in BEFORE_STATEMENT and witness["ingest_result"] is not None:
            raise RuntimeError("E_CRASH_ACK_BEFORE_COMMIT")
        if key in {"GAP-10", "LATE-01"} and witness["ingest_result"] != {
            "error": "E_INGEST_GAP" if key == "GAP-10" else "E_INGEST_GENERATION_CLOSED"
        }:
            raise RuntimeError("E_CRASH_INGEST_RESULT")
        if key == "SQL-07" and witness["ingest_result"] != {"ack": tables["ack_outbox"][0]}:
            raise RuntimeError("E_CRASH_INGEST_RESULT")
        if key.startswith("SQL") and key != "SQL-07":
            written = int(key[-2:])
            if [len(tables[name]) for name in CHAIN] != [int(i < written) for i in range(5)]:
                raise RuntimeError("E_CRASH_BOUNDARY_TRANSACTION_STATE")
        if is_gap and key != "GAP-10":
            stage = int(key[-2:])
            expected_counts = [int(stage >= n) for n in (1, 2, 3, 5, 7, 8)]
            expected_counts[-1] += 1  # Existing predecessor generation.
            controller = "SHOCKED_CLOSED" if stage >= 4 else "OPEN"
            generation = "QUARANTINED_GAP" if stage >= 6 else "ACTIVE"
            if (
                [len(tables[name]) for name in GAP_INSERTS] != expected_counts
                or tables["coherence_controllers"][0]["controller_state"] != controller
                or tables["stream_generations"][0]["generation_state"] != generation
            ):
                raise RuntimeError("E_CRASH_BOUNDARY_TRANSACTION_STATE")
        if key == "ACK-06":
            ack = witness["wire_ack"]
            if not isinstance(ack, dict) or ack.get("ack") != tables["ack_outbox"][0]:
                raise RuntimeError("E_CRASH_WIRE_ACK")

    recovery_runs: list[dict[str, Any]] = []

    def recover(case: Path, *, replay: bool = False) -> None:
        if _launch_provenance(command, trusted_command=trusted_command) != provenance:
            raise ValueError("E_CRASH_CHILD_PROVENANCE")
        suffix = "replay" if replay else "reopen"
        argv = [*command, "--recover", str(case), *(["--replay"] if replay else [])]
        (case / f"{suffix}-launch.json").write_text(
            json.dumps({**provenance, "argv": argv}, sort_keys=True)
        )
        with (
            (case / f"{suffix}.stdout").open("wb") as stdout,
            (case / f"{suffix}.stderr").open("wb") as stderr,
        ):
            completed = subprocess.run(  # noqa: S603 -- fixed local child and owned temporary directory
                argv,
                cwd=Path(__file__).resolve().parents[1],
                check=True,
                timeout=10,
                stdout=stdout,
                stderr=stderr,
            )
        recovery_runs.append(
            {
                "phase": suffix,
                "argv": argv,
                "exit": completed.returncode,
                "launch": case / f"{suffix}-launch.json",
                "stdout": case / f"{suffix}.stdout",
                "stderr": case / f"{suffix}.stderr",
            }
        )

    reader_runs: list[dict[str, Any]] = []

    def read_actual(case: Path, label: str) -> dict[str, Any]:
        run_dir = case / observation["discovery_run_id"]
        if reader_command is None:
            return read_restart_state(run_dir)
        reader_input = {
            "run_dir": str(run_dir.resolve()),
            "run_id": observation["discovery_run_id"],
            "case_id": entry["vector_id"],
            "checkpoint_id": entry["crash_checkpoint"],
            "phase": label,
        }
        input_path = case / f"reader-{label}-input.json"
        input_path.write_text(json.dumps(reader_input, sort_keys=True, separators=(",", ":")))
        argv = [*reader_command, str(run_dir), "--identity", str(input_path)]
        completed = subprocess.run(  # noqa: S603 -- fixed local read-only inspector
            argv,
            cwd=Path(__file__).resolve().parents[1],
            check=True,
            capture_output=True,
            text=True,
            timeout=10,
        )
        output = case / f"reader-{label}.json"
        output.write_text(completed.stdout)
        reader_runs.append(
            {
                "phase": label,
                "argv": argv,
                "exit": completed.returncode,
                "input": input_path,
                "artifact": output,
            }
        )
        envelope = cast(dict[str, Any], json.loads(completed.stdout))
        if envelope.get("identity") != reader_input or not isinstance(
            envelope.get("state"), dict
        ):
            raise ValueError("E_CRASH_READER_OUTPUT")
        return cast(dict[str, Any], envelope["state"])

    def actual(case: Path) -> dict[str, Any]:
        before = read_actual(case, "before")
        (case / "actual-state.json").write_text(json.dumps(before, sort_keys=True))
        recover(case, replay=True)
        recovery = json.loads((case / "recovery.json").read_text())
        after = read_actual(case, "after")
        if after != recovery["after"]:
            raise ValueError("E_CRASH_RECOVERY_OBSERVATION")
        replay = recovery["replay"]
        if "ack" in replay and replay["ack"] != after["tables"]["ack_outbox"][0]:
            raise ValueError("E_CRASH_RECOVERY_ACK")
        return {
            "before": _snapshot(before),
            "after": _snapshot(after),
            "replay": replay.get("error", "ACK"),
        }

    def compare(actual: dict[str, object], wanted: dict[str, object]) -> dict[str, object]:
        allowed = wanted.get("allowed_atomic_outcomes")
        if isinstance(allowed, list):
            if actual not in allowed:
                raise ValueError("E_RESTART_STATE_MISMATCH")
            return {"result": "PASS", "state": actual, "allowed_atomic_outcome": True}
        from tools.inspect_restart_state import inspect_restart_state

        return inspect_restart_state(actual, wanted)

    result = execute_crash_matrix(
        [{**entry, "expected_post_restart_state": expected_state}],
        command,
        workspace,
        state_reader=actual,
        prepare_case=prepare,
        recover_case=recover,
        validate_boundary=boundary,
        compare_state=compare,
    )
    for row in cast(list[dict[str, Any]], result["records"]):
        if (
            _launch_provenance(command, trusted_command=trusted_command) != provenance
            or row["command"][: len(command)] != command
        ):
            raise ValueError("E_CRASH_CHILD_PROVENANCE")
        case = Path(row["case_directory"])
        if json.loads((case / "launch-input.json").read_text())["scenario_sha256"] != _sha(
            case / "scenario.json"
        ):
            raise ValueError("E_CRASH_CHILD_PROVENANCE")
        root = Path(__file__).resolve().parents[1]
        row.update(
            input_sha256=_sha(case / "scenario.json"),
            actual_state_sha256=_sha(case / "actual-state.json"),
            actual_state_artifact=str(case / "actual-state.json"),
            recovery_sha256=_sha(case / "recovery.json"),
            boundary_sha256=_sha(case / "boundary.json"),
            expected_sha256=hashlib.sha256(
                json.dumps(expected_state, sort_keys=True).encode()
            ).hexdigest(),
            execution_kind="BACKEND_ONLY_PROCESS_CRASH",
            phase=phase,
            launch_provenance={**provenance, "argv": row["command"]},
            prerequisite_state_sha256=_sha(case / "prerequisite-state.json"),
            comparison_state_sha256=_sha(case / "comparison-state.json"),
            code_revision=subprocess.run(  # noqa: S603 -- read-only local Git identity
                ["git", "rev-parse", "HEAD"],  # noqa: S607 -- existing repository Git executable
                cwd=root,
                check=True,
                capture_output=True,
                text=True,
            ).stdout.strip(),
            source_sha256={
                name: _sha(root / name)
                for name in (
                    "tools/inspect_restart_state.py",
                    "tools/loopback_ack_crash_child.py",
                    "tools/run_loopback_ack_crash_matrix.py",
                    "tools/restart_state_reader.py",
                    "tools/sqlite_crash_child.py",
                    "tools/gap_coherence_crash_child.py",
                    "src/moj_discovery/store.py",
                    "src/moj_discovery/ingest.py",
                    "src/moj_discovery/canonical.py",
                    "schema-lock.json",
                    "uv.lock",
                    "vendor/hybrid-discovery-v6.3.6/sql/discovery-store-v1.sql",
                )
            },
            environment={"platform": platform.platform(), "python": sys.version},
        )
        if reader_command is not None:
            row.update(
                reader_runs=[
                    {"phase": item["phase"], "argv": item["argv"], "exit": item["exit"],
                     "input_path": str(item["input"].resolve()),
                     "input_sha256": _sha(item["input"]),
                     "path": str(item["artifact"].resolve()),
                     "sha256": _sha(item["artifact"])}
                    for item in reader_runs
                ],
                recovery_runs=[
                    {
                        "phase": item["phase"],
                        "argv": item["argv"],
                        "exit": item["exit"],
                        "launch_path": str(item["launch"].resolve()),
                        "launch_sha256": _sha(item["launch"]),
                        "stdout_path": str(item["stdout"].resolve()),
                        "stdout_sha256": _sha(item["stdout"]),
                        "stderr_path": str(item["stderr"].resolve()),
                        "stderr_sha256": _sha(item["stderr"]),
                    }
                    for item in recovery_runs
                ],
            )
        (case / "result.json").write_text(json.dumps(row, sort_keys=True))
    result.update(scope="BACKEND_ONLY", legacy_full_qualification="HOLD")
    return result


def run_family(
    pack: Path,
    workspace: Path,
    family: str,
    observation_input: dict[str, Any] | None,
) -> dict[str, Any]:
    entries = json.loads((pack / "docs/registries/crash-harness-registry.v1.json").read_text())[
        "entries"
    ]
    rows = []
    for entry in entries:
        if entry["harness"] != family:
            continue
        key = "-".join(entry["vector_id"].split("-")[:2])
        row: dict[str, Any] = {
            "vector_id": entry["vector_id"],
            "status": "NOT_IMPLEMENTED",
            "reason": "FULL_BROWSER_OR_LIFECYCLE_CONTRACT_MISSING",
        }
        if family == "WHOLE_RUN_DESTRUCTION":
            row["reason"] = "DESTRUCTION_OWNER_AND_AUTHORITY_NOT_IMPLEMENTED"
        elif family == "CHROME_INDEXEDDB" or key in {"ACK-01", "ACK-02", "ACK-03"}:
            row["reason"] = "REAL_EXTENSION_ACK_OR_SPOOL_NOT_IMPLEMENTED"
        elif key in {"ACK-04", "ACK-05"}:
            row["reason"] = "BACKEND_CONFIRMATION_OWNER_NOT_IMPLEMENTED"
        elif key == "CONFLICT-01":
            row["reason"] = "FULL_CONFLICT_PROCESS_EVIDENCE_NOT_IMPLEMENTED"
        elif key in {"SQL-06", "GAP-09"}:
            row["reason"] = "DURING_COMMIT_CHECKPOINT_NOT_EXPOSED"
        elif key == "LATE-01":
            row["reason"] = "LATE_HISTORY_REPAIR_NOT_IMPLEMENTED"
        if key in PHASES and observation_input is not None:
            result = run_backend_case(entry, observation_input, workspace)
            row.update(scoped_result=result["result"], scoped_evidence=result["records"][0])
        rows.append(row)
    return {
        "result": "HOLD",
        "legacy_full_qualification": "HOLD",
        "records": rows,
        "executed_vector_ids": [],
        "killed_child_count": sum("scoped_result" in row for row in rows),
    }


def run_loopback_ack_crash_matrix(
    pack: Path,
    workspace: Path,
    *,
    observation_input: dict[str, Any] | None = None,
    browser_binary: Path | None = None,
    include_mutations: bool = True,
) -> dict[str, Any]:
    from tools.run_indexeddb_crash_matrix import PACK, run_indexeddb_case

    registry_path = "docs/registries/crash-harness-registry.v1.json"
    entries = [
        row
        for row in json.loads((pack / registry_path).read_text())["entries"]
        if row["harness"] == "LOOPBACK_ACK"
    ]
    required = [
        row
        for row in json.loads((PACK / registry_path).read_text())["entries"]
        if row["harness"] == "LOOPBACK_ACK"
    ]
    if entries != required:
        raise ValueError("E_ACK_REQUIRED_CASES")
    if observation_input is not None:
        # Preserve the explicitly scoped legacy diagnostic API.
        return run_family(pack, workspace, "LOOPBACK_ACK", observation_input)
    records = [
        run_indexeddb_case(
            row,
            workspace / str(uuid4()),
            full=True,
            operation="deliver",
            browser_binary=browser_binary,
        )
        for row in entries
    ]
    from tools.owner_mutation_evidence import campaign

    mutations = campaign(entries, workspace / "mutations", records) if include_mutations else []
    return {
        "result": "PASS"
        if all(row["result"] == "PASS" for row in records)
        else "BLOCKED_ENVIRONMENT",
        "records": records,
        "mutation_results": mutations,
        "executed_vector_ids": [row["case_id"] for row in records if row["result"] == "PASS"],
        "killed_child_count": sum(
            row.get("termination", {}).get("method") not in {None, "NONE"} for row in records
        ),
        "legacy_full_qualification": "HOLD",
        "production_authority": "NONE",
    }


def run_browser_handshake(
    entry: dict[str, Any],
    case: Path,
    socket: str,
    request: dict[str, Any],
    identity: dict[str, Any],
    binding: dict[str, Any],
    extension: Path,
    binary: Path,
    observations: list[dict[str, Any]],
    *,
    browser_process: subprocess.Popen[bytes],
    profile: Path,
    sentinel: str,
    initial_sentinel: dict[str, Any],
    input_rejection: bool = False,
) -> dict[str, Any]:
    """Use the existing browser owner and independent SQLite reader for one full case."""
    from tools.inspect_restart_state import _checkpoint, _kill_owned_child
    from tools.qualify_chrome_indexeddb import _browser_process_observation
    from tools.run_indexeddb_crash_matrix import _call

    root = Path(__file__).resolve().parents[1]
    inputs: dict[str, Any] = {}
    artifacts: dict[str, Any] = {}

    def save(name: str, value: Any, *, is_input: bool = False) -> dict[str, str]:
        path = case / (name + ".json")
        path.write_text(json.dumps(value, sort_keys=True, separators=(",", ":")))
        descriptor = {"path": str(path.resolve()), "sha256": _sha(path)}
        (inputs if is_input else artifacts)[name] = descriptor
        return descriptor

    loaded_assets = {
        name: {"path": str((extension / name).resolve()), "sha256": _sha(extension / name)}
        for name in ("manifest.json", "repair-probe.html")
    }
    marker = profile / "BH_R05_PROFILE_ID"
    module_hashes_before = {
        str(path.relative_to(extension)): _sha(path)
        for path in sorted(extension.rglob("*.js"))
    }
    marker_artifact = {"path": str(marker.resolve()), "sha256": _sha(marker)}
    profile_before = save(
        "profile-before",
        {
            "profile_path": str(profile.resolve()),
            "marker": marker.read_text(),
            "sentinel": initial_sentinel,
        },
    )
    browser_before = save("browser-process-before", _browser_process_observation(browser_process))
    launch = save(
        "browser-launch",
        {
            "argv": browser_process.args,
            "pid": browser_process.pid,
            "pgid": os.getpgid(browser_process.pid),
            "profile_path": str(profile.resolve()),
            "extension_path": str(extension.resolve()),
            "origin": identity["origin"],
            "executable": str(binary),
            "sha256": _sha(binary),
        },
    )

    processes: list[dict[str, Any]] = []
    owned: subprocess.Popen[bytes] | None = None
    child_identity = {
        key: value for key, value in request["identity"].items() if key not in {"profile_id", "pid"}
    }

    def start(restart: bool) -> dict[str, Any]:
        nonlocal owned
        config = {
            "identity": child_identity,
            "observation": observations[0],
            "origin": identity["origin"],
            "token": token_hex(32),
            "restart": restart,
        }
        descriptor = save(f"server-input-{int(restart)}", config, is_input=True)
        command = [*_trusted_command(), "--browser-server", descriptor["path"]]
        with (case / f"server-{int(restart)}.log").open("wb") as log:
            owned = subprocess.Popen(  # noqa: S603 -- owned isolated local synthetic receiver
                command,
                cwd=root,
                stdout=log,
                stderr=log,
                start_new_session=True,
            )
        ready = case / f"server-{int(restart)}.json"
        deadline = monotonic() + 10
        while not ready.is_file() and monotonic() < deadline:
            if owned.poll() is not None:
                raise RuntimeError("E_ACK_SERVER_FAILED")
            sleep(0.02)
        if not ready.is_file():
            raise RuntimeError("E_ACK_SERVER_TIMEOUT")
        actual = json.loads(ready.read_text())
        if (
            actual["identity"] != {**child_identity, "pid": owned.pid}
            or actual["address"][0] != "127.0.0.1"
        ):
            raise ValueError("E_ACK_SERVER_IDENTITY")
        from tools.run_gap_coherence_crash_matrix import _proc_observation
        observed, raw = _proc_observation(owned, case / f"server-process-{int(restart)}.json")
        processes.append(
            {
                "observed": observed, "raw_process": raw,
                "argv": command,
                "pid": owned.pid,
                "pgid": os.getpgid(owned.pid),
                "identity": actual["identity"],
                "ready": save(f"server-ready-{int(restart)}", actual),
                "provenance": _launch_provenance(_trusted_command()),
            }
        )
        return {
            "endpoint": "http://127.0.0.1:" + str(actual["address"][1]),
            "token": config["token"],
        }

    def stop(kill: bool) -> None:
        if owned is None or owned.poll() is not None or os.getpgid(owned.pid) != owned.pid:
            raise RuntimeError("E_ACK_SERVER_NOT_OWNED")
        if kill:
            if not _kill_owned_child(owned):
                raise RuntimeError("E_ACK_SERVER_NOT_KILLED")
        else:
            os.killpg(owned.pid, signal.SIGTERM)
        code = owned.wait(timeout=5)
        if code != (-signal.SIGKILL if kill else -signal.SIGTERM):
            raise RuntimeError("E_ACK_SERVER_EXIT")
        processes[-1].update(
            exit=code,
            mechanism="POSIX_OWNED_PROCESS_GROUP_SIGKILL"
            if kill
            else "POSIX_OWNED_PROCESS_GROUP_SIGTERM_CLEANUP",
        )

    reader_runs: list[dict[str, Any]] = []

    def read_backend(phase: str) -> dict[str, Any]:
        run_dir = case / identity["run_id"]
        reader_input = {
            "run_dir": str(run_dir.resolve()),
            "run_id": identity["run_id"],
            "case_id": entry["vector_id"],
            "checkpoint_id": entry["crash_checkpoint"],
            "phase": phase,
        }
        descriptor = save("reader-" + phase, reader_input, is_input=True)
        command = [
            str(Path(sys.executable).absolute()),
            "-I",
            str(root / "tools/restart_state_reader.py"),
            str(run_dir.resolve()),
            "--identity",
            descriptor["path"],
        ]
        result = subprocess.run(  # noqa: S603 -- fixed independent read-only local reader
            command,
            cwd=root,
            check=True,
            capture_output=True,
            text=True,
            timeout=10,
        )
        output = json.loads(result.stdout)
        if output["identity"] != reader_input:
            raise ValueError("E_ACK_READER_IDENTITY")
        artifact = save("reader-output-" + phase, output)
        reader_runs.append(
            {"phase": phase, "argv": command, "exit": result.returncode, "artifact": artifact}
        )
        return cast(dict[str, Any], output["state"])

    def read_browser(phase: str) -> dict[str, Any]:
        value = {
            "identity": request["identity"],
            "options": request["options"],
            "operation": "read",
            "observations": [],
        }
        save("browser-reader-" + phase, value, is_input=True)
        worker_id = str(uuid4())
        result = _call(socket, "startWorker", worker_id, value)
        _call(socket, "terminateWorker", worker_id)
        if result.get("worker_id") != worker_id:
            raise ValueError("E_ACK_READER_WORKER")
        save("browser-" + phase, result)
        return result

    try:
        transport = start(False)
        request = {**request, "transport": transport}
        save("worker", request, is_input=True)
        if input_rejection:
            from tools.owner_mutation_evidence import browser_input

            return browser_input(
                entry, case, socket, request, identity, binding, extension, binary, observations,
                browser_process, profile, sentinel, inputs, artifacts, processes, reader_runs,
                loaded_assets, marker_artifact, profile_before, browser_before, launch,
                save, read_browser, read_backend, stop,
            )
        worker_id = str(uuid4())
        _call(socket, "beginWorker", worker_id, request)
        action = entry["kill_action"]
        if action == "SIGKILL_BACKEND_CHILD":
            assert owned is not None
            backend_identity = {**child_identity, "pid": owned.pid}
            try:
                _checkpoint(
                    case / "backend-checkpoint.json", owned, backend_identity, entry["vector_id"]
                )
            except RuntimeError:
                _call(socket, "waitWorker")
                raise
            checkpoint = json.loads((case / "backend-checkpoint.json").read_text())
            save("backend-boundary", json.loads((case / "backend-boundary.json").read_text()))
            stop(True)
            termination = {
                "method": "POSIX_OWNED_PROCESS_GROUP_SIGKILL",
                "pid": owned.pid,
                "returncode": -signal.SIGKILL,
            }
        else:
            checkpoint = _call(socket, "waitWorker")
            if (
                any(checkpoint.get(key) != value for key, value in identity.items())
                or checkpoint.get("worker_id") != worker_id
                or checkpoint.get("boundary") != entry["crash_checkpoint"]
            ):
                raise ValueError("E_ACK_WORKER_CHECKPOINT")
            termination = (
                {"method": "Worker.terminate", "worker_id": worker_id}
                if action != "NONE"
                else {"method": "NONE"}
            )
        _call(socket, "terminateWorker", worker_id)
        if action != "SIGKILL_BACKEND_CHILD":
            stop(False)
        save("checkpoint", checkpoint)
        transport = start(True)
        actual = read_browser("before")
        backend_before = read_backend("before")
        recovery = {
            **request,
            "operation": "recover",
            "transport": transport,
            "observations": request["observations"][:1] if not actual["entries"] else [],
        }
        save("recovery-worker", recovery, is_input=True)
        recovery_id = str(uuid4())
        recovery_result = _call(socket, "startWorker", recovery_id, recovery)
        _call(socket, "terminateWorker", recovery_id)
        save("recovery-worker-output", recovery_result)
        browser_after = read_browser("after")
        backend_after = read_backend("after")
        stop(False)
        profile_after = save(
            "profile-after",
            {
                "profile_path": str(profile.resolve()),
                "marker": marker.read_text(),
                "sentinel": _call(socket, "readSentinel", identity["profile_id"]),
            },
        )
        browser_after_process = save(
            "browser-process-after", _browser_process_observation(browser_process)
        )
        save("backend-before", backend_before)
        save("backend-after", backend_after)
        save("expected", entry["expected_post_restart_state"])
        wires = {
            path.name: save(path.stem, json.loads(path.read_text()))
            for path in sorted(case.glob("wire-*.json"))
        }
        module_hashes_after = {
            str(path.relative_to(extension)): _sha(path)
            for path in sorted(extension.rglob("*.js"))
        }
        execution_binding = {
            "before": module_hashes_before,
            "after": module_hashes_after,
        }
        execution_binding_artifact = save("typescript-execution-binding", execution_binding)
        row = {
            "vector_id": entry["vector_id"],
            "case_id": entry["vector_id"],
            "case_directory": str(case.resolve()),
            "status": "PASS",
            "result": "PASS",
            "executed": True,
            "launch_attempted": True,
            "qualification_scope": "BROWSER_LOOPBACK_ACK",
            "execution_kind": "BROWSER_LOOPBACK_ACK",
            "legacy_full_qualification": "HOLD",
            "identity": identity,
            "worker_id": worker_id,
            "checkpoint": checkpoint,
            "termination": termination,
            "actual": actual,
            "backend_before": backend_before,
            "browser_after": browser_after,
            "backend_after": backend_after,
            "observations": observations,
            "expected": entry["expected_post_restart_state"],
            "observed_error": None,
            "comparison": {"matched": True},
            "evidence_binding": binding,
            "revision": binding["revision"],
            "environment": binding["environment"],
            "inputs": inputs,
            "artifacts": artifacts,
            "wire_artifacts": wires,
            "reader_runs": reader_runs,
            "backend_processes": processes,
            "browser": {"executable": str(binary), "sha256": _sha(binary)},
            "loaded_assets": loaded_assets,
            "profile_readbacks": {
                "before": profile_before,
                "after": profile_after,
                "marker": marker_artifact,
                "sentinel": sentinel,
            },
            "browser_provenance": {
                "launch": launch,
                "before": browser_before,
                "after": browser_after_process,
            },
            "module_hashes": module_hashes_after,
            "typescript_execution_binding": execution_binding,
            "typescript_execution_binding_artifact": execution_binding_artifact,
        }
        from tools.verify_repair_evidence import _verify_browser_ack

        _verify_browser_ack(row, binding, terminal=False)
        terminal_path = case / "terminal-result.json"
        terminal_path.write_text(json.dumps(row, sort_keys=True, separators=(",", ":")))
        row["terminal_artifact"] = {
            "path": str(terminal_path.resolve()),
            "sha256": _sha(terminal_path),
        }
        return row
    finally:
        if owned is not None and owned.poll() is None:
            _kill_owned_child(owned)
            owned.wait(timeout=5)"""Supplemental native Ingestor/COMMIT-I/O boundaries; no physical loss proof."""

from __future__ import annotations

import json
import subprocess
import tomllib
import zipfile
from pathlib import Path
from typing import TYPE_CHECKING, Any
from uuid import uuid4

from tools.native_ingestor_probe import COMMIT_PHASE, PHASES, dependency_payload
from tools.run_environment_qualification import (
    NATIVE,
    WINDOWS_PARENT,
    _verify_native_observation,
    artifact,
    checked,
    localpath,
    save,
    winpath,
)
from tools.run_indexeddb_crash_matrix import ROOT, _observations
from tools.verify_repair_evidence import _validate_sqlite_state, capture_binding

if TYPE_CHECKING:
    from tools.retained_artifact_io import RetainedArtifactIO

DEPENDENCIES = WINDOWS_PARENT / "native-dependency-closure-ef63da26-f87f-45ab-af76-dd2b9ef02c08"
SCRIPT = ROOT / "tools/native_ingestor_probe.py"
MODES = ("setup", "write", "reopen", "read", "replay", "replay-again", "final-read")


def dependency_binding() -> dict[str, Any]:
    files = dependency_payload(DEPENDENCIES)
    preparation = DEPENDENCIES / "preparation.json"
    prepared = json.loads(preparation.read_text())
    lock = artifact(ROOT / "uv.lock")
    if lock["sha256"] != prepared["lock_sha256"]:
        raise ValueError("E_NATIVE_DEPENDENCY_LOCK")
    packages = {
        row["name"]: row for row in tomllib.loads((ROOT / "uv.lock").read_text())["package"]
    }
    wheels = []
    for wheel in prepared["wheels"]:
        source = Path(wheel["source"])
        descriptor = artifact(source)
        package = packages[wheel["name"]]
        if (
            descriptor["sha256"] != wheel["sha256"]
            or package["version"] != wheel["version"]
            or wheel["locked_wheel"] not in package["wheels"]
            or wheel["locked_wheel"]["hash"] != "sha256:" + descriptor["sha256"]
        ):
            raise ValueError("E_NATIVE_DEPENDENCY_WHEEL")
        with zipfile.ZipFile(source) as archive:
            for member in archive.infolist():
                if (
                    not member.is_dir()
                    and archive.read(member)
                    != (DEPENDENCIES / "site-packages" / member.filename).read_bytes()
                ):
                    raise ValueError("E_NATIVE_DEPENDENCY_WHEEL_PAYLOAD")
        wheels.append(descriptor)
    for item in prepared["rfc8785"]["files"]:
        copied = (DEPENDENCIES / "site-packages" / item["path"]).read_bytes()
        if copied != Path(item["independent_source"]).read_bytes():
            raise ValueError("E_NATIVE_DEPENDENCY_RFC_PAYLOAD")
        if (
            not item["path"].endswith("/RECORD")
            and copied != Path(item["installed_source"]).read_bytes()
        ):
            raise ValueError("E_NATIVE_DEPENDENCY_RFC_PAYLOAD")
    return {
        "preparation": artifact(preparation),
        "files": files,
        "wheels": wheels,
        "lock": lock,
        "rfc_provenance": prepared["rfc8785"]["provenance"],
        "native_pyd": artifact(DEPENDENCIES / "site-packages/rpds/rpds.cp312-win_amd64.pyd"),
    }


def verify_loaded_dependencies(value: dict[str, Any], dependency: dict[str, Any]) -> None:
    imported = json.loads((DEPENDENCIES / "native-import.json").read_text())
    if (
        artifact(DEPENDENCIES / "native-import.json")["sha256"]
        != "1a431a828750baf69c4919a7ae185ea1f282cb631187a61c8e6a0f6f6fbce2f5"
    ):
        raise ValueError("E_NATIVE_DEPENDENCY_IMPORT_REFERENCE")
    expected = {
        "modules": {
            item["distribution"]: {key: item[key] for key in ("path", "sha256", "version")}
            for item in imported["dependencies"]
        },
        "native_rpds": imported["native_rpds"],
    }
    if value != expected or value["native_rpds"]["sha256"] != dependency["native_pyd"]["sha256"]:
        raise ValueError("E_NATIVE_DEPENDENCY_IMPORT")


def _execute_native_ingestor(workspace: Path, *, commit_io: str | None = None) -> dict[str, Any]:
    workspace.mkdir(parents=True, exist_ok=True)
    dependency = dependency_binding()
    owned = WINDOWS_PARENT / ("native-ingestor-" + str(uuid4()))
    owned.mkdir(exist_ok=False)
    delivery = _observations(str(uuid4()))[0]
    config = {
        "workspace": winpath(owned),
        "root": winpath(ROOT),
        "dependency_root": winpath(DEPENDENCIES),
        "delivery": delivery,
    }
    if commit_io is not None:
        config["commit_io"] = commit_io
    input_path = workspace / "owner-input.json"
    save(input_path, config)
    command = [str(NATIVE), "-I", "-B", winpath(SCRIPT), "owner", winpath(input_path)]
    process = subprocess.run(command, capture_output=True, timeout=180)  # noqa: S603
    (workspace / "owner.stdout").write_bytes(process.stdout)
    (workspace / "owner.stderr").write_bytes(process.stderr)
    if process.returncode or process.stderr:
        raise ValueError("E_NATIVE_INGESTOR_OWNER:" + process.stderr.decode())
    report = {
        **json.loads(process.stdout),
        "result": "PASS",
        "binding": capture_binding(),
        "dependency": dependency,
        "input": artifact(input_path),
        "config": config,
        "command": command,
        "exit": process.returncode,
        "stdout": artifact(workspace / "owner.stdout"),
        "stderr": artifact(workspace / "owner.stderr"),
        "scope": "NATIVE_SQLITE_COMMIT_IO_ONLY"
        if commit_io is not None
        else "NATIVE_INGESTOR_TEST_OWNER_BOUNDARIES_ONLY",
        "native_sql06": "PASS" if commit_io is not None else "HOLD_UNSUPPORTED",
        "physical_power_loss": "HOLD_NOT_EXECUTED",
        "tcp_ack_publication": "NOT_EXECUTED",
        "production_authority": "NONE",
    }
    try:
        verify_native_ingestor(report)
    except ValueError:
        save(workspace / "native-ingestor-candidate.json", {**report, "result": "UNVERIFIED"})
        raise
    save(workspace / "native-ingestor-terminal.json", report)
    return report


def run_native_ingestor(workspace: Path) -> dict[str, Any]:
    return _execute_native_ingestor(workspace)


def run_native_commit_io(workspace: Path, *, mode: str = "armed") -> dict[str, Any]:
    return _execute_native_ingestor(workspace, commit_io=mode)


def verify_native_commit_io(
    report: dict[str, Any], *, artifacts: RetainedArtifactIO | None = None
) -> None:
    verify_native_ingestor(report, artifacts=artifacts)
    if report["native_sql06"] != "PASS" or report["scope"] != "NATIVE_SQLITE_COMMIT_IO_ONLY":
        raise ValueError("E_NATIVE_COMMIT_IO_CALLBACK")


def verify_native_ingestor(
    report: dict[str, Any], *, artifacts: RetainedArtifactIO | None = None
) -> None:
    def retained(descriptor: dict[str, str]) -> bytes:
        boundary = artifacts.recorded_boundary(descriptor["path"]) if artifacts else None
        return checked(descriptor, artifacts=artifacts, recorded_boundary=boundary)

    try:
        io = "commit_io" in report["config"]
        if (
            report["result"] != "PASS"
            or report["binding"] != capture_binding()
            or report["dependency"] != dependency_binding()
            or report["exit"] != 0
            or retained(report["stderr"])
            or report["scope"]
            != (
                "NATIVE_SQLITE_COMMIT_IO_ONLY"
                if io
                else "NATIVE_INGESTOR_TEST_OWNER_BOUNDARIES_ONLY"
            )
            or report["native_sql06"] != ("PASS" if io else "HOLD_UNSUPPORTED")
            or report["physical_power_loss"] != "HOLD_NOT_EXECUTED"
            or report["tcp_ack_publication"] != "NOT_EXECUTED"
            or report["production_authority"] != "NONE"
        ):
            raise ValueError("binding")
        raw = json.loads(retained(report["stdout"]))
        if set(raw) != {
            "cases",
            "controller",
            "system",
            "python_version",
            "runtime_files",
        } or raw != {key: report[key] for key in raw}:
            raise ValueError("raw owner")
        runtime = [
            NATIVE,
            NATIVE.parent / "python312.dll",
            NATIVE.parent / "DLLs/_sqlite3.pyd",
            NATIVE.parent / "DLLs/sqlite3.dll",
        ]
        if report["system"] != "nt" or not report["python_version"].startswith("3.12.14 "):
            raise ValueError("native runtime")
        if len(report["runtime_files"]) != len(runtime):
            raise ValueError("native runtime files")
        for descriptor, path in zip(report["runtime_files"], runtime, strict=True):
            if localpath(descriptor["path"]) != path or checked(descriptor) != path.read_bytes():
                raise ValueError("native runtime files")
        cfg = json.loads(retained(report["input"]))
        if cfg != report["config"] or set(cfg) != {
            "workspace",
            "root",
            "dependency_root",
            "delivery",
        } | ({"commit_io"} if io else set()):
            raise ValueError("input")
        if io and cfg["commit_io"] not in {"armed", "bypass", "unarmed", "postcommit"}:
            raise ValueError("E_NATIVE_COMMIT_IO_MODE")
        from moj_discovery.canonical import verify_canonical_content_hash
        from moj_discovery.schema_registry import validate_artifact
        from moj_discovery.store import VENDOR

        delivery = cfg["delivery"]
        validate_artifact(
            delivery, "raw-observation.schema.json", bootstrap_only=True, vendor=VENDOR
        )
        verify_canonical_content_hash(
            "RawObservation",
            delivery,
            delivery["content_hash"],
            registry_path=VENDOR / "registries/canonical-hash-domains.v1.json",
        )
        run_id = delivery["discovery_run_id"]
        if delivery != _observations(run_id)[0]:
            raise ValueError("ordinary delivery")
        owned = localpath(cfg["workspace"])
        if owned.parent != WINDOWS_PARENT or not owned.name.startswith("native-ingestor-"):
            raise ValueError("owned workspace")
        if cfg["root"] != winpath(ROOT) or cfg["dependency_root"] != winpath(DEPENDENCIES):
            raise ValueError("input paths")
        command = [
            str(NATIVE),
            "-I",
            "-B",
            winpath(SCRIPT),
            "owner",
            winpath(Path(report["input"]["path"])),
        ]
        if report["command"] != command:
            raise ValueError("command")
        controller_identity = _verify_native_observation(
            report["controller"],
            [winpath(NATIVE), *command[1:]],
            report["controller"]["cim"]["ParentProcessId"],
            wsl_entry=True,
        )
        phases = (COMMIT_PHASE,) if io else PHASES
        if [row["case_id"] for row in report["cases"]] != list(phases):
            raise ValueError("case set")
        identities = {controller_identity}
        for ordinal, row in enumerate(report["cases"]):
            phase = phases[ordinal]
            committed_after = ordinal if not io else int(cfg["commit_io"] != "armed")
            case = owned / phase
            identity = {"run_id": run_id, "case_id": phase, "checkpoint_id": phase}
            base = {
                "root": cfg["root"],
                "dependency_root": cfg["dependency_root"],
                "run_dir": winpath(case / run_id),
                "identity": identity,
            }
            if set(row["inputs"]) != set(MODES):
                raise ValueError("inputs")
            for mode in MODES:
                value = {
                    **base,
                    **(
                        {"delivery": delivery}
                        if mode in {"setup", "write", "replay", "replay-again"}
                        else {}
                    ),
                }
                if io and mode == "write":
                    value["commit_io"] = cfg["commit_io"]
                item = row["inputs"][mode]
                if (
                    item["value"] != value
                    or json.loads(retained(item["artifact"])) != value
                    or localpath(item["artifact"]["path"]) != case / f"{mode}.input.json"
                ):
                    raise ValueError("oracle-free child input")
            if row["writer"] != row["writer_start"]:
                raise ValueError("writer replacement")
            writer_identity = _verify_native_observation(
                row["writer"],
                [
                    winpath(NATIVE),
                    "-I",
                    "-B",
                    winpath(SCRIPT),
                    "write",
                    winpath(case / "write.input.json"),
                ],
                report["controller"]["pid"],
            )
            identities.add(writer_identity)
            if row["termination"] != {
                "mechanism": "WINDOWS_TERMINATE_PROCESS_OWNED_HANDLE",
                "exit": 1,
                "pid": row["writer"]["pid"],
                "graceful": False,
            }:
                raise ValueError("termination")
            for key, filename in [
                ("writer_stdout", "write.stdout"),
                ("writer_stderr", "write.stderr"),
            ]:
                if localpath(row[key]["path"]) != case / filename or retained(row[key]):
                    raise ValueError("writer output")
            checkpoint = row["checkpoint"]
            if (
                checkpoint != json.loads(retained(row["checkpoint_artifact"]))
                or localpath(row["checkpoint_artifact"]["path"]) != case / "checkpoint.json"
                or set(checkpoint)
                != {
                    "identity",
                    "in_transaction",
                    "tables",
                    "ingest_ack",
                    "owner_ack_published",
                    "loaded_dependencies",
                }
                | ({"commit_io"} if io else set())
                or checkpoint["identity"] != {**identity, "pid": row["writer"]["pid"]}
                or checkpoint["in_transaction"] != (committed_after == 0)
                or checkpoint["owner_ack_published"] is not False
            ):
                raise ValueError("checkpoint")
            verify_loaded_dependencies(checkpoint["loaded_dependencies"], report["dependency"])
            names = ["before", "reopened", "after", "replayed", "replayed_again", "final"]
            if [process["mode"] for process in row["processes"]] != [
                mode for mode in MODES if mode != "write"
            ]:
                raise ValueError("reader set")
            for name, process in zip(names, row["processes"], strict=True):
                mode = process["mode"]
                process_identity = _verify_native_observation(
                    process["observed"],
                    [
                        winpath(NATIVE),
                        "-I",
                        "-B",
                        winpath(SCRIPT),
                        mode,
                        winpath(case / f"{mode}.input.json"),
                    ],
                    report["controller"]["pid"],
                )
                identities.add(process_identity)
                value = process["value"]
                if (
                    process["exit"] != 0
                    or retained(process["stderr"])
                    or localpath(process["stdout"]["path"]) != case / f"{mode}.stdout"
                    or localpath(process["stderr"]["path"]) != case / f"{mode}.stderr"
                    or value != json.loads(retained(process["stdout"]))
                    or set(value) != {"pid", "identity", "state", "ack", "loaded_dependencies"}
                    or value["pid"] != process["observed"]["pid"]
                    or value["identity"] != identity
                    or value["state"] != row[name]
                ):
                    raise ValueError("reader success")
                verify_loaded_dependencies(value["loaded_dependencies"], report["dependency"])
                committed = (
                    0
                    if name == "before"
                    else committed_after
                    if name in {"reopened", "after"}
                    else 1
                )
                _validate_sqlite_state(row[name], {"observation": delivery}, committed)
                expected_ack = (
                    row[name]["tables"]["ack_outbox"][0]
                    if mode in {"replay", "replay-again"}
                    else None
                )
                if value["ack"] != expected_ack:
                    raise ValueError("ack")
            _validate_sqlite_state(
                {**row["before"], "tables": checkpoint["tables"]}, {"observation": delivery}, 1
            )
            if (
                checkpoint["ingest_ack"]
                != (None if committed_after == 0 else row["after"]["tables"]["ack_outbox"][0])
                or row["after"] != row["reopened"]
                or row["replayed"] != row["replayed_again"]
                or row["replayed_again"] != row["final"]
                or (committed_after == 0 and row["after"] != row["before"])
                or (committed_after == 1 and row["after"] != row["replayed"])
            ):
                raise ValueError("atomic/replay state")
        if len(identities) != 1 + 7 * len(phases):
            raise ValueError("independent process identity")
        if io:
            from tools.native_sqlite_commit_io import verify_commit_callback

            verify_commit_callback(
                report["cases"][0],
                owned / COMMIT_PHASE,
                cfg["commit_io"],
                artifacts=artifacts,
            )
    except (ValueError, KeyError, TypeError, OSError) as error:
        raise ValueError("E_NATIVE_INGESTOR_EVIDENCE") from error"""Execute exact offline cases in owned workers; compare actual artifacts in the parent."""

# ruff: noqa: E402
import argparse
import json
import signal
import subprocess
import sys
from pathlib import Path
from time import monotonic
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT), str(ROOT / "src")]
from tools.offline_harness import SliceHarness
from tools.offline_results import artifacts, inventory, reference

META = {"OFF-20", "OFF-21", "OFF-22", "OFF-25"}


def observed_case(case: str, root: Path) -> dict[str, Any]:
    if case in META:
        from tools.offline_meta import check_meta
        from tools.verify_offline_slice import verify_offline_slice

        return check_meta(case, root, verify_offline_slice)
    from tools.offline_oracle import assert_case

    return assert_case(case, root / case / "run")


def run_required_cases(
    output: Path, browser_binary: Path, case_ids: list[str] | None = None
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    from tools.run_offline_slice import write_result

    selected = case_ids or [row["case_id"] for row in inventory()]
    records, observations = [], []
    commands = output / "commands"
    commands.mkdir()
    expected = {row["case_id"]: row["expected_behavior"] for row in inventory()}
    for case in selected:
        command = [
            sys.executable,
            str(ROOT / "tools/run_offline_faults.py"),
            "--case",
            case,
            "--output",
            str(output),
            "--browser-binary",
            str(browser_binary),
        ]
        with (
            (commands / (case + ".stdout")).open("xb") as out,
            (commands / (case + ".stderr")).open("xb") as err,
        ):
            started = monotonic()
            process = subprocess.Popen(  # noqa: S603 -- fixed owned worker, no shell
                command, cwd=ROOT, stdout=out, stderr=err
            )
            try:
                code = process.wait(timeout=120 if case == "OFF-19" else 30)
            except subprocess.TimeoutExpired:
                process.terminate()
                try:
                    process.wait(timeout=45)
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.wait()
                    raise RuntimeError("E_OFFLINE_OWNED_CLEANUP_TIMEOUT") from None
                code = process.returncode
        (commands / (case + ".json")).write_text(
            json.dumps(
                {
                    "command": command,
                    "exit": code,
                    "pid": process.pid,
                    "elapsed_seconds": monotonic() - started,
                }
            )
        )
        status, reason = "FAIL", "E_OFFLINE_CASE_EXECUTION"
        observed = {"case_id": case, "reason": reason}
        if code == 0:
            try:
                observed = observed_case(case, output)
            except Exception:
                reason = "E_OFFLINE_ORACLE"
            else:
                status, reason = "PASS", "VERIFIED_OBSERVATIONS"
        refs = artifacts(output, case)
        refs.extend(
            reference(commands / (case + suffix), output)
            for suffix in [".stdout", ".stderr", ".json"]
        )
        if case in {"OFF-20", "OFF-22", "OFF-25"}:
            refs.append(reference(output / "reference.json", output))
        if case == "OFF-22":
            refs.extend(
                reference(path, output) for path in sorted(output.glob("negative-OFF-22-*.json"))
            )
        records.append(
            {
                "case_id": case,
                "status": status,
                "executed": True,
                "expected_behavior": expected[case],
                "actual_code": "OBSERVED_CASE_PASS" if status == "PASS" else reason,
                "command_exit": code,
                "artifacts": refs,
                "reason_code": reason,
            }
        )
        observations.append(observed)
        print(json.dumps({"case_id": case, "status": status, "command_exit": code}), flush=True)
        if case == "OFF-01" and status == "PASS":
            write_result(
                output,
                "single-stream",
                records[:1],
                observations[:1],
                name="reference.json",
                diagnostic_name="reference-diagnostic.html",
            )
    return records, observations


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--case", required=True)
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument("--browser-binary", required=True, type=Path)
    args = parser.parse_args()

    def terminate(_signum: int, _frame: Any) -> None:
        raise SystemExit(143)

    signal.signal(signal.SIGTERM, terminate)
    try:
        if args.case in META:
            from tools.offline_meta import run_meta
            from tools.verify_offline_slice import verify_offline_slice

            run_meta(args.case, args.output, verify_offline_slice)
        else:
            SliceHarness(args.output, args.browser_binary).run_case(args.case)
    except Exception:
        print("E_OFFLINE_CASE_EXECUTION", file=sys.stderr)
        return 1
    print(json.dumps({"case_id": args.case, "execution": "FINISHED"}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())"""Run a loopback receiver; ephemeral credentials arrive only on private stdin."""

# ruff: noqa: E402
import argparse
import asyncio
import os
import signal
import sys
from pathlib import Path
from typing import Any
from uuid import UUID

from websockets.asyncio.server import ServerConnection

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT), str(ROOT / "src")]

from moj_discovery.canonical import parse_strict_json
from moj_discovery.input_journal import InputJournal
from moj_discovery.offline_faults import WriteDeniedStore
from moj_discovery.offline_receiver import serve_offline


async def run(run_dir: Path, fault: str | None = None) -> None:
    journal = InputJournal(run_dir)
    journal.reconcile(journal.store)
    if fault in {"AFTER_RECEIVED", "AFTER_APPLY"}:

        def observer(stage: str, index: int) -> None:
            if stage == fault and index == 1:
                import rfc8785

                with (run_dir / "checkpoint.json").open("xb") as output:
                    output.write(
                        rfc8785.dumps(
                            {
                                "stage": stage,
                                "receive_index": index,
                                "pid": os.getpid(),
                                "run_id": journal.context["run_id"],
                            }
                        )
                    )
                    output.flush()
                    os.fsync(output.fileno())
                os.kill(os.getpid(), signal.SIGSTOP)

        journal.observer = observer
    if fault == "SQLITE_DENY_THIRD":
        journal.store = WriteDeniedStore(journal.store.db_path, run_dir / "sqlite-faults.jsonl")
    keys: dict[str, bytes] = {}
    receiver = await serve_offline(journal.context, keys.get, journal.store, journal)
    if fault in {"DROP_ACK", "FAKE_ACK"}:
        used = False

        async def before_send(socket: ServerConnection, kind: str, body: dict[str, Any]) -> bool:
            nonlocal used
            if kind == "ACK" and not used:
                used = True
                import rfc8785

                (run_dir / "wire-fault.json").write_bytes(
                    rfc8785.dumps(
                        {
                            "fault": fault,
                            "run_id": journal.context["run_id"],
                            "pid": os.getpid(),
                            "sequence": body["highest_contiguous_sequence"],
                        }
                    )
                )
                if fault == "DROP_ACK":
                    await socket.close(1000, "OFFLINE_ACK_LOSS")
                    return False
                body["cursor_hash"] = "0" * 64
            return True

        receiver.before_send = before_send
    try:
        print('{"status":"LISTENING","pid":' + str(os.getpid()) + "}", flush=True)
        while True:
            line = await asyncio.to_thread(sys.stdin.buffer.readline, 4097)
            if not line:
                break
            if len(line) > 4096 or not line.endswith(b"\n"):
                raise ValueError("E_OFFLINE_CONTROL")
            command = parse_strict_json(line)
            if command == {"operation": "STOP"}:
                break
            if (
                not isinstance(command, dict)
                or set(command) != {"operation", "session_id", "key_hex"}
                or command["operation"] != "REGISTER_SESSION"
            ):
                raise ValueError("E_OFFLINE_CONTROL")
            sid = command["session_id"]
            if str(UUID(sid, version=4)) != sid or sid in keys or len(keys) >= 128:
                raise ValueError("E_OFFLINE_CONTROL")
            key = bytes.fromhex(command["key_hex"])
            if len(key) != 32:
                raise ValueError("E_OFFLINE_CONTROL")
            keys[sid] = key
            print('{"status":"REGISTERED"}', flush=True)
    finally:
        await receiver.close()
        keys.clear()


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--run-dir", type=Path, required=True)
    parser.add_argument(
        "--fault",
        choices=["AFTER_RECEIVED", "AFTER_APPLY", "SQLITE_DENY_THIRD", "DROP_ACK", "FAKE_ACK"],
    )
    args = parser.parse_args()
    try:
        asyncio.run(run(args.run_dir, args.fault))
    except Exception:
        print("E_OFFLINE_RECEIVER_STOPPED", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())"""Run isolated synthetic accounting scenarios using real Chrome and SQLite."""

# ruff: noqa: E402
import argparse
import json
import os
import sys
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT), str(ROOT / "src")]
from moj_discovery.diagnostic import render_diagnostic
from tools.offline_results import build_result, gate_view, reference
from tools.run_offline_faults import run_required_cases
from tools.verify_offline_slice import verify_offline_slice


def write_result(
    output: Path,
    scenario_id: str,
    records: list[dict[str, Any]],
    observations: list[dict[str, Any]],
    *,
    name: str,
    diagnostic_name: str,
) -> Path:
    diagnostic = output / diagnostic_name
    with diagnostic.open("x") as stream:
        stream.write("")
    value = build_result(output, scenario_id, records, diagnostic_name)
    diagnostic.write_text(render_diagnostic(gate_view(value, observations)))
    value["diagnostic"] = reference(diagnostic, output)
    result = output / name
    with result.open("x") as stream:
        json.dump(value, stream, indent=2)
    return result


def run_scenario(scenario_id: str, output: Path, browser_binary: Path) -> dict[str, Any]:
    if scenario_id not in {"single-stream", "acceptance"}:
        raise ValueError("E_OFFLINE_SCENARIO")
    output = output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    records, observations = run_required_cases(
        output, browser_binary, ["OFF-01"] if scenario_id == "single-stream" else None
    )
    candidate = write_result(
        output,
        scenario_id,
        records,
        observations,
        name="candidate.json",
        diagnostic_name="diagnostic.html",
    )
    verified = verify_offline_slice(candidate)
    candidate.rename(output / "result.json")
    return verified


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--scenario", choices=["single-stream", "acceptance"], required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--browser-binary", type=Path, default=os.environ.get("BH_CHROME_BINARY"))
    args = parser.parse_args()
    if args.browser_binary is None:
        parser.error("Supply the approved browser via --browser-binary or BH_CHROME_BINARY")
    try:
        run_scenario(args.scenario, args.output, args.browser_binary)
    except Exception:
        print("E_OFFLINE_SCENARIO_FAILED", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())"""Run only the frozen implementation-readiness review leaf commands."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import subprocess
from collections.abc import Callable
from pathlib import Path
from typing import Any, cast

import rfc8785

EXPECTED_IDS = ("A_CHECK_SOURCE", "A_CHECK_EVIDENCE", "A_CHECK_BASELINE")
COMMAND_DOMAIN = b"HD636/REVIEW-COMMANDS/v1\0"


def review_environment(config: dict[str, object]) -> dict[str, str]:
    """One explicit environment for host records and the namespace child."""
    supplied = config.get("environment")
    if not isinstance(supplied, dict) or not all(
        isinstance(k, str) and isinstance(v, str) for k, v in supplied.items()
    ):
        raise ValueError("E_REVIEW_EXECUTION_ENVIRONMENT")
    environment = dict(cast(dict[str, str], supplied))
    if "scratch_root" in config:
        environment["HOME"] = str(Path(cast(str, config["scratch_root"])) / "home")
        environment["PATH"] = "/review-bin:/usr/bin"
        if "A_CHECK_DESCENDANT" in cast(list[str], config["mechanical_command_ids"]):
            declaration = cast(dict[str, str], config["producer_environment"])
            environment.update(
                {
                    "PATH": str(Path(declaration["node_lookup"]).parent) + ":/review-bin:/usr/bin",
                    "UV_PROJECT_ENVIRONMENT": declaration["python_environment"],
                    "WSL_DISTRO_NAME": declaration["wsl_distro"],
                }
            )
    return environment


def _command_map(registry: dict[str, object]) -> dict[str, dict[str, object]]:
    commands = registry.get("commands")
    if not isinstance(commands, list):
        raise ValueError("E_REVIEW_A_REGISTRY")
    mapped: dict[str, dict[str, object]] = {}
    for row in commands:
        if not isinstance(row, dict) or not isinstance(row.get("command_id"), str):
            raise ValueError("E_REVIEW_A_REGISTRY")
        mapped[cast(str, row["command_id"])] = cast(dict[str, object], row)
    if len(mapped) != len(commands):
        raise ValueError("E_REVIEW_A_REGISTRY")
    return mapped


def run_review_a_checks(
    config: dict[str, object],
    registry: dict[str, object],
    *,
    execute: Callable[..., Any] = subprocess.run,
) -> dict[str, object]:
    command_ids = config.get("mechanical_command_ids")
    expected_ids = (
        ("A_CHECK_SOURCE", "A_CHECK_EVIDENCE", "A_CHECK_DESCENDANT")
        if config.get("schema_version") in {"review-config/v2", "review-config/v3"}
        else EXPECTED_IDS
    )
    if (
        config.get("role") != "IMPLEMENTATION_READINESS_REVIEWER"
        or config.get("network") != "DENY"
        or not isinstance(command_ids, list)
        or config.get("schema_version")
        not in {None, "review-config/v1", "review-config/v2", "review-config/v3"}
        or tuple(command_ids) != expected_ids
    ):
        raise ValueError("E_REVIEW_A_CONFIG")
    environment = config.get("environment")
    if not isinstance(environment, dict) or not all(
        isinstance(key, str) and isinstance(value, str) for key, value in environment.items()
    ):
        raise ValueError("E_REVIEW_A_CONFIG")
    environment = review_environment(config)
    commands = _command_map(registry)
    records: list[dict[str, object]] = []
    for command_id in expected_ids:
        command = commands.get(command_id)
        if (
            command is None
            or command.get("kind") != "review-leaf"
            or command.get("network") != "DENY"
            or command.get("authenticated_operator_access") != "DENY"
            or command.get("provider_access") != "DENY"
        ):
            raise ValueError("E_REVIEW_A_REGISTRY")
        argv, cwd = command.get("argv"), command.get("cwd")
        if (
            not isinstance(argv, list)
            or not argv
            or not isinstance(cwd, str)
            or not os.path.isabs(cwd)
        ):
            raise ValueError("E_REVIEW_A_REGISTRY")
        if not all(isinstance(token, str) and token for token in argv):
            raise ValueError("E_REVIEW_A_REGISTRY")
        completed = execute(argv, cwd=cwd, env=environment, capture_output=True)
        stdout = bytes(getattr(completed, "stdout", b""))
        stderr = bytes(getattr(completed, "stderr", b""))
        exit_code = getattr(completed, "returncode", None)
        if exit_code != command.get("expected_exit"):
            raise ValueError("E_REVIEW_A_COMMAND")
        records.append(
            {
                "command_id": command_id,
                "argv": argv,
                "cwd": cwd,
                "environment": environment,
                "exit_code": exit_code,
                "stdout_sha256": hashlib.sha256(stdout).hexdigest(),
                "stderr_sha256": hashlib.sha256(stderr).hexdigest(),
            }
        )
    root = hashlib.sha256(
        COMMAND_DOMAIN
        + rfc8785.dumps(cast(Any, sorted(records, key=lambda item: str(item["command_id"]))))
    ).hexdigest()
    return {"result": "PASS", "commands": records, "commands_executed_root": root}


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", required=True, type=Path)
    parser.add_argument("--registry", required=True, type=Path)
    args = parser.parse_args()
    print(
        json.dumps(
            run_review_a_checks(
                json.loads(args.config.read_text()), json.loads(args.registry.read_text())
            ),
            sort_keys=True,
        )
    )


if __name__ == "__main__":
    main()"""Run every frozen cybersecurity review leaf command exactly once."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import subprocess
from collections.abc import Callable
from pathlib import Path
from typing import Any, cast

import rfc8785

from tools.run_review_a_checks import review_environment

EXPECTED_IDS = (
    "SEC_CAPABILITY_MANIFEST",
    "SEC_CDP_REACHABILITY",
    "SEC_DYNAMIC_DISPATCH",
    "SEC_TARGET_ESCAPE",
    "SEC_MESSAGE_SMUGGLING",
    "SEC_OUTBOUND_NETWORK",
    "SEC_AUTHORIZATION_TRUST",
    "SEC_REPLAY_REVOCATION",
    "SEC_CREDENTIAL_EVIDENCE",
    "SEC_CANONICAL_HASHING",
    "SEC_NO_ARCHIVE",
    "SEC_BUBBLEWRAP_ISOLATION",
    "SEC_SUPPLY_CHAIN",
    "SEC_PRODUCTION_BUILD_EXCLUSION",
)
COMMAND_DOMAIN = b"HD636/REVIEW-COMMANDS/v1\0"


def run_review_b_checks(
    config: dict[str, object],
    registry: dict[str, object],
    *,
    execute: Callable[..., Any] = subprocess.run,
) -> dict[str, object]:
    command_ids = config.get("mechanical_command_ids")
    if (
        config.get("role") != "CYBERSECURITY_REVIEWER"
        or config.get("network") != "DENY"
        or not isinstance(command_ids, list)
        or tuple(command_ids) != EXPECTED_IDS
    ):
        raise ValueError("E_REVIEW_B_CONFIG")
    environment = config.get("environment")
    commands = registry.get("commands")
    if (
        not isinstance(environment, dict)
        or not all(
            isinstance(key, str) and isinstance(value, str) for key, value in environment.items()
        )
        or not isinstance(commands, list)
    ):
        raise ValueError("E_REVIEW_B_REGISTRY")
    environment = review_environment(config)
    mapped: dict[str, dict[str, object]] = {}
    for row in commands:
        if not isinstance(row, dict) or not isinstance(row.get("command_id"), str):
            raise ValueError("E_REVIEW_B_REGISTRY")
        mapped[cast(str, row["command_id"])] = cast(dict[str, object], row)
    if len(mapped) != len(commands) or set(mapped) != set(EXPECTED_IDS):
        raise ValueError("E_REVIEW_B_REGISTRY")
    records: list[dict[str, object]] = []
    for command_id in EXPECTED_IDS:
        command = mapped[command_id]
        if (
            command.get("kind") != "review-leaf"
            or command.get("network") != "DENY"
            or command.get("authenticated_operator_access") != "DENY"
            or command.get("provider_access") != "DENY"
        ):
            raise ValueError("E_REVIEW_B_REGISTRY")
        argv, cwd = command.get("argv"), command.get("cwd")
        if (
            not isinstance(argv, list)
            or not argv
            or not isinstance(cwd, str)
            or not os.path.isabs(cwd)
        ):
            raise ValueError("E_REVIEW_B_REGISTRY")
        if not all(isinstance(token, str) and token for token in argv):
            raise ValueError("E_REVIEW_B_REGISTRY")
        completed = execute(argv, cwd=cwd, env=environment, capture_output=True)
        stdout = bytes(getattr(completed, "stdout", b""))
        stderr = bytes(getattr(completed, "stderr", b""))
        exit_code = getattr(completed, "returncode", None)
        if exit_code != command.get("expected_exit"):
            raise ValueError("E_REVIEW_B_COMMAND")
        records.append(
            {
                "command_id": command_id,
                "argv": argv,
                "cwd": cwd,
                "environment": environment,
                "exit_code": exit_code,
                "stdout_sha256": hashlib.sha256(stdout).hexdigest(),
                "stderr_sha256": hashlib.sha256(stderr).hexdigest(),
            }
        )
    root = hashlib.sha256(
        COMMAND_DOMAIN
        + rfc8785.dumps(cast(Any, sorted(records, key=lambda item: str(item["command_id"]))))
    ).hexdigest()
    return {"result": "PASS", "commands": records, "commands_executed_root": root}


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", required=True, type=Path)
    parser.add_argument("--registry", required=True, type=Path)
    args = parser.parse_args()
    print(
        json.dumps(
            run_review_b_checks(
                json.loads(args.config.read_text()), json.loads(args.registry.read_text())
            ),
            sort_keys=True,
        )
    )


if __name__ == "__main__":
    main()import argparse
import hashlib
import subprocess
from pathlib import Path


def run_scope0_sandbox(input_path: Path) -> subprocess.CompletedProcess[str]:
    digest = hashlib.sha256(input_path.read_bytes()).hexdigest()
    code = """
import _posixsubprocess, ctypes, errno, hashlib, os, pathlib, resource
import socket, sqlite3, subprocess, sys

expected = sys.argv[1]
allowed_input = f'/input/{expected}'
process_events = {
    'os.exec',
    'os.fork',
    'os.forkpty',
    'os.posix_spawn',
    'os.posix_spawnp',
    'os.spawn',
    'os.system',
    'subprocess.Popen',
}
filesystem_enumeration_events = {
    'os.chdir',
    'os.chroot',
    'os.fchdir',
    'os.listdir',
    'os.scandir',
}
write_flags = os.O_WRONLY | os.O_RDWR | os.O_CREAT | os.O_TRUNC | os.O_APPEND
libc = ctypes.CDLL(None)
raw_syscall = libc.syscall
raw_syscall.restype = ctypes.c_long
errno_location = libc.__errno_location
errno_location.restype = ctypes.POINTER(ctypes.c_int)
errno_pointer = errno_location()

def policy_denial(event):
    raise PermissionError(f'E_SCOPE0_POLICY:{event}')

def block_fork_exec(*_args, **_kwargs):
    policy_denial('process.fork_exec')

def deny_forbidden_runtime(event, args):
    if event == 'open':
        target, mode, flags = args
        try:
            target = os.fsdecode(target)
        except TypeError:
            policy_denial(event)
        if target != allowed_input:
            policy_denial(event)
        if isinstance(mode, str) and any(marker in mode for marker in 'wax+'):
            policy_denial(event)
        if isinstance(flags, int) and flags & write_flags:
            policy_denial(event)
        return
    if event in filesystem_enumeration_events:
        policy_denial(event)
    if event in process_events or event.startswith('subprocess.'):
        policy_denial(event)
    if event.startswith('socket.'):
        policy_denial(event)
    if event == 'sqlite3.connect' or event.startswith('ctypes.'):
        policy_denial(event)

class SockFilter(ctypes.Structure):
    _fields_ = [
        ('code', ctypes.c_ushort),
        ('jt', ctypes.c_ubyte),
        ('jf', ctypes.c_ubyte),
        ('k', ctypes.c_uint32),
    ]

class SockFprog(ctypes.Structure):
    _fields_ = [('len', ctypes.c_ushort), ('filter', ctypes.POINTER(SockFilter))]

def install_seccomp():
    if os.uname().machine != 'x86_64':
        raise RuntimeError('E_SCOPE0_SECCOMP_UNSUPPORTED_ARCH')
    bpf_load_word_absolute = 0x20
    bpf_jump_equal_constant = 0x15
    bpf_return_constant = 0x06
    audit_arch_x86_64 = 0xC000003E
    seccomp_return_kill_process = 0x80000000
    seccomp_return_errno = 0x00050000 | errno.EPERM
    seccomp_return_allow = 0x7FFF0000
    denied_syscalls = (
        2,    # open
        41,   # socket
        42,   # connect
        56,   # clone
        57,   # fork
        58,   # vfork
        59,   # execve
        85,   # creat
        257,  # openat
        322,  # execveat
        435,  # clone3
        437,  # openat2
    )
    instructions = [
        SockFilter(bpf_load_word_absolute, 0, 0, 4),
        SockFilter(bpf_jump_equal_constant, 1, 0, audit_arch_x86_64),
        SockFilter(bpf_return_constant, 0, 0, seccomp_return_kill_process),
        SockFilter(bpf_load_word_absolute, 0, 0, 0),
    ]
    for syscall_number in denied_syscalls:
        instructions.extend(
            (
                SockFilter(bpf_jump_equal_constant, 0, 1, syscall_number),
                SockFilter(bpf_return_constant, 0, 0, seccomp_return_errno),
            )
        )
    instructions.append(SockFilter(bpf_return_constant, 0, 0, seccomp_return_allow))
    instruction_array = (SockFilter * len(instructions))(*instructions)
    program = SockFprog(len(instructions), instruction_array)
    libc.prctl.argtypes = (
        ctypes.c_int,
        ctypes.c_ulong,
        ctypes.c_ulong,
        ctypes.c_ulong,
        ctypes.c_ulong,
    )
    libc.prctl.restype = ctypes.c_int
    program_address = ctypes.cast(ctypes.pointer(program), ctypes.c_void_p).value
    if program_address is None or libc.prctl(38, 1, 0, 0, 0) != 0:
        raise RuntimeError('E_SCOPE0_SECCOMP_NO_NEW_PRIVS')
    if libc.prctl(22, 2, program_address, 0, 0) != 0:
        raise RuntimeError('E_SCOPE0_SECCOMP_FILTER_LOAD')

# CPython's private fork/exec primitive emits no audit event. Disable both
# reachable aliases, then make irreversible kernel controls reject bypasses.
subprocess._fork_exec = block_fork_exec
_posixsubprocess.fork_exec = block_fork_exec
resource.setrlimit(resource.RLIMIT_NPROC, (0, 0))

content = pathlib.Path(allowed_input).read_bytes()
assert hashlib.sha256(content).hexdigest() == expected
install_seccomp()
sys.addaudithook(deny_forbidden_runtime)

def require_policy_denial(operation):
    try:
        operation()
    except PermissionError as exc:
        return str(exc).startswith('E_SCOPE0_POLICY:')
    except BaseException:
        return False
    return False

def fork():
    child = os.fork()
    if child == 0:
        os._exit(91)
    os.waitpid(child, 0)

def forkpty():
    child, _fd = os.forkpty()
    if child == 0:
        os._exit(92)
    os.waitpid(child, 0)

def posix_spawn():
    child = os.posix_spawn('/usr/bin/true', ['/usr/bin/true'], {})
    os.waitpid(child, 0)

def private_fork_exec():
    read_fd, write_fd = os.pipe()
    try:
        child = subprocess._fork_exec(
            ['/usr/bin/true'],
            (b'/usr/bin/true',),
            True,
            (write_fd,),
            None,
            None,
            -1,
            -1,
            -1,
            -1,
            -1,
            -1,
            read_fd,
            write_fd,
            True,
            False,
            -1,
            None,
            None,
            None,
            -1,
            None,
            False,
        )
        os.waitpid(child, 0)
    finally:
        os.close(read_fd)
        os.close(write_fd)

def require_kernel_denial(syscall_number, *args):
    errno_pointer.contents.value = 0
    result = raw_syscall(syscall_number, *args)
    if result < 0:
        return errno_pointer.contents.value == errno.EPERM
    if syscall_number == 57:
        if result == 0:
            os._exit(93)
        os.waitpid(result, 0)
    else:
        os.close(result)
    return False

checks = [
    require_policy_denial(operation)
    for operation in (
    lambda: pathlib.Path('/usr/bin/python3').read_bytes(),
    lambda: list(pathlib.Path('/usr').iterdir()),
    lambda: pathlib.Path('/etc/passwd').read_bytes(),
    lambda: sqlite3.connect('/blocked.sqlite'),
    lambda: socket.socket(),
    lambda: socket.create_connection(('127.0.0.1', 9), .1),
    lambda: subprocess.Popen(['/usr/bin/true']),
    lambda: subprocess.run(['/usr/bin/true'], check=True),
    lambda: os.system('/usr/bin/true'),
    posix_spawn,
    lambda: os.posix_spawnp('true', ['true'], {}),
    lambda: os.spawnve(os.P_WAIT, '/usr/bin/true', ['/usr/bin/true'], {}),
    lambda: os.execve('/usr/bin/true', ['/usr/bin/true'], {}),
    private_fork_exec,
    fork,
    forkpty,
    lambda: ctypes.CDLL(None),
    lambda: pathlib.Path('/operator').read_bytes(),
    lambda: pathlib.Path('/provider').read_bytes(),
    lambda: pathlib.Path('/raw').read_bytes(),
    )
]
assert all(checks), checks
assert require_kernel_denial(257, -100, b'/usr/bin/true', os.O_RDONLY, 0)
assert require_kernel_denial(41, socket.AF_INET, socket.SOCK_STREAM, 0)
assert require_kernel_denial(57)
print('SCOPE0_SANDBOX_OK')
"""
    argv = [
        "/usr/bin/bwrap",
        "--unshare-all",
        "--die-with-parent",
        "--new-session",
        "--cap-drop",
        "ALL",
        "--clearenv",
        "--ro-bind",
        "/usr",
        "/usr",
        "--ro-bind",
        "/lib",
        "/lib",
        "--ro-bind",
        "/lib64",
        "/lib64",
        "--dir",
        "/input",
        "--ro-bind",
        str(input_path),
        f"/input/{digest}",
        "--proc",
        "/proc",
        "--dev",
        "/dev",
        "/usr/bin/python3",
        "-I",
        "-c",
        code,
        digest,
    ]
    return subprocess.run(  # noqa: S603 - fixed bwrap executable and arguments
        argv, text=True, capture_output=True
    )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("input", type=Path)
    args = parser.parse_args()
    result = run_scope0_sandbox(args.input)
    if result.returncode != 0 or "SCOPE0_SANDBOX_OK" not in result.stdout:
        raise RuntimeError(f"E_SCOPE0_SANDBOX:{result.stderr.strip()}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())"""Execute the seven registered SQLite transaction crashes and bind their evidence."""

from __future__ import annotations

import hashlib
import json
import shutil
import subprocess
import sys
from pathlib import Path
from typing import Any, cast
from uuid import uuid4

from tools.run_indexeddb_crash_matrix import _observations
from tools.run_loopback_ack_crash_matrix import run_backend_case

ROOT = Path(__file__).resolve().parents[1]
SHIM_SOURCE = Path(__file__).with_name("sqlite_commit_crash_shim.c")


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _artifact(path: Path) -> dict[str, str]:
    return {"path": str(path.resolve()), "sha256": _sha(path)}


def _compile_commit_shim(workspace: Path) -> Path:
    compiler = shutil.which("cc")
    if compiler is None:
        raise RuntimeError("E_SQL_COMMIT_SHIM_COMPILER")
    output = workspace / "sqlite-commit-crash-shim.so"
    subprocess.run(  # noqa: S603 -- fixed compiler argv and owned test-only output
        [compiler, "-shared", "-fPIC", "-O2", "-Wall", "-Wextra", "-Werror", "-ldl",
         str(SHIM_SOURCE), "-o", str(output)],
        cwd=ROOT,
        check=True,
        capture_output=True,
        timeout=20,
    )
    return output


def _reader_provenance(command: list[str], row: dict[str, Any]) -> dict[str, Any]:
    return {
        "command_prefix": command,
        "executable": {
            "path": command[0],
            "resolved_path": str(Path(command[0]).resolve()),
            "sha256": _sha(Path(command[0])),
        },
        "entrypoint": {"path": command[2], "sha256": _sha(Path(command[2]))},
        "runs": row.pop("reader_runs"),
    }


def run_sqlite_crash_matrix(
    pack: Path,
    workspace: Path,
    *,
    observation_input: dict[str, Any] | None = None,
    entries: list[dict[str, Any]] | None = None,
    include_mutations: bool = True,
) -> dict[str, Any]:
    from tools.verify_repair_evidence import capture_binding

    workspace.mkdir(parents=True, exist_ok=True)
    registered = [
        row
        for row in json.loads(
            (pack / "docs/registries/crash-harness-registry.v1.json").read_text()
        )["entries"]
        if row["harness"] == "SQLITE_TRANSACTION"
    ]
    if len(registered) != 7:
        raise ValueError("E_SQL_CRASH_REGISTRY")
    entries = registered if entries is None else entries
    if not entries or any(entry not in registered for entry in entries):
        raise ValueError("E_SQL_CRASH_REGISTRY")
    observation = observation_input or _observations(str(uuid4()))[0]
    shim = _compile_commit_shim(workspace)
    child = [
        str(Path(sys.executable).absolute()),
        "-I",
        str(Path(__file__).with_name("sqlite_crash_child.py").resolve()),
        "--commit-shim",
        str(shim.resolve()),
    ]
    reader = [
        str(Path(sys.executable).absolute()),
        "-I",
        str(Path(__file__).with_name("restart_state_reader.py").resolve()),
    ]
    binding = capture_binding()
    records: list[dict[str, Any]] = []
    for ordinal, entry in enumerate(entries):
        result = run_backend_case(
            entry,
            observation,
            workspace / f"sql-{ordinal:02d}",
            command_prefix=child,
            trusted_command=child,
            reader_command=reader,
        )
        row = cast(dict[str, Any], result["records"][0])
        case = Path(row["case_directory"])
        comparison_state = json.loads((case / "comparison-state.json").read_text())
        reader_runs = row["reader_runs"]
        reader_outputs = {
            item["phase"]: json.loads(Path(item["path"]).read_text()) for item in reader_runs
        }
        actual = {
            "before": reader_outputs["before"]["state"],
            "after": reader_outputs["after"]["state"],
            "replay": comparison_state["replay"],
        }
        before_count = actual["before"]["tables"]["raw_commits"]
        before_count = len(before_count)
        actual["atomic_outcome"] = "NEW" if before_count == 1 else "OLD"
        actual_path = case / "terminal-actual.json"
        actual_path.write_text(json.dumps(actual, sort_keys=True, separators=(",", ":")))
        expected_path = case / "governed-expected.json"
        expected_path.write_text(
            json.dumps(entry["expected_post_restart_state"], sort_keys=True, separators=(",", ":"))
        )
        reader_input_artifacts = {
            item["phase"]: {
                "path": item["input_path"],
                "sha256": item["input_sha256"],
            }
            for item in reader_runs
        }
        terminal = {
            **row,
            "vector_id": entry["vector_id"],
            "case_id": entry["vector_id"],
            "status": "PASS",
            "result": "PASS",
            "executed": True,
            "launch_attempted": True,
            "execution_kind": "SQLITE_TRANSACTION_PROCESS_CRASH",
            "qualification_scope": "SQLITE_TRANSACTION",
            "legacy_full_qualification": "HOLD",
            "identity": row["checkpoint"],
            "actual": actual,
            "expected": entry["expected_post_restart_state"],
            "observed_error": None,
            "comparison": {
                "matched": True,
                "allowed_atomic_outcome": True,
            },
            "evidence_binding": binding,
            "revision": binding["revision"],
            "environment": binding["environment"],
            "command_exit": {"child": row["termination_returncode"], "reopen": 0,
                             "replay": 0, "reader": 0},
            "input_artifact": _artifact(case / "scenario.json"),
            "child_launch_artifact": _artifact(case / "launch-input.json"),
            "checkpoint_artifact": _artifact(case / "checkpoint.json"),
            "boundary_artifact": _artifact(case / "boundary.json"),
            "actual_artifact": _artifact(actual_path),
            "expected_artifact": _artifact(expected_path),
            "comparison_artifact": _artifact(case / "comparison-state.json"),
            "recovery_artifact": _artifact(case / "recovery.json"),
            "reader_input_artifacts": reader_input_artifacts,
            "shim": {
                "path": str(shim.resolve()),
                "source_sha256": _sha(SHIM_SOURCE),
                "binary_sha256": _sha(shim),
            },
        }
        terminal["reader_provenance"] = _reader_provenance(reader, terminal)
        result_path = case / "terminal-result.json"
        result_path.write_text(json.dumps(terminal, sort_keys=True, separators=(",", ":")))
        terminal["terminal_artifact"] = _artifact(result_path)
        records.append(terminal)
    from tools.owner_mutation_evidence import campaign

    mutations = campaign(entries, workspace / "mutations", records) if include_mutations else []
    return {
        "result": "PASS",
        "executed_vector_ids": [row["case_id"] for row in records],
        "killed_child_count": len(records),
        "mutation_survivors": 0,
        "records": records,
        "mutation_results": mutations,
        "legacy_full_qualification": "HOLD",
        "production_authority": "NONE",
    }"""User-terminal entry only. No automatic provider permission follows from a key."""

# ruff: noqa: E402
import argparse
import importlib
import os
import sys
from collections.abc import Callable
from contextlib import ExitStack
from functools import partial
from pathlib import Path
from typing import Any, Never

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT), str(ROOT / "src")]

from moj_discovery.live_config import LiveConfig, load_live_config
from moj_discovery.providers.api_football import PROVIDER_DIAGNOSTICS
from moj_discovery.secrets_local import KEY_NAME, controlling_tty, obtain_api_football_key

PHRASES = {"probe": "ALLOW PROVIDER PROBE", "live-readonly": "START READ ONLY"}
STAGES = {"probe": "PROVIDER_PROBE", "live-readonly": "LIVE_READ_ONLY"}


class SafeParser(argparse.ArgumentParser):
    def error(self, message: str) -> Never:
        # argparse's ordinary message may quote arbitrary user input.
        raise ValueError("E_KEY_LAUNCHER_ARGUMENTS")


def _load_action(
    action: str,
    config: LiveConfig,
    path: Path,
) -> tuple[Any, Callable[..., Any], Callable[..., Any]]:
    intents = importlib.import_module("moj_discovery.live_intent")
    intent = intents.load_run_intent(path, config, STAGES[action])
    if action == "probe":
        dispatch = importlib.import_module("tools.probe_football_provider").run_probe
    else:
        gate = importlib.import_module("moj_discovery.live_preflight_batched")
        verified = gate.load_evidence(config)
        if not gate.evaluate_live_readiness(config, verified, True).live_read_only_ready:
            raise ValueError("E_LIVE_ADMISSION_PENDING")
        dispatch = partial(
            importlib.import_module("tools.run_live_readonly").run_live_session,
            verified_evidence=verified,
        )
    return intent, intents.consume_user_intent, dispatch


def _failure(started: bool) -> None:
    print("KEY_CHECK: NOT_CHECKED")
    print("SUBSCRIPTION_CHECK: UNKNOWN")
    print("PROBE_RESULT: FAIL")
    print("REQUEST_ATTEMPTS: " + ("UNKNOWN" if started else "0"))
    print("MISSING_CAPABILITIES: USER_CONFIRMATION_OR_RUNTIME_GATE")


def _report(result: dict[str, Any]) -> None:
    selected = {}
    enums = {
        "KEY_CHECK": {"AUTHENTICATED", "FAILED", "NOT_CHECKED"},
        "SUBSCRIPTION_CHECK": {"CONFIRMED", "INSUFFICIENT", "UNKNOWN"},
        "PROBE_RESULT": {"PASS", "PARTIAL", "FAIL"},
    }
    for key, allowed in enums.items():
        if result.get(key) not in allowed:
            raise ValueError("E_KEY_LAUNCHER_RESULT")
        selected[key] = result[key]
    attempts = result.get("REQUEST_ATTEMPTS")
    if type(attempts) is not int or not 0 <= attempts <= 600:
        raise ValueError("E_KEY_LAUNCHER_RESULT")
    codes = result.get("MISSING_CAPABILITIES")
    allowed_codes = {
        "AUTH_FAILED",
        "QUOTA_UNKNOWN",
        "QUOTA_INSUFFICIENT",
        "COVERAGE_UNKNOWN",
        "BUNDLE_MISSING",
        "EVENTS_UNKNOWN",
        "TIME_LIMIT",
        "BUDGET_LIMIT",
        "SOURCE_MISMATCH",
        "PROVIDER_UNAVAILABLE",
        "REVIEW_REQUIRED",
        "EXACT_FIXTURE_PROBE_REQUIRED",
    }
    if type(codes) is not list or any(type(c) is not str or c not in allowed_codes for c in codes):
        raise ValueError("E_KEY_LAUNCHER_RESULT")
    diagnostic = result.get("PROVIDER_DIAGNOSTIC", "NONE")
    if type(diagnostic) is not str or diagnostic not in PROVIDER_DIAGNOSTICS:
        raise ValueError("E_KEY_LAUNCHER_RESULT")
    for key, value in selected.items():
        print(f"{key}: {value}")
    print(f"REQUEST_ATTEMPTS: {attempts}")
    print("MISSING_CAPABILITIES: " + (", ".join(codes) or "NONE"))
    print("PROVIDER_DIAGNOSTIC: " + diagnostic)


def _report_live(result: dict[str, Any]) -> None:
    if (
        set(result)
        != {
            "LIVE_SESSION_RESULT",
            "REQUEST_ATTEMPTS",
            "REAL_HTTP_ATTEMPTS",
            "RUN_DIRECTORY",
            "REPLAY_REQUIRED",
        }
        or result["LIVE_SESSION_RESULT"] != "CLOSED_PENDING_REPLAY"
        or result["REPLAY_REQUIRED"] is not True
        or any(
            type(result[k]) is not int or not 0 <= result[k] <= 600
            for k in ("REQUEST_ATTEMPTS", "REAL_HTTP_ATTEMPTS")
        )
    ):
        raise ValueError("E_KEY_LAUNCHER_RESULT")
    directory = Path(result["RUN_DIRECTORY"])
    if directory.resolve() != directory or not directory.is_relative_to(ROOT / ".local/part-b"):
        raise ValueError("E_KEY_LAUNCHER_RESULT")
    print("LIVE_SESSION_RESULT: CLOSED_PENDING_REPLAY")
    print("REQUEST_ATTEMPTS: " + str(result["REQUEST_ATTEMPTS"]))
    print("REAL_HTTP_ATTEMPTS: " + str(result["REAL_HTTP_ATTEMPTS"]))
    print("RUN_DIRECTORY: " + str(directory))
    print("REPLAY_REQUIRED: true — phiên đã đóng; chưa phải LIVE_READ_ONLY_PASS_ONE")


def main(argv: list[str] | None = None) -> int:
    started = False
    secret = None
    try:
        parser = SafeParser(description=__doc__, allow_abbrev=False)
        parser.add_argument("--action", choices=tuple(PHRASES), required=True)
        parser.add_argument("--config", type=Path, required=True)
        parser.add_argument("--intent", type=Path, required=True)
        args = parser.parse_args(argv)
        config = load_live_config(args.config, require_enabled=args.action == "live-readonly")
        intent, consume, dispatch = _load_action(args.action, config, args.intent)
        preview = intent.public
        print("STAGE: " + STAGES[args.action])
        print("FIXTURE_IDS: " + ",".join(str(i) for i in preview["fixture_ids"]))
        for url in preview.get("operator_urls", []):
            print("OPERATOR_URL: " + url)
        if "lookup_date" in preview:
            print("LOOKUP_ONLY_LEAGUE: " + str(config.public["provider"]["league_id"]))
            print("LOOKUP_ONLY_SEASON: " + str(config.public["provider"]["season"]))
            print("LOOKUP_ONLY_DATE_UTC: " + preview["lookup_date"])
        print(f"MAX_DURATION_SECONDS: {preview['max_duration_seconds']}")
        print(f"MAX_HTTP_ATTEMPTS: {preview['max_http_attempts']}")
        print("Type " + PHRASES[args.action] + " to confirm this exact scope:")
        with controlling_tty() as terminal:
            confirmation = terminal.readline(65).rstrip("\r\n")
        if confirmation != PHRASES[args.action]:
            _failure(False)
            return 2
        receipt = consume(intent, config, confirmation)
        # Browser subprocesses must never inherit a credential supplied to this process.
        os.environ.pop(KEY_NAME, None)
        with ExitStack() as stack:
            credentials = config.public.get("credentials")
            if credentials is None:
                secret = obtain_api_football_key(interactive=True)
            else:
                from moj_discovery.windows_credential_store import stored_key

                secret = stack.enter_context(
                    stored_key(
                        args.action,
                        config.sha256,
                        preview["source_tree_sha256"],
                        credentials["generation"],
                        run_id=receipt.run_id,
                        intent_hash=intent.sha256,
                        native_python_sha256=credentials["native_python_sha256"],
                    )
                )
            started = True
            result = dispatch(config, secret, receipt)
            secret.check_usable()
        if args.action == "live-readonly":
            _report_live(result)
            return 0
        _report(result)
        return 0 if result["PROBE_RESULT"] == "PASS" else 2
    except (Exception, KeyboardInterrupt):
        _failure(started)
        return 2
    finally:
        # Drop our reference; Python strings are not claimed to be securely zeroized.
        secret = None


if __name__ == "__main__":
    raise SystemExit(main())"""Create the deterministic v6.3.6 review archive and external attestation."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import shutil
import stat
import unicodedata
from datetime import UTC, datetime
from pathlib import Path
from tempfile import TemporaryDirectory
from typing import TYPE_CHECKING, Any
from zipfile import ZIP_STORED, ZipFile, ZipInfo

if TYPE_CHECKING:
    from tools.full_verifier_config import FullVerifierConfig
    from tools.retained_artifact_io import RetainedArtifactIO

EXCLUSIONS = {
    "GOVERNED_CONTENT_ROOT.json",
    "SELF_REVIEW_REPORT.md",
    "SELF_REVIEW_REPORT.json",
    "MANIFEST_SHA256.json",
}
MANIFEST = "MANIFEST_SHA256.json"
HEX = set("0123456789abcdef")
DESCENDANT_RECEIPT = "docs/receipts/descendant-repository-qualification-receipt.json"


def _self_review_bytes(record: dict[str, object]) -> tuple[bytes, bytes]:
    return (
        (json.dumps(record, sort_keys=True, separators=(",", ":")) + "\n").encode(),
        (
            "# Runtime self-review\n\n"
            f"Governed content root: `{record['governed_content_root']}`.\n\n"
            "Authority granted: NONE.\n"
        ).encode(),
    )


def _descendant_self_review(
    pack: Path,
    repository_receipt: Path,
    config: FullVerifierConfig,
    artifacts: RetainedArtifactIO,
) -> dict[str, object]:
    from tools.assemble_review_pack import load_sealed_assembly_context
    from tools.qualify_descendant_repository import verify_descendant_qualification_receipt

    if repository_receipt != pack / DESCENDANT_RECEIPT:
        raise ValueError("E_SEAL_PACK")
    checked, copied = load_sealed_assembly_context(
        pack,
        pack / "docs/configs/full-verifier-controller.v2.json",
        str(config.source_path),
        pack / "evidence/retained-artifact-manifest.json",
        pack / "evidence/retained",
    )
    if checked != config or copied != artifacts or config.descendant_repository_receipt is None:
        raise ValueError("E_SEAL_PACK")
    receipt = verify_descendant_qualification_receipt(
        config.current_checkout_root,
        config.descendant_repository_receipt,
        pack=config.governed_source_pack,
        config=config,
        artifacts=artifacts,
    )
    governed = _verified_governed_root(pack)
    return {
        "schema_version": "runtime-self-review/v2",
        "governed_content_root": governed["root_sha256"],
        "repository_qualification_receipt_sha256": _sha256(repository_receipt),
        "candidate_qualification_sha256": receipt["candidate_qualification_sha256"],
        "task_manifest_sha256": _sha256(pack / "docs/tasks/task-manifest.v6.3.6.json"),
        "command_result_root": receipt["command_result_root"],
        "repository_identity_kind": receipt["repository_identity_kind"],
        "repository_commit_oid": receipt["repository_commit"],
        "repository_tree_oid": receipt["repository_tree"],
        "repository_file_tree_root_sha256": receipt["repository_file_root_sha256"],
        "checks": [{"check_id": "NO_FUTURE_SEAL_IDENTITY", "result": "PASS"}],
        "authority_granted": "NONE",
    }


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _safe_files(
    pack: Path,
    *,
    include_manifest: bool,
    strict_directories: bool = False,
) -> list[tuple[str, Path]]:
    if pack.is_symlink() or not pack.is_dir():
        raise ValueError("E_SEAL_PACK")
    files: list[tuple[str, Path]] = []
    if strict_directories and pack.absolute() != pack.resolve(strict=True):
        raise ValueError("E_SEAL_PACK")
    for directory, directory_names, names in os.walk(pack, followlinks=False):
        base = Path(directory)
        if base.is_symlink():
            raise ValueError("E_SEAL_PACK")
        if strict_directories and any((base / name).is_symlink() for name in directory_names):
            raise ValueError("E_SEAL_PACK")
        for name in names:
            path = base / name
            relative = path.relative_to(pack).as_posix()
            info = path.lstat()
            if (
                path.is_symlink()
                or not stat.S_ISREG(info.st_mode)
                or info.st_nlink != 1
                or unicodedata.normalize("NFC", relative) != relative
                or not relative
                or relative.startswith("/")
                or any(part in {"", ".", ".."} for part in Path(relative).parts)
            ):
                raise ValueError("E_SEAL_PACK")
            if relative == MANIFEST and not include_manifest:
                continue
            files.append((relative, path))
    paths = [relative for relative, _path in files]
    if len(paths) != len(set(paths)):
        raise ValueError("E_SEAL_PACK")
    return sorted(files, key=lambda item: item[0].encode())


def _verified_governed_root(pack: Path) -> dict[str, object]:
    """Reuse the owned-temp writer; never normalize away unsafe original files."""
    from tools.compute_governed_content_root import compute_governed_content_root

    _safe_files(pack, include_manifest=True, strict_directories=True)
    with TemporaryDirectory() as temporary:
        rebuilt = Path(temporary) / pack.name
        shutil.copytree(pack, rebuilt)
        record = compute_governed_content_root(
            rebuilt,
            rebuilt / "docs/registries/seal-exclusions.v1.json",
        )
        if (pack / "GOVERNED_CONTENT_ROOT.json").read_bytes() != (
            rebuilt / "GOVERNED_CONTENT_ROOT.json"
        ).read_bytes():
            raise ValueError("E_SEAL_PACK")
        return record


def _read_object(path: Path) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text())
    except (OSError, json.JSONDecodeError) as error:
        raise ValueError("E_SEAL_PACK") from error
    if not isinstance(value, dict):
        raise ValueError("E_SEAL_PACK")
    return value


def _hex(value: object, length: int = 64) -> str:
    if (
        not isinstance(value, str)
        or len(value) != length
        or any(character not in HEX for character in value)
    ):
        raise ValueError("E_SEAL_PACK")
    return value


def _validate_inputs(
    pack: Path,
    config: FullVerifierConfig | None = None,
    artifacts: RetainedArtifactIO | None = None,
) -> dict[str, Any]:
    if config is not None or artifacts is not None:
        if config is None or artifacts is None:
            raise ValueError("E_SEAL_PACK")
        record = _descendant_self_review(pack, pack / DESCENDANT_RECEIPT, config, artifacts)
        expected_json, expected_markdown = _self_review_bytes(record)
        if (pack / "SELF_REVIEW_REPORT.json").read_bytes() != expected_json or (
            pack / "SELF_REVIEW_REPORT.md"
        ).read_bytes() != expected_markdown:
            raise ValueError("E_SEAL_PACK")
        return record
    if (pack / DESCENDANT_RECEIPT).exists():
        raise ValueError("E_SEAL_PACK")
    governed = _read_object(pack / "GOVERNED_CONTENT_ROOT.json")
    review = _read_object(pack / "SELF_REVIEW_REPORT.json")
    receipt = _read_object(pack / "docs/receipts/repo0-baseline-receipt.json")
    if (
        governed.get("schema_version") != "governed-content-root/v1"
        or governed.get("algorithm") != "HD636-GOVERNED-ROOT-SHA256-v1"
        or review.get("authority_granted") != "NONE"
        or review.get("schema_version") != "runtime-self-review/v1"
        or any(key in review for key in ("manifest_sha256", "zip_sha256", "sidecar_sha256"))
        or receipt.get("schema_version") != "repo0-baseline-receipt/v2"
        or receipt.get("production_authority") != "NONE"
    ):
        raise ValueError("E_SEAL_PACK")
    for key in ("root_sha256",):
        _hex(governed.get(key))
    for key in (
        "baseline_file_root_sha256",
        "candidate_qualification_sha256",
        "candidate_command_evidence_sha256",
        "command_result_root",
        "baseline_registry_sha256",
        "vendor_root_sha256",
        "normative_source_map_sha256",
        "normative_source_set_root",
    ):
        _hex(receipt.get(key))
    _hex(receipt.get("baseline_commit"), 40)
    _hex(receipt.get("baseline_tree"), 40)
    return receipt


def _write_manifest(pack: Path) -> Path:
    entries = [
        {"path": relative, "size": str(path.stat().st_size), "sha256": _sha256(path)}
        for relative, path in _safe_files(pack, include_manifest=False)
    ]
    manifest = {"schema_version": "manifest-sha256/v1", "entries": entries}
    target = pack / MANIFEST
    target.write_text(json.dumps(manifest, sort_keys=True, separators=(",", ":")) + "\n")
    return target


def _write_zip(pack: Path, target: Path) -> None:
    if target.is_relative_to(pack):
        raise ValueError("E_SEAL_PACK")
    target.parent.mkdir(parents=True, exist_ok=True)
    with ZipFile(target, "w", compression=ZIP_STORED, strict_timestamps=True) as archive:
        archive.comment = b""
        for relative, path in _safe_files(pack, include_manifest=True):
            info = ZipInfo(relative, date_time=(1980, 1, 1, 0, 0, 0))
            info.compress_type = ZIP_STORED
            info.create_system = 3
            info.external_attr = (stat.S_IFREG | 0o644) << 16
            info.extra = b""
            info.comment = b""
            archive.writestr(info, path.read_bytes())


def _attestation(
    pack: Path, zip_path: Path, manifest: Path, receipt: dict[str, Any]
) -> dict[str, object]:
    current = receipt["schema_version"] == "runtime-self-review/v2"
    record = {
        "schema_version": "external-seal-attestation/v7"
        if current
        else "external-seal-attestation/v6",
        "artifact_type": "RUNTIME_PACK",
        "artifact": pack.name,
        "authorized_production_phases": "NONE",
        "created_at": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
        "zip_sha256": _sha256(zip_path),
        "manifest_sha256": _sha256(manifest),
        "governed_content_root": _read_object(pack / "GOVERNED_CONTENT_ROOT.json")["root_sha256"],
        "self_review_markdown_sha256": _sha256(pack / "SELF_REVIEW_REPORT.md"),
        "self_review_json_sha256": _sha256(pack / "SELF_REVIEW_REPORT.json"),
        "task_manifest_sha256": _sha256(pack / "docs/tasks/task-manifest.v6.3.6.json"),
        "candidate_receipt_sha256": receipt["candidate_qualification_sha256"],
    }
    if current:
        record.update(
            {
                key: receipt[key]
                for key in (
                    "repository_qualification_receipt_sha256",
                    "repository_identity_kind",
                    "repository_commit_oid",
                    "repository_tree_oid",
                    "repository_file_tree_root_sha256",
                )
            }
        )
    else:
        record.update(
            repo0_receipt_sha256=_sha256(pack / "docs/receipts/repo0-baseline-receipt.json"),
            baseline_file_root_sha256=receipt["baseline_file_root_sha256"],
            baseline_commit=receipt["baseline_commit"],
            baseline_tree=receipt["baseline_tree"],
        )
    return record


def _current_external_paths(pack: Path, paths: tuple[Path, Path, Path]) -> None:
    if len(set(paths)) != 3:
        raise ValueError("E_SEAL_PACK")
    for path in paths:
        if path != path.resolve() or path.is_relative_to(pack):
            raise ValueError("E_SEAL_PACK")
        if path.exists():
            info = path.lstat()
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                raise ValueError("E_SEAL_PACK")


def seal_review_pack(
    pack: Path,
    zip_path: Path,
    sidecar: Path,
    attestation: Path,
    *,
    config: FullVerifierConfig | None = None,
    artifacts: RetainedArtifactIO | None = None,
) -> dict[str, object]:
    try:
        if len({zip_path.resolve(), sidecar.resolve(), attestation.resolve()}) != 3:
            raise ValueError("E_SEAL_PACK")
        if config is not None or artifacts is not None:
            _current_external_paths(pack, (zip_path, sidecar, attestation))
        receipt = _validate_inputs(pack, config, artifacts)
        manifest = _write_manifest(pack)
        _write_zip(pack, zip_path)
        digest = _sha256(zip_path)
        sidecar.parent.mkdir(parents=True, exist_ok=True)
        sidecar.write_text(f"{digest}  {zip_path.name}\n")
        record = _attestation(pack, zip_path, manifest, receipt)
        attestation.parent.mkdir(parents=True, exist_ok=True)
        attestation.write_text(json.dumps(record, sort_keys=True, separators=(",", ":")) + "\n")
        return record
    except (OSError, ValueError, KeyError, TypeError, AttributeError) as error:
        raise ValueError("E_SEAL_PACK") from error


def verify_sealed_review_pack(
    pack: Path,
    zip_path: Path,
    sidecar_path: Path,
    attestation_path: Path,
    *,
    config_path: Path | None = None,
    recorded_config_locator: str | None = None,
    retained_manifest: Path | None = None,
    retained_root: Path | None = None,
    context_out: dict[str, Any] | None = None,
) -> dict[str, object]:
    """Independently reconstruct in owned temporary storage, without input writes."""
    from tools.compute_governed_content_root import compute_governed_content_root

    try:
        # copytree dereferences links by default, so inspect the ORIGINAL first.
        _safe_files(pack, include_manifest=True, strict_directories=True)
        attestation = _read_object(attestation_path)
        current = attestation.get("schema_version") == "external-seal-attestation/v7"
        context = (config_path, recorded_config_locator, retained_manifest, retained_root)
        config, artifacts = None, None
        if current:
            if (
                config_path is None
                or recorded_config_locator is None
                or retained_manifest is None
                or retained_root is None
            ):
                raise ValueError("E_SEAL_PACK")
            from tools.assemble_review_pack import load_sealed_assembly_context

            config, artifacts = load_sealed_assembly_context(
                pack,
                config_path,
                recorded_config_locator,
                retained_manifest,
                retained_root,
            )
            _current_external_paths(pack, (zip_path, sidecar_path, attestation_path))
            receipt = _validate_inputs(pack, config, artifacts)
        elif any(value is not None for value in context):
            raise ValueError("E_SEAL_PACK")
        digest = _sha256(zip_path)
        if (
            attestation.get("schema_version")
            not in {"external-seal-attestation/v6", "external-seal-attestation/v7"}
            or attestation.get("artifact_type") != "RUNTIME_PACK"
            or attestation.get("authorized_production_phases") != "NONE"
            or attestation.get("zip_sha256") != digest
            or sidecar_path.read_text() != f"{digest}  {zip_path.name}\n"
        ):
            raise ValueError("E_SEAL_PACK")
        if current:
            from moj_discovery.schema_formats import _is_rfc3339_date_time

            if not isinstance(attestation["created_at"], str) or not _is_rfc3339_date_time(
                attestation["created_at"]
            ):
                raise ValueError("E_SEAL_PACK")
        else:
            datetime.fromisoformat(str(attestation["created_at"]).replace("Z", "+00:00"))
        with TemporaryDirectory() as temporary:
            root = Path(temporary)
            rebuilt = root / pack.name
            shutil.copytree(pack, rebuilt)
            compute_governed_content_root(
                rebuilt,
                rebuilt / "docs/registries/seal-exclusions.v1.json",
            )
            if current:
                # The original descendant chain was fully verified above. Rebuild
                # its deterministic envelope from that measured record, without
                # recursively verifying the same chain again in each writer.
                expected_json, expected_markdown = _self_review_bytes(receipt)
                (rebuilt / "SELF_REVIEW_REPORT.json").write_bytes(expected_json)
                (rebuilt / "SELF_REVIEW_REPORT.md").write_bytes(expected_markdown)
                manifest = _write_manifest(rebuilt)
                _write_zip(rebuilt, root / zip_path.name)
                (root / sidecar_path.name).write_text(
                    f"{_sha256(root / zip_path.name)}  {zip_path.name}\n"
                )
                expected = _attestation(rebuilt, root / zip_path.name, manifest, receipt)
            else:
                expected = seal_review_pack(
                    rebuilt,
                    root / zip_path.name,
                    root / sidecar_path.name,
                    root / attestation_path.name,
                )
            expected["created_at"] = attestation["created_at"]
            if (
                expected != attestation
                or (root / zip_path.name).read_bytes() != zip_path.read_bytes()
            ):
                raise ValueError("E_SEAL_PACK")
            if current and (
                any(
                    (rebuilt / name).read_bytes() != (pack / name).read_bytes()
                    for name in EXCLUSIONS
                )
                or (root / sidecar_path.name).read_bytes() != sidecar_path.read_bytes()
            ):
                raise ValueError("E_SEAL_PACK")
        if context_out is not None:
            context_out.clear()
            context_out.update(controller=config, artifacts=artifacts)
        return attestation
    except (OSError, ValueError, KeyError, TypeError, AttributeError) as error:
        raise ValueError("E_SEAL_PACK") from error


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--pack", required=True, type=Path)
    parser.add_argument("--zip", required=True, type=Path)
    parser.add_argument("--sidecar", required=True, type=Path)
    parser.add_argument("--attestation", required=True, type=Path)
    parser.add_argument("--config", type=Path)
    parser.add_argument("--recorded-config")
    parser.add_argument("--retained-manifest", type=Path)
    parser.add_argument("--retained-root", type=Path)
    args = parser.parse_args()
    context = (args.config, args.recorded_config, args.retained_manifest, args.retained_root)
    config, artifacts = None, None
    if any(value is not None for value in context):
        if not all(value is not None for value in context):
            raise ValueError("E_SEAL_PACK")
        # Direct governed CLI execution must work outside an installed package.
        import sys

        runtime_root = Path(__file__).resolve().parents[1]
        sys.path[:0] = [str(runtime_root), str(runtime_root / "src")]
        from tools.assemble_review_pack import load_sealed_assembly_context

        config, artifacts = load_sealed_assembly_context(args.pack, *context)
    result = seal_review_pack(
        args.pack,
        args.zip,
        args.sidecar,
        args.attestation,
        config=config,
        artifacts=artifacts,
    )
    print(json.dumps(result, sort_keys=True))


