     &&[ts.SyntaxKind.PlusPlusToken,ts.SyntaxKind.MinusMinusToken].includes(n.operator)&&!ts.isIdentifier(n.operand))
     ||((ts.isForOfStatement(n)||ts.isForInStatement(n))&&!ts.isVariableDeclarationList(n.initializer))))deny(file,'OPERATOR_WRITE');
  if((reader||ui)&&n.kind===ts.SyntaxKind.ThisKeyword)deny(file,'GLOBAL_ALIAS');
  if(ts.isIdentifier(n)&&reference(n)){
   const name=n.text, path=chain(maximal(n));
   if(!checker.getSymbolAtLocation(n)&&!globals.has(name))deny(file,'UNDECLARED_GLOBAL:'+name);
   if(forbidden.has(name))deny(file,'FORBIDDEN_GLOBAL');
   if(name==='chrome'&&!ts.isTypeOfExpression(n.parent)&&!(data.policy.chrome_owners[file]??[]).includes(path))deny(file,'CHROME_OWNER:'+path);
   if(name==='chrome'&&!ts.isTypeOfExpression(n.parent)&&path!=='chrome.runtime.id'){
    const use=maximal(n);if(!ts.isCallExpression(use.parent)||use.parent.expression!==use)deny(file,'CHROME_ALIAS');
   }
   if(name==='indexedDB'&&(file!==data.policy.indexeddb_owner||path!=='indexedDB.open'||!directCall(maximal(n))))deny(file,'STORAGE_OWNER');
   if(name==='WebSocket'){
    const call=n.parent;
    if(!data.policy.websocket_owners[file]||(!['WebSocket.OPEN','WebSocket.CLOSED','WebSocket.CLOSING','WebSocket.CONNECTING'].includes(path)
      &&(!ts.isNewExpression(call)||call.expression!==n||call.arguments?.length!==1||!ts.isStringLiteral(call.arguments[0])
      ||call.arguments[0].text!==data.policy.websocket_owners[file])))deny(file,'OUTBOUND_NETWORK');
   }
   if(name==='globalThis'&&!(reader&&ts.isVariableDeclaration(n.parent)&&n.parent.name.getText(source)==='global'))deny(file,'GLOBAL_ALIAS');
   if(reader&&name==='global'&&!initialized(n,'globalThis'))deny(file,'GLOBAL_ALIAS');
   if(reader&&fieldArray(n)&&!(ts.isVariableDeclaration(n.parent)&&n.parent.name===n)
      &&!(ts.isForOfStatement(n.parent)&&n.parent.expression===n)&&!ts.isSpreadElement(n.parent)
      &&!(path==='fields.map'&&directCall(maximal(n))))deny(file,'OPERATOR_FIELD_ALIAS');
   if(reader&&name==='global'&&!(ts.isVariableDeclaration(n.parent)&&n.parent.name===n)
      &&!(ts.isElementAccessExpression(n.parent)&&n.parent.expression===n&&ts.isStringLiteral(n.parent.argumentExpression)&&n.parent.argumentExpression.text==='BH_LIVE_READER_V1'))deny(file,'GLOBAL_ALIAS');
   if(['document','window','location','getSelection','getComputedStyle','MutationObserver','addEventListener'].includes(name)&&!reader&&!ui)deny(file,'DOM_OWNER');
   if(ui&&name==='window'&&!(path==='window.addEventListener'&&directCall(maximal(n))
      &&maximal(n).parent.arguments[0]?.getText(source)==='"pagehide"'))deny(file,'UI_WINDOW_ACCESS');
   if(ui&&name==='document'&&!['document.createElement','document.activeElement','document.querySelector','document.body.dataset'].includes(path)
      &&!ts.isTypeOfExpression(n.parent))deny(file,'UI_DOCUMENT_ACCESS');
   if(ui&&name==='location')deny(file,'NAVIGATION');
   if(reader&&name==='document'&&!['document.querySelector','document.querySelectorAll','document.visibilityState','document.documentElement','document.addEventListener'].includes(path)
      &&!(ts.isCallExpression(n.parent)&&chain(n.parent.expression)==='stableSelector'&&n.parent.arguments[1]===n))deny(file,'DOCUMENT_ACCESS');
   if(reader&&name==='location'&&path!=='location.href')deny(file,'NAVIGATION');
   if(reader&&['window'].includes(name))deny(file,'PAGE_CHANNEL');
  }
  if(ts.isCallExpression(n)){
   const path=chain(n.expression);
   if(path==='chrome.scripting.executeScript'){
    const compact=n.arguments[0]?.getText(source).replace(/\s/g,'').replaceAll("'",'"');
    if(compact!=='{target:{tabId:plan.tabId,frameIds:[0]},files:["src/live/dom_reader.js"],world:"ISOLATED"}')deny(file,'SCRIPT_TARGET');
   }
   if(reader&&['addEventListener','document.addEventListener'].includes(path)
      &&(!ts.isStringLiteral(n.arguments[0])||!['visibilitychange','pagehide','popstate','hashchange'].includes(n.arguments[0].text)))deny(file,'PAGE_CHANNEL');
  }
  ts.forEachChild(n,visit);
 };visit(source);modules.push({file,imports});
}
process.stdout.write(JSON.stringify({errors:[...new Set(errors)],modules}));
"""


def package_policy() -> dict[str, Any]:
    value = json.loads(POLICY.read_bytes())
    if (
        value["schema_version"] != "part-b-package-policy/v1"
        or value["production_authority"] != "NONE"
    ):
        raise ValueError("E_LIVE_PACKAGE_POLICY")
    return cast(dict[str, Any], value)


class Page(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.scripts: list[str] = []
        self.styles: list[str] = []
        self.in_script = False

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        values = dict(attrs)
        allowed = {
            "html": {"lang"},
            "head": set(),
            "title": set(),
            "body": {"data-live-workspace"},
            "header": set(),
            "main": set(),
            "h1": set(),
            "p": {"class"},
            "details": {"class"},
            "summary": set(),
            "ol": set(),
            "li": set(),
        }
        if len(values) != len(attrs):
            raise ValueError("E_LIVE_PACKAGE_HTML")
        if tag == "script":
            if set(values) != {"src", "type"} or values["type"] != "module":
                raise ValueError("E_LIVE_PACKAGE_HTML")
            self.scripts.append(str(values["src"]))
            self.in_script = True
        elif tag == "link":
            if values != {"rel": "stylesheet", "href": "panel.css"}:
                raise ValueError("E_LIVE_PACKAGE_HTML")
            self.styles.append("panel.css")
        elif tag == "meta":
            if values not in (
                {"charset": "utf-8"},
                {"name": "viewport", "content": "width=device-width,initial-scale=1"},
            ):
                raise ValueError("E_LIVE_PACKAGE_HTML")
        elif tag not in allowed or set(values) - allowed[tag]:
            raise ValueError("E_LIVE_PACKAGE_HTML")

    def handle_endtag(self, tag: str) -> None:
        if tag == "script":
            self.in_script = False

    def handle_data(self, data: str) -> None:
        if self.in_script and data.strip():
            raise ValueError("E_LIVE_PACKAGE_HTML")


def verify_live_package(directory: Path) -> dict[str, Any]:
    policy = package_policy()
    expected = {
        "manifest.json",
        *policy["assets"],
        *policy["generated_modules"],
        *("src/" + name for name in policy["shared_modules"]),
        *("src/live/" + name + ".js" for name in policy["live_modules"]),
    }
    if directory.resolve() != directory or not directory.is_dir():
        raise ValueError("E_LIVE_PACKAGE_PATH")
    files = {}
    for path in directory.rglob("*"):
        if path.resolve() != path or not (path.is_dir() or path.is_file()):
            raise ValueError("E_LIVE_PACKAGE_PATH")
        if path.is_file():
            if path.stat().st_nlink != 1 or path.stat().st_size > 4 * 1024 * 1024:
                raise ValueError("E_LIVE_PACKAGE_PATH")
            files[path.relative_to(directory).as_posix()] = path.read_bytes()
    if set(files) != expected:
        raise ValueError("E_LIVE_PACKAGE_INVENTORY")
    manifest = json.loads(files["manifest.json"])
    identity = {"name", "version", "description", "key"}
    if (
        set(manifest) != set(policy["manifest"]) | identity
        or any(manifest[name] != value for name, value in policy["manifest"].items())
        or manifest != json.loads((ROOT / "extension/manifest.live.json").read_bytes())
    ):
        raise ValueError("E_LIVE_PACKAGE_MANIFEST")
    for name in ("src/live/panel.html", "src/live/workspace.html"):
        page = Page()
        page.feed(files[name].decode())
        if page.scripts != ["workspace.js"] or page.styles != ["panel.css"]:
            raise ValueError("E_LIVE_PACKAGE_HTML")
    css = files["src/live/panel.css"].decode().lower()
    if "url(" in css or "@import" in css:
        raise ValueError("E_LIVE_PACKAGE_CSS")
    node = shutil.which("node")
    if not node:
        raise ValueError("E_LIVE_PACKAGE_NODE")
    result = subprocess.run(  # noqa: S603 -- fixed parser, emitted code is parsed, never executed.
        [node, "-e", AST_CHECK, str(ROOT / "extension/node_modules/typescript")],
        input=json.dumps(
            {
                "sources": {k: v.decode() for k, v in files.items() if k.endswith(".js")},
                "policy": policy,
            }
        ),
        capture_output=True,
        text=True,
        timeout=30,
        check=True,
    )
    observed = json.loads(result.stdout)
    if observed["errors"]:
        raise ValueError("E_LIVE_PACKAGE_CAPABILITY:" + ",".join(observed["errors"]))
    for module in observed["modules"]:
        for imported in module["imports"]:
            if (
                not imported.startswith(".")
                or "\\" in imported
                or "?" in imported
                or "#" in imported
            ):
                raise ValueError("E_LIVE_PACKAGE_IMPORT")
            target = (directory / PurePosixPath(module["file"]).parent / imported).resolve()
            if (
                not target.is_relative_to(directory)
                or target.relative_to(directory).as_posix() not in expected
            ):
                raise ValueError("E_LIVE_PACKAGE_IMPORT")
    return {
        "schema_version": "part-b-package-boundary/v1",
        "result": "PASS",
        "scope": "STATIC_PACKAGE_BOUNDARY_ONLY",
        "production_authority": "NONE",
        "independent_review": "NOT_INFERRED",
        "policy_sha256": hashlib.sha256(POLICY.read_bytes()).hexdigest(),
        "files": {name: hashlib.sha256(raw).hexdigest() for name, raw in sorted(files.items())},
    }"""Run bounded local checks or fail closed before legacy full qualification."""

from __future__ import annotations

import argparse
import ast
import hashlib
import json
import os
import shutil
import stat
import subprocess
import sys
from collections.abc import Sequence
from pathlib import Path, PurePosixPath
from typing import Any, cast

REPOSITORY_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPOSITORY_ROOT))

from tools import run_command_registry  # noqa: E402
from tools.build_candidate_qualification_receipt import (  # noqa: E402
    validate_candidate_qualification_receipt,
)
from tools.full_verifier_config import FullVerifierConfig, load_controller_config  # noqa: E402
from tools.sync_pack_assets import sync_pack_assets  # noqa: E402

REPAIR_TESTS = (
    "tests/repairs/test_restart_evidence_boundary.py",
    "tests/repairs/test_clock_raw_input.py",
    "tests/repairs/test_clock_dispatch_completeness.py",
    "tests/repairs/test_clock_qualification_records.py",
)
PYTEST_CACHE = "cache_dir=.local/bh-repair/pytest-cache"


def _display_argv(argv: Sequence[str]) -> list[str]:
    displayed = list(argv)
    executable = Path(displayed[0])
    if executable.is_absolute():
        try:
            displayed[0] = executable.relative_to(REPOSITORY_ROOT).as_posix()
        except ValueError:
            displayed[0] = executable.name
    return displayed


def _portable_commands() -> tuple[tuple[str, list[str]], ...]:
    pytest = [sys.executable, "-m", "pytest"]
    return (
        (
            "compile_all_tests",
            ["pnpm", "--dir", "extension", "exec", "tsc", "-p", "tsconfig.test.json"],
        ),
        (
            "registry_self_check",
            [sys.executable, "tools/run_command_registry.py", "--self-check"],
        ),
        (
            "implemented_repair_tests",
            [*pytest, "-q", *REPAIR_TESTS, "-o", PYTEST_CACHE],
        ),
        (
            "collect_all_repair_tests",
            [*pytest, "--collect-only", "-q", "tests/repairs", "-o", PYTEST_CACHE],
        ),
    )


def _portable_timeout(check_id: str) -> int:
    return 900 if check_id == "implemented_repair_tests" else 300


def _portable_environment() -> dict[str, str]:
    environment = {
        key: value for key, value in os.environ.items() if not key.startswith(("PYTEST_", "PYTHON"))
    }
    environment.update(
        {
            "NPM_CONFIG_IGNORE_SCRIPTS": "true",
            "PYTEST_DISABLE_PLUGIN_AUTOLOAD": "1",
            "PYTHONDONTWRITEBYTECODE": "1",
            "UV_NO_PROGRESS": "1",
            "UV_PYTHON_DOWNLOADS": "never",
        }
    )
    return environment


def _captured_text(value: str | bytes | None) -> str:
    if isinstance(value, bytes):
        return value.decode(errors="replace")
    return value or ""


def _run_portable() -> int:
    environment = _portable_environment()
    results: list[dict[str, object]] = []
    for check_id, argv in _portable_commands():
        try:
            completed = subprocess.run(  # noqa: S603 - fixed repo-owned command list.
                argv,
                cwd=REPOSITORY_ROOT,
                env=environment,
                capture_output=True,
                text=True,
                check=False,
                timeout=_portable_timeout(check_id),
            )
            result: dict[str, object] = {
                "check_id": check_id,
                "argv": _display_argv(argv),
                "exit_code": completed.returncode,
                "stdout": completed.stdout,
                "stderr": completed.stderr,
            }
        except subprocess.TimeoutExpired as error:
            partial_stderr = _captured_text(error.stderr)
            result = {
                "check_id": check_id,
                "argv": _display_argv(argv),
                "exit_code": None,
                "stdout": _captured_text(error.stdout),
                "stderr": "\n".join(
                    part for part in (partial_stderr, f"{type(error).__name__}: {error}") if part
                ),
            }
        except OSError as error:
            result = {
                "check_id": check_id,
                "argv": _display_argv(argv),
                "exit_code": None,
                "stdout": "",
                "stderr": f"{type(error).__name__}: {error}",
            }
        results.append(result)
        if result["exit_code"] != 0:
            break
    passed = len(results) == len(_portable_commands()) and all(
        result["exit_code"] == 0 for result in results
    )
    print(
        json.dumps(
            {
                "schema_version": "local-verification-report/v1",
                "profile": "portable",
                "status": "PASS" if passed else "FAIL",
                "production_authority": "NONE",
                "results": results,
            },
            sort_keys=True,
        )
    )
    return 0 if passed else 1


def _configured_path(identifier: str, path: Path | None, *, directory: bool) -> dict[str, object]:
    record: dict[str, object] = {"prerequisite_id": identifier, "path": None}
    if path is None:
        return {**record, "status": "MISSING_CONFIGURATION"}
    record["path"] = str(path)
    if not path.is_absolute():
        return {**record, "status": "INVALID", "detail": "path must be absolute"}
    try:
        resolved = path.resolve(strict=True)
    except OSError as error:
        return {**record, "status": "MISSING", "detail": str(error)}
    record["path"] = str(resolved)
    valid = resolved.is_dir() if directory else resolved.is_file()
    return {**record, "status": "PASS" if valid else "INVALID"}


def _configured_output_directory(identifier: str, path: Path) -> dict[str, object]:
    record: dict[str, object] = {"prerequisite_id": identifier, "path": str(path)}
    if not path.is_absolute() or path.is_symlink():
        return {**record, "status": "INVALID"}
    if path.exists():
        return {**record, "status": "PASS" if path.is_dir() else "INVALID"}
    try:
        parent = path.parent.resolve(strict=True)
    except OSError as error:
        return {**record, "status": "MISSING", "detail": str(error)}
    return {**record, "status": "PASS" if parent.is_dir() else "INVALID"}


def _sha256_file(path: Path) -> str:
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def _load_object(path: Path) -> dict[str, Any]:
    value = json.loads(path.read_text())
    if not isinstance(value, dict):
        raise ValueError("JSON root is not an object")
    return cast(dict[str, Any], value)


def _git_output(root: Path, *args: str) -> str:
    git = shutil.which("git")
    if git is None:
        raise ValueError("receipt content mismatch")
    completed = subprocess.run(  # noqa: S603 - fixed git executable and read-only args.
        [git, "-C", str(root), *args],
        capture_output=True,
        text=True,
        check=False,
        timeout=30,
    )
    if completed.returncode != 0:
        raise ValueError("receipt content mismatch")
    return completed.stdout.strip()


def _validate_bootstrap_receipt(receipt_path: Path, pack: Path, accepted_ancestor: str) -> None:
    receipt = _load_object(receipt_path)
    authoring_root = pack.resolve(strict=True).parent
    if (
        set(receipt)
        != {
            "schema_version",
            "accepted_authoring_ancestor",
            "root",
            "head",
            "tree",
            "status",
        }
        or receipt.get("schema_version") != "current-authoring-repository-receipt/v1"
        or receipt.get("accepted_authoring_ancestor") != accepted_ancestor
        or receipt.get("root") != str(authoring_root)
        or receipt.get("head") != _git_output(authoring_root, "rev-parse", "HEAD")
        or receipt.get("tree") != _git_output(authoring_root, "rev-parse", "HEAD^{tree}")
        or receipt.get("status") != ""
        or _git_output(authoring_root, "status", "--porcelain", "--untracked-files=all")
    ):
        raise ValueError("receipt content mismatch")
    _git_output(
        authoring_root,
        "merge-base",
        "--is-ancestor",
        accepted_ancestor,
        cast(str, receipt["head"]),
    )


def _validate_authoring_tests(root: Path, expected_sha256: str | None = None) -> str:
    delivery = _load_object(
        REPOSITORY_ROOT / "vendor/hybrid-discovery-v6.3.6/docs/registries/delivery-map.v1.json"
    )
    exports = delivery.get("authoring_source_exports")
    if not isinstance(exports, list):
        raise ValueError("E_EXTERNAL_AUTHORING_TESTS")
    expected: set[str] = set()
    destinations: set[str] = set()
    for item in exports:
        if (
            not isinstance(item, dict)
            or set(item) != {"source", "destination", "owner"}
            or item["owner"] != "V636-P09-T01"
        ):
            raise ValueError("E_EXTERNAL_AUTHORING_TESTS")
        for field in ("source", "destination"):
            value = item[field]
            if (
                not isinstance(value, str)
                or not value
                or "\\" in value
                or "\0" in value
                or PurePosixPath(value).is_absolute()
                or PurePosixPath(value).as_posix() != value
                or any(part in {".", ".."} for part in PurePosixPath(value).parts)
            ):
                raise ValueError("E_EXTERNAL_AUTHORING_TESTS")
        name, destination = item["source"], item["destination"]
        if (
            name in expected
            or destination in destinations
            or PurePosixPath(destination).parts[:2] != ("pack", "authoring-source")
            or len(PurePosixPath(destination).parts) < 3
        ):
            raise ValueError("E_EXTERNAL_AUTHORING_TESTS")
        expected.add(name)
        destinations.add(destination)
    python_expected = {
        name for name in expected if name.startswith(("authoring-tests/", "authoring-tools/"))
    }
    if not python_expected:
        raise ValueError("E_EXTERNAL_AUTHORING_TESTS")
    authoring_root = root.parent
    actual_paths = {
        path.relative_to(authoring_root).as_posix()
        for directory in (authoring_root / "authoring-tests", authoring_root / "authoring-tools")
        for path in directory.rglob("*.py")
        if path.is_file()
    }
    if actual_paths != python_expected:
        raise ValueError("E_EXTERNAL_AUTHORING_TESTS")
    rows: list[tuple[str, int, str]] = []
    for name in sorted(expected, key=lambda item: item.encode()):
        path = authoring_root / name
        try:
            info = path.lstat()
            if (
                path.is_symlink()
                or not stat.S_ISREG(info.st_mode)
                or info.st_nlink != 1
                or path.resolve(strict=True) != path
            ):
                raise ValueError("E_EXTERNAL_AUTHORING_TESTS")
            contents = path.read_bytes()
            source = contents.decode("utf-8") if name in python_expected else ""
        except (OSError, UnicodeError, RuntimeError) as error:
            raise ValueError("E_EXTERNAL_AUTHORING_TESTS") from error
        if not contents:
            raise ValueError("E_EXTERNAL_AUTHORING_TESTS")
        if name.startswith("authoring-tests/"):
            try:
                tree = ast.parse(source)
            except SyntaxError as error:
                raise ValueError("E_EXTERNAL_AUTHORING_TESTS") from error
            if not any(
                isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
                and node.name.startswith("test_")
                for node in ast.walk(tree)
            ):
                raise ValueError("E_EXTERNAL_AUTHORING_TESTS")
        rows.append((name, len(contents), hashlib.sha256(contents).hexdigest()))
    payload = "".join(f"{name}\0{size}\0{digest}\n" for name, size, digest in rows).encode()
    digest = hashlib.sha256(payload).hexdigest()
    if expected_sha256 is not None and digest != expected_sha256:
        raise ValueError("E_EXTERNAL_AUTHORING_TESTS")
    return digest


def _external_authoring_environment(config: FullVerifierConfig) -> dict[str, str]:
    environment = run_command_registry.execution_environment(config)
    environment.update({"PYTEST_DISABLE_PLUGIN_AUTOLOAD": "1", "PYTHONDONTWRITEBYTECODE": "1"})
    return environment


def _execute_external_authoring_suite(config: FullVerifierConfig) -> dict[str, object]:
    completed = subprocess.run(  # noqa: S603 - exact argv is source-owned configuration.
        list(config.external_authoring_argv),
        cwd=config.external_authoring_cwd,
        env=_external_authoring_environment(config),
        capture_output=True,
        check=False,
    )
    stdout = completed.stdout
    stderr = completed.stderr
    record: dict[str, object] = {
        "argv": list(config.external_authoring_argv),
        "cwd": str(config.external_authoring_cwd),
        "exit_code": completed.returncode,
        "passed": completed.returncode == 0,
        "stdout_sha256": hashlib.sha256(stdout).hexdigest(),
        "stdout_size_bytes": str(len(stdout)),
        "stderr_sha256": hashlib.sha256(stderr).hexdigest(),
        "stderr_size_bytes": str(len(stderr)),
    }
    if completed.returncode == 0:
        run_command_registry.validate_external_authoring_result(record, config)
    return record


def _nonempty_directory(path: Path) -> bool:
    return path.is_dir() and not path.is_symlink() and next(path.iterdir(), None) is not None


def _validate_cache(root: Path, kind: str) -> None:
    if kind == "uv":
        tag = root / "CACHEDIR.TAG"
        valid = (
            tag.is_file()
            and bool(tag.read_bytes())
            and any(
                child.name.startswith(("archive-v", "wheels-v", "simple-v", "sdists-v"))
                and _nonempty_directory(child)
                for child in root.iterdir()
            )
        )
        code = "E_UV_CACHE"
    elif kind == "pnpm":
        valid = all(_nonempty_directory(root / name) for name in ("files", "index"))
        code = "E_PNPM_STORE"
    else:
        raise ValueError("E_CACHE_KIND")
    if not valid:
        raise ValueError(code)


def _controller_binding(config: FullVerifierConfig) -> dict[str, object]:
    try:
        registry = run_command_registry.validate_registry()
        commands = run_command_registry.effective_candidate_commands(registry, config)
        environment = run_command_registry.execution_environment(config)
    except (OSError, ValueError, json.JSONDecodeError) as error:
        return {
            "prerequisite_id": "controller_configuration_binding",
            "path": str(config.source_path),
            "status": "HOLD",
            "code": "CONTROLLER_CONFIG_UNBOUND",
            "detail": str(error),
        }
    external = next(
        (
            item
            for item in cast(list[dict[str, object]], registry["commands"])
            if item["command_id"] == "VERIFY_EXTERNAL_AUTHORING_SOURCES"
        ),
        None,
    )
    if (
        {Path(cast(str, command["cwd"])) for command in commands} != {config.current_checkout_root}
        or external is None
        or external.get("cwd") != str(config.external_authoring_cwd)
        or external.get("argv") != list(config.external_authoring_argv)
        or environment.get("UV_CACHE_DIR") != str(config.uv_cache)
        or environment.get("npm_config_store_dir") != str(config.pnpm_store)
        or environment.get("BH_CHROME_BINARY") != str(config.chrome_path)
        or environment.get("UV_OFFLINE") != "1"
        or environment.get("npm_config_offline") != "true"
    ):
        return {
            "prerequisite_id": "controller_configuration_binding",
            "path": str(config.source_path),
            "status": "HOLD",
            "code": "CONTROLLER_CONFIG_UNBOUND",
        }
    return {
        "prerequisite_id": "controller_configuration_binding",
        "path": str(config.source_path),
        "status": "PASS",
    }


def _full_prerequisites(config: FullVerifierConfig) -> list[dict[str, object]]:
    source_config = _configured_path(
        "source_owned_controller_config", config.source_path, directory=False
    )
    pack = _configured_path("governed_source_pack", config.governed_source_pack, directory=True)
    if pack["status"] == "PASS":
        try:
            sync_pack_assets(Path(cast(str, pack["path"])), REPOSITORY_ROOT, check=True)
        except (OSError, ValueError, json.JSONDecodeError) as error:
            pack.update(status="INVALID", detail=str(error))

    evidence = _configured_output_directory("evidence_root", config.evidence_root)
    bootstrap: dict[str, object] = {
        "prerequisite_id": "authoring_repository_receipt",
        "path": None,
        "status": "MISSING_CONFIGURATION",
    }
    if evidence["status"] == "PASS":
        bootstrap_path = config.authoring_repository_receipt
        bootstrap = _configured_path(
            "authoring_repository_receipt", bootstrap_path, directory=False
        )
        if bootstrap["status"] == "PASS":
            try:
                if pack["status"] != "PASS":
                    raise ValueError("receipt content mismatch")
                _validate_bootstrap_receipt(
                    bootstrap_path,
                    Path(cast(str, pack["path"])),
                    config.accepted_authoring_ancestor,
                )
            except (OSError, ValueError, json.JSONDecodeError, subprocess.SubprocessError) as error:
                bootstrap.update(status="INVALID", detail=str(error))

    uv_cache = _configured_path("uv_cache", config.uv_cache, directory=True)
    pnpm_store = _configured_path("pnpm_store", config.pnpm_store, directory=True)
    authoring_tests = _configured_path(
        "external_authoring_tests", config.external_authoring_tests, directory=True
    )
    if authoring_tests["status"] == "PASS":
        try:
            _validate_authoring_tests(
                Path(cast(str, authoring_tests["path"])),
                config.external_authoring_source_sha256,
            )
        except (OSError, ValueError) as error:
            authoring_tests.update(status="INVALID", detail=str(error))
    for record, kind in ((uv_cache, "uv"), (pnpm_store, "pnpm")):
        if record["status"] == "PASS":
            try:
                _validate_cache(Path(cast(str, record["path"])), kind)
            except (OSError, ValueError) as error:
                record.update(status="INVALID", detail=str(error))
    chrome = _configured_path("chrome_binary", config.chrome_path, directory=False)
    if chrome["status"] == "PASS":
        chrome_path = Path(cast(str, chrome["path"]))
        digest = _sha256_file(chrome_path)
        if not os.access(chrome_path, os.X_OK) or digest != config.chrome_sha256:
            chrome.update(status="INVALID", detail="executable bit or SHA-256 mismatch")

    return [
        source_config,
        pack,
        evidence,
        bootstrap,
        authoring_tests,
        uv_cache,
        pnpm_store,
        chrome,
        _controller_binding(config),
    ]


def _delegate_controller(config: FullVerifierConfig) -> int:
    from tools import phase_evidence

    config.evidence_root.mkdir(parents=True, exist_ok=True)
    # A campaign is exclusive. Keep interrupted observations and choose a new
    # source-owned evidence root instead of executing over partial outputs.
    if (
        config.candidate_command_evidence.exists()
        or (config.evidence_root / "command-logs").exists()
    ):
        print("E_CONTROLLER_CAMPAIGN_EXISTS: use a new declared evidence root", flush=True)
        return 1
    try:
        current_phases = phase_evidence.contract(config)
        campaign_identity = (
            run_command_registry._git_source_identity(REPOSITORY_ROOT)
            if current_phases is not None
            else None
        )
        external_result = _execute_external_authoring_suite(config)
        if external_result["passed"] is not True:
            return 1
        _validate_bootstrap_receipt(
            config.authoring_repository_receipt,
            config.governed_source_pack,
            config.accepted_authoring_ancestor,
        )
        _validate_authoring_tests(
            config.external_authoring_tests,
            config.external_authoring_source_sha256,
        )
        registry = run_command_registry.validate_registry()
    except (OSError, ValueError, json.JSONDecodeError, subprocess.SubprocessError):
        return 1

    def recheck_campaign() -> None:
        if current_phases is not None:
            if campaign_identity != run_command_registry._git_source_identity(REPOSITORY_ROOT):
                raise ValueError("E_CONTROLLER_SOURCE_DRIFT")
            _validate_authoring_tests(
                config.external_authoring_tests, config.external_authoring_source_sha256
            )

    def execute(command_id: str) -> dict[str, object]:
        recheck_campaign()
        command = next(
            (
                item
                for item in cast(list[dict[str, object]], registry["commands"])
                if item["command_id"] == command_id
            ),
            None,
        )
        if command is None:
            raise ValueError("E_CONTROLLER_DAG")
        cwd = Path(cast(str, command["cwd"]))
        if cwd != REPOSITORY_ROOT:
            if (
                current_phases is None
                or command_id not in phase_evidence.CURRENT_COMMANDS
                or cwd != config.external_authoring_cwd
            ):
                raise ValueError("E_CONTROLLER_DAG")
            _validate_authoring_tests(
                config.external_authoring_tests, config.external_authoring_source_sha256
            )
        result = run_command_registry.evaluate_invocation(
            command,
            environment=run_command_registry.execution_environment(config),
            working_directory=cwd,
            **(
                {"log_directory": config.evidence_root / "command-logs"}
                if current_phases is not None
                else {}
            ),
        )
        if result.get("passed") is not True:
            raise RuntimeError(f"E_CONTROLLER_DAG:{command_id}")
        recheck_campaign()
        return result

    try:
        phase_results = []
        if current_phases is not None:
            for command_id in sorted(phase_evidence.CURRENT_COMMANDS):
                phase_results.append(execute(command_id))
            with (config.evidence_root / "CURRENT_INPUTS.json").open("x") as stream:
                json.dump(
                    {
                        "source_identity": campaign_identity,
                        "results": phase_results,
                        "controller_binding": config.binding(),
                    },
                    stream,
                    sort_keys=True,
                )
                stream.write("\n")
            execute("CAPTURE_V636_SUPPLEMENTAL_ENVIRONMENT")
        execute("VERIFY_V636_P07_T01")
        command_evidence = _load_object(config.candidate_command_evidence)
        command_evidence["schema_version"] = "candidate-command-results/v3"
        command_evidence["external_authoring_result"] = external_result
        config.candidate_command_evidence.write_text(
            json.dumps(command_evidence, sort_keys=True, separators=(",", ":")) + "\n"
        )
        if current_phases is not None:
            execute("ISSUE_CURRENT_PHASE_PROOFS")
        execute("VERIFY_V636_P07_T02")
        issuance = execute("VERIFY_V636_P07_T03")
        config.candidate_issuance_evidence.write_text(
            json.dumps(
                {
                    "schema_version": "candidate-issuance-result/v1",
                    "result": "PASS",
                    "production_authority": "NONE",
                    "controller_binding": config.binding(),
                    "command": issuance,
                    "proof_coverage_sha256": _sha256_file(config.proof_coverage_evidence),
                },
                sort_keys=True,
                separators=(",", ":"),
            )
            + "\n"
        )
    except (OSError, RuntimeError, ValueError, json.JSONDecodeError) as error:
        print(str(error), flush=True)
        return 1
    return 0


def _validate_candidate_postcondition(config: FullVerifierConfig) -> None:
    validate_candidate_qualification_receipt(
        REPOSITORY_ROOT,
        config.candidate_command_evidence,
        _load_object(config.candidate_qualification_receipt),
        config,
    )


def _run_full(config: FullVerifierConfig | None) -> int:
    prerequisites: list[dict[str, object]]
    if config is None:
        prerequisites = [
            {
                "prerequisite_id": "source_owned_controller_config",
                "path": None,
                "status": "MISSING_CONFIGURATION",
                "code": "CONTROLLER_CONFIG_UNBOUND",
            }
        ]
    else:
        prerequisites = _full_prerequisites(config)
    ready = all(item["status"] == "PASS" for item in prerequisites)
    hold_codes = sorted(
        cast(str, item["code"]) for item in prerequisites if isinstance(item.get("code"), str)
    )
    print(
        json.dumps(
            {
                "schema_version": "full-verification-prerequisites/v1",
                "profile": "full",
                "status": "READY" if ready else "HOLD",
                "production_authority": "NONE",
                "authoritative_controller": "PENDING" if ready else "NOT_EXECUTED",
                "hold_codes": hold_codes,
                "prerequisites": prerequisites,
            },
            sort_keys=True,
        ),
        flush=True,
    )
    if not ready:
        return 2
    assert config is not None
    result = _delegate_controller(config)
    if result != 0:
        return result
    try:
        _validate_candidate_postcondition(config)
    except (OSError, ValueError, json.JSONDecodeError):
        return 1
    return 0


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--profile", choices=("portable", "full"), required=True)
    parser.add_argument("--config", type=Path)
    parser.add_argument("--pack", type=Path)
    parser.add_argument("--evidence-root", type=Path)
    parser.add_argument("--authoring-tests", type=Path)
    parser.add_argument("--uv-cache", type=Path)
    parser.add_argument("--pnpm-store", type=Path)
    parser.add_argument("--chrome", type=Path)
    parser.add_argument("--chrome-sha256")
    args = parser.parse_args(argv)
    if args.profile == "portable":
        return _run_portable()
    if any(
        value is not None
        for value in (
            args.pack,
            args.evidence_root,
            args.authoring_tests,
            args.uv_cache,
            args.pnpm_store,
            args.chrome,
            args.chrome_sha256,
        )
    ):
        return _run_full(None)
    if args.config is None:
        return _run_full(None)
    try:
        config = load_controller_config(args.config)
    except ValueError:
        return _run_full(None)
    return _run_full(config)


if __name__ == "__main__":
    raise SystemExit(main())import argparse
import hashlib
import sys
import unicodedata
from pathlib import Path, PurePosixPath

from jsonschema import Draft202012Validator  # type: ignore[import-untyped]

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from moj_discovery.canonical import parse_strict_json
from moj_discovery.vendor import verify_vendored_assets
from tools.sync_pack_assets import MANIFEST, _tree_files


def _relative(value: object, *, prefix: str = "") -> str:
    if not isinstance(value, str) or "\\" in value or not value.startswith(prefix):
        raise ValueError("E_NORMATIVE:PATH")
    path = PurePosixPath(value)
    if (
        path.is_absolute()
        or path.as_posix() != value
        or any(
            part in {"", ".", ".."} or unicodedata.normalize("NFC", part) != part
            for part in path.parts
        )
    ):
        raise ValueError("E_NORMATIVE:PATH")
    return value


def _object(path: Path) -> dict[str, object]:
    value = parse_strict_json(path.read_bytes())
    if not isinstance(value, dict):
        raise ValueError(f"E_NORMATIVE:OBJECT:{path}")
    return value


def _pointer(document: object, pointer: object) -> None:
    if not isinstance(pointer, str) or not pointer.startswith("#/"):
        raise ValueError("E_NORMATIVE:POINTER")
    value = document
    for part in pointer[2:].split("/"):
        part = part.replace("~1", "/").replace("~0", "~")
        if not isinstance(value, dict) or part not in value:
            raise ValueError("E_NORMATIVE:POINTER")
        value = value[part]


def _sha256(content: bytes) -> str:
    return hashlib.sha256(content).hexdigest()


def _normative_entries(pack: Path, vendor: Path) -> dict[str, tuple[dict[str, object], bytes]]:
    source_map = _object(pack / "docs/registries/normative-source-map.v1.json")
    if (
        source_map.get("schema_version") != "normative-source-map/v1"
        or source_map.get("owner_phase") != "MIG0"
        or source_map.get("vendor_prefix") != "runtime/vendor/hybrid-discovery-v6.3.6/"
        or source_map.get("plan_namespace") != "docs/"
    ):
        raise ValueError("E_NORMATIVE:MAP")
    inherited = source_map.get("inherited_entries")
    plan_entries = source_map.get("plan_entries")
    overrides = source_map.get("graph_overrides")
    if (
        not isinstance(inherited, list)
        or not isinstance(plan_entries, list)
        or not isinstance(overrides, list)
    ):
        raise ValueError("E_NORMATIVE:MAP")
    override_paths = {_relative(item) for item in overrides}
    if override_paths != {
        "graphs/executable-discovery-graph.v1.json",
        "graphs/non-authoritative-future-roadmap.v1.json",
    }:
        raise ValueError("E_NORMATIVE:MAP")
    pack_files = {path.relative_to(pack).as_posix(): path for path in _tree_files(pack)}
    vendor_files = {path.relative_to(vendor).as_posix(): path for path in _tree_files(vendor)}
    effective: dict[str, tuple[dict[str, object], bytes]] = {}
    sources: set[str] = set()
    for raw in [*inherited, *plan_entries]:
        if not isinstance(raw, dict):
            raise ValueError("E_NORMATIVE:MAP")
        source = _relative(raw.get("plan_source"), prefix="docs/")
        destination = _relative(raw.get("vendor_relative"))
        if source in sources or source not in pack_files:
            raise ValueError("E_NORMATIVE:MAP")
        sources.add(source)
        source_bytes = pack_files[source].read_bytes()
        source_hash = raw.get("source_sha256")
        normalized_hash = raw.get("plan_sha256")
        expected = source_bytes
        expected_hash = normalized_hash if normalized_hash is not None else source_hash
        if expected_hash is not None and (
            not isinstance(expected_hash, str) or _sha256(expected) != expected_hash
        ):
            raise ValueError("E_NORMATIVE:SOURCE_HASH")
        if destination in effective and destination not in override_paths:
            raise ValueError("E_NORMATIVE:COLLISION")
        effective[destination] = (raw, expected)
    if set(vendor_files) != set(effective) | {MANIFEST}:
        raise ValueError("E_NORMATIVE:FILE_SET")
    for destination, (_, expected) in effective.items():
        if vendor_files[destination].read_bytes() != expected:
            raise ValueError(f"E_NORMATIVE:BYTES:{destination}")
    return effective


def _verify_schema_references(
    pack: Path,
    vendor: Path,
    entries: dict[str, tuple[dict[str, object], bytes]],
) -> None:
    registry = _object(pack / "docs/registries/schema-reference-registry.v1.json")
    references = registry.get("references")
    if (
        registry.get("schema_version") != "schema-reference-registry/v2"
        or not isinstance(references, list)
    ):
        raise ValueError("E_NORMATIVE:SCHEMA_REFERENCE")
    prefix = "runtime/vendor/hybrid-discovery-v6.3.6/"
    names: set[str] = set()
    for reference in references:
        if not isinstance(reference, dict):
            raise ValueError("E_NORMATIVE:SCHEMA_REFERENCE")
        name = reference.get("logical_name")
        plan_path = _relative(
            reference.get("plan_source_path"), prefix="pack/docs/"
        ).removeprefix("pack/")
        runtime_path = _relative(
            reference.get("materialized_runtime_path"), prefix=prefix
        ).removeprefix(prefix)
        if (
            not isinstance(name, str)
            or name in names
            or plan_path != runtime_path
            or runtime_path not in entries
        ):
            raise ValueError("E_NORMATIVE:SCHEMA_REFERENCE")
        names.add(name)
        source = _object(pack / plan_path)
        materialized = _object(vendor / runtime_path)
        Draft202012Validator.check_schema(source)
        Draft202012Validator.check_schema(materialized)
        if (pack / plan_path).read_bytes() != (vendor / runtime_path).read_bytes():
            raise ValueError("E_NORMATIVE:SCHEMA_BYTES")
        _pointer(source, reference.get("json_pointer"))


def _verify_cdp_lock(pack: Path, vendor: Path) -> None:
    lock = _object(pack / "docs/inherited/v6.2/security/cdp-protocol-lock.v1.json")
    files = lock.get("files")
    if not isinstance(files, list):
        raise ValueError("E_NORMATIVE:CDP")
    for item in files:
        if not isinstance(item, dict):
            raise ValueError("E_NORMATIVE:CDP")
        relative = _relative(item.get("path"))
        path = vendor / "cdp" / relative
        if (
            not path.is_file()
            or path.stat().st_size != item.get("size_bytes")
            or _sha256(path.read_bytes()) != item.get("sha256")
        ):
            raise ValueError(f"E_NORMATIVE:CDP:{relative}")


def _verify_task_manifest(pack: Path) -> None:
    plan = _object(pack / "plan-manifest.json")
    schema = _object(pack / "docs/schemas/task-card-v6.3.6.schema.json")
    tasks = _object(pack / "docs/tasks/task-manifest.v6.3.6.json")
    error = next(
        Draft202012Validator(schema)
        .evolve(schema={"$ref": "#/$defs/TaskManifestV636"})
        .iter_errors(tasks),
        None,
    )
    task_rows = tasks.get("tasks")
    if error is not None or (
        plan.get("schema_version") != "hybrid-discovery-v6.3.6-plan/v1"
        or plan.get("authorized_production_phases") != "NONE"
        or plan.get("task_manifest") != "docs/tasks/task-manifest.v6.3.6.json"
        or plan.get("task_schema")
        != "pack/docs/schemas/task-card-v6.3.6.schema.json#/$defs/TaskManifestV636"
        or plan.get("task_count") != tasks.get("declared_task_count")
        or not isinstance(task_rows, list)
        or plan.get("task_count") != len(task_rows)
    ):
        raise ValueError("E_NORMATIVE:PLAN:BINDING")


def verify_normative_bundle(pack: Path, runtime: Path) -> None:
    pack = pack.resolve()
    runtime = runtime.resolve()
    vendor = runtime / "vendor/hybrid-discovery-v6.3.6"
    entries = _normative_entries(pack, vendor)
    verify_vendored_assets(runtime)
    _verify_schema_references(pack, vendor, entries)
    _verify_cdp_lock(pack, vendor)
    _verify_task_manifest(pack)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--pack", type=Path, required=True)
    parser.add_argument("--runtime", type=Path, required=True)
    args = parser.parse_args()
    verify_normative_bundle(args.pack, args.runtime)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())"""Independently reopen source-bound offline evidence; no authority is granted."""

# ruff: noqa: E402
import argparse
import hashlib
import json
import os
import subprocess
import sys
from pathlib import Path
from typing import Any, cast
from uuid import uuid4

ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT), str(ROOT / "src")]
from moj_discovery.canonical import parse_strict_json
from moj_discovery.diagnostic import render_diagnostic
from moj_discovery.input_journal import _read
from moj_discovery.offline_protocol import _validator
from moj_discovery.replay import verify_replay_equivalence
from tools.offline_browser import OfflineBrowser, prepare_offline_extension
from tools.offline_harness import source_hashes
from tools.offline_meta import check_meta
from tools.offline_oracle import assert_case
from tools.offline_results import gate_view


def artifact(root: Path, reference: dict[str, Any]) -> Path:
    name = reference["relative_path"]
    relative = Path(name)
    if relative.is_absolute() or ".." in relative.parts or "\\" in name:
        raise ValueError("E_OFFLINE_ARTIFACT_PATH")
    path = root / relative
    if not path.resolve().is_relative_to(root.resolve()) or any(
        p.is_symlink() for p in (path, *path.parents)
    ):
        raise ValueError("E_OFFLINE_ARTIFACT_PATH")
    data = _read(path)
    if len(data) != reference["bytes"] or hashlib.sha256(data).hexdigest() != reference["sha256"]:
        raise ValueError("E_OFFLINE_ARTIFACT_HASH")
    return path


def verify_offline_slice(result_path: Path) -> dict[str, Any]:
    if not __debug__:
        raise RuntimeError("E_OFFLINE_OPTIMIZED_EXECUTION")
    result = cast(dict[str, Any], parse_strict_json(_read(result_path)))
    _validator("result.schema.json").validate(result)
    root = result_path.absolute().parent
    provenance = result["provenance"]
    registry = json.loads((ROOT / "registries/offline-cases.json").read_text())["cases"]
    complete = [f"OFF-{index:02d}" for index in range(1, 28)]
    if [row["case_id"] for row in registry] != complete:
        raise ValueError("E_OFFLINE_CASE_INVENTORY")
    required = complete if provenance["scenario_id"] == "acceptance" else ["OFF-01"]
    if (
        result["required_case_ids"] != required
        or [r["case_id"] for r in result["records"]] != required
        or result["run_id"] != provenance["run_id"]
    ):
        raise ValueError("E_OFFLINE_CASE_INVENTORY")
    full = provenance["scenario_id"] == "acceptance"
    if result["OFFLINE_SLICE_PASS"] != ("YES" if full else "NO"):
        raise ValueError("E_OFFLINE_FORGED_PASS")
    if result["LEGACY_FULL_QUALIFICATION"] not in {"HOLD", "NOT_EVALUATED"} or result[
        "INDEPENDENT_SECURITY_REVIEW"
    ] not in {"NOT_RUN", "SELF_ONLY"}:
        raise ValueError("E_OFFLINE_UNSUPPORTED_AUTHORITY_CLAIM")
    current = source_hashes()
    tree_hash = hashlib.sha256(json.dumps(current, sort_keys=True).encode()).hexdigest()
    head = subprocess.check_output(
        ["/usr/bin/git", "rev-parse", "HEAD"], cwd=ROOT, text=True
    ).strip()
    if tree_hash != provenance["source_tree_sha256"] or head != provenance["code_revision"]:
        raise ValueError("E_OFFLINE_SOURCE_STALE")
    bindings = {
        "python_lock_sha256": "uv.lock",
        "node_lock_sha256": "pnpm-lock.yaml",
        "vendor_sha256": "vendor/hybrid-discovery-v6.3.6/SCHEMA_SHA256.json",
        "scenario_sha256": "registries/offline-cases.json",
    }
    for field, path in bindings.items():
        if hashlib.sha256((ROOT / path).read_bytes()).hexdigest() != provenance[field]:
            raise ValueError("E_OFFLINE_SOURCE_BINDING")
    browser_path = Path(os.environ.get("BH_CHROME_BINARY", "/opt/google/chrome/chrome"))
    if hashlib.sha256(browser_path.read_bytes()).hexdigest() != provenance["browser_sha256"]:
        raise ValueError("E_OFFLINE_BROWSER_BINDING")
    artifact(root, result["diagnostic"])
    expectations = {r["case_id"]: r["expected_behavior"] for r in registry}
    cases = []
    verification = root / "verification" / str(uuid4())
    prepare_offline_extension(verification / "current-modules")
    expected_modules = json.loads(_read(verification / "current-modules/module-hashes.json"))
    for record in result["records"]:
        if (
            record["status"] != "PASS"
            or record["executed"] is not True
            or record["command_exit"] != 0
            or record["expected_behavior"] != expectations[record["case_id"]]
            or not record["artifacts"]
        ):
            raise ValueError("E_OFFLINE_CASE_NOT_PASSED")
        names = [r["relative_path"] for r in record["artifacts"]]
        if len(set(names)) != len(names):
            raise ValueError("E_OFFLINE_ARTIFACT_DUPLICATE")
        for reference in record["artifacts"]:
            artifact(root, reference)
        case = record["case_id"]
        directory = root / case
        consumed = {
            str(path.relative_to(root))
            for path in directory.rglob("*")
            if path.is_file()
            and "profile" not in path.parts
            and "offline-extension" not in path.parts
        }
        if not consumed.issubset(names):
            raise ValueError("E_OFFLINE_UNBOUND_EVIDENCE")
        command_names = {f"commands/{case}{suffix}" for suffix in [".json", ".stdout", ".stderr"]}
        if not command_names.issubset(names):
            raise ValueError("E_OFFLINE_MISSING_COMMAND_EVIDENCE")
        command = json.loads(_read(root / "commands" / (case + ".json")))
        expected_command = [
            str(ROOT / "tools/run_offline_faults.py"),
            "--case",
            case,
            "--output",
            str(root),
            "--browser-binary",
            str(browser_path),
        ]
        if not 0 < command["elapsed_seconds"] <= (120 if case == "OFF-19" else 30):
            raise ValueError("E_OFFLINE_CASE_TIMEOUT")
        if (
            command["exit"] != 0
            or command["pid"] <= 0
            or command["command"][1:] != expected_command
        ):
            raise ValueError("E_OFFLINE_COMMAND_BINDING")
        finished = json.loads(_read(root / "commands" / (case + ".stdout")))
        if finished != {"case_id": case, "execution": "FINISHED"}:
            raise ValueError("E_OFFLINE_COMMAND_BINDING")
        if case in {"OFF-20", "OFF-21", "OFF-22", "OFF-25"}:
            required_meta = {
                "OFF-20": ["input.json", "diagnostic.html"],
                "OFF-21": ["config.json", "observed.json"],
                "OFF-22": ["observed.json", "tampered.bin"],
                "OFF-25": [
                    "observed.json",
                    "original-config.json",
                    "changed-config.json",
                    "changed-sources.json",
                ],
            }[case]
            if not {f"{case}/{name}" for name in required_meta}.issubset(names):
                raise ValueError("E_OFFLINE_MISSING_META_EVIDENCE")
            if case in {"OFF-20", "OFF-22", "OFF-25"} and "reference.json" not in names:
                raise ValueError("E_OFFLINE_MISSING_META_EVIDENCE")
            if case == "OFF-22" and not {
                f"negative-{case}-{kind}.json"
                for kind in ["missing", "tampered", "duplicate", "forged"]
            }.issubset(names):
                raise ValueError("E_OFFLINE_MISSING_META_EVIDENCE")
            cases.append(check_meta(case, root, verify_offline_slice))
            continue
        mandatory = [
            f"{case}/{name}"
            for name in [
                "readback.json",
                "timings.json",
                "sources.json",
                "module-hashes.json",
                "run/context.json",
                "run/run.sqlite3",
                "browser/identity.json",
                "reader/identity.json",
                "browser/termination.json",
                "reader/termination.json",
                "backend.json",
            ]
        ]
        if not set(mandatory).issubset(names):
            raise ValueError("E_OFFLINE_MISSING_READER_EVIDENCE")
        if json.loads(_read(directory / "sources.json")) != current:
            raise ValueError("E_OFFLINE_SOURCE_STALE")
        modules = json.loads(_read(directory / "module-hashes.json"))
        extension = directory / "offline-extension"
        actual_modules = {
            str(p.relative_to(extension)): hashlib.sha256(_read(p)).hexdigest()
            for p in extension.rglob("*")
            if p.is_file()
        }
        if modules != actual_modules or modules != expected_modules:
            raise ValueError("E_OFFLINE_BROWSER_MODULES")
        context = json.loads(_read(directory / "run/context.json"))
        if (
            context["code_sha256"] != tree_hash
            or context["vendor_sha256"] != provenance["vendor_sha256"]
        ):
            raise ValueError("E_OFFLINE_SOURCE_BINDING")
        writer = json.loads(_read(directory / "browser/identity.json"))
        reader = json.loads(_read(directory / "reader/identity.json"))
        if (
            writer["pid"] == reader["pid"]
            or writer["document"]["origin"] != provenance["extension_origin"]
            or reader["document"]["origin"] != context["allowed_extension_origin"]
            or reader["binary_sha256"] != provenance["browser_sha256"]
            or writer["binary_sha256"] != provenance["browser_sha256"]
            or writer["version"]["product"] != provenance["browser_version"]
            or reader["version"]["product"] != provenance["browser_version"]
        ):
            raise ValueError("E_OFFLINE_BROWSER_IDENTITY")
        for name in ["browser", "reader"]:
            termination = json.loads(_read(directory / name / "termination.json"))
            if (
                termination["method"] != "SIGKILL_PROCESS_GROUP"
                or termination["returncode"] != -9
                or termination["graceful"]
            ):
                raise ValueError("E_OFFLINE_CRASH_EVIDENCE")
        probe = OfflineBrowser(
            root / "verification" / str(uuid4()) / case,
            extension,
            context["allowed_extension_origin"],
            browser_path,
            profile=directory / "browser/profile",
        )
        try:
            reopened = probe.command({"operation": "INIT", "context": context, "credentials": []})
        finally:
            probe.close()
        if reopened.get("status") != "OK":
            raise ValueError("E_OFFLINE_STORAGE_CHANGED")
        previous = json.loads(_read(directory / "readback.json"))["reader"]
        if reopened["state"] != previous["state"] or reopened["retained"] != previous["retained"]:
            raise ValueError("E_OFFLINE_STORAGE_CHANGED")
        replay_target = verification / case / "replay"
        if case == "OFF-16":
            try:
                verify_replay_equivalence(directory / "run", replay_target)
            except (ValueError, OSError):
                pass
            else:
                raise ValueError("E_OFFLINE_MISSING_RAW_ACCEPTED")
        else:
            verify_replay_equivalence(directory / "run", replay_target)
        cases.append(assert_case(case, directory / "run"))
    full = provenance["scenario_id"] == "acceptance"
    if result["OFFLINE_SLICE_PASS"] != ("YES" if full else "NO"):
        raise ValueError("E_OFFLINE_FORGED_PASS")
    if source_hashes() != current:
        raise ValueError("E_OFFLINE_SOURCE_STALE")
    verified = gate_view(result, cases)
    if (root / result["diagnostic"]["relative_path"]).read_text() != render_diagnostic(verified):
        raise ValueError("E_OFFLINE_DIAGNOSTIC_BINDING")
    return verified


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input", type=Path, required=True)
    args = parser.parse_args()
    try:
        result = verify_offline_slice(args.input)
    except Exception:
        print("E_OFFLINE_GATE_REJECTED", file=sys.stderr)
        return 1
    print(json.dumps(result, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())"""Run finite source-bound Part B checks and retain actual process/test observations."""

# ruff: noqa: E402
import argparse
import hashlib
import importlib
import json
