    "test_local_bridge.py",
]
PART_B_PYTHON = [
    *sorted(
        str(p.relative_to(ROOT))
        for p in (ROOT / "src/moj_discovery").glob("live_*.py")
        if p.name != "live_preflight.py"
    ),
